/// Reads direct children from the active descriptor stream using engine-owned identity.
pub fn streamDirectChildren(allocator: std.mem.Allocator, stream: *const HostNodeDescriptorStream, parent_elem_id: u64) []u64 {
    return @ptrCast(descriptor_stream.streamDirectChildren(HostNodeDescriptorStream, allocator, stream, ids.ElemId.fromRaw(parent_elem_id)));
}

/// Reads direct children into from the active descriptor stream using engine-owned identity.
pub fn streamDirectChildrenInto(allocator: std.mem.Allocator, stream: *const HostNodeDescriptorStream, parent_elem_id: u64, children: *shared_buffer.List(u64)) []const u64 {
    const nominal_children: *shared_buffer.List(ids.ElemId) = @ptrCast(children);
    return ids.elemSliceRaw(descriptor_stream.streamDirectChildrenInto(HostNodeDescriptorStream, allocator, stream, ids.ElemId.fromRaw(parent_elem_id), nominal_children));
}

/// Returns scope id for an already indexed render node.
pub fn renderNodeScopeId(stream: *const HostNodeDescriptorStream, node: HostRenderNode) u64 {
    return descriptor_stream.renderNodeScopeId(HostNodeDescriptorStream, stream, node).raw();
}

/// Performs elem scope id inside the shared engine while preserving transaction and changed-set invariants.
pub fn elemScopeId(stream: *const HostNodeDescriptorStream, elem_id: u64) ?u64 {
    const scope_id = descriptor_stream.elemScopeId(HostNodeDescriptorStream, stream, ids.ElemId.fromRaw(elem_id)) orelse return null;
    return scope_id.raw();
}

fn textFieldDescriptorIndexesActive(indexes: HostTextFieldDescriptorIndexes) bool {
    // Browser-scoped scalars only, matching the previous hand-written list:
    // native metadata publishes through the typed native publication.
    inline for (comptime std.meta.tags(render.TextField)) |field| {
        if (comptime !field.isNative()) {
            if (@field(indexes.indexes, @tagName(field)) != .none) return true;
        }
    }
    return false;
}

fn boolFieldDescriptorIndexesActive(indexes: HostBoolFieldDescriptorIndexes) bool {
    // Browser-scoped scalars only, matching the previous hand-written list.
    inline for (comptime std.meta.tags(render.BoolField)) |field| {
        if (comptime !field.isNative()) {
            if (@field(indexes.indexes, @tagName(field)) != .none) return true;
        }
    }
    return false;
}

fn eventDescriptorIndexesActive(indexes: HostEventDescriptorIndexes) bool {
    inline for (comptime std.meta.tags(render.EventKind)) |kind| {
        if (@field(indexes.indexes, @tagName(kind)) != .none) return true;
    }
    return false;
}

fn elemDescriptorIndexActive(index: HostElemDescriptorIndex) bool {
    return index.element != .none or
        index.text_node != .none or
        index.signal_text_node != .none or
        textFieldDescriptorIndexesActive(index.static_text_attrs) or
        textFieldDescriptorIndexesActive(index.signal_text_attrs) or
        boolFieldDescriptorIndexesActive(index.static_bool_attrs) or
        boolFieldDescriptorIndexesActive(index.signal_bool_attrs) or
        eventDescriptorIndexesActive(index.events);
}

/// Performs adjusted render insert index inside the shared engine while preserving transaction and changed-set invariants.
pub fn adjustedRenderInsertIndex(old_index: usize, replace_index: usize, removed_count: usize, replacement_count: usize) usize {
    return descriptor_stream.adjustedRenderInsertIndex(old_index, replace_index, removed_count, replacement_count);
}

fn sourceNodeIdsIntersect(left: []const u64, right: []const u64) bool {
    for (left) |left_id| {
        for (right) |right_id| {
            if (left_id == right_id) return true;
        }
    }
    return false;
}

// Host-agnostic signal-record construction helpers (shared by both hosts).

/// Delivers node binder ref through the same source-update and propagation path as other inputs.
pub fn resolveNodeBinderRef(binder_stack: []const HostBinderBinding, token: HostBinderToken) u64 {
    var index = binder_stack.len;
    while (index > 0) {
        index -= 1;
        const binding = binder_stack[index];
        if (binding.token == token) return binding.node_id.raw();
    }
    @panic("Node.BinderRef referenced a state binder outside the active scope");
}

/// Performs render text field from abi inside the shared engine while preserving transaction and changed-set invariants.
pub fn renderTextFieldFromAbi(field: u64) RenderTextField {
    return abi_view.textFieldFromAbi(field);
}

/// Performs render bool field from abi inside the shared engine while preserving transaction and changed-set invariants.
pub fn renderBoolFieldFromAbi(field: u64) RenderBoolField {
    return abi_view.boolFieldFromAbi(field);
}

/// Performs render event kind from abi inside the shared engine while preserving transaction and changed-set invariants.
pub fn renderEventKindFromAbi(kind: u64) RenderEventKind {
    return abi_view.eventKindFromAbi(kind);
}

/// Performs engine inside the shared engine while preserving transaction and changed-set invariants.
pub fn Engine(comptime Ctx: type) type {
    verifyCtx(Ctx);

    return struct {
        const Self = @This();

        pub const Context = Ctx;
        pub const Metrics = Ctx.Metrics;
        pub const RegistryOps = Ctx.RegistryOps;
        pub const HostValueRegistry = host_value_registry.Registry(HostValueCapability);
        pub const ActiveEventDesc = HostActiveEventDesc;
        pub const IdentityInternError = scope_tree.Error || identity_table.Error;
        pub const EventLookupError = active_graph.EventLookupError;
        pub const SignalLookupError = active_graph.SignalLookupError;
        pub const ActiveEventLookupError = error{
            MissingActiveEvent,
        };
        pub const StateLookupError = error{
            MissingActiveState,
        };
        pub const RocHostRequiredError = error{
            MissingRocHost,
        };

        host_values: HostValueRegistry = .{},
        active_events: shared_buffer.List(ActiveEventDesc) = .empty,
        event_descriptors: shared_buffer.List(HostEventDescriptor) = .empty,
        signal_event_routes: shared_buffer.List(HostSignalEventRoute) = .empty,
        signal_descriptors: shared_buffer.List(HostSignalDescriptor) = .empty,
        signal_routes: shared_buffer.List(HostSignalRoute) = .empty,
        signal_dependents: shared_buffer.List(HostSignalDependentsRoute) = .empty,
        signal_cache: shared_buffer.List(HostSignalCacheSlot) = .empty,
        states: shared_buffer.List(HostState) = .empty,
        state_indexes_by_node_id: shared_buffer.List(?usize) = .empty,
        scopes: shared_buffer.List(HostScope) = .empty,
        each_row_site_indexes: HostEachRowSiteIndexMap = .empty,
        each_row_sites: shared_buffer.List(HostEachRowSite) = .empty,
        each_row_memberships_by_scope_id: shared_buffer.List(?HostEachRowMembership) = .empty,
        rows_store: ?rows_site_store.Store = null,
        rows_site_ids: std.HashMapUnmanaged(each_runtime.SiteKey, rows_site_store.SiteId, each_runtime.SiteKeyContext, std.hash_map.default_max_load_percentage) = .empty,
        each_generation_ids_by_rows_site: std.AutoHashMapUnmanaged(rows_site_store.SiteId, each_generation.GenerationId) = .empty,
        reserved_rows_generation_entries: usize = 0,
        row_handle_registry: row_handles.Registry(void) = .init(),
        committed_row_bindings: each_generation.BindingTable = .{},
        each_generation_clock: each_generation.GenerationClock = .{},
        each_generations: std.AutoHashMapUnmanaged(each_generation.GenerationId, *each_generation.Generation) = .{},
        each_generation_ids_by_site_index: shared_buffer.List(?each_generation.GenerationId) = .empty,
        active_each_candidate_bindings: ?*const each_generation.CandidateBindings = null,
        active_each_candidate_inputs: ?*const PreparedEachInputs = null,
        active_each_candidate_generation: ?*each_generation.Generation = null,
        active_each_candidate_rows_site_id: ?rows_site_store.SiteId = null,
        active_each_prepared_bindings: ?*const std.AutoHashMapUnmanaged(row_handles.RowHandleId, each_generation.RowBinding) = null,
        active_each_prepared_generations: ?*const std.AutoHashMapUnmanaged(each_generation.GenerationId, *each_generation.Generation) = null,
        node_identities: shared_buffer.List(HostNodeIdentity) = .empty,
        dom_identities: shared_buffer.List(HostDomIdentity) = .empty,
        active_node_identity_ids: std.AutoHashMapUnmanaged(u128, u64) = .empty,
        active_dom_identity_ids: std.AutoHashMapUnmanaged(u128, u64) = .empty,
        has_inactive_scopes: bool = false,
        has_inactive_node_identities: bool = false,
        has_inactive_dom_identities: bool = false,
        // Identity ids retired during the current dirty generation must not be
        // reused until the next one; see identity_table.internNode.
        identity_reuse_barrier: u64 = 0,
        active_stream: HostNodeDescriptorStream = .{},
        active_signal_graph: shared_buffer.List(HostActiveSignalGraphNode) = .empty,
        active_source_signal_routes: active_graph.RouteTable(u64) = .empty,
        active_text_signal_routes: active_graph.RouteTable(HostActiveTextSignalSink) = .empty,
        active_bool_signal_routes: active_graph.RouteTable(HostActiveBoolSignalSink) = .empty,
        active_change_signal_routes: active_graph.RouteTable(HostActiveChangeSignalSink) = .empty,
        active_structural_signal_routes: active_graph.RouteTable(HostActiveStructuralSignal) = .empty,
        active_row_sources: std.AutoHashMapUnmanaged(row_handles.RowHandleId, *HostSignalRecord) = .{},
        selectors: selector_runtime.Registry(HostSignalRecord) = .{},
        render_cache: render_cache_mod.Cache(Ctx) = .{},
        positions: ?structural_positions.Positions = null,
        /// Effects accepted by committed `Then` commands, in start order, until
        /// the host runs them once the turn has settled.
        pending_effects: shared_buffer.List(PendingEffect) = .empty,
        running_effects: shared_buffer.List(RunningEffect) = .empty,
        next_effect_id: u64 = 1,
        /// The declared reads of whatever handler, sink, or effect is having its
        /// command applied right now; a `Then` snapshots them for its effect.
        effect_origin: ?*HostSignalBinding = null,
        /// Set while an effect's result command runs, so its changes to states
        /// that were retired while the effect ran are skipped instead of
        /// treated as a malformed command.
        applying_effect_result: bool = false,
        active_intervals: effects_runtime.IntervalRegistry = .empty,
        cleanup_events: HostCleanupEvents = .empty,
        next_interval_token: u64 = 1,
        next_elem_id: u64 = 0,
        roc_host: ?*abi.RocHost = null,
        root_elem: ?abi.Elem = null,
        last_runtime_metrics: Metrics = Ctx.zeroMetrics(),
        pending_roc_metrics: Metrics = Ctx.zeroMetrics(),
        // Render-command accumulator (patches/create/append/remove/...) folded into
        // last_runtime_metrics at finish. Engine-owned so both hosts share it.
        render_metrics: render.Metrics = .{},
        // Dispatch counters (events processed / recompute batches) folded into
        // last_runtime_metrics at finish. Engine-owned so both hosts share it.
        dispatch_metrics: DispatchMetrics = .{},
        dirty_signal_generation: u64 = 0,
        active_each_sinks: each_collection.ActiveSinks = .{},
        scratch: EngineScratch = .{},

        const ActiveSignalGraphLifecycle = struct {
            engine: *Self,
            ctx: Ctx.Handle,

            /// Ensures interval capacity or state before publication can begin.
            pub fn ensureInterval(self: *@This(), source_token: HostSignalToken, period_ms: u64) void {
                self.engine.ensureActiveInterval(self.ctx, source_token, period_ms);
            }

            /// Registers an interval appended by a prepared transaction using
            /// registry capacity the transaction reserved during preparation.
            pub fn registerInterval(self: *@This(), source_token: HostSignalToken, period_ms: u64) void {
                self.engine.registerActiveIntervalAssumeCapacity(self.ctx, source_token, period_ms);
            }

            /// Removes interval and releases the ownership attached to that live entry.
            pub fn removeInterval(self: *@This(), source_token: HostSignalToken) void {
                self.engine.removeActiveIntervalBySourceToken(self.ctx, source_token);
            }

            /// Adds one live selector member to the shared keyed index.
            pub fn ensureSelector(self: *@This(), input: *HostSignalRecord, key: []const u8, member: *HostSignalRecord) void {
                self.engine.selectors.register(Ctx.allocator(self.ctx), input, key, member) catch @panic("out of memory");
            }

            /// Registers a selector member after prepared graph publication.
            pub fn registerSelector(self: *@This(), input: *HostSignalRecord, key: []const u8, member: *HostSignalRecord) void {
                _ = self;
                _ = input;
                _ = key;
                _ = member;
            }

            /// Adds one live row source to the stable handle index.
            pub fn ensureRowSource(self: *@This(), record: *HostSignalRecord) void {
                const row = switch (record.payload) {
                    .row_source => |payload| payload,
                    else => @panic("row source index received a non-row record"),
                };
                const entry = self.engine.active_row_sources.getOrPut(Ctx.allocator(self.ctx), row.row_handle) catch @panic("out of memory");
                if (entry.found_existing and entry.value_ptr.* != record) @panic("row handle resolved to multiple active source records");
                entry.value_ptr.* = record;
            }

            /// Publishes a pre-reserved row-source entry without allocation.
            pub fn registerRowSource(self: *@This(), record: *HostSignalRecord) void {
                const row = switch (record.payload) {
                    .row_source => |payload| payload,
                    else => @panic("row source index received a non-row record"),
                };
                const entry = self.engine.active_row_sources.getOrPutAssumeCapacity(row.row_handle);
                if (entry.found_existing and entry.value_ptr.* != record) @panic("row handle resolved to multiple active source records");
                entry.value_ptr.* = record;
            }

            /// Performs release record inside the shared engine while preserving transaction and changed-set invariants.
            pub fn releaseRecord(self: *@This(), record: *HostSignalRecord) void {
                switch (record.payload) {
                    .select, .keyed_select => |payload| {
                        self.engine.selectors.unregister(Ctx.allocator(self.ctx), payload.input, payload.key, record);
                        self.engine.pending_roc_metrics.bump(.selector_registry_visits, 1);
                        self.engine.pending_roc_metrics.bump(.selector_memberships_released, 1);
                    },
                    .row_source => |payload| {
                        const removed = self.engine.active_row_sources.fetchRemove(payload.row_handle) orelse @panic("retired row source was absent from its handle index");
                        if (removed.value != record) @panic("retired row source index pointed at a different record");
                    },
                    else => {},
                }
                record.release(Ctx.allocator(self.ctx), self.ctx, self.engine.roc_host.?, &self.engine.pending_roc_metrics);
            }
        };

        const EachRowScopeKeyLookup = struct {
            engine: *Self,
            /// Live nested sites the committing collection reconciles; their
            /// identities are republished only after the journal runs, so an
            /// emptied one stays for the reconciliation to refill.
            reconciled_sites: []const PreparedNestedRowSync = &.{},

            /// Performs row key hash through the keyed-row capabilities that own key and item values.
            pub fn rowKeyHash(self: *@This(), scope_id: ids.ScopeId) u64 {
                return self.engine.eachRowScopeKeyHash(scope_id.raw());
            }

            /// Keeps an empty keyed-row site while its descriptor remains live,
            /// allowing a later update to repopulate it without inventing a
            /// second lifecycle path.
            pub fn siteRemainsActive(self: *@This(), key: each_runtime.SiteKey) bool {
                for (self.reconciled_sites) |*sync| if (sync.parent_scope_id == key.parent_scope_id and sync.site_ordinal == key.site_ordinal) return true;
                const node_id = self.engine.active_node_identity_ids.get(identityKey(key.parent_scope_id.raw(), key.site_ordinal.raw())) orelse return false;
                const site = self.engine.activeScopeSiteByNodeId(node_id, .each) orelse return false;
                return site.scope_id == key.parent_scope_id and site.ordinal == key.site_ordinal and self.engine.activeEachIndexByNodeId(node_id) != null;
            }
        };

        const EachRowSync = struct {
            engine: *Self,
            ctx: Ctx.Handle,
            roc_host: *abi.RocHost,
            inputs: *PreparedEachInputs,

            /// Records each sync in the metrics or lifecycle state owned by this operation.
            pub fn recordEachSync(self: *@This(), next_len: usize, existing_len: usize) void {
                self.engine.recordEachSync(next_len, existing_len);
            }

            /// Reports whether h key is present in maintained state.
            /// Hashes an incoming key through the each descriptor capability.
            pub fn hashKey(self: *@This(), key: usize) u64 {
                self.engine.recordEachKeyHash();
                if (key >= self.inputs.snapshot.keys.hashes.items.len) @panic("each key index exceeded candidate generation");
                return self.inputs.snapshot.keys.hashes.items[key];
            }

            /// Compares candidate row keys exactly after hash lookup, preserving collision correctness.
            /// Compares two incoming keys before persistent publication.
            pub fn nextKeysEqual(self: *@This(), left: usize, right: usize) bool {
                self.engine.recordEachKeyDuplicateCompare();
                return std.mem.eql(u8, self.inputs.key(left) orelse @panic("missing candidate key"), self.inputs.key(right) orelse @panic("missing candidate key"));
            }

            /// Performs existing key equals inside the shared engine while preserving transaction and changed-set invariants.
            /// Compares an incoming key with one persistent row key.
            pub fn existingKeyEquals(self: *@This(), scope_id: ids.ScopeId, key: usize) bool {
                self.engine.recordEachKeyReuseCompare();
                const handle = scope_runtime.eachRowHandle(self.engine.scopes.items, scope_id);
                const binding = self.engine.resolveEachRowBinding(handle) orelse @panic("each row had no committed generation binding");
                _ = self.engine.eachGenerationForBinding(binding) orelse @panic("each row generation was not retained");
                const location = self.engine.rows_store.?.findScope(scope_id.raw()) orelse @panic("committed each scope was absent from Rows store");
                const committed = self.engine.rows_store.?.getRowConst(location.site_id, location.row_id) catch @panic("committed each row became stale");
                return std.mem.eql(u8, committed.key, self.inputs.key(key) orelse @panic("candidate each key index exceeded generation"));
            }

            /// Performs row item equals through the keyed-row capabilities that own key and item values.
            /// Compares an incoming item with one persistent row item.
            pub fn rowItemEquals(self: *@This(), _: ids.ScopeId, item: usize) bool {
                self.engine.recordEachItemCompare();
                return self.inputs.item_equal[item];
            }

            /// Replaces row key while releasing displaced ownership exactly once.
            pub fn replaceRowKey(self: *@This(), scope_id: ids.ScopeId, key_hash: u64, _: usize) void {
                scope_runtime.eachRow(self.engine.scopes.items, scope_id).key_hash = key_hash;
            }

            /// Replaces row item while releasing displaced ownership exactly once.
            pub fn replaceRowItem(_: *@This(), _: ids.ScopeId, _: usize) void {}

            /// Performs drop incoming key inside the shared engine while preserving transaction and changed-set invariants.
            pub fn dropIncomingKey(_: *@This(), _: usize) void {}

            /// Performs drop incoming item inside the shared engine while preserving transaction and changed-set invariants.
            pub fn dropIncomingItem(_: *@This(), _: usize) void {}

            /// Performs create row inside the shared engine while preserving transaction and changed-set invariants.
            pub fn createRow(self: *@This(), parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal, key_hash: u64, _: usize, item: usize) ids.ScopeId {
                const handle = self.engine.row_handle_registry.insert(Ctx.allocator(self.ctx), {}) catch @panic("row handle resource limit");
                self.inputs.created_handles.append(Ctx.allocator(self.ctx), handle) catch @panic("out of memory");
                self.inputs.candidate_bindings.putAssumeCapacity(handle, .{ .generation_id = self.inputs.generation.id, .item_slot = self.inputs.slot(item) orelse @panic("missing candidate Rows slot") }, .{ .snapshot = item }) catch @panic("invalid duplicate row binding");
                return self.engine.createEachRowScope(self.ctx, parent_scope_id, site_ordinal, key_hash, handle);
            }

            /// Performs dispose scope inside the shared engine while preserving transaction and changed-set invariants.
            pub fn disposeScope(self: *@This(), scope_id: ids.ScopeId) void {
                self.engine.disposeScopeSubtree(self.ctx, self.roc_host, scope_id.raw());
            }

            /// Performs row key hash through the keyed-row capabilities that own key and item values.
            pub fn rowKeyHash(self: *@This(), scope_id: ids.ScopeId) u64 {
                return self.engine.eachRowScopeKeyHash(scope_id.raw());
            }

            /// Records rows in the metrics or lifecycle state owned by this operation.
            pub fn recordRows(self: *@This(), rows_reused: u64, rows_created: u64, rows_removed: u64) void {
                var metrics = self.engine.pending_roc_metrics;
                metrics.bump(.rows_reused, rows_reused);
                metrics.bump(.rows_created, rows_created);
                metrics.bump(.rows_removed, rows_removed);
                self.engine.pending_roc_metrics = metrics;
            }

            /// Rejects a duplicate keyed row at the narrow reconciliation boundary with a bounded diagnostic.
            pub fn failDuplicateEachKey(self: *@This(), parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal, first_index: usize, second_index: usize, key: usize) noreturn {
                var buf: [512]u8 = undefined;
                const msg = formatEachDuplicateKeyDiagnostic(&buf, parent_scope_id.raw(), site_ordinal.raw(), first_index, second_index, self.inputs.key(key) orelse "<invalid key>");
                if (comptime @hasDecl(Ctx, "failWithMessage")) Ctx.failWithMessage(self.ctx, msg);
                @panic(msg);
            }
        };

        const PreparedEachRowSyncHooks = struct {
            base: EachRowSync,
            scopes: *scope_runtime.PreparedScopeClaims,
            inputs: ?*PreparedEachInputs = null,

            fn initWithScopeClaims(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, scopes: *scope_runtime.PreparedScopeClaims) @This() {
                return .{
                    .base = .{ .engine = engine, .ctx = ctx, .roc_host = roc_host, .inputs = undefined },
                    .scopes = scopes,
                };
            }

            /// Hashes an incoming key through the each descriptor capability.
            pub fn hashKey(self: *@This(), key: usize) u64 {
                return self.base.hashKey(key);
            }

            /// Compares two incoming keys before persistent publication.
            pub fn nextKeysEqual(self: *@This(), left: usize, right: usize) bool {
                return self.base.nextKeysEqual(left, right);
            }

            /// Compares an incoming key with one persistent row key.
            pub fn existingKeyEquals(self: *@This(), scope_id: ids.ScopeId, key: usize) bool {
                return self.base.existingKeyEquals(scope_id, key);
            }

            /// Compares an incoming item with one persistent row item.
            pub fn rowItemEquals(self: *@This(), scope_id: ids.ScopeId, item: usize) bool {
                return self.base.rowItemEquals(scope_id, item);
            }

            /// Retains a new row in the plan-local scope overlay.
            pub fn prepareCreatedRow(self: *@This(), allocator: std.mem.Allocator, parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal, input_index: usize, key_hash: u64, _: usize, _: usize) (std.mem.Allocator.Error || error{ResourceLimit})!ids.ScopeId {
                _ = allocator;
                const inputs = self.inputs orelse @panic("prepared each hooks had no generation inputs");
                const row_handle = try self.base.engine.row_handle_registry.insert(Ctx.allocator(self.base.ctx), {});
                inputs.created_handles.append(Ctx.allocator(self.base.ctx), row_handle) catch {
                    _ = self.base.engine.row_handle_registry.remove(row_handle) catch unreachable;
                    return error.OutOfMemory;
                };
                inputs.candidate_bindings.putAssumeCapacity(row_handle, .{ .generation_id = inputs.generation.id, .item_slot = inputs.slot(input_index) orelse @panic("missing candidate Rows slot") }, .{ .snapshot = input_index }) catch @panic("invalid duplicate row binding");
                inputs.row_handles_by_index[input_index] = row_handle;
                const scope_id = try self.scopes.prepareRow(
                    &self.base.engine.scopes,
                    parent_scope_id,
                    site_ordinal,
                    key_hash,
                    row_handle,
                );
                inputs.transferEntry(input_index);
                return scope_id;
            }

            /// Batches equality for every reused row into one app-compiled
            /// collection call and stages its candidate generation binding.
            pub fn prepareItemComparisons(self: *@This(), allocator: std.mem.Allocator, scope_ids: []const ids.ScopeId, created: []const bool) (std.mem.Allocator.Error || error{ResourceLimit})!void {
                const inputs = self.inputs orelse @panic("prepared each hooks had no generation inputs");
                var pairs: shared_buffer.List(u64) = .empty;
                defer pairs.deinit(allocator);
                var reused_count: usize = 0;
                for (created) |was_created| if (!was_created) {
                    reused_count += 1;
                };
                try pairs.ensureTotalCapacity(allocator, std.math.mul(usize, reused_count, 2) catch return error.ResourceLimit);
                var old_generation: ?*each_generation.Generation = null;
                for (scope_ids, created, 0..) |scope_id, was_created, next_index| {
                    if (was_created) continue;
                    const row_handle = scope_runtime.eachRowHandle(self.base.engine.scopes.items, scope_id);
                    const binding = self.base.engine.resolveEachRowBinding(row_handle) orelse return error.ResourceLimit;
                    const generation = self.base.engine.eachGenerationForBinding(binding) orelse return error.ResourceLimit;
                    if (old_generation) |existing| {
                        if (existing != generation) return error.ResourceLimit;
                    } else old_generation = generation;
                    pairs.appendAssumeCapacity(binding.item_slot);
                    pairs.appendAssumeCapacity(inputs.slot(next_index) orelse return error.ResourceLimit);
                    inputs.candidate_bindings.putAssumeCapacity(row_handle, .{ .generation_id = inputs.generation.id, .item_slot = inputs.slot(next_index) orelse return error.ResourceLimit }, .{ .snapshot = next_index }) catch return error.ResourceLimit;
                    inputs.row_handles_by_index[next_index] = row_handle;
                }
                const old = old_generation orelse return;
                const result_count = pairs.items.len / 2;
                var results: each_collection.BoolStorage = .{};
                defer results.deinit(allocator);
                var sink = results.prepare(allocator, result_count) catch return error.OutOfMemory;
                const token = self.base.engine.active_each_sinks.activateBool(&sink) catch return error.ResourceLimit;
                errdefer self.base.engine.active_each_sinks.abort(token) catch {};
                const pair_list = retained_values.U64List.fromSlice(pairs.items, self.base.roc_host);
                defer pair_list.decref(self.base.roc_host);
                const returned = retained_values.callRowsCompareSlots(
                    Ctx,
                    self.base.ctx,
                    self.base.roc_host,
                    old.ops.rows_capability,
                    inputs.generation.ops.rows_capability,
                    inputs.generation.ops.compare_slots,
                    old.collection.value,
                    inputs.generation.collection.value,
                    pair_list,
                    @intFromEnum(token),
                );
                if (returned != @intFromEnum(token)) return error.ResourceLimit;
                self.base.engine.active_each_sinks.finishBool(token) catch return error.ResourceLimit;
                var result_index: usize = 0;
                for (created, 0..) |was_created, next_index| {
                    if (was_created) continue;
                    inputs.item_equal[next_index] = results.values.items[result_index];
                    result_index += 1;
                }
            }

            /// Reserves engine retirement journals; populated by the enclosing transaction.
            pub fn prepareExistingRowsCommit(_: *@This(), _: std.mem.Allocator, _: usize) std.mem.Allocator.Error!void {}

            /// Validates that reconciliation references a prepared scope identity.
            pub fn commitCreatedRow(self: *@This(), scope_id: ids.ScopeId) void {
                if (scope_id.index() >= self.base.engine.scopes.items.len or !self.base.engine.scopes.items[scope_id.index()].lifecycle.isActive()) @panic("unknown committed each-row scope");
                switch (self.base.engine.scopes.items[scope_id.index()].step) {
                    .each_row => {},
                    else => @panic("prepared each row claimed a non-row scope"),
                }
            }

            /// Publishes all provisional scope records without allocation.
            pub fn finishPreparedRowsCommit(self: *@This()) void {
                _ = self;
            }

            /// Drops every provisional row cell while persistent scopes remain unchanged.
            pub fn abortPreparedRows(self: *@This()) void {
                _ = self;
            }

            /// Replaces a surviving row key at the allocation-free commit boundary.
            pub fn replaceRowKey(self: *@This(), scope_id: ids.ScopeId, key_hash: u64, key: usize) void {
                self.base.replaceRowKey(scope_id, key_hash, key);
            }

            /// Replaces a surviving row item at the allocation-free commit boundary.
            pub fn replaceRowItem(self: *@This(), scope_id: ids.ScopeId, item: usize) void {
                self.base.replaceRowItem(scope_id, item);
            }

            /// Releases an unchanged incoming key after publication succeeds.
            pub fn dropIncomingKey(self: *@This(), key: usize) void {
                self.base.dropIncomingKey(key);
            }

            /// Releases an unchanged incoming item after publication succeeds.
            pub fn dropIncomingItem(self: *@This(), item: usize) void {
                self.base.dropIncomingItem(item);
            }

            /// Retires an obsolete row scope after all preparation succeeds.
            pub fn disposeScope(_: *@This(), _: ids.ScopeId) void {
                // The enclosing prepared subtree-retirement journal owns this
                // removal. Reconciliation publishes only the final site index.
            }

            /// Reads a committed row hash while rebuilding the site index.
            pub fn rowKeyHash(self: *@This(), scope_id: ids.ScopeId) u64 {
                return self.base.rowKeyHash(scope_id);
            }

            /// Reports duplicate incoming keys through the bounded host diagnostic.
            pub fn failDuplicateEachKey(self: *@This(), parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal, first_index: usize, second_index: usize, key: usize) noreturn {
                self.base.failDuplicateEachKey(parent_scope_id, site_ordinal, first_index, second_index, key);
            }

            fn deinit(self: *@This()) void {
                self.* = undefined;
            }
        };

        const PreparedEachGeneration = struct {
            generation: *each_generation.Generation,
            description: each_collection.Description,
            snapshot: each_collection.SnapshotStorage,
            delta: ?each_collection.DeltaStorage,

            fn deinit(self: *@This(), allocator: std.mem.Allocator, ctx: Ctx.Handle, roc_host: *abi.RocHost, metrics: anytype) void {
                self.generation.deinit(allocator, ctx, roc_host, metrics);
                allocator.destroy(self.generation);
                self.snapshot.deinit(allocator);
                if (self.delta) |*delta| delta.deinit(allocator);
                self.* = undefined;
            }
        };

        pub const PreparedEachInputs = struct {
            allocator: std.mem.Allocator,
            engine: *Self,
            ctx: Ctx.Handle,
            roc_host: *abi.RocHost,
            generation: *each_generation.Generation,
            description: each_collection.Description,
            snapshot: each_collection.SnapshotStorage,
            delta: ?each_collection.DeltaStorage,
            keys: []usize = &.{},
            items: []usize = &.{},
            item_equal: []bool = &.{},
            // Snapshot reconciliation fills this at the same candidate index
            // for both reused and created rows. Consumers must preserve that
            // alignment instead of searching provisional or committed scopes.
            row_handles_by_index: []?row_handles.RowHandleId = &.{},
            candidate_bindings: each_generation.CandidateBindings,
            created_handles: shared_buffer.List(row_handles.RowHandleId) = .empty,
            rows_site_id: ?rows_site_store.SiteId = null,
            rows_site_key: ?each_runtime.SiteKey = null,
            rows_transition: ?rows_transition.PreparedTransition = null,
            rows_site_published: bool = false,
            rows_generation_entry_reserved: bool = false,
            transferred: bool = false,

            fn key(self: *const @This(), index: usize) ?[]const u8 {
                return self.snapshot.keys.key(index);
            }

            fn candidateKey(self: *const @This(), locator: each_generation.CandidateKeyLocator) ?[]const u8 {
                return switch (locator) {
                    .snapshot => |index| self.snapshot.keys.key(index),
                    .delta => |index| if (self.delta) |*delta| delta.keys.key(index) else null,
                };
            }

            fn slot(self: *const @This(), index: usize) ?u64 {
                if (!self.snapshot.complete or index >= self.snapshot.rows.items.len) return null;
                return self.snapshot.rows.items[index].slot;
            }

            /// Extracts and retains keyed-row inputs while all compiler-owned capabilities are active.
            pub fn prepare(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, each: HostNodeEachDesc) CollectionError!@This() {
                return prepareWithAllocator(engine, ctx, roc_host, each, Ctx.allocator(ctx));
            }

            /// Test seam that faults host-side extraction storage without injecting into Roc callbacks.
            pub fn prepareWithAllocator(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, each: HostNodeEachDesc, allocator: std.mem.Allocator) CollectionError!@This() {
                return prepareWithOverlay(engine, ctx, roc_host, &each, allocator, null, &.{}, null);
            }

            /// Extracts keyed-row inputs for an each staged in the same
            /// transaction as the state cells its items signal may read.
            /// `provisional_states` are the staged collection's not-yet-published
            /// cells: an items signal that is a `ref` to one of them has no entry
            /// in the committed state table yet, so its capability must come
            /// from the provisional cell.
            pub fn prepareWithProvisionalStates(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, each: *const HostNodeEachDesc, allocator: std.mem.Allocator, provisional_states: []const HostState) CollectionError!@This() {
                return prepareWithOverlay(engine, ctx, roc_host, each, allocator, null, provisional_states, null);
            }

            fn prepareWithOverlay(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, each: *const HostNodeEachDesc, allocator: std.mem.Allocator, overlay: ?*const signal_records.PreparedCacheUpdates, provisional_states: []const HostState, expected_rows_parent: ?u64) CollectionError!@This() {
                var prepared_generation = try engine.prepareEachGeneration(ctx, roc_host, each, overlay, provisional_states, expected_rows_parent, allocator);
                errdefer prepared_generation.deinit(allocator, ctx, roc_host, &engine.pending_roc_metrics);
                const generation = prepared_generation.generation;
                const is_sparse_delta = prepared_generation.delta != null and !prepared_generation.snapshot.complete;
                const scratch_count: usize = if (is_sparse_delta) 0 else generation.item_count;
                const indices = allocator.alloc(usize, scratch_count) catch return error.OutOfMemory;
                errdefer allocator.free(indices);
                for (indices, 0..) |*index, value| index.* = value;
                const item_equal = allocator.alloc(bool, scratch_count) catch return error.OutOfMemory;
                errdefer allocator.free(item_equal);
                @memset(item_equal, false);
                const row_handles_by_index = allocator.alloc(?row_handles.RowHandleId, scratch_count) catch return error.OutOfMemory;
                errdefer allocator.free(row_handles_by_index);
                @memset(row_handles_by_index, null);
                var candidate_bindings = each_generation.CandidateBindings.init(allocator);
                errdefer candidate_bindings.deinit();
                const binding_reserve = if (prepared_generation.delta) |delta| delta.ops.items.len else generation.item_count;
                candidate_bindings.reserve(binding_reserve) catch |err| return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    error.ResourceLimit => error.ResourceLimit,
                };
                return .{
                    .allocator = allocator,
                    .engine = engine,
                    .ctx = ctx,
                    .roc_host = roc_host,
                    .generation = generation,
                    .description = prepared_generation.description,
                    .snapshot = prepared_generation.snapshot,
                    .delta = prepared_generation.delta,
                    .keys = indices,
                    .items = indices,
                    .item_equal = item_equal,
                    .row_handles_by_index = row_handles_by_index,
                    .candidate_bindings = candidate_bindings,
                };
            }

            fn transferEntry(_: *@This(), _: usize) void {}

            /// Transfers every remaining input value into a committed row reconciliation.
            pub fn transfer(self: *@This()) void {
                if (self.transferred) @panic("prepared each inputs transferred twice");
                self.transferred = true;
            }

            /// Releases a provisional generation unless commit transferred it
            /// into the engine's generation registry.
            pub fn deinit(self: *@This()) void {
                if (self.rows_generation_entry_reserved) {
                    if (self.engine.reserved_rows_generation_entries == 0) @panic("Rows generation reservation accounting underflow");
                    self.engine.reserved_rows_generation_entries -= 1;
                }
                if (self.rows_transition) |*transition| transition.deinit();
                if (self.rows_site_id) |site_id| if (!self.rows_site_published) {
                    if (self.engine.rows_store) |*store| {
                        store.destroyEmptySite(site_id) catch |err| switch (err) {
                            error.SiteNotEmpty => @panic("unpublished Rows transition populated its committed site"),
                            else => @panic("provisional Rows site became stale"),
                        };
                    } else @panic("provisional Rows site lost its store");
                };
                if (!self.transferred) {
                    for (self.created_handles.items) |handle| _ = self.engine.row_handle_registry.remove(handle) catch @panic("provisional each row handle was stale");
                    self.generation.deinit(self.allocator, self.ctx, self.roc_host, &self.engine.pending_roc_metrics);
                    self.allocator.destroy(self.generation);
                }
                self.snapshot.deinit(self.allocator);
                if (self.delta) |*delta| delta.deinit(self.allocator);
                self.allocator.free(self.keys);
                self.allocator.free(self.item_equal);
                self.allocator.free(self.row_handles_by_index);
                self.created_handles.deinit(self.allocator);
                self.candidate_bindings.deinit();
                self.* = undefined;
            }
        };

        /// Heap-stable ownership bridge from compiler-produced each inputs into keyed-row reconciliation.
        pub const PreparedActiveEachRows = struct {
            /// Typed engine view of one row in the prepared `Rows` candidate.
            /// Key bytes and metadata remain owned by the transition until the
            /// prepared collection plan is committed or aborted.
            pub const CandidateRow = struct {
                row_id: rows_transition.RowId,
                scope_id: ids.ScopeId,
                row_handle: row_handles.RowHandleId,
                item_slot: u64,
                render_span: rows_site_store.RowRenderSpan,
                key: []const u8,
                created: bool,
                item_changed: bool,
            };

            /// Allocation-free full-order cursor for structural and render
            /// consumers that genuinely need every candidate row.
            pub const CandidateIterator = struct {
                inner: rows_transition.CandidateIterator,

                /// Advances through the overlay order without constructing a
                /// positional scope, handle, key, or item array.
                pub fn next(self: *CandidateIterator) CollectionError!?CandidateRow {
                    const candidate = self.inner.next() orelse return null;
                    return @as(?CandidateRow, try adaptCandidate(candidate));
                }
            };

            /// Delta-bounded cursor for ordinary row-source propagation.
            pub const ChangedCandidateIterator = struct {
                inner: rows_transition.ChangedCandidateIterator,

                /// Advances through changed surviving rows only. The work is
                /// bounded by transition-local shadows, not total site length.
                pub fn next(self: *ChangedCandidateIterator) CollectionError!?CandidateRow {
                    const candidate = self.inner.next() orelse return null;
                    return @as(?CandidateRow, try adaptCandidate(candidate));
                }
            };

            /// Delta-bounded cursor over rows whose scopes and builders are
            /// newly created by this transition.
            pub const CreatedCandidateIterator = struct {
                rows: []const rows_transition.CreatedRow,
                index: usize = 0,

                /// Advances through the transition's creation journal only;
                /// untouched candidate rows are never visited.
                pub fn next(self: *CreatedCandidateIterator) CollectionError!?CandidateRow {
                    if (self.index == self.rows.len) return null;
                    const row = self.rows[self.index];
                    self.index += 1;
                    if (row.metadata.item_slot == 0 or row.metadata.row_handle == 0) return error.InvalidDescriptor;
                    return .{
                        .row_id = row.row_id,
                        .scope_id = ids.ScopeId.fromRaw(row.metadata.scope_id),
                        .row_handle = row_handles.RowHandleId.fromRaw(row.metadata.row_handle),
                        .item_slot = row.metadata.item_slot,
                        .render_span = row.metadata.render_span,
                        .key = row.key,
                        .created = true,
                        .item_changed = false,
                    };
                }
            };

            /// Borrowed adapter over one prepared sparse Rows transition.
            pub const CandidateRows = struct {
                transition: *const rows_transition.PreparedTransition,

                /// Returns the exact final row count without materialization.
                pub fn len(self: CandidateRows) usize {
                    return self.transition.candidateLen();
                }

                /// Starts allocation-free traversal of final intrusive order.
                pub fn iterate(self: CandidateRows) CandidateIterator {
                    return .{ .inner = self.transition.iterateCandidate() };
                }

                /// Returns a safe scratch reservation bound for changed rows.
                pub fn changedUpperBound(self: CandidateRows) usize {
                    return self.transition.changedCandidateUpperBound();
                }

                /// Starts traversal of changed surviving rows only.
                pub fn iterateChanged(self: CandidateRows) ChangedCandidateIterator {
                    return .{ .inner = self.transition.iterateChangedCandidates() };
                }

                /// Returns the exact number of row builders required by this
                /// sparse transition.
                pub fn createdLen(self: CandidateRows) usize {
                    return self.transition.createdRows().len;
                }

                /// Traverses only the transition's row-creation journal.
                pub fn iterateCreated(self: CandidateRows) CreatedCandidateIterator {
                    return .{ .rows = self.transition.createdRows() };
                }
            };

            allocator: std.mem.Allocator,
            engine: *Self,
            inputs: PreparedEachInputs,
            hooks: PreparedEachRowSyncHooks,
            rows: each_runtime.PreparedRowSync,
            owned_scope_claims: ?scope_runtime.PreparedScopeClaims = null,
            scope_claims: *scope_runtime.PreparedScopeClaims,
            removed_handles: []row_handles.RowHandleId = &.{},
            retired_generation: ?*each_generation.Generation = null,
            direct_delta: bool = false,
            direct_index: DirectRowIndex = .{},
            phase: CommitPhase = .prepared,

            /// Edit-bounded site-index bookkeeping for a matching-parent
            /// sparse delta. Survivors, moves, and item updates never enter
            /// the site's key index or membership table: only rows the
            /// transition created or removed do, and those are already
            /// enumerated by the transition's own journals. Counts are
            /// derived arithmetically from the transition, never by walking
            /// the candidate.
            const DirectRowIndex = struct {
                /// Scopes the transition created, in creation-journal order.
                created_scope_ids: []ids.ScopeId = &.{},
                /// Final row count of the site after publication.
                candidate_len: usize = 0,
                /// Surviving rows whose item changed in this delta.
                updated_count: usize = 0,
            };

            fn adaptCandidate(candidate: rows_transition.CandidateRow) CollectionError!CandidateRow {
                const row_id = candidate.row_id orelse return error.InvalidDescriptor;
                if (candidate.metadata.item_slot == 0 or candidate.metadata.row_handle == 0) return error.InvalidDescriptor;
                return .{
                    .row_id = row_id,
                    .scope_id = ids.ScopeId.fromRaw(candidate.metadata.scope_id),
                    .row_handle = row_handles.RowHandleId.fromRaw(candidate.metadata.row_handle),
                    .item_slot = candidate.metadata.item_slot,
                    .render_span = candidate.metadata.render_span,
                    .key = candidate.key,
                    .created = candidate.created,
                    .item_changed = candidate.item_changed,
                };
            }

            /// Borrows the prepared candidate in a form shared structural and
            /// render consumers can traverse without dense positional arrays.
            pub fn candidateRows(self: *const @This()) CandidateRows {
                const transition = if (self.inputs.rows_transition) |*value| value else @panic("prepared each rows lacked a Rows candidate transition");
                return .{ .transition = transition };
            }

            fn prepareDirectRows(
                engine: *Self,
                ctx: Ctx.Handle,
                allocator: std.mem.Allocator,
                site: HostNodeScopeSiteDesc,
                site_index: usize,
                rows_store: *rows_site_store.Store,
                rows_site_id: rows_site_store.SiteId,
                parent_owner: rows_site_store.OwnerToken,
                inputs: *PreparedEachInputs,
                scope_claims: *scope_runtime.PreparedScopeClaims,
                direct_index: *DirectRowIndex,
            ) CollectionError!each_runtime.PreparedRowSync {
                const delta = if (inputs.delta) |*value| value else return error.InvalidDescriptor;
                if (!delta.complete) return error.InvalidDescriptor;
                const edits = allocator.alloc(rows_transition.StableEdit, delta.ops.items.len) catch return error.OutOfMemory;
                defer allocator.free(edits);

                for (delta.ops.items, edits) |op, *edit| edit.* = switch (op) {
                    .clear => .clear,
                    .move => |value| .{ .move = .{ .first_slot = value.first_slot, .count = value.count, .before_slot = value.before_slot } },
                    .remove => |value| .{ .remove = .{ .first_slot = value.first_slot, .count = value.count } },
                    .update => |value| blk: {
                        const key = delta.keys.key(value.key_index) orelse return error.InvalidDescriptor;
                        const row_id = (rows_store.findItemSlot(rows_site_id, value.slot) catch return error.InvalidDescriptor) orelse return error.InvalidDescriptor;
                        const row = rows_store.getRowConst(rows_site_id, row_id) catch return error.InvalidDescriptor;
                        if (row.metadata.row_handle == 0) return error.InvalidDescriptor;
                        inputs.candidate_bindings.putAssumeCapacity(row_handles.RowHandleId.fromRaw(row.metadata.row_handle), .{
                            .generation_id = inputs.generation.id,
                            .item_slot = value.slot,
                        }, .{ .delta = value.key_index }) catch return error.InvalidDescriptor;
                        break :blk .{ .update = .{
                            .slot = value.slot,
                            .key = key,
                            .metadata = row.metadata,
                        } };
                    },
                    .insert => |value| blk: {
                        const key = delta.keys.key(value.key_index) orelse return error.InvalidDescriptor;
                        if (value.key_index >= delta.keys.hashes.items.len) return error.InvalidDescriptor;
                        const row_handle = engine.row_handle_registry.insert(Ctx.allocator(ctx), {}) catch |err| return switch (err) {
                            error.OutOfMemory => error.OutOfMemory,
                            error.ResourceLimit => error.ResourceLimit,
                        };
                        inputs.created_handles.append(allocator, row_handle) catch {
                            _ = engine.row_handle_registry.remove(row_handle) catch unreachable;
                            return error.OutOfMemory;
                        };
                        const scope_id = scope_claims.prepareRow(
                            &engine.scopes,
                            site.scope_id,
                            site.ordinal,
                            delta.keys.hashes.items[value.key_index],
                            row_handle,
                        ) catch |err| return switch (err) {
                            error.OutOfMemory => error.OutOfMemory,
                            error.ResourceLimit => error.ResourceLimit,
                        };
                        inputs.candidate_bindings.putAssumeCapacity(row_handle, .{
                            .generation_id = inputs.generation.id,
                            .item_slot = value.slot,
                        }, .{ .delta = value.key_index }) catch return error.InvalidDescriptor;
                        break :blk .{ .insert = .{
                            .slot = value.slot,
                            .before_slot = value.before_slot,
                            .key = key,
                            .metadata = .{
                                .item_slot = value.slot,
                                .scope_id = scope_id.raw(),
                                .row_handle = row_handle.raw(),
                            },
                        } };
                    },
                };

                const next_owner = rows_site_store.OwnerToken.fromRaw(inputs.generation.rows_generation) catch return error.InvalidDescriptor;
                inputs.rows_transition = rows_transition.PreparedTransition.prepareStable(
                    allocator,
                    rows_store,
                    rows_site_id,
                    parent_owner,
                    next_owner,
                    edits,
                ) catch |err| return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    error.ResourceLimit => error.ResourceLimit,
                    else => error.InvalidDescriptor,
                };
                const transition = &inputs.rows_transition.?;
                if (transition.candidateLen() != inputs.generation.item_count) return error.InvalidDescriptor;

                // Work here is bounded by the edit batch: created and removed
                // rows come from the transition's journals and changed
                // survivors from its touched set. The untouched remainder of
                // the site is never visited, so nothing below scales with
                // `candidateLen()`.
                const created_rows = transition.createdRows();
                const removed_rows = transition.removedRows();
                const binding_edits = std.math.add(usize, delta.ops.items.len, removed_rows.len) catch return error.ResourceLimit;
                inputs.candidate_bindings.reserve(binding_edits) catch |err| return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    error.ResourceLimit => error.ResourceLimit,
                };

                const created_scope_ids = allocator.alloc(ids.ScopeId, created_rows.len) catch return error.OutOfMemory;
                errdefer allocator.free(created_scope_ids);
                const removed_scope_ids = allocator.alloc(ids.ScopeId, removed_rows.len) catch return error.OutOfMemory;
                errdefer allocator.free(removed_scope_ids);

                var highest_scope_id = ids.root_scope;
                for (created_rows, created_scope_ids) |row, *scope_id| {
                    if (row.metadata.row_handle == 0 or row.metadata.item_slot == 0) return error.InvalidDescriptor;
                    scope_id.* = ids.ScopeId.fromRaw(row.metadata.scope_id);
                    if (scope_id.raw() > highest_scope_id.raw()) highest_scope_id = scope_id.*;
                }
                var updated_count: usize = 0;
                var changed = transition.iterateChangedCandidates();
                while (changed.next()) |row| {
                    if (row.metadata.row_handle == 0 or row.metadata.item_slot == 0) return error.InvalidDescriptor;
                    updated_count += 1;
                }
                engine.pending_roc_metrics.bump(.rows_candidate_rows_visited, @intCast(created_rows.len + updated_count));

                for (removed_rows, removed_scope_ids) |row_id, *scope_id| {
                    const row = rows_store.getRowConst(rows_site_id, row_id) catch return error.InvalidDescriptor;
                    if (row.metadata.row_handle == 0) return error.InvalidDescriptor;
                    scope_id.* = ids.ScopeId.fromRaw(row.metadata.scope_id);
                    inputs.candidate_bindings.removeAssumeCapacity(row_handles.RowHandleId.fromRaw(row.metadata.row_handle)) catch return error.InvalidDescriptor;
                }

                // The site index grows by at most the created rows; removals
                // swap-remove in place. Membership must cover the highest
                // created scope, which is the only fresh slot it can name.
                const legacy_site = &engine.each_row_sites.items[site_index];
                legacy_site.scope_ids.ensureUnusedCapacity(allocator, created_rows.len) catch return error.OutOfMemory;
                legacy_site.hash_links.ensureUnusedCapacity(allocator, created_rows.len) catch return error.OutOfMemory;
                legacy_site.hash_heads.ensureUnusedCapacity(allocator, std.math.cast(u32, created_rows.len) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                engine.each_row_memberships_by_scope_id.ensureTotalCapacity(allocator, std.math.add(usize, highest_scope_id.index(), 1) catch return error.ResourceLimit) catch return error.OutOfMemory;

                direct_index.* = .{
                    .created_scope_ids = created_scope_ids,
                    .candidate_len = transition.candidateLen(),
                    .updated_count = updated_count,
                };
                return .{
                    .allocator = allocator,
                    .site_index = site_index,
                    .next_scope_ids = &.{},
                    .key_hashes = &.{},
                    .row_items_changed = &.{},
                    .scope_created = &.{},
                    .removed_scope_ids = removed_scope_ids,
                    .created_count = created_rows.len,
                    .highest_scope_id = highest_scope_id,
                };
            }

            /// Retires the transition's removed stable rows before any
            /// overlapping structural replacement publishes reused scopes.
            fn commitRowsTransitionRemovalsEarly(self: *@This()) void {
                if (self.inputs.rows_transition) |*transition| transition.commitRemovalsEarly() else @panic("prepared active each lacked Rows transition");
            }

            /// Extracts owned inputs and prepares row matching without persistent mutation.
            pub fn prepare(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, site: HostNodeScopeSiteDesc, each: HostNodeEachDesc, allocator: std.mem.Allocator) CollectionError!*@This() {
                return prepareWithOverlay(engine, ctx, roc_host, site, &each, allocator, null);
            }

            fn prepareWithOverlay(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, site: HostNodeScopeSiteDesc, each: *const HostNodeEachDesc, allocator: std.mem.Allocator, overlay: ?*const signal_records.PreparedCacheUpdates) CollectionError!*@This() {
                return prepareWithOverlayAndScopeClaims(engine, ctx, roc_host, site, each, allocator, overlay, null);
            }

            fn prepareWithOverlayAndScopeClaims(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, site: HostNodeScopeSiteDesc, each: *const HostNodeEachDesc, allocator: std.mem.Allocator, overlay: ?*const signal_records.PreparedCacheUpdates, shared_scope_claims: ?*scope_runtime.PreparedScopeClaims) CollectionError!*@This() {
                const plan = allocator.create(@This()) catch return error.OutOfMemory;
                errdefer allocator.destroy(plan);
                plan.* = undefined;
                plan.direct_index = .{};
                errdefer allocator.free(plan.direct_index.created_scope_ids);
                plan.owned_scope_claims = if (shared_scope_claims == null) scope_runtime.PreparedScopeClaims.init(allocator, engine.scopes.items, ids.Generation.fromRaw(engine.identity_reuse_barrier)) else null;
                plan.scope_claims = shared_scope_claims orelse &plan.owned_scope_claims.?;
                errdefer if (plan.owned_scope_claims != null) {
                    plan.scope_claims.abort();
                    plan.scope_claims.deinit();
                };
                const rows_key = each_runtime.SiteKey{ .parent_scope_id = site.scope_id, .site_ordinal = site.ordinal };
                const rows_site_id = engine.rows_site_ids.get(rows_key) orelse return error.InvalidDescriptor;
                const rows_store = engine.rowsStore(allocator);
                const parent_owner = (rows_store.getSiteConst(rows_site_id) catch return error.InvalidDescriptor).owner_token;
                var inputs = try PreparedEachInputs.prepareWithOverlay(engine, ctx, roc_host, each, allocator, overlay, &.{}, parent_owner.raw());
                errdefer inputs.deinit();
                var hooks = PreparedEachRowSyncHooks.initWithScopeClaims(engine, ctx, roc_host, plan.scope_claims);
                errdefer hooks.deinit();
                hooks.inputs = &inputs;
                hooks.base.inputs = &inputs;
                const site_index = engine.activeEachRowSiteIndex(site.scope_id, site.ordinal) orelse @panic("active each descriptor had no row site");
                const direct_delta = inputs.delta != null and !inputs.snapshot.complete;
                var rows = if (direct_delta)
                    try prepareDirectRows(engine, ctx, allocator, site, site_index, rows_store, rows_site_id, parent_owner, &inputs, plan.scope_claims, &plan.direct_index)
                else blk: {
                    const binding_edits = std.math.add(usize, inputs.generation.item_count, engine.each_row_sites.items[site_index].scope_ids.items.len) catch return error.ResourceLimit;
                    inputs.candidate_bindings.reserve(binding_edits) catch |err| return switch (err) {
                        error.OutOfMemory => error.OutOfMemory,
                        error.ResourceLimit => error.ResourceLimit,
                    };
                    break :blk try each_runtime.PreparedRowSync.prepare(allocator, &engine.each_row_sites, &engine.each_row_memberships_by_scope_id, site_index, site.scope_id, site.ordinal, inputs.keys, inputs.items, &hooks);
                };
                errdefer {
                    rows.abort(&hooks);
                    rows.deinit();
                }
                if (!direct_delta) {
                    for (rows.removed_scope_ids) |scope_id| {
                        const row_handle = scope_runtime.eachRowHandle(engine.scopes.items, scope_id);
                        inputs.candidate_bindings.removeAssumeCapacity(row_handle) catch return error.InvalidDescriptor;
                    }
                    const next_owner = rows_site_store.OwnerToken.fromRaw(inputs.generation.rows_generation) catch return error.InvalidDescriptor;
                    const stable_edit_count = std.math.add(usize, rows.next_scope_ids.len, 1) catch return error.ResourceLimit;
                    const stable_edits = allocator.alloc(rows_transition.StableEdit, stable_edit_count) catch return error.OutOfMemory;
                    defer allocator.free(stable_edits);
                    stable_edits[0] = .clear;
                    for (rows.next_scope_ids, 0..) |row_scope_id, row_index| {
                        const slot = inputs.slot(row_index) orelse return error.InvalidDescriptor;
                        const key = inputs.key(row_index) orelse return error.InvalidDescriptor;
                        const row_handle = inputs.row_handles_by_index[row_index] orelse return error.InvalidDescriptor;
                        const render_span: rows_site_store.RowRenderSpan = if (rows_store.findScope(row_scope_id.raw())) |location|
                            (rows_store.getRowConst(location.site_id, location.row_id) catch return error.InvalidDescriptor).metadata.render_span
                        else
                            .{};
                        stable_edits[row_index + 1] = .{ .insert = .{
                            .slot = slot,
                            .before_slot = 0,
                            .key = key,
                            .metadata = .{
                                .item_slot = slot,
                                .scope_id = row_scope_id.raw(),
                                .row_handle = row_handle.raw(),
                                .render_span = render_span,
                            },
                        } };
                    }
                    inputs.rows_transition = rows_transition.PreparedTransition.prepareStable(allocator, rows_store, rows_site_id, parent_owner, next_owner, stable_edits) catch |err| return switch (err) {
                        error.OutOfMemory => error.OutOfMemory,
                        error.ResourceLimit => error.ResourceLimit,
                        else => error.InvalidDescriptor,
                    };
                }
                inputs.rows_site_id = rows_site_id;
                inputs.rows_site_published = true;
                inputs.candidate_bindings.preflightCommit(&engine.committed_row_bindings) catch |err| return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    error.ResourceLimit => error.ResourceLimit,
                };
                engine.each_generations.ensureUnusedCapacity(allocator, 1) catch return error.OutOfMemory;
                const generation_entries_with_reservations = std.math.add(usize, engine.each_generation_ids_by_rows_site.count(), engine.reserved_rows_generation_entries) catch return error.ResourceLimit;
                const generation_entry_bound = std.math.add(usize, generation_entries_with_reservations, 1) catch return error.ResourceLimit;
                engine.each_generation_ids_by_rows_site.ensureTotalCapacity(allocator, std.math.cast(u32, generation_entry_bound) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                engine.reserved_rows_generation_entries += 1;
                inputs.rows_generation_entry_reserved = true;
                const site_slot_count = std.math.add(usize, site_index, 1) catch return error.ResourceLimit;
                engine.each_generation_ids_by_site_index.ensureTotalCapacity(allocator, site_slot_count) catch return error.OutOfMemory;
                const removed_handles = allocator.alloc(row_handles.RowHandleId, rows.removed_scope_ids.len) catch return error.OutOfMemory;
                for (rows.removed_scope_ids, removed_handles) |scope_id, *handle| handle.* = scope_runtime.eachRowHandle(engine.scopes.items, scope_id);
                plan.allocator = allocator;
                plan.engine = engine;
                plan.inputs = inputs;
                plan.hooks = hooks;
                plan.rows = rows;
                plan.removed_handles = removed_handles;
                plan.direct_delta = direct_delta;
                plan.phase = .prepared;
                plan.hooks.inputs = &plan.inputs;
                plan.hooks.base.inputs = &plan.inputs;
                return plan;
            }

            /// Publishes row ownership/order without allocation and returns the structural diff.
            pub fn commit(self: *@This()) HostKeyedRowDiffResult {
                if (self.phase.isCommitted()) @panic("prepared active each rows committed twice");
                if (self.owned_scope_claims != null) self.scope_claims.commit(&self.engine.scopes);
                const result = if (self.direct_delta) self.commitDirectRows() else self.rows.commit(&self.engine.each_row_sites, &self.engine.each_row_memberships_by_scope_id, self.inputs.keys, self.inputs.items, &self.hooks);
                if (self.inputs.rows_transition) |*transition| {
                    if (self.direct_delta) self.engine.pending_roc_metrics.bump(.rows_order_links_touched, @intCast(transition.orderLinksTouched()));
                    transition.commit();
                } else @panic("prepared active each lacked Rows transition");
                const site_index = self.rows.site_index;
                const rows_site_id = self.inputs.rows_site_id orelse @panic("prepared active each lacked stable Rows site");
                while (self.engine.each_generation_ids_by_site_index.items.len <= site_index) self.engine.each_generation_ids_by_site_index.appendAssumeCapacity(null);
                if (self.engine.each_generation_ids_by_rows_site.get(rows_site_id)) |old_id| {
                    self.retired_generation = (self.engine.each_generations.fetchRemove(old_id) orelse @panic("stable Rows site named an absent generation")).value;
                }
                self.engine.each_generations.putAssumeCapacity(self.inputs.generation.id, self.inputs.generation);
                self.engine.each_generation_ids_by_site_index.items[site_index] = self.inputs.generation.id;
                self.engine.each_generation_ids_by_rows_site.putAssumeCapacity(rows_site_id, self.inputs.generation.id);
                if (!self.inputs.rows_generation_entry_reserved or self.engine.reserved_rows_generation_entries == 0) @panic("prepared active each lacked generation-map reservation");
                self.engine.reserved_rows_generation_entries -= 1;
                self.inputs.rows_generation_entry_reserved = false;
                self.inputs.candidate_bindings.commit(&self.engine.committed_row_bindings);
                self.inputs.transfer();
                self.hooks.base.recordRows(result.rows_reused, result.rows_created, result.rows_removed);
                // Each created row is a scope this commit published; the
                // scope-claim overlay does not count scopes on its own.
                self.engine.recordScopesCreated(result.rows_created);
                self.phase.markCommitted();
                return result;
            }

            /// Publishes a matching-parent sparse delta into the site's key
            /// index and membership table by touching only the rows the
            /// transition removed or created. Removed rows swap-remove out
            /// of the dense site table (one moved survivor per removal), and
            /// created rows append under the key hash their scope already
            /// carries, so no surviving key is rehashed and no untouched
            /// membership entry is rewritten. Committed row order lives in
            /// the Rows store, not in this table. Capacity was preflighted
            /// by `prepareDirectRows`; nothing here allocates.
            fn commitDirectRows(self: *@This()) HostKeyedRowDiffResult {
                const engine = self.engine;
                const site_index = self.rows.site_index;
                var row_keys = EachRowScopeKeyLookup{ .engine = engine };
                var entries_rewritten: u64 = 0;
                for (self.rows.removed_scope_ids) |scope_id| {
                    // Swap-removal rewrites the last row's membership unless
                    // the removed row already was the last one.
                    const membership = engine.each_row_memberships_by_scope_id.items[scope_id.index()] orelse @panic("removed each row lacked site membership");
                    const moved_survivor: u64 = if (membership.row_index + 1 != engine.each_row_sites.items[site_index].scope_ids.items.len) 1 else 0;
                    each_runtime.removeRowFromSiteIndex(&engine.each_row_sites, &engine.each_row_memberships_by_scope_id, scope_id, scope_runtime.eachRowKeyHash(engine.scopes.items, scope_id), &row_keys);
                    entries_rewritten += 1 + moved_survivor;
                }
                for (self.direct_index.created_scope_ids) |scope_id| {
                    each_runtime.appendRowToSiteIndex(self.allocator, &engine.each_row_sites, &engine.each_row_memberships_by_scope_id, site_index, scope_id, scope_runtime.eachRowKeyHash(engine.scopes.items, scope_id));
                    entries_rewritten += 1;
                }
                engine.pending_roc_metrics.bump(.rows_membership_entries_rewritten, entries_rewritten);

                const created_count = self.direct_index.created_scope_ids.len;
                const candidate_len = self.direct_index.candidate_len;
                const updated_count = self.direct_index.updated_count;
                if (candidate_len < created_count + updated_count) @panic("direct Rows delta counted more edited rows than the site holds");
                const result = HostKeyedRowDiffResult{
                    .scope_ids = &.{},
                    .row_items_changed = &.{},
                    .scope_created = &.{},
                    .removed_scope_ids = self.rows.removed_scope_ids,
                    .rows_reused = candidate_len - created_count,
                    .rows_created = @intCast(created_count),
                    .rows_removed = @intCast(self.rows.removed_scope_ids.len),
                    .row_items_unchanged = @intCast(candidate_len - created_count - updated_count),
                    .row_items_updated = @intCast(updated_count),
                };
                self.rows.removed_scope_ids = &.{};
                return result;
            }

            /// Aborts provisional cells or releases committed-plan storage.
            pub fn deinit(self: *@This()) void {
                if (!self.phase.isCommitted()) self.rows.abort(&self.hooks);
                self.rows.deinit();
                self.inputs.deinit();
                if (self.phase.isCommitted()) {
                    if (self.retired_generation) |generation| {
                        generation.deinit(self.allocator, self.hooks.base.ctx, self.hooks.base.roc_host, &self.engine.pending_roc_metrics);
                        self.allocator.destroy(generation);
                    }
                }
                self.allocator.free(self.removed_handles);
                self.allocator.free(self.direct_index.created_scope_ids);
                if (self.owned_scope_claims != null) {
                    self.scope_claims.abort();
                    self.scope_claims.deinit();
                }
                self.hooks.deinit();
                const allocator = self.allocator;
                allocator.destroy(self);
            }
        };

        const PreparedCompositeRows = struct {
            allocator: std.mem.Allocator,
            engine: *Self,
            host_ctx: Ctx.Handle,
            roc_host: *abi.RocHost,
            scope_claims: scope_runtime.PreparedScopeClaims,
            rows: []*PreparedActiveEachRows,
            replacements: []*PreparedEachRowReplacementCollection,
            replacement_owner: ?*PreparedReplacementOwner = null,
            layouts: []PreparedEachRowRenderLayout = &.{},
            descriptor_target_scopes: []bool = &.{},
            retired_scope_ids: []u64 = &.{},
            final_render_topology: ?PreparedFinalRenderTopology = null,
            render_layout_plan: ?PreparedRenderLayoutPlan = null,
            downstream: ?*PreparedStructuralDownstream = null,
            cache_overlay: ?*signal_records.PreparedCacheUpdates = null,
            /// The state value this transaction publishes, staged into the
            /// replacement collection so new rows read it; see
            /// `StagedCollectionCtx.stageExternalStates`.
            external_state: []const PreparedExternalState = &.{},
            prepared_len: usize = 0,
            phase: CommitPhase = .prepared,

            fn prepare(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, changes: []const HostDirtyStructuralSignal, overlay: *signal_records.PreparedCacheUpdates, state_update: []const PreparedExternalState) CollectionError!*@This() {
                if (changes.len < 2) return error.ResourceLimit;
                const owner = try create(engine, ctx, roc_host, changes.len);
                errdefer owner.deinit();
                owner.cache_overlay = overlay;
                owner.external_state = state_update;
                const allocator = Ctx.allocator(ctx);
                for (changes) |change| {
                    if (change.kind != .each) return error.ResourceLimit;
                    const site = engine.activeScopeSiteByNodeId(change.node_id.raw(), .each) orelse return error.InvalidDescriptor;
                    if (site.scope_id != change.scope_id or site.ordinal != change.ordinal) return error.InvalidDescriptor;
                    const each_index = engine.activeEachIndexByNodeId(change.node_id.raw()) orelse return error.InvalidDescriptor;
                    const each = &engine.active_stream.eaches.items[each_index];
                    if (each.items.record != change.record) return error.InvalidDescriptor;
                    try owner.prepareOne(site, each, overlay);
                }
                const sites = allocator.alloc(HostNodeScopeSiteDesc, changes.len) catch return error.OutOfMemory;
                defer allocator.free(sites);
                const eaches = allocator.alloc(*const HostNodeEachDesc, changes.len) catch return error.OutOfMemory;
                defer allocator.free(eaches);
                for (changes, 0..) |change, index| {
                    sites[index] = engine.activeScopeSiteByNodeId(change.node_id.raw(), .each) orelse return error.InvalidDescriptor;
                    const each_index = engine.activeEachIndexByNodeId(change.node_id.raw()) orelse return error.InvalidDescriptor;
                    eaches[index] = &engine.active_stream.eaches.items[each_index];
                }
                try owner.prepareReplacement(sites, eaches, .{}, &.{});
                {
                    if (try PreparedCompositeStructural.prepareSparseDownstream(engine, ctx, roc_host, &.{}, &.{}, sites, owner, owner.replacement_owner.?, overlay)) |downstream| {
                        owner.downstream = downstream;
                        return owner;
                    }
                }
                try owner.prepareRenderLayouts(sites);
                try owner.prepareDownstream(sites);
                return owner;
            }

            fn create(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, count: usize) CollectionError!*@This() {
                if (count == 0) return error.ResourceLimit;
                const allocator = Ctx.allocator(ctx);
                const owner = allocator.create(@This()) catch return error.OutOfMemory;
                errdefer allocator.destroy(owner);
                const rows = allocator.alloc(*PreparedActiveEachRows, count) catch return error.OutOfMemory;
                errdefer allocator.free(rows);
                const replacements = allocator.alloc(*PreparedEachRowReplacementCollection, count) catch return error.OutOfMemory;
                errdefer allocator.free(replacements);
                owner.* = .{
                    .allocator = allocator,
                    .engine = engine,
                    .host_ctx = ctx,
                    .roc_host = roc_host,
                    .scope_claims = scope_runtime.PreparedScopeClaims.init(allocator, engine.scopes.items, ids.Generation.fromRaw(engine.identity_reuse_barrier)),
                    .rows = rows,
                    .replacements = replacements,
                };
                return owner;
            }

            fn prepareOne(self: *@This(), site: HostNodeScopeSiteDesc, each: *const HostNodeEachDesc, overlay: ?*const signal_records.PreparedCacheUpdates) CollectionError!void {
                if (self.prepared_len == self.rows.len) return error.ResourceLimit;
                const prepared_rows = try PreparedActiveEachRows.prepareWithOverlayAndScopeClaims(self.engine, self.host_ctx, self.roc_host, site, each, self.allocator, overlay, &self.scope_claims);
                self.rows[self.prepared_len] = prepared_rows;
                const replacement = PreparedEachRowReplacementCollection.prepareEvaluated(self.engine, self.host_ctx, self.roc_host, each.*, prepared_rows) catch |err| {
                    prepared_rows.deinit();
                    return err;
                };
                self.replacements[self.prepared_len] = replacement;
                self.prepared_len += 1;
            }

            fn prepareReplacement(self: *@This(), sites: []const HostNodeScopeSiteDesc, eaches: []const *const HostNodeEachDesc, limits: collection_budget.Limits, dirty_source_node_ids: []const u64) CollectionError!void {
                if (self.replacement_owner != null or sites.len != self.prepared_len or eaches.len != self.prepared_len) return error.ResourceLimit;
                var total: StaticRootCounts = .{};
                var root_count: usize = 0;
                for (self.replacements[0..self.prepared_len]) |replacement| {
                    try PreparedReplacementOwner.addRootCounts(&total, replacement.counts);
                    root_count = std.math.add(usize, root_count, replacement.row_elems.len) catch return error.ResourceLimit;
                }
                const owner = try PreparedReplacementOwner.create(self.engine, self.host_ctx, self.roc_host, limits, total, root_count);
                errdefer owner.deinit();
                owner.collection.cache_overlay = self.cache_overlay;
                try owner.collection.stageExternalStates(self.roc_host, self.external_state);
                for (self.replacements[0..self.prepared_len], self.rows[0..self.prepared_len]) |replacement, rows| {
                    try owner.collection.indexCandidateGeneration(&rows.inputs);
                    try replacement.attachScopeIds(owner);
                }
                for (self.replacements[0..self.prepared_len], sites, eaches, 0..) |replacement, site, each, index| {
                    const previous_bindings = self.engine.active_each_candidate_bindings;
                    const previous_inputs = self.engine.active_each_candidate_inputs;
                    const previous_generation = self.engine.active_each_candidate_generation;
                    const previous_rows_site_id = self.engine.active_each_candidate_rows_site_id;
                    self.engine.active_each_candidate_bindings = &self.rows[index].inputs.candidate_bindings;
                    self.engine.active_each_candidate_inputs = &self.rows[index].inputs;
                    self.engine.active_each_candidate_generation = self.rows[index].inputs.generation;
                    self.engine.active_each_candidate_rows_site_id = self.rows[index].inputs.rows_site_id;
                    defer {
                        self.engine.active_each_candidate_bindings = previous_bindings;
                        self.engine.active_each_candidate_inputs = previous_inputs;
                        self.engine.active_each_candidate_generation = previous_generation;
                        self.engine.active_each_candidate_rows_site_id = previous_rows_site_id;
                    }
                    try replacement.collectRowsInto(site, each.*, owner, dirty_source_node_ids);
                }
                // Cover the transaction-wide unique bindings plus every local
                // overlay. The latter includes removals and nested edits whose
                // commit order may temporarily exceed the final live count.
                var binding_edits = std.math.add(usize, owner.collection.prepared_row_bindings.count(), owner.collection.candidate_binding_edit_count) catch return error.ResourceLimit;
                for (self.rows[0..self.prepared_len]) |rows| binding_edits = std.math.add(usize, binding_edits, rows.inputs.candidate_bindings.candidate.count()) catch return error.ResourceLimit;
                const binding_bound = std.math.add(usize, self.engine.committed_row_bindings.entries.count(), binding_edits) catch return error.ResourceLimit;
                self.engine.committed_row_bindings.entries.ensureTotalCapacity(self.allocator, std.math.cast(u32, binding_bound) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                owner.materialize();
                for (self.replacements[0..self.prepared_len], sites) |replacement, site| try replacement.finalizeRenderSpans(site);
                for (self.replacements[0..self.prepared_len]) |replacement| replacement.releaseEvaluatedRows();
                self.replacement_owner = owner;
            }

            fn prepareRenderLayouts(self: *@This(), sites: []const HostNodeScopeSiteDesc) CollectionError!void {
                if (self.replacement_owner == null or self.layouts.len != 0 or sites.len != self.prepared_len) return error.ResourceLimit;
                const layouts = self.allocator.alloc(PreparedEachRowRenderLayout, self.prepared_len) catch return error.OutOfMemory;
                var prepared_len: usize = 0;
                errdefer {
                    for (layouts[0..prepared_len]) |*layout| layout.deinit();
                    self.allocator.free(layouts);
                }
                for (layouts, sites, self.rows[0..self.prepared_len], self.replacements[0..self.prepared_len]) |*layout, site, rows, replacement| {
                    layout.* = try PreparedEachRowRenderLayout.prepare(self.engine, self.allocator, site, &rows.rows, replacement.replacement_rows, &self.replacement_owner.?.collection);
                    prepared_len += 1;
                }

                const targets = self.allocator.alloc(bool, self.engine.scopes.items.len) catch return error.OutOfMemory;
                errdefer self.allocator.free(targets);
                @memset(targets, false);
                var retired_count: usize = 0;
                for (layouts) |*layout| for (layout.targets.descriptor_target_scopes, 0..) |targeted, scope_index| if (targeted) {
                    if (targets[scope_index]) return error.ResourceLimit;
                    targets[scope_index] = true;
                };
                for (layouts) |*layout| retired_count = std.math.add(usize, retired_count, layout.targets.scope_retirement.?.scope_ids.len) catch return error.ResourceLimit;
                const retired_scope_ids = self.allocator.alloc(u64, retired_count) catch return error.OutOfMemory;
                errdefer self.allocator.free(retired_scope_ids);
                var retired_write: usize = 0;
                for (layouts) |*layout| for (layout.targets.scope_retirement.?.scope_ids) |scope_id| {
                    for (retired_scope_ids[0..retired_write]) |existing| if (existing == scope_id.raw()) return error.ResourceLimit;
                    retired_scope_ids[retired_write] = scope_id.raw();
                    retired_write += 1;
                };

                var plan = PreparedRenderLayoutPlan.init(self.allocator);
                errdefer plan.deinit();
                for (layouts) |*layout| try plan.describeEachSite(layout);
                try plan.describeNestedSites(self.replacement_owner.?.collection.nested_row_syncs.items);
                try plan.resolve(self.engine, targets);
                self.final_render_topology = try PreparedFinalRenderTopology.preparePlaced(self.engine, self.allocator, self.replacement_owner.?, targets, plan.removed_render_count, plan.placements.items);
                self.render_layout_plan = plan;
                self.descriptor_target_scopes = targets;
                self.retired_scope_ids = retired_scope_ids;
                self.layouts = layouts;
            }

            fn prepareDownstream(self: *@This(), sites: []const HostNodeScopeSiteDesc) CollectionError!void {
                if (self.downstream != null or self.final_render_topology == null or sites.len != self.prepared_len) return error.ResourceLimit;
                var descriptor_roots: shared_buffer.List(u64) = .empty;
                defer descriptor_roots.deinit(self.allocator);
                var retired_roots: shared_buffer.List(u64) = .empty;
                defer retired_roots.deinit(self.allocator);
                var remove_starts: shared_buffer.List(usize) = .empty;
                defer remove_starts.deinit(self.allocator);
                var parents: shared_buffer.List(u64) = .empty;
                defer parents.deinit(self.allocator);
                var scan_scopes: shared_buffer.List([]const bool) = .empty;
                defer scan_scopes.deinit(self.allocator);
                for (self.rows[0..self.prepared_len], self.replacements[0..self.prepared_len], self.layouts, sites) |rows, replacement, *layout, site| {
                    for (rows.rows.removed_scope_ids) |scope_id| descriptor_roots.append(self.allocator, scope_id.raw()) catch return error.OutOfMemory;
                    for (rows.rows.removed_scope_ids) |scope_id| retired_roots.append(self.allocator, scope_id.raw()) catch return error.OutOfMemory;
                    for (replacement.replacement_rows) |row| if (!row.created) descriptor_roots.append(self.allocator, row.scope_id.raw()) catch return error.OutOfMemory;
                    remove_starts.appendSlice(self.allocator, layout.remove_starts) catch return error.OutOfMemory;
                    // Each site's intervals must be scanned against that site's
                    // own target scopes. Scanning against the union lets a
                    // site's walk continue straight into an adjacent site's
                    // rows, which then collides with that site's interval.
                    for (layout.remove_starts) |_| scan_scopes.append(self.allocator, layout.targets.descriptor_target_scopes) catch return error.OutOfMemory;
                    var seen_parent = false;
                    for (parents.items) |parent| if (parent == site.parent_elem_id.raw()) {
                        seen_parent = true;
                        break;
                    };
                    if (!seen_parent) parents.append(self.allocator, site.parent_elem_id.raw()) catch return error.OutOfMemory;
                }
                try self.replacement_owner.?.collection.appendNestedSiteRenderParents(self.allocator, &parents);
                const downstream = try PreparedStructuralDownstream.prepareExternal(
                    self.engine,
                    self.host_ctx,
                    self.roc_host,
                    self.replacement_owner.?,
                    descriptor_roots.items,
                    retired_roots.items,
                    remove_starts.items,
                    scan_scopes.items,
                    parents.items,
                    self.cache_overlay,
                );
                errdefer downstream.deinit();
                downstream.final_render_topology = self.final_render_topology;
                self.final_render_topology = null;
                const plan = self.render_layout_plan orelse return error.ResourceLimit;
                self.render_layout_plan = null;
                try downstream.adoptRenderLayoutPlan(plan);
                try downstream.prepareFinalRenderTopology(parents.items);
                self.downstream = downstream;
            }

            fn commitDownstream(self: *@This()) void {
                const downstream = self.downstream orelse @panic("composite rows had no prepared downstream");
                downstream.commitAssumeCapacityWith(self, struct {
                    fn apply(composite: *PreparedCompositeRows) void {
                        composite.commit();
                    }
                }.apply);
            }

            fn commit(self: *@This()) void {
                if (self.phase.isCommitted()) @panic("prepared composite rows committed twice");
                self.scope_claims.commit(&self.engine.scopes);
                for (self.rows[0..self.prepared_len]) |rows| {
                    var diff = rows.commit();
                    diff.deinit(self.allocator);
                }
                self.phase.markCommitted();
            }

            fn commitRowsTransitionRemovalsEarly(self: *@This()) void {
                for (self.rows[0..self.prepared_len]) |rows| rows.commitRowsTransitionRemovalsEarly();
            }

            fn deinit(self: *@This()) void {
                if (self.downstream) |downstream| downstream.deinit();
                if (self.final_render_topology) |*topology| topology.deinit();
                if (self.render_layout_plan) |*plan| plan.deinit();
                self.allocator.free(self.retired_scope_ids);
                self.allocator.free(self.descriptor_target_scopes);
                for (self.layouts) |*layout| layout.deinit();
                self.allocator.free(self.layouts);
                if (self.replacement_owner) |owner| owner.deinit();
                for (self.replacements[0..self.prepared_len]) |replacement| replacement.deinit();
                for (self.rows[0..self.prepared_len]) |rows| rows.deinit();
                if (!self.phase.isCommitted()) self.scope_claims.abort();
                self.scope_claims.deinit();
                self.allocator.free(self.replacements);
                self.allocator.free(self.rows);
                const allocator = self.allocator;
                allocator.destroy(self);
            }
        };

        /// Preparation-only owner for a bounded mixed set of disjoint `when`
        /// branches and `each` rows. It deliberately stops before topology or
        /// downstream publication so production routing can adopt the seam only
        /// after the remaining transaction has equivalent fault coverage.
        const PreparedCompositeStructural = struct {
            const GlobalRange = struct {
                change_index: usize,
                scope_id: u64,
                start: usize,
                len: usize,
                site_start: usize,
                site_len: usize,
            };

            allocator: std.mem.Allocator,
            engine: *Self,
            normalized_whens: PreparedDirtyWhenSet,
            rows: *PreparedCompositeRows,
            replacement_owner: *PreparedReplacementOwner,
            branch_ranges: []GlobalRange,
            row_ranges: []GlobalRange,
            subsumed_each_indexes: []usize,
            layouts: []PreparedEachRowRenderLayout,
            downstream: *PreparedStructuralDownstream,
            changes: []HostDirtyStructuralSignal,
            overlay: *signal_records.PreparedCacheUpdates,
            phase: CommitPhase = .prepared,

            fn prepareSparseDownstream(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, selections: []const AggregateBranchSelection, branch_ranges: []const GlobalRange, sites: []const HostNodeScopeSiteDesc, rows: *PreparedCompositeRows, replacement: *PreparedReplacementOwner, overlay: *signal_records.PreparedCacheUpdates) CollectionError!?*PreparedStructuralDownstream {
                const allocator = Ctx.allocator(ctx);
                var parents: shared_buffer.List(u64) = .empty;
                defer parents.deinit(allocator);
                var parent_set: std.AutoHashMapUnmanaged(u64, void) = .{};
                defer parent_set.deinit(allocator);
                var retired_roots: shared_buffer.List(ids.ScopeId) = .empty;
                defer retired_roots.deinit(allocator);
                var synced_rows: shared_buffer.List(ids.ScopeId) = .empty;
                defer synced_rows.deinit(allocator);
                for (sites, rows.rows[0..rows.prepared_len], rows.replacements[0..rows.prepared_len]) |site, row_plan, row_replacement| {
                    if (row_plan.inputs.rows_transition == null) return null;
                    for (row_replacement.replacement_rows) |range| if (!range.created) return null;
                    const parent = try parent_set.getOrPut(allocator, site.parent_elem_id.raw());
                    if (!parent.found_existing) parents.append(allocator, site.parent_elem_id.raw()) catch return error.OutOfMemory;
                    retired_roots.appendSlice(allocator, row_plan.rows.removed_scope_ids) catch return error.OutOfMemory;
                    synced_rows.appendSlice(allocator, row_plan.rows.removed_scope_ids) catch return error.OutOfMemory;
                }
                for (selections) |selection| {
                    const parent = try parent_set.getOrPut(allocator, selection.parent_elem_id.raw());
                    if (!parent.found_existing) parents.append(allocator, selection.parent_elem_id.raw()) catch return error.OutOfMemory;
                    retired_roots.append(allocator, selection.retired_scope_id) catch return error.OutOfMemory;
                }
                const downstream = try PreparedStructuralDownstream.prepareSparseExternalScopes(engine, ctx, roc_host, replacement, retired_roots.items, synced_rows.items, parents.items, overlay);
                errdefer downstream.deinit();
                for (sites, rows.rows[0..rows.prepared_len]) |site, row_plan| {
                    try downstream.adoptSparseEachRender(site, row_plan);
                }
                try downstream.adoptSparseBranches(selections, branch_ranges);
                return downstream;
            }

            fn scopeCoveredByRetiredBranch(engine: *Self, scope_id: u64, selections: []const AggregateBranchSelection) CollectionError!bool {
                for (selections) |selection| if (engine.scopeIsDescendantOrSelf(scope_id, selection.retired_scope_id.raw()) catch |err| return scopeError(err)) return true;
                return false;
            }

            fn normalizedScopeRoots(engine: *Self, allocator: std.mem.Allocator, roots: []const u64) CollectionError![]u64 {
                const order = allocator.dupe(u64, roots) catch return error.OutOfMemory;
                errdefer allocator.free(order);
                const Sort = struct {
                    engine: *Self,
                    fn lessThan(sort: @This(), left: u64, right: u64) bool {
                        const left_depth = sort.engine.scopeDepth(left);
                        const right_depth = sort.engine.scopeDepth(right);
                        if (left_depth != right_depth) return left_depth < right_depth;
                        return left < right;
                    }
                };
                std.mem.sort(u64, order, Sort{ .engine = engine }, Sort.lessThan);
                var write: usize = 0;
                for (order) |candidate| {
                    var covered = false;
                    for (order[0..write]) |root| if (engine.scopeIsDescendantOrSelf(candidate, root) catch |err| return scopeError(err)) {
                        covered = true;
                        break;
                    };
                    if (!covered) {
                        order[write] = candidate;
                        write += 1;
                    }
                }
                if (write == order.len) return order;
                const normalized = allocator.dupe(u64, order[0..write]) catch return error.OutOfMemory;
                allocator.free(order);
                return normalized;
            }

            fn prepare(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, changes: []HostDirtyStructuralSignal, overlay: *signal_records.PreparedCacheUpdates, limits: collection_budget.Limits, dirty_source_node_ids: []const u64, state_update: []const PreparedExternalState) CollectionError!*@This() {
                var all_eaches_subsumed = false;
                return prepareWithSubsumedFlag(engine, ctx, roc_host, changes, overlay, limits, dirty_source_node_ids, state_update, &all_eaches_subsumed);
            }

            fn prepareWithSubsumedFlag(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, changes: []HostDirtyStructuralSignal, overlay: *signal_records.PreparedCacheUpdates, limits: collection_budget.Limits, dirty_source_node_ids: []const u64, state_update: []const PreparedExternalState, all_eaches_subsumed: *bool) CollectionError!*@This() {
                all_eaches_subsumed.* = false;
                const allocator = Ctx.allocator(ctx);
                var when_count: usize = 0;
                var each_count: usize = 0;
                for (changes) |change| switch (change.kind) {
                    .when => when_count = std.math.add(usize, when_count, 1) catch return error.ResourceLimit,
                    .each => each_count = std.math.add(usize, each_count, 1) catch return error.ResourceLimit,
                };
                if (when_count == 0 or each_count == 0) return error.ResourceLimit;

                var normalized = try PreparedDirtyWhenSet.prepareWhenSubset(engine, allocator, changes);
                var normalized_owned = true;
                errdefer if (normalized_owned) normalized.deinit(allocator);
                if (normalized.selected_indexes.len == 0) return error.ResourceLimit;

                const selections_storage = allocator.alloc(AggregateBranchSelection, normalized.selected_indexes.len) catch return error.OutOfMemory;
                defer allocator.free(selections_storage);
                var built_selection_count: usize = 0;
                defer for (selections_storage[0..built_selection_count]) |selection| selection.elem.decref(roc_host);
                var selections = selections_storage;
                for (normalized.selected_indexes, 0..) |change_index, selection_index| {
                    const change = changes[change_index];
                    const site = engine.activeScopeSiteByNodeId(change.node_id.raw(), .when) orelse return error.InvalidDescriptor;
                    if (site.scope_id != change.scope_id or site.ordinal != change.ordinal) return error.InvalidDescriptor;
                    const when_index = engine.activeWhenIndexByNodeId(change.node_id.raw()) orelse return error.InvalidDescriptor;
                    const when_desc = &engine.active_stream.whens.items[when_index];
                    if (when_desc.condition.record != change.record) return error.InvalidDescriptor;
                    const branch = change.branch orelse return error.InvalidDescriptor;
                    const retired_scope_id = (engine.activeWhenBranchScopeId(site.scope_id, site.ordinal, branch.opposite()) catch |err| return scopeError(err)) orelse return error.InvalidScope;
                    if ((engine.activeWhenBranchScopeId(site.scope_id, site.ordinal, branch) catch |err| return scopeError(err)) != null) return error.InvalidScope;
                    const value_cell = if (change.cache_staged_in_overlay) switch (overlay.readSlot(@constCast(&when_desc.cached_value)).*) {
                        .absent => return error.InvalidDescriptor,
                        .present => |cell| cell,
                    } else change.pending_when_cache orelse return error.InvalidDescriptor;
                    const branch_elem = engine.buildWhenElem(ctx, roc_host, when_desc.ops, value_cell.value, value_cell.cap);
                    selections[selection_index] = .{
                        .node_id = change.node_id,
                        .parent_scope_id = site.scope_id,
                        .site_ordinal = site.ordinal,
                        .parent_elem_id = site.parent_elem_id,
                        .retired_scope_id = retired_scope_id,
                        .render_insert_index = site.render_insert_index,
                        .binder_bindings = site.binder_bindings,
                        .branch = branch,
                        .elem = branch_elem,
                    };
                    built_selection_count += 1;
                }

                var subsumed_each = shared_buffer.List(usize).empty;
                errdefer subsumed_each.deinit(allocator);
                subsumed_each.ensureTotalCapacity(allocator, each_count) catch return error.OutOfMemory;
                const each_order = allocator.alloc(usize, each_count) catch return error.OutOfMemory;
                defer allocator.free(each_order);
                var order_write: usize = 0;
                for (changes, 0..) |change, change_index| if (change.kind == .each) {
                    each_order[order_write] = change_index;
                    order_write += 1;
                };
                const SortEach = struct {
                    engine: *Self,
                    changes: []const HostDirtyStructuralSignal,
                    fn ownershipDepth(sort: @This(), change_index: usize) usize {
                        const change = sort.changes[change_index];
                        var depth: usize = 0;
                        for (sort.changes, 0..) |candidate, candidate_index| {
                            if (candidate_index == change_index or candidate.kind != .each) continue;
                            const site = sort.engine.activeScopeSiteByNodeId(candidate.node_id.raw(), .each) orelse continue;
                            const each_site = HostEachSite{ .parent_scope_id = site.scope_id, .site_ordinal = site.ordinal };
                            if ((sort.engine.eachSiteRowAncestorScopeId(change.scope_id.raw(), each_site) catch null) != null) depth += 1;
                        }
                        return depth;
                    }
                    fn lessThan(sort: @This(), left: usize, right: usize) bool {
                        const left_ownership_depth = sort.ownershipDepth(left);
                        const right_ownership_depth = sort.ownershipDepth(right);
                        if (left_ownership_depth != right_ownership_depth) return left_ownership_depth < right_ownership_depth;
                        const left_depth = sort.engine.scopeDepth(sort.changes[left].scope_id.raw());
                        const right_depth = sort.engine.scopeDepth(sort.changes[right].scope_id.raw());
                        if (left_depth != right_depth) return left_depth < right_depth;
                        return left < right;
                    }
                };
                std.mem.sort(usize, each_order, SortEach{ .engine = engine, .changes = changes }, SortEach.lessThan);

                const rows = try PreparedCompositeRows.create(engine, ctx, roc_host, each_count);
                errdefer rows.deinit();
                rows.cache_overlay = overlay;
                const sites_storage = allocator.alloc(HostNodeScopeSiteDesc, each_count) catch return error.OutOfMemory;
                defer allocator.free(sites_storage);
                const eaches_storage = allocator.alloc(*const HostNodeEachDesc, each_count) catch return error.OutOfMemory;
                defer allocator.free(eaches_storage);
                const each_change_indexes_storage = allocator.alloc(usize, each_count) catch return error.OutOfMemory;
                defer allocator.free(each_change_indexes_storage);
                var removed_row_scopes = shared_buffer.List(u64).empty;
                defer removed_row_scopes.deinit(allocator);
                var each_write: usize = 0;
                for (each_order) |change_index| {
                    const change = changes[change_index];
                    var covered = try scopeCoveredByRetiredBranch(engine, change.scope_id.raw(), selections);
                    if (!covered) for (removed_row_scopes.items) |removed_scope_id| {
                        if (engine.scopeIsDescendantOrSelf(change.scope_id.raw(), removed_scope_id) catch |err| return scopeError(err)) {
                            covered = true;
                            break;
                        }
                    };
                    if (covered) {
                        subsumed_each.appendAssumeCapacity(change_index);
                        continue;
                    }
                    const site = engine.activeScopeSiteByNodeId(change.node_id.raw(), .each) orelse return error.InvalidDescriptor;
                    if (site.scope_id != change.scope_id or site.ordinal != change.ordinal) return error.InvalidDescriptor;
                    const each_index = engine.activeEachIndexByNodeId(change.node_id.raw()) orelse return error.InvalidDescriptor;
                    const each = &engine.active_stream.eaches.items[each_index];
                    if (each.items.record != change.record) return error.InvalidDescriptor;
                    sites_storage[each_write] = site;
                    eaches_storage[each_write] = each;
                    each_change_indexes_storage[each_write] = change_index;
                    try rows.prepareOne(site, each, overlay);
                    for (rows.rows[each_write].rows.removed_scope_ids) |scope_id| removed_row_scopes.append(allocator, scope_id.raw()) catch return error.OutOfMemory;
                    for (rows.replacements[each_write].row_elems) |row_elem| {
                        if (row_elem.created) continue;
                        removed_row_scopes.append(allocator, row_elem.scope_id.raw()) catch return error.OutOfMemory;
                    }
                    each_write += 1;
                }
                if (each_write == 0) {
                    all_eaches_subsumed.* = true;
                    return error.ResourceLimit;
                }
                const sites = sites_storage[0..each_write];
                const eaches = eaches_storage[0..each_write];
                const each_change_indexes = each_change_indexes_storage[0..each_write];
                const subsumed_each_indexes = subsumed_each.toOwnedSlice(allocator) catch return error.OutOfMemory;
                errdefer allocator.free(subsumed_each_indexes);

                // Row reconciliation can retire the owner of a dirty `when`
                // selected before the each diffs were known. Such a branch is
                // owned by the removed row and must not contribute a second,
                // stale replacement placement to this transaction.
                const selected_when_indexes = allocator.alloc(usize, normalized.selected_indexes.len) catch return error.OutOfMemory;
                defer allocator.free(selected_when_indexes);
                const combined_subsumed_capacity = std.math.add(usize, normalized.subsumed_indexes.len, normalized.selected_indexes.len) catch return error.ResourceLimit;
                const subsumed_when_indexes = allocator.alloc(usize, combined_subsumed_capacity) catch return error.OutOfMemory;
                defer allocator.free(subsumed_when_indexes);
                @memcpy(subsumed_when_indexes[0..normalized.subsumed_indexes.len], normalized.subsumed_indexes);
                var selected_when_write: usize = 0;
                var subsumed_when_write = normalized.subsumed_indexes.len;
                for (selections, normalized.selected_indexes) |selection, change_index| {
                    var covered = false;
                    for (removed_row_scopes.items) |removed_scope_id| {
                        if (engine.scopeIsDescendantOrSelf(selection.parent_scope_id.raw(), removed_scope_id) catch |err| return scopeError(err)) {
                            covered = true;
                            break;
                        }
                    }
                    if (covered) {
                        subsumed_when_indexes[subsumed_when_write] = change_index;
                        subsumed_when_write += 1;
                    } else {
                        selections_storage[selected_when_write] = selection;
                        selected_when_indexes[selected_when_write] = change_index;
                        selected_when_write += 1;
                    }
                }
                const selected_when_owned = allocator.dupe(usize, selected_when_indexes[0..selected_when_write]) catch return error.OutOfMemory;
                const subsumed_when_owned = allocator.dupe(usize, subsumed_when_indexes[0..subsumed_when_write]) catch {
                    allocator.free(selected_when_owned);
                    return error.OutOfMemory;
                };
                allocator.free(normalized.selected_indexes);
                allocator.free(normalized.subsumed_indexes);
                normalized.selected_indexes = selected_when_owned;
                normalized.subsumed_indexes = subsumed_when_owned;
                selections = selections_storage[0..selected_when_write];

                var total: StaticRootCounts = .{};
                for (selections) |selection| try PreparedReplacementOwner.addRootCounts(&total, try countStaticRootNodes(selection.elem));
                var row_root_count: usize = 0;
                for (rows.replacements[0..rows.prepared_len]) |replacement| {
                    try PreparedReplacementOwner.addRootCounts(&total, replacement.counts);
                    row_root_count = std.math.add(usize, row_root_count, replacement.row_elems.len) catch return error.ResourceLimit;
                }
                const root_count = std.math.add(usize, normalized.selected_indexes.len, row_root_count) catch return error.ResourceLimit;
                const replacement_owner = try PreparedReplacementOwner.create(engine, ctx, roc_host, limits, total, root_count);
                errdefer replacement_owner.deinit();
                replacement_owner.collection.cache_overlay = overlay;
                try replacement_owner.collection.stageExternalStates(roc_host, state_update);
                for (rows.rows[0..rows.prepared_len]) |prepared_rows| try replacement_owner.collection.indexCandidateGeneration(&prepared_rows.inputs);
                const branch_ranges = allocator.alloc(GlobalRange, normalized.selected_indexes.len) catch return error.OutOfMemory;
                errdefer allocator.free(branch_ranges);
                const row_ranges = allocator.alloc(GlobalRange, row_root_count) catch return error.OutOfMemory;
                errdefer allocator.free(row_ranges);

                for (rows.replacements[0..rows.prepared_len]) |replacement| {
                    try replacement.attachScopeIds(replacement_owner);
                }
                for (selections, normalized.selected_indexes, 0..) |selection, change_index, index| {
                    const collected = try replacement_owner.collectWhenSelectionRange(selection, dirty_source_node_ids);
                    branch_ranges[index] = .{ .change_index = change_index, .scope_id = collected.scope_id, .start = collected.start, .len = collected.len, .site_start = collected.site_start, .site_len = collected.site_len };
                }
                var row_write: usize = 0;
                for (rows.replacements[0..rows.prepared_len], rows.rows[0..rows.prepared_len], sites, eaches, each_change_indexes) |replacement, prepared_rows, site, each, change_index| {
                    const previous_bindings = engine.active_each_candidate_bindings;
                    const previous_inputs = engine.active_each_candidate_inputs;
                    const previous_generation = engine.active_each_candidate_generation;
                    const previous_rows_site_id = engine.active_each_candidate_rows_site_id;
                    engine.active_each_candidate_bindings = &prepared_rows.inputs.candidate_bindings;
                    engine.active_each_candidate_inputs = &prepared_rows.inputs;
                    engine.active_each_candidate_generation = prepared_rows.inputs.generation;
                    engine.active_each_candidate_rows_site_id = prepared_rows.inputs.rows_site_id;
                    defer {
                        engine.active_each_candidate_bindings = previous_bindings;
                        engine.active_each_candidate_inputs = previous_inputs;
                        engine.active_each_candidate_generation = previous_generation;
                        engine.active_each_candidate_rows_site_id = previous_rows_site_id;
                    }
                    try replacement.collectRowsInto(site, each.*, replacement_owner, dirty_source_node_ids);
                    for (replacement.replacement_rows) |range| {
                        row_ranges[row_write] = .{ .change_index = change_index, .scope_id = range.scope_id.raw(), .start = range.start, .len = range.len, .site_start = range.site_start, .site_len = range.site_len };
                        row_write += 1;
                    }
                }
                if (row_write != row_ranges.len) return error.ResourceLimit;
                var binding_edits = std.math.add(usize, replacement_owner.collection.prepared_row_bindings.count(), replacement_owner.collection.candidate_binding_edit_count) catch return error.ResourceLimit;
                for (rows.rows[0..rows.prepared_len]) |prepared_rows| binding_edits = std.math.add(usize, binding_edits, prepared_rows.inputs.candidate_bindings.candidate.count()) catch return error.ResourceLimit;
                const binding_bound = std.math.add(usize, engine.committed_row_bindings.entries.count(), binding_edits) catch return error.ResourceLimit;
                engine.committed_row_bindings.entries.ensureTotalCapacity(allocator, std.math.cast(u32, binding_bound) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                replacement_owner.materialize();
                for (rows.replacements[0..rows.prepared_len], sites) |replacement, site| try replacement.finalizeRenderSpans(site);
                for (rows.replacements[0..rows.prepared_len]) |replacement| replacement.releaseEvaluatedRows();

                if (try prepareSparseDownstream(engine, ctx, roc_host, selections, branch_ranges, sites, rows, replacement_owner, overlay)) |downstream| {
                    errdefer downstream.deinit();
                    const layouts = allocator.alloc(PreparedEachRowRenderLayout, 0) catch return error.OutOfMemory;
                    errdefer allocator.free(layouts);
                    const plan = allocator.create(@This()) catch return error.OutOfMemory;
                    plan.* = .{
                        .allocator = allocator,
                        .engine = engine,
                        .normalized_whens = normalized,
                        .rows = rows,
                        .replacement_owner = replacement_owner,
                        .branch_ranges = branch_ranges,
                        .row_ranges = row_ranges,
                        .subsumed_each_indexes = subsumed_each_indexes,
                        .layouts = layouts,
                        .downstream = downstream,
                        .changes = changes,
                        .overlay = overlay,
                    };
                    normalized_owned = false;
                    return plan;
                }

                const layouts = allocator.alloc(PreparedEachRowRenderLayout, rows.prepared_len) catch return error.OutOfMemory;
                var layouts_prepared: usize = 0;
                errdefer {
                    for (layouts[0..layouts_prepared]) |*layout| layout.deinit();
                    allocator.free(layouts);
                }
                for (layouts, sites, rows.rows[0..rows.prepared_len], rows.replacements[0..rows.prepared_len]) |*layout, site, prepared_rows, replacement| {
                    layout.* = try PreparedEachRowRenderLayout.prepare(engine, allocator, site, &prepared_rows.rows, replacement.replacement_rows, &replacement_owner.collection);
                    layouts_prepared += 1;
                }

                var descriptor_roots_list = shared_buffer.List(u64).empty;
                defer descriptor_roots_list.deinit(allocator);
                var retired_roots_list = shared_buffer.List(u64).empty;
                defer retired_roots_list.deinit(allocator);
                for (selections) |selection| {
                    descriptor_roots_list.append(allocator, selection.retired_scope_id.raw()) catch return error.OutOfMemory;
                    retired_roots_list.append(allocator, selection.retired_scope_id.raw()) catch return error.OutOfMemory;
                }
                for (rows.rows[0..rows.prepared_len], rows.replacements[0..rows.prepared_len]) |prepared_rows, replacement| {
                    for (prepared_rows.rows.removed_scope_ids) |scope_id| descriptor_roots_list.append(allocator, scope_id.raw()) catch return error.OutOfMemory;
                    for (prepared_rows.rows.removed_scope_ids) |scope_id| retired_roots_list.append(allocator, scope_id.raw()) catch return error.OutOfMemory;
                    for (replacement.replacement_rows) |range| if (!range.created) {
                        descriptor_roots_list.append(allocator, range.scope_id.raw()) catch return error.OutOfMemory;
                    };
                }
                const descriptor_roots = try normalizedScopeRoots(engine, allocator, descriptor_roots_list.items);
                defer allocator.free(descriptor_roots);
                const retired_roots = try normalizedScopeRoots(engine, allocator, retired_roots_list.items);
                defer allocator.free(retired_roots);
                var targets = try PreparedStructuralTargets.prepare(engine, allocator, descriptor_roots, retired_roots, &replacement_owner.collection);
                var targets_owned = true;
                errdefer if (targets_owned) targets.deinit(allocator);
                var layout_plan = PreparedRenderLayoutPlan.init(allocator);
                var layout_plan_owned = true;
                errdefer if (layout_plan_owned) layout_plan.deinit();
                for (selections, branch_ranges) |selection, range| {
                    _ = try layout_plan.describeBranch(engine, selection, .{ .scope_id = range.scope_id, .start = range.start, .len = range.len, .site_start = range.site_start, .site_len = range.site_len });
                }
                for (layouts) |*layout| try layout_plan.describeEachSite(layout);
                try layout_plan.describeNestedSites(replacement_owner.collection.nested_row_syncs.items);
                try layout_plan.resolve(engine, targets.descriptor_target_scopes);
                var final_render_topology = try PreparedFinalRenderTopology.preparePlaced(engine, allocator, replacement_owner, targets.descriptor_target_scopes, layout_plan.removed_render_count, layout_plan.placements.items);
                var final_topology_owned = true;
                errdefer if (final_topology_owned) final_render_topology.deinit();

                var removal_starts = shared_buffer.List(usize).empty;
                defer removal_starts.deinit(allocator);
                var inside_target = false;
                for (engine.active_stream.render_nodes.items, 0..) |node, index| {
                    const scope_id = renderNodeScopeId(&engine.active_stream, node);
                    const targeted = targets.descriptor_target_scopes[@intCast(scope_id)];
                    if (targeted and !inside_target) removal_starts.append(allocator, index) catch return error.OutOfMemory;
                    inside_target = targeted;
                }
                // Every edited site's parent takes its final child order from
                // the resolved topology, as the pure each path does; see
                // `AggregateBranchCollection.prepareWithState`. The render
                // parents of the live nested sites join them, since surviving
                // rows and collected ones interleave under those.
                var parents: shared_buffer.List(u64) = .empty;
                defer parents.deinit(allocator);
                for (selections) |selection| try PreparedStructuralDownstream.appendUniqueParentElemId(allocator, &parents, selection.parent_elem_id.raw());
                for (sites) |site| try PreparedStructuralDownstream.appendUniqueParentElemId(allocator, &parents, site.parent_elem_id.raw());
                try replacement_owner.collection.appendNestedSiteRenderParents(allocator, &parents);
                const downstream = try PreparedStructuralDownstream.prepareExternal(engine, ctx, roc_host, replacement_owner, descriptor_roots, retired_roots, removal_starts.items, null, parents.items, overlay);
                errdefer downstream.deinit();
                downstream.final_render_topology = final_render_topology;
                final_topology_owned = false;
                layout_plan_owned = false;
                try downstream.adoptRenderLayoutPlan(layout_plan);
                try downstream.prepareFinalRenderTopology(parents.items);
                downstream.suppressed_render_parent_ids = &.{};
                targets.deinit(allocator);
                targets_owned = false;

                const plan = allocator.create(@This()) catch return error.OutOfMemory;
                errdefer allocator.destroy(plan);
                plan.* = .{
                    .allocator = allocator,
                    .engine = engine,
                    .normalized_whens = normalized,
                    .rows = rows,
                    .replacement_owner = replacement_owner,
                    .branch_ranges = branch_ranges,
                    .row_ranges = row_ranges,
                    .subsumed_each_indexes = subsumed_each_indexes,
                    .layouts = layouts,
                    .downstream = downstream,
                    .changes = changes,
                    .overlay = overlay,
                };
                normalized_owned = false;
                return plan;
            }

            fn commitEarly(self: *@This()) void {
                self.overlay.commit();
            }

            fn commitLate(self: *@This()) void {
                self.rows.commit();
                for (self.normalized_whens.selected_indexes) |change_index| {
                    const change = &self.changes[change_index];
                    const when_index = self.engine.activeWhenIndexByNodeId(change.node_id.raw()) orelse @panic("prepared mixed when descriptor disappeared before commit");
                    change.commitPendingWhenCache(&self.engine.active_stream.whens.items[when_index].cached_value, self.rows.host_ctx, self.rows.roc_host, &self.engine.pending_roc_metrics);
                }
                for (self.normalized_whens.subsumed_indexes) |change_index| self.changes[change_index].abortPendingWhenCache(self.rows.host_ctx, self.rows.roc_host, &self.engine.pending_roc_metrics);
                self.phase.markCommitted();
            }

            fn commitRowsTransitionRemovalsEarly(self: *@This()) void {
                self.rows.commitRowsTransitionRemovalsEarly();
            }

            fn commitAssumeCapacity(self: *@This()) render.Counts {
                if (self.phase.isCommitted()) @panic("prepared mixed structural transaction committed twice");
                var counts = if (self.downstream.render_splice) |*splice| splice.counts() else render.Counts{};
                self.downstream.commitAssumeCapacityWithEarlyAndLate(self, commitEarly, self, commitLate);
                counts.addAll(self.engine.runActiveOnChangeInitialCommandIndices(self.rows.host_ctx, self.rows.roc_host, self.downstream.publication.?.replacement_on_change_indices));
                counts.addAll(self.engine.runActiveMountCommandIndices(self.rows.host_ctx, self.rows.roc_host, self.downstream.publication.?.replacement_mount_indices));
                if (comptime enable_runtime_metrics) self.engine.render_metrics.addCommandCounts(counts);
                return counts;
            }

            fn deinit(self: *@This()) void {
                self.downstream.deinit();
                for (self.layouts) |*layout| layout.deinit();
                self.allocator.free(self.layouts);
                self.replacement_owner.deinit();
                self.rows.deinit();
                self.normalized_whens.deinit(self.allocator);
                self.allocator.free(self.branch_ranges);
                self.allocator.free(self.row_ranges);
                self.allocator.free(self.subsumed_each_indexes);
                const allocator = self.allocator;
                allocator.destroy(self);
            }
        };

        const ScopeIdentityDeactivation = struct {
            engine: *Self,
            ctx: Ctx.Handle,
            roc_host: *abi.RocHost,

            /// Performs deactivate node inside the shared engine while preserving transaction and changed-set invariants.
            pub fn deactivateNode(self: *@This(), node_id: u64) void {
                const identity = self.engine.node_identities.items[@intCast(node_id)];
                _ = self.engine.active_node_identity_ids.remove(identityKey(identity.scope_id.raw(), identity.ordinal.raw()));
                self.engine.deactivateState(self.ctx, self.roc_host, node_id);
            }
        };

        const ScopeDisposal = struct {
            engine: *Self,
            ctx: Ctx.Handle,
            roc_host: *abi.RocHost,

            /// Performs deactivate node identities inside the shared engine while preserving transaction and changed-set invariants.
            pub fn deactivateNodeIdentities(self: *@This(), scope_id: ids.ScopeId) void {
                var identity_deactivation = ScopeIdentityDeactivation{ .engine = self.engine, .ctx = self.ctx, .roc_host = self.roc_host };
                var ordinal: u64 = 0;
                while (self.engine.active_node_identity_ids.fetchRemove(identityKey(scope_id.raw(), ordinal))) |entry| : (ordinal += 1) {
                    const node_id = entry.value;
                    identity_deactivation.deactivateNode(node_id);
                    const identity = &self.engine.node_identities.items[@intCast(node_id)];
                    identity.lifecycle = .{ .retired = ids.Generation.fromRaw(self.engine.identity_reuse_barrier) };
                    self.engine.has_inactive_node_identities = true;
                }
            }

            /// Appends cleanup events using capacity that must already satisfy the caller's transaction contract.
            pub fn appendCleanupEvents(self: *@This(), scope_id: ids.ScopeId) void {
                for (self.engine.active_stream.cleanups.items) |cleanup| {
                    if (cleanup.scope_id == scope_id) {
                        self.engine.appendCleanupEvent(self.ctx, cleanup.name);
                    }
                }
            }

            /// Performs deactivate dom identities inside the shared engine while preserving transaction and changed-set invariants.
            pub fn deactivateDomIdentities(self: *@This(), scope_id: ids.ScopeId) void {
                var ordinal: u64 = 0;
                while (self.engine.active_dom_identity_ids.fetchRemove(identityKey(scope_id.raw(), ordinal))) |entry| : (ordinal += 1) {
                    const identity = &self.engine.dom_identities.items[@intCast(entry.value - 1)];
                    identity.lifecycle = .{ .retired = ids.Generation.fromRaw(self.engine.identity_reuse_barrier) };
                    self.engine.has_inactive_dom_identities = true;
                }
            }

            /// Removes each row and releases the ownership attached to that live entry.
            pub fn removeEachRow(self: *@This(), scope_id: ids.ScopeId, key_hash: u64, row_handle: row_handles.RowHandleId) void {
                self.engine.removeEachRowFromSiteIndex(scope_id.raw(), key_hash);
                if (!self.engine.committed_row_bindings.entries.remove(row_handle)) @panic("disposed each row had no committed generation binding");
                _ = self.engine.row_handle_registry.remove(row_handle) catch @panic("disposed each row had a stale row handle");
            }

            /// Performs deinit scope step inside the shared engine while preserving transaction and changed-set invariants.
            pub fn deinitScopeStep(self: *@This(), step: *HostScopeStep) void {
                _ = self;
                deinitHostScopeStep(step);
            }

            /// Records scope disposed in the metrics or lifecycle state owned by this operation.
            pub fn recordScopeDisposed(self: *@This()) void {
                self.engine.has_inactive_scopes = true;
                var metrics = self.engine.pending_roc_metrics;
                metrics.bump(.scopes_disposed, 1);
                self.engine.pending_roc_metrics = metrics;
            }
        };

        const ActiveDomIds = struct {
            stream: *const HostNodeDescriptorStream,

            /// Performs elem id is active inside the shared engine while preserving transaction and changed-set invariants.
            pub fn elemIdIsActive(self: @This(), elem_id: ids.ElemId) bool {
                const index = self.stream.elemDescriptorIndex(elem_id) orelse return false;
                return elemDescriptorIndexActive(index);
            }
        };

        /// Creates an initialized value with the ownership and capacity invariants required by this module.
        pub fn init() Self {
            return .{};
        }

        /// Copies one key into the currently active generation-scoped sink.
        /// The caller retains ownership of `key` only until this function returns.
        pub fn pushEachKeySink(self: *Self, _: Ctx.Handle, token: u64, index: u64, key: []const u8) each_collection.SinkError!u64 {
            const item_index = std.math.cast(usize, index) orelse return error.ResourceLimit;
            const sink_token: each_collection.SinkToken = @enumFromInt(token);
            try self.active_each_sinks.pushKeyBorrowed(sink_token, item_index, key);
            return token;
        }

        /// Writes one comparison result into the currently active
        /// generation-scoped sink without allocating.
        pub fn pushEachBoolSink(self: *Self, _: Ctx.Handle, token: u64, index: u64, value: bool) each_collection.SinkError!u64 {
            const item_index = std.math.cast(usize, index) orelse return error.ResourceLimit;
            const sink_token: each_collection.SinkToken = @enumFromInt(token);
            try self.active_each_sinks.pushBool(sink_token, item_index, value);
            return token;
        }

        /// Records the one snapshot description for the active Rows callback.
        pub fn pushRowsSnapshotDescriptionSink(self: *Self, _: Ctx.Handle, token: u64, generation: u64, item_count: u64, key_bytes: u64) each_collection.SinkError!u64 {
            try self.active_each_sinks.pushSnapshotDescription(@enumFromInt(token), generation, item_count, key_bytes);
            return token;
        }

        /// Records the one canonical delta description for the active Rows callback.
        pub fn pushRowsDeltaDescriptionSink(self: *Self, _: Ctx.Handle, token: u64, generation: u64, parent: u64, item_count: u64, snapshot_key_bytes: u64, op_count: u64, delta_key_count: u64, delta_key_bytes: u64) each_collection.SinkError!u64 {
            try self.active_each_sinks.pushDeltaDescription(@enumFromInt(token), generation, parent, item_count, snapshot_key_bytes, op_count, delta_key_count, delta_key_bytes);
            return token;
        }

        /// Copies one counted snapshot row; the host retains no Roc string borrow.
        pub fn pushRowsSnapshotSink(self: *Self, _: Ctx.Handle, token: u64, index: u64, slot: u64, key: []const u8) each_collection.SinkError!u64 {
            try self.active_each_sinks.pushSnapshot(@enumFromInt(token), std.math.cast(usize, index) orelse return error.ResourceLimit, slot, key);
            return token;
        }

        /// Copies one canonical clear operation into preallocated delta scratch.
        pub fn pushRowsDeltaClearSink(self: *Self, _: Ctx.Handle, token: u64, op_index: u64) each_collection.SinkError!u64 {
            try self.active_each_sinks.pushDeltaClear(@enumFromInt(token), std.math.cast(usize, op_index) orelse return error.ResourceLimit);
            return token;
        }

        /// Copies one canonical insert; ABI order is before-slot then inserted slot.
        pub fn pushRowsDeltaInsertSink(self: *Self, _: Ctx.Handle, token: u64, op_index: u64, before_slot: u64, slot: u64, key: []const u8) each_collection.SinkError!u64 {
            try self.active_each_sinks.pushDeltaInsert(@enumFromInt(token), std.math.cast(usize, op_index) orelse return error.ResourceLimit, slot, before_slot, key);
            return token;
        }

        /// Copies one canonical stable-slot range move into preallocated scratch.
        pub fn pushRowsDeltaMoveSink(self: *Self, _: Ctx.Handle, token: u64, op_index: u64, first_slot: u64, count: u64, before_slot: u64) each_collection.SinkError!u64 {
            try self.active_each_sinks.pushDeltaMove(@enumFromInt(token), std.math.cast(usize, op_index) orelse return error.ResourceLimit, first_slot, count, before_slot);
            return token;
        }

        /// Copies one canonical stable-slot range removal into preallocated scratch.
        pub fn pushRowsDeltaRemoveSink(self: *Self, _: Ctx.Handle, token: u64, op_index: u64, first_slot: u64, count: u64) each_collection.SinkError!u64 {
            try self.active_each_sinks.pushDeltaRemove(@enumFromInt(token), std.math.cast(usize, op_index) orelse return error.ResourceLimit, first_slot, count);
            return token;
        }

        /// Copies one canonical item update and its exact authenticated key.
        pub fn pushRowsDeltaUpdateSink(self: *Self, _: Ctx.Handle, token: u64, op_index: u64, slot: u64, key: []const u8) each_collection.SinkError!u64 {
            try self.active_each_sinks.pushDeltaUpdate(@enumFromInt(token), std.math.cast(usize, op_index) orelse return error.ResourceLimit, slot, key);
            return token;
        }

        fn prepareEachGeneration(
            self: *Self,
            ctx: Ctx.Handle,
            roc_host: *abi.RocHost,
            each: *const HostNodeEachDesc,
            overlay: ?*const signal_records.PreparedCacheUpdates,
            provisional_states: []const HostState,
            expected_rows_parent: ?u64,
            allocator: std.mem.Allocator,
        ) CollectionError!PreparedEachGeneration {
            const items_slot = if (overlay) |prepared| prepared.readSlot(@constCast(&each.cached_value)) else &each.cached_value;
            const collection = self.cloneCachedSignalValue(ctx, items_slot);
            const items_cap = self.hostSignalRecordCapabilityWithProvisionalStates(ctx, each.items.record, provisional_states);
            assertHostValueCapabilitiesMatch(each.ops.rows_capability, items_cap, "Rows capability did not match its signal value");
            var collection_owned = true;
            errdefer if (collection_owned) callHostValueToUnitWithCapability(ctx, roc_host, items_cap, hv.hostValueCapabilityDrop(items_cap), collection);

            var description_sink: each_collection.DescriptionSink = .{};
            const description_token = self.active_each_sinks.activateDescription(&description_sink) catch return error.ResourceLimit;
            errdefer self.active_each_sinks.abort(description_token) catch {};
            const described = retained_values.callRowsDescribe(Ctx, ctx, roc_host, items_cap, each.ops.describe, collection, @intFromEnum(description_token));
            if (described != @intFromEnum(description_token)) return error.InvalidDescriptor;
            const description = self.active_each_sinks.finishDescription(description_token) catch return error.InvalidDescriptor;
            const Shape = struct { generation: u64, item_count: usize, key_bytes: usize };
            const shape: Shape = switch (description) {
                .snapshot => |value| .{ .generation = value.generation, .item_count = value.item_count, .key_bytes = value.snapshot_key_bytes },
                .delta => |value| .{ .generation = value.generation, .item_count = value.item_count, .key_bytes = value.snapshot_key_bytes },
            };
            const use_direct_delta = switch (description) {
                .snapshot => false,
                .delta => |value| if (expected_rows_parent) |expected| value.parent == expected else false,
            };
            var delta: each_collection.DeltaStorage = .{};
            var has_delta = false;
            // `DeltaStorage.prepare` grows the operation buffer before the key
            // arena, so a refusal inside it can leave storage behind while
            // `has_delta` is still false. Releasing unconditionally is a no-op
            // for untouched storage and returns that partial reservation.
            errdefer delta.deinit(allocator);
            if (use_direct_delta) {
                const delta_shape = description.delta;
                var delta_sink = delta.prepare(allocator, delta_shape.op_count, delta_shape.delta_key_count, delta_shape.delta_key_bytes) catch |err| return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    error.ResourceLimit => error.ResourceLimit,
                    else => error.InvalidDescriptor,
                };
                has_delta = true;
                const delta_token = self.active_each_sinks.activateDelta(&delta_sink) catch return error.ResourceLimit;
                errdefer self.active_each_sinks.abort(delta_token) catch {};
                const copied_delta = retained_values.callRowsCopyDelta(Ctx, ctx, roc_host, each.ops.rows_capability, each.ops.copy_delta, collection, @intFromEnum(delta_token));
                if (copied_delta != @intFromEnum(delta_token)) return error.InvalidDescriptor;
                self.active_each_sinks.finishDelta(delta_token) catch return error.InvalidDescriptor;
            }

            var snapshot: each_collection.SnapshotStorage = .{};
            errdefer snapshot.deinit(allocator);
            if (!use_direct_delta) {
                // A fresh site, an explicit snapshot generation, or a stale
                // sibling delta is authenticated through the exact counted
                // snapshot fallback. We never retain both representations.
                var sink = snapshot.prepare(allocator, shape.item_count, shape.key_bytes) catch |err| return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    else => error.ResourceLimit,
                };
                const snapshot_token = self.active_each_sinks.activateSnapshot(&sink) catch return error.ResourceLimit;
                errdefer self.active_each_sinks.abort(snapshot_token) catch {};
                const copied = retained_values.callRowsCopySnapshot(Ctx, ctx, roc_host, each.ops.rows_capability, each.ops.copy_snapshot, collection, @intFromEnum(snapshot_token));
                if (copied != @intFromEnum(snapshot_token)) return error.InvalidDescriptor;
                self.active_each_sinks.finishSnapshot(snapshot_token) catch return error.InvalidDescriptor;
            }

            // Engine generation identity is site-publication identity, not the
            // Roc generation callable address: the same immutable Rows value
            // may legitimately feed more than one Ui.each site.
            const id = self.each_generation_clock.mint() catch return error.ResourceLimit;
            const generation = allocator.create(each_generation.Generation) catch return error.OutOfMemory;
            errdefer allocator.destroy(generation);
            generation.* = each_generation.Generation.initOwned(id, shape.generation, collection, each.ops, shape.item_count, &self.pending_roc_metrics) catch return error.InvalidDescriptor;
            collection_owned = false;
            const result = PreparedEachGeneration{
                .generation = generation,
                .description = description,
                .snapshot = snapshot,
                .delta = if (has_delta) delta else null,
            };
            snapshot = .{};
            delta = .{};
            has_delta = false;
            return result;
        }

        /// Performs deinit scratch inside the shared engine while preserving transaction and changed-set invariants.
        pub fn deinitScratch(self: *Self, ctx: Ctx.Handle) void {
            self.scratch.deinit(Ctx.allocator(ctx));
        }

        /// Releases the empty selector registry's retained hash-table storage.
        pub fn deinitSelectors(self: *Self, ctx: Ctx.Handle) void {
            if (self.selectors.groups.count() != 0) @panic("selector registry deinitialized while members were active");
            self.selectors.deinit(Ctx.allocator(ctx));
        }

        fn scratchBinderStack(self: *Self, allocator: std.mem.Allocator, base: []const HostBinderBinding) *shared_buffer.List(HostBinderBinding) {
            if (self.scratch.binder_stack.items.len != 0) {
                @panic("engine binder scratch was already active");
            }
            self.scratch.binder_stack.appendSlice(allocator, base) catch @panic("out of memory");
            return &self.scratch.binder_stack;
        }

        const PreparedSelectorAppend = selector_runtime.Registry(HostSignalRecord).PreparedAppend;

        /// Stages the selector memberships a prepared graph change appends.
        ///
        /// Work here is proportional to the appended records: surviving
        /// memberships stay in the live registry untouched, and retired ones
        /// leave through `ActiveSignalGraphLifecycle.releaseRecord` when the
        /// release closure runs at commit. Staged keys and buckets are owned by
        /// the returned value until `commitPreparedSelectors` moves them into the
        /// live registry; dropping it before then is the complete rollback. The
        /// live registry's tables are only grown, never edited, before commit.
        fn prepareSelectorsForGraphChange(
            self: *Self,
            allocator: std.mem.Allocator,
            append: *const active_graph.PreparedGraphAppend(HostSignalRecord),
        ) CollectionError!PreparedSelectorAppend {
            var prepared: PreparedSelectorAppend = .{};
            errdefer prepared.deinit(allocator);
            for (append.new_nodes) |node| switch (node.record.payload) {
                .select, .keyed_select => |payload| prepared.stage(allocator, payload.input, payload.key, node.record) catch return error.OutOfMemory,
                else => {},
            };
            prepared.reserveLive(allocator, &self.selectors) catch return error.OutOfMemory;
            return prepared;
        }

        /// Publishes staged selector memberships after the release closure has
        /// unregistered the retired ones. Allocation-free by construction. The
        /// selector work counters are reported here, once per committed
        /// transaction, so a preparation that was refused and retried does not
        /// inflate them.
        fn commitPreparedSelectors(self: *Self, allocator: std.mem.Allocator, prepared: *PreparedSelectorAppend, append: *const active_graph.PreparedGraphAppend(HostSignalRecord)) void {
            self.pending_roc_metrics.bump(.selector_registry_visits, append.new_nodes.len);
            self.pending_roc_metrics.bump(.selector_registrations, prepared.staged_memberships);
            self.pending_roc_metrics.bump(.selector_key_bytes_copied, prepared.staged_key_bytes);
            prepared.commitInto(allocator, &self.selectors);
        }

        fn debugPhase(ctx: Ctx.Handle, phase: DebugPhase) void {
            if (comptime @hasDecl(Ctx, "debugPhase")) {
                Ctx.debugPhase(ctx, phase);
            }
        }

        fn callHostValueToUnitWithCapability(ctx: Ctx.Handle, roc_host: *abi.RocHost, cap: HostValueCapability, callable: abi.RocErasedCallable, value: HostValue) void {
            retained_values.callHostValueToUnitWithCapability(Ctx, ctx, roc_host, cap, callable, value);
        }

        fn callHostValueToHostValueWithCapability(ctx: Ctx.Handle, roc_host: *abi.RocHost, cap: HostValueCapability, callable: abi.RocErasedCallable, value: HostValue) HostValue {
            return retained_values.callHostValueToHostValueWithCapability(Ctx, ctx, roc_host, cap, callable, value);
        }

        fn callHostValueToElemWithCapability(ctx: Ctx.Handle, roc_host: *abi.RocHost, cap: HostValueCapability, callable: abi.RocErasedCallable, value: HostValue) abi.Elem {
            return retained_values.callHostValueToElemWithCapability(Ctx, ctx, roc_host, cap, callable, value);
        }

        fn callHostValueToCmdWithCapability(ctx: Ctx.Handle, roc_host: *abi.RocHost, cap: HostValueCapability, callable: abi.RocErasedCallable, value: HostValue) erased_calls.Cmd {
            return retained_values.callHostValueToCmdWithCapability(Ctx, ctx, roc_host, cap, callable, value);
        }

