        /// Records dispatch in the metrics or lifecycle state owned by this operation.
        pub fn recordDispatch(self: *Self) void {
            if (comptime !enable_runtime_metrics) return;
            self.dispatch_metrics.events_processed += 1;
            self.dispatch_metrics.recompute_batches += 1;
        }

        /// Records stream nodes scanned in the metrics or lifecycle state owned by this operation.
        pub fn recordStreamNodesScanned(self: *Self, count: usize) void {
            self.pending_roc_metrics.bump(.stream_nodes_scanned, @intCast(count));
        }

        /// Records stream nodes scanned by in the metrics or lifecycle state owned by this operation.
        pub fn recordStreamNodesScannedBy(self: *Self, comptime field: RuntimeMetrics.Field, count: usize) void {
            var metrics = self.pending_roc_metrics;
            metrics.bump(.stream_nodes_scanned, @intCast(count));
            metrics.bump(field, @intCast(count));
            self.pending_roc_metrics = metrics;
        }

        /// Records scope created in the metrics or lifecycle state owned by this operation.
        pub fn recordScopeCreated(self: *Self) void {
            var metrics = self.pending_roc_metrics;
            metrics.bump(.scopes_created, 1);
            self.pending_roc_metrics = metrics;
        }

        /// Counts `count` scopes published at once, such as the row scopes a
        /// keyed reconciliation created.
        pub fn recordScopesCreated(self: *Self, count: u64) void {
            var metrics = self.pending_roc_metrics;
            metrics.bump(.scopes_created, count);
            self.pending_roc_metrics = metrics;
        }

        /// Counts `count` keyed rows created by a staged mount, together with
        /// the row scopes they occupy, in the pending transaction metrics.
        pub fn recordRowsCreated(self: *Self, count: u64) void {
            var metrics = self.pending_roc_metrics;
            metrics.bump(.rows_created, count);
            self.pending_roc_metrics = metrics;
        }

        /// Retires prepared scope subtrees at publication. Each scope's step
        /// moves into `retired_steps` for the deferred, host-calling release,
        /// the scopes become inactive, and the disposals are recorded in the
        /// same `scopes_disposed` counter the immediate disposal path reports
        /// through `recordScopeDisposed`: the metric describes what the
        /// reconciler did, not which publication path did it. Allocation free;
        /// `retired_steps` must already hold capacity for every scope.
        fn commitPreparedScopeRetirement(self: *Self, allocator: std.mem.Allocator, retirement: *const scope_runtime.PreparedSubtreeRetirement, retired_steps: *shared_buffer.List(HostScopeStep)) void {
            for (retirement.scope_ids) |scope_id| {
                const scope = &self.scopes.items[scope_id.index()];
                retired_steps.appendAssumeCapacity(scope.step);
                scope.step = .root;
            }
            retirement.applyMetadata(HostEachRowScopeStep, self.scopes.items, ids.Generation.fromRaw(self.identity_reuse_barrier));
            for (retirement.scope_ids) |scope_id| self.active_stream.releaseRetiredScopeIndexes(allocator, scope_id);
            self.has_inactive_scopes = retirement.scope_ids.len != 0 or self.has_inactive_scopes;
            var metrics = self.pending_roc_metrics;
            metrics.bump(.scopes_disposed, @intCast(retirement.scope_ids.len));
            self.pending_roc_metrics = metrics;
        }

        /// Releases ownership carried by a scope step after prepared metadata
        /// retirement has made that step unreachable from the committed scope
        /// table. Sparse row retirement has already removed the row from its
        /// site. A Rows candidate overlay may already have removed the binding
        /// at publication, while generic subtree retirement leaves it here for
        /// final cleanup. The generation-checked public handle remains owned
        /// by the retired scope in both cases and must be released exactly once.
        fn releasePreparedRetiredScopeStep(self: *Self, step: *HostScopeStep) void {
            switch (step.*) {
                .each_row => |row| {
                    _ = self.committed_row_bindings.entries.remove(row.row_handle);
                    _ = self.row_handle_registry.remove(row.row_handle) catch @panic("prepared retired row scope had a stale row handle");
                },
                .root, .component, .when_branch => {},
            }
            deinitHostScopeStep(step);
        }

