        /// Clears event descriptors while retaining bounded storage where the type promises reuse.
        pub fn clearEventDescriptors(self: *Self) void {
            self.event_descriptors.items.len = 0;
        }

        /// Releases the active table's event owner after its graph membership
        /// has been detached. Descriptor copies only borrow this handler.
        pub fn deinitActiveEventDesc(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, desc: ActiveEventDesc) void {
            var handler = desc.handler;
            handler.deinit(Ctx.allocator(ctx), ctx, roc_host, &self.pending_roc_metrics);
        }

        /// Clears active events while retaining bounded storage where the type promises reuse.
        pub fn clearActiveEvents(self: *Self, ctx: Ctx.Handle) RocHostRequiredError!void {
            const roc_host = self.roc_host orelse {
                if (self.active_events.items.len != 0) return RocHostRequiredError.MissingRocHost;
                return;
            };
            for (self.active_events.items) |desc| {
                self.deinitActiveEventDesc(ctx, roc_host, desc);
            }
            self.active_events.items.len = 0;
        }

        /// Clears signal cache while retaining bounded storage where the type promises reuse.
        pub fn clearSignalCache(self: *Self, ctx: Ctx.Handle) RocHostRequiredError!void {
            const roc_host = self.roc_host orelse {
                if (self.signal_cache.items.len != 0) return RocHostRequiredError.MissingRocHost;
                return;
            };
            for (self.signal_cache.items) |*slot| {
                slot.deinit(ctx, roc_host, &self.pending_roc_metrics);
            }
            self.signal_cache.items.len = 0;
        }

        /// Clears states while retaining bounded storage where the type promises reuse.
        pub fn clearStates(self: *Self, ctx: Ctx.Handle) RocHostRequiredError!void {
            const roc_host = self.roc_host orelse {
                for (self.states.items) |state| {
                    if (state.isActive()) return RocHostRequiredError.MissingRocHost;
                }
                self.states.items.len = 0;
                self.state_indexes_by_node_id.items.len = 0;
                return;
            };
            for (self.states.items) |*state| {
                if (!state.isActive()) continue;
                state.retire(ctx, roc_host, &self.pending_roc_metrics);
            }
            self.states.items.len = 0;
            self.state_indexes_by_node_id.items.len = 0;
        }

        fn ensureStateIndexSlot(self: *Self, ctx: Ctx.Handle, node_id: u64) *?usize {
            const allocator = Ctx.allocator(ctx);
            const index: usize = @intCast(node_id);
            while (self.state_indexes_by_node_id.items.len <= index) {
                self.state_indexes_by_node_id.append(allocator, null) catch @panic("out of memory");
            }
            return &self.state_indexes_by_node_id.items[index];
        }

        fn recordStateCellIndex(self: *Self, ctx: Ctx.Handle, node_id: u64, index: usize) void {
            const slot = self.ensureStateIndexSlot(ctx, node_id);
            if (slot.* != null) @panic("state cell index already existed for node id");
            slot.* = index;
        }

        fn clearStateCellIndex(self: *Self, node_id: u64, expected: usize) void {
            if (node_id >= self.state_indexes_by_node_id.items.len) @panic("state cell index clear referenced an unknown node id");
            const slot = &self.state_indexes_by_node_id.items[@intCast(node_id)];
            const existing = slot.* orelse @panic("state cell index clear missed its node id");
            if (existing != expected) @panic("state cell index clear referenced the wrong state index");
            slot.* = null;
        }

        fn clearEachRowSites(self: *Self, allocator: std.mem.Allocator) void {
            if (self.positions) |*positions| positions.deinit();
            self.positions = null;
            each_runtime.clearSites(allocator, &self.each_row_sites, &self.each_row_site_indexes, &self.each_row_memberships_by_scope_id);
            if (self.rows_store) |*store| store.deinit();
            self.rows_store = null;
            self.rows_site_ids.deinit(allocator);
            self.rows_site_ids = .empty;
        }

        fn rowsStore(self: *Self, allocator: std.mem.Allocator) *rows_site_store.Store {
            if (self.rows_store == null) self.rows_store = rows_site_store.Store.init(allocator);
            return &self.rows_store.?;
        }

        fn deinitEachGenerationOwnership(self: *Self, allocator: std.mem.Allocator, ctx: Ctx.Handle, roc_host: *abi.RocHost) void {
            if (self.active_each_candidate_bindings != null or self.active_each_candidate_inputs != null or self.active_each_candidate_generation != null or self.active_each_candidate_rows_site_id != null or self.active_each_prepared_bindings != null or self.active_each_prepared_generations != null) @panic("each generation ownership cleared during active reconciliation");

            self.committed_row_bindings.deinit(allocator);
            self.row_handle_registry.deinit(allocator);
            self.row_handle_registry = .init();

            var generations = self.each_generations.valueIterator();
            while (generations.next()) |generation_ptr| {
                const generation = generation_ptr.*;
                generation.deinit(allocator, ctx, roc_host, &self.pending_roc_metrics);
                allocator.destroy(generation);
            }
            self.each_generations.deinit(allocator);
            self.each_generations = .{};
            self.each_generation_ids_by_site_index.deinit(allocator);
            self.each_generation_ids_by_site_index = .empty;
            self.each_generation_ids_by_rows_site.deinit(allocator);
            self.each_generation_ids_by_rows_site = .empty;
        }

        fn ensureEachRowSiteIndex(self: *Self, allocator: std.mem.Allocator, parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal) usize {
            return each_runtime.ensureSiteIndex(allocator, &self.each_row_sites, &self.each_row_site_indexes, parent_scope_id, site_ordinal);
        }

        fn activeEachRowSiteIndex(self: *Self, parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal) ?usize {
            return each_runtime.activeSiteIndex(&self.each_row_site_indexes, parent_scope_id, site_ordinal);
        }

        fn appendEachRowToSiteIndex(self: *Self, allocator: std.mem.Allocator, site_index: usize, scope_id: u64, key_hash: u64) void {
            each_runtime.appendRowToSiteIndex(allocator, &self.each_row_sites, &self.each_row_memberships_by_scope_id, site_index, ids.ScopeId.fromRaw(scope_id), key_hash);
        }

        fn removeEachRowFromSiteIndex(self: *Self, scope_id: u64, key_hash: u64) void {
            var row_keys = EachRowScopeKeyLookup{ .engine = self };
            each_runtime.removeRowFromSiteIndex(&self.each_row_sites, &self.each_row_memberships_by_scope_id, ids.ScopeId.fromRaw(scope_id), key_hash, &row_keys);
        }

        /// Performs deactivate state inside the shared engine while preserving transaction and changed-set invariants.
        pub fn deactivateState(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, node_id: u64) void {
            const state_index = self.stateIndexByNodeId(node_id) orelse return;
            const state = &self.states.items[state_index];
            state.retire(ctx, roc_host, &self.pending_roc_metrics);
            self.clearStateCellIndex(node_id, state_index);
        }

        /// Clears scopes while retaining bounded storage where the type promises reuse.
        pub fn clearScopes(self: *Self, ctx: Ctx.Handle) RocHostRequiredError!void {
            if (self.roc_host) |roc_host| {
                for (self.scopes.items) |*scope| {
                    if (!scope.lifecycle.isActive()) continue;
                    deinitHostScopeStep(&scope.step);
                }
                self.deinitEachGenerationOwnership(Ctx.allocator(ctx), ctx, roc_host);
            } else if (self.scopes.items.len != 0 or self.each_generations.count() != 0 or self.committed_row_bindings.entries.count() != 0) {
                return RocHostRequiredError.MissingRocHost;
            }
            self.scopes.items.len = 0;
            self.has_inactive_scopes = false;
            self.clearEachRowSites(Ctx.allocator(ctx));
        }

        /// Performs cleanup event count inside the shared engine while preserving transaction and changed-set invariants.
        pub fn cleanupEventCount(self: *const Self, name: []const u8) u64 {
            return effects_runtime.cleanupEventCount(self.cleanup_events.items, name);
        }

        /// Returns active interval record count by period from the maintained active-runtime indexes.
        pub fn activeIntervalRecordCountByPeriod(self: *const Self, period_ms: u64) u64 {
            return effects_runtime.activeIntervalRecordCountByPeriod(self.active_signal_graph.items, period_ms);
        }

        /// Returns active interval record by token from the maintained active-runtime indexes.
        pub fn activeIntervalRecordByToken(self: *Self, source_token: HostSignalToken) ?*HostSignalRecord {
            const record = self.active_stream.signalRecordByToken(source_token) orelse return null;
            if (self.activeSignalRecordId(record) == null) return null;
            return if (record.intervalSource() != null) record else null;
        }

        /// Returns active interval source token by runtime token from the maintained active-runtime indexes.
        pub fn activeIntervalSourceTokenByRuntimeToken(self: *Self, token: u64) ?HostSignalToken {
            return effects_runtime.activeIntervalSourceTokenByRuntimeToken(&self.active_intervals, ids.IntervalToken.fromRaw(token));
        }

        /// Returns dense source ids for the validated event route without rediscovering dependencies.
        pub fn sourceSignalIdsForEvent(self: *Self, event_id: u64) EventLookupError![]const u64 {
            return active_graph.sourceSignalIdsForEvent(self.signal_event_routes.items, event_id);
        }

        /// Performs event payload descriptor inside the shared engine while preserving transaction and changed-set invariants.
        pub fn eventPayloadDescriptor(self: *Self, event_id: u64) EventLookupError!BoundaryPayloadDescriptor {
            return active_graph.eventPayloadDescriptor(self.event_descriptors.items, event_id);
        }

        /// Returns dense signal ids associated with for state from maintained indexes.
        pub fn signalIdsForState(self: *Self, state_id: u64) SignalLookupError![]const u64 {
            return active_graph.signalIdsForState(self.signal_routes.items, state_id);
        }

        /// Performs dependent signal ids for signal inside the shared engine while preserving transaction and changed-set invariants.
        pub fn dependentSignalIdsForSignal(self: *Self, signal_id: u64) SignalLookupError![]const u64 {
            return active_graph.dependentSignalIdsForSignal(self.signal_dependents.items, signal_id);
        }

        /// Returns a signal's topological rank without traversing the dependency graph.
        pub fn signalRank(self: *Self, signal_id: u64) SignalLookupError!u64 {
            return active_graph.signalRank(self.signal_descriptors.items, signal_id);
        }

        /// Returns next dirty signal generation from maintained local structure without a full-tree scan.
        pub fn nextDirtySignalGeneration(self: *Self) u64 {
            if (self.dirty_signal_generation == std.math.maxInt(u64)) {
                @panic("host dirty signal generation overflowed");
            }
            self.dirty_signal_generation += 1;
            self.identity_reuse_barrier = self.dirty_signal_generation;
            return self.dirty_signal_generation;
        }

        /// Returns active signal rank from the maintained active-runtime indexes.
        pub fn activeSignalRank(self: *Self, record_id: u64) u64 {
            return active_graph.rank(HostSignalRecord, self.active_signal_graph.items, record_id);
        }

        /// Performs dependent active signal record ids inside the shared engine while preserving transaction and changed-set invariants.
        pub fn dependentActiveSignalRecordIds(self: *Self, record_id: u64) []const u64 {
            return active_graph.dependentIds(HostSignalRecord, self.active_signal_graph.items, record_id);
        }

        fn scratchDirtyActiveSignalRecordIdsForSources(self: *Self, ctx: Ctx.Handle, dirty_source_node_ids: []const u64) []const u64 {
            return self.scratch.dirty_active_records.collectForSources(
                HostSignalRecord,
                Ctx.allocator(ctx),
                self.active_signal_graph.items,
                self.active_source_signal_routes.items,
                dirty_source_node_ids,
            );
        }

        fn scratchDirtyActiveSignalRecordIdsForRoots(self: *Self, ctx: Ctx.Handle, root_record_ids: []const u64) []const u64 {
            return self.scratch.dirty_active_records.collectForRoots(
                HostSignalRecord,
                Ctx.allocator(ctx),
                self.active_signal_graph.items,
                root_record_ids,
            );
        }

        /// Records derived call in the metrics or lifecycle state owned by this operation.
        pub fn recordDerivedCall(self: *Self) void {
            var metrics = self.pending_roc_metrics;
            metrics.bump(.derived_calls_into_roc, 1);
            self.pending_roc_metrics = metrics;
        }

        /// Records signal prune in the metrics or lifecycle state owned by this operation.
        pub fn recordSignalPrune(self: *Self) void {
            var metrics = self.pending_roc_metrics;
            metrics.bump(.propagation_prunes, 1);
            self.pending_roc_metrics = metrics;
        }

        /// Performs clone cached signal value inside the shared engine while preserving transaction and changed-set invariants.
        pub fn cloneCachedSignalValue(self: *Self, ctx: Ctx.Handle, cache_slot: *const HostSignalCacheSlot) HostValue {
            _ = self;
            debugPhase(ctx, .clone_cached_signal);
            return switch (cache_slot.*) {
                .absent => @panic("cached signal expression value was requested before initialization"),
                .present => |cached| Ctx.cloneHostValue(ctx, cached.value),
            };
        }

        /// Performs update dirty signal expr cache inside the shared engine while preserving transaction and changed-set invariants.
        pub fn updateDirtySignalExprCache(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, cache_slot: *HostSignalCacheSlot, value: HostValue, cap: HostValueCapability) HostSignalEvalResult {
            switch (cache_slot.*) {
                .absent => {
                    debugPhase(ctx, .dirty_cache_initialize);
                    return .{
                        .value = self.replaceSignalExprCacheAndClone(ctx, cache_slot, roc_host, value, cap),
                        .changed = true,
                    };
                },
                .present => |*cached| {
                    debugPhase(ctx, .dirty_cache_compare);
                    const values_equal = cached.valueEquals(ctx, roc_host, value);
                    if (values_equal) {
                        debugPhase(ctx, .dirty_cache_drop_equal);
                        cached.dropIncoming(ctx, roc_host, value);
                        self.recordSignalPrune();
                        debugPhase(ctx, .dirty_cache_clone_equal);
                        return .{ .value = Ctx.cloneHostValue(ctx, cached.value), .changed = false };
                    }

                    debugPhase(ctx, .dirty_cache_replace);
                    cached.replaceValue(ctx, roc_host, value);
                    debugPhase(ctx, .dirty_cache_clone_changed);
                    return .{ .value = Ctx.cloneHostValue(ctx, cached.value), .changed = true };
                },
            }
        }

        fn updatePreparedDirtySignalExprCache(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, overlay: *signal_records.PreparedCacheUpdates, cache_slot: *HostSignalCacheSlot, value: HostValue, cap: HostValueCapability) HostSignalEvalResult {
            return switch (overlay.readSlot(cache_slot).*) {
                .absent => blk: {
                    overlay.stageAssumeCapacity(cache_slot, value, cap, &self.pending_roc_metrics);
                    break :blk .{ .value = self.cloneCachedSignalValue(ctx, overlay.readSlot(cache_slot)), .changed = true };
                },
                .present => |*cached| blk: {
                    if (cached.valueEquals(ctx, roc_host, value)) {
                        cached.dropIncoming(ctx, roc_host, value);
                        overlay.propagation_prunes += 1;
                        break :blk .{ .value = Ctx.cloneHostValue(ctx, cached.value), .changed = false };
                    }
                    overlay.stageAssumeCapacity(cache_slot, value, cap, &self.pending_roc_metrics);
                    break :blk .{ .value = self.cloneCachedSignalValue(ctx, overlay.readSlot(cache_slot)), .changed = true };
                },
            };
        }

        fn rememberPreparedDirtySignalResult(_: *Self, overlay: *signal_records.PreparedCacheUpdates, record: *HostSignalRecord, dirty_generation: u64, result: HostSignalEvalResult) HostSignalEvalResult {
            overlay.rememberResultAssumeCapacity(signal_records.EvaluationKey.fromRecord(record), dirty_generation, result.changed);
            return result;
        }

        /// Publishes a prepared overlay: every staged cache replacement becomes
        /// the live value, every memoized evaluation becomes a durable dirty
        /// stamp, and the overlay's derived-call and prune counts reach the
        /// metrics. Until this runs the transaction is invisible, so a caller
        /// that abandons a transaction simply never calls this and destroys the
        /// overlay instead. It may be called at most once for a given overlay,
        /// and the overlay must still be destroyed afterwards so that the values
        /// the commit displaced are released. Advancing
        /// `dirty_signal_generation` is the caller's business, not this
        /// function's, because a transaction publishes render and structural
        /// work alongside these caches.
        pub fn commitPreparedDirtySignalCaches(self: *Self, overlay: *signal_records.PreparedCacheUpdates) void {
            overlay.commit();
            for (overlay.results.items) |entry| {
                const record = entry.key.record();
                record.last_dirty_generation = entry.dirty_generation;
                record.last_dirty_changed = entry.changed;
            }
            var metrics = self.pending_roc_metrics;
            metrics.bump(.derived_calls_into_roc, overlay.derived_calls);
            metrics.bump(.propagation_prunes, overlay.propagation_prunes);
            metrics.bump(.selector_members_dirtied, overlay.selector_members_dirtied);
            self.pending_roc_metrics = metrics;
        }

        fn reserveCacheDescriptorVector(
            self: *Self,
            allocator: std.mem.Allocator,
            replacement: *const HostNodeDescriptorStream,
            overlay: *signal_records.PreparedCacheUpdates,
            comptime field_name: []const u8,
        ) std.mem.Allocator.Error!void {
            const active = &@field(self.active_stream, field_name);
            const incoming = &@field(replacement.*, field_name);
            const Descriptor = @TypeOf(active.items[0]);
            const old_base = @intFromPtr(active.items.ptr);
            const old_len = active.items.len;
            try active.ensureUnusedCapacity(allocator, incoming.items.len);
            overlay.rebaseDescriptorCacheSlotsAssumeCapacity(Descriptor, old_base, old_len, active.items);
        }

        /// Cache journals are prepared before structural publication capacity.
        /// Rebind them immediately after every potentially relocating reserve,
        /// including when a later reserve fails and the journal must roll back.
        fn reserveCacheBearingDescriptorPublication(self: *Self, allocator: std.mem.Allocator, replacement: *const HostNodeDescriptorStream, overlay: *signal_records.PreparedCacheUpdates) std.mem.Allocator.Error!void {
            try self.reserveCacheDescriptorVector(allocator, replacement, overlay, "signal_text_nodes");
            try self.reserveCacheDescriptorVector(allocator, replacement, overlay, "signal_text_attrs");
            try self.reserveCacheDescriptorVector(allocator, replacement, overlay, "signal_custom_text_attrs");
            try self.reserveCacheDescriptorVector(allocator, replacement, overlay, "signal_optional_custom_text_attrs");
            try self.reserveCacheDescriptorVector(allocator, replacement, overlay, "signal_custom_bool_attrs");
            try self.reserveCacheDescriptorVector(allocator, replacement, overlay, "signal_bool_attrs");
            try self.reserveCacheDescriptorVector(allocator, replacement, overlay, "on_changes");
            try self.reserveCacheDescriptorVector(allocator, replacement, overlay, "whens");
            try self.reserveCacheDescriptorVector(allocator, replacement, overlay, "eaches");
        }

        /// Performs update dirty signal cache inside the shared engine while preserving transaction and changed-set invariants.
        pub fn updateDirtySignalCache(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, cache_slot: *HostSignalCacheSlot, value: HostValue, cap: HostValueCapability) bool {
            switch (cache_slot.*) {
                .absent => {
                    cache_slot.replace(ctx, roc_host, &self.pending_roc_metrics, value, cap);
                    return true;
                },
                .present => |*cached| {
                    const values_equal = cached.valueEquals(ctx, roc_host, value);
                    if (values_equal) {
                        cached.dropIncoming(ctx, roc_host, value);
                        self.recordSignalPrune();
                        return false;
                    }

                    cache_slot.replaceValue(ctx, roc_host, value);
                    return true;
                },
            }
        }

        /// Performs clone memoized dirty signal result inside the shared engine while preserving transaction and changed-set invariants.
        pub fn cloneMemoizedDirtySignalResult(self: *Self, ctx: Ctx.Handle, record: *HostSignalRecord, dirty_generation: u64) ?HostSignalEvalResult {
            if (record.last_dirty_generation != dirty_generation) return null;

            const cache_slot = record.cachedSlot() orelse return null;
            return .{
                .value = self.cloneCachedSignalValue(ctx, cache_slot),
                .changed = record.last_dirty_changed,
            };
        }

        /// Performs remember dirty signal result inside the shared engine while preserving transaction and changed-set invariants.
        pub fn rememberDirtySignalResult(_: *Self, record: *HostSignalRecord, dirty_generation: u64, result: HostSignalEvalResult) HostSignalEvalResult {
            record.last_dirty_generation = dirty_generation;
            record.last_dirty_changed = result.changed;
            return result;
        }

        /// Performs host signal record capability inside the shared engine while preserving transaction and changed-set invariants.
        pub fn hostSignalRecordCapability(_: *Self, ctx: Ctx.Handle, record: *const HostSignalRecord) HostValueCapability {
            return record.capability(Ctx, ctx);
        }

        /// Performs host signal binding capability inside the shared engine while preserving transaction and changed-set invariants.
        pub fn hostSignalBindingCapability(self: *Self, ctx: Ctx.Handle, signal: *const HostSignalBinding) HostValueCapability {
            return self.hostSignalRecordCapability(ctx, signal.record);
        }

        fn hostSignalRecordCapabilityWithProvisionalStates(self: *Self, ctx: Ctx.Handle, record: *const HostSignalRecord, provisional_states: []const HostState) HostValueCapability {
            switch (record.payload) {
                .ref => |node_id| {
                    for (provisional_states) |state| if (state.state_id == node_id) return state.activePayloadConst().cell.cap;
                },
                else => {},
            }
            return self.hostSignalRecordCapability(ctx, record);
        }

        fn dropHostSignalRecordValueWithProvisionalStates(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, record: *const HostSignalRecord, value: HostValue, provisional_states: []const HostState) void {
            const cap = self.hostSignalRecordCapabilityWithProvisionalStates(ctx, record, provisional_states);
            callHostValueToUnitWithCapability(ctx, roc_host, cap, hv.hostValueCapabilityDrop(cap), value);
        }

        /// Performs drop host signal record value inside the shared engine while preserving transaction and changed-set invariants.
        pub fn dropHostSignalRecordValue(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, record: *const HostSignalRecord, value: HostValue) void {
            const cap = self.hostSignalRecordCapability(ctx, record);
            callHostValueToUnitWithCapability(ctx, roc_host, cap, hv.hostValueCapabilityDrop(cap), value);
        }

        /// Ensures state from desc capacity or state before publication can begin.
        pub fn ensureStateFromDesc(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, desc: HostNodeStateDesc) void {
            if (self.stateIndexByNodeId(desc.node_id.raw()) != null) return;

            const initial = erased_calls.callValueInitThunk(roc_host, desc.initial.toAbi());
            var cell = HostValueCell.initRetained(initial, desc.cap, &self.pending_roc_metrics);
            const next_state = HostState.initActive(desc.node_id.raw(), cell, 0);
            const state_index = blk: {
                for (self.states.items, 0..) |state, index| {
                    if (state.isActive()) continue;
                    self.states.items[index] = next_state;
                    break :blk index;
                }
                const index = self.states.items.len;
                self.states.append(Ctx.allocator(ctx), next_state) catch {
                    cell.deinit(ctx, roc_host, &self.pending_roc_metrics);
                    @panic("out of memory");
                };
                break :blk index;
            };
            self.recordStateCellIndex(ctx, desc.node_id.raw(), state_index);
        }

        fn signalRecordByTokenForStream(self: *Self, stream: *HostNodeDescriptorStream, token: HostSignalToken) ?*HostSignalRecord {
            if (stream.signalRecordByToken(token)) |record| return record;
            if (stream != &self.active_stream) return self.active_stream.signalRecordByToken(token);
            return null;
        }

        fn signalRecordByKeyedSelectForStream(self: *Self, stream: *HostNodeDescriptorStream, identity: signal_records.KeyedSelectIdentity) ?*HostSignalRecord {
            if (stream.signalRecordByKeyedSelectIdentity(identity)) |record| return record;
            if (stream != &self.active_stream) return self.active_stream.signalRecordByKeyedSelectIdentity(identity);
            return null;
        }

        fn retainExistingSignalRecordForStream(self: *Self, allocator: std.mem.Allocator, stream: *HostNodeDescriptorStream, token: HostSignalToken, expected_tag: std.meta.Tag(HostSignalRecordPayload)) ?*HostSignalRecord {
            const record = self.signalRecordByTokenForStream(stream, token) orelse return null;
            validateExistingSignalRecord(record, expected_tag);
            stream.rememberSignalRecord(allocator, record);
            return record.retain();
        }

        /// Performs bind node signal expr inside the shared engine while preserving transaction and changed-set invariants.
        pub fn bindNodeSignalExpr(self: *Self, allocator: std.mem.Allocator, stream: *HostNodeDescriptorStream, expr: abi.NodeSignalExpr, binder_stack: []const HostBinderBinding) *HostSignalRecord {
            const binding = ImmediateSignalRecordCtx{ .engine = self, .allocator = allocator, .stream = stream };
            return self.bindSignalExprViewWith(ImmediateSignalRecordCtx, binding, abi_view.SignalExpr.fromAbi(expr), binder_stack) catch @panic("out of memory");
        }

        const ImmediateSignalRecordCtx = struct {
            engine: *Self,
            allocator: std.mem.Allocator,
            stream: *HostNodeDescriptorStream,

            fn retainExisting(self: @This(), token: HostSignalToken, expected_tag: std.meta.Tag(HostSignalRecordPayload)) error{OutOfMemory}!?*HostSignalRecord {
                return self.engine.retainExistingSignalRecordForStream(self.allocator, self.stream, token, expected_tag);
            }

            fn retainExistingKeyed(self: @This(), identity: signal_records.KeyedSelectIdentity) error{OutOfMemory}!?*HostSignalRecord {
                const record = self.engine.signalRecordByKeyedSelectForStream(self.stream, identity) orelse return null;
                validateExistingSignalRecord(record, .keyed_select);
                self.stream.rememberSignalRecord(self.allocator, record);
                return record.retain();
            }

            fn init(self: @This(), payload: HostSignalRecordPayload) error{OutOfMemory}!*HostSignalRecord {
                return HostSignalRecord.tryInit(self.allocator, payload);
            }

            fn remember(self: @This(), record: *HostSignalRecord) error{OutOfMemory}!void {
                self.stream.rememberSignalRecord(self.allocator, record);
            }
        };

        fn signalExprViewMatchesRecord(expr: abi_view.SignalExpr, binder_stack: []const HostBinderBinding, record: *HostSignalRecord) bool {
            return switch (expr) {
                .ref => |payload| switch (record.payload) {
                    .ref => |node_id| node_id == resolveNodeBinderRef(binder_stack, payload.binder.callable),
                    else => false,
                },
                .keyed_select => |payload| if (record.keyedSelectIdentity()) |identity|
                    identity.site == payload.site and identity.row_handle.raw() == payload.row_handle
                else
                    false,
                .const_value => |payload| record.token() == payload.token.callable,
                .map => |payload| record.token() == payload.token.callable,
                .map2 => |payload| record.token() == payload.token.callable,
                .select => |payload| record.token() == payload.token.callable,
                .combine => |payload| record.token() == payload.token.callable,
                .interval_source => |payload| record.token() == payload.token.callable,
                .entropy_seed_source => |payload| record.token() == payload.token.callable,
                .location_source => |payload| record.token() == payload.token.callable,
                .online_source => |payload| record.token() == payload.token.callable,
                .row_source => |payload| record.token() == payload.token.callable,
                .visibility_source => |payload| record.token() == payload.token.callable,
                .storage_source => |payload| record.token() == payload.token.callable,
            };
        }

        fn validateKeyedSelectorRow(self: *Self, row_handle: row_handles.RowHandleId, key: []const u8) void {
            if (!self.row_handle_registry.contains(row_handle)) @panic("keyed selector row handle was not active");
            if (self.active_each_candidate_inputs) |inputs| {
                const bindings = self.active_each_candidate_bindings orelse @panic("candidate each inputs lacked its binding overlay");
                if (bindings != &inputs.candidate_bindings) @panic("candidate each key arena did not match its binding overlay");
                if (bindings.candidate.get(row_handle)) |entry| {
                    const binding = entry.binding orelse @panic("keyed selector referenced a retired candidate row");
                    if (binding.generation_id != inputs.generation.id) @panic("keyed selector candidate generation did not match its key arena");
                    const locator = bindings.keyLocator(row_handle) orelse @panic("keyed selector candidate lacked its key locator");
                    const candidate_key = inputs.candidateKey(locator) orelse @panic("keyed selector candidate key locator was invalid");
                    if (!std.mem.eql(u8, candidate_key, key)) @panic("keyed selector key did not match its candidate row handle");
                    return;
                }
            }
            if (self.active_each_candidate_bindings) |bindings| if (bindings.candidate.contains(row_handle))
                @panic("keyed selector candidate binding had no matching active key arena");
            const store = if (self.rows_store) |*rows_store| rows_store else @panic("keyed selector row handle had no row store");
            const location = store.findRowHandle(row_handle.raw()) orelse @panic("keyed selector row handle was not indexed");
            const row = store.getRowConst(location.site_id, location.row_id) catch @panic("keyed selector row handle referenced a stale row");
            if (!std.mem.eql(u8, row.key, key)) @panic("keyed selector key did not match its row handle");
        }

        fn bindSignalExprViewWith(self: *Self, comptime Binding: type, binding: Binding, expr: abi_view.SignalExpr, binder_stack: []const HostBinderBinding) error{OutOfMemory}!*HostSignalRecord {
            const allocator = binding.allocator;
            return switch (expr) {
                .ref => |payload| blk: {
                    const token = payload.binder.callable;
                    const node_id = resolveNodeBinderRef(binder_stack, token);
                    break :blk try binding.init(.{ .ref = node_id });
                },
                .const_value => |payload| blk: {
                    const token = payload.token.callable;
                    if (try binding.retainExisting(token, .const_value)) |record| {
                        break :blk record;
                    }

                    const record = try binding.init(.{ .const_value = .{
                        .init = retainHostCallable(payload.init, &self.pending_roc_metrics),
                        .cap = retainHostValueCapability(payload.capability, &self.pending_roc_metrics),
                    } });
                    try binding.remember(record);
                    break :blk record;
                },
                .row_source => |payload| blk: {
                    const token = payload.token.callable;
                    if (try binding.retainExisting(token, .row_source)) |record| {
                        const existing = switch (record.payload) {
                            .row_source => |row| row,
                            else => unreachable,
                        };
                        if (existing.row_handle.raw() != payload.row_handle) @panic("row source identity was reused with a different row handle");
                        break :blk record;
                    }

                    const record = try binding.init(.{ .row_source = .{
                        .row_handle = row_handles.RowHandleId.fromRaw(payload.row_handle),
                        .identity = retainHostCallable(InitializerCallable.fromAbi(payload.token.callable), &self.pending_roc_metrics),
                        .cap = retainHostValueCapability(payload.capability, &self.pending_roc_metrics),
                    } });
                    try binding.remember(record);
                    break :blk record;
                },
                .map => |payload| blk: {
                    const token = payload.token.callable;
                    if (try binding.retainExisting(token, .map)) |record| {
                        break :blk record;
                    }

                    const input = try self.bindSignalExprViewWith(Binding, binding, abi_view.SignalExpr.fromAbi(payload.input.*), binder_stack);
                    var input_unbound = true;
                    errdefer if (input_unbound) if (comptime @hasDecl(Binding, "release")) binding.release(input);
                    input_unbound = false;
                    const record = try binding.init(.{ .map = .{
                        .input = input,
                        .transform = retainHostCallable(payload.transform, &self.pending_roc_metrics),
                        .cap = retainHostValueCapability(payload.capability, &self.pending_roc_metrics),
                    } });
                    try binding.remember(record);
                    break :blk record;
                },
                .map2 => |payload| blk: {
                    const token = payload.token.callable;
                    if (try binding.retainExisting(token, .map2)) |record| {
                        break :blk record;
                    }

                    const left = try self.bindSignalExprViewWith(Binding, binding, abi_view.SignalExpr.fromAbi(payload.left.*), binder_stack);
                    var left_unbound = true;
                    errdefer if (left_unbound) if (comptime @hasDecl(Binding, "release")) binding.release(left);
                    const right = try self.bindSignalExprViewWith(Binding, binding, abi_view.SignalExpr.fromAbi(payload.right.*), binder_stack);
                    var right_unbound = true;
                    errdefer if (right_unbound) if (comptime @hasDecl(Binding, "release")) binding.release(right);
                    left_unbound = false;
                    right_unbound = false;
                    const record = try binding.init(.{ .map2 = .{
                        .left = left,
                        .right = right,
                        .transform = retainHostCallable(payload.transform, &self.pending_roc_metrics),
                        .cap = retainHostValueCapability(payload.capability, &self.pending_roc_metrics),
                    } });
                    try binding.remember(record);
                    break :blk record;
                },
                .select => |payload| blk: {
                    const token = payload.token.callable;
                    if (try binding.retainExisting(token, .select)) |record| {
                        break :blk record;
                    }

                    const input = try self.bindSignalExprViewWith(Binding, binding, abi_view.SignalExpr.fromAbi(payload.input.*), binder_stack);
                    var input_unbound = true;
                    errdefer if (input_unbound) if (comptime @hasDecl(Binding, "release")) binding.release(input);
                    const key = try allocator.dupe(u8, payload.key.asSlice());
                    input_unbound = false;
                    const record = try binding.init(.{ .select = .{
                        .input = input,
                        .key = key,
                        .input_read = retainHostTextRead(payload.input_read, &self.pending_roc_metrics),
                        .false_init = retainHostCallable(payload.false_init, &self.pending_roc_metrics),
                        .true_init = retainHostCallable(payload.true_init, &self.pending_roc_metrics),
                        .cap = retainHostValueCapability(payload.capability, &self.pending_roc_metrics),
                    } });
                    try binding.remember(record);
                    break :blk record;
                },
                .keyed_select => |payload| blk: {
                    const identity = signal_records.KeyedSelectIdentity{
                        .site = payload.site,
                        .row_handle = row_handles.RowHandleId.fromRaw(payload.row_handle),
                    };
                    self.validateKeyedSelectorRow(identity.row_handle, payload.key.asSlice());
                    if (try binding.retainExistingKeyed(identity)) |record| {
                        const existing = &record.payload.keyed_select;
                        if (!signalExprViewMatchesRecord(abi_view.SignalExpr.fromAbi(payload.input.*), binder_stack, existing.input)) @panic("keyed selector identity was reused with a different input");
                        if (!std.mem.eql(u8, existing.key, payload.key.asSlice())) @panic("keyed selector identity was reused with a different key");
                        if (!std.meta.eql(existing.input_read, payload.input_read)) @panic("keyed selector identity was reused with a different key reader");
                        if (retained_values.hostSignalTokenFromCallable(existing.false_init.toAbi()) != retained_values.hostSignalTokenFromCallable(payload.false_init.toAbi())) @panic("keyed selector identity was reused with a different false initializer");
                        if (retained_values.hostSignalTokenFromCallable(existing.true_init.toAbi()) != retained_values.hostSignalTokenFromCallable(payload.true_init.toAbi())) @panic("keyed selector identity was reused with a different true initializer");
                        if (!std.meta.eql(existing.cap, payload.capability)) @panic("keyed selector identity was reused with a different capability");
                        break :blk record;
                    }
                    const input = try self.bindSignalExprViewWith(Binding, binding, abi_view.SignalExpr.fromAbi(payload.input.*), binder_stack);
                    var input_unbound = true;
                    errdefer if (input_unbound) if (comptime @hasDecl(Binding, "release")) binding.release(input);
                    const key = try allocator.dupe(u8, payload.key.asSlice());
                    input_unbound = false;
                    const record = try binding.init(.{ .keyed_select = .{
                        .keyed_identity = identity,
                        .input = input,
                        .key = key,
                        .input_read = retainHostTextRead(payload.input_read, &self.pending_roc_metrics),
                        .false_init = retainHostCallable(payload.false_init, &self.pending_roc_metrics),
                        .true_init = retainHostCallable(payload.true_init, &self.pending_roc_metrics),
                        .cap = retainHostValueCapability(payload.capability, &self.pending_roc_metrics),
                    } });
                    break :blk record;
                },
                .combine => |payload| blk: {
                    const token = payload.token.callable;
                    if (try binding.retainExisting(token, .combine)) |record| {
                        break :blk record;
                    }

                    const children = try allocator.alloc(*HostSignalRecord, payload.children.len);
                    var initialized_children: usize = 0;
                    var children_unbound = true;
                    errdefer if (children_unbound) {
                        if (comptime @hasDecl(Binding, "release")) for (children[0..initialized_children]) |child| binding.release(child);
                        allocator.free(children);
                    };
                    for (payload.children, children) |child, *dest| {
                        dest.* = try self.bindSignalExprViewWith(Binding, binding, abi_view.SignalExpr.fromAbi(child), binder_stack);
                        initialized_children += 1;
                    }
                    children_unbound = false;
                    const record = try binding.init(.{ .combine = .{
                        .children = children,
                        .transform = retainHostCallable(payload.transform, &self.pending_roc_metrics),
                        .cap = retainHostValueCapability(payload.capability, &self.pending_roc_metrics),
                    } });
                    try binding.remember(record);
                    break :blk record;
                },
                .interval_source => |payload| blk: {
                    const token = payload.token.callable;
                    if (try binding.retainExisting(token, .interval_source)) |record| {
                        break :blk record;
                    }

                    const record = try binding.init(.{ .interval_source = .{
                        .period_ms = payload.period_ms,
                        .initial = retainHostCallable(payload.initial, &self.pending_roc_metrics),
                        .tick = retainHostCallable(payload.tick, &self.pending_roc_metrics),
                        .cap = retainHostValueCapability(payload.capability, &self.pending_roc_metrics),
                    } });
                    try binding.remember(record);
                    break :blk record;
                },
                .entropy_seed_source => |payload| blk: {
                    const token = payload.token.callable;
                    if (try binding.retainExisting(token, .entropy_seed_source)) |record| {
                        break :blk record;
                    }

                    const record = try binding.init(.{ .entropy_seed_source = .{
                        .payload_cap = retainHostValueCapability(payload.payload_capability, &self.pending_roc_metrics),
                        .from_payload = retainHostCallable(payload.from_payload, &self.pending_roc_metrics),
                        .cap = retainHostValueCapability(payload.capability, &self.pending_roc_metrics),
                    } });
                    try binding.remember(record);
                    break :blk record;
                },
                .location_source => |payload| blk: {
                    const token = payload.token.callable;
                    if (try binding.retainExisting(token, .location_source)) |record| {
                        break :blk record;
                    }

                    const record = try binding.init(.{ .location_source = .{
                        .payload_cap = retainHostValueCapability(payload.payload_capability, &self.pending_roc_metrics),
                        .from_payload = retainHostCallable(payload.from_payload, &self.pending_roc_metrics),
                        .cap = retainHostValueCapability(payload.capability, &self.pending_roc_metrics),
                    } });
                    try binding.remember(record);
                    break :blk record;
                },
                .visibility_source => |payload| blk: {
                    const token = payload.token.callable;
                    if (try binding.retainExisting(token, .visibility_source)) |record| {
                        break :blk record;
                    }

                    const record = try binding.init(.{ .visibility_source = .{
                        .payload_cap = retainHostValueCapability(payload.payload_capability, &self.pending_roc_metrics),
                        .from_payload = retainHostCallable(payload.from_payload, &self.pending_roc_metrics),
                        .cap = retainHostValueCapability(payload.capability, &self.pending_roc_metrics),
                    } });
                    try binding.remember(record);
                    break :blk record;
                },
                .online_source => |payload| blk: {
                    const token = payload.token.callable;
                    if (try binding.retainExisting(token, .online_source)) |record| {
                        break :blk record;
                    }

                    const record = try binding.init(.{ .online_source = .{
                        .payload_cap = retainHostValueCapability(payload.payload_capability, &self.pending_roc_metrics),
                        .from_payload = retainHostCallable(payload.from_payload, &self.pending_roc_metrics),
                        .cap = retainHostValueCapability(payload.capability, &self.pending_roc_metrics),
                    } });
                    try binding.remember(record);
                    break :blk record;
                },
                .storage_source => |payload| blk: {
                    const token = payload.token.callable;
                    if (try binding.retainExisting(token, .storage_source)) |record| {
                        break :blk record;
                    }

                    const key_copy = allocator.dupe(u8, payload.key.asSlice()) catch @panic("out of memory");
                    errdefer allocator.free(key_copy);
                    const record = try binding.init(.{ .storage_source = .{
                        .area = payload.area,
                        .key = key_copy,
                        .payload_cap = retainHostValueCapability(payload.payload_capability, &self.pending_roc_metrics),
                        .from_payload = retainHostCallable(payload.from_payload, &self.pending_roc_metrics),
                        .cap = retainHostValueCapability(payload.capability, &self.pending_roc_metrics),
                    } });
                    try binding.remember(record);
                    break :blk record;
                },
            };
        }

        /// Performs bind node signal inside the shared engine while preserving transaction and changed-set invariants.
        pub fn bindNodeSignal(self: *Self, allocator: std.mem.Allocator, stream: *HostNodeDescriptorStream, expr: abi.NodeSignalExpr, binder_stack: []const HostBinderBinding) HostSignalBinding {
            const record = self.bindNodeSignalExpr(allocator, stream, expr, binder_stack);
            var source_node_ids: shared_buffer.List(u64) = .empty;
            appendSignalRecordSourceNodeIds(allocator, &source_node_ids, record);
            return .{
                .record = record,
                .source_node_ids = source_node_ids.toOwnedSlice(allocator) catch @panic("out of memory"),
            };
        }

        /// Reads node id in scope subtree from the active descriptor stream using engine-owned identity.
        pub fn streamNodeIdInScopeSubtree(self: *Self, previous: *const HostNodeDescriptorStream, node_id: ids.NodeId, root_scope_id: ids.ScopeId) bool {
            const descriptor_index = previous.nodeDescriptorIndex(node_id) orelse return false;
            const ScopeSiteSlot = struct {
                kind: HostNodeScopeSiteKind,
                index: ?usize,
            };
            const scope_site_slots = [_]ScopeSiteSlot{
                .{ .kind = .component, .index = descriptor_index.scope_sites.component.get() },
                .{ .kind = .state, .index = descriptor_index.scope_sites.state.get() },
                .{ .kind = .when, .index = descriptor_index.scope_sites.when.get() },
                .{ .kind = .each, .index = descriptor_index.scope_sites.each.get() },
            };
            for (scope_site_slots) |slot| {
                const site_index = slot.index orelse continue;
                if (site_index >= previous.scope_sites.items.len) @panic("scope site descriptor index exceeded descriptor table");
                const site = previous.scope_sites.items[site_index];
                if (site.node_id != node_id or site.kind != slot.kind) @panic("scope site descriptor index pointed at the wrong node");
                if (self.scopeIsDescendantOrSelf(site.scope_id.raw(), root_scope_id.raw()) catch @panic("scope descriptor referenced an unknown parent scope")) return true;
            }
            return false;
        }

        /// Returns in scope subtree for an already indexed render node.
        pub fn renderNodeInScopeSubtree(self: *Self, stream: *const HostNodeDescriptorStream, node: HostRenderNode, root_scope_id: u64) bool {
            return self.scopeIsDescendantOrSelf(renderNodeScopeId(stream, node), root_scope_id) catch @panic("scope descriptor referenced an unknown parent scope");
        }

        /// Performs first render index in scope subtree inside the shared engine while preserving transaction and changed-set invariants.
        pub fn firstRenderIndexInScopeSubtree(self: *Self, stream: *const HostNodeDescriptorStream, root_scope_id: u64) ?usize {
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_render_scope, stream.render_nodes.items.len);
            for (stream.render_nodes.items, 0..) |node, index| {
                if (self.renderNodeInScopeSubtree(stream, node, root_scope_id)) return index;
            }
            return null;
        }

        /// Returns last render end index in scope subtree retained for observability or local structural traversal.
        pub fn lastRenderEndIndexInScopeSubtree(self: *Self, stream: *const HostNodeDescriptorStream, root_scope_id: u64) ?usize {
            var end_index: ?usize = null;
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_render_scope, stream.render_nodes.items.len);
            for (stream.render_nodes.items, 0..) |node, index| {
                if (self.renderNodeInScopeSubtree(stream, node, root_scope_id)) {
                    end_index = index + 1;
                }
            }
            return end_index;
        }

        /// Evaluates scope subtree has dirty structural source using explicit scope ownership rather than DOM position or content.
        pub fn scopeSubtreeHasDirtyStructuralSource(self: *Self, previous: *const HostNodeDescriptorStream, root_scope_id: u64, dirty_source_node_ids: []const u64) bool {
            if (dirty_source_node_ids.len == 0) return false;

            self.recordStreamNodesScannedBy(.stream_nodes_scanned_dirty_scope, previous.whens.items.len);
            for (previous.whens.items) |desc| {
                if (!self.streamNodeIdInScopeSubtree(previous, desc.node_id, ids.ScopeId.fromRaw(root_scope_id))) continue;
                if (sourceNodeIdsIntersect(desc.condition.source_node_ids, dirty_source_node_ids)) return true;
            }
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_dirty_scope, previous.eaches.items.len);
            for (previous.eaches.items) |desc| {
                if (!self.streamNodeIdInScopeSubtree(previous, desc.node_id, ids.ScopeId.fromRaw(root_scope_id))) continue;
                if (sourceNodeIdsIntersect(desc.items.source_node_ids, dirty_source_node_ids)) return true;
            }
            return false;
        }

        /// Performs clone host signal cache slot inside the shared engine while preserving transaction and changed-set invariants.
        pub fn cloneHostSignalCacheSlot(self: *Self, ctx: Ctx.Handle, slot: HostSignalCacheSlot, metrics: anytype) HostSignalCacheSlot {
            _ = self;
            return slot.cloneRetained(ctx, metrics);
        }

        /// Performs copy active scope subtree descriptors inside the shared engine while preserving transaction and changed-set invariants.
        pub fn copyActiveScopeSubtreeDescriptors(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, stream: *HostNodeDescriptorStream, root_scope_id: u64) void {
            const allocator = Ctx.allocator(ctx);
            const previous = &self.active_stream;
            const previous_render_base = self.firstRenderIndexInScopeSubtree(previous, root_scope_id);
            const next_render_base = stream.render_nodes.items.len;
            var copied_elem_ids: shared_buffer.List(u64) = .empty;
            defer copied_elem_ids.deinit(allocator);

            for (previous.render_nodes.items) |node| {
                const node_scope_id = renderNodeScopeId(previous, node);
                if (!(self.scopeIsDescendantOrSelf(node_scope_id, root_scope_id) catch @panic("scope descriptor referenced an unknown parent scope"))) continue;

                copied_elem_ids.append(allocator, node.elem_id.raw()) catch @panic("out of memory");
                switch (node.kind) {
                    .element => {
                        const desc = findElementDesc(previous, node.elem_id.raw()) orelse @panic("copyActiveScopeSubtreeDescriptors: render node has no matching descriptor");
                        _ = stream.appendElementInNamespace(allocator, desc.elem_id, desc.parent_elem_id, desc.scope_id, desc.tag, desc.namespace);
                    },
                    .text => {
                        const desc = findTextNodeDesc(previous, node.elem_id.raw()) orelse @panic("copyActiveScopeSubtreeDescriptors: render node has no matching descriptor");
                        stream.appendTextNode(allocator, desc.elem_id, desc.parent_elem_id, desc.scope_id, desc.value);
                    },
                    .signal_text => {
                        const desc = findSignalTextNodeDesc(previous, node.elem_id.raw()) orelse @panic("copyActiveScopeSubtreeDescriptors: render node has no matching descriptor");
                        const signal = desc.signal.cloneRetained(allocator, &self.pending_roc_metrics);
                        stream.appendSignalTextNode(allocator, ctx, roc_host, &self.pending_roc_metrics, desc.elem_id, desc.parent_elem_id, desc.scope_id, signal, desc.read);
                        stream.signal_text_nodes.items[stream.signal_text_nodes.items.len - 1].cached_value = self.cloneHostSignalCacheSlot(ctx, desc.cached_value, &self.pending_roc_metrics);
                    },
                }
            }

            for (previous.static_text_attrs.items) |desc| {
                if (!u64SliceContains(copied_elem_ids.items, desc.elem_id.raw())) continue;
                stream.appendStaticTextAttr(allocator, desc.elem_id, desc.field, desc.value);
            }
            for (previous.signal_text_attrs.items) |desc| {
                if (!u64SliceContains(copied_elem_ids.items, desc.elem_id.raw())) continue;
                const signal = desc.signal.cloneRetained(allocator, &self.pending_roc_metrics);
                stream.appendSignalTextAttr(allocator, ctx, roc_host, &self.pending_roc_metrics, desc.elem_id, desc.field, signal, desc.read);
                stream.signal_text_attrs.items[stream.signal_text_attrs.items.len - 1].cached_value = self.cloneHostSignalCacheSlot(ctx, desc.cached_value, &self.pending_roc_metrics);
            }
            for (previous.static_custom_text_attrs.items) |desc| {
                if (!u64SliceContains(copied_elem_ids.items, desc.elem_id.raw())) continue;
                stream.appendStaticCustomTextAttr(allocator, desc.elem_id, desc.name, desc.value);
            }
            for (previous.signal_custom_text_attrs.items) |desc| {
                if (!u64SliceContains(copied_elem_ids.items, desc.elem_id.raw())) continue;
                const signal = desc.signal.cloneRetained(allocator, &self.pending_roc_metrics);
                stream.appendSignalCustomTextAttr(allocator, ctx, roc_host, &self.pending_roc_metrics, desc.elem_id, desc.name, signal, desc.read);
                stream.signal_custom_text_attrs.items[stream.signal_custom_text_attrs.items.len - 1].cached_value = self.cloneHostSignalCacheSlot(ctx, desc.cached_value, &self.pending_roc_metrics);
            }
            for (previous.signal_optional_custom_text_attrs.items) |desc| {
                if (!u64SliceContains(copied_elem_ids.items, desc.elem_id.raw())) continue;
                const signal = desc.signal.cloneRetained(allocator, &self.pending_roc_metrics);
                stream.appendSignalOptionalCustomTextAttr(allocator, ctx, roc_host, &self.pending_roc_metrics, desc.elem_id, desc.name, signal, desc.present, desc.read);
                stream.signal_optional_custom_text_attrs.items[stream.signal_optional_custom_text_attrs.items.len - 1].cached_value = self.cloneHostSignalCacheSlot(ctx, desc.cached_value, &self.pending_roc_metrics);
            }
            for (previous.static_custom_bool_attrs.items) |desc| {
                if (!u64SliceContains(copied_elem_ids.items, desc.elem_id.raw())) continue;
                stream.appendStaticCustomBoolAttr(allocator, desc.elem_id, desc.name, desc.value);
            }
            for (previous.signal_custom_bool_attrs.items) |desc| {
                if (!u64SliceContains(copied_elem_ids.items, desc.elem_id.raw())) continue;
                const signal = desc.signal.cloneRetained(allocator, &self.pending_roc_metrics);
                stream.appendSignalCustomBoolAttr(allocator, ctx, roc_host, &self.pending_roc_metrics, desc.elem_id, desc.name, signal, desc.read);
                stream.signal_custom_bool_attrs.items[stream.signal_custom_bool_attrs.items.len - 1].cached_value = self.cloneHostSignalCacheSlot(ctx, desc.cached_value, &self.pending_roc_metrics);
            }
            for (previous.static_bool_attrs.items) |desc| {
                if (!u64SliceContains(copied_elem_ids.items, desc.elem_id.raw())) continue;
                stream.appendStaticBoolAttr(allocator, desc.elem_id, desc.field, desc.value);
            }
            for (previous.signal_bool_attrs.items) |desc| {
                if (!u64SliceContains(copied_elem_ids.items, desc.elem_id.raw())) continue;
                const signal = desc.signal.cloneRetained(allocator, &self.pending_roc_metrics);
                stream.appendSignalBoolAttr(allocator, ctx, roc_host, &self.pending_roc_metrics, desc.elem_id, desc.field, signal, desc.read);
                stream.signal_bool_attrs.items[stream.signal_bool_attrs.items.len - 1].cached_value = self.cloneHostSignalCacheSlot(ctx, desc.cached_value, &self.pending_roc_metrics);
            }
            for (previous.on_changes.items) |desc| {
                if (!(self.scopeIsDescendantOrSelf(desc.scope_id.raw(), root_scope_id) catch @panic("scope descriptor referenced an unknown parent scope"))) continue;
                const signal = desc.signal.cloneRetained(allocator, &self.pending_roc_metrics);
                stream.appendOnChange(allocator, ctx, roc_host, &self.pending_roc_metrics, desc.scope_id, signal, desc.to_cmd, desc.run_initial, desc.run_initial_pending);
                stream.on_changes.items[stream.on_changes.items.len - 1].cached_value = self.cloneHostSignalCacheSlot(ctx, desc.cached_value, &self.pending_roc_metrics);
            }
            for (previous.mounts.items) |desc| {
                if (!(self.scopeIsDescendantOrSelf(desc.scope_id.raw(), root_scope_id) catch @panic("scope descriptor referenced an unknown parent scope"))) continue;
                stream.appendMount(allocator, roc_host, &self.pending_roc_metrics, desc.scope_id, desc.to_cmd, false);
            }
            for (previous.cleanups.items) |desc| {
                if (!(self.scopeIsDescendantOrSelf(desc.scope_id.raw(), root_scope_id) catch @panic("scope descriptor referenced an unknown parent scope"))) continue;
                stream.appendCleanup(allocator, desc.scope_id, desc.name);
            }
            for (previous.events.items, 0..) |desc, event_index| {
                if (!u64SliceContains(copied_elem_ids.items, desc.elem_id.raw())) continue;
                const handler = if (desc.owns_handler) desc.handler else self.activeEventHandlerByIndex(event_index) catch @panic("active event table is missing its retained handler");
                switch (desc.binding) {
                    .fixed => |kind| stream.appendEvent(allocator, ctx, roc_host, &self.pending_roc_metrics, desc.elem_id, kind, desc.delivery_request, desc.payload_descriptor, handler),
                    .named => |binding| stream.appendNamedEvent(allocator, ctx, roc_host, &self.pending_roc_metrics, desc.elem_id, binding.name, binding.policy, binding.delivery_request, binding.key_chord, desc.payload_descriptor, handler),
                }
            }

            for (previous.scope_sites.items) |desc| {
                if (!(self.scopeIsDescendantOrSelf(desc.scope_id.raw(), root_scope_id) catch @panic("scope descriptor referenced an unknown parent scope"))) continue;
                const render_insert_index = if (previous_render_base) |render_base| blk: {
                    if (desc.render_insert_index < render_base) @panic("copied scope site insertion point precedes its scope subtree");
                    break :blk next_render_base + (desc.render_insert_index - render_base);
                } else next_render_base;
                stream.appendScopeSiteAt(allocator, desc.node_id, desc.scope_id, desc.ordinal, desc.parent_elem_id, render_insert_index, desc.kind, desc.binder_bindings);
            }
            for (previous.states.items) |desc| {
                if (!self.streamNodeIdInScopeSubtree(previous, desc.node_id, ids.ScopeId.fromRaw(root_scope_id))) continue;
                stream.appendState(allocator, roc_host, &self.pending_roc_metrics, desc.node_id, desc.initial, desc.cap);
            }
            for (previous.whens.items) |desc| {
                if (!self.streamNodeIdInScopeSubtree(previous, desc.node_id, ids.ScopeId.fromRaw(root_scope_id))) continue;
                const condition = desc.condition.cloneRetained(allocator, &self.pending_roc_metrics);
                stream.appendWhen(allocator, ctx, roc_host, &self.pending_roc_metrics, desc.node_id, condition, desc.ops);
                stream.whens.items[stream.whens.items.len - 1].cached_value = self.cloneHostSignalCacheSlot(ctx, desc.cached_value, &self.pending_roc_metrics);
            }
            for (previous.eaches.items) |desc| {
                if (!self.streamNodeIdInScopeSubtree(previous, desc.node_id, ids.ScopeId.fromRaw(root_scope_id))) continue;
                const items = desc.items.cloneRetained(allocator, &self.pending_roc_metrics);
                stream.appendEach(allocator, ctx, roc_host, &self.pending_roc_metrics, desc.node_id, items, desc.ops);
                stream.eaches.items[stream.eaches.items.len - 1].cached_value = self.cloneHostSignalCacheSlot(ctx, desc.cached_value, &self.pending_roc_metrics);
            }
        }

        /// Appends cleanup event using capacity that must already satisfy the caller's transaction contract.
        pub fn appendCleanupEvent(self: *Self, ctx: Ctx.Handle, name: []const u8) void {
            effects_runtime.appendCleanupEvent(Ctx.allocator(ctx), &self.cleanup_events, name);
        }

        /// Performs dispose scope subtree inside the shared engine while preserving transaction and changed-set invariants.
        pub fn disposeScopeSubtree(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, scope_id: u64) void {
            var disposal = ScopeDisposal{ .engine = self, .ctx = ctx, .roc_host = roc_host };
            scope_runtime.disposeSubtree(HostEachRowScopeStep, self.scopes.items, ids.ScopeId.fromRaw(scope_id), ids.Generation.fromRaw(self.identity_reuse_barrier), &disposal);
        }

        /// Performs create each row scope inside the shared engine while preserving transaction and changed-set invariants.
        pub fn createEachRowScope(self: *Self, ctx: Ctx.Handle, parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal, key_hash: u64, row_handle: row_handles.RowHandleId) ids.ScopeId {
            self.validateScopeId(parent_scope_id) catch @panic("scope id has no host scope descriptor");

            const result = if (self.has_inactive_scopes)
                scope_runtime.appendEachRow(Ctx.allocator(ctx), &self.scopes, parent_scope_id, site_ordinal, key_hash, row_handle, ids.Generation.fromRaw(self.identity_reuse_barrier)) catch @panic("scope id has no host scope descriptor")
            else
                scope_runtime.appendFreshEachRow(Ctx.allocator(ctx), &self.scopes, parent_scope_id, site_ordinal, key_hash, row_handle) catch @panic("scope id has no host scope descriptor");
            self.recordScopeCreated();
            const site_index = self.ensureEachRowSiteIndex(Ctx.allocator(ctx), parent_scope_id, site_ordinal);
            self.appendEachRowToSiteIndex(Ctx.allocator(ctx), site_index, result.scope_id.raw(), key_hash);
            return result.scope_id;
        }

        /// Every way a staged collection or publication can refuse, grouped by the
        /// contract the transaction violated:
        /// - `OutOfMemory`: the host allocator refused a preparation allocation.
        /// - `ResourceLimit`: a configured budget, reservation, or arithmetic bound was exceeded.
        /// - `InvalidScope`: a scope or identity the transaction named is unknown, inactive, duplicated, or unavailable.
        /// - `InvalidDescriptor`: a descriptor, node, state cell, site, or attribute the transaction assumed does not exist or is semantically rejected.
        /// - `OverlappingRemoval`: two removals in one transaction claim the same render interval or scope subtree.
        /// - `InvalidRenderTopology`: the staged render tree contradicts the committed one.
        /// - `InvalidSignalGraphAppend`: a staged signal graph append does not match the committed graph.
        /// - `InvalidSignalGraphRelease`: a staged signal graph release names records the committed graph does not hold.
        pub const CollectionError = error{ OutOfMemory, ResourceLimit, InvalidScope, InvalidDescriptor, OverlappingRemoval, InvalidRenderTopology, InvalidSignalGraphAppend, InvalidSignalGraphRelease };

        /// Maps a scope-tree rejection onto the collection contract it violated.
        fn scopeError(err: scope_tree.Error) CollectionError {
            return switch (err) {
                error.OutOfMemory => error.OutOfMemory,
                error.UnknownScope, error.InactiveScope, error.InvalidRoot => error.InvalidScope,
            };
        }

        const RenderSpliceError = std.mem.Allocator.Error || error{ ResourceLimit, MissingNode, MissingParent, ActiveNode, DuplicateNode, ConflictingParent, DuplicateChild, TagMismatch };

        /// Maps a render-cache splice rejection onto the collection contract it violated.
        fn renderSpliceError(err: RenderSpliceError) CollectionError {
            return switch (err) {
                error.OutOfMemory => error.OutOfMemory,
                error.ResourceLimit => error.ResourceLimit,
                error.MissingNode, error.MissingParent, error.ActiveNode, error.DuplicateNode, error.ConflictingParent, error.DuplicateChild, error.TagMismatch => error.InvalidRenderTopology,
            };
        }
        const WhenCollection = struct {
            scope: scope_tree.InternResult,
            branch: HostScopeBranch,
            elem: abi.Elem,
            capability: HostValueCapability,
        };

        fn activeWhenBranch(self: *Self, parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal) CollectionError!?HostScopeBranch {
            const true_scope = self.activeWhenBranchScopeId(parent_scope_id, site_ordinal, .true_branch) catch |err| return scopeError(err);
            const false_scope = self.activeWhenBranchScopeId(parent_scope_id, site_ordinal, .false_branch) catch |err| return scopeError(err);
            if (true_scope != null and false_scope != null) return error.InvalidScope;
            if (true_scope != null) return .true_branch;
            if (false_scope != null) return .false_branch;
            return null;
        }

        fn buildWhenElem(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, ops: HostWhenOps, value: HostValue, cap: HostValueCapability) abi.Elem {
            _ = self;
            assertHostValueCapabilitiesMatch(ops.case_capability, cap, "when case capability did not match its signal value");
            const builder_value = Ctx.cloneHostValue(ctx, value);
            return callHostValueToElemWithCapability(ctx, roc_host, ops.case_capability, ops.build, builder_value);
        }

        fn collectActiveWhenElemDescriptorsWith(self: *Self, comptime Collection: type, collection: Collection, ctx: Ctx.Handle, roc_host: *abi.RocHost, stream: *HostNodeDescriptorStream, selected: WhenCollection, parent_elem_id: ids.ElemId, binder_stack: *shared_buffer.List(HostBinderBinding), dirty_source_node_ids: []const u64) CollectionError!void {
            Ctx.pushHostValueCapabilities(ctx, &.{selected.capability});
            defer Ctx.popHostValueCapabilities(ctx);
            var branch_ordinal = ids.SiteOrdinal.fromRaw(0);
            var branch_dom_ordinal = ids.SiteOrdinal.fromRaw(0);
            try self.collectActiveElemDescriptorsWith(Collection, collection, ctx, roc_host, stream, selected.elem, selected.scope.scope_id, parent_elem_id, &branch_ordinal, &branch_dom_ordinal, binder_stack, selected.scope.created, dirty_source_node_ids);
        }

        fn collectActiveEachRowElemDescriptorsWith(self: *Self, comptime Collection: type, collection: Collection, ctx: Ctx.Handle, roc_host: *abi.RocHost, stream: *HostNodeDescriptorStream, each: HostNodeEachDesc, row_elem: abi.Elem, row_scope_id: ids.ScopeId, parent_elem_id: ids.ElemId, ordinal: *ids.SiteOrdinal, dom_ordinal: *ids.SiteOrdinal, binder_stack: *shared_buffer.List(HostBinderBinding), row_created: bool, dirty_source_node_ids: []const u64) CollectionError!void {
            Ctx.pushHostValueCapabilities(ctx, &.{each.ops.item_capability});
            defer Ctx.popHostValueCapabilities(ctx);
            try collection.appendConstructionPosition(row_scope_id, parent_elem_id, .rowStart(row_scope_id));
            try self.collectActiveElemDescriptorsWith(Collection, collection, ctx, roc_host, stream, row_elem, row_scope_id, parent_elem_id, ordinal, dom_ordinal, binder_stack, row_created, dirty_source_node_ids);
            try collection.appendConstructionPosition(row_scope_id, parent_elem_id, .rowEnd(row_scope_id));
        }

        fn buildEachRowElem(self: *Self, roc_host: *abi.RocHost, ops: HostEachOps, row_scope_id: ids.ScopeId) abi.Elem {
            const handle = scope_runtime.eachRowHandle(self.scopes.items, row_scope_id);
            const binding = self.resolveEachRowBinding(handle) orelse @panic("each row had no committed generation binding");
            _ = self.eachGenerationForBinding(binding) orelse @panic("each row generation was not retained");
            const location = self.rows_store.?.findScope(row_scope_id.raw()) orelse @panic("each row scope was absent from Rows store");
            const key = (self.rows_store.?.getRowConst(location.site_id, location.row_id) catch @panic("each row became stale")).key;
            return retained_values.callEachRowBuilder(roc_host, ops.row, abi.RocStr.fromSlice(key, roc_host), handle.raw());
        }

        const StagedCollectionCtx = struct {
            const Collection = @This();
            const PreparedCustomAttrKey = struct {
                elem_id: u64,
                name: []const u8,
            };
            const PreparedCustomAttrContext = struct {
                /// Hashes an element identity and its exact custom-attribute bytes.
                pub fn hash(_: @This(), key: PreparedCustomAttrKey) u64 {
                    return std.hash.Wyhash.hash(key.elem_id, key.name);
                }

                /// Compares both the element identity and exact attribute bytes.
                pub fn eql(_: @This(), left: PreparedCustomAttrKey, right: PreparedCustomAttrKey) bool {
                    return left.elem_id == right.elem_id and std.mem.eql(u8, left.name, right.name);
                }
            };
            const PreparedCustomAttrIndex = std.HashMapUnmanaged(
                PreparedCustomAttrKey,
                void,
                PreparedCustomAttrContext,
                std.hash_map.default_max_load_percentage,
            );
            const PreparedNamedEventKey = struct {
                elem_id: u64,
                name: []const u8,
                key_chord: ?@import("key_chord.zig").Chord = null,
            };
            const PreparedNamedEventContext = struct {
                /// Hashes an element identity and its exact event-name bytes.
                pub fn hash(_: @This(), key: PreparedNamedEventKey) u64 {
                    const filter: u64 = if (key.key_chord) |chord| (@as(u64, chord.key) << 32) | chord.modifiers else 0;
                    return std.hash.Wyhash.hash(key.elem_id ^ filter, key.name);
                }

                /// Compares both the element identity and exact event-name bytes.
                pub fn eql(_: @This(), left: PreparedNamedEventKey, right: PreparedNamedEventKey) bool {
                    return left.elem_id == right.elem_id and std.mem.eql(u8, left.name, right.name) and @import("key_chord.zig").optionalEql(left.key_chord, right.key_chord);
                }
            };
            const PreparedNamedEventIndex = std.HashMapUnmanaged(
                PreparedNamedEventKey,
                void,
                PreparedNamedEventContext,
                std.hash_map.default_max_load_percentage,
            );
            const PreparedRenderNode = union(enum) {
                static: usize,
                signal: usize,
            };
            const RowRenderSpanRange = struct {
                item_slot: u64,
                parent_elem_id: ids.ElemId,
                start: usize,
                len: usize,
            };
            const RowRenderSpanIntent = struct {
                owner: union(enum) { initial: usize, nested: usize },
                range: RowRenderSpanRange,
            };
            const ScopeDescriptorCounts = struct {
                elems: usize = 0,
                nodes: usize = 0,
            };
            /// One scope this collection will publish, in claim order. Scope
            /// intents and each-row scopes are journaled in separate lists,
            /// but a child is always claimed after its parent, so replaying
            /// claims in order attaches every child beneath an already
            /// published parent even when reused ids are not monotonic.
            const ScopePublication = union(enum) {
                intent: usize,
                each_row: usize,
            };
            engine: *Self,
            host_ctx: Ctx.Handle,
            stream: *HostNodeDescriptorStream,
            budget: collection_budget.StreamBudget,
            scopes: collection_plan.ScopeOverlay = .{},
            node_identities: collection_plan.IdentityOverlay = .{},
            dom_identities: collection_plan.IdentityOverlay = .{},
            /// Newest committed reusable-ring slot this collection has walked
            /// past (claimed or skipped), or null before the first walk. The
            /// next candidate is its ring successor; the ring itself is never
            /// modified until commit publishes the claimed slots.
            last_reused_scope_id: ?ids.ScopeId = null,
            /// Set once the ring ran out or its next slot was barrier-blocked;
            /// later claims take fresh slots without touching the ring.
            scope_reuse_exhausted: bool = false,
            scope_claim_work: if (builtin.is_test) scope_runtime.ScopeClaimWork else void = if (builtin.is_test) .{} else {},
            /// Claim-order journal replayed by `commit`; see `ScopePublication`.
            scope_publications: shared_buffer.List(ScopePublication) = .empty,
            fresh_scope_cursor: u64 = 0,
            reusable_node_cursor: usize = 0,
            fresh_node_cursor: u64 = 0,
            reusable_dom_cursor: usize = 0,
            fresh_dom_cursor: u64 = 0,
            prepared_nodes: shared_buffer.List(HostNodeDescriptorStream.PreparedStaticNode) = .empty,
            prepared_render_order: shared_buffer.List(PreparedRenderNode) = .empty,
            construction_order: shared_buffer.List(structural_positions.Entry) = .empty,
            prepared_attrs: shared_buffer.List(HostNodeDescriptorStream.PreparedStaticAttr) = .empty,
            prepared_signal_attrs: shared_buffer.List(HostNodeDescriptorStream.PreparedSignalDescriptor) = .empty,
            /// Exact names already staged by this transaction. Keys borrow
            /// descriptor-owned name storage and therefore must be destroyed
            /// before prepared descriptors are aborted or moved.
            prepared_custom_attrs: PreparedCustomAttrIndex = .empty,
            custom_attr_lookup_work: if (builtin.is_test) usize else void = if (builtin.is_test) 0 else {},
            prepared_events: shared_buffer.List(HostNodeDescriptorStream.PreparedEventDescriptor) = .empty,
            /// Exact named-event bindings already staged by this transaction.
            /// Keys borrow the corresponding prepared event's copied name.
            prepared_named_events: PreparedNamedEventIndex = .empty,
            named_event_lookup_work: if (builtin.is_test) usize else void = if (builtin.is_test) 0 else {},
            prepared_lifecycle: shared_buffer.List(HostNodeDescriptorStream.PreparedLifecycleDescriptor) = .empty,
            prepared_state_sites: shared_buffer.List(HostNodeDescriptorStream.PreparedScopeSite) = .empty,
            prepared_states: shared_buffer.List(HostNodeDescriptorStream.PreparedState) = .empty,
            prepared_state_cells: shared_buffer.List(HostState) = .empty,
            external_state_count: usize = 0,
            /// The enclosing source transaction's prepared cache updates, when
            /// this collection mounts inside one; staged records read through it.
            cache_overlay: ?*const signal_records.PreparedCacheUpdates = null,
            prepared_each_row_scopes: shared_buffer.List(HostScope) = .empty,
            prepared_whens: shared_buffer.List(HostNodeDescriptorStream.PreparedWhen) = .empty,
            prepared_eaches: shared_buffer.List(HostNodeDescriptorStream.PreparedEach) = .empty,
            prepared_each_sites: shared_buffer.List(HostEachRowSite) = .empty,
            prepared_initial_each_inputs: shared_buffer.List(PreparedEachInputs) = .empty,
            /// Generations displaced when a retiring structural site is
            /// re-collected under the same stable site identity.
            retired_initial_generations: shared_buffer.List(*each_generation.Generation) = .empty,
            /// Each sites a re-collected row brought back under a live site
            /// key, reconciled by key against the committed rows rather than
            /// mounted afresh. Preparation-owned; publication commits each
            /// reconciliation into the site it prepared against.
            nested_row_syncs: shared_buffer.List(PreparedNestedRowSync) = .empty,
            /// Created or re-collected row ranges whose stable render anchors
            /// are installed after the prepared descriptor order materializes.
            row_render_span_intents: shared_buffer.List(RowRenderSpanIntent) = .empty,
            /// Conservative sum of nested row-binding edits, used to reserve
            /// the one committed table for every staged reconciliation before publication.
            candidate_binding_edit_count: usize = 0,
            /// Number of candidate generations this collection will publish
            /// into the shared registry at its allocation-free commit boundary.
            candidate_generation_count: usize = 0,
            /// Borrowed O(1) indexes for every candidate generation visible
            /// while this collection is being prepared. They own neither row
            /// handles nor generations; the per-site prepared inputs retain
            /// those until commit or abort.
            prepared_row_bindings: std.AutoHashMapUnmanaged(row_handles.RowHandleId, each_generation.RowBinding) = .empty,
            prepared_generations: std.AutoHashMapUnmanaged(each_generation.GenerationId, *each_generation.Generation) = .empty,
            pending_scope_descriptor_counts: std.AutoHashMapUnmanaged(u64, ScopeDescriptorCounts) = .empty,
            prepared_named_event_groups: shared_buffer.List(HostNodeDescriptorStream.PreparedNamedEventIndexGroup) = .empty,
            prepared_named_event_group_by_elem: std.AutoHashMapUnmanaged(u64, usize) = .empty,
            signal_records: collection_plan.SignalRecordPlan(HostSignalToken, signal_records.KeyedSelectIdentity, HostSignalRecord) = .{},
            signal_bindings: shared_buffer.List(HostSignalBinding) = .empty,
            signal_roc_host: ?*abi.RocHost = null,
            plan: CapacityPlan = .{},
            phase: CollectionPhase = .collecting,

            /// Cumulative capacity totals of one staged collection transaction.
            ///
            /// Every reservation the collection makes, at init and again when
            /// a nested each site adds its evaluated rows, adds its counts
            /// here and then reserves every engine, stream, and
            /// preparation-owned container against the cumulative totals.
            /// Materialization and publication assume capacity against these
            /// totals and must not allocate, so a reservation relative to what
            /// has been appended so far is not expressible: a nested site
            /// reserves while its outer site's siblings and rows are still
            /// pending, and those claim ids and slots after the nested
            /// reservation ran. Engine-owned tables do not grow at all until
            /// commit, so their unused capacity must cover the whole plan.
            const CapacityPlan = struct {
                /// One reservation's contribution to the plan.
                const Counts = struct {
                    roots: StaticRootCounts = .{},
                    /// Scopes the transaction claims beyond the component and
                    /// when-branch scopes its roots declare: externally
                    /// attached scope ids and one scope per each row.
                    external_scopes: usize = 0,
                    each_rows: usize = 0,
                    /// State cells staged for an external state update; they
                    /// are retired at commit rather than published.
                    external_states: usize = 0,

                    fn scopeSites(self: Counts) CollectionError!usize {
                        const state_component = try total(self.roots.state_sites, self.roots.component_sites);
                        const without_each = try total(state_component, self.roots.when_sites);
                        return total(without_each, self.roots.each_sites);
                    }

                    fn scopeIntents(self: Counts) CollectionError!usize {
                        const child_scopes = try total(self.roots.component_sites, self.roots.when_sites);
                        return total(self.external_scopes, child_scopes);
                    }

                    /// Every descriptor root contains at least one signal
                    /// record, so the record count also bounds roots that are
                    /// neither attributes nor lifecycle entries, such as when
                    /// conditions and signal-backed text nodes.
                    fn signalRoots(self: Counts) CollectionError!usize {
                        const attr_lifecycle = try total(self.roots.attrs, self.roots.lifecycle);
                        return @max(attr_lifecycle, self.roots.signal_records);
                    }
                };

                nodes: usize = 0,
                elements: usize = 0,
                text_nodes: usize = 0,
                signal_text_nodes: usize = 0,
                attrs: usize = 0,
                static_text_attrs: usize = 0,
                static_custom_text_attrs: usize = 0,
                static_bool_attrs: usize = 0,
                static_custom_bool_attrs: usize = 0,
                signal_text_attrs: usize = 0,
                signal_custom_text_attrs: usize = 0,
                signal_optional_custom_text_attrs: usize = 0,
                signal_bool_attrs: usize = 0,
                signal_custom_bool_attrs: usize = 0,
                events: usize = 0,
                named_events: usize = 0,
                custom_attrs: usize = 0,
                lifecycle: usize = 0,
                signal_records: usize = 0,
                signal_roots: usize = 0,
                state_sites: usize = 0,
                when_sites: usize = 0,
                each_sites: usize = 0,
                scope_sites: usize = 0,
                scope_intents: usize = 0,
                each_rows: usize = 0,
                external_states: usize = 0,
                /// Committed table lengths the latest reservation was made
                /// against; fresh ids are claimed contiguously above them.
                /// Other steps of a composite transaction may append to the
                /// engine tables before this collection commits, so the
                /// coverage checks compare against these bases, not the
                /// lengths at commit.
                scope_base: usize = 0,
                node_base: usize = 0,
                dom_base: usize = 0,

                fn total(left: usize, right: usize) CollectionError!usize {
                    return std.math.add(usize, left, right) catch error.ResourceLimit;
                }

                /// Returns the totals after `counts` joins the plan; the plan
                /// itself only changes once every reservation has succeeded.
                fn add(self: CapacityPlan, counts: Counts) CollectionError!CapacityPlan {
                    return .{
                        .nodes = try total(self.nodes, counts.roots.nodes),
                        .elements = try total(self.elements, counts.roots.elements),
                        .text_nodes = try total(self.text_nodes, counts.roots.text_nodes),
                        .signal_text_nodes = try total(self.signal_text_nodes, counts.roots.signal_text_nodes),
                        .attrs = try total(self.attrs, counts.roots.attrs),
                        .static_text_attrs = try total(self.static_text_attrs, counts.roots.static_text_attrs),
                        .static_custom_text_attrs = try total(self.static_custom_text_attrs, counts.roots.static_custom_text_attrs),
                        .static_bool_attrs = try total(self.static_bool_attrs, counts.roots.static_bool_attrs),
                        .static_custom_bool_attrs = try total(self.static_custom_bool_attrs, counts.roots.static_custom_bool_attrs),
                        .signal_text_attrs = try total(self.signal_text_attrs, counts.roots.signal_text_attrs),
                        .signal_custom_text_attrs = try total(self.signal_custom_text_attrs, counts.roots.signal_custom_text_attrs),
                        .signal_optional_custom_text_attrs = try total(self.signal_optional_custom_text_attrs, counts.roots.signal_optional_custom_text_attrs),
                        .signal_bool_attrs = try total(self.signal_bool_attrs, counts.roots.signal_bool_attrs),
                        .signal_custom_bool_attrs = try total(self.signal_custom_bool_attrs, counts.roots.signal_custom_bool_attrs),
                        .events = try total(self.events, counts.roots.events),
                        .named_events = try total(self.named_events, counts.roots.named_events),
                        .custom_attrs = try total(self.custom_attrs, counts.roots.custom_attrs),
                        .lifecycle = try total(self.lifecycle, counts.roots.lifecycle),
                        .signal_records = try total(self.signal_records, counts.roots.signal_records),
                        .signal_roots = try total(self.signal_roots, try counts.signalRoots()),
                        .state_sites = try total(self.state_sites, counts.roots.state_sites),
                        .when_sites = try total(self.when_sites, counts.roots.when_sites),
                        .each_sites = try total(self.each_sites, counts.roots.each_sites),
                        .scope_sites = try total(self.scope_sites, try counts.scopeSites()),
                        .scope_intents = try total(self.scope_intents, try counts.scopeIntents()),
                        .each_rows = try total(self.each_rows, counts.each_rows),
                        .external_states = try total(self.external_states, counts.external_states),
                        .scope_base = self.scope_base,
                        .node_base = self.node_base,
                        .dom_base = self.dom_base,
                    };
                }

                /// Reserves every container the collection publishes into
                /// against these cumulative totals. Only the identity and
                /// scope overlays take this reservation's own `added` counts:
                /// they track their outstanding reservations themselves.
                fn reserve(self: *CapacityPlan, collection: *StagedCollectionCtx, added: Counts) CollectionError!void {
                    const allocator = Ctx.allocator(collection.host_ctx);
                    const engine_ptr = collection.engine;
                    self.scope_base = engine_ptr.scopes.items.len;
                    self.node_base = engine_ptr.node_identities.items.len;
                    self.dom_base = engine_ptr.dom_identities.items.len;
                    collection.scopes.prepare(allocator, try added.scopeIntents()) catch return error.OutOfMemory;
                    collection.node_identities.prepare(allocator, try added.scopeSites()) catch return error.OutOfMemory;
                    collection.dom_identities.prepare(allocator, added.roots.nodes) catch return error.OutOfMemory;

                    var static_attrs = try total(self.static_text_attrs, self.static_custom_text_attrs);
                    static_attrs = try total(static_attrs, try total(self.static_bool_attrs, self.static_custom_bool_attrs));
                    var signal_descriptors = try total(self.signal_text_attrs, self.signal_custom_text_attrs);
                    signal_descriptors = try total(signal_descriptors, self.signal_optional_custom_text_attrs);
                    signal_descriptors = try total(signal_descriptors, try total(self.signal_bool_attrs, self.signal_custom_bool_attrs));
                    signal_descriptors = try total(signal_descriptors, self.signal_text_nodes);
                    const named_events_u32 = std.math.cast(u32, self.named_events) orelse return error.ResourceLimit;
                    const state_cells = try total(self.state_sites, self.external_states);
                    collection.prepared_nodes.ensureUnusedCapacity(allocator, self.nodes) catch return error.OutOfMemory;
                    collection.prepared_render_order.ensureUnusedCapacity(allocator, self.nodes) catch return error.OutOfMemory;
                    const row_positions = try total(self.each_rows, self.each_rows);
                    const site_positions = try total(self.when_sites, try total(self.each_sites, self.each_sites));
                    const position_count = try total(self.nodes, try total(site_positions, row_positions));
                    collection.construction_order.ensureUnusedCapacity(allocator, position_count) catch return error.OutOfMemory;
                    collection.prepared_attrs.ensureUnusedCapacity(allocator, static_attrs) catch return error.OutOfMemory;
                    collection.prepared_signal_attrs.ensureUnusedCapacity(allocator, signal_descriptors) catch return error.OutOfMemory;
                    // A nested branch can reserve before its parent's remaining
                    // attributes or events have been inserted. Reserve the whole
                    // plan, including those outstanding parent entries.
                    collection.prepared_custom_attrs.ensureTotalCapacity(allocator, std.math.cast(u32, self.custom_attrs) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                    collection.prepared_events.ensureUnusedCapacity(allocator, self.events) catch return error.OutOfMemory;
                    collection.prepared_named_events.ensureTotalCapacity(allocator, named_events_u32) catch return error.OutOfMemory;
                    collection.prepared_lifecycle.ensureUnusedCapacity(allocator, self.lifecycle) catch return error.OutOfMemory;
                    collection.prepared_state_sites.ensureUnusedCapacity(allocator, self.scope_sites) catch return error.OutOfMemory;
                    collection.prepared_states.ensureUnusedCapacity(allocator, self.state_sites) catch return error.OutOfMemory;
                    collection.prepared_state_cells.ensureUnusedCapacity(allocator, state_cells) catch return error.OutOfMemory;
                    collection.prepared_whens.ensureUnusedCapacity(allocator, self.when_sites) catch return error.OutOfMemory;
                    collection.prepared_eaches.ensureUnusedCapacity(allocator, self.each_sites) catch return error.OutOfMemory;
                    collection.prepared_each_sites.ensureUnusedCapacity(allocator, self.each_sites) catch return error.OutOfMemory;
                    collection.prepared_each_row_scopes.ensureUnusedCapacity(allocator, self.each_rows) catch return error.OutOfMemory;
                    collection.scope_publications.ensureTotalCapacity(allocator, try total(self.scope_intents, self.each_rows)) catch return error.OutOfMemory;
                    collection.prepared_named_event_groups.ensureUnusedCapacity(allocator, self.named_events) catch return error.OutOfMemory;
                    collection.prepared_named_event_group_by_elem.ensureUnusedCapacity(allocator, named_events_u32) catch return error.OutOfMemory;
                    collection.signal_records.prepare(allocator, self.signal_records, self.signal_roots) catch return error.OutOfMemory;
                    collection.signal_bindings.ensureUnusedCapacity(allocator, self.signal_roots) catch return error.OutOfMemory;

                    // Fresh scope, node, and elem ids are claimed contiguously
                    // above the committed tables, skipping only ids this
                    // transaction already holds, so the committed length plus
                    // the cumulative total bounds every id the plan can claim.
                    const scope_len = try total(self.scope_base, self.scope_intents);
                    const state_index_len = try total(self.node_base, self.scope_sites);
                    engine_ptr.scopes.ensureTotalCapacity(allocator, scope_len) catch return error.OutOfMemory;
                    engine_ptr.each_row_memberships_by_scope_id.ensureTotalCapacity(allocator, scope_len) catch return error.OutOfMemory;
                    engine_ptr.node_identities.ensureUnusedCapacity(allocator, self.scope_sites) catch return error.OutOfMemory;
                    engine_ptr.active_node_identity_ids.ensureUnusedCapacity(allocator, std.math.cast(u32, self.scope_sites) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                    engine_ptr.states.ensureUnusedCapacity(allocator, self.state_sites) catch return error.OutOfMemory;
                    engine_ptr.state_indexes_by_node_id.ensureTotalCapacity(allocator, state_index_len) catch return error.OutOfMemory;
                    // `engine.dom_identities` grows to the exact elem id when
                    // `reserveDomIdentity` claims it during preparation: a
                    // transaction that reuses retired ids appends nothing, and
                    // reserving `nodes` fresh slots regardless would grow the
                    // committed table on every such transaction, breaking its
                    // plateau. The plan still bounds every claim.
                    engine_ptr.active_dom_identity_ids.ensureUnusedCapacity(allocator, std.math.cast(u32, self.nodes) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                    engine_ptr.each_row_sites.ensureUnusedCapacity(allocator, self.each_sites) catch return error.OutOfMemory;
                    engine_ptr.each_row_site_indexes.ensureUnusedCapacity(allocator, std.math.cast(u32, self.each_sites) orelse return error.ResourceLimit) catch return error.OutOfMemory;

                    const highest_elem_id: u64 = @intCast(try total(self.dom_base, self.nodes));
                    try collection.stream.reservePreparedStaticNodeLanes(allocator, self.elements, self.text_nodes, self.nodes, highest_elem_id);
                    try collection.stream.reservePreparedStaticAttrLanes(allocator, self.static_text_attrs, self.static_bool_attrs, self.static_custom_text_attrs, self.static_custom_bool_attrs);
                    try collection.stream.reservePreparedSignalAttrLanes(allocator, self.signal_text_attrs, self.signal_bool_attrs, self.signal_custom_text_attrs, self.signal_optional_custom_text_attrs, self.signal_custom_bool_attrs, highest_elem_id);
                    try collection.stream.reservePreparedSignalTextNodes(allocator, self.signal_text_nodes, highest_elem_id);
                    try collection.stream.reservePreparedSignalRecordPublication(allocator, self.signal_records);
                    try collection.stream.reservePreparedEvents(allocator, self.events, highest_elem_id);
                    try collection.stream.reservePreparedCustomAttrIndex(allocator, self.custom_attrs);
                    try collection.stream.reservePreparedLifecycle(allocator, self.lifecycle);
                    if (self.scope_sites != 0) {
                        const highest_node_id: u64 = @intCast(state_index_len - 1);
                        try collection.stream.reservePreparedStateSites(allocator, self.scope_sites, highest_node_id);
                        try collection.stream.reservePreparedWhens(allocator, self.when_sites, highest_node_id);
                        try collection.stream.reservePreparedEaches(allocator, self.each_sites, highest_node_id);
                    }
                }

                /// Checks, in safe builds only, that the preparation-owned
                /// vectors and the prepared stream can absorb the plan before
                /// materialization drains them into the stream.
                fn assertStreamCovered(self: *const CapacityPlan, collection: *const StagedCollectionCtx) void {
                    if (!std.debug.runtime_safety) return;
                    const stream = collection.stream;
                    std.debug.assert(collection.prepared_nodes.capacity >= self.nodes);
                    std.debug.assert(collection.prepared_render_order.capacity >= self.nodes);
                    std.debug.assert(collection.construction_order.capacity >= self.nodes + self.when_sites + self.each_sites);
                    const static_attrs = self.static_text_attrs +| self.static_custom_text_attrs +| self.static_bool_attrs +| self.static_custom_bool_attrs;
                    const signal_descriptors = self.signal_text_attrs +| self.signal_custom_text_attrs +| self.signal_optional_custom_text_attrs +| self.signal_bool_attrs +| self.signal_custom_bool_attrs +| self.signal_text_nodes;
                    std.debug.assert(collection.prepared_attrs.capacity >= static_attrs);
                    std.debug.assert(collection.prepared_signal_attrs.capacity >= signal_descriptors);
                    std.debug.assert(collection.prepared_events.capacity >= self.events);
                    std.debug.assert(collection.prepared_lifecycle.capacity >= self.lifecycle);
                    std.debug.assert(collection.prepared_state_sites.capacity >= self.scope_sites);
                    std.debug.assert(collection.prepared_states.capacity >= self.state_sites);
                    std.debug.assert(collection.prepared_state_cells.capacity >= self.state_sites +| self.external_states);
                    std.debug.assert(collection.prepared_whens.capacity >= self.when_sites);
                    std.debug.assert(collection.prepared_eaches.capacity >= self.each_sites);
                    std.debug.assert(collection.prepared_each_sites.capacity >= self.each_sites);
                    std.debug.assert(collection.prepared_each_row_scopes.capacity >= self.each_rows);
                    std.debug.assert(collection.scope_publications.capacity >= self.scope_intents +| self.each_rows);
                    std.debug.assert(collection.prepared_named_event_groups.capacity >= self.named_events);
                    std.debug.assert(collection.signal_bindings.capacity >= self.signal_roots);
                    std.debug.assert(collection.signal_records.token_intents.capacity >= self.signal_records);
                    std.debug.assert(collection.signal_records.descriptor_roots.capacity >= self.signal_roots);
                    std.debug.assert(stream.render_nodes.capacity - stream.render_nodes.items.len >= self.nodes);
                    std.debug.assert(stream.elements.capacity - stream.elements.items.len >= self.elements);
                    std.debug.assert(stream.text_nodes.capacity - stream.text_nodes.items.len >= self.text_nodes);
                    std.debug.assert(stream.signal_text_nodes.capacity - stream.signal_text_nodes.items.len >= self.signal_text_nodes);
                    std.debug.assert(stream.static_text_attrs.capacity - stream.static_text_attrs.items.len >= self.static_text_attrs);
                    std.debug.assert(stream.static_bool_attrs.capacity - stream.static_bool_attrs.items.len >= self.static_bool_attrs);
                    std.debug.assert(stream.static_custom_text_attrs.capacity - stream.static_custom_text_attrs.items.len >= self.static_custom_text_attrs);
                    std.debug.assert(stream.static_custom_bool_attrs.capacity - stream.static_custom_bool_attrs.items.len >= self.static_custom_bool_attrs);
                    std.debug.assert(stream.signal_text_attrs.capacity - stream.signal_text_attrs.items.len >= self.signal_text_attrs);
                    std.debug.assert(stream.signal_bool_attrs.capacity - stream.signal_bool_attrs.items.len >= self.signal_bool_attrs);
                    std.debug.assert(stream.signal_custom_text_attrs.capacity - stream.signal_custom_text_attrs.items.len >= self.signal_custom_text_attrs);
                    std.debug.assert(stream.signal_optional_custom_text_attrs.capacity - stream.signal_optional_custom_text_attrs.items.len >= self.signal_optional_custom_text_attrs);
                    std.debug.assert(stream.signal_custom_bool_attrs.capacity - stream.signal_custom_bool_attrs.items.len >= self.signal_custom_bool_attrs);
                    std.debug.assert(stream.events.capacity - stream.events.items.len >= self.events);
                    std.debug.assert(stream.on_changes.capacity - stream.on_changes.items.len >= self.lifecycle);
                    std.debug.assert(stream.mounts.capacity - stream.mounts.items.len >= self.lifecycle);
                    std.debug.assert(stream.cleanups.capacity - stream.cleanups.items.len >= self.lifecycle);
                    std.debug.assert(stream.scope_sites.capacity - stream.scope_sites.items.len >= self.scope_sites);
                    std.debug.assert(stream.states.capacity - stream.states.items.len >= self.scope_sites);
                    std.debug.assert(stream.whens.capacity - stream.whens.items.len >= self.when_sites);
                    std.debug.assert(stream.eaches.capacity - stream.eaches.items.len >= self.each_sites);
                    std.debug.assert(stream.descriptor_indexes_by_elem_id.capacity >= self.dom_base +| self.nodes +| 1);
                    if (self.scope_sites != 0) std.debug.assert(stream.descriptor_indexes_by_node_id.capacity >= self.node_base +| self.scope_sites);
                }

                /// Checks, in safe builds only, that the engine-owned tables
                /// publication appends into can absorb the plan. Hash maps
                /// track their own availability and are not checked here.
                fn assertEngineCovered(self: *const CapacityPlan, collection: *const StagedCollectionCtx) void {
                    if (!std.debug.runtime_safety) return;
                    const engine_ptr = collection.engine;
                    std.debug.assert(engine_ptr.scopes.capacity >= self.scope_base +| self.scope_intents);
                    std.debug.assert(engine_ptr.each_row_memberships_by_scope_id.capacity >= self.scope_base +| self.scope_intents);
                    std.debug.assert(engine_ptr.node_identities.capacity >= self.node_base +| self.scope_sites);
                    std.debug.assert(engine_ptr.state_indexes_by_node_id.capacity >= self.node_base +| self.scope_sites);
                    std.debug.assert(engine_ptr.states.capacity - engine_ptr.states.items.len >= self.state_sites);
                    for (collection.dom_identities.intents.items) |intent| std.debug.assert(engine_ptr.dom_identities.capacity >= intent.id);
                    std.debug.assert(engine_ptr.each_row_sites.capacity - engine_ptr.each_row_sites.items.len >= self.each_sites);
                }
            };

            fn init(engine_ptr: *Self, host_ctx: Ctx.Handle, stream: *HostNodeDescriptorStream, limits: collection_budget.Limits, counts: StaticRootCounts, expected_external_scopes: usize) CollectionError!@This() {
                var self = @This(){
                    .engine = engine_ptr,
                    .host_ctx = host_ctx,
                    .stream = stream,
                    .budget = collection_budget.StreamBudget.init(limits) catch return error.ResourceLimit,
                };
                errdefer self.deinit();
                if (counts.nodes > limits.nodes) return error.ResourceLimit;
                try self.reserveCounts(.{ .roots = counts, .external_scopes = expected_external_scopes });
                return self;
            }

            fn deinit(self: *@This()) void {
                const allocator = Ctx.allocator(self.host_ctx);
                // Index keys borrow names owned by prepared descriptors (or by
                // the materialized stream), so discard every borrow first.
                self.prepared_custom_attrs.deinit(allocator);
                self.prepared_custom_attrs = .empty;
                // Named-event keys likewise borrow descriptor-owned names.
                self.prepared_named_events.deinit(allocator);
                self.prepared_named_events = .empty;
                if (!self.phase.isCommitted()) {
                    var index = self.prepared_nodes.items.len;
                    if (!self.phase.isMaterialized()) {
                        while (index != 0) {
                            index -= 1;
                            self.prepared_nodes.items[index].abort(allocator);
                        }
                        index = self.prepared_events.items.len;
                        while (index != 0) {
                            index -= 1;
                            self.prepared_events.items[index].abort(allocator, self.host_ctx, self.signal_roc_host orelse @panic("staged event lacked Roc host"), &self.engine.pending_roc_metrics);
                        }
                        index = self.prepared_named_event_groups.items.len;
                        while (index != 0) {
                            index -= 1;
                            self.prepared_named_event_groups.items[index].abort(allocator);
                        }
                        index = self.prepared_lifecycle.items.len;
                        while (index != 0) {
                            index -= 1;
                            self.prepared_lifecycle.items[index].abort(allocator, self.host_ctx, self.signal_roc_host orelse @panic("staged lifecycle descriptor lacked Roc host"), &self.engine.pending_roc_metrics);
                        }
                    }
                    index = self.prepared_state_cells.items.len;
                    while (index != 0) {
                        index -= 1;
                        self.prepared_state_cells.items[index].retire(self.host_ctx, self.signal_roc_host orelse @panic("staged state lacked Roc host"), &self.engine.pending_roc_metrics);
                    }
                    index = self.prepared_each_row_scopes.items.len;
                    while (index != 0) {
                        index -= 1;
                        deinitHostScopeStep(&self.prepared_each_row_scopes.items[index].step);
                    }
                    if (!self.phase.isMaterialized()) {
                        index = self.prepared_states.items.len;
                        while (index != 0) {
                            index -= 1;
                            self.prepared_states.items[index].abort(self.signal_roc_host orelse @panic("staged state lacked Roc host"), &self.engine.pending_roc_metrics);
                        }
                        index = self.prepared_state_sites.items.len;
                        while (index != 0) {
                            index -= 1;
                            self.prepared_state_sites.items[index].abort(allocator);
                        }
                        index = self.prepared_whens.items.len;
                        while (index != 0) {
                            index -= 1;
                            self.prepared_whens.items[index].abort(allocator, self.host_ctx, self.signal_roc_host orelse @panic("staged when lacked Roc host"), &self.engine.pending_roc_metrics);
                        }
                        index = self.prepared_eaches.items.len;
                        while (index != 0) {
                            index -= 1;
                            self.prepared_eaches.items[index].abort(allocator, self.host_ctx, self.signal_roc_host orelse @panic("staged each lacked Roc host"), &self.engine.pending_roc_metrics);
                        }
                        index = self.prepared_attrs.items.len;
                        while (index != 0) {
                            index -= 1;
                            self.prepared_attrs.items[index].abort(allocator);
                        }
                        index = self.prepared_signal_attrs.items.len;
                        while (index != 0) {
                            index -= 1;
                            self.prepared_signal_attrs.items[index].abort(
                                allocator,
                                self.host_ctx,
                                self.signal_roc_host orelse @panic("staged signal descriptor lacked Roc host"),
                                &self.engine.pending_roc_metrics,
                            );
                        }
                        for (self.signal_bindings.items) |binding| allocator.free(binding.source_node_ids);
                    }
                    self.scopes.abort();
                    self.scope_publications.clearRetainingCapacity();
                    self.node_identities.abort();
                    self.dom_identities.abort();
                }
                self.prepared_nodes.deinit(allocator);
                self.prepared_render_order.deinit(allocator);
                self.construction_order.deinit(allocator);
                self.prepared_attrs.deinit(allocator);
                self.prepared_signal_attrs.deinit(allocator);
                self.prepared_events.deinit(allocator);
                self.prepared_lifecycle.deinit(allocator);
                self.prepared_named_event_groups.deinit(allocator);
                self.prepared_named_event_group_by_elem.deinit(allocator);
                self.prepared_state_sites.deinit(allocator);
                self.prepared_states.deinit(allocator);
                self.prepared_state_cells.deinit(allocator);
                self.prepared_each_row_scopes.deinit(allocator);
                self.scope_publications.deinit(allocator);
                self.prepared_whens.deinit(allocator);
                self.prepared_eaches.deinit(allocator);
                for (self.prepared_each_sites.items) |*site| site.deinit(allocator);
                self.prepared_each_sites.deinit(allocator);
                for (self.prepared_initial_each_inputs.items) |*inputs| inputs.deinit();
                self.prepared_initial_each_inputs.deinit(allocator);
                for (self.retired_initial_generations.items) |generation| {
                    generation.deinit(allocator, self.host_ctx, self.signal_roc_host orelse @panic("retired initial Rows generation lacked Roc host"), &self.engine.pending_roc_metrics);
                    allocator.destroy(generation);
                }
                self.retired_initial_generations.deinit(allocator);
                for (self.nested_row_syncs.items) |*sync| sync.deinit();
                self.nested_row_syncs.deinit(allocator);
                self.row_render_span_intents.deinit(allocator);
                self.prepared_row_bindings.deinit(allocator);
                self.prepared_generations.deinit(allocator);
                self.pending_scope_descriptor_counts.deinit(allocator);
                self.signal_bindings.deinit(allocator);
                const SignalReleaser = struct {
                    collection: *Collection,
                    /// Performs release record inside the shared engine while preserving transaction and changed-set invariants.
                    pub fn releaseRecord(releaser: @This(), record: *HostSignalRecord) void {
                        record.release(
                            Ctx.allocator(releaser.collection.host_ctx),
                            releaser.collection.host_ctx,
                            releaser.collection.signal_roc_host orelse @panic("staged signal record lacked Roc host"),
                            &releaser.collection.engine.pending_roc_metrics,
                        );
                    }
                };
                self.signal_records.deinit(allocator, SignalReleaser{ .collection = self });
                self.scopes.deinit(allocator);
                self.node_identities.deinit(allocator);
                self.dom_identities.deinit(allocator);
            }

            fn indexCandidateGeneration(self: *@This(), inputs: *const PreparedEachInputs) CollectionError!void {
                const allocator = Ctx.allocator(self.host_ctx);
                self.prepared_generations.ensureUnusedCapacity(allocator, 1) catch return error.OutOfMemory;
                const generation_entry = self.prepared_generations.getOrPutAssumeCapacity(inputs.generation.id);
                if (generation_entry.found_existing and generation_entry.value_ptr.* != inputs.generation) return error.InvalidDescriptor;
                generation_entry.value_ptr.* = inputs.generation;

                var live_count: usize = 0;
                var count_iterator = inputs.candidate_bindings.candidate.valueIterator();
                while (count_iterator.next()) |entry| if (entry.binding != null) {
                    live_count = std.math.add(usize, live_count, 1) catch return error.ResourceLimit;
                };
                self.prepared_row_bindings.ensureUnusedCapacity(allocator, std.math.cast(u32, live_count) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                var iterator = inputs.candidate_bindings.candidate.iterator();
                while (iterator.next()) |entry| if (entry.value_ptr.binding) |binding| {
                    const prepared = self.prepared_row_bindings.getOrPutAssumeCapacity(entry.key_ptr.*);
                    if (prepared.found_existing and !std.meta.eql(prepared.value_ptr.*, binding)) return error.InvalidDescriptor;
                    prepared.value_ptr.* = binding;
                };
            }

            /// Adds `counts` to the transaction's capacity plan and reserves
            /// every container against the new cumulative totals. The plan
            /// only advances once every reservation succeeded, so a refused
            /// reservation leaves the previous totals intact for retry.
            fn reserveCounts(self: *@This(), counts: CapacityPlan.Counts) CollectionError!void {
                var next = try self.plan.add(counts);
                try next.reserve(self, counts);
                self.plan = next;
            }

            fn reserveScopeDescriptors(self: *@This(), scope_id: ids.ScopeId, additional_elems: usize, additional_nodes: usize) CollectionError!void {
                const allocator = Ctx.allocator(self.host_ctx);
                const prior = self.pending_scope_descriptor_counts.get(scope_id.raw()) orelse ScopeDescriptorCounts{};
                const next = ScopeDescriptorCounts{
                    .elems = std.math.add(usize, prior.elems, additional_elems) catch return error.ResourceLimit,
                    .nodes = std.math.add(usize, prior.nodes, additional_nodes) catch return error.ResourceLimit,
                };
                if (!self.pending_scope_descriptor_counts.contains(scope_id.raw())) self.pending_scope_descriptor_counts.ensureUnusedCapacity(allocator, 1) catch return error.OutOfMemory;
                try self.stream.reserveScopeDescriptorOwnership(allocator, scope_id, next.elems, next.nodes);
                self.pending_scope_descriptor_counts.putAssumeCapacity(scope_id.raw(), next);
            }

            /// Stages the state value a transaction publishes so every signal
            /// a freshly collected branch or row reads through a bare `Ref`
            /// sees it rather than the committed cell. The cache overlay only
            /// covers records the active graph already holds; a record
            /// collected in this transaction has no slot there and would read
            /// the retired value. The clone is transaction-owned: `deinit`
            /// and `commit` both retire it, since the state update itself is
            /// published by the plan that owns the transaction.
            fn stageExternalStates(self: *@This(), roc_host: *abi.RocHost, updates: []const PreparedExternalState) CollectionError!void {
                if (updates.len == 0) return;
                if (self.external_state_count != 0) return error.ResourceLimit;
                self.signal_roc_host = roc_host;
                try self.reserveCounts(.{ .external_states = updates.len });
                for (updates) |update| {
                    const cloned = Ctx.cloneHostValue(self.host_ctx, update.value);
                    self.prepared_state_cells.appendAssumeCapacity(HostState.initActive(update.state_id, HostValueCell.initRetained(cloned, update.cap, &self.engine.pending_roc_metrics), 0));
                }
                self.external_state_count = updates.len;
            }

            fn rootScope(self: *@This()) CollectionError!scope_tree.InternResult {
                const key: collection_plan.ScopeKey = .{ .parent_id = ids.root_scope, .ordinal = ids.SiteOrdinal.fromRaw(0), .kind = .root };
                const active_id: ?ids.ScopeId = if (self.engine.scopes.items.len != 0) ids.root_scope else null;
                const intent_index = self.scopes.intents.items.len;
                const scope_id = self.scopes.reserve(key, active_id, &.{ids.root_scope}) catch |err| switch (err) {
                    error.NoCapacity => return error.ResourceLimit,
                    error.NoAvailableScope => return error.InvalidScope,
                };
                // A fresh root is the first claim of an empty table; a live
                // root resolves through the overlay without a new intent.
                if (self.scopes.intents.items.len != intent_index) try self.noteScopeClaimed(scope_id, null, .{ .intent = intent_index });
                return .{ .scope_id = scope_id, .created = active_id == null };
            }

            fn validateScope(self: *@This(), scope_id: ids.ScopeId) CollectionError!void {
                const root_key: collection_plan.ScopeKey = .{ .parent_id = ids.root_scope, .ordinal = ids.SiteOrdinal.fromRaw(0), .kind = .root };
                if (self.scopes.lookup(root_key, null) == scope_id) return;
                if (self.scopes.reserved_ids.contains(scope_id)) return;
                self.engine.validateScopeId(scope_id) catch |err| return scopeError(err);
            }

            fn attachExternalScopeIds(self: *@This(), scope_ids: []const u64) CollectionError!void {
                for (scope_ids) |scope_id| {
                    self.scopes.reserveExternal(ids.ScopeId.fromRaw(scope_id)) catch |err| switch (err) {
                        error.NoCapacity => return error.ResourceLimit,
                        error.DuplicateScope => return error.InvalidScope,
                    };
                }
            }

            /// Peeks the next committed reusable-ring slot this collection may
            /// claim, without consuming it. The walk starts at the ring head
            /// (oldest retirement) and resumes after the last slot handed out,
            /// so provisional claims never touch committed availability and
            /// an aborted collection leaves the ring exactly as it found it.
            /// Slots another party already reserved with this transaction
            /// (`reserved_ids`) are stepped over; they sit at the ring head
            /// because that party walked the same ring, so the skip is
            /// bounded by that party's own claim count. A barrier-blocked
            /// slot ends the walk for good: every later slot was retired in
            /// the same or a later generation.
            fn nextReusableScopeCandidate(self: *@This()) ?ids.ScopeId {
                if (self.scope_reuse_exhausted) return null;
                const scopes = self.engine.scopes.items;
                const barrier = ids.Generation.fromRaw(self.engine.identity_reuse_barrier);
                var candidate = if (self.last_reused_scope_id) |last| after_last: {
                    if (scopes[last.index()].lifecycle.isActive() or !scope_tree.isLinkedReusable(HostEachRowScopeStep, scopes, last)) @panic("provisionally claimed scope slot changed under an open collection");
                    break :after_last scope_tree.nextReusableScope(HostEachRowScopeStep, scopes, last);
                } else scope_tree.firstReusableScope(HostEachRowScopeStep, scopes);
                while (candidate) |scope_id| : (candidate = scope_tree.nextReusableScope(HostEachRowScopeStep, scopes, scope_id)) {
                    if (builtin.is_test) self.scope_claim_work.reusable_slots_visited += 1;
                    if (scopes[scope_id.index()].lifecycle.blocksReuse(barrier)) break;
                    if (self.scopes.reserved_ids.contains(scope_id)) {
                        self.last_reused_scope_id = scope_id;
                        continue;
                    }
                    return scope_id;
                }
                self.scope_reuse_exhausted = true;
                return null;
            }

            /// Returns the lowest fresh id above the committed table and this
            /// collection's earlier fresh claims that no reservation holds.
            fn nextFreshScopeId(self: *const @This()) CollectionError!u64 {
                var fresh_id = @max(self.fresh_scope_cursor, @as(u64, @intCast(self.engine.scopes.items.len)));
                while (self.scopes.reserved_ids.contains(ids.ScopeId.fromRaw(fresh_id))) fresh_id = std.math.add(u64, fresh_id, 1) catch return error.ResourceLimit;
                return fresh_id;
            }

            /// Records that `scope_id` was claimed: advances the ring cursor
            /// or the fresh cursor, and journals the publication in claim order.
            fn noteScopeClaimed(self: *@This(), scope_id: ids.ScopeId, reused: ?ids.ScopeId, publication: ScopePublication) CollectionError!void {
                if (reused != null and reused.? == scope_id) {
                    self.last_reused_scope_id = scope_id;
                } else {
                    self.fresh_scope_cursor = std.math.add(u64, scope_id.raw(), 1) catch return error.ResourceLimit;
                    if (builtin.is_test) self.scope_claim_work.fresh_slots_claimed += 1;
                }
                self.scope_publications.appendAssumeCapacity(publication);
            }

            fn reserveScopeIdentity(self: *@This(), key: collection_plan.ScopeKey, active_id: ?u64) CollectionError!u64 {
                if (self.scopes.lookup(key, if (active_id) |id| ids.ScopeId.fromRaw(id) else null)) |id| return id.raw();
                var candidates: [2]ids.ScopeId = undefined;
                var candidate_count: usize = 0;
                const reused = self.nextReusableScopeCandidate();
                if (reused) |scope_id| {
                    candidates[candidate_count] = scope_id;
                    candidate_count += 1;
                }
                const fresh_id = try self.nextFreshScopeId();
                candidates[candidate_count] = ids.ScopeId.fromRaw(fresh_id);
                candidate_count += 1;
                const intent_index = self.scopes.intents.items.len;
                const reserved = self.scopes.reserve(key, if (active_id) |id| ids.ScopeId.fromRaw(id) else null, candidates[0..candidate_count]) catch |err| switch (err) {
                    error.NoCapacity => return error.ResourceLimit,
                    error.NoAvailableScope => return error.InvalidScope,
                };
                try self.noteScopeClaimed(reserved, reused, .{ .intent = intent_index });
                return reserved.raw();
            }

            /// Whether `scope_id` is a committed, active scope: one this
            /// collection re-collects when it collects under it, since a
            /// scope the collection creates can only occupy an inactive slot.
            fn committedScopeIsActive(self: *const @This(), scope_id: ids.ScopeId) bool {
                return scope_id.index() < self.engine.scopes.items.len and self.engine.scopes.items[scope_id.index()].lifecycle.isActive();
            }

            /// A committed child scope re-collected under its committed parent
            /// keeps its identity: it is claimed like the parent was, so the
            /// scope stays active through publication while its descriptors
            /// are replaced, and the retirement derived from the collection
            /// knows it is kept.
            fn keepCommittedChildScope(self: *@This(), scope_id: ids.ScopeId) CollectionError!void {
                if (self.scopes.reserved_ids.contains(scope_id)) return;
                self.scopes.reserveExternal(scope_id) catch |err| switch (err) {
                    error.NoCapacity => return error.ResourceLimit,
                    error.DuplicateScope => return error.InvalidScope,
                };
            }

            fn reserveWhenBranchScope(self: *@This(), parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal, branch: HostScopeBranch) CollectionError!scope_tree.InternResult {
                const key: collection_plan.ScopeKey = .{ .parent_id = parent_scope_id, .ordinal = site_ordinal, .kind = .{ .when_branch = branch } };
                const active_id = if (self.committedScopeIsActive(parent_scope_id)) self.engine.activeWhenBranchScopeId(parent_scope_id, site_ordinal, branch) catch |err| return scopeError(err) else null;
                const branch_scope_id = try self.reserveScopeIdentity(key, if (active_id) |value| value.raw() else null);
                if (active_id) |value| try self.keepCommittedChildScope(value);
                return .{ .scope_id = ids.ScopeId.fromRaw(branch_scope_id), .created = active_id == null };
            }

            fn reserveEachRowScopeGeneration(self: *@This(), parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal, key_hash: u64, row_handle: row_handles.RowHandleId) CollectionError!ids.ScopeId {
                try self.validateScope(parent_scope_id);

                const reused = self.nextReusableScopeCandidate();
                const claimed: u64 = if (reused) |scope_id| scope_id.raw() else try self.nextFreshScopeId();
                self.scopes.reserveExternal(ids.ScopeId.fromRaw(claimed)) catch |err| switch (err) {
                    error.NoCapacity => return error.ResourceLimit,
                    error.DuplicateScope => return error.InvalidScope,
                };
                try self.noteScopeClaimed(ids.ScopeId.fromRaw(claimed), reused, .{ .each_row = self.prepared_each_row_scopes.items.len });
                if (std.debug.runtime_safety) std.debug.assert(claimed < self.plan.scope_base + self.plan.scope_intents);
                self.prepared_each_row_scopes.appendAssumeCapacity(.{
                    .scope_id = ids.ScopeId.fromRaw(claimed),
                    .parent_scope_id = parent_scope_id,
                    .step = .{ .each_row = .{
                        .site_ordinal = site_ordinal,
                        .key_hash = key_hash,
                        .row_handle = row_handle,
                    } },
                    .lifecycle = .active,
                });
                return ids.ScopeId.fromRaw(claimed);
            }

            fn reserveDomIdentity(self: *@This(), scope_id: ids.ScopeId, ordinal: ids.SiteOrdinal) CollectionError!ids.ElemId {
                const key = identityKey(scope_id.raw(), ordinal.raw());
                const active_id = self.engine.active_dom_identity_ids.get(key);
                if (active_id != null or self.dom_identities.provisional_by_key.contains(key)) {
                    const elem_id = self.dom_identities.reserve(key, active_id, &.{}) catch |err| return switch (err) {
                        error.NoCapacity => error.ResourceLimit,
                        error.NoAvailableIdentity => error.InvalidScope,
                    };
                    return ids.ElemId.fromRaw(elem_id);
                }
                var candidates: [2]u64 = undefined;
                var candidate_count: usize = 0;
                while (self.reusable_dom_cursor < self.engine.dom_identities.items.len) : (self.reusable_dom_cursor += 1) {
                    const identity = self.engine.dom_identities.items[self.reusable_dom_cursor];
                    if (identity.lifecycle.blocksReuse(ids.Generation.fromRaw(self.engine.identity_reuse_barrier))) continue;
                    if (self.dom_identities.reserved_ids.contains(identity.elem_id.raw())) continue;
                    // The render cache is the publication authority. Never
                    // recycle an ID that remains live there, even if identity
                    // metadata was retired by an earlier structural splice.
                    if (self.engine.render_cache.hasActiveNode(identity.elem_id)) continue;
                    candidates[candidate_count] = identity.elem_id.raw();
                    candidate_count += 1;
                    self.reusable_dom_cursor += 1;
                    break;
                }
                var fresh_id = @max(self.fresh_dom_cursor, std.math.add(u64, @intCast(self.engine.dom_identities.items.len), 1) catch return error.ResourceLimit);
                while (self.dom_identities.reserved_ids.contains(fresh_id) or self.engine.render_cache.hasActiveNode(ids.ElemId.fromRaw(fresh_id))) fresh_id = std.math.add(u64, fresh_id, 1) catch return error.ResourceLimit;
                candidates[candidate_count] = fresh_id;
                candidate_count += 1;
                const elem_id = self.dom_identities.reserve(key, active_id, candidates[0..candidate_count]) catch |err| return switch (err) {
                    error.NoCapacity => error.ResourceLimit,
                    error.NoAvailableIdentity => error.InvalidScope,
                };
                if (elem_id == fresh_id) self.fresh_dom_cursor = std.math.add(u64, fresh_id, 1) catch return error.ResourceLimit;
                // Elem ids are one-based and claimed contiguously above the
                // committed table, so the plan's cumulative node total bounds
                // every id this transaction can hold; the table grows to the
                // exact id here, while preparation may still allocate.
                if (std.debug.runtime_safety) std.debug.assert(elem_id <= self.plan.dom_base + self.plan.nodes);
                const required_len = std.math.cast(usize, elem_id) orelse return error.ResourceLimit;
                self.engine.dom_identities.ensureTotalCapacity(Ctx.allocator(self.host_ctx), required_len) catch return error.OutOfMemory;
                return ids.ElemId.fromRaw(elem_id);
            }

            fn reserveNodeIdentity(self: *@This(), scope_id: ids.ScopeId, ordinal: ids.SiteOrdinal) CollectionError!ids.NodeId {
                const key = identityKey(scope_id.raw(), ordinal.raw());
                const active_id = self.engine.active_node_identity_ids.get(key);
                if (active_id != null or self.node_identities.provisional_by_key.contains(key)) {
                    const node_id = self.node_identities.reserve(key, active_id, &.{}) catch |err| return switch (err) {
                        error.NoCapacity => error.ResourceLimit,
                        error.NoAvailableIdentity => error.InvalidScope,
                    };
                    return ids.NodeId.fromRaw(node_id);
                }
                var candidates: [2]u64 = undefined;
                var candidate_count: usize = 0;
                while (self.reusable_node_cursor < self.engine.node_identities.items.len) : (self.reusable_node_cursor += 1) {
                    const identity = self.engine.node_identities.items[self.reusable_node_cursor];
                    if (identity.lifecycle.blocksReuse(ids.Generation.fromRaw(self.engine.identity_reuse_barrier))) continue;
                    if (self.node_identities.reserved_ids.contains(identity.node_id.raw())) continue;
                    // The committed descriptor stream is the publication
                    // authority for node ids, exactly as the render cache is
                    // for element ids. Identity metadata for a construction
                    // site can be retired while another scope's live site
                    // still occupies that node's descriptor slots, and the
                    // per-node slots hold one descriptor each.
                    if (self.engine.activeStreamHoldsNode(identity.node_id.raw())) continue;
                    candidates[candidate_count] = identity.node_id.raw();
                    candidate_count += 1;
                    self.reusable_node_cursor += 1;
                    break;
                }
                var fresh_id = @max(self.fresh_node_cursor, @as(u64, @intCast(self.engine.node_identities.items.len)));
                while (self.node_identities.reserved_ids.contains(fresh_id) or self.engine.activeStreamHoldsNode(fresh_id)) fresh_id = std.math.add(u64, fresh_id, 1) catch return error.ResourceLimit;
                candidates[candidate_count] = fresh_id;
                candidate_count += 1;
                const node_id = self.node_identities.reserve(key, active_id, candidates[0..candidate_count]) catch |err| return switch (err) {
                    error.NoCapacity => error.ResourceLimit,
                    error.NoAvailableIdentity => error.InvalidScope,
                };
                if (node_id == fresh_id) self.fresh_node_cursor = std.math.add(u64, fresh_id, 1) catch return error.ResourceLimit;
                return ids.NodeId.fromRaw(node_id);
            }

            fn beginState(self: *@This(), roc_host: *abi.RocHost, scope_id: ids.ScopeId, parent_elem_id: ids.ElemId, ordinal: *ids.SiteOrdinal, binder_stack: *shared_buffer.List(HostBinderBinding), state: abi_view.StateElem) CollectionError!HostBinderBinding {
                const allocator = Ctx.allocator(self.host_ctx);
                const binder_bytes = std.math.mul(usize, binder_stack.items.len, @sizeOf(HostBinderBinding)) catch return error.ResourceLimit;
                const descriptor_bytes = std.math.add(usize, @sizeOf(HostNodeScopeSiteDesc) + @sizeOf(HostNodeStateDesc), binder_bytes) catch return error.ResourceLimit;
                try self.budget.charge(0, descriptor_bytes);
                // The binder stack is caller-owned preparation scratch that is
                // pushed and popped while descriptors are collected; nothing
                // appends to it at publication, so it stays outside the plan.
                binder_stack.ensureUnusedCapacity(allocator, 1) catch return error.OutOfMemory;
                const site_ordinal = ordinal.*;
                const node_id = try self.reserveNodeIdentity(scope_id, site_ordinal);
                try self.reserveScopeDescriptors(scope_id, 0, 1);
                var prepared_site = self.stream.prepareScopeSite(allocator, node_id, scope_id, site_ordinal, parent_elem_id, .state, binder_stack.items) catch return error.OutOfMemory;
                prepared_site.desc.render_insert_index = self.prepared_render_order.items.len;
                errdefer prepared_site.abort(allocator);
                self.signal_roc_host = roc_host;
                const prepared_state = self.stream.prepareState(node_id, state.initial, state.capability, &self.engine.pending_roc_metrics);
                errdefer prepared_state.abort(roc_host, &self.engine.pending_roc_metrics);
                if (self.engine.stateIndexByNodeId(node_id.raw()) == null) {
                    const initial = erased_calls.callValueInitThunk(roc_host, state.initial.toAbi());
                    const cell = HostValueCell.initRetained(initial, state.capability, &self.engine.pending_roc_metrics);
                    self.prepared_state_cells.appendAssumeCapacity(HostState.initActive(node_id.raw(), cell, 0));
                }
                self.prepared_state_sites.appendAssumeCapacity(prepared_site);
                self.prepared_states.appendAssumeCapacity(prepared_state);
                ordinal.* = ids.SiteOrdinal.fromRaw(ordinal.*.raw() + 1);
                return .{ .token = state.binder.callable, .node_id = node_id };
            }

            fn beginComponent(self: *@This(), scope_id: ids.ScopeId, parent_elem_id: ids.ElemId, ordinal: *ids.SiteOrdinal, binder_stack: []const HostBinderBinding) CollectionError!scope_tree.InternResult {
                const binder_bytes = std.math.mul(usize, binder_stack.len, @sizeOf(HostBinderBinding)) catch return error.ResourceLimit;
                try self.budget.charge(0, std.math.add(usize, @sizeOf(HostNodeScopeSiteDesc), binder_bytes) catch return error.ResourceLimit);
                const site_ordinal = ordinal.*;
                const node_id = try self.reserveNodeIdentity(scope_id, site_ordinal);
                try self.reserveScopeDescriptors(scope_id, 0, 1);
                var prepared = self.stream.prepareScopeSite(Ctx.allocator(self.host_ctx), node_id, scope_id, site_ordinal, parent_elem_id, .component, binder_stack) catch return error.OutOfMemory;
                prepared.desc.render_insert_index = self.prepared_render_order.items.len;
                errdefer prepared.abort(Ctx.allocator(self.host_ctx));
                const key: collection_plan.ScopeKey = .{ .parent_id = scope_id, .ordinal = site_ordinal, .kind = .component };
                var active_id: ?u64 = null;
                for (self.engine.scopes.items) |scope| {
                    if (!self.committedScopeIsActive(scope_id)) break;
                    if (!scope.lifecycle.isActive() or scope.parent_scope_id == null or scope.parent_scope_id.? != scope_id) continue;
                    switch (scope.step) {
                        .component => |step| if (step.site_ordinal == site_ordinal) {
                            active_id = scope.scope_id.raw();
                            break;
                        },
                        else => {},
                    }
                }
                const component_scope_id = try self.reserveScopeIdentity(key, active_id);
                if (active_id) |value| try self.keepCommittedChildScope(ids.ScopeId.fromRaw(value));
                self.prepared_state_sites.appendAssumeCapacity(prepared);
                ordinal.* = ids.SiteOrdinal.fromRaw(ordinal.*.raw() + 1);
                return .{ .scope_id = ids.ScopeId.fromRaw(component_scope_id), .created = active_id == null };
            }

            fn beginWhen(self: *@This(), roc_host: *abi.RocHost, scope_id: ids.ScopeId, parent_elem_id: ids.ElemId, ordinal: *ids.SiteOrdinal, binder_stack: []const HostBinderBinding, payload: abi_view.WhenElem) CollectionError!WhenCollection {
                const allocator = Ctx.allocator(self.host_ctx);
                const binder_bytes = std.math.mul(usize, binder_stack.len, @sizeOf(HostBinderBinding)) catch return error.ResourceLimit;
                try self.budget.charge(0, std.math.add(usize, @sizeOf(HostNodeScopeSiteDesc) + @sizeOf(HostNodeWhenDesc), binder_bytes) catch return error.ResourceLimit);
                const site_ordinal = ordinal.*;
                const node_id = try self.reserveNodeIdentity(scope_id, site_ordinal);
                try self.reserveScopeDescriptors(scope_id, 0, 1);
                var site = self.stream.prepareScopeSite(allocator, node_id, scope_id, site_ordinal, parent_elem_id, .when, binder_stack) catch return error.OutOfMemory;
                site.desc.render_insert_index = self.prepared_render_order.items.len;
                errdefer site.abort(allocator);
                try self.appendConstructionPosition(scope_id, parent_elem_id, .marker(node_id, .when));
                const condition = try self.bindSignalRoot(roc_host, payload.condition.*, binder_stack);
                var prepared = self.stream.prepareWhen(node_id, condition, payload.ops, &self.engine.pending_roc_metrics);
                errdefer prepared.abort(allocator, self.host_ctx, roc_host, &self.engine.pending_roc_metrics);
                self.signal_records.transferDescriptorRoot(condition.record);
                const journaled = self.signal_bindings.pop() orelse @panic("staged when binding journal underflow");
                if (journaled.record != condition.record or journaled.source_node_ids.ptr != condition.source_node_ids.ptr) @panic("staged when binding journal transfer mismatch");
                const value = self.engine.evalHostSignalBindingStaged(self.host_ctx, roc_host, &prepared.desc.condition, self.prepared_state_cells.items, self.cache_overlay);
                const cap = self.engine.hostSignalRecordCapabilityWithProvisionalStates(self.host_ctx, prepared.desc.condition.record, self.prepared_state_cells.items);
                // Owned before anything fallible runs. The condition value comes
                // back retained, and selecting a branch, building its elem, and
                // reserving for it can all refuse; until the cell owns the value
                // nothing would release it, so a refusal here leaked it. The
                // errdefer above already aborts this descriptor, and aborting it
                // releases the cell.
                prepared.desc.cached_value = .{ .present = HostValueCell.initRetained(value, cap, &self.engine.pending_roc_metrics) };
                const branch = if (self.committedScopeIsActive(scope_id))
                    (try self.engine.activeWhenBranch(scope_id, site_ordinal)) orelse .true_branch
                else
                    .true_branch;
                const branch_elem = self.engine.buildWhenElem(self.host_ctx, roc_host, prepared.desc.ops, value, cap);
                errdefer branch_elem.decref(roc_host);
                try self.reserveCounts(.{ .roots = try countStaticRootNodes(branch_elem) });
                // Under a scope re-collected here the opposite branch may
                // still be active: it retires with the re-collection. Under
                // any other committed scope it is a live branch this
                // collection would duplicate.
                if (self.committedScopeIsActive(scope_id) and !self.scopes.reserved_ids.contains(scope_id) and (self.engine.activeWhenBranchScopeId(scope_id, site_ordinal, branch.opposite()) catch |err| return scopeError(err)) != null) return error.InvalidScope;
                const branch_scope = try self.reserveWhenBranchScope(scope_id, site_ordinal, branch);
                self.prepared_state_sites.appendAssumeCapacity(site);
                self.prepared_whens.appendAssumeCapacity(prepared);
                ordinal.* = ids.SiteOrdinal.fromRaw(ordinal.*.raw() + 1);
                return .{ .scope = branch_scope, .branch = branch, .elem = branch_elem, .capability = prepared.desc.ops.case_capability };
            }

            fn collectInitialEach(self: *@This(), roc_host: *abi.RocHost, scope_id: ids.ScopeId, parent_elem_id: ids.ElemId, ordinal: *ids.SiteOrdinal, binder_stack: *shared_buffer.List(HostBinderBinding), payload: abi_view.EachElem, dirty_source_node_ids: []const u64) CollectionError!void {
                const allocator = Ctx.allocator(self.host_ctx);
                const site_ordinal = ordinal.*;
                const node_id = try self.reserveNodeIdentity(scope_id, site_ordinal);
                try self.reserveScopeDescriptors(scope_id, 0, 1);
                var site = self.stream.prepareScopeSite(allocator, node_id, scope_id, site_ordinal, parent_elem_id, .each, binder_stack.items) catch return error.OutOfMemory;
                site.desc.render_insert_index = self.prepared_render_order.items.len;
                errdefer site.abort(allocator);
                try self.appendConstructionPosition(scope_id, parent_elem_id, .marker(node_id, .each));
                const items = try self.bindSignalRoot(roc_host, payload.rows.*, binder_stack.items);
                var prepared_each = self.stream.prepareEach(node_id, items, payload.ops, &self.engine.pending_roc_metrics);
                errdefer prepared_each.abort(allocator, self.host_ctx, roc_host, &self.engine.pending_roc_metrics);
                self.signal_records.transferDescriptorRoot(items.record);
                const journaled = self.signal_bindings.pop() orelse @panic("staged each binding journal underflow");
                if (journaled.record != items.record or journaled.source_node_ids.ptr != items.source_node_ids.ptr) @panic("staged each binding journal transfer mismatch");
                const items_value = self.engine.evalHostSignalBindingStaged(self.host_ctx, roc_host, &prepared_each.desc.items, self.prepared_state_cells.items, self.cache_overlay);
                const items_cap = self.engine.hostSignalRecordCapabilityWithProvisionalStates(self.host_ctx, prepared_each.desc.items.record, self.prepared_state_cells.items);
                assertHostValueCapabilitiesMatch(prepared_each.desc.ops.rows_capability, items_cap, "Rows extension capability did not match its signal value");
                prepared_each.desc.cached_value = .{ .present = HostValueCell.initRetained(items_value, items_cap, &self.engine.pending_roc_metrics) };

                // A live site key names a committed each site whose rows this
                // collection reconciles by key: the parent scope is a
                // committed row re-collected in place, and its nested rows
                // keep their scopes, descriptors, and render nodes when their
                // keys survive. Only a scope no committed site names mounts
                // its rows afresh.
                if (self.liveEachSiteIndex(scope_id, site_ordinal)) |site_index| {
                    try self.collectNestedRowSync(roc_host, scope_id, parent_elem_id, site_ordinal, site_index, &prepared_each.desc, binder_stack, dirty_source_node_ids);
                    try self.appendConstructionPosition(scope_id, parent_elem_id, .marker(node_id, .each_end));
                    self.prepared_state_sites.appendAssumeCapacity(site);
                    self.prepared_eaches.appendAssumeCapacity(prepared_each);
                    ordinal.* = ids.SiteOrdinal.fromRaw(ordinal.*.raw() + 1);
                    return;
                }

                const evaluated = try PreparedInitialEach.prepare(self.engine, self.host_ctx, roc_host, &prepared_each.desc, scope_id, site_ordinal, allocator, self.prepared_state_cells.items);
                defer evaluated.deinit();
                try evaluated.reserveForCollection(self);
                // Initial-row bindings are staged while the row scopes are
                // collected below, so reserve their full generation bound
                // rather than the still-empty candidate table.
                self.candidate_binding_edit_count = std.math.add(usize, self.candidate_binding_edit_count, evaluated.inputs.generation.item_count) catch return error.ResourceLimit;
                const committed_binding_bound = std.math.add(usize, self.engine.committed_row_bindings.entries.count(), self.candidate_binding_edit_count) catch return error.ResourceLimit;
                self.engine.committed_row_bindings.entries.ensureTotalCapacity(allocator, std.math.cast(u32, committed_binding_bound) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                evaluated.inputs.candidate_bindings.preflightCommit(&self.engine.committed_row_bindings) catch |err| return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    error.ResourceLimit => error.ResourceLimit,
                };
                self.candidate_generation_count = std.math.add(usize, self.candidate_generation_count, 1) catch return error.ResourceLimit;
                self.engine.each_generations.ensureUnusedCapacity(allocator, std.math.cast(u32, self.candidate_generation_count) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                self.retired_initial_generations.ensureUnusedCapacity(allocator, self.candidate_generation_count) catch return error.OutOfMemory;
                const site_slot_bound = std.math.add(usize, self.engine.each_generation_ids_by_site_index.items.len, self.candidate_generation_count) catch return error.ResourceLimit;
                self.engine.each_generation_ids_by_site_index.ensureTotalCapacity(allocator, site_slot_bound) catch return error.OutOfMemory;
                try self.indexCandidateGeneration(&evaluated.inputs);

                // The site's own row tables are sized to exactly its rows and
                // filled below during preparation; publication moves the whole
                // site into `engine.each_row_sites`, whose slot the plan holds.
                var prepared_site = HostEachRowSite{ .key = .{ .parent_scope_id = scope_id, .site_ordinal = site_ordinal } };
                errdefer prepared_site.deinit(allocator);
                prepared_site.scope_ids.ensureTotalCapacity(allocator, evaluated.rows.len) catch return error.OutOfMemory;
                prepared_site.hash_links.ensureTotalCapacity(allocator, evaluated.rows.len) catch return error.OutOfMemory;
                prepared_site.hash_heads.ensureTotalCapacity(allocator, std.math.cast(u32, evaluated.rows.len) orelse return error.ResourceLimit) catch return error.OutOfMemory;

                const previous_bindings = self.engine.active_each_candidate_bindings;
                const previous_inputs = self.engine.active_each_candidate_inputs;
                const previous_generation = self.engine.active_each_candidate_generation;
                const previous_rows_site_id = self.engine.active_each_candidate_rows_site_id;
                self.engine.active_each_candidate_bindings = &evaluated.inputs.candidate_bindings;
                self.engine.active_each_candidate_inputs = &evaluated.inputs;
                self.engine.active_each_candidate_generation = evaluated.inputs.generation;
                self.engine.active_each_candidate_rows_site_id = evaluated.inputs.rows_site_id;
                defer {
                    self.engine.active_each_candidate_bindings = previous_bindings;
                    self.engine.active_each_candidate_inputs = previous_inputs;
                    self.engine.active_each_candidate_generation = previous_generation;
                    self.engine.active_each_candidate_rows_site_id = previous_rows_site_id;
                }
                const row_render_ranges = allocator.alloc(RowRenderSpanRange, evaluated.rows.len) catch return error.OutOfMemory;
                defer allocator.free(row_render_ranges);
                for (evaluated.rows, 0..) |row, row_index| {
                    const row_scope_id = try self.reserveEachRowScopeGeneration(scope_id, site_ordinal, row.key_hash, row.row_handle);
                    prepared_site.scope_ids.appendAssumeCapacity(row_scope_id);
                    prepared_site.hash_links.appendAssumeCapacity(each_runtime.missing_row_index);
                    const hash_entry = prepared_site.hash_heads.getOrPutAssumeCapacity(row.key_hash);
                    if (hash_entry.found_existing) prepared_site.hash_links.items[row_index] = hash_entry.value_ptr.*;
                    hash_entry.value_ptr.* = row_index;

                    var row_ordinal = ids.SiteOrdinal.fromRaw(0);
                    var row_dom_ordinal = ids.SiteOrdinal.fromRaw(0);
                    const render_start = self.prepared_render_order.items.len;
                    try self.engine.collectActiveEachRowElemDescriptorsWith(*Collection, self, self.host_ctx, roc_host, self.stream, prepared_each.desc, row.elem, row_scope_id, parent_elem_id, &row_ordinal, &row_dom_ordinal, binder_stack, true, dirty_source_node_ids);
                    row_render_ranges[row_index] = .{
                        .item_slot = evaluated.inputs.slot(row_index) orelse return error.InvalidDescriptor,
                        .parent_elem_id = parent_elem_id,
                        .start = render_start,
                        .len = self.prepared_render_order.items.len - render_start,
                    };
                }

                const rows_key = each_runtime.SiteKey{ .parent_scope_id = scope_id, .site_ordinal = site_ordinal };
                const rows_site_bound = std.math.add(usize, self.engine.rows_site_ids.count(), self.candidate_generation_count) catch return error.ResourceLimit;
                self.engine.rows_site_ids.ensureTotalCapacity(allocator, std.math.cast(u32, rows_site_bound) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                const stable_generation_bound = std.math.add(usize, self.engine.each_generation_ids_by_rows_site.count(), self.candidate_generation_count) catch return error.ResourceLimit;
                self.engine.each_generation_ids_by_rows_site.ensureTotalCapacity(allocator, std.math.cast(u32, stable_generation_bound) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                const owner = rows_site_store.OwnerToken.fromRaw(evaluated.inputs.generation.rows_generation) catch return error.InvalidDescriptor;
                const rows_store = self.engine.rowsStore(allocator);
                const existing_rows_site_id = self.engine.rows_site_ids.get(rows_key);
                const rows_site_id = existing_rows_site_id orelse (rows_store.createSite(owner) catch |err| return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    error.ResourceLimit => error.ResourceLimit,
                    else => error.InvalidDescriptor,
                });
                evaluated.inputs.rows_site_id = rows_site_id;
                evaluated.inputs.rows_site_key = rows_key;
                evaluated.inputs.rows_site_published = existing_rows_site_id != null;
                const edit_offset: usize = if (existing_rows_site_id != null) 1 else 0;
                const stable_edits = allocator.alloc(rows_transition.StableEdit, evaluated.rows.len + edit_offset) catch return error.OutOfMemory;
                defer allocator.free(stable_edits);
                if (edit_offset != 0) stable_edits[0] = .clear;
                for (evaluated.rows, prepared_site.scope_ids.items, 0..) |row, row_scope_id, row_index| {
                    const slot = evaluated.inputs.slot(row_index) orelse return error.InvalidDescriptor;
                    const key = evaluated.inputs.key(row_index) orelse return error.InvalidDescriptor;
                    stable_edits[row_index + edit_offset] = .{ .insert = .{
                        .slot = slot,
                        .before_slot = 0,
                        .key = key,
                        .metadata = .{ .item_slot = slot, .scope_id = row_scope_id.raw(), .row_handle = row.row_handle.raw() },
                    } };
                }
                evaluated.inputs.rows_transition = if (existing_rows_site_id != null)
                    rows_transition.PreparedTransition.prepareStable(allocator, rows_store, rows_site_id, (rows_store.getSiteConst(rows_site_id) catch return error.InvalidDescriptor).owner_token, owner, stable_edits) catch |err| return switch (err) {
                        error.OutOfMemory => error.OutOfMemory,
                        error.ResourceLimit => error.ResourceLimit,
                        else => error.InvalidDescriptor,
                    }
                else
                    rows_transition.PreparedTransition.prepareInitial(allocator, rows_store, rows_site_id, owner, stable_edits) catch |err| return switch (err) {
                        error.OutOfMemory => error.OutOfMemory,
                        error.ResourceLimit => error.ResourceLimit,
                        else => error.InvalidDescriptor,
                    };

                evaluated.inputs.rows_transition.?.prepareRenderSpanUpdates(row_render_ranges.len) catch |err| return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    error.ResourceLimit => error.ResourceLimit,
                    else => error.InvalidDescriptor,
                };
                self.row_render_span_intents.ensureUnusedCapacity(allocator, row_render_ranges.len) catch return error.OutOfMemory;

                try self.appendConstructionPosition(scope_id, parent_elem_id, .marker(node_id, .each_end));

                // Transfer the only still-fallible owner first. If growing
                // this journal refuses, the local errdefers remain the sole
                // owners of the site descriptors and row table. Once it
                // succeeds, every remaining append is capacity-preflighted
                // and the collection owns the complete initial each.
                const input_index = self.prepared_initial_each_inputs.items.len;
                self.prepared_initial_each_inputs.append(allocator, evaluated.inputs) catch return error.OutOfMemory;
                evaluated.owns_inputs = false;
                self.prepared_state_sites.appendAssumeCapacity(site);
                self.prepared_eaches.appendAssumeCapacity(prepared_each);
                self.prepared_each_sites.appendAssumeCapacity(prepared_site);
                for (row_render_ranges) |range| self.row_render_span_intents.appendAssumeCapacity(.{ .owner = .{ .initial = input_index }, .range = range });
                ordinal.* = ids.SiteOrdinal.fromRaw(ordinal.*.raw() + 1);
            }

            /// Appends the render parent of every live nested site this
            /// collection reconciled, once each and skipping parents already
            /// listed: surviving rows and collected ones interleave under
            /// such a parent, so its final child order must come from the
            /// render topology rather than the structural pass.
            fn appendNestedSiteRenderParents(self: *const @This(), allocator: std.mem.Allocator, parents: *shared_buffer.List(u64)) CollectionError!void {
                for (self.nested_row_syncs.items) |*sync| {
                    const parent_id = sync.parent_elem_id.raw();
                    const listed = for (parents.items) |existing| {
                        if (existing == parent_id) break true;
                    } else false;
                    if (!listed) parents.append(allocator, parent_id) catch return error.OutOfMemory;
                }
            }

            /// The committed each site `scope_id` and `site_ordinal` name,
            /// when `scope_id` is a committed scope this collection
            /// re-collects rather than one it creates. A scope this
            /// transaction claims can only occupy an inactive slot, so an
            /// active slot under the collected id is the committed scope.
            fn liveEachSiteIndex(self: *const @This(), scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal) ?usize {
                if (scope_id.index() >= self.engine.scopes.items.len) return null;
                if (!self.engine.scopes.items[scope_id.index()].lifecycle.isActive()) return null;
                return self.engine.activeEachRowSiteIndex(scope_id, site_ordinal);
            }

            /// Reconciles the committed rows of the live site `site_index`
            /// against the items its re-collected parent row now produces.
            /// A survivor keeps its scope; one whose item changed, or whose
            /// subtree reads a dirty source, is re-collected in place exactly
            /// as its parent row was, and is otherwise left untouched. A
            /// created row claims a scope from the plan and mounts here; a
            /// removed row retires with the enclosing subtree journal. The
            /// site's next order is recorded as layout pieces so the render
            /// layout plan keeps surviving render nodes where they stand.
            fn prepareNestedDirectRows(
                self: *@This(),
                scope_id: ids.ScopeId,
                site_ordinal: ids.SiteOrdinal,
                site_index: usize,
                rows_site_id: rows_site_store.SiteId,
                parent_owner: rows_site_store.OwnerToken,
                inputs: *PreparedEachInputs,
            ) CollectionError!each_runtime.PreparedRowSync {
                const allocator = Ctx.allocator(self.host_ctx);
                const engine_ptr = self.engine;
                const rows_store = engine_ptr.rowsStore(allocator);
                const delta = if (inputs.delta) |*value| value else return error.InvalidDescriptor;
                if (!delta.complete) return error.InvalidDescriptor;
                const edits = allocator.alloc(rows_transition.StableEdit, delta.ops.items.len) catch return error.OutOfMemory;
                defer allocator.free(edits);

                for (delta.ops.items, edits) |op, *edit| edit.* = switch (op) {
                    .clear => .clear,
                    .move => |value| .{ .move = .{ .first_slot = value.first_slot, .count = value.count, .before_slot = value.before_slot } },
                    .remove => |value| .{ .remove = .{ .first_slot = value.first_slot, .count = value.count } },
                    .update => |value| blk: {
                        const key = delta.keys.key(value.key_index) orelse return error.InvalidDescriptor;
                        const row_id = (rows_store.findItemSlot(rows_site_id, value.slot) catch return error.InvalidDescriptor) orelse return error.InvalidDescriptor;
                        const row = rows_store.getRowConst(rows_site_id, row_id) catch return error.InvalidDescriptor;
                        if (row.metadata.row_handle == 0) return error.InvalidDescriptor;
                        inputs.candidate_bindings.putAssumeCapacity(row_handles.RowHandleId.fromRaw(row.metadata.row_handle), .{
                            .generation_id = inputs.generation.id,
                            .item_slot = value.slot,
                        }, .{ .delta = value.key_index }) catch return error.InvalidDescriptor;
                        break :blk .{ .update = .{
                            .slot = value.slot,
                            .key = key,
                            .metadata = row.metadata,
                        } };
                    },
                    .insert => |value| blk: {
                        const key = delta.keys.key(value.key_index) orelse return error.InvalidDescriptor;
                        if (value.key_index >= delta.keys.hashes.items.len) return error.InvalidDescriptor;
                        const row_handle = engine_ptr.row_handle_registry.insert(allocator, {}) catch |err| return switch (err) {
                            error.OutOfMemory => error.OutOfMemory,
                            error.ResourceLimit => error.ResourceLimit,
                        };
                        inputs.created_handles.append(allocator, row_handle) catch {
                            _ = engine_ptr.row_handle_registry.remove(row_handle) catch unreachable;
                            return error.OutOfMemory;
                        };
                        const row_scope_id = try self.reserveEachRowScopeGeneration(scope_id, site_ordinal, delta.keys.hashes.items[value.key_index], row_handle);
                        inputs.candidate_bindings.putAssumeCapacity(row_handle, .{
                            .generation_id = inputs.generation.id,
                            .item_slot = value.slot,
                        }, .{ .delta = value.key_index }) catch return error.InvalidDescriptor;
                        break :blk .{ .insert = .{
                            .slot = value.slot,
                            .before_slot = value.before_slot,
                            .key = key,
                            .metadata = .{
                                .item_slot = value.slot,
                                .scope_id = row_scope_id.raw(),
                                .row_handle = row_handle.raw(),
                            },
                        } };
                    },
                };

                const next_owner = rows_site_store.OwnerToken.fromRaw(inputs.generation.rows_generation) catch return error.InvalidDescriptor;
                inputs.rows_transition = rows_transition.PreparedTransition.prepareStable(
                    allocator,
                    rows_store,
                    rows_site_id,
                    parent_owner,
                    next_owner,
                    edits,
                ) catch |err| return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    error.ResourceLimit => error.ResourceLimit,
                    else => error.InvalidDescriptor,
                };
                const transition = &inputs.rows_transition.?;
                if (transition.candidateLen() != inputs.generation.item_count) return error.InvalidDescriptor;

                const binding_edits = std.math.add(usize, delta.ops.items.len, transition.removedRows().len) catch return error.ResourceLimit;
                inputs.candidate_bindings.reserve(binding_edits) catch |err| return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    error.ResourceLimit => error.ResourceLimit,
                };

                const next_scope_ids = allocator.alloc(ids.ScopeId, transition.candidateLen()) catch return error.OutOfMemory;
                errdefer allocator.free(next_scope_ids);
                const key_hashes = allocator.alloc(u64, transition.candidateLen()) catch return error.OutOfMemory;
                errdefer allocator.free(key_hashes);
                const item_changed = allocator.alloc(bool, transition.candidateLen()) catch return error.OutOfMemory;
                errdefer allocator.free(item_changed);
                const scope_created = allocator.alloc(bool, transition.candidateLen()) catch return error.OutOfMemory;
                errdefer allocator.free(scope_created);
                const removed_scope_ids = allocator.alloc(ids.ScopeId, transition.removedRows().len) catch return error.OutOfMemory;
                errdefer allocator.free(removed_scope_ids);

                var highest_scope_id = ids.root_scope;
                var created_count: usize = 0;
                var candidate = transition.iterateCandidate();
                var index: usize = 0;
                while (candidate.next()) |row| : (index += 1) {
                    if (index >= next_scope_ids.len or row.metadata.row_handle == 0 or row.metadata.item_slot == 0) return error.InvalidDescriptor;
                    const row_scope_id = ids.ScopeId.fromRaw(row.metadata.scope_id);
                    next_scope_ids[index] = row_scope_id;
                    key_hashes[index] = std.hash.Wyhash.hash(0, row.key);
                    item_changed[index] = row.item_changed;
                    scope_created[index] = row.created;
                    if (row.created) created_count += 1;
                    if (row_scope_id.raw() > highest_scope_id.raw()) highest_scope_id = row_scope_id;
                }
                if (index != next_scope_ids.len) return error.InvalidDescriptor;

                for (transition.removedRows(), removed_scope_ids) |row_id, *removed_scope_id| {
                    const row = rows_store.getRowConst(rows_site_id, row_id) catch return error.InvalidDescriptor;
                    if (row.metadata.row_handle == 0) return error.InvalidDescriptor;
                    removed_scope_id.* = ids.ScopeId.fromRaw(row.metadata.scope_id);
                    inputs.candidate_bindings.removeAssumeCapacity(row_handles.RowHandleId.fromRaw(row.metadata.row_handle)) catch return error.InvalidDescriptor;
                }

                const legacy_site = &engine_ptr.each_row_sites.items[site_index];
                legacy_site.scope_ids.ensureTotalCapacity(allocator, next_scope_ids.len) catch return error.OutOfMemory;
                legacy_site.hash_links.ensureTotalCapacity(allocator, next_scope_ids.len) catch return error.OutOfMemory;
                legacy_site.hash_heads.ensureTotalCapacity(allocator, std.math.cast(u32, next_scope_ids.len) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                engine_ptr.each_row_memberships_by_scope_id.ensureTotalCapacity(allocator, std.math.add(usize, highest_scope_id.index(), 1) catch return error.ResourceLimit) catch return error.OutOfMemory;

                return .{
                    .allocator = allocator,
                    .site_index = site_index,
                    .next_scope_ids = next_scope_ids,
                    .key_hashes = key_hashes,
                    .row_items_changed = item_changed,
                    .scope_created = scope_created,
                    .removed_scope_ids = removed_scope_ids,
                    .created_count = created_count,
                    .highest_scope_id = highest_scope_id,
                };
            }

            fn collectNestedRowSync(self: *@This(), roc_host: *abi.RocHost, scope_id: ids.ScopeId, parent_elem_id: ids.ElemId, site_ordinal: ids.SiteOrdinal, site_index: usize, each: *const HostNodeEachDesc, binder_stack: *shared_buffer.List(HostBinderBinding), dirty_source_node_ids: []const u64) CollectionError!void {
                const allocator = Ctx.allocator(self.host_ctx);
                const engine_ptr = self.engine;
                self.signal_roc_host = roc_host;
                self.nested_row_syncs.ensureUnusedCapacity(allocator, 1) catch return error.OutOfMemory;
                const old_site = engine_ptr.activeScopeSiteByNodeId(each.node_id.raw(), .each) orelse return error.InvalidDescriptor;
                if (old_site.scope_id != scope_id or old_site.ordinal != site_ordinal) return error.InvalidDescriptor;

                const rows_key = each_runtime.SiteKey{ .parent_scope_id = scope_id, .site_ordinal = site_ordinal };
                const rows_site_id = engine_ptr.rows_site_ids.get(rows_key) orelse return error.InvalidDescriptor;
                const rows_store = engine_ptr.rowsStore(allocator);
                const parent_owner = (rows_store.getSiteConst(rows_site_id) catch return error.InvalidDescriptor).owner_token;
                var inputs = try PreparedEachInputs.prepareWithOverlay(engine_ptr, self.host_ctx, roc_host, each, allocator, null, self.prepared_state_cells.items, parent_owner.raw());
                errdefer inputs.deinit();
                inputs.rows_site_id = rows_site_id;
                inputs.rows_site_key = rows_key;
                inputs.rows_site_published = true;
                const direct_delta = inputs.delta != null and !inputs.snapshot.complete;
                // Which rows the reconciliation creates is its own decision,
                // so the plan takes the row count as the bound on the scopes
                // it may claim: every next row is either created here or a
                // committed survivor this collection may attach.
                const scope_bound = if (inputs.delta) |delta| delta.ops.items.len else inputs.keys.len;
                try self.reserveCounts(.{ .external_scopes = scope_bound, .each_rows = scope_bound });
                var hooks = StagedEachRowSyncHooks.init(self, roc_host, &inputs);
                engine_ptr.recordEachSync(inputs.generation.item_count, engine_ptr.each_row_sites.items[site_index].scope_ids.items.len);
                var rows = if (direct_delta)
                    try self.prepareNestedDirectRows(scope_id, site_ordinal, site_index, rows_site_id, parent_owner, &inputs)
                else blk: {
                    const binding_edits = std.math.add(usize, inputs.generation.item_count, engine_ptr.each_row_sites.items[site_index].scope_ids.items.len) catch return error.ResourceLimit;
                    inputs.candidate_bindings.reserve(binding_edits) catch |err| return switch (err) {
                        error.OutOfMemory => error.OutOfMemory,
                        error.ResourceLimit => error.ResourceLimit,
                    };
                    break :blk each_runtime.PreparedRowSync.prepare(allocator, &engine_ptr.each_row_sites, &engine_ptr.each_row_memberships_by_scope_id, site_index, scope_id, site_ordinal, inputs.keys, inputs.items, &hooks) catch |err| switch (err) {
                        error.OutOfMemory => return error.OutOfMemory,
                        error.ResourceLimit => return error.ResourceLimit,
                    };
                };
                errdefer {
                    rows.abort(&hooks);
                    rows.deinit();
                }
                if (!direct_delta) {
                    const next_owner = rows_site_store.OwnerToken.fromRaw(inputs.generation.rows_generation) catch return error.InvalidDescriptor;
                    const stable_edit_count = std.math.add(usize, rows.next_scope_ids.len, 1) catch return error.ResourceLimit;
                    const stable_edits = allocator.alloc(rows_transition.StableEdit, stable_edit_count) catch return error.OutOfMemory;
                    defer allocator.free(stable_edits);
                    stable_edits[0] = .clear;
                    for (rows.next_scope_ids, 0..) |row_scope_id, row_index| {
                        const slot = inputs.slot(row_index) orelse return error.InvalidDescriptor;
                        const key = inputs.key(row_index) orelse return error.InvalidDescriptor;
                        const row_handle = inputs.row_handles_by_index[row_index] orelse return error.InvalidDescriptor;
                        stable_edits[row_index + 1] = .{ .insert = .{
                            .slot = slot,
                            .before_slot = 0,
                            .key = key,
                            .metadata = .{
                                .item_slot = slot,
                                .scope_id = row_scope_id.raw(),
                                .row_handle = row_handle.raw(),
                            },
                        } };
                    }
                    inputs.rows_transition = rows_transition.PreparedTransition.prepareStable(allocator, rows_store, rows_site_id, parent_owner, next_owner, stable_edits) catch |err| return switch (err) {
                        error.OutOfMemory => error.OutOfMemory,
                        error.ResourceLimit => error.ResourceLimit,
                        else => error.InvalidDescriptor,
                    };
                }
                for (rows.removed_scope_ids) |removed_scope_id| {
                    const row_handle = scope_runtime.eachRowHandle(engine_ptr.scopes.items, removed_scope_id);
                    inputs.candidate_bindings.removeAssumeCapacity(row_handle) catch return error.InvalidDescriptor;
                }
                inputs.candidate_bindings.preflightCommit(&engine_ptr.committed_row_bindings) catch |err| return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    error.ResourceLimit => error.ResourceLimit,
                };
                self.candidate_binding_edit_count = std.math.add(usize, self.candidate_binding_edit_count, inputs.candidate_bindings.candidate.count()) catch return error.ResourceLimit;
                const committed_binding_bound = std.math.add(usize, engine_ptr.committed_row_bindings.entries.count(), self.candidate_binding_edit_count) catch return error.ResourceLimit;
                engine_ptr.committed_row_bindings.entries.ensureTotalCapacity(allocator, std.math.cast(u32, committed_binding_bound) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                self.candidate_generation_count = std.math.add(usize, self.candidate_generation_count, 1) catch return error.ResourceLimit;
                engine_ptr.each_generations.ensureUnusedCapacity(allocator, std.math.cast(u32, self.candidate_generation_count) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                const site_slot_count = std.math.add(usize, site_index, 1) catch return error.ResourceLimit;
                engine_ptr.each_generation_ids_by_site_index.ensureTotalCapacity(allocator, site_slot_count) catch return error.OutOfMemory;
                try self.indexCandidateGeneration(&inputs);

                const row_count = rows.next_scope_ids.len;
                const recollected = allocator.alloc(bool, row_count) catch return error.OutOfMemory;
                errdefer allocator.free(recollected);
                var row_render_ranges: shared_buffer.List(RowRenderSpanRange) = .empty;
                defer row_render_ranges.deinit(allocator);
                var collected_item_slots: std.AutoHashMapUnmanaged(u64, u64) = .empty;
                defer collected_item_slots.deinit(allocator);
                const row_elems = allocator.alloc(?abi.Elem, row_count) catch return error.OutOfMemory;
                defer allocator.free(row_elems);
                @memset(row_elems, null);
                defer for (row_elems) |maybe_elem| if (maybe_elem) |elem| elem.decref(roc_host);
                var total: StaticRootCounts = .{};
                var sparse_row_elems: std.AutoHashMapUnmanaged(u64, abi.Elem) = .empty;
                defer {
                    var values = sparse_row_elems.valueIterator();
                    while (values.next()) |elem| elem.decref(roc_host);
                    sparse_row_elems.deinit(allocator);
                }
                if (direct_delta) {
                    const candidate_rows = PreparedActiveEachRows.CandidateRows{ .transition = &inputs.rows_transition.? };
                    const sparse_bound = std.math.add(usize, candidate_rows.createdLen(), candidate_rows.changedUpperBound()) catch return error.ResourceLimit;
                    sparse_row_elems.ensureTotalCapacity(allocator, std.math.cast(u32, sparse_bound) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                    var created_candidates = candidate_rows.iterateCreated();
                    while (try created_candidates.next()) |candidate| {
                        const elem = retained_values.callEachRowBuilder(roc_host, each.ops.row, abi.RocStr.fromSlice(candidate.key, roc_host), candidate.row_handle.raw());
                        errdefer elem.decref(roc_host);
                        try PreparedReplacementOwner.addRootCounts(&total, try countStaticRootNodes(elem));
                        const entry = sparse_row_elems.getOrPutAssumeCapacity(candidate.scope_id.raw());
                        if (entry.found_existing) return error.InvalidDescriptor;
                        entry.value_ptr.* = elem;
                    }
                    var changed_candidates = candidate_rows.iterateChanged();
                    while (try changed_candidates.next()) |candidate| {
                        const elem = retained_values.callEachRowBuilder(roc_host, each.ops.row, abi.RocStr.fromSlice(candidate.key, roc_host), candidate.row_handle.raw());
                        errdefer elem.decref(roc_host);
                        try PreparedReplacementOwner.addRootCounts(&total, try countStaticRootNodes(elem));
                        const entry = sparse_row_elems.getOrPutAssumeCapacity(candidate.scope_id.raw());
                        if (entry.found_existing) return error.InvalidDescriptor;
                        entry.value_ptr.* = elem;
                    }
                }
                const previous_bindings = engine_ptr.active_each_candidate_bindings;
                const previous_inputs = engine_ptr.active_each_candidate_inputs;
                const previous_generation = engine_ptr.active_each_candidate_generation;
                const previous_rows_site_id = engine_ptr.active_each_candidate_rows_site_id;
                engine_ptr.active_each_candidate_bindings = &inputs.candidate_bindings;
                engine_ptr.active_each_candidate_inputs = &inputs;
                engine_ptr.active_each_candidate_generation = inputs.generation;
                engine_ptr.active_each_candidate_rows_site_id = inputs.rows_site_id;
                defer {
                    engine_ptr.active_each_candidate_bindings = previous_bindings;
                    engine_ptr.active_each_candidate_inputs = previous_inputs;
                    engine_ptr.active_each_candidate_generation = previous_generation;
                    engine_ptr.active_each_candidate_rows_site_id = previous_rows_site_id;
                }
                var direct_candidate: ?PreparedActiveEachRows.CandidateIterator = if (direct_delta)
                    (PreparedActiveEachRows.CandidateRows{ .transition = &inputs.rows_transition.? }).iterate()
                else
                    null;
                for (rows.next_scope_ids, rows.scope_created, rows.row_items_changed, 0..) |row_scope_id, created, changed, index| {
                    const candidate_row: ?PreparedActiveEachRows.CandidateRow = if (direct_delta)
                        (try direct_candidate.?.next()) orelse return error.InvalidDescriptor
                    else
                        null;
                    const item_slot = if (candidate_row) |candidate| candidate.item_slot else inputs.slot(index) orelse return error.InvalidDescriptor;
                    if (candidate_row) |candidate| {
                        if (candidate.scope_id != row_scope_id or candidate.created != created or candidate.item_changed != changed) return error.InvalidDescriptor;
                    }
                    const structurally_dirty = !created and engine_ptr.scopeSubtreeHasDirtyStructuralSource(&engine_ptr.active_stream, row_scope_id.raw(), dirty_source_node_ids);
                    recollected[index] = !created and (changed or structurally_dirty);
                    if (!created and !recollected[index]) continue;
                    collected_item_slots.put(allocator, row_scope_id.raw(), item_slot) catch return error.OutOfMemory;
                    if (direct_delta) {
                        if (sparse_row_elems.fetchRemove(row_scope_id.raw())) |built| {
                            row_elems[index] = built.value;
                            continue;
                        }
                        if (!structurally_dirty) return error.InvalidDescriptor;
                    }
                    const key = if (candidate_row) |candidate| candidate.key else inputs.key(index) orelse return error.InvalidDescriptor;
                    const row_handle = if (candidate_row) |candidate| candidate.row_handle else inputs.row_handles_by_index[index] orelse return error.InvalidDescriptor;
                    const elem = retained_values.callEachRowBuilder(roc_host, each.ops.row, abi.RocStr.fromSlice(key, roc_host), row_handle.raw());
                    row_elems[index] = elem;
                    try PreparedReplacementOwner.addRootCounts(&total, try countStaticRootNodes(elem));
                }
                if (direct_candidate) |*candidate| if ((try candidate.next()) != null) return error.InvalidDescriptor;
                if (sparse_row_elems.count() != 0) return error.InvalidDescriptor;
                try self.reserveCounts(.{ .roots = total });

                var segments: shared_buffer.List(HostEachRowRenderSegment) = .empty;
                defer segments.deinit(allocator);
                const old_end = try engine_ptr.appendEachSiteRenderSegments(allocator, .{ .parent_scope_id = scope_id, .site_ordinal = site_ordinal }, old_site.render_insert_index, &segments);
                const old_start = if (segments.items.len != 0) segments.items[0].start else old_site.render_insert_index;

                const pieces = allocator.alloc(PreparedRenderLayoutPlan.Piece, row_count) catch return error.OutOfMemory;
                errdefer allocator.free(pieces);
                const local_render_start = self.prepared_render_order.items.len;
                const local_site_start = self.prepared_state_sites.items.len;
                // A surviving row that renders nothing has no span of its
                // own; it sits after the previous survivor, or at the site.
                var survivor_cursor = old_start;
                for (rows.next_scope_ids, rows.scope_created, 0..) |row_scope_id, created, index| {
                    if (row_elems[index]) |elem| {
                        if (!created) self.scopes.reserveExternal(row_scope_id) catch |err| switch (err) {
                            error.NoCapacity => return error.ResourceLimit,
                            error.DuplicateScope => return error.InvalidScope,
                        };
                        const render_start = self.prepared_render_order.items.len;
                        const site_start = self.prepared_state_sites.items.len;
                        var row_ordinal = ids.SiteOrdinal.fromRaw(0);
                        var row_dom_ordinal = ids.SiteOrdinal.fromRaw(0);
                        try engine_ptr.collectActiveEachRowElemDescriptorsWith(*Collection, self, self.host_ctx, roc_host, self.stream, each.*, elem, row_scope_id, parent_elem_id, &row_ordinal, &row_dom_ordinal, binder_stack, created, dirty_source_node_ids);
                        row_render_ranges.append(allocator, .{
                            .item_slot = collected_item_slots.get(row_scope_id.raw()) orelse return error.InvalidDescriptor,
                            .parent_elem_id = parent_elem_id,
                            .start = render_start,
                            .len = self.prepared_render_order.items.len - render_start,
                        }) catch return error.OutOfMemory;
                        pieces[index] = .{ .replacement = .{
                            .render_start = render_start,
                            .render_len = self.prepared_render_order.items.len - render_start,
                            .site_start = site_start,
                            .site_len = self.prepared_state_sites.items.len - site_start,
                        } };
                        continue;
                    }
                    const segment = for (segments.items) |segment| {
                        if (segment.scope_id == row_scope_id) break segment;
                    } else null;
                    if (segment) |span| {
                        pieces[index] = .{ .survivor = .{ .scope_id = row_scope_id.raw(), .old_start = span.start, .len = span.len } };
                        survivor_cursor = span.start + span.len;
                    } else {
                        pieces[index] = .{ .survivor = .{ .scope_id = row_scope_id.raw(), .old_start = survivor_cursor, .len = 0 } };
                    }
                }

                // The caller appends the site's own descriptor next, so it
                // closes the span of scope sites this reconciliation created.
                const local_site_index = self.prepared_state_sites.items.len;
                inputs.rows_transition.?.prepareRenderSpanUpdates(row_render_ranges.items.len) catch |err| return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    error.ResourceLimit => error.ResourceLimit,
                    else => error.InvalidDescriptor,
                };
                self.row_render_span_intents.ensureUnusedCapacity(allocator, row_render_ranges.items.len) catch return error.OutOfMemory;
                const nested_sync_index = self.nested_row_syncs.items.len;
                self.nested_row_syncs.appendAssumeCapacity(.{
                    .allocator = allocator,
                    .node_id = each.node_id,
                    .parent_scope_id = scope_id,
                    .site_ordinal = site_ordinal,
                    .parent_elem_id = parent_elem_id,
                    .site_index = site_index,
                    .local_render_start = local_render_start,
                    .local_render_len = self.prepared_render_order.items.len - local_render_start,
                    .local_site_start = local_site_start,
                    .local_site_len = local_site_index + 1 - local_site_start,
                    .local_site_index = local_site_index,
                    .old_start = old_start,
                    .old_end = old_end,
                    .inputs = inputs,
                    .rows = rows,
                    .direct_delta = direct_delta,
                    .recollected = recollected,
                    .pieces = pieces,
                });
                for (row_render_ranges.items) |range| self.row_render_span_intents.appendAssumeCapacity(.{ .owner = .{ .nested = nested_sync_index }, .range = range });
            }

            fn appendConstructionPosition(self: *@This(), owner: ids.ScopeId, parent: ids.ElemId, position: structural_positions.PositionId) CollectionError!void {
                try self.budget.charge(0, @sizeOf(structural_positions.Entry));
                // External replacement rows can add their boundary pair after
                // static-root counts are known. Growth is still provisional,
                // charged to this collection, and released on refusal.
                self.construction_order.append(Ctx.allocator(self.host_ctx), .{ .owner = owner, .parent = parent, .position = position }) catch return error.OutOfMemory;
            }

            fn appendElement(self: *@This(), scope_id: ids.ScopeId, parent_elem_id: ids.ElemId, dom_ordinal: *ids.SiteOrdinal, tag: []const u8, namespace: render.ElementNamespace) CollectionError!ids.ElemId {
                const descriptor_bytes = std.math.add(usize, @sizeOf(HostElementDesc), tag.len) catch return error.ResourceLimit;
                try self.budget.charge(1, descriptor_bytes);
                const elem_id = try self.reserveDomIdentity(scope_id, dom_ordinal.*);
                try self.reserveScopeDescriptors(scope_id, 1, 0);
                const prepared = try self.stream.prepareElementInNamespace(Ctx.allocator(self.host_ctx), elem_id, parent_elem_id, scope_id, tag, namespace);
                self.prepared_nodes.appendAssumeCapacity(prepared);
                self.prepared_render_order.appendAssumeCapacity(.{ .static = self.prepared_nodes.items.len - 1 });
                try self.appendConstructionPosition(scope_id, parent_elem_id, .element(elem_id));
                dom_ordinal.* = ids.SiteOrdinal.fromRaw(dom_ordinal.*.raw() + 1);
                return elem_id;
            }

            fn appendText(self: *@This(), scope_id: ids.ScopeId, parent_elem_id: ids.ElemId, dom_ordinal: *ids.SiteOrdinal, value: []const u8) CollectionError!void {
                const descriptor_bytes = std.math.add(usize, @sizeOf(HostNodeTextNodeDesc), value.len) catch return error.ResourceLimit;
                try self.budget.charge(1, descriptor_bytes);
                const elem_id = try self.reserveDomIdentity(scope_id, dom_ordinal.*);
                try self.reserveScopeDescriptors(scope_id, 1, 0);
                const prepared = try self.stream.prepareTextNode(Ctx.allocator(self.host_ctx), elem_id, parent_elem_id, scope_id, value);
                self.prepared_nodes.appendAssumeCapacity(prepared);
                self.prepared_render_order.appendAssumeCapacity(.{ .static = self.prepared_nodes.items.len - 1 });
                try self.appendConstructionPosition(scope_id, parent_elem_id, .element(elem_id));
                dom_ordinal.* = ids.SiteOrdinal.fromRaw(dom_ordinal.*.raw() + 1);
            }

            fn appendSignalText(self: *@This(), roc_host: *abi.RocHost, scope_id: ids.ScopeId, parent_elem_id: ids.ElemId, dom_ordinal: *ids.SiteOrdinal, payload: abi_view.TextSignalElem, binder_stack: []const HostBinderBinding) CollectionError!void {
                try self.budget.charge(1, @sizeOf(HostNodeSignalTextNodeDesc));
                const elem_id = try self.reserveDomIdentity(scope_id, dom_ordinal.*);
                try self.reserveScopeDescriptors(scope_id, 1, 0);
                const signal = try self.bindSignalRoot(roc_host, payload.signal.*, binder_stack);
                const read = retainHostTextRead(payload.read, &self.engine.pending_roc_metrics);
                self.prepared_signal_attrs.appendAssumeCapacity(.{ .text_node = .{
                    .elem_id = elem_id,
                    .parent_elem_id = parent_elem_id,
                    .scope_id = scope_id,
                    .signal = signal,
                    .read = read,
                } });
                self.prepared_render_order.appendAssumeCapacity(.{ .signal = self.prepared_signal_attrs.items.len - 1 });
                self.signal_records.transferDescriptorRoot(signal.record);
                const journaled = self.signal_bindings.pop() orelse @panic("staged signal binding journal underflow");
                if (journaled.record != signal.record or journaled.source_node_ids.ptr != signal.source_node_ids.ptr or journaled.source_node_ids.len != signal.source_node_ids.len) @panic("staged signal binding journal transfer mismatch");
                try self.appendConstructionPosition(scope_id, parent_elem_id, .element(elem_id));
                dom_ordinal.* = ids.SiteOrdinal.fromRaw(dom_ordinal.*.raw() + 1);
            }

            fn prepareEventHandler(self: *@This(), roc_host: *abi.RocHost, scope_id: ids.ScopeId, msg: abi_view.EventMessage, binder_stack: []const HostBinderBinding) CollectionError!descriptor_stream.EventHandler {
                self.signal_roc_host = roc_host;
                return switch (msg.handler) {
                    .reduce => |handler| .{ .reduce = .{
                        .binder_token = handler.binder.callable,
                        .target_node_id = ids.NodeId.fromRaw(resolveNodeBinderRef(binder_stack, handler.binder.callable)),
                        .read_binder_token = handler.read_binder.callable,
                        .read_node_id = ids.NodeId.fromRaw(resolveNodeBinderRef(binder_stack, handler.read_binder.callable)),
                        .payload_reducer = retainHostEventReducer(handler.payload_reducer, &self.engine.pending_roc_metrics),
                    } },
                    .action => |handler| blk: {
                        const reads = try self.bindSignalRoot(roc_host, handler.reads.*, binder_stack);
                        // No fallible operation follows the journal transfer.
                        self.signal_records.transferDescriptorRoot(reads.record);
                        const journaled = self.signal_bindings.pop() orelse @panic("staged action read journal underflow");
                        if (journaled.record != reads.record or journaled.source_node_ids.ptr != reads.source_node_ids.ptr or journaled.source_node_ids.len != reads.source_node_ids.len) @panic("staged action read journal transfer mismatch");
                        const payload_cap = retained_values.retainHostValueCapability(handler.payload_cap, &self.engine.pending_roc_metrics);
                        abi.increfErasedCallable(handler.to_cmd.toAbi(), 1);
                        self.engine.pending_roc_metrics.bump(.closure_retains, 1);
                        break :blk .{ .action = .{
                            .scope_id = scope_id,
                            .reads = reads,
                            .payload_cap = payload_cap,
                            .to_cmd = handler.to_cmd,
                        } };
                    },
                };
            }

            fn appendAttr(self: *@This(), roc_host: *abi.RocHost, scope_id: ids.ScopeId, elem_id: ids.ElemId, attr: abi.NodeAttr, binder_stack: []const HostBinderBinding) CollectionError!void {
                const prepared = switch (abi_view.NodeAttr.fromAbi(attr)) {
                    .signal_text => |payload| switch (payload.target) {
                        .fixed => |field| {
                            try self.budget.charge(0, @sizeOf(HostNodeSignalTextAttrDesc));
                            const signal = try self.bindSignalRoot(roc_host, payload.signal.*, binder_stack);
                            const read = retainHostTextRead(payload.read, &self.engine.pending_roc_metrics);
                            self.prepared_signal_attrs.appendAssumeCapacity(.{ .text_attr = .{
                                .elem_id = elem_id,
                                .field = field,
                                .signal = signal,
                                .read = read,
                            } });
                            self.signal_records.transferDescriptorRoot(signal.record);
                            const journaled = self.signal_bindings.pop() orelse @panic("staged signal binding journal underflow");
                            if (journaled.record != signal.record or journaled.source_node_ids.ptr != signal.source_node_ids.ptr or journaled.source_node_ids.len != signal.source_node_ids.len) {
                                @panic("staged signal binding journal transfer mismatch");
                            }
                            return;
                        },
                        .custom => |name| {
                            const name_slice = name.asSlice();
                            if (name_slice.len == 0 or self.customAttrExists(elem_id, name_slice)) return error.InvalidDescriptor;
                            const bytes = std.math.add(usize, @sizeOf(HostNodeSignalCustomTextAttrDesc), name_slice.len) catch return error.ResourceLimit;
                            try self.budget.charge(0, bytes);
                            const allocator = Ctx.allocator(self.host_ctx);
                            try self.stream.reservePreparedCustomAttrEntry(allocator, elem_id.raw());
                            const name_copy = allocator.dupe(u8, name_slice) catch return error.OutOfMemory;
                            errdefer allocator.free(name_copy);
                            const signal = try self.bindSignalRoot(roc_host, payload.signal.*, binder_stack);
                            const read = retainHostTextRead(payload.read, &self.engine.pending_roc_metrics);
                            self.prepared_signal_attrs.appendAssumeCapacity(.{ .custom_text_attr = .{
                                .elem_id = elem_id,
                                .name = name_copy,
                                .signal = signal,
                                .read = read,
                            } });
                            self.rememberPreparedCustomAttr(elem_id, name_copy);
                            self.signal_records.transferDescriptorRoot(signal.record);
                            const journaled = self.signal_bindings.pop() orelse @panic("staged signal binding journal underflow");
                            if (journaled.record != signal.record or journaled.source_node_ids.ptr != signal.source_node_ids.ptr or journaled.source_node_ids.len != signal.source_node_ids.len) {
                                @panic("staged signal binding journal transfer mismatch");
                            }
                            return;
                        },
                    },
                    .signal_optional_text => |payload| switch (payload.target) {
                        .fixed => return error.InvalidDescriptor,
                        .custom => |name| {
                            const name_slice = name.asSlice();
                            if (name_slice.len == 0 or self.customAttrExists(elem_id, name_slice)) return error.InvalidDescriptor;
                            const bytes = std.math.add(usize, @sizeOf(HostNodeSignalOptionalCustomTextAttrDesc), name_slice.len) catch return error.ResourceLimit;
                            try self.budget.charge(0, bytes);
                            const allocator = Ctx.allocator(self.host_ctx);
                            try self.stream.reservePreparedCustomAttrEntry(allocator, elem_id.raw());
                            const name_copy = allocator.dupe(u8, name_slice) catch return error.OutOfMemory;
                            errdefer allocator.free(name_copy);
                            const signal = try self.bindSignalRoot(roc_host, payload.signal.*, binder_stack);
                            const present = retainHostBoolRead(payload.present, &self.engine.pending_roc_metrics);
                            const read = retainHostTextRead(payload.read, &self.engine.pending_roc_metrics);
                            self.prepared_signal_attrs.appendAssumeCapacity(.{ .optional_custom_text_attr = .{
                                .elem_id = elem_id,
                                .name = name_copy,
                                .signal = signal,
                                .present = present,
                                .read = read,
                            } });
                            self.rememberPreparedCustomAttr(elem_id, name_copy);
                            self.signal_records.transferDescriptorRoot(signal.record);
                            const journaled = self.signal_bindings.pop() orelse @panic("staged signal binding journal underflow");
                            if (journaled.record != signal.record or journaled.source_node_ids.ptr != signal.source_node_ids.ptr or journaled.source_node_ids.len != signal.source_node_ids.len) @panic("staged signal binding journal transfer mismatch");
                            return;
                        },
                    },
                    .signal_bool => |payload| switch (payload.target) {
                        .fixed => |field| {
                            try self.budget.charge(0, @sizeOf(HostNodeSignalBoolAttrDesc));
                            const signal = try self.bindSignalRoot(roc_host, payload.signal.*, binder_stack);
                            const read = retainHostBoolRead(payload.read, &self.engine.pending_roc_metrics);
                            self.prepared_signal_attrs.appendAssumeCapacity(.{ .bool_attr = .{
                                .elem_id = elem_id,
                                .field = field,
                                .signal = signal,
                                .read = read,
                            } });
                            self.signal_records.transferDescriptorRoot(signal.record);
                            const journaled = self.signal_bindings.pop() orelse @panic("staged signal binding journal underflow");
                            if (journaled.record != signal.record or journaled.source_node_ids.ptr != signal.source_node_ids.ptr or journaled.source_node_ids.len != signal.source_node_ids.len) {
                                @panic("staged signal binding journal transfer mismatch");
                            }
                            return;
                        },
                        .custom => |name| {
                            const name_slice = name.asSlice();
                            if (name_slice.len == 0 or self.customAttrExists(elem_id, name_slice)) return error.InvalidDescriptor;
                            const bytes = std.math.add(usize, @sizeOf(HostNodeSignalCustomBoolAttrDesc), name_slice.len) catch return error.ResourceLimit;
                            try self.budget.charge(0, bytes);
                            const allocator = Ctx.allocator(self.host_ctx);
                            try self.stream.reservePreparedCustomAttrEntry(allocator, elem_id.raw());
                            const name_copy = allocator.dupe(u8, name_slice) catch return error.OutOfMemory;
                            errdefer allocator.free(name_copy);
                            const signal = try self.bindSignalRoot(roc_host, payload.signal.*, binder_stack);
                            const read = retainHostBoolRead(payload.read, &self.engine.pending_roc_metrics);
                            self.prepared_signal_attrs.appendAssumeCapacity(.{ .custom_bool_attr = .{
                                .elem_id = elem_id,
                                .name = name_copy,
                                .signal = signal,
                                .read = read,
                            } });
                            self.rememberPreparedCustomAttr(elem_id, name_copy);
                            self.signal_records.transferDescriptorRoot(signal.record);
                            const journaled = self.signal_bindings.pop() orelse @panic("staged signal binding journal underflow");
                            if (journaled.record != signal.record or journaled.source_node_ids.ptr != signal.source_node_ids.ptr or journaled.source_node_ids.len != signal.source_node_ids.len) @panic("staged signal binding journal transfer mismatch");
                            return;
                        },
                    },
                    .event => |payload| {
                        try self.budget.charge(0, @sizeOf(HostNodeEventDesc));
                        const handler = try self.prepareEventHandler(roc_host, scope_id, payload.msg, binder_stack);
                        self.prepared_events.appendAssumeCapacity(.{ .desc = .{
                            .elem_id = elem_id,
                            .binding = .{ .fixed = payload.kind },
                            .delivery_request = payload.delivery_request,
                            .payload_descriptor = payload.msg.payload_descriptor,
                            .handler = handler,
                        } });
                        return;
                    },
                    .named_event => |payload| {
                        const name = payload.name.asSlice();
                        if (name.len == 0 or self.namedEventExists(elem_id, name, payload.key_chord)) return error.InvalidDescriptor;
                        if (payload.key_chord != null) {
                            if (comptime @hasDecl(Ctx, "supports_native_shortcuts")) {
                                if (!Ctx.supports_native_shortcuts) return error.InvalidDescriptor;
                            }
                            if (!payload.msg.payload_descriptor.eql(BoundaryPayloadDescriptor.init(.unit, .none))) return error.InvalidDescriptor;
                            const required_policy = render.EventPolicy{ .prevent_default = true, .stop_propagation = true };
                            if (!payload.policy.eql(required_policy) or payload.delivery_request != .native) return error.InvalidDescriptor;
                            const shortcut_count = if (self.prepared_named_event_group_by_elem.get(elem_id.raw())) |group| self.prepared_named_event_groups.items[group].shortcut_count else self.existingShortcutCount(elem_id);
                            if (shortcut_count >= @import("key_chord.zig").max_per_element) return error.ResourceLimit;
                        }
                        const bytes = std.math.add(usize, @sizeOf(HostNodeEventDesc), name.len) catch return error.ResourceLimit;
                        try self.budget.charge(0, bytes);
                        const group_index = try self.prepareNamedEventGroup(elem_id);
                        const allocator = Ctx.allocator(self.host_ctx);
                        const name_copy = allocator.dupe(u8, name) catch return error.OutOfMemory;
                        errdefer allocator.free(name_copy);
                        const handler = try self.prepareEventHandler(roc_host, scope_id, payload.msg, binder_stack);
                        const event_ordinal = self.prepared_events.items.len;
                        self.prepared_events.appendAssumeCapacity(.{ .desc = .{
                            .elem_id = elem_id,
                            .binding = .{ .named = .{
                                .name = name_copy,
                                .policy = payload.policy,
                                .delivery_request = payload.delivery_request,
                                .key_chord = payload.key_chord,
                            } },
                            .delivery_request = payload.delivery_request,
                            .payload_descriptor = payload.msg.payload_descriptor,
                            .handler = handler,
                        } });
                        self.prepared_named_event_groups.items[group_index].event_ordinals.appendAssumeCapacity(event_ordinal);
                        if (payload.key_chord != null) self.prepared_named_event_groups.items[group_index].shortcut_count += 1;
                        self.rememberPreparedNamedEvent(elem_id, name_copy, payload.key_chord);
                        return;
                    },
                    .static_text => |payload| switch (payload.target) {
                        .fixed => |field| blk: {
                            const bytes = std.math.add(usize, @sizeOf(HostNodeStaticTextAttrDesc), payload.value.asSlice().len) catch return error.ResourceLimit;
                            try self.budget.charge(0, bytes);
                            break :blk self.stream.prepareStaticTextAttr(Ctx.allocator(self.host_ctx), elem_id, field, payload.value.asSlice()) catch return error.OutOfMemory;
                        },
                        .custom => |name| blk: {
                            const name_slice = name.asSlice();
                            if (name_slice.len == 0 or self.customAttrExists(elem_id, name_slice)) return error.InvalidDescriptor;
                            const bytes = std.math.add(usize, @sizeOf(HostNodeStaticCustomTextAttrDesc), name_slice.len) catch return error.ResourceLimit;
                            const total = std.math.add(usize, bytes, payload.value.asSlice().len) catch return error.ResourceLimit;
                            try self.budget.charge(0, total);
                            const allocator = Ctx.allocator(self.host_ctx);
                            try self.stream.reservePreparedCustomAttrEntry(allocator, elem_id.raw());
                            break :blk self.stream.prepareStaticCustomTextAttr(allocator, elem_id, name_slice, payload.value.asSlice()) catch return error.OutOfMemory;
                        },
                    },
                    .static_bool => |payload| switch (payload.target) {
                        .fixed => |field| blk: {
                            try self.budget.charge(0, @sizeOf(HostNodeStaticBoolAttrDesc));
                            break :blk self.stream.prepareStaticBoolAttr(elem_id, field, payload.value);
                        },
                        .custom => |name| blk: {
                            const name_slice = name.asSlice();
                            if (name_slice.len == 0 or self.customAttrExists(elem_id, name_slice)) return error.InvalidDescriptor;
                            const bytes = std.math.add(usize, @sizeOf(HostNodeStaticCustomBoolAttrDesc), name_slice.len) catch return error.ResourceLimit;
                            try self.budget.charge(0, bytes);
                            const allocator = Ctx.allocator(self.host_ctx);
                            try self.stream.reservePreparedCustomAttrEntry(allocator, elem_id.raw());
                            break :blk self.stream.prepareStaticCustomBoolAttr(allocator, elem_id, name_slice, payload.value) catch return error.OutOfMemory;
                        },
                    },
                };
                self.prepared_attrs.appendAssumeCapacity(prepared);
                switch (prepared) {
                    .custom_text => |value| self.rememberPreparedCustomAttr(value.elem_id, value.name),
                    .custom_boolean => |value| self.rememberPreparedCustomAttr(value.elem_id, value.name),
                    .text, .boolean => {},
                }
            }

            fn appendCleanup(self: *@This(), roc_host: *abi.RocHost, scope_id: ids.ScopeId, name: []const u8) CollectionError!void {
                self.signal_roc_host = roc_host;
                const allocator = Ctx.allocator(self.host_ctx);
                try self.stream.reserveLifecycleScope(allocator, scope_id, self.prepared_lifecycle.capacity);
                const prepared = self.stream.prepareCleanup(allocator, scope_id, name) catch return error.OutOfMemory;
                self.prepared_lifecycle.appendAssumeCapacity(prepared);
            }

            fn appendMount(self: *@This(), roc_host: *abi.RocHost, scope_id: ids.ScopeId, to_cmd: CommandBuilderCallable, run_on_mount: bool) CollectionError!void {
                self.signal_roc_host = roc_host;
                const allocator = Ctx.allocator(self.host_ctx);
                try self.stream.reserveLifecycleScope(allocator, scope_id, self.prepared_lifecycle.capacity);
                self.prepared_lifecycle.appendAssumeCapacity(self.stream.prepareMount(to_cmd, scope_id, run_on_mount, &self.engine.pending_roc_metrics));
            }

            fn appendOnChange(self: *@This(), roc_host: *abi.RocHost, scope_id: ids.ScopeId, payload: abi_view.OnChangeElem, binder_stack: []const HostBinderBinding, scope_created: bool) CollectionError!void {
                const allocator = Ctx.allocator(self.host_ctx);
                try self.stream.reserveLifecycleScope(allocator, scope_id, self.prepared_lifecycle.capacity);
                const signal = try self.bindSignalRoot(roc_host, payload.signal.*, binder_stack);
                self.prepared_lifecycle.appendAssumeCapacity(self.stream.prepareOnChange(signal, payload.to_cmd, scope_id, payload.run_initial, payload.run_initial and scope_created, &self.engine.pending_roc_metrics));
                self.signal_records.transferDescriptorRoot(signal.record);
                const journaled = self.signal_bindings.pop() orelse @panic("staged lifecycle signal binding journal underflow");
                if (journaled.record != signal.record) @panic("staged lifecycle signal binding journal transfer mismatch");
            }

            fn customAttrExists(self: *@This(), elem_id: ids.ElemId, name: []const u8) bool {
                if (builtin.is_test) self.custom_attr_lookup_work += 1;
                if (self.stream.customTextAttrDescriptorExists(elem_id, name)) return true;
                return self.prepared_custom_attrs.contains(.{ .elem_id = elem_id.raw(), .name = name });
            }

            fn rememberPreparedCustomAttr(self: *@This(), elem_id: ids.ElemId, name: []const u8) void {
                const result = self.prepared_custom_attrs.getOrPutAssumeCapacity(.{ .elem_id = elem_id.raw(), .name = name });
                if (result.found_existing) @panic("custom attribute was staged without duplicate validation");
            }

            fn namedEventExists(self: *@This(), elem_id: ids.ElemId, name: []const u8, chord: ?@import("key_chord.zig").Chord) bool {
                if (builtin.is_test) self.named_event_lookup_work += 1;
                if (self.stream.namedEventDescriptorExists(elem_id, name, chord)) return true;
                return self.prepared_named_events.contains(.{ .elem_id = elem_id.raw(), .name = name, .key_chord = chord });
            }

            fn rememberPreparedNamedEvent(self: *@This(), elem_id: ids.ElemId, name: []const u8, chord: ?@import("key_chord.zig").Chord) void {
                const result = self.prepared_named_events.getOrPutAssumeCapacity(.{ .elem_id = elem_id.raw(), .name = name, .key_chord = chord });
                if (result.found_existing) @panic("named event was staged without duplicate validation");
            }

            fn existingShortcutCount(self: *@This(), elem_id: ids.ElemId) usize {
                var count: usize = 0;
                // Read this changed element's existing registrations once when
                // opening its prepared group, then maintain the count in O(1).
                for (self.stream.namedEventIndices(elem_id)) |index| {
                    if (self.stream.events.items[index].named().?.key_chord != null) count += 1;
                }
                return count;
            }

            /// A group's ordinals are appended during preparation, one per
            /// named event as it is collected, and only read when the group
            /// publishes; the per-event growth here is therefore additive
            /// preparation work rather than a publication reservation, and the
            /// group slot itself comes from the plan's attribute total.
            fn prepareNamedEventGroup(self: *@This(), elem_id: ids.ElemId) CollectionError!usize {
                const allocator = Ctx.allocator(self.host_ctx);
                if (self.prepared_named_event_group_by_elem.get(elem_id.raw())) |index| {
                    const group = &self.prepared_named_event_groups.items[index];
                    group.event_ordinals.ensureUnusedCapacity(allocator, 1) catch return error.OutOfMemory;
                    if (group.existed) try self.stream.reserveExistingNamedEventIndexes(allocator, elem_id.raw(), group.event_ordinals.items.len + 1);
                    return index;
                }
                var group = HostNodeDescriptorStream.PreparedNamedEventIndexGroup{
                    .elem_id = elem_id,
                    .existed = self.stream.namedEventIndexSlotExists(elem_id.raw()),
                    .shortcut_count = self.existingShortcutCount(elem_id),
                };
                errdefer group.abort(allocator);
                group.event_ordinals.ensureTotalCapacity(allocator, 1) catch return error.OutOfMemory;
                if (group.existed) try self.stream.reserveExistingNamedEventIndexes(allocator, elem_id.raw(), 1);
                const index = self.prepared_named_event_groups.items.len;
                self.prepared_named_event_groups.appendAssumeCapacity(group);
                self.prepared_named_event_group_by_elem.putAssumeCapacity(elem_id.raw(), index);
                return index;
            }

            const StagedSignalRecordCtx = struct {
                collection: *Collection,
                allocator: std.mem.Allocator,

                fn retainExisting(self: @This(), token: HostSignalToken, expected_tag: std.meta.Tag(HostSignalRecordPayload)) error{OutOfMemory}!?*HostSignalRecord {
                    const persistent = self.collection.engine.signalRecordByTokenForStream(self.collection.stream, token);
                    const record = self.collection.signal_records.lookup(token, persistent) orelse return null;
                    validateExistingSignalRecord(record, expected_tag);
                    if (!self.collection.signal_records.by_token.contains(token)) {
                        if (self.collection.signal_records.token_intents.items.len >= self.collection.plan.signal_records) return error.OutOfMemory;
                        self.collection.signal_records.rememberTokenAssumeCapacity(token, record);
                    }
                    return record.retain();
                }

                fn retainExistingKeyed(self: @This(), identity: signal_records.KeyedSelectIdentity) error{OutOfMemory}!?*HostSignalRecord {
                    const persistent = self.collection.engine.signalRecordByKeyedSelectForStream(self.collection.stream, identity);
                    const record = self.collection.signal_records.lookupComposite(identity, persistent) orelse return null;
                    validateExistingSignalRecord(record, .keyed_select);
                    if (!self.collection.signal_records.by_composite.contains(identity)) {
                        if (self.collection.signal_records.composite_intents.items.len >= self.collection.plan.signal_records) return error.OutOfMemory;
                        self.collection.signal_records.rememberCompositeAssumeCapacity(identity, record);
                    }
                    return record.retain();
                }

                fn init(self: @This(), payload: HostSignalRecordPayload) error{OutOfMemory}!*HostSignalRecord {
                    return HostSignalRecord.tryInitOwned(
                        self.allocator,
                        self.collection.host_ctx,
                        self.collection.signal_roc_host orelse @panic("staged signal binding lacked Roc host"),
                        &self.collection.engine.pending_roc_metrics,
                        payload,
                    );
                }

                fn release(self: @This(), record: *HostSignalRecord) void {
                    record.release(
                        self.allocator,
                        self.collection.host_ctx,
                        self.collection.signal_roc_host orelse @panic("staged signal binding lacked Roc host"),
                        &self.collection.engine.pending_roc_metrics,
                    );
                }

                fn remember(self: @This(), record: *HostSignalRecord) error{OutOfMemory}!void {
                    if (record.keyedSelectIdentity()) |identity| {
                        if (self.collection.signal_records.by_composite.contains(identity)) return;
                        if (self.collection.signal_records.composite_intents.items.len >= self.collection.plan.signal_records) return error.OutOfMemory;
                        self.collection.signal_records.rememberCompositeAssumeCapacity(identity, record);
                        return;
                    }
                    const token = record.token() orelse return;
                    if (self.collection.signal_records.by_token.contains(token)) return;
                    if (self.collection.signal_records.token_intents.items.len >= self.collection.plan.signal_records) return error.OutOfMemory;
                    self.collection.signal_records.rememberTokenAssumeCapacity(token, record);
                }
            };

            fn bindSignalRoot(self: *@This(), roc_host: *abi.RocHost, expr: abi.NodeSignalExpr, binder_stack: []const HostBinderBinding) CollectionError!HostSignalBinding {
                if (self.signal_records.descriptor_roots.items.len >= self.plan.signal_roots) return error.OutOfMemory;
                self.signal_roc_host = roc_host;
                const binding = StagedSignalRecordCtx{ .collection = self, .allocator = Ctx.allocator(self.host_ctx) };
                const record = self.engine.bindSignalExprViewWith(StagedSignalRecordCtx, binding, abi_view.SignalExpr.fromAbi(expr), binder_stack) catch return error.OutOfMemory;
                self.signal_records.ownDescriptorRootAssumeCapacity(record);
                var source_node_ids: shared_buffer.List(u64) = .empty;
                appendSignalRecordSourceNodeIdsFallible(binding.allocator, &source_node_ids, record) catch {
                    source_node_ids.deinit(binding.allocator);
                    return error.OutOfMemory;
                };
                const result = HostSignalBinding{
                    .record = record,
                    .source_node_ids = source_node_ids.toOwnedSlice(binding.allocator) catch {
                        source_node_ids.deinit(binding.allocator);
                        return error.OutOfMemory;
                    },
                };
                self.signal_bindings.appendAssumeCapacity(result);
                return result;
            }

            const SignalPublisher = struct {
                stream: *HostNodeDescriptorStream,

                /// Publishes token during the allocation-free commit phase.
                pub fn publishToken(self: @This(), token: HostSignalToken, record: *HostSignalRecord) void {
                    self.stream.rememberSignalRecordAssumeCapacity(token, record);
                }

                /// Publishes a keyed-selector composite identity after all index growth was preflighted.
                pub fn publishComposite(self: @This(), identity: signal_records.KeyedSelectIdentity, record: *HostSignalRecord) void {
                    self.stream.rememberKeyedSelectRecordAssumeCapacity(identity, record);
                }

                /// Publishes descriptor root during the allocation-free commit phase.
                pub fn publishDescriptorRoot(self: @This(), record: *HostSignalRecord) void {
                    self.stream.rememberPreparedSignalRecordTreeAssumeCapacity(record);
                }
            };

            /// Transfers prepared descriptor ownership into the plan-local
            /// stream without publishing persistent engine identities/scopes.
            fn materializeStream(self: *@This()) void {
                if (self.phase.isMaterialized()) @panic("staged collection stream materialized twice");
                self.plan.assertStreamCovered(self);
                for (self.prepared_render_order.items) |entry| switch (entry) {
                    .static => |index| self.stream.appendPreparedStaticNode(self.prepared_nodes.items[index]),
                    .signal => |index| self.stream.appendPreparedSignalDescriptor(self.prepared_signal_attrs.items[index]),
                };
                for (self.row_render_span_intents.items) |intent| {
                    const transition = switch (intent.owner) {
                        .initial => |index| if (self.prepared_initial_each_inputs.items[index].rows_transition) |*value| value else @panic("initial row render span lost its Rows transition"),
                        .nested => |index| if (self.nested_row_syncs.items[index].inputs.rows_transition) |*value| value else @panic("nested row render span lost its Rows transition"),
                    };
                    const range = intent.range;
                    const span = rowRenderSpanForRange(self.stream, range.parent_elem_id, range.start, range.len) catch @panic("prepared row render span was invalid");
                    transition.setCandidateRenderSpanAssumeCapacity(range.item_slot, span) catch @panic("prepared row render span lost its candidate slot");
                }
                self.row_render_span_intents.clearRetainingCapacity();
                self.prepared_nodes.clearRetainingCapacity();
                self.prepared_render_order.clearRetainingCapacity();
                for (self.prepared_attrs.items) |prepared| self.stream.appendPreparedStaticAttr(prepared);
                self.prepared_attrs.clearRetainingCapacity();
                self.signal_records.commit(SignalPublisher{ .stream = self.stream });
                for (self.prepared_signal_attrs.items) |prepared| switch (prepared) {
                    .text_node => {},
                    else => self.stream.appendPreparedSignalDescriptor(prepared),
                };
                self.prepared_signal_attrs.clearRetainingCapacity();
                const event_base = self.stream.events.items.len;
                for (self.prepared_events.items) |prepared| self.stream.appendPreparedEvent(prepared);
                self.stream.publishPreparedNamedEventIndexes(self.prepared_named_event_groups.items, event_base);
                self.prepared_events.clearRetainingCapacity();
                self.prepared_named_event_groups.clearRetainingCapacity();
                for (self.prepared_lifecycle.items) |prepared| self.stream.appendPreparedLifecycle(prepared);
                self.prepared_lifecycle.clearRetainingCapacity();
                for (self.prepared_state_sites.items) |site| self.stream.appendPreparedScopeSite(site);
                for (self.prepared_states.items) |state| self.stream.appendPreparedState(state);
                self.prepared_state_sites.clearRetainingCapacity();
                self.prepared_states.clearRetainingCapacity();
                for (self.prepared_whens.items) |prepared| self.stream.appendPreparedWhen(prepared);
                self.prepared_whens.clearRetainingCapacity();
                for (self.prepared_eaches.items) |prepared| self.stream.appendPreparedEach(prepared);
                self.prepared_eaches.clearRetainingCapacity();
                self.phase.markMaterialized();
            }

            /// Publishes only pre-reserved state. This function must remain
            /// allocation-free so preparation is the last recoverable point.
            fn commit(self: *@This()) void {
                if (self.phase.isCommitted()) @panic("staged collection committed twice");
                if (!self.phase.isMaterialized()) self.materializeStream();
                self.plan.assertEngineCovered(self);
                const original_scope_len = self.engine.scopes.items.len;
                var final_scope_len = original_scope_len;
                var reserved_scope_iterator = self.scopes.reserved_ids.keyIterator();
                while (reserved_scope_iterator.next()) |scope_id| {
                    final_scope_len = @max(final_scope_len, std.math.add(usize, scope_id.index(), 1) catch @panic("prepared scope id overflow"));
                }
                // Scope and each-row reservations share one dense id space but
                // are journaled separately. Replay them in claim order: fresh
                // ids were handed out ascending, so the fresh suffix publishes
                // contiguously, and every parent was claimed before its
                // children, so reused slots (whose ids follow the ring, not
                // the table) attach beneath an already published parent.
                if (self.scope_publications.items.len != self.scopes.intents.items.len + self.prepared_each_row_scopes.items.len) @panic("scope publication journal does not cover every claim");
                for (self.scope_publications.items) |publication| {
                    const scope: HostScope = switch (publication) {
                        .intent => |index| scope: {
                            const intent = self.scopes.intents.items[index];
                            break :scope switch (intent.key.kind) {
                                .root => .{ .scope_id = intent.id, .parent_scope_id = null, .step = .root, .lifecycle = .active },
                                .component => .{ .scope_id = intent.id, .parent_scope_id = intent.key.parent_id, .step = .{ .component = .{ .site_ordinal = intent.key.ordinal } }, .lifecycle = .active },
                                .when_branch => |branch| .{ .scope_id = intent.id, .parent_scope_id = intent.key.parent_id, .step = .{ .when_branch = .{ .site_ordinal = intent.key.ordinal, .branch = branch } }, .lifecycle = .active },
                            };
                        },
                        .each_row => |index| self.prepared_each_row_scopes.items[index],
                    };
                    scope_tree.publishScopeAssumeCapacity(HostEachRowScopeStep, &self.engine.scopes, original_scope_len, scope);
                    self.engine.recordScopeCreated();
                }
                self.scope_publications.clearRetainingCapacity();
                if (self.engine.scopes.items.len != final_scope_len) @panic("prepared scope suffix did not publish contiguously");
                // Rows an each mounted inside this collection are created rows
                // just like the rows a keyed reconciliation creates; a spec
                // counting a new outer row expects its nested rows with it.
                self.engine.recordRowsCreated(@intCast(self.prepared_each_row_scopes.items.len));
                self.prepared_each_row_scopes.clearRetainingCapacity();
                // A re-collected row's live each sites publish their keyed
                // reconciliation into the committed site: the created row
                // scopes are active as of the loop above, the surviving ones
                // never left, and the removed ones retire with the subtree
                // journal after this collection.
                for (self.nested_row_syncs.items) |*sync| sync.commit(self);
                if (self.prepared_each_sites.items.len != 0) {
                    const membership_len = self.engine.scopes.items.len;
                    while (self.engine.each_row_memberships_by_scope_id.items.len < membership_len) self.engine.each_row_memberships_by_scope_id.appendAssumeCapacity(null);
                    for (self.prepared_each_sites.items, self.prepared_initial_each_inputs.items) |site, *inputs| {
                        // A site mounted afresh is one no live site key names:
                        // a live key under a re-collected row is reconciled
                        // through `nested_row_syncs` instead.
                        if (self.engine.each_row_site_indexes.contains(site.key)) @panic("staged each site collided with a live site under the same key");
                        const site_index = self.engine.each_row_sites.items.len;
                        self.engine.each_row_site_indexes.putAssumeCapacity(site.key, site_index);
                        self.engine.each_row_sites.appendAssumeCapacity(site);
                        const rows_key = inputs.rows_site_key orelse @panic("prepared initial each lacked Rows site key");
                        const rows_site_id = inputs.rows_site_id orelse @panic("prepared initial each lacked Rows site identity");
                        if (self.engine.rows_site_ids.get(rows_key)) |live_site_id| {
                            if (live_site_id != rows_site_id) @panic("prepared initial Rows site collided with a different live site");
                        }
                        if (inputs.rows_transition) |*transition| transition.commit() else @panic("prepared initial each lacked Rows transition");
                        self.engine.rows_site_ids.putAssumeCapacity(rows_key, rows_site_id);
                        if (self.engine.each_generation_ids_by_rows_site.get(rows_site_id)) |old_generation_id| {
                            if (old_generation_id != inputs.generation.id) {
                                const retired = self.engine.each_generations.fetchRemove(old_generation_id) orelse @panic("retiring Rows site generation was absent");
                                self.retired_initial_generations.appendAssumeCapacity(retired.value);
                            }
                        }
                        self.engine.each_generation_ids_by_rows_site.putAssumeCapacity(rows_site_id, inputs.generation.id);
                        inputs.rows_site_published = true;
                        self.engine.each_generations.putAssumeCapacity(inputs.generation.id, inputs.generation);
                        self.engine.each_generation_ids_by_site_index.appendAssumeCapacity(inputs.generation.id);
                        inputs.candidate_bindings.commit(&self.engine.committed_row_bindings);
                        inputs.transfer();
                        for (site.scope_ids.items, 0..) |scope_id, row_index| {
                            const membership = &self.engine.each_row_memberships_by_scope_id.items[scope_id.index()];
                            if (membership.* != null) @panic("prepared initial each row had duplicate membership");
                            membership.* = .{ .site_index = site_index, .row_index = row_index };
                        }
                        inputs.deinit();
                    }
                }
                self.prepared_each_sites.clearRetainingCapacity();
                self.prepared_initial_each_inputs.clearRetainingCapacity();
                for (self.dom_identities.intents.items) |intent| {
                    const scope_id: u64 = @truncate(intent.key >> 64);
                    const ordinal: u64 = @truncate(intent.key);
                    const identity: HostDomIdentity = .{
                        .elem_id = ids.ElemId.fromRaw(intent.id),
                        .scope_id = ids.ScopeId.fromRaw(scope_id),
                        .ordinal = ids.SiteOrdinal.fromRaw(ordinal),
                        .lifecycle = .active,
                    };
                    const identity_index: usize = @intCast(intent.id - 1);
                    if (identity_index < self.engine.dom_identities.items.len) {
                        // A re-collected site publishes its committed
                        // identity again; the slot is inactive when the
                        // transaction retired that generation with the
                        // descriptor it replaces, and still the same
                        // identity when it did not.
                        const slot = self.engine.dom_identities.items[identity_index];
                        if (slot.lifecycle.isActive() and (slot.scope_id != identity.scope_id or slot.ordinal != identity.ordinal)) @panic("staged DOM identity reused an active slot");
                        self.engine.dom_identities.items[identity_index] = identity;
                    } else {
                        if (identity_index != self.engine.dom_identities.items.len) @panic("staged DOM identity suffix was not contiguous");
                        self.engine.dom_identities.appendAssumeCapacity(identity);
                    }
                    self.engine.active_dom_identity_ids.putAssumeCapacity(intent.key, intent.id);
                }
                for (self.node_identities.intents.items) |intent| {
                    const scope_id: u64 = @truncate(intent.key >> 64);
                    const ordinal: u64 = @truncate(intent.key);
                    const identity: HostNodeIdentity = .{
                        .node_id = ids.NodeId.fromRaw(intent.id),
                        .scope_id = ids.ScopeId.fromRaw(scope_id),
                        .ordinal = ids.SiteOrdinal.fromRaw(ordinal),
                        .lifecycle = .active,
                    };
                    const identity_index: usize = @intCast(intent.id);
                    if (identity_index < self.engine.node_identities.items.len) {
                        const slot = self.engine.node_identities.items[identity_index];
                        if (slot.lifecycle.isActive() and (slot.scope_id != identity.scope_id or slot.ordinal != identity.ordinal)) @panic("staged node identity reused an active slot");
                        self.engine.node_identities.items[identity_index] = identity;
                    } else {
                        if (identity_index != self.engine.node_identities.items.len) @panic("staged node identity suffix was not contiguous");
                        self.engine.node_identities.appendAssumeCapacity(identity);
                    }
                    self.engine.active_node_identity_ids.putAssumeCapacity(intent.key, intent.id);
                }
                for (self.prepared_state_cells.items[0..self.external_state_count]) |*state| state.retire(self.host_ctx, self.signal_roc_host orelse @panic("staged state lacked Roc host"), &self.engine.pending_roc_metrics);
                for (self.prepared_state_cells.items[self.external_state_count..]) |state| {
                    while (self.engine.state_indexes_by_node_id.items.len <= state.state_id) self.engine.state_indexes_by_node_id.appendAssumeCapacity(null);
                    const state_index = self.engine.states.items.len;
                    self.engine.states.appendAssumeCapacity(state);
                    self.engine.state_indexes_by_node_id.items[@intCast(state.state_id)] = state_index;
                }
                self.prepared_state_cells.clearRetainingCapacity();
                self.external_state_count = 0;
                self.scopes.finishExternalCommit();
                self.node_identities.finishExternalCommit();
                self.dom_identities.finishExternalCommit();
                self.phase.markCommitted();
            }

            /// Publishes the stable Rows-store transitions before another
            /// reconciliation may reuse scopes retired by this replacement.
            /// Descriptor, scope, generation, and binding publication remains
            /// in `commit` at the ordinary collection boundary.
            fn commitRowsTransitionRemovalsEarly(self: *@This()) void {
                for (self.prepared_initial_each_inputs.items) |*inputs| {
                    if (inputs.rows_transition) |*transition| transition.commitRemovalsEarly() else @panic("prepared initial each lacked Rows transition");
                }
            }
        };

        fn collectActiveElemDescriptorsWith(self: *Self, comptime Collection: type, collection: Collection, ctx: Ctx.Handle, roc_host: *abi.RocHost, stream: *HostNodeDescriptorStream, elem: abi.Elem, scope_id: ids.ScopeId, parent_elem_id: ids.ElemId, ordinal: *ids.SiteOrdinal, dom_ordinal: *ids.SiteOrdinal, binder_stack: *shared_buffer.List(HostBinderBinding), scope_created: bool, dirty_source_node_ids: []const u64) CollectionError!void {
            try collection.validateScope(scope_id);

            switch (abi_view.Elem.fromAbi(elem)) {
                .element => |payload| {
                    const elem_id = try collection.appendElement(scope_id, parent_elem_id, dom_ordinal, payload.tag.asSlice(), payload.namespace);
                    for (payload.attrs) |attr| {
                        try collection.appendAttr(roc_host, scope_id, elem_id, attr, binder_stack.items);
                    }
                    for (payload.children) |child| {
                        try self.collectActiveElemDescriptorsWith(Collection, collection, ctx, roc_host, stream, child, scope_id, elem_id, ordinal, dom_ordinal, binder_stack, scope_created, dirty_source_node_ids);
                    }
                },
                .text => |payload| {
                    try collection.appendText(scope_id, parent_elem_id, dom_ordinal, payload.text.asSlice());
                },
                .text_signal => |payload| {
                    try collection.appendSignalText(roc_host, scope_id, parent_elem_id, dom_ordinal, payload, binder_stack.items);
                },
                .cleanup => |payload| {
                    try collection.appendCleanup(roc_host, scope_id, payload.name.asSlice());
                },
                .on_change => |payload| {
                    try collection.appendOnChange(roc_host, scope_id, payload, binder_stack.items, scope_created);
                },
                .on_mount => |payload| {
                    try collection.appendMount(roc_host, scope_id, payload.to_cmd, scope_created);
                },
                .state => |state| {
                    const binder = try collection.beginState(roc_host, scope_id, parent_elem_id, ordinal, binder_stack, state);
                    binder_stack.appendAssumeCapacity(binder);
                    try self.collectActiveElemDescriptorsWith(Collection, collection, ctx, roc_host, stream, state.child.*, scope_id, parent_elem_id, ordinal, dom_ordinal, binder_stack, scope_created, dirty_source_node_ids);
                    _ = binder_stack.pop() orelse unreachable;
                },
                .component => |payload| {
                    const component_scope = try collection.beginComponent(scope_id, parent_elem_id, ordinal, binder_stack.items);
                    const component_scope_id = component_scope.scope_id;
                    var component_ordinal = ids.SiteOrdinal.fromRaw(0);
                    var component_dom_ordinal = ids.SiteOrdinal.fromRaw(0);
                    try self.collectActiveElemDescriptorsWith(Collection, collection, ctx, roc_host, stream, payload.child.*, component_scope_id, parent_elem_id, &component_ordinal, &component_dom_ordinal, binder_stack, component_scope.created, dirty_source_node_ids);
                },
                .when => |when_payload| {
                    const selected = try collection.beginWhen(roc_host, scope_id, parent_elem_id, ordinal, binder_stack.items, when_payload);
                    defer selected.elem.decref(roc_host);
                    try self.collectActiveWhenElemDescriptorsWith(Collection, collection, ctx, roc_host, stream, selected, parent_elem_id, binder_stack, dirty_source_node_ids);
                },
                .each => |each_payload| {
                    try collection.collectInitialEach(roc_host, scope_id, parent_elem_id, ordinal, binder_stack, each_payload, dirty_source_node_ids);
                },
            }
        }

        fn collectActiveElemRootDescriptorsWith(self: *Self, comptime Collection: type, collection: Collection, ctx: Ctx.Handle, roc_host: *abi.RocHost, stream: *HostNodeDescriptorStream, root: abi.Elem, dirty_source_node_ids: []const u64) CollectionError!void {
            const root_scope = try collection.rootScope();
            const root_scope_id = root_scope.scope_id;
            const allocator = Ctx.allocator(ctx);
            const binder_stack = self.scratchBinderStack(allocator, &.{});
            defer self.scratch.binder_stack.clearRetainingCapacity();
            var ordinal = ids.SiteOrdinal.fromRaw(0);
            var dom_ordinal = ids.SiteOrdinal.fromRaw(0);
            try self.collectActiveElemDescriptorsWith(Collection, collection, ctx, roc_host, stream, root, root_scope_id, ids.root_elem, &ordinal, &dom_ordinal, binder_stack, root_scope.created, dirty_source_node_ids);
        }

        const StaticRootCounts = struct {
            nodes: usize = 0,
            elements: usize = 0,
            text_nodes: usize = 0,
            signal_text_nodes: usize = 0,
            attrs: usize = 0,
            static_text_attrs: usize = 0,
            static_custom_text_attrs: usize = 0,
            static_bool_attrs: usize = 0,
            static_custom_bool_attrs: usize = 0,
            signal_text_attrs: usize = 0,
            signal_custom_text_attrs: usize = 0,
            signal_optional_custom_text_attrs: usize = 0,
            signal_bool_attrs: usize = 0,
            signal_custom_bool_attrs: usize = 0,
            events: usize = 0,
            named_events: usize = 0,
            custom_attrs: usize = 0,
            lifecycle: usize = 0,
            signal_records: usize = 0,
            state_sites: usize = 0,
            component_sites: usize = 0,
            when_sites: usize = 0,
            each_sites: usize = 0,
        };

        fn countSignalExprRecords(expr: abi.NodeSignalExpr) CollectionError!usize {
            return switch (abi_view.SignalExpr.fromAbi(expr)) {
                .ref, .const_value, .row_source, .interval_source, .entropy_seed_source, .location_source, .visibility_source, .online_source, .storage_source => 1,
                .map => |payload| std.math.add(usize, 1, try countSignalExprRecords(payload.input.*)) catch return error.ResourceLimit,
                .select => |payload| std.math.add(usize, 1, try countSignalExprRecords(payload.input.*)) catch return error.ResourceLimit,
                .keyed_select => |payload| std.math.add(usize, 1, try countSignalExprRecords(payload.input.*)) catch return error.ResourceLimit,
                .map2 => |payload| blk: {
                    const left = try countSignalExprRecords(payload.left.*);
                    const right = try countSignalExprRecords(payload.right.*);
                    const children = std.math.add(usize, left, right) catch return error.ResourceLimit;
                    break :blk std.math.add(usize, 1, children) catch return error.ResourceLimit;
                },
                .combine => |payload| blk: {
                    var count: usize = 1;
                    for (payload.children) |child| {
                        count = std.math.add(usize, count, try countSignalExprRecords(child)) catch return error.ResourceLimit;
                    }
                    break :blk count;
                },
            };
        }

        fn countStaticRootNodes(elem: abi.Elem) CollectionError!StaticRootCounts {
            return switch (abi_view.Elem.fromAbi(elem)) {
                .element => |payload| blk: {
                    var count = StaticRootCounts{ .nodes = 1, .elements = 1, .attrs = payload.attrs.len };
                    for (payload.attrs) |attr| switch (abi_view.NodeAttr.fromAbi(attr)) {
                        .static_text => |value| switch (value.target) {
                            .fixed => count.static_text_attrs += 1,
                            .custom => {
                                count.static_custom_text_attrs += 1;
                                count.custom_attrs += 1;
                            },
                        },
                        .static_bool => |value| switch (value.target) {
                            .fixed => count.static_bool_attrs += 1,
                            .custom => {
                                count.static_custom_bool_attrs += 1;
                                count.custom_attrs += 1;
                            },
                        },
                        .signal_text => |signal| {
                            switch (signal.target) {
                                .fixed => count.signal_text_attrs += 1,
                                .custom => {
                                    count.signal_custom_text_attrs += 1;
                                    count.custom_attrs += 1;
                                },
                            }
                            count.signal_records = std.math.add(usize, count.signal_records, try countSignalExprRecords(signal.signal.*)) catch return error.ResourceLimit;
                        },
                        .signal_optional_text => |signal| {
                            count.signal_optional_custom_text_attrs += 1;
                            count.custom_attrs += 1;
                            count.signal_records = std.math.add(usize, count.signal_records, try countSignalExprRecords(signal.signal.*)) catch return error.ResourceLimit;
                        },
                        .signal_bool => |signal| {
                            switch (signal.target) {
                                .fixed => count.signal_bool_attrs += 1,
                                .custom => {
                                    count.signal_custom_bool_attrs += 1;
                                    count.custom_attrs += 1;
                                },
                            }
                            count.signal_records = std.math.add(usize, count.signal_records, try countSignalExprRecords(signal.signal.*)) catch return error.ResourceLimit;
                        },
                        .event => |event| {
                            count.events += 1;
                            if (event.msg.handler == .action) count.signal_records = std.math.add(usize, count.signal_records, try countSignalExprRecords(event.msg.handler.action.reads.*)) catch return error.ResourceLimit;
                        },
                        .named_event => |event| {
                            count.events += 1;
                            count.named_events += 1;
                            if (event.msg.handler == .action) count.signal_records = std.math.add(usize, count.signal_records, try countSignalExprRecords(event.msg.handler.action.reads.*)) catch return error.ResourceLimit;
                        },
                    };
                    for (payload.children) |child| {
                        const child_count = try countStaticRootNodes(child);
                        inline for (std.meta.fields(StaticRootCounts)) |field| {
                            @field(count, field.name) = std.math.add(usize, @field(count, field.name), @field(child_count, field.name)) catch return error.ResourceLimit;
                        }
                    }
                    break :blk count;
                },
                .text => .{ .nodes = 1, .text_nodes = 1 },
                .text_signal => |payload| .{ .nodes = 1, .signal_text_nodes = 1, .signal_records = try countSignalExprRecords(payload.signal.*) },
                .state => |payload| blk: {
                    var count = try countStaticRootNodes(payload.child.*);
                    count.state_sites = std.math.add(usize, count.state_sites, 1) catch return error.ResourceLimit;
                    break :blk count;
                },
                .component => |payload| blk: {
                    var count = try countStaticRootNodes(payload.child.*);
                    count.component_sites = std.math.add(usize, count.component_sites, 1) catch return error.ResourceLimit;
                    break :blk count;
                },
                .when => |payload| blk: {
                    var count = StaticRootCounts{};
                    count.signal_records = std.math.add(usize, count.signal_records, try countSignalExprRecords(payload.condition.*)) catch return error.ResourceLimit;
                    count.when_sites = std.math.add(usize, count.when_sites, 1) catch return error.ResourceLimit;
                    break :blk count;
                },
                .cleanup, .on_mount => .{ .lifecycle = 1 },
                .on_change => |payload| .{ .lifecycle = 1, .signal_records = try countSignalExprRecords(payload.signal.*) },
                .each => |payload| .{ .signal_records = try countSignalExprRecords(payload.rows.*), .each_sites = 1 },
            };
        }

        /// Row-sync hooks for a live each site reconciled inside a staged
        /// collection. Created rows claim their scopes from the collection's
        /// capacity plan and are published with every other row scope the
        /// collection prepared; removed rows are left to the enclosing subtree
        /// retirement, which the transaction derives from the reconciliation.
        const StagedEachRowSyncHooks = struct {
            base: EachRowSync,
            collection: *StagedCollectionCtx,
            inputs: ?*PreparedEachInputs,

            fn init(collection: *StagedCollectionCtx, roc_host: *abi.RocHost, inputs: ?*PreparedEachInputs) @This() {
                return .{
                    .base = .{ .engine = collection.engine, .ctx = collection.host_ctx, .roc_host = roc_host, .inputs = inputs orelse undefined },
                    .collection = collection,
                    .inputs = inputs,
                };
            }

            /// Hashes an incoming key through the each descriptor capability.
            pub fn hashKey(self: *@This(), key: usize) u64 {
                return self.base.hashKey(key);
            }

            /// Compares two incoming keys before persistent publication.
            pub fn nextKeysEqual(self: *@This(), left: usize, right: usize) bool {
                return self.base.nextKeysEqual(left, right);
            }

            /// Compares an incoming key with one persistent row key.
            pub fn existingKeyEquals(self: *@This(), scope_id: ids.ScopeId, key: usize) bool {
                return self.base.existingKeyEquals(scope_id, key);
            }

            /// Compares an incoming item with one persistent row item.
            pub fn rowItemEquals(self: *@This(), scope_id: ids.ScopeId, item: usize) bool {
                return self.base.rowItemEquals(scope_id, item);
            }

            /// Claims a provisional row scope from the collection's plan and
            /// moves the incoming key and item into it.
            pub fn prepareCreatedRow(self: *@This(), allocator: std.mem.Allocator, parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal, input_index: usize, key_hash: u64, _: usize, _: usize) (std.mem.Allocator.Error || error{ResourceLimit})!ids.ScopeId {
                _ = allocator;
                const inputs = self.inputs orelse @panic("staged each hooks had no generation inputs");
                const row_handle = try self.base.engine.row_handle_registry.insert(Ctx.allocator(self.base.ctx), {});
                inputs.created_handles.append(Ctx.allocator(self.base.ctx), row_handle) catch {
                    _ = self.base.engine.row_handle_registry.remove(row_handle) catch unreachable;
                    return error.OutOfMemory;
                };
                inputs.candidate_bindings.putAssumeCapacity(row_handle, .{ .generation_id = inputs.generation.id, .item_slot = inputs.slot(input_index) orelse @panic("missing candidate Rows slot") }, .{ .snapshot = input_index }) catch @panic("invalid duplicate row binding");
                inputs.row_handles_by_index[input_index] = row_handle;
                const scope_id = self.collection.reserveEachRowScopeGeneration(parent_scope_id, site_ordinal, key_hash, row_handle) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.ResourceLimit => return error.ResourceLimit,
                    // The parent row was validated when its own collection
                    // began, and a claimed scope id is never offered twice.
                    error.InvalidScope, error.InvalidDescriptor, error.OverlappingRemoval, error.InvalidRenderTopology, error.InvalidSignalGraphAppend, error.InvalidSignalGraphRelease => @panic("staged nested row could not claim a scope under its validated parent row"),
                };
                inputs.transferEntry(input_index);
                return scope_id;
            }

            /// Batches equality for reused rows and stages their candidate bindings.
            pub fn prepareItemComparisons(self: *@This(), allocator: std.mem.Allocator, scope_ids: []const ids.ScopeId, created: []const bool) (std.mem.Allocator.Error || error{ResourceLimit})!void {
                const inputs = self.inputs orelse @panic("staged each hooks had no generation inputs");
                var pairs: shared_buffer.List(u64) = .empty;
                defer pairs.deinit(allocator);
                var reused_count: usize = 0;
                for (created) |was_created| if (!was_created) {
                    reused_count += 1;
                };
                try pairs.ensureTotalCapacity(allocator, std.math.mul(usize, reused_count, 2) catch return error.ResourceLimit);
                var old_generation: ?*each_generation.Generation = null;
                for (scope_ids, created, 0..) |scope_id, was_created, next_index| {
                    if (was_created) continue;
                    const row_handle = scope_runtime.eachRowHandle(self.base.engine.scopes.items, scope_id);
                    const binding = self.base.engine.committed_row_bindings.get(row_handle) orelse return error.ResourceLimit;
                    const generation = self.base.engine.each_generations.get(binding.generation_id) orelse return error.ResourceLimit;
                    if (old_generation) |existing| {
                        if (existing != generation) return error.ResourceLimit;
                    } else old_generation = generation;
                    pairs.appendAssumeCapacity(binding.item_slot);
                    pairs.appendAssumeCapacity(inputs.slot(next_index) orelse return error.ResourceLimit);
                    inputs.candidate_bindings.putAssumeCapacity(row_handle, .{ .generation_id = inputs.generation.id, .item_slot = inputs.slot(next_index) orelse return error.ResourceLimit }, .{ .snapshot = next_index }) catch return error.ResourceLimit;
                    inputs.row_handles_by_index[next_index] = row_handle;
                }
                const old = old_generation orelse return;
                var results: each_collection.BoolStorage = .{};
                defer results.deinit(allocator);
                var sink = results.prepare(allocator, pairs.items.len / 2) catch return error.OutOfMemory;
                const token = self.base.engine.active_each_sinks.activateBool(&sink) catch return error.ResourceLimit;
                errdefer self.base.engine.active_each_sinks.abort(token) catch {};
                const pair_list = retained_values.U64List.fromSlice(pairs.items, self.base.roc_host);
                defer pair_list.decref(self.base.roc_host);
                const returned = retained_values.callRowsCompareSlots(
                    Ctx,
                    self.base.ctx,
                    self.base.roc_host,
                    old.ops.rows_capability,
                    inputs.generation.ops.rows_capability,
                    inputs.generation.ops.compare_slots,
                    old.collection.value,
                    inputs.generation.collection.value,
                    pair_list,
                    @intFromEnum(token),
                );
                if (returned != @intFromEnum(token)) return error.ResourceLimit;
                self.base.engine.active_each_sinks.finishBool(token) catch return error.ResourceLimit;
                var result_index: usize = 0;
                for (created, 0..) |was_created, next_index| {
                    if (was_created) continue;
                    inputs.item_equal[next_index] = results.values.items[result_index];
                    result_index += 1;
                }
            }

            /// The enclosing transaction derives the retirement journal from
            /// the reconciliation; nothing to reserve here.
            pub fn prepareExistingRowsCommit(_: *@This(), _: std.mem.Allocator, _: usize) std.mem.Allocator.Error!void {}

            /// Validates that reconciliation references a published row scope.
            pub fn commitCreatedRow(self: *@This(), scope_id: ids.ScopeId) void {
                if (scope_id.index() >= self.base.engine.scopes.items.len or !self.base.engine.scopes.items[scope_id.index()].lifecycle.isActive()) @panic("unknown committed nested each-row scope");
                switch (self.base.engine.scopes.items[scope_id.index()].step) {
                    .each_row => {},
                    else => @panic("prepared nested each row claimed a non-row scope"),
                }
            }

            /// Provisional row scopes are published by the collection.
            pub fn finishPreparedRowsCommit(_: *@This()) void {}

            /// Provisional row scopes are released by the collection.
            pub fn abortPreparedRows(_: *@This()) void {}

            /// Replaces a surviving row key at the allocation-free commit boundary.
            pub fn replaceRowKey(self: *@This(), scope_id: ids.ScopeId, key_hash: u64, key: usize) void {
                self.base.replaceRowKey(scope_id, key_hash, key);
            }

            /// Replaces a surviving row item at the allocation-free commit boundary.
            pub fn replaceRowItem(self: *@This(), scope_id: ids.ScopeId, item: usize) void {
                self.base.replaceRowItem(scope_id, item);
            }

            /// Releases an unchanged incoming key after publication succeeds.
            pub fn dropIncomingKey(self: *@This(), key: usize) void {
                self.base.dropIncomingKey(key);
            }

            /// Releases an unchanged incoming item after publication succeeds.
            pub fn dropIncomingItem(self: *@This(), item: usize) void {
                self.base.dropIncomingItem(item);
            }

            /// A removed row retires with the enclosing subtree journal.
            pub fn disposeScope(_: *@This(), _: ids.ScopeId) void {}

            /// Reads a committed row hash while rebuilding the site index.
            pub fn rowKeyHash(self: *@This(), scope_id: ids.ScopeId) u64 {
                return self.base.rowKeyHash(scope_id);
            }

            /// Reports duplicate incoming keys through the bounded host diagnostic.
            pub fn failDuplicateEachKey(self: *@This(), parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal, first_index: usize, second_index: usize, key: usize) noreturn {
                self.base.failDuplicateEachKey(parent_scope_id, site_ordinal, first_index, second_index, key);
            }
        };

        /// One live each site a re-collected row brought back: the keyed
        /// reconciliation of its committed rows against the items the row now
        /// produces, and the site's next order as the pieces a
        /// `PreparedRenderLayoutPlan` lays out inside the row's replacement.
        ///
        /// A next row is exactly one of: created here (a provisional scope in
        /// the collection's plan), a survivor re-collected in place (its scope
        /// kept, its old descriptors retired with the row's), or an untouched
        /// survivor (scope, descriptors, and render nodes all kept). A
        /// committed row the next order omits is removed and retires with the
        /// enclosing subtree journal.
        const PreparedNestedRowSync = struct {
            allocator: std.mem.Allocator,
            node_id: ids.NodeId,
            parent_scope_id: ids.ScopeId,
            site_ordinal: ids.SiteOrdinal,
            parent_elem_id: ids.ElemId,
            /// The committed site in `engine.each_row_sites`.
            site_index: usize,
            /// The render span the collected rows occupy in the replacement
            /// stream, starting where the site's descriptor points.
            local_render_start: usize,
            local_render_len: usize,
            /// The scope sites the collected rows created in the replacement
            /// stream, closed by the site's own descriptor at
            /// `local_site_index`.
            local_site_start: usize,
            local_site_len: usize,
            local_site_index: usize,
            /// The span the committed rows occupy in the active stream, or
            /// the committed site's insertion point when none renders.
            old_start: usize,
            old_end: usize,
            inputs: PreparedEachInputs,
            rows: each_runtime.PreparedRowSync,
            direct_delta: bool = false,
            retired_generation: ?*each_generation.Generation = null,
            /// Per next row: a survivor re-collected in place.
            recollected: []bool,
            pieces: []PreparedRenderLayoutPlan.Piece,
            phase: CommitPhase = .prepared,

            /// Whether `scope_id` is a committed row the next order keeps,
            /// re-collected or not.
            fn keepsRow(self: *const @This(), scope_id: u64) bool {
                for (self.rows.next_scope_ids, self.rows.scope_created) |row_scope_id, created| {
                    if (!created and row_scope_id.raw() == scope_id) return true;
                }
                return false;
            }

            /// Whether `scope_id` is a survivor this collection re-collects
            /// in place: its old descriptors retire, its scope stays.
            fn recollectsRow(self: *const @This(), scope_id: u64) bool {
                for (self.rows.next_scope_ids, self.rows.scope_created, self.recollected) |row_scope_id, created, recollected| {
                    if (!created and recollected and row_scope_id.raw() == scope_id) return true;
                }
                return false;
            }

            /// Whether `scope_id` is a committed row the next order omits.
            fn removesRow(self: *const @This(), scope_id: u64) bool {
                for (self.rows.removed_scope_ids) |row_scope_id| if (row_scope_id.raw() == scope_id) return true;
                return false;
            }

            /// Publishes the reconciliation into the committed site without
            /// allocating. Created rows are counted with every row scope the
            /// collection publishes, so only reuse and removal are recorded
            /// here.
            fn commit(self: *@This(), collection: *StagedCollectionCtx) void {
                if (self.phase.isCommitted()) @panic("nested row sync committed twice");
                const engine_ptr = collection.engine;
                // The subtree journal applied before this collection may
                // have swapped sites around while dropping emptied ones; the
                // site is found by its key again, not by the index it held.
                self.rows.site_index = engine_ptr.each_row_site_indexes.get(.{ .parent_scope_id = self.parent_scope_id, .site_ordinal = self.site_ordinal }) orelse @panic("nested row sync lost its committed site before publication");
                var hooks = StagedEachRowSyncHooks.init(collection, collection.signal_roc_host orelse @panic("staged nested row sync lacked Roc host"), &self.inputs);
                var diff = if (self.direct_delta) self.commitDirectRows(engine_ptr) else self.rows.commit(&engine_ptr.each_row_sites, &engine_ptr.each_row_memberships_by_scope_id, self.inputs.keys, self.inputs.items, &hooks);
                if (self.inputs.rows_transition) |*transition| {
                    if (self.direct_delta) engine_ptr.pending_roc_metrics.bump(.rows_order_links_touched, @intCast(transition.orderLinksTouched()));
                    transition.commit();
                } else @panic("nested row sync lacked Rows transition");
                const site_index = self.rows.site_index;
                const rows_site_id = self.inputs.rows_site_id orelse @panic("nested row sync lacked stable Rows site");
                while (engine_ptr.each_generation_ids_by_site_index.items.len <= site_index) engine_ptr.each_generation_ids_by_site_index.appendAssumeCapacity(null);
                if (engine_ptr.each_generation_ids_by_rows_site.get(rows_site_id)) |old_id| {
                    self.retired_generation = (engine_ptr.each_generations.fetchRemove(old_id) orelse @panic("stable nested Rows site named an absent generation")).value;
                }
                engine_ptr.each_generations.putAssumeCapacity(self.inputs.generation.id, self.inputs.generation);
                engine_ptr.each_generation_ids_by_site_index.items[site_index] = self.inputs.generation.id;
                engine_ptr.each_generation_ids_by_rows_site.putAssumeCapacity(rows_site_id, self.inputs.generation.id);
                self.inputs.candidate_bindings.commit(&engine_ptr.committed_row_bindings);
                self.inputs.transfer();
                hooks.base.recordRows(diff.rows_reused, 0, diff.rows_removed);
                diff.deinit(self.allocator);
                self.phase.markCommitted();
            }

            fn commitDirectRows(self: *@This(), engine_ptr: *Self) HostKeyedRowDiffResult {
                const site = &engine_ptr.each_row_sites.items[self.rows.site_index];
                while (engine_ptr.each_row_memberships_by_scope_id.items.len <= self.rows.highest_scope_id.index()) engine_ptr.each_row_memberships_by_scope_id.appendAssumeCapacity(null);
                for (site.scope_ids.items) |scope_id| engine_ptr.each_row_memberships_by_scope_id.items[scope_id.index()] = null;
                site.scope_ids.clearRetainingCapacity();
                site.scope_ids.appendSliceAssumeCapacity(self.rows.next_scope_ids);
                site.hash_links.items.len = self.rows.next_scope_ids.len;
                @memset(site.hash_links.items, each_runtime.missing_row_index);
                site.hash_heads.clearRetainingCapacity();
                for (self.rows.next_scope_ids, self.rows.key_hashes, 0..) |scope_id, key_hash, row_index| {
                    const entry = site.hash_heads.getOrPutAssumeCapacity(key_hash);
                    if (entry.found_existing) site.hash_links.items[row_index] = entry.value_ptr.*;
                    entry.value_ptr.* = row_index;
                    engine_ptr.each_row_memberships_by_scope_id.items[scope_id.index()] = .{ .site_index = self.rows.site_index, .row_index = row_index };
                }

                var unchanged_count: u64 = 0;
                var updated_count: u64 = 0;
                for (self.rows.scope_created, self.rows.row_items_changed) |created, changed| {
                    if (created) continue;
                    if (changed) updated_count += 1 else unchanged_count += 1;
                }
                const result = HostKeyedRowDiffResult{
                    .scope_ids = self.rows.next_scope_ids,
                    .row_items_changed = self.rows.row_items_changed,
                    .scope_created = self.rows.scope_created,
                    .removed_scope_ids = self.rows.removed_scope_ids,
                    .rows_reused = self.rows.next_scope_ids.len - self.rows.created_count,
                    .rows_created = @intCast(self.rows.created_count),
                    .rows_removed = @intCast(self.rows.removed_scope_ids.len),
                    .row_items_unchanged = unchanged_count,
                    .row_items_updated = updated_count,
                };
                self.rows.next_scope_ids = &.{};
                self.rows.row_items_changed = &.{};
                self.rows.scope_created = &.{};
                self.rows.removed_scope_ids = &.{};
                return result;
            }

            fn deinit(self: *@This()) void {
                self.rows.deinit();
                if (self.retired_generation) |generation| {
                    generation.deinit(self.allocator, self.inputs.ctx, self.inputs.roc_host, &self.inputs.engine.pending_roc_metrics);
                    self.allocator.destroy(generation);
                }
                self.inputs.deinit();
                self.allocator.free(self.recollected);
                self.allocator.free(self.pieces);
                self.* = undefined;
            }
        };

        const PreparedInitialEach = struct {
            const Row = struct {
                elem: abi.Elem,
                counts: StaticRootCounts,
                key_hash: u64,
                row_handle: row_handles.RowHandleId,
            };

            allocator: std.mem.Allocator,
            engine: *Self,
            host_ctx: Ctx.Handle,
            roc_host: *abi.RocHost,
            ops: HostEachOps,
            inputs: PreparedEachInputs,
            owns_inputs: bool = true,
            rows: []Row,
            total_counts: StaticRootCounts = .{},
            phase: CommitPhase = .prepared,

            /// Evaluates every row of an each mounted by a staged collection.
            /// `provisional_states` are that collection's not-yet-published state
            /// cells, which the items signal may reference before the state
            /// table holds them.
            fn prepare(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, each: *const HostNodeEachDesc, parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal, allocator: std.mem.Allocator, provisional_states: []const HostState) CollectionError!*@This() {
                const plan = allocator.create(@This()) catch return error.OutOfMemory;
                errdefer allocator.destroy(plan);
                var inputs = try PreparedEachInputs.prepareWithProvisionalStates(engine, ctx, roc_host, each, allocator, provisional_states);
                errdefer inputs.deinit();
                const rows = allocator.alloc(Row, inputs.items.len) catch return error.OutOfMemory;
                errdefer allocator.free(rows);
                var evaluated: usize = 0;
                errdefer for (rows[0..evaluated]) |row| row.elem.decref(roc_host);

                var hash_heads: std.AutoHashMapUnmanaged(u64, usize) = .empty;
                defer hash_heads.deinit(allocator);
                const hash_links = allocator.alloc(usize, inputs.keys.len) catch return error.OutOfMemory;
                defer allocator.free(hash_links);
                @memset(hash_links, each_runtime.missing_row_index);
                var hooks = EachRowSync{ .engine = engine, .ctx = ctx, .roc_host = roc_host, .inputs = &inputs };
                var total: StaticRootCounts = .{};
                for (inputs.keys, inputs.items, 0..) |key, item, index| {
                    const key_hash = hooks.hashKey(key);
                    if (hash_heads.get(key_hash)) |head| {
                        var previous = head;
                        while (previous != each_runtime.missing_row_index) {
                            if (hooks.nextKeysEqual(inputs.keys[previous], key)) {
                                hooks.failDuplicateEachKey(parent_scope_id, site_ordinal, previous, index, key);
                            }
                            previous = hash_links[previous];
                        }
                    }
                    const entry = hash_heads.getOrPut(allocator, key_hash) catch return error.OutOfMemory;
                    if (entry.found_existing) hash_links[index] = entry.value_ptr.*;
                    entry.value_ptr.* = index;

                    const row_handle = engine.row_handle_registry.insert(allocator, {}) catch |err| return switch (err) {
                        error.OutOfMemory => error.OutOfMemory,
                        error.ResourceLimit => error.ResourceLimit,
                    };
                    inputs.created_handles.append(allocator, row_handle) catch {
                        _ = engine.row_handle_registry.remove(row_handle) catch unreachable;
                        return error.OutOfMemory;
                    };
                    inputs.candidate_bindings.putAssumeCapacity(row_handle, .{ .generation_id = inputs.generation.id, .item_slot = inputs.slot(item) orelse return error.InvalidDescriptor }, .{ .snapshot = key }) catch return error.InvalidDescriptor;
                    inputs.row_handles_by_index[item] = row_handle;
                    const key_bytes = inputs.key(key) orelse return error.InvalidDescriptor;
                    const elem = retained_values.callEachRowBuilder(roc_host, each.ops.row, abi.RocStr.fromSlice(key_bytes, roc_host), row_handle.raw());
                    rows[index] = .{ .elem = elem, .counts = .{}, .key_hash = key_hash, .row_handle = row_handle };
                    evaluated += 1;
                    rows[index].counts = try countStaticRootNodes(elem);
                    try PreparedReplacementOwner.addRootCounts(&total, rows[index].counts);
                }
                plan.* = .{
                    .allocator = allocator,
                    .engine = engine,
                    .host_ctx = ctx,
                    .roc_host = roc_host,
                    .ops = each.ops,
                    .inputs = inputs,
                    .rows = rows,
                    .total_counts = total,
                };
                return plan;
            }

            /// Joins the rows' subtrees, one scope per row, and the row scope
            /// records to the collection's cumulative plan. The site itself
            /// was counted by whichever reservation covered its enclosing
            /// subtree, so nothing here is relative to the sites or rows
            /// appended so far.
            fn reserveForCollection(self: *const @This(), collection: *StagedCollectionCtx) CollectionError!void {
                try collection.reserveCounts(.{ .roots = self.total_counts, .external_scopes = self.rows.len, .each_rows = self.rows.len });
            }

            fn deinit(self: *@This()) void {
                if (!self.phase.isCommitted()) for (self.rows) |row| row.elem.decref(self.roc_host);
                self.allocator.free(self.rows);
                if (self.owns_inputs) self.inputs.deinit();
                const allocator = self.allocator;
                allocator.destroy(self);
            }
        };

        const AggregateBranchSelection = struct {
            node_id: ids.NodeId,
            parent_scope_id: ids.ScopeId,
            site_ordinal: ids.SiteOrdinal,
            parent_elem_id: ids.ElemId,
            retired_scope_id: ids.ScopeId,
            render_insert_index: usize,
            binder_bindings: []const HostBinderBinding,
            branch: HostScopeBranch,
            elem: abi.Elem,
        };

        const PreparedIdentityRetirements = struct {
            node_ids: []u64,
            dom_ids: []u64,

            fn prepare(engine: *Self, allocator: std.mem.Allocator, target_scopes: []const bool) CollectionError!@This() {
                var node_count: usize = 0;
                for (engine.node_identities.items) |identity| {
                    if (identity.scope_id.index() >= target_scopes.len) return error.ResourceLimit;
                    if (identity.lifecycle.isActive() and target_scopes[identity.scope_id.index()]) node_count = std.math.add(usize, node_count, 1) catch return error.ResourceLimit;
                }
                const node_ids = allocator.alloc(u64, node_count) catch return error.OutOfMemory;
                errdefer allocator.free(node_ids);
                var node_write: usize = 0;
                for (engine.node_identities.items) |identity| if (identity.lifecycle.isActive() and target_scopes[identity.scope_id.index()]) {
                    node_ids[node_write] = identity.node_id.raw();
                    node_write += 1;
                };

                var dom_count: usize = 0;
                for (engine.dom_identities.items) |identity| {
                    if (identity.scope_id.index() >= target_scopes.len) return error.ResourceLimit;
                    if (identity.lifecycle.isActive() and target_scopes[identity.scope_id.index()]) dom_count = std.math.add(usize, dom_count, 1) catch return error.ResourceLimit;
                }
                const dom_ids = allocator.alloc(u64, dom_count) catch return error.OutOfMemory;
                errdefer allocator.free(dom_ids);
                var dom_write: usize = 0;
                for (engine.dom_identities.items, 1..) |identity, elem_id| if (identity.lifecycle.isActive() and target_scopes[identity.scope_id.index()]) {
                    dom_ids[dom_write] = elem_id;
                    dom_write += 1;
                };
                return .{ .node_ids = node_ids, .dom_ids = dom_ids };
            }

            fn prepareExactRemoval(engine: *Self, allocator: std.mem.Allocator, retired_scope_ids: []const ids.ScopeId, removal: *const structural_splice.PreparedRemoval) CollectionError!@This() {
                var node_capacity = removal.node_indexes.scope_site_indexes.items.len;
                for (retired_scope_ids) |scope_id| node_capacity = std.math.add(
                    usize,
                    node_capacity,
                    engine.active_stream.scopeOwnedNodeIds(scope_id).len,
                ) catch return error.ResourceLimit;
                var unique_nodes = std.AutoHashMapUnmanaged(u64, void).empty;
                defer unique_nodes.deinit(allocator);
                unique_nodes.ensureTotalCapacity(allocator, std.math.cast(u32, node_capacity) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                var node_list = shared_buffer.List(u64).empty;
                errdefer node_list.deinit(allocator);
                node_list.ensureTotalCapacity(allocator, node_capacity) catch return error.OutOfMemory;
                for (retired_scope_ids) |scope_id| for (engine.active_stream.scopeOwnedNodeIds(scope_id)) |node_id| {
                    const entry = unique_nodes.getOrPutAssumeCapacity(node_id.raw());
                    if (!entry.found_existing) node_list.appendAssumeCapacity(node_id.raw());
                };
                for (removal.node_indexes.scope_site_indexes.items) |site_index| {
                    if (site_index >= engine.active_stream.scope_sites.items.len) return error.InvalidDescriptor;
                    const node_id = engine.active_stream.scope_sites.items[site_index].node_id;
                    const entry = unique_nodes.getOrPutAssumeCapacity(node_id.raw());
                    if (!entry.found_existing) node_list.appendAssumeCapacity(node_id.raw());
                }
                for (node_list.items) |node_id_raw| {
                    const node_id = ids.NodeId.fromRaw(node_id_raw);
                    if (node_id.index() >= engine.node_identities.items.len) return error.ResourceLimit;
                    const identity = engine.node_identities.items[node_id.index()];
                    if (!identity.lifecycle.isActive() or identity.node_id != node_id) return error.InvalidDescriptor;
                }
                const node_ids = node_list.toOwnedSlice(allocator) catch return error.OutOfMemory;
                errdefer allocator.free(node_ids);

                const dom_ids = allocator.alloc(u64, removal.scan.removed_elem_ids.len) catch return error.OutOfMemory;
                errdefer allocator.free(dom_ids);
                for (removal.scan.removed_elem_ids, dom_ids) |elem_id, *dom_id_out| {
                    if (elem_id == 0 or elem_id > engine.dom_identities.items.len) return error.ResourceLimit;
                    const identity = engine.dom_identities.items[@intCast(elem_id - 1)];
                    if (!identity.lifecycle.isActive()) return error.InvalidDescriptor;
                    dom_id_out.* = elem_id;
                }
                return .{ .node_ids = node_ids, .dom_ids = dom_ids };
            }

            fn apply(self: *const @This(), engine: *Self) void {
                for (self.node_ids) |node_id| {
                    const identity = &engine.node_identities.items[@intCast(node_id)];
                    if (!engine.active_node_identity_ids.remove(identityKey(identity.scope_id.raw(), identity.ordinal.raw()))) @panic("prepared node identity retirement no longer matched active index");
                    identity.lifecycle = .{ .retired = ids.Generation.fromRaw(engine.identity_reuse_barrier) };
                }
                for (self.dom_ids) |elem_id| {
                    const identity = &engine.dom_identities.items[@intCast(elem_id - 1)];
                    if (!engine.active_dom_identity_ids.remove(identityKey(identity.scope_id.raw(), identity.ordinal.raw()))) @panic("prepared DOM identity retirement no longer matched active index");
                    identity.lifecycle = .{ .retired = ids.Generation.fromRaw(engine.identity_reuse_barrier) };
                }
                engine.has_inactive_node_identities = engine.has_inactive_node_identities or self.node_ids.len != 0;
                engine.has_inactive_dom_identities = engine.has_inactive_dom_identities or self.dom_ids.len != 0;
            }

            fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
                allocator.free(self.node_ids);
                allocator.free(self.dom_ids);
                self.* = undefined;
            }
        };

        const PreparedStateRetirementIndexes = struct {
            indexes_descending: []usize,

            fn descending(_: void, left: usize, right: usize) bool {
                return left > right;
            }

            fn prepare(engine: *Self, allocator: std.mem.Allocator, descriptor_indexes: []const usize) CollectionError!@This() {
                const indexes = allocator.alloc(usize, descriptor_indexes.len) catch return error.OutOfMemory;
                errdefer allocator.free(indexes);
                for (descriptor_indexes, 0..) |descriptor_index, offset| {
                    if (descriptor_index >= engine.active_stream.states.items.len) return error.InvalidDescriptor;
                    const node_id = engine.active_stream.states.items[descriptor_index].node_id;
                    if (node_id.index() >= engine.state_indexes_by_node_id.items.len) return error.InvalidDescriptor;
                    indexes[offset] = engine.state_indexes_by_node_id.items[node_id.index()] orelse return error.InvalidDescriptor;
                }
                std.mem.sort(usize, indexes, {}, descending);
                if (indexes.len > 1) for (indexes[1..], indexes[0 .. indexes.len - 1]) |current, previous| {
                    if (current == previous) return error.ResourceLimit;
                };
                return .{ .indexes_descending = indexes };
            }

            fn reserveRetired(self: *const @This(), allocator: std.mem.Allocator, retired: *shared_buffer.List(HostState)) CollectionError!void {
                retired.ensureUnusedCapacity(allocator, self.indexes_descending.len) catch return error.OutOfMemory;
            }

            fn apply(self: *const @This(), engine: *Self, retired: *shared_buffer.List(HostState)) void {
                for (self.indexes_descending) |index| {
                    const removed = engine.states.swapRemove(index);
                    engine.clearStateCellIndex(removed.state_id, index);
                    retired.appendAssumeCapacity(removed);
                    if (index < engine.states.items.len) {
                        const moved = engine.states.items[index];
                        engine.state_indexes_by_node_id.items[@intCast(moved.state_id)] = index;
                    }
                }
            }

            fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
                allocator.free(self.indexes_descending);
                self.* = undefined;
            }
        };

        fn prepareRowRetirementForScopes(engine: *Self, allocator: std.mem.Allocator, scope_ids: anytype) CollectionError!each_runtime.PreparedRowRemovals {
            var removals: shared_buffer.List(each_runtime.RowRemoval) = .empty;
            defer removals.deinit(allocator);
            removals.ensureTotalCapacity(allocator, scope_ids.len) catch return error.OutOfMemory;
            for (scope_ids) |scope_id| {
                const raw_scope_id = if (@TypeOf(scope_id) == u64) scope_id else scope_id.raw();
                const scope_index: usize = @intCast(raw_scope_id);
                if (scope_index >= engine.scopes.items.len) return error.ResourceLimit;
                switch (engine.scopes.items[scope_index].step) {
                    .each_row => |row| {
                        const membership = engine.each_row_memberships_by_scope_id.items[scope_index] orelse return error.InvalidDescriptor;
                        if (membership.site_index >= engine.each_row_sites.items.len) return error.InvalidDescriptor;
                        removals.appendAssumeCapacity(.{
                            .scope_id = ids.ScopeId.fromRaw(raw_scope_id),
                            .key_hash = row.key_hash,
                            .site_key = engine.each_row_sites.items[membership.site_index].key,
                        });
                    },
                    .root, .component, .when_branch => {},
                }
            }
            return try each_runtime.prepareRowRemovals(allocator, engine.each_row_sites.items, engine.each_row_memberships_by_scope_id.items, removals.items);
        }

        const PreparedEffectRetirements = struct {
            cleanup_names: shared_buffer.List([]const u8) = .empty,

            fn prepare(engine: *Self, allocator: std.mem.Allocator, cleanup_indexes: []const usize) CollectionError!@This() {
                var self: @This() = .{};
                errdefer self.deinit(allocator, null);
                try self.cleanup_names.ensureTotalCapacity(allocator, cleanup_indexes.len);
                for (cleanup_indexes) |cleanup_index| {
                    if (cleanup_index >= engine.active_stream.cleanups.items.len) return error.ResourceLimit;
                    const name = try allocator.dupe(u8, engine.active_stream.cleanups.items[cleanup_index].name);
                    self.cleanup_names.appendAssumeCapacity(name);
                }
                try engine.cleanup_events.ensureUnusedCapacity(allocator, self.cleanup_names.items.len);
                return self;
            }

            fn apply(self: *@This(), engine: *Self, _: Ctx.Handle) void {
                engine.cleanup_events.appendSliceAssumeCapacity(self.cleanup_names.items);
                self.cleanup_names.items.len = 0;
            }

            fn deinit(self: *@This(), allocator: std.mem.Allocator, _: ?*abi.RocHost) void {
                for (self.cleanup_names.items) |name| allocator.free(name);
                self.cleanup_names.deinit(allocator);
                self.* = undefined;
            }
        };

        const PreparedEachRowSubtreeRetirement = struct {
            targets: ?PreparedStructuralTargets = null,
            identities: ?PreparedIdentityRetirements = null,
            states: ?PreparedStateRetirementIndexes = null,
            rows: ?each_runtime.PreparedRowRemovals = null,
            effects: ?PreparedEffectRetirements = null,
            retired_states: shared_buffer.List(HostState) = .empty,
            retired_steps: shared_buffer.List(HostScopeStep) = .empty,

            fn prepare(engine: *Self, allocator: std.mem.Allocator, removed_root_scope_ids: []const u64) CollectionError!@This() {
                return prepareWithTargets(engine, allocator, removed_root_scope_ids, removed_root_scope_ids);
            }

            fn prepareWithTargets(engine: *Self, allocator: std.mem.Allocator, descriptor_root_scope_ids: []const u64, removed_root_scope_ids: []const u64) CollectionError!@This() {
                var self: @This() = .{};
                errdefer self.deinit(engine, allocator, null, null);
                self.targets = try PreparedStructuralTargets.prepare(engine, allocator, descriptor_root_scope_ids, removed_root_scope_ids, null);
                const target_scopes = self.targets.?.descriptor_target_scopes;
                const retirement_scope_ids = self.targets.?.scope_retirement.?.scope_ids;
                self.identities = try PreparedIdentityRetirements.prepare(engine, allocator, target_scopes);

                var state_indexes: shared_buffer.List(usize) = .empty;
                defer state_indexes.deinit(allocator);
                state_indexes.ensureTotalCapacity(allocator, engine.active_stream.states.items.len) catch return error.OutOfMemory;
                for (engine.active_stream.states.items, 0..) |state, state_index| {
                    const node_index = engine.active_stream.nodeDescriptorIndex(state.node_id) orelse return error.InvalidDescriptor;
                    const site_index = node_index.scope_sites.get(.state) orelse return error.InvalidDescriptor;
                    if (site_index >= engine.active_stream.scope_sites.items.len) return error.InvalidDescriptor;
                    const owner = engine.active_stream.scope_sites.items[site_index].scope_id;
                    if (owner.index() >= target_scopes.len) return error.ResourceLimit;
                    if (target_scopes[owner.index()]) state_indexes.appendAssumeCapacity(state_index);
                }
                self.states = try PreparedStateRetirementIndexes.prepare(engine, allocator, state_indexes.items);
                try self.states.?.reserveRetired(allocator, &self.retired_states);
                self.rows = try prepareRowRetirementForScopes(engine, allocator, retirement_scope_ids);

                var cleanup_indexes: shared_buffer.List(usize) = .empty;
                defer cleanup_indexes.deinit(allocator);
                for (target_scopes, 0..) |targeted, scope_id| if (targeted) {
                    for (engine.active_stream.lifecycleIndices(ids.ScopeId.fromIndex(scope_id))) |lifecycle| if (lifecycle.kind == .cleanup) {
                        cleanup_indexes.append(allocator, lifecycle.index) catch return error.OutOfMemory;
                    };
                };
                self.effects = try PreparedEffectRetirements.prepare(engine, allocator, cleanup_indexes.items);
                self.retired_steps.ensureUnusedCapacity(allocator, retirement_scope_ids.len) catch return error.OutOfMemory;
                return self;
            }

            fn applyBeforeRowCommit(self: *@This(), engine: *Self, allocator: std.mem.Allocator) void {
                self.states.?.apply(engine, &self.retired_states);
                self.identities.?.apply(engine);
                var row_keys = EachRowScopeKeyLookup{ .engine = engine };
                self.rows.?.apply(allocator, &engine.each_row_sites, &engine.each_row_site_indexes, &engine.each_row_memberships_by_scope_id, &row_keys);
            }

            fn refineDescriptorOwnedRetirement(self: *@This(), engine: *Self, allocator: std.mem.Allocator, removal: *const structural_splice.PreparedRemoval) CollectionError!void {
                const retirement_scope_ids = self.targets.?.scope_retirement.?.scope_ids;
                var exact_identities = try PreparedIdentityRetirements.prepareExactRemoval(engine, allocator, retirement_scope_ids, removal);
                errdefer exact_identities.deinit(allocator);
                var exact_effects = try PreparedEffectRetirements.prepare(engine, allocator, removal.node_indexes.cleanup_indexes.items);
                errdefer exact_effects.deinit(allocator, null);
                self.identities.?.deinit(allocator);
                self.identities = exact_identities;
                self.effects.?.deinit(allocator, null);
                self.effects = exact_effects;
            }

            fn applyAfterRowCommit(self: *@This(), engine: *Self, allocator: std.mem.Allocator) void {
                engine.commitPreparedScopeRetirement(allocator, &self.targets.?.scope_retirement.?, &self.retired_steps);
            }

            fn applyEffectsAfterPublication(self: *@This(), engine: *Self, ctx: Ctx.Handle) void {
                self.effects.?.apply(engine, ctx);
            }

            fn deinit(self: *@This(), engine: *Self, allocator: std.mem.Allocator, ctx: ?Ctx.Handle, roc_host: ?*abi.RocHost) void {
                if (ctx) |host_ctx| if (roc_host) |host| {
                    for (self.retired_states.items) |*state| state.retire(host_ctx, host, &engine.pending_roc_metrics);
                    for (self.retired_steps.items) |*step| engine.releasePreparedRetiredScopeStep(step);
                };
                self.retired_states.deinit(allocator);
                self.retired_steps.deinit(allocator);
                if (self.effects) |*effects| effects.deinit(allocator, roc_host);
                if (self.rows) |*rows| rows.deinit(allocator);
                if (self.states) |*states| states.deinit(allocator);
                if (self.identities) |*identities| identities.deinit(allocator);
                if (self.targets) |*targets| targets.deinit(allocator);
                self.* = undefined;
            }
        };

        const PreparedEachRowReplacementCollection = struct {
            const RowElem = struct {
                scope_id: ids.ScopeId,
                item_slot: u64,
                created: bool,
                elem: abi.Elem,
            };
            const ReplacementRow = struct {
                scope_id: ids.ScopeId,
                item_slot: u64,
                created: bool,
                start: usize,
                len: usize,
                /// Index range of this row's scope sites in the replacement
                /// stream, so the rebase can attribute each staged site to the
                /// row that created it without guessing from render positions.
                site_start: usize,
                site_len: usize,
            };

            engine: *Self,
            host_ctx: Ctx.Handle,
            roc_host: *abi.RocHost,
            prepared_rows: *PreparedActiveEachRows,
            replacement: *PreparedReplacementOwner = undefined,
            owns_replacement: bool = true,
            row_elems: []RowElem = &.{},
            replacement_rows: []ReplacementRow = &.{},
            counts: StaticRootCounts = .{},
            phase: CommitPhase = .prepared,

            fn prepare(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, site: HostNodeScopeSiteDesc, each: HostNodeEachDesc, prepared_rows: *PreparedActiveEachRows, limits: collection_budget.Limits, dirty_source_node_ids: []const u64, cache_overlay: ?*const signal_records.PreparedCacheUpdates, state_update: []const PreparedExternalState) CollectionError!*@This() {
                const inputs = &prepared_rows.inputs;
                const previous_bindings = engine.active_each_candidate_bindings;
                const previous_inputs = engine.active_each_candidate_inputs;
                const previous_generation = engine.active_each_candidate_generation;
                const previous_rows_site_id = engine.active_each_candidate_rows_site_id;
                engine.active_each_candidate_bindings = &inputs.candidate_bindings;
                engine.active_each_candidate_inputs = inputs;
                engine.active_each_candidate_generation = inputs.generation;
                engine.active_each_candidate_rows_site_id = inputs.rows_site_id;
                defer {
                    engine.active_each_candidate_bindings = previous_bindings;
                    engine.active_each_candidate_inputs = previous_inputs;
                    engine.active_each_candidate_generation = previous_generation;
                    engine.active_each_candidate_rows_site_id = previous_rows_site_id;
                }
                const plan = try prepareEvaluated(engine, ctx, roc_host, each, prepared_rows);
                errdefer plan.deinit();
                plan.replacement = try PreparedReplacementOwner.create(engine, ctx, roc_host, limits, plan.counts, plan.row_elems.len);
                plan.owns_replacement = true;
                plan.replacement.collection.cache_overlay = cache_overlay;
                try plan.replacement.collection.stageExternalStates(roc_host, state_update);
                try plan.collectInto(site, each, plan.replacement, dirty_source_node_ids);
                plan.replacement.materialize();
                try plan.finalizeRenderSpans(site);
                plan.releaseEvaluatedRows();
                return plan;
            }

            fn prepareEvaluated(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, each: HostNodeEachDesc, prepared_rows: *PreparedActiveEachRows) CollectionError!*@This() {
                const rows = &prepared_rows.rows;
                const inputs = &prepared_rows.inputs;
                const row_count = if (prepared_rows.direct_delta) prepared_rows.candidateRows().len() else rows.next_scope_ids.len;
                if (inputs.generation.item_count != row_count) return error.ResourceLimit;
                const allocator = Ctx.allocator(ctx);
                const plan = allocator.create(@This()) catch return error.OutOfMemory;
                errdefer allocator.destroy(plan);
                plan.* = .{ .engine = engine, .host_ctx = ctx, .roc_host = roc_host, .prepared_rows = prepared_rows, .owns_replacement = false };

                var changed_count: usize = 0;
                if (prepared_rows.direct_delta) {
                    changed_count = prepared_rows.candidateRows().createdLen();
                } else for (rows.scope_created) |created| if (created) {
                    changed_count = std.math.add(usize, changed_count, 1) catch return error.ResourceLimit;
                };
                const transition = if (inputs.rows_transition) |*value| value else return error.InvalidDescriptor;
                transition.prepareRenderSpanUpdates(changed_count) catch |err| return switch (err) {
                    error.OutOfMemory => error.OutOfMemory,
                    error.ResourceLimit => error.ResourceLimit,
                    else => error.InvalidDescriptor,
                };
                plan.row_elems = allocator.alloc(RowElem, changed_count) catch return error.OutOfMemory;
                errdefer allocator.free(plan.row_elems);
                plan.replacement_rows = allocator.alloc(ReplacementRow, changed_count) catch return error.OutOfMemory;
                errdefer allocator.free(plan.replacement_rows);
                var evaluated: usize = 0;
                errdefer for (plan.row_elems[0..evaluated]) |*entry| entry.elem.decref(roc_host);
                if (prepared_rows.direct_delta) {
                    var created = prepared_rows.candidateRows().iterateCreated();
                    while (try created.next()) |row| {
                        const elem = retained_values.callEachRowBuilder(roc_host, each.ops.row, abi.RocStr.fromSlice(row.key, roc_host), row.row_handle.raw());
                        plan.row_elems[evaluated] = .{ .scope_id = row.scope_id, .item_slot = row.item_slot, .created = true, .elem = elem };
                        evaluated += 1;
                        try AggregateBranchCollection.addCounts(&plan.counts, try countStaticRootNodes(elem));
                    }
                    if (evaluated != changed_count) return error.InvalidDescriptor;
                } else {
                    for (rows.scope_created, 0..) |created, row_index| {
                        if (!created) continue;
                        const key = inputs.key(row_index) orelse return error.InvalidDescriptor;
                        const row_handle = inputs.row_handles_by_index[row_index] orelse return error.InvalidDescriptor;
                        const elem = retained_values.callEachRowBuilder(roc_host, each.ops.row, abi.RocStr.fromSlice(key, roc_host), row_handle.raw());
                        plan.row_elems[evaluated] = .{ .scope_id = rows.next_scope_ids[row_index], .item_slot = inputs.slot(row_index) orelse return error.InvalidDescriptor, .created = true, .elem = elem };
                        evaluated += 1;
                        try AggregateBranchCollection.addCounts(&plan.counts, try countStaticRootNodes(elem));
                    }
                }
                return plan;
            }

            fn collectInto(plan: *@This(), site: HostNodeScopeSiteDesc, each: HostNodeEachDesc, replacement: *PreparedReplacementOwner, dirty_source_node_ids: []const u64) CollectionError!void {
                try plan.attachScopeIds(replacement);
                try plan.collectRowsInto(site, each, replacement, dirty_source_node_ids);
            }

            fn attachScopeIds(plan: *@This(), replacement: *PreparedReplacementOwner) CollectionError!void {
                const allocator = Ctx.allocator(plan.host_ctx);
                plan.replacement = replacement;
                const replacement_scope_ids = allocator.alloc(u64, plan.row_elems.len) catch return error.OutOfMemory;
                defer allocator.free(replacement_scope_ids);
                for (plan.row_elems, replacement_scope_ids) |row, *scope_id| scope_id.* = row.scope_id.raw();
                try replacement.attachExternalScopeIds(replacement_scope_ids);
            }

            fn collectRowsInto(plan: *@This(), site: HostNodeScopeSiteDesc, each: HostNodeEachDesc, replacement: *PreparedReplacementOwner, dirty_source_node_ids: []const u64) CollectionError!void {
                plan.replacement = replacement;
                for (plan.row_elems, 0..) |*entry, replacement_index| {
                    const segment = try replacement.collectEachRow(site, each, entry.elem, entry.scope_id, entry.created, dirty_source_node_ids);
                    plan.replacement_rows[replacement_index] = .{
                        .scope_id = entry.scope_id,
                        .item_slot = entry.item_slot,
                        .created = entry.created,
                        .start = segment.start,
                        .len = segment.len,
                        .site_start = segment.site_start,
                        .site_len = segment.site_len,
                    };
                }
            }

            fn finalizeRenderSpans(plan: *@This(), site: HostNodeScopeSiteDesc) CollectionError!void {
                const transition = if (plan.prepared_rows.inputs.rows_transition) |*value| value else return error.InvalidDescriptor;
                for (plan.replacement_rows) |row| {
                    const span = try rowRenderSpanForRange(&plan.replacement.stream, site.parent_elem_id, row.start, row.len);
                    transition.setCandidateRenderSpanAssumeCapacity(row.item_slot, span) catch |err| return switch (err) {
                        error.OutOfMemory => error.OutOfMemory,
                        error.ResourceLimit => error.ResourceLimit,
                        else => error.InvalidDescriptor,
                    };
                }
            }

            fn releaseEvaluatedRows(plan: *@This()) void {
                const allocator = Ctx.allocator(plan.host_ctx);
                for (plan.row_elems) |*entry| entry.elem.decref(plan.roc_host);
                allocator.free(plan.row_elems);
                plan.row_elems = &.{};
            }

            fn commit(self: *@This()) void {
                if (self.phase.isCommitted()) @panic("prepared each replacement collection committed twice");
                if (self.owns_replacement) self.replacement.collection.commit();
                self.phase.markCommitted();
            }

            fn deinit(self: *@This()) void {
                const allocator = Ctx.allocator(self.host_ctx);
                for (self.row_elems) |*entry| entry.elem.decref(self.roc_host);
                allocator.free(self.row_elems);
                allocator.free(self.replacement_rows);
                if (self.owns_replacement) self.replacement.deinit();
                allocator.destroy(self);
            }
        };

        fn rowRenderSpanForRange(stream: *const HostNodeDescriptorStream, parent_elem_id: ids.ElemId, start: usize, len: usize) CollectionError!rows_site_store.RowRenderSpan {
            if (start > stream.render_nodes.items.len or len > stream.render_nodes.items.len - start) return error.InvalidRenderTopology;
            if (len == 0) return .{};
            const nodes = stream.render_nodes.items[start..][0..len];
            var first_root: ?u64 = null;
            var last_root: ?u64 = null;
            var root_count: usize = 0;
            for (nodes) |node| if (renderNodeParentElemId(stream, node) == parent_elem_id.raw()) {
                if (first_root == null) first_root = node.elem_id.raw();
                last_root = node.elem_id.raw();
                root_count = std.math.add(usize, root_count, 1) catch return error.ResourceLimit;
            };
            if (root_count == 0) return error.InvalidRenderTopology;
            return .{
                .first_node = nodes[0].elem_id.raw(),
                .last_node = nodes[nodes.len - 1].elem_id.raw(),
                .first_root = first_root,
                .last_root = last_root,
                .root_count = std.math.cast(u32, root_count) orelse return error.ResourceLimit,
            };
        }

        /// Appends the render span of every committed row of `each_site`, in
        /// render order, one segment per row. Returns one past the last node
        /// any row owns, or `site_insert_index` when no row renders.
        fn appendEachSiteRenderSegments(self: *Self, allocator: std.mem.Allocator, each_site: HostEachSite, site_insert_index: usize, segments: *shared_buffer.List(HostEachRowRenderSegment)) CollectionError!usize {
            var render_index: usize = 0;
            var old_end: usize = site_insert_index;
            while (render_index < self.active_stream.render_nodes.items.len) {
                const scope_id = renderNodeScopeId(&self.active_stream, self.active_stream.render_nodes.items[render_index]);
                const row_scope_id = (self.eachSiteRowAncestorScopeId(scope_id, each_site) catch |err| return scopeError(err)) orelse {
                    render_index += 1;
                    continue;
                };
                const start = render_index;
                render_index += 1;
                while (render_index < self.active_stream.render_nodes.items.len) : (render_index += 1) {
                    const next_scope = renderNodeScopeId(&self.active_stream, self.active_stream.render_nodes.items[render_index]);
                    const next_row = self.eachSiteRowAncestorScopeId(next_scope, each_site) catch |err| return scopeError(err);
                    if (next_row == null or next_row.? != row_scope_id) break;
                }
                segments.append(allocator, .{ .scope_id = ids.ScopeId.fromRaw(row_scope_id), .start = start, .len = render_index - start }) catch return error.OutOfMemory;
                old_end = @max(old_end, render_index);
            }
            return old_end;
        }

        /// One edited each site described in old coordinates: the rows it
        /// currently renders, the retirement the edit needs, and its rows in
        /// their next order as the pieces a `PreparedRenderLayoutPlan` lays out.
        const PreparedEachRowRenderLayout = struct {
            allocator: std.mem.Allocator,
            site: HostNodeScopeSiteDesc,
            targets: PreparedStructuralTargets,
            remove_starts: []usize,
            /// The site's next rows in order: a surviving row with its old
            /// span, or a collected row with its replacement-stream span.
            pieces: []PreparedRenderLayoutPlan.Piece,
            removal: structural_splice.PreparedMultiRemoval,
            /// One past the last active-stream render node any current row of
            /// this site owns, or the site's insertion point when it has no
            /// rows. Old coordinates, so sibling sites can be checked for
            /// overlap before any of them grows or shrinks.
            old_end: usize,

            fn prepare(engine: *Self, allocator: std.mem.Allocator, site: HostNodeScopeSiteDesc, rows: *const each_runtime.PreparedRowSync, replacements: []const PreparedEachRowReplacementCollection.ReplacementRow, collection: ?*const StagedCollectionCtx) CollectionError!@This() {
                if (!engine.active_stream.render_nodes_ordered) return error.ResourceLimit;
                var segments: shared_buffer.List(HostEachRowRenderSegment) = .empty;
                defer segments.deinit(allocator);
                var by_scope: std.AutoHashMapUnmanaged(u64, usize) = .empty;
                defer by_scope.deinit(allocator);
                const each_site = HostEachSite{ .parent_scope_id = site.scope_id, .site_ordinal = site.ordinal };
                const old_end = try engine.appendEachSiteRenderSegments(allocator, each_site, site.render_insert_index, &segments);
                for (segments.items, 0..) |segment, index| {
                    const entry = by_scope.getOrPut(allocator, segment.scope_id.raw()) catch return error.OutOfMemory;
                    if (entry.found_existing) return error.InvalidRenderTopology;
                    entry.value_ptr.* = index;
                }

                var descriptor_roots: shared_buffer.List(u64) = .empty;
                defer descriptor_roots.deinit(allocator);
                descriptor_roots.ensureTotalCapacity(allocator, std.math.add(usize, rows.removed_scope_ids.len, replacements.len) catch return error.ResourceLimit) catch return error.OutOfMemory;
                for (rows.removed_scope_ids) |scope_id| descriptor_roots.appendAssumeCapacity(scope_id.raw());
                var remove_starts_list: shared_buffer.List(usize) = .empty;
                defer remove_starts_list.deinit(allocator);
                remove_starts_list.ensureTotalCapacity(allocator, std.math.add(usize, rows.removed_scope_ids.len, replacements.len) catch return error.ResourceLimit) catch return error.OutOfMemory;
                for (rows.removed_scope_ids) |scope_id| {
                    const segment_index = by_scope.get(scope_id.raw()) orelse return error.InvalidScope;
                    remove_starts_list.appendAssumeCapacity(segments.items[segment_index].start);
                }
                for (replacements) |replacement| if (!replacement.created) {
                    const segment_index = by_scope.get(replacement.scope_id.raw()) orelse return error.InvalidScope;
                    remove_starts_list.appendAssumeCapacity(segments.items[segment_index].start);
                    descriptor_roots.appendAssumeCapacity(replacement.scope_id.raw());
                };
                var targets = try PreparedStructuralTargets.prepare(engine, allocator, descriptor_roots.items, @ptrCast(rows.removed_scope_ids), collection);
                errdefer targets.deinit(allocator);
                const target_scopes = targets.descriptor_target_scopes;
                remove_starts_list.clearRetainingCapacity();
                var inside_target = false;
                for (engine.active_stream.render_nodes.items, 0..) |node, index| {
                    const scope_id = renderNodeScopeId(&engine.active_stream, node);
                    if (scope_id >= target_scopes.len) return error.ResourceLimit;
                    const targeted = target_scopes[@intCast(scope_id)];
                    if (targeted and !inside_target) remove_starts_list.appendAssumeCapacity(index);
                    inside_target = targeted;
                }
                const remove_starts = remove_starts_list.toOwnedSlice(allocator) catch return error.OutOfMemory;
                errdefer allocator.free(remove_starts);
                const removal = structural_splice.prepareMultiRemoval(HostNodeDescriptorStream, allocator, &engine.active_stream, remove_starts, target_scopes, null) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.ResourceLimit => return error.ResourceLimit,
                    error.InvalidDescriptor => return error.InvalidDescriptor,
                    error.OverlappingIntervals => return error.OverlappingRemoval,
                };
                errdefer {
                    var mutable = removal;
                    mutable.deinit(allocator);
                }

                const pieces = allocator.alloc(PreparedRenderLayoutPlan.Piece, rows.next_scope_ids.len) catch return error.OutOfMemory;
                errdefer allocator.free(pieces);
                for (rows.next_scope_ids, pieces) |scope_id, *piece| {
                    const replacement: ?PreparedEachRowReplacementCollection.ReplacementRow = for (replacements) |candidate| {
                        if (candidate.scope_id == scope_id) break candidate;
                    } else null;
                    if (replacement) |row| {
                        piece.* = .{ .replacement = .{ .render_start = row.start, .render_len = row.len, .site_start = row.site_start, .site_len = row.site_len } };
                    } else {
                        const segment_index = by_scope.get(scope_id.raw()) orelse return error.InvalidScope;
                        const segment = segments.items[segment_index];
                        piece.* = .{ .survivor = .{ .scope_id = scope_id.raw(), .old_start = segment.start, .len = segment.len } };
                    }
                }
                return .{ .allocator = allocator, .site = site, .targets = targets, .remove_starts = remove_starts, .pieces = pieces, .removal = removal, .old_end = old_end };
            }

            fn deinit(self: *@This()) void {
                self.removal.deinit(self.allocator);
                self.allocator.free(self.pieces);
                self.allocator.free(self.remove_starts);
                self.targets.deinit(self.allocator);
                self.* = undefined;
            }
        };

        const PreparedFinalRenderTopology = struct {
            const ActiveStreamPosition = struct { value: usize };
            const ReplacementStreamPosition = struct { value: usize };
            const FinalTopologyPosition = struct { value: usize };
            const PlacementSource = union(enum) {
                active: ActiveStreamPosition,
                replacement: ReplacementStreamPosition,
            };
            const MetadataSource = enum { active, replacement };
            const Placement = struct {
                source: PlacementSource,
                final_start: FinalTopologyPosition,
                len: usize,

                fn active(source_start: ActiveStreamPosition, final_start: FinalTopologyPosition, len: usize) @This() {
                    return .{ .source = .{ .active = source_start }, .final_start = final_start, .len = len };
                }

                fn replacement(source_start: ReplacementStreamPosition, final_start: FinalTopologyPosition, len: usize) @This() {
                    return .{ .source = .{ .replacement = source_start }, .final_start = final_start, .len = len };
                }
            };
            allocator: std.mem.Allocator,
            render_nodes: shared_buffer.List(HostRenderNode) = .empty,
            metadata: std.AutoHashMapUnmanaged(u64, HostRenderElemIndex) = .empty,

            fn preparePlaced(engine: *Self, allocator: std.mem.Allocator, replacement: *const PreparedReplacementOwner, target_scopes: []const bool, removed_render_count: usize, placements: []const Placement) CollectionError!@This() {
                var prepared: @This() = .{ .allocator = allocator };
                errdefer prepared.deinit();
                const retained_len = std.math.sub(usize, engine.active_stream.render_nodes.items.len, removed_render_count) catch return error.ResourceLimit;
                const final_len = std.math.add(usize, retained_len, replacement.stream.render_nodes.items.len) catch return error.ResourceLimit;
                prepared.render_nodes = .{ .items = allocator.alloc(HostRenderNode, final_len) catch return error.OutOfMemory, .capacity = final_len };
                const filled = allocator.alloc(bool, final_len) catch return error.OutOfMemory;
                defer allocator.free(filled);
                @memset(filled, false);
                const sources = allocator.alloc(MetadataSource, final_len) catch return error.OutOfMemory;
                defer allocator.free(sources);
                const old_used = allocator.alloc(bool, engine.active_stream.render_nodes.items.len) catch return error.OutOfMemory;
                defer allocator.free(old_used);
                @memset(old_used, false);
                for (placements) |placement| {
                    const source_nodes, const source_start = switch (placement.source) {
                        .active => |position| .{ engine.active_stream.render_nodes.items, position.value },
                        .replacement => |position| .{ replacement.stream.render_nodes.items, position.value },
                    };
                    const final_start = placement.final_start.value;
                    if (source_start > source_nodes.len or placement.len > source_nodes.len - source_start) return error.ResourceLimit;
                    if (final_start > final_len or placement.len > final_len - final_start) return error.ResourceLimit;
                    for (filled[final_start..][0..placement.len]) |is_filled| if (is_filled) return error.ResourceLimit;
                    @memcpy(prepared.render_nodes.items[final_start..][0..placement.len], source_nodes[source_start..][0..placement.len]);
                    @memset(filled[final_start..][0..placement.len], true);
                    const source_kind: MetadataSource = switch (placement.source) {
                        .active => .active,
                        .replacement => .replacement,
                    };
                    @memset(sources[final_start..][0..placement.len], source_kind);
                    if (source_kind == .active) {
                        for (old_used[source_start..][0..placement.len]) |is_used| if (is_used) return error.ResourceLimit;
                        @memset(old_used[source_start..][0..placement.len], true);
                    }
                }
                var final_cursor: usize = 0;
                for (engine.active_stream.render_nodes.items, 0..) |node, old_index| {
                    if (old_used[old_index]) continue;
                    const scope_id = renderNodeScopeId(&engine.active_stream, node);
                    if (scope_id >= target_scopes.len) return error.ResourceLimit;
                    if (target_scopes[@intCast(scope_id)]) continue;
                    while (final_cursor < filled.len and filled[final_cursor]) final_cursor += 1;
                    if (final_cursor == filled.len) return error.ResourceLimit;
                    prepared.render_nodes.items[final_cursor] = node;
                    filled[final_cursor] = true;
                    sources[final_cursor] = .active;
                }
                for (filled) |is_filled| if (!is_filled) return error.ResourceLimit;
                prepared.metadata.ensureTotalCapacity(allocator, @intCast(std.math.mul(usize, final_len, 2) catch return error.ResourceLimit)) catch return error.OutOfMemory;
                for (prepared.render_nodes.items, sources, 0..) |node, source_kind, render_index| {
                    const source = switch (source_kind) {
                        .active => &engine.active_stream,
                        .replacement => &replacement.stream,
                    };
                    _ = renderNodeScopeId(source, node);
                    const parent_elem_id = renderNodeParentElemId(source, node);
                    const node_entry = prepared.metadata.getOrPutAssumeCapacity(node.elem_id.raw());
                    if (node_entry.found_existing and node_entry.value_ptr.render_node != null) return error.ResourceLimit;
                    node_entry.value_ptr.* = .{ .render_node = render_index };
                    if (node.elem_id.raw() != 0) {
                        const parent_entry = prepared.metadata.getOrPutAssumeCapacity(parent_elem_id);
                        if (!parent_entry.found_existing) parent_entry.value_ptr.* = .{};
                        if (parent_entry.value_ptr.last_child) |previous_id| {
                            const previous = prepared.metadata.getPtr(previous_id.raw()) orelse return error.InvalidRenderTopology;
                            previous.next_sibling = node.elem_id;
                            node_entry.value_ptr.previous_sibling = previous_id;
                        } else parent_entry.value_ptr.first_child = node.elem_id;
                        parent_entry.value_ptr.last_child = node.elem_id;
                    }
                }
                return prepared;
            }

            fn apply(self: *@This(), stream: *HostNodeDescriptorStream) void {
                std.mem.swap(shared_buffer.List(HostRenderNode), &self.render_nodes, &stream.render_nodes);
                std.mem.swap(std.AutoHashMapUnmanaged(u64, HostRenderElemIndex), &self.metadata, &stream.render_metadata_by_elem_id);
                stream.render_nodes_ordered = true;
            }

            fn deinit(self: *@This()) void {
                self.render_nodes.deinit(self.allocator);
                self.metadata.deinit(self.allocator);
                self.* = undefined;
            }
        };

        /// Reserves the retirement journal for exactly the descriptors a
        /// prepared removal displaces. The journal owns retired payloads
        /// from the allocation-free commit until the plan is torn down, so
        /// this preflight is sized by the removal alone: it never consults
        /// the live stream's token count or the highest retired id.
        fn prepareRetiredStreamCapacity(allocator: std.mem.Allocator, retired: *HostRetiredDescriptors, removal: *const structural_splice.PreparedRemoval) CollectionError!void {
            const indexes = &removal.descriptor_indexes;
            const nodes = &removal.node_indexes;
            try retired.reserve(allocator, .{
                .render_nodes = removal.scan.removed_elem_ids.len,
                .elements = indexes.element_indexes.items.len,
                .text_nodes = indexes.text_node_indexes.items.len,
                .static_text_attrs = indexes.static_text_attr_indexes.items.len,
                .static_bool_attrs = indexes.static_bool_attr_indexes.items.len,
                .signal_text_nodes = indexes.signal_text_node_indexes.items.len,
                .signal_text_attrs = indexes.signal_text_attr_indexes.items.len,
                .signal_bool_attrs = indexes.signal_bool_attr_indexes.items.len,
                .events = indexes.event_indexes.items.len,
                .static_custom_text_attrs = indexes.static_custom_text_attr_indexes.items.len,
                .signal_custom_text_attrs = indexes.signal_custom_text_attr_indexes.items.len,
                .signal_optional_custom_text_attrs = indexes.signal_optional_custom_text_attr_indexes.items.len,
                .static_custom_bool_attrs = indexes.static_custom_bool_attr_indexes.items.len,
                .signal_custom_bool_attrs = indexes.signal_custom_bool_attr_indexes.items.len,
                .scope_sites = nodes.scope_site_indexes.items.len,
                .states = nodes.state_indexes.items.len,
                .whens = nodes.when_indexes.items.len,
                .eaches = nodes.each_indexes.items.len,
                .on_changes = nodes.on_change_indexes.items.len,
                .mounts = nodes.mount_indexes.items.len,
                .cleanups = nodes.cleanup_indexes.items.len,
            });
        }

        fn collectRetiredGraphRootsForRemoval(engine: *Self, allocator: std.mem.Allocator, removal: *const structural_splice.PreparedRemoval, roots: *shared_buffer.List(*HostSignalRecord)) CollectionError!void {
            const indexes = &removal.descriptor_indexes;
            for (indexes.event_indexes.items) |index| if (engine.active_stream.events.items[index].handler.signalRoot()) |root| {
                roots.append(allocator, root) catch return error.OutOfMemory;
            };
            for (indexes.signal_text_node_indexes.items) |index| roots.append(allocator, engine.active_stream.signal_text_nodes.items[index].signal.record) catch return error.OutOfMemory;
            for (indexes.signal_text_attr_indexes.items) |index| roots.append(allocator, engine.active_stream.signal_text_attrs.items[index].signal.record) catch return error.OutOfMemory;
            for (indexes.signal_custom_text_attr_indexes.items) |index| roots.append(allocator, engine.active_stream.signal_custom_text_attrs.items[index].signal.record) catch return error.OutOfMemory;
            for (indexes.signal_optional_custom_text_attr_indexes.items) |index| roots.append(allocator, engine.active_stream.signal_optional_custom_text_attrs.items[index].signal.record) catch return error.OutOfMemory;
            for (indexes.signal_bool_attr_indexes.items) |index| roots.append(allocator, engine.active_stream.signal_bool_attrs.items[index].signal.record) catch return error.OutOfMemory;
            for (indexes.signal_custom_bool_attr_indexes.items) |index| roots.append(allocator, engine.active_stream.signal_custom_bool_attrs.items[index].signal.record) catch return error.OutOfMemory;
            for (removal.node_indexes.on_change_indexes.items) |index| roots.append(allocator, engine.active_stream.on_changes.items[index].signal.record) catch return error.OutOfMemory;
            for (removal.node_indexes.when_indexes.items) |index| roots.append(allocator, engine.active_stream.whens.items[index].condition.record) catch return error.OutOfMemory;
            for (removal.node_indexes.each_indexes.items) |index| roots.append(allocator, engine.active_stream.eaches.items[index].items.record) catch return error.OutOfMemory;
        }

        fn collectReplacementGraphRootsForStream(allocator: std.mem.Allocator, stream: *HostNodeDescriptorStream, roots: *shared_buffer.List(*HostSignalRecord)) CollectionError!void {
            for (stream.events.items) |desc| if (desc.handler.signalRoot()) |root| {
                roots.append(allocator, root) catch return error.OutOfMemory;
            };
            for (stream.signal_text_nodes.items) |*desc| roots.append(allocator, desc.signal.record) catch return error.OutOfMemory;
            for (stream.signal_text_attrs.items) |*desc| roots.append(allocator, desc.signal.record) catch return error.OutOfMemory;
            for (stream.signal_custom_text_attrs.items) |*desc| roots.append(allocator, desc.signal.record) catch return error.OutOfMemory;
            for (stream.signal_optional_custom_text_attrs.items) |*desc| roots.append(allocator, desc.signal.record) catch return error.OutOfMemory;
            for (stream.signal_bool_attrs.items) |*desc| roots.append(allocator, desc.signal.record) catch return error.OutOfMemory;
            for (stream.signal_custom_bool_attrs.items) |*desc| roots.append(allocator, desc.signal.record) catch return error.OutOfMemory;
            for (stream.on_changes.items) |*desc| roots.append(allocator, desc.signal.record) catch return error.OutOfMemory;
            for (stream.whens.items) |*desc| roots.append(allocator, desc.condition.record) catch return error.OutOfMemory;
            for (stream.eaches.items) |*desc| roots.append(allocator, desc.items.record) catch return error.OutOfMemory;
        }

        const PreparedStructuralTargets = struct {
            const Work = struct {
                subtree_scope_visits: usize = 0,
                subtree_child_links_followed: usize = 0,
            };

            descriptor_target_scopes: []bool = &.{},
            scope_retirement: ?scope_runtime.PreparedSubtreeRetirement = null,
            work: Work = .{},

            fn markSubtree(engine: *Self, targets: []bool, root: ids.ScopeId, value: bool, work: *Work) CollectionError!void {
                if (root.index() >= engine.scopes.items.len) return error.InvalidScope;
                const scope = engine.scopes.items[root.index()];
                if (scope.scope_id != root) return error.InvalidScope;
                if (!scope.lifecycle.isActive()) return;
                work.subtree_scope_visits += 1;
                targets[root.index()] = value;
                var child = scope.first_child_scope_id;
                while (child) |child_id| {
                    work.subtree_child_links_followed += 1;
                    try markSubtree(engine, targets, child_id, value, work);
                    child = engine.scopes.items[child_id.index()].next_sibling_scope_id;
                }
            }

            /// Whether `scope_id` is a committed row some live site under a
            /// descriptor root keeps, untouched or re-collected in place.
            fn keptByNestedSync(nested_syncs: []const PreparedNestedRowSync, scope_id: u64) bool {
                for (nested_syncs) |*sync| if (sync.keepsRow(scope_id)) return true;
                return false;
            }

            /// Derives the descriptor targets and the retired subtrees of one
            /// structural transaction.
            ///
            /// `descriptor_root_scope_ids` are the scopes whose committed
            /// descriptors the transaction replaces: retired subtrees and rows
            /// re-collected in place. Every scope under one is a target, except
            /// the subtree of an untouched survivor a live nested site keeps
            /// (`nested_syncs`), whose descriptors and render nodes stay.
            ///
            /// `retired_root_scope_ids` are the subtrees the transaction's own
            /// row syncs and branch selections retire. A row re-collected in
            /// place retires more than that: its nested rows are re-created
            /// under fresh scopes unless a live nested site reconciles them, so
            /// every committed each-row scope whose nearest enclosing row or
            /// descriptor root is a non-retired descriptor root - the
            /// re-collected row itself, or one of its re-collected nested rows -
            /// retires too, unless that nested site keeps it.
            fn prepare(engine: *Self, allocator: std.mem.Allocator, descriptor_root_scope_ids: []const u64, retired_root_scope_ids: []const u64, collection: ?*const StagedCollectionCtx) CollectionError!@This() {
                const nested_syncs: []const PreparedNestedRowSync = if (collection) |staged| staged.nested_row_syncs.items else &.{};
                var prepared: @This() = .{};
                errdefer prepared.deinit(allocator);
                prepared.descriptor_target_scopes = allocator.alloc(bool, engine.scopes.items.len) catch return error.OutOfMemory;
                @memset(prepared.descriptor_target_scopes, false);
                const is_descriptor_root = allocator.alloc(bool, engine.scopes.items.len) catch return error.OutOfMemory;
                defer allocator.free(is_descriptor_root);
                @memset(is_descriptor_root, false);
                const is_retired_root = allocator.alloc(bool, engine.scopes.items.len) catch return error.OutOfMemory;
                defer allocator.free(is_retired_root);
                @memset(is_retired_root, false);
                for (descriptor_root_scope_ids) |root_scope_id| {
                    if (root_scope_id >= engine.scopes.items.len) return error.InvalidScope;
                    if (!engine.scopes.items[@intCast(root_scope_id)].lifecycle.isActive()) return error.InvalidScope;
                    is_descriptor_root[@intCast(root_scope_id)] = true;
                    try markSubtree(engine, prepared.descriptor_target_scopes, ids.ScopeId.fromRaw(root_scope_id), true, &prepared.work);
                }
                for (retired_root_scope_ids) |root_scope_id| {
                    if (root_scope_id >= engine.scopes.items.len) return error.InvalidScope;
                    if (!engine.scopes.items[@intCast(root_scope_id)].lifecycle.isActive()) return error.InvalidScope;
                    is_retired_root[@intCast(root_scope_id)] = true;
                }
                // A live nested site only concerns this transaction when its
                // parent row is re-collected here; the rows it keeps leave
                // the targets, and the survivors it re-collects join the
                // descriptor roots exactly as their parent did.
                for (nested_syncs) |*sync| {
                    if (sync.parent_scope_id.index() >= prepared.descriptor_target_scopes.len) return error.InvalidScope;
                    if (!prepared.descriptor_target_scopes[sync.parent_scope_id.index()]) continue;
                    for (sync.rows.next_scope_ids, sync.rows.scope_created, sync.recollected) |row_scope_id, created, recollected| {
                        if (created) continue;
                        if (row_scope_id.index() >= engine.scopes.items.len) return error.InvalidScope;
                        if (recollected) {
                            is_descriptor_root[row_scope_id.index()] = true;
                            continue;
                        }
                        try markSubtree(engine, prepared.descriptor_target_scopes, row_scope_id, false, &prepared.work);
                    }
                }

                // A committed branch or component scope the collection claimed
                // again under its re-collected parent is re-collected like the
                // parent: its descriptors are replaced under the same scope.
                for (engine.scopes.items) |scope| {
                    if (!scope.lifecycle.isActive()) continue;
                    if (scope.step != .when_branch and scope.step != .component) continue;
                    if (!prepared.descriptor_target_scopes[scope.scope_id.index()]) continue;
                    const staged = collection orelse continue;
                    if (staged.scopes.reserved_ids.contains(scope.scope_id)) is_descriptor_root[scope.scope_id.index()] = true;
                }

                var retired_roots: shared_buffer.List(ids.ScopeId) = .empty;
                defer retired_roots.deinit(allocator);
                retired_roots.ensureTotalCapacity(allocator, retired_root_scope_ids.len) catch return error.OutOfMemory;
                for (retired_root_scope_ids) |scope_id| retired_roots.appendAssumeCapacity(ids.ScopeId.fromRaw(scope_id));
                // Every other committed row, branch, or component scope whose
                // nearest enclosing scope of those kinds is a re-collected
                // descriptor root is content that root no longer declares.
                for (engine.scopes.items) |scope| {
                    if (!scope.lifecycle.isActive() or scope.step == .root) continue;
                    if (!prepared.descriptor_target_scopes[scope.scope_id.index()]) continue;
                    if (is_retired_root[scope.scope_id.index()] or is_descriptor_root[scope.scope_id.index()]) continue;
                    if (keptByNestedSync(nested_syncs, scope.scope_id.raw())) continue;
                    var ancestor = scope.parent_scope_id;
                    const retires = while (ancestor) |id| {
                        if (is_descriptor_root[id.index()]) break !is_retired_root[id.index()];
                        if (engine.scopes.items[id.index()].step != .root) break false;
                        ancestor = engine.scopes.items[id.index()].parent_scope_id;
                    } else false;
                    if (retires) retired_roots.append(allocator, scope.scope_id) catch return error.OutOfMemory;
                }
                prepared.scope_retirement = scope_runtime.prepareSubtreesRetirement(HostEachRowScopeStep, allocator, engine.scopes.items, retired_roots.items) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.OverlappingSubtrees => return error.OverlappingRemoval,
                };
                for (prepared.scope_retirement.?.scope_ids) |scope_id| {
                    if (scope_id.index() >= prepared.descriptor_target_scopes.len or !prepared.descriptor_target_scopes[scope_id.index()]) return error.InvalidScope;
                }
                return prepared;
            }

            fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
                if (self.scope_retirement) |*retirement| retirement.deinit(allocator);
                allocator.free(self.descriptor_target_scopes);
                self.* = .{};
            }
        };

        fn positionError(err: structural_positions.Error) CollectionError {
            return switch (err) {
                error.OutOfMemory => error.OutOfMemory,
                error.ResourceLimit => error.ResourceLimit,
                else => error.InvalidRenderTopology,
            };
        }

        const PreparedReplacementOwner = struct {
            engine: *Self,
            host_ctx: Ctx.Handle,
            roc_host: *abi.RocHost,
            stream: HostNodeDescriptorStream = .{},
            collection: StagedCollectionCtx = undefined,
            positions: ?structural_positions.Prepared = null,
            construction_ranges: std.AutoHashMapUnmanaged(ids.ScopeId, ConstructionRange) = .empty,

            const ConstructionRange = struct { start: usize, len: usize };

            fn addRootCounts(total: *StaticRootCounts, next: StaticRootCounts) CollectionError!void {
                inline for (std.meta.fields(StaticRootCounts)) |field| {
                    @field(total, field.name) = std.math.add(usize, @field(total, field.name), @field(next, field.name)) catch return error.ResourceLimit;
                }
            }

            fn countRoots(elems: []const abi.Elem) CollectionError!StaticRootCounts {
                var total: StaticRootCounts = .{};
                for (elems) |elem| try addRootCounts(&total, try countStaticRootNodes(elem));
                return total;
            }

            fn create(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, limits: collection_budget.Limits, counts: StaticRootCounts, expected_roots: usize) CollectionError!*@This() {
                const allocator = Ctx.allocator(ctx);
                const owner = allocator.create(@This()) catch return error.OutOfMemory;
                errdefer allocator.destroy(owner);
                owner.* = .{ .engine = engine, .host_ctx = ctx, .roc_host = roc_host };
                errdefer owner.stream.deinit(allocator, ctx, roc_host, &engine.pending_roc_metrics);
                owner.collection = try StagedCollectionCtx.init(engine, ctx, &owner.stream, limits, counts, expected_roots);
                return owner;
            }

            fn preparePositions(self: *@This()) *structural_positions.Prepared {
                if (self.positions == null) {
                    if (self.engine.positions == null) self.engine.positions = structural_positions.Positions.init(Ctx.allocator(self.host_ctx));
                    self.positions = self.engine.positions.?.prepare();
                }
                return &self.positions.?;
            }

            fn rememberConstructionRange(self: *@This(), scope: ids.ScopeId, start: usize) CollectionError!void {
                self.construction_ranges.put(Ctx.allocator(self.host_ctx), scope, .{ .start = start, .len = self.collection.construction_order.items.len - start }) catch return error.OutOfMemory;
            }

            fn placeConstructionRange(self: *@This(), scope: ids.ScopeId, parent: ids.ElemId, before: ?structural_positions.PositionId) CollectionError!void {
                const range = self.construction_ranges.get(scope) orelse return error.InvalidDescriptor;
                const positions = self.preparePositions();
                for (self.collection.construction_order.items[range.start..][0..range.len]) |entry| {
                    positions.place(entry, if (entry.parent == parent) before else null) catch |err| return positionError(err);
                }
            }

            fn commitPositions(self: *@This()) void {
                if (self.positions) |*positions| positions.commit();
            }

            fn attachExternalScopeIds(self: *@This(), scope_ids: []const u64) CollectionError!void {
                try self.collection.attachExternalScopeIds(scope_ids);
            }

            const CollectedWhenSelection = struct {
                scope_id: u64,
                start: usize,
                len: usize,
                site_start: usize,
                site_len: usize,
            };

            fn collectWhenSelectionRange(self: *@This(), selection: AggregateBranchSelection, dirty_source_node_ids: []const u64) CollectionError!CollectedWhenSelection {
                try self.collection.validateScope(selection.parent_scope_id);
                const branch_scope = try self.collection.reserveWhenBranchScope(selection.parent_scope_id, selection.site_ordinal, selection.branch);
                if (!branch_scope.created) return error.ResourceLimit;
                const allocator = Ctx.allocator(self.host_ctx);
                var binder_stack: shared_buffer.List(HostBinderBinding) = .empty;
                defer binder_stack.deinit(allocator);
                const counts = try countStaticRootNodes(selection.elem);
                const binder_capacity = std.math.add(usize, selection.binder_bindings.len, counts.state_sites) catch return error.ResourceLimit;
                binder_stack.ensureTotalCapacity(allocator, binder_capacity) catch return error.OutOfMemory;
                binder_stack.appendSliceAssumeCapacity(selection.binder_bindings);
                var ordinal = ids.SiteOrdinal.fromRaw(0);
                var dom_ordinal = ids.SiteOrdinal.fromRaw(0);
                const render_start = self.collection.prepared_render_order.items.len;
                const site_start = self.collection.prepared_state_sites.items.len;
                const construction_start = self.collection.construction_order.items.len;
                try self.engine.collectActiveElemDescriptorsWith(*StagedCollectionCtx, &self.collection, self.host_ctx, self.roc_host, &self.stream, selection.elem, branch_scope.scope_id, selection.parent_elem_id, &ordinal, &dom_ordinal, &binder_stack, true, dirty_source_node_ids);
                try self.rememberConstructionRange(branch_scope.scope_id, construction_start);
                return .{
                    .scope_id = branch_scope.scope_id.raw(),
                    .start = render_start,
                    .len = self.collection.prepared_render_order.items.len - render_start,
                    .site_start = site_start,
                    .site_len = self.collection.prepared_state_sites.items.len - site_start,
                };
            }

            fn collectWhenSelection(self: *@This(), selection: AggregateBranchSelection, dirty_source_node_ids: []const u64) CollectionError!u64 {
                return (try self.collectWhenSelectionRange(selection, dirty_source_node_ids)).scope_id;
            }

            fn collectEachRow(self: *@This(), site: HostNodeScopeSiteDesc, each: HostNodeEachDesc, elem: abi.Elem, row_scope_id: ids.ScopeId, scope_created: bool, dirty_source_node_ids: []const u64) CollectionError!struct { start: usize, len: usize, site_start: usize, site_len: usize } {
                const allocator = Ctx.allocator(self.host_ctx);
                var binder_stack: shared_buffer.List(HostBinderBinding) = .empty;
                defer binder_stack.deinit(allocator);
                const counts = try countStaticRootNodes(elem);
                const binder_capacity = std.math.add(usize, site.binder_bindings.len, counts.state_sites) catch return error.ResourceLimit;
                binder_stack.ensureTotalCapacity(allocator, binder_capacity) catch return error.OutOfMemory;
                binder_stack.appendSliceAssumeCapacity(site.binder_bindings);
                var ordinal = ids.SiteOrdinal.fromRaw(0);
                var dom_ordinal = ids.SiteOrdinal.fromRaw(0);
                const render_start = self.collection.prepared_render_order.items.len;
                const site_start = self.collection.prepared_state_sites.items.len;
                const construction_start = self.collection.construction_order.items.len;
                try self.engine.collectActiveEachRowElemDescriptorsWith(*StagedCollectionCtx, &self.collection, self.host_ctx, self.roc_host, &self.stream, each, elem, row_scope_id, site.parent_elem_id, &ordinal, &dom_ordinal, &binder_stack, scope_created, dirty_source_node_ids);
                try self.rememberConstructionRange(row_scope_id, construction_start);
                return .{ .start = render_start, .len = self.collection.prepared_render_order.items.len - render_start, .site_start = site_start, .site_len = self.collection.prepared_state_sites.items.len - site_start };
            }

            fn materialize(self: *@This()) void {
                self.collection.materializeStream();
            }

            fn deinit(self: *@This()) void {
                const allocator = Ctx.allocator(self.host_ctx);
                if (self.positions) |*positions| positions.deinit();
                self.construction_ranges.deinit(allocator);
                self.collection.deinit();
                self.stream.deinit(allocator, self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics);
                allocator.destroy(self);
            }
        };

        /// Owns a completely collected root generation until its persistent
        /// scope, identity, state, signal, and descriptor ownership can be
        /// committed together. Preparation may allocate and invoke pure Roc
        /// readers, but it never changes the engine's logical committed state.
        /// Dropping an uncommitted plan releases every provisional value and
        /// makes the same engine safe to retry.
        pub const PreparedRootCollection = struct {
            owner: *PreparedReplacementOwner,

            /// Collects and materializes one root into plan-owned storage.
            /// Host allocation failure is recoverable; allocation failure in a
            /// Roc callback remains the platform allocator's fatal boundary.
            pub fn prepare(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, root: abi.Elem, limits: collection_budget.Limits, dirty_source_node_ids: []const u64) CollectionError!*@This() {
                const allocator = Ctx.allocator(ctx);
                const plan = allocator.create(@This()) catch return error.OutOfMemory;
                errdefer allocator.destroy(plan);
                const counts = try countStaticRootNodes(root);
                const owner = try PreparedReplacementOwner.create(engine, ctx, roc_host, limits, counts, 1);
                errdefer owner.deinit();
                try engine.collectActiveElemRootDescriptorsWith(*StagedCollectionCtx, &owner.collection, ctx, roc_host, &owner.stream, root, dirty_source_node_ids);
                owner.materialize();
                const positions = owner.preparePositions();
                for (owner.collection.construction_order.items) |entry| positions.place(entry, null) catch |err| return positionError(err);
                positions.preflight() catch |err| return positionError(err);
                plan.* = .{ .owner = owner };
                return plan;
            }

            /// Returns the fully materialized but unpublished descriptor stream.
            pub fn descriptorStream(self: *const @This()) *const HostNodeDescriptorStream {
                return &self.owner.stream;
            }

            /// Publishes the pre-reserved engine ownership and transfers the
            /// descriptor stream to the caller without allocating. Render and
            /// host publication must already have been prepared before this
            /// irreversible step is used by a complete root transaction.
            pub fn commit(self: *@This()) HostNodeDescriptorStream {
                self.owner.collection.commit();
                self.owner.commitPositions();
                const stream = self.owner.stream;
                self.owner.stream = .{};
                const allocator = Ctx.allocator(self.owner.host_ctx);
                self.owner.deinit();
                allocator.destroy(self);
                return stream;
            }

            /// Aborts the plan and releases all provisional ownership.
            pub fn deinit(self: *@This()) void {
                const allocator = Ctx.allocator(self.owner.host_ctx);
                self.owner.deinit();
                allocator.destroy(self);
            }
        };

        /// The render layout of one staged structural transaction: described
        /// by the staging path in old coordinates, resolved here into final
        /// ones, and applied to every scope site's insertion index at commit.
        ///
        /// Coordinates: everything a path *describes* is an index into the
        /// committed active render stream (`active_stream.render_nodes`) or, for
        /// collected content, into the replacement stream. Everything the plan
        /// *derives* - a region's `final_start`, every placement, every resolved
        /// site index - is an index into the final render stream this
        /// transaction publishes.
        ///
        /// A path describes one **region** per edited site: the old span the
        /// site's content occupied and, in final order, the **pieces** that
        /// replace it - a surviving row copied from the active stream or a
        /// collected row or branch copied from the replacement stream. A
        /// region may nest inside a surviving piece of another region (a when
        /// inside a surviving row of an edited each); nesting is decided by
        /// scope ancestry, never by positions.
        ///
        /// `resolve` walks the old stream once in document order
        /// (`compareSitePositions`), keeping a single final cursor: retained
        /// nodes between regions keep their relative order, a region lands on
        /// the cursor and lays its pieces out from there, and a surviving piece
        /// is walked recursively so regions nested in it split it into moved
        /// fragments. That one walk yields every region's final start, the
        /// `PreparedFinalRenderTopology.Placement` list, and the surviving rows and
        /// replacement ranges site resolution needs. Old spans must agree with
        /// the document order - overlapping or out-of-order regions, or a
        /// region inside removed content - are refused as
        /// `InvalidRenderTopology`.
        ///
        /// `finish` resolves each active site once. An edited site lands on its
        /// region's final start. A site living inside a surviving row follows
        /// the row's fragment. Otherwise the index is shifted by the net size
        /// change of every region that stands before the site in document
        /// order; a region inside the site's own content leaves it alone. The
        /// replacement stream's own sites are translated through the range of
        /// the row or branch that collected them. `apply` then publishes the
        /// resolved indexes without allocating.
        const PreparedRenderLayoutPlan = struct {
            const unmapped = std.math.maxInt(usize);
            const Piece = union(enum) {
                /// A surviving row: its scope and old span.
                survivor: struct { scope_id: u64, old_start: usize, len: usize },
                /// A collected row or branch: its render span in the
                /// replacement stream and the scope sites it created.
                replacement: struct { render_start: usize, render_len: usize, site_start: usize, site_len: usize },
            };
            /// Where a region collected inside a row's replacement sits in
            /// the replacement stream: the render span its own collected rows
            /// occupy, the scope sites they created, and the index of the
            /// region's site descriptor, which closes that site span.
            const LocalSpan = struct {
                render_start: usize,
                render_len: usize,
                site_start: usize,
                site_len: usize,
                site_index: usize,
            };
            const Region = struct {
                node_id: u64,
                kind: HostNodeScopeSiteKind,
                owner: SitePosition,
                old_start: usize,
                old_end: usize,
                pieces: []Piece,
                /// Present for a region nested in a collected row: a live
                /// each site the row brought back and reconciled by key.
                local: ?LocalSpan = null,
                /// The region whose piece carries this one, set as the
                /// layout consumes it. A carried region's size change is
                /// part of its parent's.
                parent: ?usize = null,
                final_start: usize = unmapped,
                new_len: usize = 0,
            };
            /// A surviving row and where it landed, so a site living inside
            /// it can be resolved from the row's final start.
            const SurvivingRow = struct {
                scope_id: u64,
                old_start: usize,
                old_end: usize,
                final_start: usize,
            };
            const ReplacementRange = struct {
                site_start: usize,
                site_len: usize,
                render_start: usize,
                render_len: usize,
                final_start: usize,
            };
            const Phase = enum { describing, resolved, finished };

            allocator: std.mem.Allocator,
            regions: shared_buffer.List(Region) = .empty,
            rows: shared_buffer.List(SurvivingRow) = .empty,
            ranges: shared_buffer.List(ReplacementRange) = .empty,
            placements: shared_buffer.List(PreparedFinalRenderTopology.Placement) = .empty,
            /// Per region: laid out already, either at the top level or as a
            /// region nested in a surviving row.
            consumed: []bool = &.{},
            removed_render_count: usize = 0,
            active_new: []usize = &.{},
            replacement_new: []usize = &.{},
            phase: Phase = .describing,

            fn init(allocator: std.mem.Allocator) @This() {
                return .{ .allocator = allocator };
            }

            /// Describes an edited each site from its layout: the old span its
            /// rows occupy and its rows in their next order.
            fn describeEachSite(self: *@This(), layout: *const PreparedEachRowRenderLayout) CollectionError!void {
                if (self.phase != .describing) return error.ResourceLimit;
                const pieces = self.allocator.dupe(Piece, layout.pieces) catch return error.OutOfMemory;
                errdefer self.allocator.free(pieces);
                const site = layout.site;
                self.regions.append(self.allocator, .{ .node_id = site.node_id.raw(), .kind = .each, .owner = SitePosition.ofSite(site), .old_start = site.render_insert_index, .old_end = layout.old_end, .pieces = pieces }) catch return error.OutOfMemory;
            }

            /// Describes a when branch selection: the retired branch's old
            /// span, found from the render nodes its scope owns, replaced by
            /// the collected branch. A retired branch that renders nothing
            /// sits at the site's index. Returns the old start, which is also
            /// where the retirement scan for this branch begins.
            fn describeBranch(self: *@This(), engine: *Self, selection: AggregateBranchSelection, collected: PreparedReplacementOwner.CollectedWhenSelection) CollectionError!usize {
                if (self.phase != .describing) return error.ResourceLimit;
                if (!engine.active_stream.render_nodes_ordered) return error.ResourceLimit;
                var old_start: ?usize = null;
                var old_end: usize = 0;
                for (engine.active_stream.render_nodes.items, 0..) |node, render_index| {
                    const scope_id = renderNodeScopeId(&engine.active_stream, node);
                    const retired = engine.scopeIsDescendantOrSelf(scope_id, selection.retired_scope_id.raw()) catch |err| return scopeError(err);
                    if (!retired) continue;
                    if (old_start == null) {
                        old_start = render_index;
                    } else if (render_index != old_end) return error.InvalidRenderTopology;
                    old_end = render_index + 1;
                }
                const start = old_start orelse blk: {
                    old_end = selection.render_insert_index;
                    break :blk selection.render_insert_index;
                };
                const pieces = self.allocator.alloc(Piece, 1) catch return error.OutOfMemory;
                errdefer self.allocator.free(pieces);
                pieces[0] = .{ .replacement = .{ .render_start = collected.start, .render_len = collected.len, .site_start = collected.site_start, .site_len = collected.site_len } };
                self.regions.append(self.allocator, .{ .node_id = selection.node_id.raw(), .kind = .when, .owner = .{ .scope_id = selection.parent_scope_id.raw(), .ordinal = selection.site_ordinal }, .old_start = start, .old_end = old_end, .pieces = pieces }) catch return error.OutOfMemory;
                return start;
            }

            /// Describes every live each site a re-collected row brought back:
            /// its committed rows' old span and its rows in their next order,
            /// laid out inside the row's replacement where the site's
            /// descriptor was collected.
            fn describeNestedSites(self: *@This(), nested_syncs: []const PreparedNestedRowSync) CollectionError!void {
                if (self.phase != .describing) return error.ResourceLimit;
                for (nested_syncs) |*sync| {
                    const pieces = self.allocator.dupe(Piece, sync.pieces) catch return error.OutOfMemory;
                    errdefer self.allocator.free(pieces);
                    self.regions.append(self.allocator, .{
                        .node_id = sync.node_id.raw(),
                        .kind = .each,
                        .owner = .{ .scope_id = sync.parent_scope_id.raw(), .ordinal = sync.site_ordinal },
                        .old_start = sync.old_start,
                        .old_end = sync.old_end,
                        .pieces = pieces,
                        .local = .{
                            .render_start = sync.local_render_start,
                            .render_len = sync.local_render_len,
                            .site_start = sync.local_site_start,
                            .site_len = sync.local_site_len,
                            .site_index = sync.local_site_index,
                        },
                    }) catch return error.OutOfMemory;
                }
            }

            fn regionsInDocumentOrder(self: *@This(), engine: *Self) CollectionError!void {
                const regions = self.regions.items;
                // Insertion sort: region counts are small and the comparator
                // can fail, which `std.mem.sort` cannot report.
                var index: usize = 1;
                while (index < regions.len) : (index += 1) {
                    var position = index;
                    while (position > 0) : (position -= 1) {
                        switch (try engine.compareSitePositions(regions[position - 1].owner, regions[position].owner)) {
                            .before, .contains => break,
                            .after, .contained => std.mem.swap(Region, &regions[position - 1], &regions[position]),
                            .same => return error.InvalidRenderTopology,
                        }
                    }
                }
            }

            fn requireRetained(engine: *Self, target_scopes: []const bool, old_start: usize, old_end: usize) CollectionError!void {
                for (engine.active_stream.render_nodes.items[old_start..old_end]) |node| {
                    const scope_id = renderNodeScopeId(&engine.active_stream, node);
                    if (scope_id >= target_scopes.len) return error.InvalidRenderTopology;
                    if (target_scopes[@intCast(scope_id)]) return error.InvalidRenderTopology;
                }
            }

            fn placeSurvivorFragment(self: *@This(), engine: *Self, target_scopes: []const bool, old_start: usize, old_end: usize, final_start: usize) CollectionError!usize {
                const len = old_end - old_start;
                if (len == 0) return final_start;
                try requireRetained(engine, target_scopes, old_start, old_end);
                self.placements.append(self.allocator, PreparedFinalRenderTopology.Placement.active(.{ .value = old_start }, .{ .value = final_start }, len)) catch return error.OutOfMemory;
                return std.math.add(usize, final_start, len) catch return error.ResourceLimit;
            }

            /// The next live nested site a collected row's replacement
            /// carries: the outermost region, not yet laid out, whose site
            /// descriptor lies inside `range`'s scope-site span. Regions
            /// nest - a site collected inside a re-collected nested row sits
            /// within that row's site's span, and its descriptor precedes the
            /// enclosing site's, which closes its own span - so the earliest
            /// span start wins and, between spans starting together, the
            /// longer one: the inner region is laid out by the replacement
            /// of the row that collected it.
            fn nextNestedSiteIn(self: *const @This(), range: anytype) ?usize {
                var found: ?usize = null;
                var found_start: usize = 0;
                var found_len: usize = 0;
                for (self.regions.items, 0..) |region, index| {
                    if (self.consumed[index]) continue;
                    const local = region.local orelse continue;
                    if (local.site_index < range.site_start or local.site_index - range.site_start >= range.site_len) continue;
                    if (found == null or local.site_start < found_start or (local.site_start == found_start and local.site_len > found_len)) {
                        found = index;
                        found_start = local.site_start;
                        found_len = local.site_len;
                    }
                }
                return found;
            }

            /// Lays a surviving row out at `final_start`. The regions nested
            /// in it are found by scope, not by walking on from the last
            /// region laid out: survivors are placed in their *next* order,
            /// and two reordered rows that both hold a flipping region would
            /// otherwise each be handed the other's. Within one row the
            /// regions still come in document order, which is old-span order.
            /// Returns the final cursor after the row.
            fn layoutSurvivor(self: *@This(), engine: *Self, target_scopes: []const bool, region_index: usize, scope_id: u64, old_start: usize, old_end: usize, final_start: usize) CollectionError!usize {
                self.rows.append(self.allocator, .{ .scope_id = scope_id, .old_start = old_start, .old_end = old_end, .final_start = final_start }) catch return error.OutOfMemory;
                var old = old_start;
                var final = final_start;
                for (self.regions.items, 0..) |nested, nested_index| {
                    if (self.consumed[nested_index]) continue;
                    if (!(engine.scopeIsDescendantOrSelf(nested.owner.scope_id, scope_id) catch |err| return scopeError(err))) continue;
                    // Nothing is collected under an untouched survivor, so no
                    // live nested site can be laid out inside it.
                    if (nested.local != null) return error.InvalidRenderTopology;
                    if (nested.old_start < old or nested.old_end > old_end) return error.InvalidRenderTopology;
                    final = try self.placeSurvivorFragment(engine, target_scopes, old, nested.old_start, final);
                    self.regions.items[nested_index].parent = region_index;
                    final = try self.layoutRegion(engine, target_scopes, nested_index, final);
                    old = nested.old_end;
                }
                return self.placeSurvivorFragment(engine, target_scopes, old, old_end, final);
            }

            fn placeReplacementFragment(self: *@This(), render_start: usize, render_len: usize, site_start: usize, site_len: usize, final_start: usize) CollectionError!usize {
                if (render_len == 0 and site_len == 0) return final_start;
                if (render_len != 0) self.placements.append(self.allocator, PreparedFinalRenderTopology.Placement.replacement(.{ .value = render_start }, .{ .value = final_start }, render_len)) catch return error.OutOfMemory;
                self.ranges.append(self.allocator, .{ .site_start = site_start, .site_len = site_len, .render_start = render_start, .render_len = render_len, .final_start = final_start }) catch return error.OutOfMemory;
                return std.math.add(usize, final_start, render_len) catch return error.ResourceLimit;
            }

            /// Lays a collected row or branch out at `final_start`: the live
            /// nested sites collected inside it (the regions whose site
            /// descriptor the piece created, next in document order) split
            /// it into fragments around the rows they keep. Returns the final
            /// cursor after the piece.
            fn layoutReplacement(self: *@This(), engine: *Self, target_scopes: []const bool, region_index: usize, range: anytype, final_start: usize) CollectionError!usize {
                const render_end = std.math.add(usize, range.render_start, range.render_len) catch return error.ResourceLimit;
                const site_end = std.math.add(usize, range.site_start, range.site_len) catch return error.ResourceLimit;
                var render_cursor = range.render_start;
                var site_cursor = range.site_start;
                var final = final_start;
                while (self.nextNestedSiteIn(range)) |nested_index| {
                    const local = self.regions.items[nested_index].local.?;
                    if (local.render_start < render_cursor or local.site_start < site_cursor) return error.InvalidRenderTopology;
                    const local_render_end = std.math.add(usize, local.render_start, local.render_len) catch return error.ResourceLimit;
                    const local_site_end = std.math.add(usize, local.site_start, local.site_len) catch return error.ResourceLimit;
                    if (local_render_end > render_end or local_site_end > site_end or local.site_index >= local_site_end) return error.InvalidRenderTopology;
                    final = try self.placeReplacementFragment(render_cursor, local.render_start - render_cursor, site_cursor, local.site_start - site_cursor, final);
                    self.regions.items[nested_index].parent = region_index;
                    final = try self.layoutRegion(engine, target_scopes, nested_index, final);
                    render_cursor = local_render_end;
                    site_cursor = local_site_end;
                }
                return self.placeReplacementFragment(render_cursor, render_end - render_cursor, site_cursor, site_end - site_cursor, final);
            }

            /// Lays a region out at `final_start` and returns the final cursor
            /// after it. The regions nested in it are consumed by its surviving
            /// pieces; any left over sits in content this transaction removes
            /// and should have been subsumed before staging.
            fn layoutRegion(self: *@This(), engine: *Self, target_scopes: []const bool, region_index: usize, final_start: usize) CollectionError!usize {
                if (self.consumed[region_index]) return error.InvalidRenderTopology;
                self.consumed[region_index] = true;
                var final = final_start;
                for (self.regions.items[region_index].pieces) |piece| switch (piece) {
                    .replacement => |range| {
                        final = try self.layoutReplacement(engine, target_scopes, region_index, range, final);
                    },
                    .survivor => |row| {
                        const row_end = std.math.add(usize, row.old_start, row.len) catch return error.ResourceLimit;
                        final = try self.layoutSurvivor(engine, target_scopes, region_index, row.scope_id, row.old_start, row_end, final);
                    },
                };
                const region = &self.regions.items[region_index];
                for (self.regions.items, self.consumed) |other, is_consumed| {
                    if (is_consumed) continue;
                    switch (try engine.compareSitePositions(region.owner, other.owner)) {
                        .contains => return error.InvalidRenderTopology,
                        else => {},
                    }
                }
                region.final_start = final_start;
                region.new_len = std.math.sub(usize, final, final_start) catch return error.ResourceLimit;
                return final;
            }

            /// Derives every final coordinate from the described regions. The
            /// retained nodes outside every region keep their order and are
            /// left for `PreparedFinalRenderTopology.preparePlaced` to fill in.
            fn resolve(self: *@This(), engine: *Self, target_scopes: []const bool) CollectionError!void {
                if (self.phase != .describing) return error.ResourceLimit;
                try self.regionsInDocumentOrder(engine);
                const old_nodes = engine.active_stream.render_nodes.items;
                var removed: usize = 0;
                for (old_nodes) |node| {
                    const scope_id = renderNodeScopeId(&engine.active_stream, node);
                    if (scope_id >= target_scopes.len) return error.InvalidRenderTopology;
                    if (target_scopes[@intCast(scope_id)]) removed += 1;
                }
                self.removed_render_count = removed;
                self.consumed = self.allocator.alloc(bool, self.regions.items.len) catch return error.OutOfMemory;
                @memset(self.consumed, false);
                var old: usize = 0;
                var final: usize = 0;
                for (self.regions.items, 0..) |region, region_index| {
                    if (self.consumed[region_index]) continue;
                    // A live nested site is laid out by the collected row
                    // that brought it back; one reaching the top level has
                    // no such row before it in document order.
                    if (region.local != null) return error.InvalidRenderTopology;
                    if (region.old_start < old or region.old_end < region.old_start or region.old_end > old_nodes.len) return error.InvalidRenderTopology;
                    try requireRetained(engine, target_scopes, old, region.old_start);
                    final = std.math.add(usize, final, region.old_start - old) catch return error.ResourceLimit;
                    final = try self.layoutRegion(engine, target_scopes, region_index, final);
                    old = region.old_end;
                }
                try requireRetained(engine, target_scopes, old, old_nodes.len);
                self.phase = .resolved;
            }

            /// Whether `region_index` shifts the sites `finish` resolves in
            /// the context `row`: outside any surviving row, every region
            /// whose size change is not already part of a carrying
            /// ancestor's; inside a surviving row, only the regions nested in
            /// that row, again net of an ancestor counted by the same rule.
            /// Regions carry regions to any depth, so every ancestor is
            /// asked, not only the nearest: a region three levels down is
            /// part of the top-level region's change even though the middle
            /// region, being carried, shifts nothing itself.
            fn regionShiftsSitesIn(self: *const @This(), engine: *Self, region_index: usize, row: ?SurvivingRow) CollectionError!bool {
                const region = self.regions.items[region_index];
                if (row) |surviving| {
                    if (!(engine.scopeIsDescendantOrSelf(region.owner.scope_id, surviving.scope_id) catch |err| return scopeError(err))) return false;
                }
                var ancestor = region.parent;
                while (ancestor) |parent| : (ancestor = self.regions.items[parent].parent) {
                    if (try self.regionShiftsSitesIn(engine, parent, row)) return false;
                }
                return true;
            }

            /// The innermost surviving row whose scope contains `scope_id`, if
            /// the site lives inside content a region keeps.
            fn innermostSurvivingRow(self: *const @This(), engine: *Self, scope_id: u64) CollectionError!?SurvivingRow {
                var found: ?SurvivingRow = null;
                var found_depth: usize = 0;
                for (self.rows.items) |row| {
                    if (!(engine.scopeIsDescendantOrSelf(scope_id, row.scope_id) catch |err| return scopeError(err))) continue;
                    const depth = engine.scopeDepth(row.scope_id);
                    if (found == null or depth > found_depth) {
                        found = row;
                        found_depth = depth;
                    }
                }
                return found;
            }

            fn finish(self: *@This(), engine: *Self, replacement_stream: *const HostNodeDescriptorStream, target_scopes: []const bool, final_len: usize) CollectionError!void {
                if (self.phase != .resolved) return error.ResourceLimit;
                const old_nodes = engine.active_stream.render_nodes.items;
                const active_sites = engine.active_stream.scope_sites.items;
                const active_new = self.allocator.alloc(usize, active_sites.len) catch return error.OutOfMemory;
                errdefer self.allocator.free(active_new);
                for (active_sites, active_new) |site, *new| {
                    new.* = unmapped;
                    if (site.scope_id.index() >= target_scopes.len) return error.InvalidRenderTopology;
                    if (target_scopes[site.scope_id.index()]) continue;
                    const old_index = site.render_insert_index;
                    if (old_index > old_nodes.len) return error.InvalidRenderTopology;
                    // An edited site's content starts where its region does.
                    const owned: ?usize = for (self.regions.items) |region| {
                        if (region.node_id == site.node_id.raw() and region.kind == site.kind) break region.final_start;
                    } else null;
                    if (owned) |final_start| {
                        new.* = final_start;
                        continue;
                    }
                    // A site inside a surviving row starts from where the row
                    // landed, at the same offset into it; any other site starts
                    // from its own index. Either way the regions that stand
                    // before the site in document order - and, inside a row,
                    // only those nested in that row - shift it by their net size
                    // change. A region inside the site's own content leaves it
                    // alone, and every region's old span has to agree with the
                    // order; a site whose index sits inside content the order
                    // puts elsewhere is stale and refused rather than shifted.
                    const position = SitePosition.ofSite(site);
                    const row = try self.innermostSurvivingRow(engine, site.scope_id.raw());
                    var shifted: isize = undefined;
                    if (row) |surviving| {
                        if (old_index < surviving.old_start or old_index > surviving.old_end) return error.InvalidRenderTopology;
                        shifted = std.math.cast(isize, surviving.final_start + (old_index - surviving.old_start)) orelse return error.ResourceLimit;
                    } else {
                        shifted = std.math.cast(isize, old_index) orelse return error.ResourceLimit;
                    }
                    for (self.regions.items, 0..) |region, region_index| {
                        if (!(try self.regionShiftsSitesIn(engine, region_index, row))) continue;
                        switch (try engine.compareSitePositions(region.owner, position)) {
                            .before => if (region.old_end > old_index) return error.InvalidRenderTopology,
                            .after => {
                                if (region.old_start < old_index) return error.InvalidRenderTopology;
                                continue;
                            },
                            .contained => continue,
                            .same, .contains => return error.InvalidRenderTopology,
                        }
                        const region_len = region.old_end - region.old_start;
                        shifted = std.math.add(isize, shifted, std.math.cast(isize, region.new_len) orelse return error.ResourceLimit) catch return error.ResourceLimit;
                        shifted = std.math.sub(isize, shifted, std.math.cast(isize, region_len) orelse return error.ResourceLimit) catch return error.ResourceLimit;
                    }
                    const final_index = std.math.cast(usize, shifted) orelse return error.InvalidRenderTopology;
                    if (final_index > final_len) return error.InvalidRenderTopology;
                    new.* = final_index;
                }
                const replacement_sites = replacement_stream.scope_sites.items;
                const replacement_new = self.allocator.alloc(usize, replacement_sites.len) catch return error.OutOfMemory;
                errdefer self.allocator.free(replacement_new);
                for (replacement_sites, replacement_new, 0..) |site, *new, site_index| {
                    // A live nested site's own descriptor starts where its
                    // region landed, like an edited active site does.
                    const owned: ?usize = for (self.regions.items) |region| {
                        const local = region.local orelse continue;
                        if (local.site_index == site_index) break region.final_start;
                    } else null;
                    if (owned) |final_start| {
                        if (final_start > final_len) return error.InvalidRenderTopology;
                        new.* = final_start;
                        continue;
                    }
                    const range = for (self.ranges.items) |range| {
                        if (site_index >= range.site_start and site_index - range.site_start < range.site_len) break range;
                    } else return error.InvalidRenderTopology;
                    const local = site.render_insert_index;
                    if (local < range.render_start or local > range.render_start + range.render_len) return error.InvalidRenderTopology;
                    const final_index = std.math.add(usize, range.final_start, local - range.render_start) catch return error.ResourceLimit;
                    if (final_index > final_len) return error.InvalidRenderTopology;
                    new.* = final_index;
                }
                self.active_new = active_new;
                self.replacement_new = replacement_new;
                self.phase = .finished;
            }

            /// Publishes the resolved indexes. Runs before the descriptor splice
            /// retires and appends scope sites, so both streams still have the
            /// exact site lists `finish` resolved against.
            fn apply(self: *const @This(), active_stream: *HostNodeDescriptorStream, replacement_stream: *HostNodeDescriptorStream) void {
                if (self.phase != .finished) @panic("render layout plan applied before it was finished");
                if (active_stream.scope_sites.items.len != self.active_new.len or replacement_stream.scope_sites.items.len != self.replacement_new.len) @panic("render layout plan was prepared against different descriptor streams");
                for (active_stream.scope_sites.items, self.active_new) |*site, final_index| if (final_index != unmapped) {
                    site.render_insert_index = final_index;
                };
                for (replacement_stream.scope_sites.items, self.replacement_new) |*site, final_index| site.render_insert_index = final_index;
            }

            fn deinit(self: *@This()) void {
                self.allocator.free(self.replacement_new);
                self.allocator.free(self.active_new);
                self.allocator.free(self.consumed);
                self.placements.deinit(self.allocator);
                self.ranges.deinit(self.allocator);
                self.rows.deinit(self.allocator);
                for (self.regions.items) |region| self.allocator.free(region.pieces);
                self.regions.deinit(self.allocator);
                self.* = undefined;
            }
        };

        const PreparedStructuralDownstream = struct {
            const SparseBranchRange = struct { first: ids.ElemId, last: ids.ElemId, count: usize, after: ?ids.ElemId };
            const HostRenderPublication = if (@hasDecl(Ctx, "RenderPublication")) Ctx.RenderPublication else void;
            engine: *Self,
            host_ctx: Ctx.Handle,
            roc_host: *abi.RocHost,
            replacement: *PreparedReplacementOwner = undefined,
            owns_replacement: bool = true,
            replacement_scope_ids: []u64 = &.{},
            targets: ?PreparedStructuralTargets = null,
            removal: ?structural_splice.PreparedMultiRemoval = null,
            identity_retirements: ?PreparedIdentityRetirements = null,
            state_retirement: ?PreparedStateRetirementIndexes = null,
            retired_state_cells: shared_buffer.List(HostState) = .empty,
            row_retirement: ?each_runtime.PreparedRowRemovals = null,
            retired_stable_generations: shared_buffer.List(*each_generation.Generation) = .empty,
            effects_retirement: ?PreparedEffectRetirements = null,
            retired_stream: HostRetiredDescriptors = .{},
            publication: ?structural_splice.PreparedPublicationDeltas = null,
            final_render_topology: ?PreparedFinalRenderTopology = null,
            render_layout_plan: ?PreparedRenderLayoutPlan = null,
            graph_release: ?active_graph.PreparedReleaseClosure(HostSignalRecord) = null,
            graph_append: ?active_graph.PreparedGraphAppend(HostSignalRecord) = null,
            selector_registry: ?PreparedSelectorAppend = null,
            sink_edits: ?active_graph.PreparedSinkRouteEdits = null,
            source_route_appends: ?active_graph.PreparedRouteAppends(u64) = null,
            text_route_appends: ?active_graph.PreparedRouteAppends(active_graph.TextSink) = null,
            bool_route_appends: ?active_graph.PreparedRouteAppends(active_graph.BoolSink) = null,
            change_route_appends: ?active_graph.PreparedRouteAppends(active_graph.ChangeSink) = null,
            structural_route_appends: ?active_graph.PreparedRouteAppends(active_graph.StructuralSink) = null,
            graph_source_route_count: usize = 0,
            render_splice: ?render_cache_mod.PreparedRenderSplice(Ctx) = null,
            render_batch: render.TransactionalBatch = .{},
            render_batch_target: ?*render.TransactionalBatch = null,
            publication_phase: PublicationPhase = .unprepared,
            host_render_publication: ?HostRenderPublication = null,
            retired_scope_steps: shared_buffer.List(HostScopeStep) = .empty,
            /// Render parents whose final child order this plan publishes itself
            /// through `prepareFinalRenderTopology`, so the structural pass must
            /// not also register them. Borrowed from the caller for the duration
            /// of preparation only.
            suppressed_render_parent_ids: []const u64 = &.{},
            retired_active_events: shared_buffer.List(ActiveEventDesc) = .empty,
            initial_root: bool = false,
            sparse_render_membership: bool = false,
            /// Direct-root classification cost of the last sparse scope
            /// preparation; tests assert it stays linear in retiring scopes.
            direct_root_classification_work: DirectRootClassificationWork = .{},

            // Inspect only descriptors owned by the retiring branch. The
            // descriptor pool is not document order after a sparse row edit.
            fn sparseBranchRange(engine: *Self, allocator: std.mem.Allocator, selection: AggregateBranchSelection) CollectionError!?SparseBranchRange {
                var retirement = scope_runtime.prepareSubtreesRetirement(HostEachRowScopeStep, allocator, engine.scopes.items, &.{selection.retired_scope_id}) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.OverlappingSubtrees => return error.OverlappingRemoval,
                };
                defer retirement.deinit(allocator);
                var roots: std.AutoHashMapUnmanaged(u64, void) = .{};
                defer roots.deinit(allocator);
                for (retirement.scope_ids) |scope_id| for (engine.active_stream.scopeOwnedElemIds(scope_id)) |elem_id| {
                    const index = engine.active_stream.renderNodeIndex(elem_id) orelse return error.InvalidDescriptor;
                    const node = engine.active_stream.render_nodes.items[index];
                    if (renderNodeParentElemId(&engine.active_stream, node) == selection.parent_elem_id.raw()) roots.put(allocator, elem_id.raw(), {}) catch return error.OutOfMemory;
                };
                // An empty branch requires a maintained construction-site
                // anchor; a pool position is deliberately not a substitute.
                if (roots.count() == 0) return null;
                var first: ?ids.ElemId = null;
                var iterator = roots.keyIterator();
                while (iterator.next()) |raw| {
                    const id = ids.ElemId.fromRaw(raw.*);
                    const previous = engine.render_cache.previousSibling(id);
                    if (previous == null or !roots.contains(previous.?.raw())) {
                        if (first != null) return error.InvalidRenderTopology;
                        first = id;
                    }
                }
                var current = first orelse return error.InvalidRenderTopology;
                for (0..roots.count() - 1) |_| {
                    current = engine.render_cache.nextSibling(current) orelse return error.InvalidRenderTopology;
                    if (!roots.contains(current.raw())) return error.InvalidRenderTopology;
                }
                return .{ .first = first.?, .last = current, .count = roots.count(), .after = engine.render_cache.nextSibling(current) };
            }

            fn sparseJournal(self: *@This(), parent: ids.ElemId, touched: usize, wire: usize) CollectionError!*render_cache_mod.PreparedSparseChildren {
                const splice = &(self.render_splice orelse return error.InvalidRenderTopology);
                if (self.publication_phase.needsAbort()) {
                    self.render_batch_target.?.abort();
                    self.publication_phase.resetPreflight();
                }
                if (comptime @hasDecl(Ctx, "RenderPublication")) if (self.host_render_publication) |*publication| {
                    publication.deinit();
                    self.host_render_publication = null;
                };
                for (splice.sparse_children.items) |*journal| if (journal.parent_elem_id == parent) {
                    journal.reserveAdditional(touched, wire) catch |err| return positionError(err);
                    return journal;
                };
                var journal = render_cache_mod.PreparedSparseChildren.init(Ctx, Ctx.allocator(self.host_ctx), &self.engine.render_cache, parent, touched, wire) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.ResourceLimit => return error.ResourceLimit,
                    error.MissingParent => return error.InvalidRenderTopology,
                };
                errdefer journal.deinit();
                splice.adoptSparseChildren(&journal) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    else => return error.InvalidRenderTopology,
                };
                return &splice.sparse_children.items[splice.sparse_children.items.len - 1];
            }

            fn finishSparsePublication(self: *@This()) CollectionError!void {
                if (self.publication_phase.needsAbort()) {
                    self.render_batch_target.?.abort();
                    self.publication_phase.resetPreflight();
                }
                if (comptime @hasDecl(Ctx, "RenderPublication")) if (self.host_render_publication) |*publication| {
                    publication.deinit();
                    self.host_render_publication = null;
                };
                self.replacement.preparePositions().preflight() catch |err| return positionError(err);
                const allocator = Ctx.allocator(self.host_ctx);
                const splice = &self.render_splice.?;
                splice.finishSparseParents() catch |err| return switch (err) {
                    error.InvalidRange => error.InvalidRenderTopology,
                    else => |other| renderSpliceError(other),
                };
                splice.preflight(self.render_batch_target.?, allocator) catch |err| return positionError(err);
                self.publication_phase.markPreflighted();
                if (comptime @hasDecl(Ctx, "prepareRenderPublication")) {
                    self.host_render_publication = Ctx.prepareRenderPublication(self.host_ctx, splice) catch |err| switch (err) {
                        error.OutOfMemory => return error.OutOfMemory,
                        error.ResourceLimit => return error.ResourceLimit,
                        error.InvalidRenderTopology => return error.InvalidRenderTopology,
                    };
                }
            }

            fn retirePositions(self: *@This()) CollectionError!void {
                const positions = self.replacement.preparePositions();
                for (self.targets.?.scope_retirement.?.scope_ids) |scope| positions.retireScope(scope) catch |err| return positionError(err);
            }

            fn adoptSparseBranches(self: *@This(), selections: []const AggregateBranchSelection, collected: anytype) CollectionError!void {
                const allocator = Ctx.allocator(self.host_ctx);
                // Retire visible ranges first. Candidate lexical positions then
                // supply surviving insertion anchors even for zero-root sites.
                for (selections) |selection| if (try sparseBranchRange(self.engine, allocator, selection)) |range| {
                    const journal = try self.sparseJournal(selection.parent_elem_id, range.count + 4, 0);
                    journal.removeRange(Ctx, &self.engine.render_cache, range.first, range.last, range.count) catch |err| switch (err) {
                        error.ResourceLimit => return error.ResourceLimit,
                        else => return error.InvalidRenderTopology,
                    };
                };
                try self.retirePositions();
                const positions = self.replacement.preparePositions();
                const Ordered = struct { index: usize, parent: ids.ElemId, rank: usize };
                const ordered = allocator.alloc(Ordered, selections.len) catch return error.OutOfMemory;
                defer allocator.free(ordered);
                for (selections, ordered, 0..) |selection, *entry, index| entry.* = .{
                    .index = index,
                    .parent = selection.parent_elem_id,
                    .rank = positions.positionRank(selection.parent_elem_id, structural_positions.PositionId.marker(selection.node_id, .when)) catch |err| return positionError(err),
                };
                std.mem.sort(Ordered, ordered, {}, struct {
                    fn less(_: void, a: Ordered, b: Ordered) bool {
                        if (a.parent != b.parent) return a.parent.raw() < b.parent.raw();
                        return a.rank > b.rank;
                    }
                }.less);
                var roots: shared_buffer.List(ids.ElemId) = .empty;
                defer roots.deinit(allocator);
                for (ordered) |entry| {
                    const selection = selections[entry.index];
                    const next = collected[entry.index];
                    const marker = structural_positions.PositionId.marker(selection.node_id, .when);
                    const before = positions.anchor(selection.parent_elem_id, marker) catch |err| return positionError(err);
                    const lexical_before = positions.nextPosition(selection.parent_elem_id, marker) catch |err| return positionError(err);
                    roots.clearRetainingCapacity();
                    for (self.replacement.stream.render_nodes.items[next.start..][0..next.len]) |node| {
                        if (renderNodeParentElemId(&self.replacement.stream, node) == selection.parent_elem_id.raw()) roots.append(allocator, node.elem_id) catch return error.OutOfMemory;
                    }
                    const journal = try self.sparseJournal(selection.parent_elem_id, roots.items.len + 4, roots.items.len);
                    journal.insertRootsBefore(Ctx, &self.engine.render_cache, roots.items, before) catch |err| switch (err) {
                        error.ResourceLimit => return error.ResourceLimit,
                        else => return error.InvalidRenderTopology,
                    };
                    try self.replacement.placeConstructionRange(ids.ScopeId.fromRaw(next.scope_id), selection.parent_elem_id, lexical_before);
                }
                try self.finishSparsePublication();
            }

            fn prepareSparseBranches(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, replacement: *PreparedReplacementOwner, selections: []const AggregateBranchSelection, collected: []const PreparedReplacementOwner.CollectedWhenSelection, overlay: ?*signal_records.PreparedCacheUpdates) CollectionError!?*@This() {
                const allocator = Ctx.allocator(ctx);
                var parents: shared_buffer.List(u64) = .empty;
                defer parents.deinit(allocator);
                var parent_set: std.AutoHashMapUnmanaged(u64, void) = .{};
                defer parent_set.deinit(allocator);
                var retired_roots: shared_buffer.List(ids.ScopeId) = .empty;
                defer retired_roots.deinit(allocator);
                for (selections) |selection| {
                    const parent = try parent_set.getOrPut(allocator, selection.parent_elem_id.raw());
                    if (!parent.found_existing) parents.append(allocator, selection.parent_elem_id.raw()) catch return error.OutOfMemory;
                    retired_roots.append(allocator, selection.retired_scope_id) catch return error.OutOfMemory;
                }
                const plan = try prepareSparseExternalScopes(engine, ctx, roc_host, replacement, retired_roots.items, &.{}, parents.items, overlay);
                errdefer plan.deinit();
                try plan.adoptSparseBranches(selections, collected);
                return plan;
            }

            fn addCounts(total: *StaticRootCounts, next: StaticRootCounts) CollectionError!void {
                try PreparedReplacementOwner.addRootCounts(total, next);
            }

            fn prepare(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, selections: []const AggregateBranchSelection, limits: collection_budget.Limits, dirty_source_node_ids: []const u64) CollectionError!*@This() {
                return prepareWithState(engine, ctx, roc_host, selections, limits, dirty_source_node_ids, &.{}, null);
            }

            fn prepareWithState(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, selections: []const AggregateBranchSelection, limits: collection_budget.Limits, dirty_source_node_ids: []const u64, state_update: []const PreparedExternalState, cache_overlay: ?*signal_records.PreparedCacheUpdates) CollectionError!*@This() {
                if (selections.len == 0) return error.ResourceLimit;
                var total: StaticRootCounts = .{};
                for (selections) |selection| try addCounts(&total, try countStaticRootNodes(selection.elem));

                const allocator = Ctx.allocator(ctx);
                const plan = allocator.create(@This()) catch return error.OutOfMemory;
                var plan_owns_cleanup = false;
                errdefer if (!plan_owns_cleanup) allocator.destroy(plan);
                plan.* = .{ .engine = engine, .host_ctx = ctx, .roc_host = roc_host };
                errdefer if (!plan_owns_cleanup) plan.retired_stream.deinit(allocator, ctx, roc_host, &engine.pending_roc_metrics);
                plan.replacement = try PreparedReplacementOwner.create(engine, ctx, roc_host, limits, total, selections.len);
                errdefer if (!plan_owns_cleanup) plan.replacement.deinit();
                plan.replacement.collection.cache_overlay = cache_overlay;
                try plan.replacement.collection.stageExternalStates(roc_host, state_update);
                plan.replacement_scope_ids = allocator.alloc(u64, selections.len) catch return error.OutOfMemory;
                errdefer if (!plan_owns_cleanup) allocator.free(plan.replacement_scope_ids);
                const replacement_ranges = allocator.alloc(PreparedReplacementOwner.CollectedWhenSelection, selections.len) catch return error.OutOfMemory;
                defer allocator.free(replacement_ranges);

                for (selections, 0..) |selection, index| {
                    replacement_ranges[index] = try plan.replacement.collectWhenSelectionRange(selection, dirty_source_node_ids);
                    plan.replacement_scope_ids[index] = replacement_ranges[index].scope_id;
                }
                plan.replacement.materialize();

                if (try prepareSparseBranches(engine, ctx, roc_host, plan.replacement, selections, replacement_ranges, cache_overlay)) |sparse| {
                    sparse.owns_replacement = true;
                    sparse.replacement_scope_ids = plan.replacement_scope_ids;
                    plan.retired_stream.deinit(allocator, ctx, roc_host, &engine.pending_roc_metrics);
                    allocator.destroy(plan);
                    plan_owns_cleanup = true;
                    return sparse;
                }

                var layout_plan = PreparedRenderLayoutPlan.init(allocator);
                var layout_plan_owned = true;
                errdefer if (layout_plan_owned) layout_plan.deinit();
                const retired_scope_ids = allocator.alloc(u64, selections.len) catch return error.OutOfMemory;
                defer allocator.free(retired_scope_ids);
                const render_insert_indexes = allocator.alloc(usize, selections.len) catch return error.OutOfMemory;
                defer allocator.free(render_insert_indexes);
                // Each branch's removal scan runs against that branch's own
                // scopes: scanned against the union, a walk from one retired
                // branch continues straight into the adjacent one, and the
                // second branch's interval then overlaps the first.
                const scan_scopes = allocator.alloc([]const bool, selections.len) catch return error.OutOfMemory;
                var scan_scopes_prepared: usize = 0;
                defer {
                    for (scan_scopes[0..scan_scopes_prepared]) |scopes| allocator.free(scopes);
                    allocator.free(scan_scopes);
                }
                for (selections, replacement_ranges, 0..) |selection, range, index| {
                    retired_scope_ids[index] = selection.retired_scope_id.raw();
                    render_insert_indexes[index] = try layout_plan.describeBranch(engine, selection, range);
                    const scopes = allocator.alloc(bool, engine.scopes.items.len) catch return error.OutOfMemory;
                    scan_scopes[index] = scopes;
                    scan_scopes_prepared += 1;
                    for (engine.scopes.items, scopes) |scope, *targeted| {
                        targeted.* = scope.lifecycle.isActive() and (engine.scopeIsDescendantOrSelf(scope.scope_id.raw(), selection.retired_scope_id.raw()) catch |err| return scopeError(err));
                    }
                }
                // Each site's parent publishes its final child order from the
                // resolved topology below. The structural pass anchors a branch
                // where the retired branch's children stood, which a branch
                // that rendered nothing never had, so it must not register
                // these parents itself.
                var parents: shared_buffer.List(u64) = .empty;
                defer parents.deinit(allocator);
                for (selections) |selection| try appendUniqueParentElemId(allocator, &parents, selection.parent_elem_id.raw());
                plan.suppressed_render_parent_ids = parents.items;
                try plan.prepareDownstream(allocator, retired_scope_ids, retired_scope_ids, render_insert_indexes, scan_scopes, false, cache_overlay);
                plan.suppressed_render_parent_ids = &.{};
                plan_owns_cleanup = true;
                errdefer plan.deinit();
                try layout_plan.resolve(engine, plan.targets.?.descriptor_target_scopes);
                plan.final_render_topology = try PreparedFinalRenderTopology.preparePlaced(plan.engine, allocator, plan.replacement, plan.targets.?.descriptor_target_scopes, layout_plan.removed_render_count, layout_plan.placements.items);
                layout_plan_owned = false;
                try plan.adoptRenderLayoutPlan(layout_plan);
                try plan.prepareFinalRenderTopology(parents.items);
                return plan;
            }

            /// Records a render parent once for `prepareFinalRenderTopology`,
            /// which refuses a parent listed twice.
            fn appendUniqueParentElemId(allocator: std.mem.Allocator, parents: *shared_buffer.List(u64), parent_elem_id: u64) CollectionError!void {
                for (parents.items) |existing| if (existing == parent_elem_id) return;
                parents.append(allocator, parent_elem_id) catch return error.OutOfMemory;
            }

            fn prepareExternal(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, replacement: *PreparedReplacementOwner, descriptor_root_scope_ids: []const u64, retired_root_scope_ids: []const u64, render_insert_indexes: []const usize, scan_scopes: ?[]const []const bool, suppressed_render_parent_ids: []const u64, cache_overlay: ?*signal_records.PreparedCacheUpdates) CollectionError!*@This() {
                const allocator = Ctx.allocator(ctx);
                const plan = allocator.create(@This()) catch return error.OutOfMemory;
                errdefer allocator.destroy(plan);
                plan.* = .{ .engine = engine, .host_ctx = ctx, .roc_host = roc_host, .replacement = replacement, .owns_replacement = false, .suppressed_render_parent_ids = suppressed_render_parent_ids };
                errdefer plan.retired_stream.deinit(allocator, ctx, roc_host, &engine.pending_roc_metrics);
                try plan.prepareDownstream(allocator, descriptor_root_scope_ids, retired_root_scope_ids, render_insert_indexes, scan_scopes, true, cache_overlay);
                return plan;
            }

            fn prepareInitialRoot(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, replacement: *PreparedReplacementOwner) CollectionError!*@This() {
                if (engine.active_stream.render_nodes.items.len != 0 or engine.active_signal_graph.items.len != 0 or engine.render_cache.hasRoot()) return error.InvalidRenderTopology;
                const allocator = Ctx.allocator(ctx);
                const plan = allocator.create(@This()) catch return error.OutOfMemory;
                errdefer allocator.destroy(plan);
                plan.* = .{ .engine = engine, .host_ctx = ctx, .roc_host = roc_host, .replacement = replacement, .owns_replacement = false, .initial_root = true };
                errdefer plan.retired_stream.deinit(allocator, ctx, roc_host, &engine.pending_roc_metrics);
                try plan.prepareDownstream(allocator, &.{}, &.{}, &.{}, null, true, null);
                return plan;
            }

            fn prepareEachRenderTopology(self: *@This(), rows: *const PreparedEachRowReplacementCollection, layout: *const PreparedEachRowRenderLayout, render_parent_ids: []const u64) CollectionError!void {
                const allocator = Ctx.allocator(self.host_ctx);
                var plan = PreparedRenderLayoutPlan.init(allocator);
                var plan_owned = true;
                errdefer if (plan_owned) plan.deinit();
                try plan.describeEachSite(layout);
                try plan.describeNestedSites(rows.replacement.collection.nested_row_syncs.items);
                try plan.resolve(self.engine, layout.targets.descriptor_target_scopes);
                self.final_render_topology = try PreparedFinalRenderTopology.preparePlaced(self.engine, allocator, rows.replacement, layout.targets.descriptor_target_scopes, plan.removed_render_count, plan.placements.items);
                plan_owned = false;
                try self.adoptRenderLayoutPlan(plan);
                try self.prepareFinalRenderTopology(render_parent_ids);
            }

            /// Takes ownership of a resolved layout plan and resolves every
            /// scope site's index against this downstream's retirement targets
            /// and final topology. The plan is released here on failure, so a
            /// caller hands it over exactly once.
            fn adoptRenderLayoutPlan(self: *@This(), staged: PreparedRenderLayoutPlan) CollectionError!void {
                var plan = staged;
                errdefer plan.deinit();
                if (self.render_layout_plan != null) return error.ResourceLimit;
                const topology = &(self.final_render_topology orelse return error.ResourceLimit);
                const targets = self.targets orelse return error.ResourceLimit;
                try plan.finish(self.engine, &self.replacement.stream, targets.descriptor_target_scopes, topology.render_nodes.items.len);
                self.render_layout_plan = plan;
            }

            fn prepareFinalRenderTopology(self: *@This(), parent_elem_ids: []const u64) CollectionError!void {
                const splice = &(self.render_splice orelse return);
                const allocator = Ctx.allocator(self.host_ctx);
                if (self.publication_phase.needsAbort()) {
                    self.render_batch_target.?.abort();
                    self.publication_phase.resetPreflight();
                }
                if (comptime @hasDecl(Ctx, "RenderPublication")) if (self.host_render_publication) |*publication| {
                    publication.deinit();
                    self.host_render_publication = null;
                };
                var child_capacity: usize = 0;
                for (parent_elem_ids) |parent_elem_id| {
                    const parent_index = std.math.cast(usize, parent_elem_id) orelse return error.ResourceLimit;
                    if (parent_index < self.engine.render_cache.nodes.items.len and self.engine.render_cache.nodes.items[parent_index].isActive())
                        child_capacity = std.math.add(usize, child_capacity, self.engine.render_cache.nodes.items[parent_index].children.items.len) catch return error.ResourceLimit;
                    var child_id = if (self.final_render_topology.?.metadata.get(parent_elem_id)) |entry| entry.first_child else null;
                    while (child_id) |id| {
                        child_capacity = std.math.add(usize, child_capacity, 1) catch return error.ResourceLimit;
                        child_id = (self.final_render_topology.?.metadata.get(id.raw()) orelse return error.InvalidRenderTopology).next_sibling;
                    }
                }
                try splice.reserveAdditionalChildren(parent_elem_ids.len, child_capacity);
                for (parent_elem_ids, 0..) |parent_elem_id, parent_offset| {
                    for (parent_elem_ids[0..parent_offset]) |previous| if (previous == parent_elem_id) return error.ResourceLimit;
                    var children: shared_buffer.List(ids.ElemId) = .empty;
                    defer children.deinit(allocator);
                    var child_id = if (self.final_render_topology.?.metadata.get(parent_elem_id)) |entry| entry.first_child else null;
                    while (child_id) |id| {
                        children.append(allocator, id) catch return error.OutOfMemory;
                        child_id = (self.final_render_topology.?.metadata.get(id.raw()) orelse return error.InvalidRenderTopology).next_sibling;
                    }
                    splice.addChildren(&self.engine.render_cache, ids.ElemId.fromRaw(parent_elem_id), children.items) catch |err| return renderSpliceError(err);
                }
                splice.preflight(self.render_batch_target.?, allocator) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.ResourceLimit => return error.ResourceLimit,
                };
                self.publication_phase.markPreflighted();
                if (comptime @hasDecl(Ctx, "prepareRenderPublication")) {
                    self.host_render_publication = Ctx.prepareRenderPublication(self.host_ctx, splice) catch |err| switch (err) {
                        error.OutOfMemory => return error.OutOfMemory,
                        error.ResourceLimit => return error.ResourceLimit,
                        error.InvalidRenderTopology => return error.InvalidRenderTopology,
                    };
                }
            }

            fn adoptScalarRenderSplice(self: *@This(), scalar: *render_cache_mod.PreparedRenderSplice(Ctx)) CollectionError!void {
                const splice = &(self.render_splice orelse return error.ResourceLimit);
                const allocator = Ctx.allocator(self.host_ctx);
                if (self.publication_phase.needsAbort()) {
                    self.render_batch_target.?.abort();
                    self.publication_phase.resetPreflight();
                }
                if (comptime @hasDecl(Ctx, "RenderPublication")) if (self.host_render_publication) |*publication| {
                    publication.deinit();
                    self.host_render_publication = null;
                };
                splice.adoptScalarUpdates(scalar) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.ResourceLimit => return error.ResourceLimit,
                };
                splice.preflight(self.render_batch_target.?, allocator) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.ResourceLimit => return error.ResourceLimit,
                };
                self.publication_phase.markPreflighted();
                if (comptime @hasDecl(Ctx, "prepareRenderPublication")) {
                    self.host_render_publication = Ctx.prepareRenderPublication(self.host_ctx, splice) catch |err| switch (err) {
                        error.OutOfMemory => return error.OutOfMemory,
                        error.ResourceLimit => return error.ResourceLimit,
                        error.InvalidRenderTopology => return error.InvalidRenderTopology,
                    };
                }
            }

            fn prepareExternalEach(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, rows: *const each_runtime.PreparedRowSync, inputs: *const PreparedEachInputs, replacement: *PreparedEachRowReplacementCollection, layout: *const PreparedEachRowRenderLayout, cache_overlay: ?*signal_records.PreparedCacheUpdates) CollectionError!*@This() {
                const allocator = Ctx.allocator(ctx);
                const previous_bindings = engine.active_each_candidate_bindings;
                const previous_inputs = engine.active_each_candidate_inputs;
                const previous_generation = engine.active_each_candidate_generation;
                const previous_rows_site_id = engine.active_each_candidate_rows_site_id;
                engine.active_each_candidate_bindings = &inputs.candidate_bindings;
                engine.active_each_candidate_inputs = inputs;
                engine.active_each_candidate_generation = inputs.generation;
                engine.active_each_candidate_rows_site_id = inputs.rows_site_id;
                defer {
                    engine.active_each_candidate_bindings = previous_bindings;
                    engine.active_each_candidate_inputs = previous_inputs;
                    engine.active_each_candidate_generation = previous_generation;
                    engine.active_each_candidate_rows_site_id = previous_rows_site_id;
                }
                // The site's parent and the parents of every live nested
                // site take their final child order from the topology.
                var render_parents: shared_buffer.List(u64) = .empty;
                defer render_parents.deinit(allocator);
                render_parents.append(allocator, layout.site.parent_elem_id.raw()) catch return error.OutOfMemory;
                try replacement.replacement.collection.appendNestedSiteRenderParents(allocator, &render_parents);
                var descriptor_roots: shared_buffer.List(u64) = .empty;
                defer descriptor_roots.deinit(allocator);
                descriptor_roots.ensureTotalCapacity(allocator, std.math.add(usize, rows.removed_scope_ids.len, replacement.replacement_rows.len) catch return error.ResourceLimit) catch return error.OutOfMemory;
                for (rows.removed_scope_ids) |scope_id| descriptor_roots.appendAssumeCapacity(scope_id.raw());
                for (replacement.replacement_rows) |row| if (!row.created) descriptor_roots.appendAssumeCapacity(row.scope_id.raw());
                const downstream = try prepareExternal(engine, ctx, roc_host, replacement.replacement, descriptor_roots.items, @ptrCast(rows.removed_scope_ids), layout.remove_starts, null, render_parents.items, cache_overlay);
                errdefer downstream.deinit();
                try downstream.prepareEachRenderTopology(replacement, layout, render_parents.items);
                return downstream;
            }

            fn prepareSparseExternalEach(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, site: HostNodeScopeSiteDesc, rows: *PreparedActiveEachRows, replacement: *PreparedEachRowReplacementCollection, cache_overlay: ?*signal_records.PreparedCacheUpdates) CollectionError!*@This() {
                const rows_site_id = rows.inputs.rows_site_id orelse return error.InvalidDescriptor;
                const previous_bindings = engine.active_each_candidate_bindings;
                const previous_inputs = engine.active_each_candidate_inputs;
                const previous_generation = engine.active_each_candidate_generation;
                const previous_rows_site_id = engine.active_each_candidate_rows_site_id;
                engine.active_each_candidate_bindings = &rows.inputs.candidate_bindings;
                engine.active_each_candidate_inputs = &rows.inputs;
                engine.active_each_candidate_generation = rows.inputs.generation;
                engine.active_each_candidate_rows_site_id = rows_site_id;
                defer {
                    engine.active_each_candidate_bindings = previous_bindings;
                    engine.active_each_candidate_inputs = previous_inputs;
                    engine.active_each_candidate_generation = previous_generation;
                    engine.active_each_candidate_rows_site_id = previous_rows_site_id;
                }

                const retired_roots = rows.rows.removed_scope_ids;

                const suppressed_parent = [_]u64{site.parent_elem_id.raw()};
                const plan = try prepareSparseExternalScopes(engine, ctx, roc_host, replacement.replacement, retired_roots, retired_roots, &suppressed_parent, cache_overlay);
                errdefer plan.deinit();
                try plan.adoptSparseEachRender(site, rows);
                try plan.retirePositions();
                try plan.finishSparsePublication();
                return plan;
            }

            /// Work performed while splitting retiring scopes into direct
            /// synchronized row roots and nested scopes. `membership_probes`
            /// is one per retiring scope, so a restored nested scan over the
            /// roots would report the triangular product instead.
            pub const DirectRootClassificationWork = struct {
                roots_indexed: usize = 0,
                scopes_classified: usize = 0,
                membership_probes: usize = 0,
                direct_matches: usize = 0,
            };

            /// Preflighted membership of the synchronized direct row roots.
            ///
            /// A Rows transition already retires its direct rows through the
            /// rows-site plan; only nested descendants (child rows, components,
            /// branches) need the scope-owned row retirement. Deciding which
            /// side each retiring scope falls on must cost one probe per scope
            /// rather than a scan over every root, otherwise clearing K rows
            /// pays K(K+1)/2 comparisons. `init` performs the only allocation;
            /// `classify` is allocation free so the caller can preflight the
            /// nested buffer and commit without a fallible step in between.
            pub const DirectRowRootMembership = struct {
                roots: []const ids.ScopeId,
                set: std.AutoHashMapUnmanaged(u64, void) = .{},

                /// Indexes `roots`. Duplicate roots are a caller contract
                /// error because each root is retired exactly once. On
                /// `OutOfMemory` nothing is retained and the call can be
                /// retried.
                pub fn init(allocator: std.mem.Allocator, roots: []const ids.ScopeId) CollectionError!@This() {
                    var membership: @This() = .{ .roots = roots };
                    errdefer membership.deinit(allocator);
                    membership.set.ensureTotalCapacity(allocator, std.math.cast(u32, roots.len) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                    for (roots) |root| {
                        const entry = membership.set.getOrPutAssumeCapacity(root.raw());
                        if (entry.found_existing) return error.InvalidDescriptor;
                    }
                    return membership;
                }

                /// Releases the index. Safe after a failed `init`.
                pub fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
                    self.set.deinit(allocator);
                }

                /// Appends every retiring scope that is not a direct root to
                /// `nested`, which must already hold capacity for all of
                /// `retirement_scope_ids`; this never allocates. Every direct
                /// root must be among the retiring scopes, otherwise the
                /// caller passed roots outside the retired subtrees and the
                /// call refuses with `InvalidDescriptor`; `nested` is caller
                /// scratch and holds no meaning after a refusal.
                pub fn classify(self: *const @This(), retirement_scope_ids: []const ids.ScopeId, nested: *shared_buffer.List(ids.ScopeId)) CollectionError!DirectRootClassificationWork {
                    std.debug.assert(nested.capacity - nested.items.len >= retirement_scope_ids.len);
                    var work: DirectRootClassificationWork = .{ .roots_indexed = self.roots.len };
                    for (retirement_scope_ids) |scope_id| {
                        work.scopes_classified += 1;
                        work.membership_probes += 1;
                        if (self.set.contains(scope_id.raw())) {
                            work.direct_matches += 1;
                        } else {
                            nested.appendAssumeCapacity(scope_id);
                        }
                    }
                    if (work.direct_matches != self.roots.len) return error.InvalidDescriptor;
                    return work;
                }
            };

            // Exact scope ownership is shared by one Rows edit and mixed
            // structural edits. Render-pool positions never identify ownership.
            fn prepareSparseExternalScopes(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, replacement: *PreparedReplacementOwner, retired_roots: []const ids.ScopeId, synced_row_roots: []const ids.ScopeId, suppressed_parents: []const u64, cache_overlay: ?*signal_records.PreparedCacheUpdates) CollectionError!*@This() {
                const allocator = Ctx.allocator(ctx);
                const plan = allocator.create(@This()) catch return error.OutOfMemory;
                errdefer allocator.destroy(plan);
                plan.* = .{
                    .engine = engine,
                    .host_ctx = ctx,
                    .roc_host = roc_host,
                    .replacement = replacement,
                    .owns_replacement = false,
                    .sparse_render_membership = true,
                };
                errdefer plan.retired_stream.deinit(allocator, ctx, roc_host, &engine.pending_roc_metrics);

                const retirement = scope_runtime.prepareSubtreesRetirement(HostEachRowScopeStep, allocator, engine.scopes.items, retired_roots) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.OverlappingSubtrees => return error.OverlappingRemoval,
                };
                const empty_targets = allocator.alloc(bool, 0) catch return error.OutOfMemory;
                plan.targets = .{ .descriptor_target_scopes = empty_targets, .scope_retirement = retirement };
                errdefer if (plan.targets) |*targets| targets.deinit(allocator);
                const retirement_scope_ids = plan.targets.?.scope_retirement.?.scope_ids;

                var exact_removal = structural_splice.prepareScopeOwnedRemoval(HostNodeDescriptorStream, allocator, &engine.active_stream, retirement_scope_ids) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.ResourceLimit => return error.ResourceLimit,
                    error.InvalidDescriptor => return error.InvalidDescriptor,
                };
                var exact_removal_owned = true;
                errdefer if (exact_removal_owned) exact_removal.deinit(allocator);
                const empty_intervals = allocator.alloc(structural_splice.RenderRemovalInterval, 0) catch return error.OutOfMemory;
                plan.removal = .{ .removal = exact_removal, .intervals_descending = empty_intervals };
                exact_removal_owned = false;
                errdefer if (plan.removal) |*removal| removal.deinit(allocator);

                plan.identity_retirements = try PreparedIdentityRetirements.prepareExactRemoval(engine, allocator, retirement_scope_ids, &plan.removal.?.removal);
                errdefer if (plan.identity_retirements) |*retirements| retirements.deinit(allocator);
                plan.state_retirement = try PreparedStateRetirementIndexes.prepare(engine, allocator, plan.removal.?.removal.node_indexes.state_indexes.items);
                errdefer if (plan.state_retirement) |*retirement_plan| retirement_plan.deinit(allocator);
                try plan.state_retirement.?.reserveRetired(allocator, &plan.retired_state_cells);
                errdefer plan.retired_state_cells.deinit(allocator);

                var nested_row_scopes: shared_buffer.List(ids.ScopeId) = .empty;
                defer nested_row_scopes.deinit(allocator);
                nested_row_scopes.ensureTotalCapacity(allocator, retirement_scope_ids.len) catch return error.OutOfMemory;
                var direct_roots = try DirectRowRootMembership.init(allocator, synced_row_roots);
                defer direct_roots.deinit(allocator);
                plan.direct_root_classification_work = try direct_roots.classify(retirement_scope_ids, &nested_row_scopes);
                plan.row_retirement = try prepareRowRetirementForScopes(engine, allocator, nested_row_scopes.items);
                errdefer if (plan.row_retirement) |*retirement_plan| retirement_plan.deinit(allocator);
                plan.retired_stable_generations.ensureTotalCapacity(allocator, plan.row_retirement.?.rows.len) catch return error.OutOfMemory;
                errdefer plan.retired_stable_generations.deinit(allocator);
                plan.effects_retirement = try PreparedEffectRetirements.prepare(engine, allocator, plan.removal.?.removal.node_indexes.cleanup_indexes.items);
                errdefer if (plan.effects_retirement) |*effects| effects.deinit(allocator, null);
                plan.retired_scope_steps.ensureUnusedCapacity(allocator, retirement_scope_ids.len) catch return error.OutOfMemory;
                errdefer plan.retired_scope_steps.deinit(allocator);

                const removed_event_count = plan.removal.?.removal.descriptor_indexes.event_indexes.items.len;
                const retained_event_count = std.math.sub(usize, engine.active_events.items.len, removed_event_count) catch return error.ResourceLimit;
                const final_event_count = std.math.add(usize, retained_event_count, plan.replacement.stream.events.items.len) catch return error.ResourceLimit;
                engine.active_events.ensureTotalCapacity(allocator, final_event_count) catch return error.OutOfMemory;
                plan.retired_active_events.ensureTotalCapacity(allocator, removed_event_count) catch return error.OutOfMemory;
                errdefer plan.retired_active_events.deinit(allocator);
                if (cache_overlay) |overlay| try engine.reserveCacheBearingDescriptorPublication(allocator, &plan.replacement.stream, overlay);
                try engine.active_stream.reserveMovedStreamPublication(allocator, &plan.replacement.stream);
                try prepareRetiredStreamCapacity(allocator, &plan.retired_stream, &plan.removal.?.removal);
                const on_change_base = std.math.sub(usize, engine.active_stream.on_changes.items.len, plan.removal.?.removal.node_indexes.on_change_indexes.items.len) catch return error.ResourceLimit;
                const mount_base = std.math.sub(usize, engine.active_stream.mounts.items.len, plan.removal.?.removal.node_indexes.mount_indexes.items.len) catch return error.ResourceLimit;
                plan.publication = structural_splice.preparePublicationDeltas(allocator, plan.replacement.stream.render_nodes.items, &.{}, on_change_base, plan.replacement.stream.on_changes.items.len, mount_base, plan.replacement.stream.mounts.items.len) catch return error.OutOfMemory;
                errdefer if (plan.publication) |*publication| publication.deinit(allocator);

                plan.suppressed_render_parent_ids = suppressed_parents;
                try plan.prepareGraphRenderAndPublication(allocator);
                plan.suppressed_render_parent_ids = &.{};
                return plan;
            }

            fn adoptSparseSnapshotRows(self: *@This(), site: HostNodeScopeSiteDesc, rows: *PreparedActiveEachRows) CollectionError!void {
                const positions = self.replacement.preparePositions();
                const parent = site.parent_elem_id;
                for (rows.rows.removed_scope_ids) |scope| {
                    const first = structural_positions.PositionId.rowStart(scope);
                    const last = structural_positions.PositionId.rowEnd(scope);
                    const roots = positions.rootsInRange(parent, first, last) catch |err| return positionError(err);
                    const journal = try self.sparseJournal(parent, roots.count + 4, 0);
                    if (roots.count != 0) journal.removeRange(Ctx, &self.engine.render_cache, roots.first.?, roots.last.?, roots.count) catch |err| switch (err) {
                        error.ResourceLimit => return error.ResourceLimit,
                        else => return error.InvalidRenderTopology,
                    };
                    positions.retireRange(parent, first, last) catch |err| return positionError(err);
                }
                // Snapshot matching has already identified retained scopes.
                // Place them right-to-left; an unchanged suffix produces no
                // render moves, while empty row ranges carry their markers.
                const allocator = Ctx.allocator(self.host_ctx);
                var roots: shared_buffer.List(ids.ElemId) = .empty;
                defer roots.deinit(allocator);
                var before_position = structural_positions.PositionId.marker(site.node_id, .each_end);
                var index = rows.rows.next_scope_ids.len;
                while (index != 0) {
                    index -= 1;
                    const scope = rows.rows.next_scope_ids[index];
                    const before = positions.anchor(parent, before_position) catch |err| return positionError(err);
                    if (self.replacement.construction_ranges.get(scope)) |range| {
                        roots.clearRetainingCapacity();
                        for (self.replacement.collection.construction_order.items[range.start..][0..range.len]) |entry| {
                            if (entry.parent == parent and entry.position.raw() >> 64 == 0) roots.append(allocator, ids.ElemId.fromRaw(@truncate(entry.position.raw()))) catch return error.OutOfMemory;
                        }
                        const journal = try self.sparseJournal(parent, roots.items.len + 4, roots.items.len);
                        journal.insertRootsBefore(Ctx, &self.engine.render_cache, roots.items, before) catch |err| switch (err) {
                            error.ResourceLimit => return error.ResourceLimit,
                            else => return error.InvalidRenderTopology,
                        };
                        try self.replacement.placeConstructionRange(scope, parent, before_position);
                    } else {
                        const first = structural_positions.PositionId.rowStart(scope);
                        const last = structural_positions.PositionId.rowEnd(scope);
                        const span = positions.rootsInRange(parent, first, last) catch |err| return positionError(err);
                        const journal = try self.sparseJournal(parent, span.count + 4, span.count);
                        if (span.count != 0) journal.moveRangeBefore(Ctx, &self.engine.render_cache, span.first.?, span.last.?, span.count, before) catch |err| switch (err) {
                            error.ResourceLimit => return error.ResourceLimit,
                            else => return error.InvalidRenderTopology,
                        };
                        positions.moveRange(parent, first, last, before_position) catch |err| return positionError(err);
                    }
                    before_position = structural_positions.PositionId.rowStart(scope);
                }
            }

            fn adoptSparseEachRender(self: *@This(), site: HostNodeScopeSiteDesc, rows: *PreparedActiveEachRows) CollectionError!void {
                if (!rows.direct_delta) return self.adoptSparseSnapshotRows(site, rows);
                const transition = &rows.inputs.rows_transition.?;
                const allocator = Ctx.allocator(self.host_ctx);
                if (self.publication_phase.needsAbort()) {
                    self.render_batch_target.?.abort();
                    self.publication_phase.resetPreflight();
                }
                if (comptime @hasDecl(Ctx, "RenderPublication")) if (self.host_render_publication) |*publication| {
                    publication.deinit();
                    self.host_render_publication = null;
                };

                const journal = try self.sparseJournal(site.parent_elem_id, 0, 0);
                const positions = self.replacement.preparePositions();
                const end_marker = structural_positions.PositionId.marker(site.node_id, .each_end);
                var roots: shared_buffer.List(ids.ElemId) = .empty;
                defer roots.deinit(allocator);

                for (transition.orderEdits()) |edit| switch (edit) {
                    .insert => |insert| {
                        const candidate = transition.candidateBySlot(insert.slot) orelse return error.InvalidDescriptor;
                        const span = candidate.metadata.render_span;
                        journal.reserveAdditional(span.root_count + 4, span.root_count) catch |err| return positionError(err);
                        roots.ensureTotalCapacity(allocator, span.root_count) catch return error.OutOfMemory;
                        const lexical_before = if (insert.before_scope_id == 0) end_marker else structural_positions.PositionId.rowStart(ids.ScopeId.fromRaw(insert.before_scope_id));
                        const before = positions.anchor(site.parent_elem_id, lexical_before) catch |err| return positionError(err);
                        const row_scope = ids.ScopeId.fromRaw(insert.scope_id);
                        if (self.replacement.construction_ranges.contains(row_scope)) {
                            try self.replacement.placeConstructionRange(row_scope, site.parent_elem_id, lexical_before);
                        } else {
                            positions.moveRange(site.parent_elem_id, structural_positions.PositionId.rowStart(row_scope), structural_positions.PositionId.rowEnd(row_scope), lexical_before) catch |err| return positionError(err);
                        }
                        if (span.root_count == 0) continue;
                        roots.clearRetainingCapacity();
                        var current: ?ids.ElemId = if (span.first_root) |root_id| ids.ElemId.fromRaw(root_id) else null;
                        for (0..span.root_count) |_| {
                            const root_id = current orelse return error.InvalidRenderTopology;
                            const stream = if (self.replacement.stream.renderNodeIndex(root_id) != null) &self.replacement.stream else &self.engine.active_stream;
                            const node_index = stream.renderNodeIndex(root_id) orelse return error.InvalidRenderTopology;
                            if (node_index >= stream.render_nodes.items.len) return error.InvalidRenderTopology;
                            const node = stream.render_nodes.items[node_index];
                            if (renderNodeParentElemId(stream, node) != site.parent_elem_id.raw()) return error.InvalidRenderTopology;
                            roots.appendAssumeCapacity(root_id);
                            current = stream.nextRenderSibling(root_id);
                        }
                        journal.insertRootsBefore(Ctx, &self.engine.render_cache, roots.items, before) catch |err| switch (err) {
                            error.ResourceLimit => return error.ResourceLimit,
                            error.InvalidAnchor, error.InvalidRange, error.MissingNode => return error.InvalidRenderTopology,
                        };
                    },
                    .remove => |remove| {
                        const span = positions.rootsInRange(site.parent_elem_id, structural_positions.PositionId.rowStart(ids.ScopeId.fromRaw(remove.first_scope_id)), structural_positions.PositionId.rowEnd(ids.ScopeId.fromRaw(remove.last_scope_id))) catch |err| return positionError(err);
                        journal.reserveAdditional(span.count + 4, 0) catch |err| return positionError(err);
                        positions.retireRange(site.parent_elem_id, structural_positions.PositionId.rowStart(ids.ScopeId.fromRaw(remove.first_scope_id)), structural_positions.PositionId.rowEnd(ids.ScopeId.fromRaw(remove.last_scope_id))) catch |err| return positionError(err);
                        if (span.count == 0) continue;
                        journal.removeRange(Ctx, &self.engine.render_cache, span.first.?, span.last.?, span.count) catch |err| switch (err) {
                            error.ResourceLimit => return error.ResourceLimit,
                            error.InvalidRange, error.MissingNode => return error.InvalidRenderTopology,
                        };
                    },
                    .move => |move| {
                        const span = positions.rootsInRange(site.parent_elem_id, structural_positions.PositionId.rowStart(ids.ScopeId.fromRaw(move.first_scope_id)), structural_positions.PositionId.rowEnd(ids.ScopeId.fromRaw(move.last_scope_id))) catch |err| return positionError(err);
                        journal.reserveAdditional(span.count + 4, span.count) catch |err| return positionError(err);
                        const lexical_before = if (move.before_scope_id == 0) end_marker else structural_positions.PositionId.rowStart(ids.ScopeId.fromRaw(move.before_scope_id));
                        const before = positions.anchor(site.parent_elem_id, lexical_before) catch |err| return positionError(err);
                        positions.moveRange(site.parent_elem_id, structural_positions.PositionId.rowStart(ids.ScopeId.fromRaw(move.first_scope_id)), structural_positions.PositionId.rowEnd(ids.ScopeId.fromRaw(move.last_scope_id)), lexical_before) catch |err| return positionError(err);
                        if (span.count == 0) continue;
                        journal.moveRangeBefore(Ctx, &self.engine.render_cache, span.first.?, span.last.?, span.count, before) catch |err| switch (err) {
                            error.ResourceLimit => return error.ResourceLimit,
                            error.InvalidAnchor, error.InvalidRange, error.MissingNode => return error.InvalidRenderTopology,
                        };
                    },
                    .clear => {
                        const span = positions.rootsInRange(site.parent_elem_id, structural_positions.PositionId.marker(site.node_id, .each), end_marker) catch |err| return positionError(err);
                        journal.reserveAdditional(span.count + 4, 0) catch |err| return positionError(err);
                        if (span.count == 0) continue;
                        journal.removeRange(Ctx, &self.engine.render_cache, span.first.?, span.last.?, span.count) catch |err| switch (err) {
                            error.ResourceLimit => return error.ResourceLimit,
                            error.InvalidRange, error.MissingNode => return error.InvalidRenderTopology,
                        };
                    },
                };
            }

            fn prepareDownstream(self: *@This(), allocator: std.mem.Allocator, descriptor_root_scope_ids: []const u64, retired_root_scope_ids: []const u64, render_insert_indexes: []const usize, scan_scopes: ?[]const []const bool, external_row_sync: bool, cache_overlay: ?*signal_records.PreparedCacheUpdates) CollectionError!void {
                const nested_syncs = self.replacement.collection.nested_row_syncs.items;
                self.targets = try PreparedStructuralTargets.prepare(self.engine, allocator, descriptor_root_scope_ids, retired_root_scope_ids, &self.replacement.collection);
                errdefer if (self.targets) |*targets| targets.deinit(allocator);
                const target_scopes = self.targets.?.descriptor_target_scopes;
                const retirement_scope_ids = self.targets.?.scope_retirement.?.scope_ids;
                self.removal = structural_splice.prepareMultiRemoval(HostNodeDescriptorStream, allocator, &self.engine.active_stream, render_insert_indexes, target_scopes, scan_scopes) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.ResourceLimit => return error.ResourceLimit,
                    error.InvalidDescriptor => return error.InvalidDescriptor,
                    error.OverlappingIntervals => return error.OverlappingRemoval,
                };
                errdefer if (self.removal) |*removal| removal.deinit(allocator);
                self.identity_retirements = try PreparedIdentityRetirements.prepareExactRemoval(self.engine, allocator, retirement_scope_ids, &self.removal.?.removal);
                errdefer if (self.identity_retirements) |*retirements| retirements.deinit(allocator);
                // A state site the replacement declares again under its
                // committed node id keeps its cell: the descriptor is
                // replaced, the value the site holds is not. Only the cells
                // of sites the replacement does not re-declare retire.
                var retired_state_indexes: shared_buffer.List(usize) = .empty;
                defer retired_state_indexes.deinit(allocator);
                retired_state_indexes.ensureTotalCapacity(allocator, self.removal.?.removal.node_indexes.state_indexes.items.len) catch return error.OutOfMemory;
                for (self.removal.?.removal.node_indexes.state_indexes.items) |state_index| {
                    if (state_index >= self.engine.active_stream.states.items.len) return error.InvalidDescriptor;
                    const node_id = self.engine.active_stream.states.items[state_index].node_id;
                    const redeclared = for (self.replacement.stream.states.items) |state| {
                        if (state.node_id == node_id) break true;
                    } else false;
                    if (!redeclared) retired_state_indexes.appendAssumeCapacity(state_index);
                }
                self.state_retirement = try PreparedStateRetirementIndexes.prepare(self.engine, allocator, retired_state_indexes.items);
                errdefer if (self.state_retirement) |*retirement| retirement.deinit(allocator);
                try self.state_retirement.?.reserveRetired(allocator, &self.retired_state_cells);
                errdefer self.retired_state_cells.deinit(allocator);
                if (!external_row_sync) {
                    self.row_retirement = try prepareRowRetirementForScopes(self.engine, allocator, retirement_scope_ids);
                } else {
                    // A row sync removes the retired rows from its own site
                    // itself - the transaction's syncs and the live nested
                    // sites re-collected rows reconcile alike - but a retired
                    // row can own nested each sites whose rows live in
                    // `each_row_sites` too. Retire those with the subtree, and
                    // journal even when there are none: applying the journal is
                    // what drops an emptied site whose descriptor is gone, and a
                    // nested site with no rows is exactly such a site.
                    var nested: shared_buffer.List(ids.ScopeId) = .empty;
                    defer nested.deinit(allocator);
                    nested.ensureTotalCapacity(allocator, retirement_scope_ids.len) catch return error.OutOfMemory;
                    for (retirement_scope_ids) |scope_id| {
                        const synced = for (retired_root_scope_ids) |root| {
                            if (root == scope_id.raw()) break true;
                        } else for (nested_syncs) |*sync| {
                            if (sync.removesRow(scope_id.raw())) break true;
                        } else false;
                        if (!synced) nested.appendAssumeCapacity(scope_id);
                    }
                    self.row_retirement = try prepareRowRetirementForScopes(self.engine, allocator, nested.items);
                }
                errdefer if (self.row_retirement) |*retirement| retirement.deinit(allocator);
                self.retired_stable_generations.ensureTotalCapacity(allocator, self.row_retirement.?.rows.len) catch return error.OutOfMemory;
                errdefer self.retired_stable_generations.deinit(allocator);
                self.effects_retirement = try PreparedEffectRetirements.prepare(self.engine, allocator, self.removal.?.removal.node_indexes.cleanup_indexes.items);
                errdefer if (self.effects_retirement) |*effects| effects.deinit(allocator, null);
                self.retired_scope_steps.ensureUnusedCapacity(allocator, retirement_scope_ids.len) catch return error.OutOfMemory;
                errdefer self.retired_scope_steps.deinit(allocator);
                const removed_event_count = self.removal.?.removal.descriptor_indexes.event_indexes.items.len;
                const retained_event_count = std.math.sub(usize, self.engine.active_events.items.len, removed_event_count) catch return error.ResourceLimit;
                const final_event_count = std.math.add(usize, retained_event_count, self.replacement.stream.events.items.len) catch return error.ResourceLimit;
                self.engine.active_events.ensureTotalCapacity(allocator, final_event_count) catch return error.OutOfMemory;
                self.retired_active_events.ensureTotalCapacity(allocator, removed_event_count) catch return error.OutOfMemory;
                errdefer self.retired_active_events.deinit(allocator);
                if (cache_overlay) |overlay| try self.engine.reserveCacheBearingDescriptorPublication(allocator, &self.replacement.stream, overlay);
                try self.engine.active_stream.reserveMovedStreamPublication(allocator, &self.replacement.stream);
                try prepareRetiredStreamCapacity(allocator, &self.retired_stream, &self.removal.?.removal);
                const on_change_base = std.math.sub(usize, self.engine.active_stream.on_changes.items.len, self.removal.?.removal.node_indexes.on_change_indexes.items.len) catch return error.ResourceLimit;
                const mount_base = std.math.sub(usize, self.engine.active_stream.mounts.items.len, self.removal.?.removal.node_indexes.mount_indexes.items.len) catch return error.ResourceLimit;
                self.publication = structural_splice.preparePublicationDeltas(allocator, self.replacement.stream.render_nodes.items, &.{}, on_change_base, self.replacement.stream.on_changes.items.len, mount_base, self.replacement.stream.mounts.items.len) catch return error.OutOfMemory;
                errdefer if (self.publication) |*publication| publication.deinit(allocator);
                try self.prepareGraphRenderAndPublication(allocator);
            }

            fn prepareGraphRenderAndPublication(self: *@This(), allocator: std.mem.Allocator) CollectionError!void {
                // A bare `Ref` record carries no token, so the token index
                // cannot stand in for "the replacement binds a signal": the
                // graph roots the replacement stream binds are the honest test.
                var replacement_roots: shared_buffer.List(*HostSignalRecord) = .empty;
                defer replacement_roots.deinit(allocator);
                try collectReplacementGraphRootsForStream(allocator, &self.replacement.stream, &replacement_roots);
                if (self.engine.active_signal_graph.items.len != 0 or replacement_roots.items.len != 0) {
                    self.sink_edits = try self.prepareSinkEdits(allocator);
                    errdefer if (self.sink_edits) |*edits| edits.deinit(allocator);
                    var retired_roots: shared_buffer.List(*HostSignalRecord) = .empty;
                    defer retired_roots.deinit(allocator);
                    try collectRetiredGraphRootsForRemoval(self.engine, allocator, &self.removal.?.removal, &retired_roots);
                    self.graph_release = active_graph.prepareReleaseClosure(HostSignalRecord, allocator, self.engine.active_signal_graph.items, retired_roots.items, replacement_roots.items) catch |err| switch (err) {
                        error.OutOfMemory => return error.OutOfMemory,
                        error.InvalidRelease => return error.InvalidSignalGraphRelease,
                    };
                    errdefer if (self.graph_release) |*release| release.deinit(allocator);
                    self.graph_append = active_graph.prepareGraphAppend(HostSignalRecord, allocator, self.engine.active_signal_graph.items, &self.graph_release.?, replacement_roots.items) catch |err| switch (err) {
                        error.OutOfMemory => return error.OutOfMemory,
                        error.InvalidAppend => return error.InvalidSignalGraphAppend,
                    };
                    errdefer if (self.graph_append) |*append| append.deinit(allocator);
                    self.selector_registry = try self.engine.prepareSelectorsForGraphChange(allocator, &self.graph_append.?);
                    errdefer if (self.selector_registry) |*registry| registry.deinit(allocator);
                    try self.engine.reserveActiveIntervals(self.host_ctx, self.graph_append.?.appendedIntervalSourceCount());
                    try self.engine.reserveActiveRowSources(self.host_ctx, self.graph_append.?.appendedRowSourceCount());
                    try self.prepareGraphRoutes(allocator);
                }
                try self.prepareRender(allocator);
            }

            /// Counts the host commands graph publication emits through the sink
            /// inside this transaction (interval starts for appended sources and
            /// cancellations for retired ones), so the wire reserves their records.
            fn commitSinkCommandCount(self: *const @This()) usize {
                var count: usize = 0;
                if (self.graph_append) |*append| count += append.appendedIntervalSourceCount();
                if (self.graph_release) |*release| count += release.retiredIntervalSourceCount();
                return count;
            }

            fn prepareRender(self: *@This(), allocator: std.mem.Allocator) CollectionError!void {
                if (!self.initial_root and !self.engine.render_cache.hasRoot()) return;
                // The sparse plan is torn down field by field on failure, not
                // through `deinit`, so every graph artifact prepared before the
                // render stage is released here, including the staged selector
                // memberships whose only other owner is the commit path.
                errdefer {
                    self.deinitGraphRoutes(allocator);
                    if (self.graph_append) |*append| append.deinit(allocator);
                    self.graph_append = null;
                    if (self.graph_release) |*release| release.deinit(allocator);
                    self.graph_release = null;
                    if (self.selector_registry) |*registry| registry.deinit(allocator);
                    self.selector_registry = null;
                    if (self.sink_edits) |*edits| edits.deinit(allocator);
                    self.sink_edits = null;
                }
                var facade = BranchReplacementPlan{
                    .engine = self.engine,
                    .host_ctx = self.host_ctx,
                    .roc_host = self.roc_host,
                    .replacement_stream = self.replacement.stream,
                    .collection = self.replacement.collection,
                    .removal = self.removal.?.removal,
                    .suppressed_render_parent_ids = self.suppressed_render_parent_ids,
                    .initial_root = self.initial_root,
                };
                self.render_splice = try facade.prepareRenderTopology(allocator);
                errdefer if (self.render_splice) |*splice| splice.deinit();
                self.render_splice.?.reserveSinkCommands(self.commitSinkCommandCount()) catch return error.ResourceLimit;
                self.render_batch_target = if (comptime @hasDecl(Ctx, "renderCommandBatch")) Ctx.renderCommandBatch(self.host_ctx) else &self.render_batch;
                errdefer if (self.render_batch_target == &self.render_batch) self.render_batch.deinit(allocator);
                self.render_splice.?.preflight(self.render_batch_target.?, allocator) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.ResourceLimit => return error.ResourceLimit,
                };
                self.publication_phase.markPreflighted();
                errdefer self.render_batch_target.?.abort();
                if (comptime @hasDecl(Ctx, "prepareRenderPublication")) {
                    self.host_render_publication = Ctx.prepareRenderPublication(self.host_ctx, &self.render_splice.?) catch |err| switch (err) {
                        error.OutOfMemory => return error.OutOfMemory,
                        error.ResourceLimit => return error.ResourceLimit,
                        error.InvalidRenderTopology => return error.InvalidRenderTopology,
                    };
                }
            }

            fn commitCollection(self: *@This()) void {
                self.replacement.collection.commit();
            }

            fn commitGraphAssumeCapacity(self: *@This()) void {
                self.sink_edits.?.apply(
                    &self.engine.active_text_signal_routes,
                    &self.engine.active_bool_signal_routes,
                    &self.engine.active_change_signal_routes,
                    &self.engine.active_structural_signal_routes,
                );
                const release = &self.graph_release.?;
                const append = &self.graph_append.?;
                release.applyAdjacency(self.engine.active_signal_graph.items);
                release.applyDense(
                    &self.engine.active_signal_graph,
                    &self.engine.active_source_signal_routes,
                    &self.engine.active_text_signal_routes,
                    &self.engine.active_bool_signal_routes,
                    &self.engine.active_change_signal_routes,
                    &self.engine.active_structural_signal_routes,
                );
                append.commitNodes(&self.engine.active_signal_graph);
                append.commitParallelRoutes(
                    &self.engine.active_text_signal_routes,
                    &self.engine.active_bool_signal_routes,
                    &self.engine.active_change_signal_routes,
                    &self.engine.active_structural_signal_routes,
                );
                self.source_route_appends.?.apply(&self.engine.active_source_signal_routes, self.graph_source_route_count);
                const graph_count = append.finalGraphCount();
                self.text_route_appends.?.apply(&self.engine.active_text_signal_routes, graph_count);
                self.bool_route_appends.?.apply(&self.engine.active_bool_signal_routes, graph_count);
                self.change_route_appends.?.apply(&self.engine.active_change_signal_routes, graph_count);
                self.structural_route_appends.?.apply(&self.engine.active_structural_signal_routes, graph_count);
                var lifecycle = ActiveSignalGraphLifecycle{ .engine = self.engine, .ctx = self.host_ctx };
                release.releaseRetired(Ctx.allocator(self.host_ctx), self.engine.active_signal_graph.items, &lifecycle);
                append.registerAppendedEffects(&lifecycle);
                self.engine.commitPreparedSelectors(Ctx.allocator(self.host_ctx), &self.selector_registry.?, append);
            }

            fn commitRenderAssumeCapacity(self: *@This()) void {
                const splice = &(self.render_splice orelse return);
                splice.stageAssumeCapacity(self.render_batch_target.?, Ctx.allocator(self.host_ctx)) catch @panic("prepared aggregate render batch violated preflight");
                splice.apply(&self.engine.render_cache);
                if (comptime @hasDecl(Ctx, "applyRenderPublication")) Ctx.applyRenderPublication(self.host_ctx, &self.host_render_publication.?);
            }

            fn publishRenderLast(self: *@This()) void {
                if (self.render_splice == null) return;
                self.render_batch_target.?.commit();
                self.publication_phase.markBatchPublished();
                if (comptime @hasDecl(Ctx, "publishRenderPublication")) {
                    Ctx.publishRenderPublication(self.host_ctx, &self.host_render_publication.?);
                    self.publication_phase.markHostPublished();
                }
            }

            fn commitAssumeCapacity(self: *@This()) void {
                self.commitAssumeCapacityWith({}, struct {
                    fn apply(_: void) void {}
                }.apply);
            }

            fn commitAssumeCapacityWith(self: *@This(), external: anytype, comptime commit_external: fn (@TypeOf(external)) void) void {
                self.commitAssumeCapacityWithEarlyAndLate({}, struct {
                    fn apply(_: void) void {}
                }.apply, external, commit_external);
            }

            fn commitAssumeCapacityWithEarlyAndLate(self: *@This(), early: anytype, comptime commit_early: fn (@TypeOf(early)) void, late: anytype, comptime commit_late: fn (@TypeOf(late)) void) void {
                self.commitRenderAssumeCapacity();
                commit_early(early);
                if (self.graph_release != null) self.commitGraphAssumeCapacity();

                const removal = &self.removal.?.removal;
                const indexes = &removal.descriptor_indexes;
                for (indexes.event_indexes.items) |index| self.retired_active_events.appendAssumeCapacity(self.engine.active_events.swapRemove(index));
                for (self.replacement.stream.events.items) |*desc| {
                    if (!desc.owns_handler) @panic("prepared replacement event did not own its active reducer");
                    self.engine.active_events.appendAssumeCapacity(.{
                        .payload_descriptor = desc.payload_descriptor,
                        .handler = desc.handler,
                    });
                    desc.owns_handler = false;
                }
                if (self.render_layout_plan) |*plan| {
                    plan.apply(&self.engine.active_stream, &self.replacement.stream);
                } else if (!self.initial_root and self.final_render_topology != null) {
                    @panic("structural downstream committed a render topology without re-basing its scope sites");
                }
                if (self.sparse_render_membership) {
                    for (self.render_splice.?.sparse_children.items) |*journal| {
                        if (journal.wireEdits().len != 0) self.engine.active_stream.render_nodes_ordered = false;
                    }
                    self.engine.active_stream.commitSparseRenderNodesAssumeCapacity(
                        &self.replacement.stream,
                        &self.retired_stream,
                        removal.scan.removed_elem_ids,
                    );
                    self.render_splice.?.applySparseChildrenToIndexedStream(
                        HostNodeDescriptorStream,
                        Ctx.allocator(self.host_ctx),
                        &self.engine.active_stream,
                    );
                    self.engine.active_stream.finishSparseRenderNodeRetirement(removal.scan.removed_elem_ids);
                }
                self.engine.active_stream.commitStaticDescriptorReplacementAssumeCapacity(
                    &self.replacement.stream,
                    &self.retired_stream,
                    indexes.element_indexes.items,
                    indexes.text_node_indexes.items,
                    indexes.static_text_attr_indexes.items,
                    indexes.static_bool_attr_indexes.items,
                    indexes.signal_text_node_indexes.items,
                    indexes.signal_text_attr_indexes.items,
                    indexes.signal_bool_attr_indexes.items,
                    indexes.event_indexes.items,
                    removal.node_indexes.scope_site_indexes.items,
                    removal.node_indexes.state_indexes.items,
                    removal.node_indexes.when_indexes.items,
                    removal.node_indexes.each_indexes.items,
                );
                self.engine.active_stream.commitCustomDescriptorReplacementAssumeCapacity(
                    &self.replacement.stream,
                    &self.retired_stream,
                    indexes.static_custom_text_attr_indexes.items,
                    indexes.signal_custom_text_attr_indexes.items,
                    indexes.signal_optional_custom_text_attr_indexes.items,
                    indexes.static_custom_bool_attr_indexes.items,
                    indexes.signal_custom_bool_attr_indexes.items,
                );
                self.engine.active_stream.commitLifecycleReplacementAssumeCapacity(
                    &self.replacement.stream,
                    &self.retired_stream,
                    removal.node_indexes.on_change_indexes.items,
                    removal.node_indexes.mount_indexes.items,
                    removal.node_indexes.cleanup_indexes.items,
                );
                if (self.initial_root) {
                    std.mem.swap(shared_buffer.List(HostRenderNode), &self.engine.active_stream.render_nodes, &self.replacement.stream.render_nodes);
                    std.mem.swap(std.AutoHashMapUnmanaged(u64, HostRenderElemIndex), &self.engine.active_stream.render_metadata_by_elem_id, &self.replacement.stream.render_metadata_by_elem_id);
                    self.engine.active_stream.render_nodes_ordered = true;
                } else if (!self.sparse_render_membership) if (self.final_render_topology) |*topology| topology.apply(&self.engine.active_stream);
                if (self.sparse_render_membership) {
                    for (self.publication.?.replacement_elem_ids) |raw| {
                        const index = self.engine.active_stream.renderNodeIndex(ids.ElemId.fromRaw(raw)) orelse @panic("published render node lost its index");
                        self.engine.validateRenderNodeDescriptorIntegrity(self.engine.active_stream.render_nodes.items[index]);
                    }
                } else self.engine.validateActiveRenderDescriptorIntegrity();

                self.state_retirement.?.apply(self.engine, &self.retired_state_cells);
                // Retire the old identity generation before publishing replacement
                // intents. A replacement may deliberately reuse an ID owned by the
                // retiring structure; applying retirement afterward would mark the
                // newly published identity inactive.
                self.identity_retirements.?.apply(self.engine);
                // Collection transitions retire their own stable rows first.
                // The central scope journal then removes any remaining stable
                // row whose owning subtree disappears without a collection
                // transition, before a replacement may reuse that scope.
                self.replacement.collection.commitRowsTransitionRemovalsEarly();
                if (self.row_retirement) |*row_retirement| {
                    if (self.engine.rows_store) |*store| for (row_retirement.rows) |row| {
                        const retired = store.retireScope(row.scope_id.raw()) orelse continue;
                        Ctx.allocator(self.host_ctx).free(retired.key);
                        if (!retired.site_empty) continue;
                        const mapped_site = self.engine.rows_site_ids.get(row.site_key) orelse @panic("retired empty Rows site lacked its construction identity");
                        if (mapped_site != retired.site_id) @panic("retired empty Rows site identity named another site");
                        if (!self.engine.rows_site_ids.remove(row.site_key)) unreachable;
                        if (self.engine.each_generation_ids_by_rows_site.fetchRemove(retired.site_id)) |generation_entry| {
                            const generation = self.engine.each_generations.fetchRemove(generation_entry.value) orelse @panic("retired Rows site generation was absent");
                            self.retired_stable_generations.appendAssumeCapacity(generation.value);
                        }
                        store.destroyEmptySite(retired.site_id) catch @panic("retired Rows site was not empty");
                    };
                }
                // Retire journaled rows before the collection publishes its
                // sites: a re-collected nested site takes over the slot its
                // predecessor held, which must be empty by then.
                if (self.row_retirement) |*row_retirement| {
                    var row_keys = EachRowScopeKeyLookup{ .engine = self.engine, .reconciled_sites = self.replacement.collection.nested_row_syncs.items };
                    row_retirement.applyRows(&self.engine.each_row_sites, &self.engine.each_row_memberships_by_scope_id, &row_keys);
                }
                // Row reverse indexes must be retired before the source can
                // publish a newly claimed reuse of the same scope. Scope
                // claims themselves still have to commit before replacement
                // collection scopes extend the committed scope table.
                commit_late(late);
                if (self.row_retirement) |*row_retirement| {
                    var row_keys = EachRowScopeKeyLookup{ .engine = self.engine, .reconciled_sites = self.replacement.collection.nested_row_syncs.items };
                    row_retirement.pruneSites(Ctx.allocator(self.host_ctx), &self.engine.each_row_sites, &self.engine.each_row_site_indexes, &self.engine.each_row_memberships_by_scope_id, &row_keys);
                }
                self.replacement.collection.commit();
                self.replacement.commitPositions();
                self.engine.commitPreparedScopeRetirement(Ctx.allocator(self.host_ctx), &self.targets.?.scope_retirement.?, &self.retired_scope_steps);
                self.engine.validateActiveScopeSiteInsertIndexes();

                self.publishRenderLast();
                // Cancellations and cleanup publication may call the host, so they
                // deliberately run only after the engine/cache/host publication is visible.
                self.effects_retirement.?.apply(self.engine, self.host_ctx);
            }

            fn deinit(self: *@This()) void {
                const allocator = Ctx.allocator(self.host_ctx);
                if (self.publication_phase.needsAbort() and self.render_batch_target != &self.render_batch) self.render_batch_target.?.abort();
                if (@hasDecl(Ctx, "RenderPublication")) if (self.host_render_publication) |*publication| publication.deinit();
                self.render_batch.deinit(allocator);
                if (self.render_splice) |*splice| splice.deinit();
                if (self.owns_replacement) self.replacement.deinit();
                if (self.removal) |*removal| removal.deinit(allocator);
                if (self.state_retirement) |*retirement| retirement.deinit(allocator);
                for (self.retired_state_cells.items) |*state| state.retire(self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics);
                self.retired_state_cells.deinit(allocator);
                if (self.row_retirement) |*retirement| retirement.deinit(allocator);
                for (self.retired_stable_generations.items) |generation| {
                    generation.deinit(allocator, self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics);
                    allocator.destroy(generation);
                }
                self.retired_stable_generations.deinit(allocator);
                if (self.effects_retirement) |*effects| effects.deinit(allocator, self.roc_host);
                for (self.retired_active_events.items) |event| self.engine.deinitActiveEventDesc(self.host_ctx, self.roc_host, event);
                self.retired_active_events.deinit(allocator);
                if (self.publication) |*publication| publication.deinit(allocator);
                if (self.final_render_topology) |*topology| topology.deinit();
                if (self.render_layout_plan) |*plan| plan.deinit();
                if (self.graph_append) |*append| append.deinit(allocator);
                if (self.graph_release) |*release| release.deinit(allocator);
                if (self.selector_registry) |*registry| registry.deinit(allocator);
                if (self.sink_edits) |*edits| edits.deinit(allocator);
                self.deinitGraphRoutes(allocator);
                self.retired_stream.deinit(allocator, self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics);
                if (self.identity_retirements) |*retirements| retirements.deinit(allocator);
                if (self.targets) |*targets| targets.deinit(allocator);
                for (self.retired_scope_steps.items) |*step| self.engine.releasePreparedRetiredScopeStep(step);
                self.retired_scope_steps.deinit(allocator);
                allocator.free(self.replacement_scope_ids);
                allocator.destroy(self);
            }

            fn prepareSinkEdits(self: *@This(), allocator: std.mem.Allocator) CollectionError!active_graph.PreparedSinkRouteEdits {
                var text: shared_buffer.List(active_graph.TextSinkEdit) = .empty;
                defer text.deinit(allocator);
                var bools: shared_buffer.List(active_graph.BoolSinkEdit) = .empty;
                defer bools.deinit(allocator);
                var structural: shared_buffer.List(active_graph.StructuralSinkEdit) = .empty;
                defer structural.deinit(allocator);
                var changes: shared_buffer.List(active_graph.ChangeSinkEdit) = .empty;
                defer changes.deinit(allocator);
                const removal = &self.removal.?.removal;
                const indexes = &removal.descriptor_indexes;
                var text_removals = std.math.add(usize, indexes.signal_text_node_indexes.items.len, indexes.signal_text_attr_indexes.items.len) catch return error.ResourceLimit;
                text_removals = std.math.add(usize, text_removals, indexes.signal_custom_text_attr_indexes.items.len) catch return error.ResourceLimit;
                text_removals = std.math.add(usize, text_removals, indexes.signal_optional_custom_text_attr_indexes.items.len) catch return error.ResourceLimit;
                const bool_removals = std.math.add(usize, indexes.signal_bool_attr_indexes.items.len, indexes.signal_custom_bool_attr_indexes.items.len) catch return error.ResourceLimit;
                const structural_removals = std.math.add(usize, removal.node_indexes.when_indexes.items.len, removal.node_indexes.each_indexes.items.len) catch return error.ResourceLimit;
                text.ensureTotalCapacity(allocator, std.math.mul(usize, 2, text_removals) catch return error.ResourceLimit) catch return error.OutOfMemory;
                bools.ensureTotalCapacity(allocator, std.math.mul(usize, 2, bool_removals) catch return error.ResourceLimit) catch return error.OutOfMemory;
                structural.ensureTotalCapacity(allocator, std.math.mul(usize, 2, structural_removals) catch return error.ResourceLimit) catch return error.OutOfMemory;
                changes.ensureTotalCapacity(allocator, std.math.mul(usize, 2, removal.node_indexes.on_change_indexes.items.len) catch return error.ResourceLimit) catch return error.OutOfMemory;
                try BranchReplacementPlan.appendTextSinkEdits(allocator, self.engine, &text, self.engine.active_stream.signal_text_nodes.items, indexes.signal_text_node_indexes.items, .text_node);
                try BranchReplacementPlan.appendTextSinkEdits(allocator, self.engine, &text, self.engine.active_stream.signal_text_attrs.items, indexes.signal_text_attr_indexes.items, .text_attr);
                try BranchReplacementPlan.appendTextSinkEdits(allocator, self.engine, &text, self.engine.active_stream.signal_custom_text_attrs.items, indexes.signal_custom_text_attr_indexes.items, .custom_text_attr);
                try BranchReplacementPlan.appendTextSinkEdits(allocator, self.engine, &text, self.engine.active_stream.signal_optional_custom_text_attrs.items, indexes.signal_optional_custom_text_attr_indexes.items, .custom_text_optional_attr);
                try BranchReplacementPlan.appendBoolSinkEdits(allocator, self.engine, &bools, self.engine.active_stream.signal_bool_attrs.items, indexes.signal_bool_attr_indexes.items, .bool_attr);
                try BranchReplacementPlan.appendBoolSinkEdits(allocator, self.engine, &bools, self.engine.active_stream.signal_custom_bool_attrs.items, indexes.signal_custom_bool_attr_indexes.items, .custom_bool_attr);
                try BranchReplacementPlan.appendChangeSinkEdits(allocator, self.engine, &changes, self.engine.active_stream.on_changes.items, removal.node_indexes.on_change_indexes.items);
                try BranchReplacementPlan.appendStructuralSinkEdits(allocator, self.engine, &structural, self.engine.active_stream.whens.items, removal.node_indexes.when_indexes.items, .when);
                try BranchReplacementPlan.appendStructuralSinkEdits(allocator, self.engine, &structural, self.engine.active_stream.eaches.items, removal.node_indexes.each_indexes.items, .each);
                return active_graph.prepareSinkRouteEdits(
                    allocator,
                    &self.engine.active_text_signal_routes,
                    &self.engine.active_bool_signal_routes,
                    &self.engine.active_change_signal_routes,
                    &self.engine.active_structural_signal_routes,
                    text.items,
                    bools.items,
                    changes.items,
                    structural.items,
                ) catch return error.OutOfMemory;
            }

            fn prepareGraphRoutes(self: *@This(), allocator: std.mem.Allocator) CollectionError!void {
                errdefer self.deinitGraphRoutes(allocator);
                const graph_plan = &self.graph_append.?;
                const graph_count = graph_plan.finalGraphCount();
                var source: shared_buffer.List(active_graph.RouteAppend(u64)) = .empty;
                defer source.deinit(allocator);
                var text: shared_buffer.List(active_graph.RouteAppend(active_graph.TextSink)) = .empty;
                defer text.deinit(allocator);
                var bools: shared_buffer.List(active_graph.RouteAppend(active_graph.BoolSink)) = .empty;
                defer bools.deinit(allocator);
                var changes: shared_buffer.List(active_graph.RouteAppend(active_graph.ChangeSink)) = .empty;
                defer changes.deinit(allocator);
                var structural: shared_buffer.List(active_graph.RouteAppend(active_graph.StructuralSink)) = .empty;
                defer structural.deinit(allocator);
                for (graph_plan.records, graph_plan.record_ids) |record, record_id| switch (record.payload) {
                    .ref => |source_node_id| source.append(allocator, .{ .route_index = source_node_id, .value = record_id }) catch return error.OutOfMemory,
                    else => {},
                };
                const removal = &self.removal.?.removal;
                const indexes = &removal.descriptor_indexes;
                const text_node_base = std.math.sub(usize, self.engine.active_stream.signal_text_nodes.items.len, indexes.signal_text_node_indexes.items.len) catch return error.ResourceLimit;
                for (self.replacement.stream.signal_text_nodes.items, 0..) |desc, offset| try self.appendTextRoute(allocator, &text, desc.signal.record, .{ .kind = .text_node, .index = text_node_base + offset });
                const text_attr_base = std.math.sub(usize, self.engine.active_stream.signal_text_attrs.items.len, indexes.signal_text_attr_indexes.items.len) catch return error.ResourceLimit;
                for (self.replacement.stream.signal_text_attrs.items, 0..) |desc, offset| try self.appendTextRoute(allocator, &text, desc.signal.record, .{ .kind = .text_attr, .index = text_attr_base + offset });
                const custom_text_base = std.math.sub(usize, self.engine.active_stream.signal_custom_text_attrs.items.len, indexes.signal_custom_text_attr_indexes.items.len) catch return error.ResourceLimit;
                for (self.replacement.stream.signal_custom_text_attrs.items, 0..) |desc, offset| try self.appendTextRoute(allocator, &text, desc.signal.record, .{ .kind = .custom_text_attr, .index = custom_text_base + offset });
                const optional_text_base = std.math.sub(usize, self.engine.active_stream.signal_optional_custom_text_attrs.items.len, indexes.signal_optional_custom_text_attr_indexes.items.len) catch return error.ResourceLimit;
                for (self.replacement.stream.signal_optional_custom_text_attrs.items, 0..) |desc, offset| try self.appendTextRoute(allocator, &text, desc.signal.record, .{ .kind = .custom_text_optional_attr, .index = optional_text_base + offset });
                const bool_attr_base = std.math.sub(usize, self.engine.active_stream.signal_bool_attrs.items.len, indexes.signal_bool_attr_indexes.items.len) catch return error.ResourceLimit;
                for (self.replacement.stream.signal_bool_attrs.items, 0..) |desc, offset| try self.appendBoolRoute(allocator, &bools, desc.signal.record, .{ .kind = .bool_attr, .index = bool_attr_base + offset });
                const custom_bool_base = std.math.sub(usize, self.engine.active_stream.signal_custom_bool_attrs.items.len, indexes.signal_custom_bool_attr_indexes.items.len) catch return error.ResourceLimit;
                for (self.replacement.stream.signal_custom_bool_attrs.items, 0..) |desc, offset| try self.appendBoolRoute(allocator, &bools, desc.signal.record, .{ .kind = .custom_bool_attr, .index = custom_bool_base + offset });
                const change_base = std.math.sub(usize, self.engine.active_stream.on_changes.items.len, removal.node_indexes.on_change_indexes.items.len) catch return error.ResourceLimit;
                for (self.replacement.stream.on_changes.items, 0..) |desc, offset| try self.appendChangeRoute(allocator, &changes, desc.signal.record, .{ .index = change_base + offset });
                const when_base = std.math.sub(usize, self.engine.active_stream.whens.items.len, removal.node_indexes.when_indexes.items.len) catch return error.ResourceLimit;
                for (self.replacement.stream.whens.items, 0..) |desc, offset| try self.appendStructuralRoute(allocator, &structural, desc.condition.record, .{ .kind = .when, .index = when_base + offset });
                const each_base = std.math.sub(usize, self.engine.active_stream.eaches.items.len, removal.node_indexes.each_indexes.items.len) catch return error.ResourceLimit;
                for (self.replacement.stream.eaches.items, 0..) |desc, offset| try self.appendStructuralRoute(allocator, &structural, desc.items.record, .{ .kind = .each, .index = each_base + offset });
                var source_count = self.engine.active_source_signal_routes.items.len;
                for (source.items) |entry| source_count = @max(source_count, std.math.add(usize, @intCast(entry.route_index), 1) catch return error.ResourceLimit);
                self.graph_source_route_count = source_count;
                self.source_route_appends = active_graph.prepareSourceRouteAppendsAfterRelease(allocator, &self.engine.active_source_signal_routes, &self.graph_release.?.remap, source_count, source.items) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.InvalidAppend => return error.InvalidSignalGraphAppend,
                };
                self.text_route_appends = active_graph.prepareRouteAppendsAfterRelease(active_graph.TextSink, allocator, &self.engine.active_text_signal_routes, &self.graph_release.?.remap, graph_count, text.items) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.InvalidAppend => return error.InvalidSignalGraphAppend,
                };
                self.bool_route_appends = active_graph.prepareRouteAppendsAfterRelease(active_graph.BoolSink, allocator, &self.engine.active_bool_signal_routes, &self.graph_release.?.remap, graph_count, bools.items) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.InvalidAppend => return error.InvalidSignalGraphAppend,
                };
                self.change_route_appends = active_graph.prepareRouteAppendsAfterRelease(active_graph.ChangeSink, allocator, &self.engine.active_change_signal_routes, &self.graph_release.?.remap, graph_count, changes.items) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.InvalidAppend => return error.InvalidSignalGraphAppend,
                };
                self.structural_route_appends = active_graph.prepareRouteAppendsAfterRelease(active_graph.StructuralSink, allocator, &self.engine.active_structural_signal_routes, &self.graph_release.?.remap, graph_count, structural.items) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.InvalidAppend => return error.InvalidSignalGraphAppend,
                };
                graph_plan.reservePublication(allocator, &self.engine.active_signal_graph) catch return error.OutOfMemory;
                graph_plan.reserveParallelRoutes(allocator, &self.engine.active_text_signal_routes, &self.engine.active_bool_signal_routes, &self.engine.active_change_signal_routes, &self.engine.active_structural_signal_routes) catch return error.OutOfMemory;
                try self.source_route_appends.?.reserveOuter(allocator, &self.engine.active_source_signal_routes, source_count);
            }

            fn appendTextRoute(self: *@This(), allocator: std.mem.Allocator, routes: *shared_buffer.List(active_graph.RouteAppend(active_graph.TextSink)), record: *HostSignalRecord, sink: active_graph.TextSink) CollectionError!void {
                const id = self.graph_append.?.plannedRecordId(&self.graph_release.?.remap, self.engine.active_signal_graph.items, record) orelse return error.InvalidSignalGraphAppend;
                routes.append(allocator, .{ .route_index = id, .value = sink }) catch return error.OutOfMemory;
            }
            fn appendBoolRoute(self: *@This(), allocator: std.mem.Allocator, routes: *shared_buffer.List(active_graph.RouteAppend(active_graph.BoolSink)), record: *HostSignalRecord, sink: active_graph.BoolSink) CollectionError!void {
                const id = self.graph_append.?.plannedRecordId(&self.graph_release.?.remap, self.engine.active_signal_graph.items, record) orelse return error.InvalidSignalGraphAppend;
                routes.append(allocator, .{ .route_index = id, .value = sink }) catch return error.OutOfMemory;
            }
            fn appendChangeRoute(self: *@This(), allocator: std.mem.Allocator, routes: *shared_buffer.List(active_graph.RouteAppend(active_graph.ChangeSink)), record: *HostSignalRecord, sink: active_graph.ChangeSink) CollectionError!void {
                const id = self.graph_append.?.plannedRecordId(&self.graph_release.?.remap, self.engine.active_signal_graph.items, record) orelse return error.InvalidSignalGraphAppend;
                routes.append(allocator, .{ .route_index = id, .value = sink }) catch return error.OutOfMemory;
            }
            fn appendStructuralRoute(self: *@This(), allocator: std.mem.Allocator, routes: *shared_buffer.List(active_graph.RouteAppend(active_graph.StructuralSink)), record: *HostSignalRecord, sink: active_graph.StructuralSink) CollectionError!void {
                const id = self.graph_append.?.plannedRecordId(&self.graph_release.?.remap, self.engine.active_signal_graph.items, record) orelse return error.InvalidSignalGraphAppend;
                routes.append(allocator, .{ .route_index = id, .value = sink }) catch return error.OutOfMemory;
            }
            fn deinitGraphRoutes(self: *@This(), allocator: std.mem.Allocator) void {
                if (self.source_route_appends) |*routes| routes.deinit(allocator);
                if (self.text_route_appends) |*routes| routes.deinit(allocator);
                if (self.bool_route_appends) |*routes| routes.deinit(allocator);
                if (self.change_route_appends) |*routes| routes.deinit(allocator);
                if (self.structural_route_appends) |*routes| routes.deinit(allocator);
                self.source_route_appends = null;
                self.text_route_appends = null;
                self.bool_route_appends = null;
                self.change_route_appends = null;
                self.structural_route_appends = null;
            }
        };

        /// Owns every fallible downstream artifact for publishing a prepared
        /// root into an empty engine. The plan preflights graph/routes, active
        /// events, render cache, command storage, and any host shadow before an
        /// allocation-free commit makes one generation visible.
        pub const PreparedRootDownstream = struct {
            root: *PreparedRootCollection,
            downstream: *PreparedStructuralDownstream,
            phase: CommitPhase = .prepared,

            /// Completes initial-root preparation without changing logical
            /// engine, render-cache, command, or host-visible DOM state.
            pub fn prepare(root: *PreparedRootCollection) CollectionError!*@This() {
                const owner = root.owner;
                const allocator = Ctx.allocator(owner.host_ctx);
                const plan = allocator.create(@This()) catch return error.OutOfMemory;
                errdefer allocator.destroy(plan);
                const downstream = try PreparedStructuralDownstream.prepareInitialRoot(owner.engine, owner.host_ctx, owner.roc_host, owner);
                errdefer downstream.deinit();
                plan.* = .{ .root = root, .downstream = downstream };
                return plan;
            }

            /// Publishes all prepared engine and host state without allocating.
            /// Lifecycle callbacks are deliberately separate because their Roc
            /// call frame is a fatal allocator boundary.
            pub fn commit(self: *@This()) void {
                if (self.phase.isCommitted()) @panic("prepared root downstream committed twice");
                self.downstream.commitAssumeCapacity();
                self.phase.markCommitted();
            }

            /// Runs initial-aware and mount lifecycle callbacks only after the
            /// root generation is fully committed. Allocation failure inside
            /// either callback is contained by the platform allocator.
            pub fn runLifecycle(self: *@This()) render.Counts {
                if (!self.phase.isCommitted()) @panic("prepared root lifecycle ran before publication");
                var counts = self.downstream.engine.runActiveOnChangeInitialCommandIndices(
                    self.downstream.host_ctx,
                    self.downstream.roc_host,
                    self.downstream.publication.?.replacement_on_change_indices,
                );
                counts.addAll(self.downstream.engine.runActiveMountCommandIndices(
                    self.downstream.host_ctx,
                    self.downstream.roc_host,
                    self.downstream.publication.?.replacement_mount_indices,
                ));
                return counts;
            }

            /// Releases provisional ownership after abort or retired plan
            /// storage after commit.
            pub fn deinit(self: *@This()) void {
                const allocator = Ctx.allocator(self.root.owner.host_ctx);
                self.downstream.deinit();
                self.root.deinit();
                allocator.destroy(self);
            }
        };

        const AggregateBranchCollection = PreparedStructuralDownstream;

        const BranchReplacementPlan = struct {
            const HostRenderPublication = if (@hasDecl(Ctx, "RenderPublication")) Ctx.RenderPublication else void;
            engine: *Self,
            host_ctx: Ctx.Handle,
            roc_host: *abi.RocHost,
            replacement_stream: HostNodeDescriptorStream = .{},
            retired_stream: HostRetiredDescriptors = .{},
            collection: StagedCollectionCtx = undefined,
            replacement_scope_id: u64 = 0,
            retired_scope_id: u64 = 0,
            target_scopes: []bool = &.{},
            removal: ?structural_splice.PreparedRemoval = null,
            publication: ?structural_splice.PreparedPublicationDeltas = null,
            scope_retirement: ?scope_runtime.PreparedSubtreeRetirement = null,
            retired_state_cells: shared_buffer.List(HostState) = .empty,
            state_cell_indexes: []usize = &.{},
            retired_node_identity_ids: []u64 = &.{},
            retired_dom_identity_ids: []u64 = &.{},
            row_retirement: ?each_runtime.PreparedRowRemovals = null,
            effects_retirement: ?PreparedEffectRetirements = null,
            retired_scope_steps: shared_buffer.List(HostScopeStep) = .empty,
            sink_edits: ?active_graph.PreparedSinkRouteEdits = null,
            graph_release: ?active_graph.PreparedReleaseClosure(HostSignalRecord) = null,
            graph_append: ?active_graph.PreparedGraphAppend(HostSignalRecord) = null,
            selector_registry: ?PreparedSelectorAppend = null,
            source_route_appends: ?active_graph.PreparedRouteAppends(u64) = null,
            text_route_appends: ?active_graph.PreparedRouteAppends(active_graph.TextSink) = null,
            bool_route_appends: ?active_graph.PreparedRouteAppends(active_graph.BoolSink) = null,
            change_route_appends: ?active_graph.PreparedRouteAppends(active_graph.ChangeSink) = null,
            structural_route_appends: ?active_graph.PreparedRouteAppends(active_graph.StructuralSink) = null,
            graph_source_route_count: usize = 0,
            render_splice: ?render_cache_mod.PreparedRenderSplice(Ctx) = null,
            render_batch: render.TransactionalBatch = .{},
            render_batch_target: ?*render.TransactionalBatch = null,
            publication_phase: PublicationPhase = .unprepared,
            host_render_publication: ?HostRenderPublication = null,
            /// Render parents the owning plan registers itself; see
            /// `PreparedStructuralDownstream.suppressed_render_parent_ids`.
            suppressed_render_parent_ids: []const u64 = &.{},
            initial_root: bool = false,

            /// Reports whether the owning plan publishes this render parent's
            /// final child order itself. Such a parent must be left out of the
            /// structural pass: registering the same parent twice on one splice
            /// records a duplicate parent intent rather than a second edit.
            fn isSuppressedRenderParent(self: *const @This(), parent_id: u64) bool {
                for (self.suppressed_render_parent_ids) |suppressed| if (suppressed == parent_id) return true;
                return false;
            }

            fn stateIndexDescending(_: void, left: usize, right: usize) bool {
                return left > right;
            }

            fn prepare(engine_ptr: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, site: HostNodeScopeSiteDesc, when: HostNodeWhenDesc, selected_branch: HostScopeBranch, limits: collection_budget.Limits, dirty_source_node_ids: []const u64) CollectionError!*@This() {
                if (site.kind != .when or site.node_id != when.node_id) return error.InvalidDescriptor;
                const retired_scope_id = (engine_ptr.activeWhenBranchScopeId(site.scope_id, site.ordinal, selected_branch.opposite()) catch |err| return scopeError(err)) orelse return error.InvalidScope;
                if ((engine_ptr.activeWhenBranchScopeId(site.scope_id, site.ordinal, selected_branch) catch |err| return scopeError(err)) != null) return error.InvalidScope;

                const cached = switch (when.cached_value) {
                    .absent => return error.InvalidDescriptor,
                    .present => |cell| cell,
                };
                const selected_elem = engine_ptr.buildWhenElem(ctx, roc_host, when.ops, cached.value, cached.cap);
                defer selected_elem.decref(roc_host);
                const expected = try countStaticRootNodes(selected_elem);
                const allocator = Ctx.allocator(ctx);
                const plan = allocator.create(@This()) catch return error.OutOfMemory;
                errdefer allocator.destroy(plan);
                plan.* = .{ .engine = engine_ptr, .host_ctx = ctx, .roc_host = roc_host, .retired_scope_id = retired_scope_id.raw() };
                errdefer plan.replacement_stream.deinit(allocator, ctx, roc_host, &engine_ptr.pending_roc_metrics);
                errdefer plan.retired_stream.deinit(allocator, ctx, roc_host, &engine_ptr.pending_roc_metrics);
                plan.collection = try StagedCollectionCtx.init(engine_ptr, ctx, &plan.replacement_stream, limits, expected, 1);
                errdefer plan.collection.deinit();

                const branch_scope = try plan.collection.reserveWhenBranchScope(site.scope_id, site.ordinal, selected_branch);
                if (!branch_scope.created) return error.ResourceLimit;
                plan.replacement_scope_id = branch_scope.scope_id.raw();
                var binder_stack: shared_buffer.List(HostBinderBinding) = .empty;
                defer binder_stack.deinit(allocator);
                const binder_capacity = std.math.add(usize, site.binder_bindings.len, expected.state_sites) catch return error.ResourceLimit;
                binder_stack.ensureTotalCapacity(allocator, binder_capacity) catch return error.OutOfMemory;
                binder_stack.appendSliceAssumeCapacity(site.binder_bindings);
                var ordinal = ids.SiteOrdinal.fromRaw(0);
                var dom_ordinal = ids.SiteOrdinal.fromRaw(0);
                try engine_ptr.collectActiveElemDescriptorsWith(*StagedCollectionCtx, &plan.collection, ctx, roc_host, &plan.replacement_stream, selected_elem, branch_scope.scope_id, site.parent_elem_id, &ordinal, &dom_ordinal, &binder_stack, true, dirty_source_node_ids);
                plan.collection.materializeStream();
                try engine_ptr.active_stream.reserveMovedStreamPublication(allocator, &plan.replacement_stream);

                plan.target_scopes = allocator.alloc(bool, engine_ptr.scopes.items.len) catch return error.OutOfMemory;
                errdefer allocator.free(plan.target_scopes);
                for (engine_ptr.scopes.items, 0..) |scope, index| {
                    plan.target_scopes[index] = engine_ptr.scopeIsInReplacementTarget(scope.scope_id.raw(), .{ .scope = retired_scope_id.raw() });
                }
                plan.scope_retirement = scope_runtime.prepareSubtreeRetirement(HostEachRowScopeStep, allocator, engine_ptr.scopes.items, retired_scope_id) catch return error.OutOfMemory;
                errdefer if (plan.scope_retirement) |*retirement| retirement.deinit(allocator);
                const identity_retirements = try PreparedIdentityRetirements.prepare(engine_ptr, allocator, plan.target_scopes);
                plan.retired_node_identity_ids = identity_retirements.node_ids;
                errdefer allocator.free(plan.retired_node_identity_ids);
                plan.retired_dom_identity_ids = identity_retirements.dom_ids;
                errdefer allocator.free(plan.retired_dom_identity_ids);
                plan.row_retirement = try prepareRowRetirementForScopes(engine_ptr, allocator, plan.scope_retirement.?.scope_ids);
                errdefer if (plan.row_retirement) |*retirement| retirement.deinit(allocator);
                plan.retired_scope_steps.ensureUnusedCapacity(allocator, plan.scope_retirement.?.scope_ids.len) catch return error.OutOfMemory;
                errdefer plan.retired_scope_steps.deinit(allocator);
                const render_start = engine_ptr.renderStartForReplacementTargetSet(site.render_insert_index, plan.target_scopes);
                plan.removal = try structural_splice.prepareRemoval(HostNodeDescriptorStream, allocator, &engine_ptr.active_stream, render_start, plan.target_scopes);
                errdefer if (plan.removal) |*removal| removal.deinit(allocator);
                plan.effects_retirement = try PreparedEffectRetirements.prepare(engine_ptr, allocator, plan.removal.?.node_indexes.cleanup_indexes.items);
                errdefer if (plan.effects_retirement) |*effects| effects.deinit(allocator, null);
                const state_retirement = try PreparedStateRetirementIndexes.prepare(engine_ptr, allocator, plan.removal.?.node_indexes.state_indexes.items);
                plan.state_cell_indexes = state_retirement.indexes_descending;
                errdefer allocator.free(plan.state_cell_indexes);
                try state_retirement.reserveRetired(allocator, &plan.retired_state_cells);
                errdefer plan.retired_state_cells.deinit(allocator);
                try prepareRetiredStreamCapacity(allocator, &plan.retired_stream, &plan.removal.?);
                const on_change_base = std.math.sub(usize, engine_ptr.active_stream.on_changes.items.len, plan.removal.?.node_indexes.on_change_indexes.items.len) catch return error.ResourceLimit;
                const mount_base = std.math.sub(usize, engine_ptr.active_stream.mounts.items.len, plan.removal.?.node_indexes.mount_indexes.items.len) catch return error.ResourceLimit;
                plan.publication = structural_splice.preparePublicationDeltas(
                    allocator,
                    plan.replacement_stream.render_nodes.items,
                    &.{},
                    on_change_base,
                    plan.replacement_stream.on_changes.items.len,
                    mount_base,
                    plan.replacement_stream.mounts.items.len,
                ) catch return error.OutOfMemory;
                errdefer if (plan.publication) |*publication| publication.deinit(allocator);
                try plan.prepareGraphAndRender(allocator);
                return plan;
            }

            fn prepareGraphAndRender(self: *@This(), allocator: std.mem.Allocator) CollectionError!void {
                errdefer {
                    if (self.publication_phase.needsAbort()) self.render_batch_target.?.abort();
                    if (@hasDecl(Ctx, "RenderPublication")) if (self.host_render_publication) |*publication| publication.deinit();
                    self.render_batch.deinit(allocator);
                    if (self.render_splice) |*splice| splice.deinit();
                    self.deinitGraphRoutes(allocator);
                    if (self.graph_append) |*append| append.deinit(allocator);
                    if (self.graph_release) |*release| release.deinit(allocator);
                    if (self.selector_registry) |*registry| registry.deinit(allocator);
                    if (self.sink_edits) |*edits| edits.deinit(allocator);
                }
                if (self.engine.active_signal_graph.items.len != 0) {
                    self.sink_edits = try self.prepareSinkEdits(allocator);
                    var retired_roots: shared_buffer.List(*HostSignalRecord) = .empty;
                    defer retired_roots.deinit(allocator);
                    try self.collectRetiredGraphRoots(allocator, &retired_roots);
                    var replacement_roots: shared_buffer.List(*HostSignalRecord) = .empty;
                    defer replacement_roots.deinit(allocator);
                    try self.collectReplacementGraphRoots(allocator, &replacement_roots);
                    self.graph_release = active_graph.prepareReleaseClosure(HostSignalRecord, allocator, self.engine.active_signal_graph.items, retired_roots.items, replacement_roots.items) catch |err| switch (err) {
                        error.OutOfMemory => return error.OutOfMemory,
                        error.InvalidRelease => return error.InvalidSignalGraphRelease,
                    };
                    self.graph_append = active_graph.prepareGraphAppend(HostSignalRecord, allocator, self.engine.active_signal_graph.items, &self.graph_release.?, replacement_roots.items) catch |err| switch (err) {
                        error.OutOfMemory => return error.OutOfMemory,
                        error.InvalidAppend => return error.InvalidSignalGraphAppend,
                    };
                    self.selector_registry = try self.engine.prepareSelectorsForGraphChange(allocator, &self.graph_append.?);
                    try self.engine.reserveActiveIntervals(self.host_ctx, self.graph_append.?.appendedIntervalSourceCount());
                    try self.engine.reserveActiveRowSources(self.host_ctx, self.graph_append.?.appendedRowSourceCount());
                    try self.prepareGraphRoutes(allocator);
                }
                if (self.engine.render_cache.hasRoot()) {
                    self.render_splice = try self.prepareRenderTopology(allocator);
                    var sink_commands: usize = 0;
                    if (self.graph_append) |*append| sink_commands += append.appendedIntervalSourceCount();
                    if (self.graph_release) |*release| sink_commands += release.retiredIntervalSourceCount();
                    self.render_splice.?.reserveSinkCommands(sink_commands) catch return error.ResourceLimit;
                    self.render_batch_target = if (comptime @hasDecl(Ctx, "renderCommandBatch")) Ctx.renderCommandBatch(self.host_ctx) else &self.render_batch;
                    self.render_splice.?.preflight(self.render_batch_target.?, allocator) catch |err| switch (err) {
                        error.OutOfMemory => return error.OutOfMemory,
                        error.ResourceLimit => return error.ResourceLimit,
                    };
                    self.publication_phase.markPreflighted();
                    if (comptime @hasDecl(Ctx, "prepareRenderPublication")) {
                        self.host_render_publication = Ctx.prepareRenderPublication(self.host_ctx, &self.render_splice.?) catch |err| switch (err) {
                            error.OutOfMemory => return error.OutOfMemory,
                            error.ResourceLimit => return error.ResourceLimit,
                            error.InvalidRenderTopology => return error.InvalidRenderTopology,
                        };
                    }
                }
            }

            /// Decides which retired render nodes the host keeps. The wire
            /// removes whole subtrees, so a retired node survives in the host
            /// only when a replacement claims its id under its active tag
            /// (reuse in place) and its active parent survives too; a node
            /// re-collected under a destroyed parent is created afresh.
            const HostSurvival = struct {
                cache: *const render_cache_mod.Cache(Ctx),
                retired: *const std.AutoHashMapUnmanaged(u64, void),
                replacements: *const std.AutoHashMapUnmanaged(u64, render.NodeShape),
                memo: std.AutoHashMapUnmanaged(u64, bool) = .empty,

                fn activeNode(self: *const @This(), elem_id: u64) ?*const render_cache_mod.ScalarNode {
                    const index = std.math.cast(usize, elem_id) orelse return null;
                    if (index >= self.cache.nodes.items.len or !self.cache.nodes.items[index].isActive()) return null;
                    return &self.cache.nodes.items[index];
                }

                /// True when the host still holds this node after the splice.
                fn survives(self: *@This(), elem_id: u64) bool {
                    if (!self.retired.contains(elem_id)) return true;
                    if (self.memo.get(elem_id)) |known| return known;
                    var kept = false;
                    if (self.replacements.get(elem_id)) |shape| if (self.activeNode(elem_id)) |node| if (node.activeShape().?.eql(shape)) {
                        kept = if (node.parent_id) |parent| self.survives(parent.raw()) else true;
                    };
                    self.memo.putAssumeCapacity(elem_id, kept);
                    return kept;
                }

                /// Retired node whose parent survives is a host removal root;
                /// one under another destroyed node is released with it.
                fn removalPublication(self: *@This(), elem_id: u64) render_cache_mod.RemovalPublication {
                    if (self.survives(elem_id)) return .under_removed_root;
                    const node = self.activeNode(elem_id) orelse return .subtree_root;
                    const parent = node.parent_id orelse return .subtree_root;
                    return if (self.survives(parent.raw())) .subtree_root else .under_removed_root;
                }
            };

            fn prepareRenderTopology(self: *@This(), allocator: std.mem.Allocator) CollectionError!render_cache_mod.PreparedRenderSplice(Ctx) {
                var retired: std.AutoHashMapUnmanaged(u64, void) = .empty;
                defer retired.deinit(allocator);
                const retired_count = std.math.cast(u32, self.removal.?.scan.removed_elem_ids.len) orelse return error.ResourceLimit;
                retired.ensureUnusedCapacity(allocator, retired_count) catch return error.OutOfMemory;
                for (self.removal.?.scan.removed_elem_ids) |elem_id| retired.putAssumeCapacity(elem_id, {});
                var replacements: std.AutoHashMapUnmanaged(u64, render.NodeShape) = .empty;
                defer replacements.deinit(allocator);
                replacements.ensureUnusedCapacity(allocator, std.math.cast(u32, self.replacement_stream.render_nodes.items.len) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                for (self.replacement_stream.render_nodes.items) |node| {
                    const result = replacements.getOrPutAssumeCapacity(node.elem_id.raw());
                    if (result.found_existing) return error.ResourceLimit;
                    result.value_ptr.* = descriptor_stream.renderNodeShape(HostNodeDescriptorStream, &self.replacement_stream, node);
                }
                var survival = HostSurvival{ .cache = &self.engine.render_cache, .retired = &retired, .replacements = &replacements };
                defer survival.memo.deinit(allocator);
                survival.memo.ensureUnusedCapacity(allocator, retired_count) catch return error.OutOfMemory;
                var host_removal_count: usize = 0;
                for (self.removal.?.scan.removed_elem_ids) |elem_id| host_removal_count += @intFromBool(survival.removalPublication(elem_id) == .subtree_root);

                var touched: std.AutoHashMapUnmanaged(u64, void) = .empty;
                defer touched.deinit(allocator);
                const touched_bound = std.math.add(usize, self.removal.?.scan.touched_parent_ids.len, self.replacement_stream.render_nodes.items.len) catch return error.ResourceLimit;
                touched.ensureUnusedCapacity(allocator, std.math.cast(u32, touched_bound) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                for (self.removal.?.scan.touched_parent_ids) |parent_id| {
                    if (self.isSuppressedRenderParent(parent_id)) continue;
                    if (!retired.contains(parent_id) or replacements.contains(parent_id)) touched.putAssumeCapacity(parent_id, {});
                }
                var max_elem_id: u64 = 0;
                for (self.replacement_stream.render_nodes.items) |node| {
                    max_elem_id = @max(max_elem_id, node.elem_id.raw());
                    const parent_id = descriptor_stream.renderNodeParentElemId(HostNodeDescriptorStream, &self.replacement_stream, node);
                    if (!self.isSuppressedRenderParent(parent_id.raw())) touched.putAssumeCapacity(parent_id.raw(), {});
                }

                var event_reindex = try @import("descriptor_reindex.zig").Plan.prepare(allocator, self.engine.active_stream.events.items.len, self.removal.?.descriptor_indexes.event_indexes.items);
                defer event_reindex.deinit();
                var moved_fixed_event_count: usize = 0;
                var moved_named_elem_ids = std.AutoHashMapUnmanaged(u64, void).empty;
                defer moved_named_elem_ids.deinit(allocator);
                moved_named_elem_ids.ensureTotalCapacity(allocator, std.math.cast(u32, event_reindex.moves.len) orelse return error.ResourceLimit) catch return error.OutOfMemory;
                for (event_reindex.moves) |move| {
                    const desc = self.engine.active_stream.events.items[move.original];
                    if (desc.fixedKind() != null) {
                        moved_fixed_event_count = std.math.add(usize, moved_fixed_event_count, 1) catch return error.ResourceLimit;
                    } else moved_named_elem_ids.putAssumeCapacity(desc.elem_id.raw(), {});
                }

                var final_child_count: usize = 0;
                var old_child_count: usize = 0;
                var iterator = touched.keyIterator();
                while (iterator.next()) |parent_id| {
                    const parent_index = std.math.cast(usize, parent_id.*) orelse return error.ResourceLimit;
                    if (parent_index < self.engine.render_cache.nodes.items.len and self.engine.render_cache.nodes.items[parent_index].isActive()) {
                        old_child_count = std.math.add(usize, old_child_count, self.engine.render_cache.nodes.items[parent_index].children.items.len) catch return error.ResourceLimit;
                        for (self.engine.render_cache.nodes.items[parent_index].children.items) |child_id| if (!retired.contains(child_id.raw())) {
                            final_child_count = std.math.add(usize, final_child_count, 1) catch return error.ResourceLimit;
                        };
                    }
                    var replacement_child = self.replacement_stream.firstRenderChild(ids.ElemId.fromRaw(parent_id.*));
                    while (replacement_child) |child_id| {
                        final_child_count = std.math.add(usize, final_child_count, 1) catch return error.ResourceLimit;
                        replacement_child = self.replacement_stream.nextRenderSibling(child_id);
                    }
                }
                // A replacement node that claims an active id under the same
                // tag stays in place: the host sees scalar diffs instead of a
                // remove/recreate pair. Reserve the clears such a node may
                // need for fields its old subtree set and the new one dropped.
                var reuse_count: usize = 0;
                for (self.replacement_stream.render_nodes.items) |node| {
                    const index = node.elem_id.index();
                    if (index >= self.engine.render_cache.nodes.items.len or !self.engine.render_cache.nodes.items[index].isActive()) continue;
                    if (!retired.contains(node.elem_id.raw())) return error.InvalidRenderTopology;
                    if (survival.survives(node.elem_id.raw())) reuse_count = std.math.add(usize, reuse_count, 1) catch return error.ResourceLimit;
                }
                const reuse_clears = std.math.mul(usize, reuse_count, render_cache_mod.reused_node_max_clears) catch return error.ResourceLimit;
                var wire_commands = std.math.add(usize, host_removal_count, self.replacement_stream.render_nodes.items.len) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, @intFromBool(self.initial_root)) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, reuse_clears) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, final_child_count) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, self.replacement_stream.text_nodes.items.len) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, self.replacement_stream.static_text_attrs.items.len) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, self.replacement_stream.static_bool_attrs.items.len) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, self.replacement_stream.signal_text_nodes.items.len) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, self.replacement_stream.signal_text_attrs.items.len) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, self.replacement_stream.signal_bool_attrs.items.len) catch return error.ResourceLimit;
                var element_count: usize = 0;
                var old_custom_count: usize = 0;
                var old_named_event_count: usize = 0;
                for (self.replacement_stream.render_nodes.items) |node| if (node.kind == .element) {
                    element_count = std.math.add(usize, element_count, 1) catch return error.ResourceLimit;
                    const index = node.elem_id.index();
                    if (index < self.engine.render_cache.nodes.items.len and self.engine.render_cache.nodes.items[index].isActive()) {
                        old_custom_count = std.math.add(usize, old_custom_count, self.engine.render_cache.nodes.items[index].custom_text_attrs.items.len) catch return error.ResourceLimit;
                        old_named_event_count = std.math.add(usize, old_named_event_count, self.engine.render_cache.nodes.items[index].named_events.items.len) catch return error.ResourceLimit;
                    }
                };
                var moved_old_named_event_count: usize = 0;
                var moved_named_capacity_iterator = moved_named_elem_ids.keyIterator();
                while (moved_named_capacity_iterator.next()) |elem_id| {
                    if (replacements.contains(elem_id.*)) continue;
                    const index = std.math.cast(usize, elem_id.*) orelse return error.ResourceLimit;
                    if (index < self.engine.render_cache.nodes.items.len and self.engine.render_cache.nodes.items[index].isActive()) {
                        moved_old_named_event_count = std.math.add(usize, moved_old_named_event_count, self.engine.render_cache.nodes.items[index].named_events.items.len) catch return error.ResourceLimit;
                    }
                }
                const custom_attr_wire_edits = std.math.add(usize, old_custom_count, std.math.add(usize, std.math.add(usize, self.replacement_stream.static_custom_text_attrs.items.len, self.replacement_stream.static_custom_bool_attrs.items.len) catch return error.ResourceLimit, std.math.add(usize, self.replacement_stream.signal_custom_text_attrs.items.len, std.math.add(usize, self.replacement_stream.signal_optional_custom_text_attrs.items.len, self.replacement_stream.signal_custom_bool_attrs.items.len) catch return error.ResourceLimit) catch return error.ResourceLimit) catch return error.ResourceLimit) catch return error.ResourceLimit;
                var next_named_event_count: usize = 0;
                for (self.replacement_stream.events.items) |event| next_named_event_count = std.math.add(usize, next_named_event_count, @intFromBool(event.fixedKind() == null)) catch return error.ResourceLimit;
                var moved_named_count: usize = 0;
                var moved_named_counts = moved_named_elem_ids.keyIterator();
                while (moved_named_counts.next()) |elem_id| {
                    for (self.engine.active_stream.namedEventIndices(ids.ElemId.fromRaw(elem_id.*))) |original| {
                        if (event_reindex.finalIndex(original) != null) moved_named_count = std.math.add(usize, moved_named_count, 1) catch return error.ResourceLimit;
                    }
                }
                next_named_event_count = std.math.add(usize, next_named_event_count, moved_named_count) catch return error.ResourceLimit;
                const named_event_wire_edits = std.math.add(usize, std.math.add(usize, old_named_event_count, moved_old_named_event_count) catch return error.ResourceLimit, next_named_event_count) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, old_custom_count) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, self.replacement_stream.static_custom_text_attrs.items.len) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, self.replacement_stream.static_custom_bool_attrs.items.len) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, self.replacement_stream.signal_custom_text_attrs.items.len) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, self.replacement_stream.signal_optional_custom_text_attrs.items.len) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, self.replacement_stream.signal_custom_bool_attrs.items.len) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, self.replacement_stream.events.items.len) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, old_named_event_count) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, moved_old_named_event_count) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, moved_fixed_event_count) catch return error.ResourceLimit;
                wire_commands = std.math.add(usize, wire_commands, moved_named_count) catch return error.ResourceLimit;
                var fixed_event_count: usize = 0;
                for (self.replacement_stream.events.items) |event| fixed_event_count = std.math.add(usize, fixed_event_count, @intFromBool(event.fixedKind() != null)) catch return error.ResourceLimit;
                fixed_event_count = std.math.add(usize, fixed_event_count, moved_fixed_event_count) catch return error.ResourceLimit;
                const event_base = std.math.sub(usize, self.engine.active_stream.events.items.len, self.removal.?.descriptor_indexes.event_indexes.items.len) catch return error.ResourceLimit;
                var child_links = std.math.add(usize, old_child_count, final_child_count) catch return error.ResourceLimit;
                child_links = std.math.add(usize, child_links, self.removal.?.scan.removed_elem_ids.len) catch return error.ResourceLimit;
                var splice = render_cache_mod.PreparedRenderSplice(Ctx).init(allocator, &self.engine.render_cache, .{
                    .node_capacity = std.math.add(usize, std.math.cast(usize, max_elem_id) orelse return error.ResourceLimit, 1) catch return error.ResourceLimit,
                    .new_tags = std.math.add(usize, self.replacement_stream.render_nodes.items.len, @intFromBool(self.initial_root)) catch return error.ResourceLimit,
                    .removals = self.removal.?.scan.removed_elem_ids.len,
                    .creations = std.math.add(usize, self.replacement_stream.render_nodes.items.len, @intFromBool(self.initial_root)) catch return error.ResourceLimit,
                    .children = touched.count(),
                    .child_links = child_links,
                    .text_fields = std.math.add(usize, std.math.add(usize, std.math.add(usize, self.replacement_stream.text_nodes.items.len, self.replacement_stream.static_text_attrs.items.len) catch return error.ResourceLimit, std.math.add(usize, self.replacement_stream.signal_text_nodes.items.len, self.replacement_stream.signal_text_attrs.items.len) catch return error.ResourceLimit) catch return error.ResourceLimit, std.math.mul(usize, reuse_count, std.enums.values(render_cache_mod.TextField).len) catch return error.ResourceLimit) catch return error.ResourceLimit,
                    .bool_fields = std.math.add(usize, std.math.add(usize, self.replacement_stream.static_bool_attrs.items.len, self.replacement_stream.signal_bool_attrs.items.len) catch return error.ResourceLimit, std.math.mul(usize, reuse_count, std.enums.values(render_cache_mod.BoolField).len) catch return error.ResourceLimit) catch return error.ResourceLimit,
                    .custom_attrs = element_count,
                    .custom_attr_wire_edits = custom_attr_wire_edits,
                    .fixed_events = std.math.add(usize, fixed_event_count, std.math.mul(usize, reuse_count, std.enums.values(render_cache_mod.EventKind).len) catch return error.ResourceLimit) catch return error.ResourceLimit,
                    .named_events = std.math.add(usize, element_count, moved_named_elem_ids.count()) catch return error.ResourceLimit,
                    .named_event_wire_edits = named_event_wire_edits,
                    .wire_commands = wire_commands,
                    .reuses = reuse_count,
                }) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.ResourceLimit => return error.ResourceLimit,
                };
                errdefer splice.deinit();
                if (self.initial_root) {
                    splice.reset_dom = true;
                    splice.addHostRoot(&self.engine.render_cache) catch |err| return renderSpliceError(err);
                }
                for (self.removal.?.scan.removed_elem_ids) |elem_id| if (!replacements.contains(elem_id)) splice.addRemoval(&self.engine.render_cache, ids.ElemId.fromRaw(elem_id), survival.removalPublication(elem_id)) catch |err| return renderSpliceError(err);
                for (self.replacement_stream.render_nodes.items) |node| {
                    const shape = descriptor_stream.renderNodeShape(HostNodeDescriptorStream, &self.replacement_stream, node);
                    const index = node.elem_id.index();
                    if (index < self.engine.render_cache.nodes.items.len and self.engine.render_cache.nodes.items[index].isActive()) {
                        if (!retired.contains(node.elem_id.raw())) return error.InvalidRenderTopology;
                        if (survival.survives(node.elem_id.raw()))
                            splice.addNodeReuseShape(&self.engine.render_cache, node.elem_id, shape) catch |err| return renderSpliceError(err)
                        else
                            splice.addNodeReplacementShape(&self.engine.render_cache, node.elem_id, shape, survival.removalPublication(node.elem_id.raw())) catch |err| return renderSpliceError(err);
                    } else splice.addCreationShape(&self.engine.render_cache, node.elem_id, shape) catch |err| return renderSpliceError(err);
                }
                iterator = touched.keyIterator();
                while (iterator.next()) |parent_id| {
                    const children = try self.prepareReplacementChildren(allocator, &retired, parent_id.*);
                    errdefer allocator.free(children);
                    splice.addOwnedChildren(&self.engine.render_cache, ids.ElemId.fromRaw(parent_id.*), children) catch |err| return renderSpliceError(err);
                }
                for (self.replacement_stream.text_nodes.items) |desc| splice.addTextField(&self.engine.render_cache, desc.elem_id, .text, desc.value) catch |err| return renderSpliceError(err);
                for (self.replacement_stream.static_text_attrs.items) |desc| splice.addTextField(&self.engine.render_cache, desc.elem_id, desc.field, desc.value) catch |err| return renderSpliceError(err);
                for (self.replacement_stream.static_bool_attrs.items) |desc| splice.addBoolField(&self.engine.render_cache, desc.elem_id, desc.field, desc.value) catch |err| return renderSpliceError(err);
                for (self.replacement_stream.signal_text_nodes.items) |*desc| {
                    const text = self.evalPreparedSignalText(&desc.signal, desc.read, &desc.cached_value);
                    defer text.decref(self.roc_host);
                    splice.addTextField(&self.engine.render_cache, desc.elem_id, .text, text.asSlice()) catch |err| return renderSpliceError(err);
                }
                for (self.replacement_stream.signal_text_attrs.items) |*desc| {
                    const text = self.evalPreparedSignalText(&desc.signal, desc.read, &desc.cached_value);
                    defer text.decref(self.roc_host);
                    splice.addTextField(&self.engine.render_cache, desc.elem_id, desc.field, text.asSlice()) catch |err| return renderSpliceError(err);
                }
                for (self.replacement_stream.signal_bool_attrs.items) |*desc| splice.addBoolField(&self.engine.render_cache, desc.elem_id, desc.field, self.evalPreparedSignalBool(&desc.signal, desc.read, &desc.cached_value)) catch |err| return renderSpliceError(err);
                for (self.replacement_stream.render_nodes.items) |node| {
                    if (node.kind != .element) continue;
                    var attrs: shared_buffer.List(render_cache_mod.CustomTextAttr) = .empty;
                    defer attrs.deinit(allocator);
                    const custom_indexes = self.replacement_stream.customAttrIndices(node.elem_id);
                    const custom_count = custom_indexes.len;
                    attrs.ensureTotalCapacity(allocator, custom_count) catch return error.OutOfMemory;
                    var owned_custom_text = shared_buffer.List(abi.RocStr).empty;
                    defer {
                        for (owned_custom_text.items) |*text| text.decref(self.roc_host);
                        owned_custom_text.deinit(allocator);
                    }
                    owned_custom_text.ensureTotalCapacity(allocator, custom_count) catch return error.OutOfMemory;
                    for (custom_indexes) |custom_index| switch (custom_index.kind) {
                        .static_text => {
                            const desc = self.replacement_stream.static_custom_text_attrs.items[custom_index.index];
                            attrs.appendAssumeCapacity(.{ .name = desc.name, .value = desc.value });
                        },
                        .signal_text => {
                            const desc = &self.replacement_stream.signal_custom_text_attrs.items[custom_index.index];
                            const text = self.evalPreparedSignalText(&desc.signal, desc.read, &desc.cached_value);
                            owned_custom_text.appendAssumeCapacity(text);
                            attrs.appendAssumeCapacity(.{ .name = desc.name, .value = owned_custom_text.items[owned_custom_text.items.len - 1].asSlice() });
                        },
                        .signal_text_optional => {
                            const desc = &self.replacement_stream.signal_optional_custom_text_attrs.items[custom_index.index];
                            const evaluated = self.evalPreparedSignalBinding(&desc.signal);
                            const value = evaluated.value;
                            const cap = evaluated.cap;
                            assertHostValueCapabilitiesMatch(desc.present.capability, cap, "prepared optional text presence capability did not match its signal value");
                            assertHostValueCapabilitiesMatch(desc.read.capability, cap, "prepared optional text read capability did not match its signal value");
                            if (callHostValueToBoolWithCapability(self.host_ctx, self.roc_host, desc.present.capability, desc.present.read, value)) {
                                const text = callHostValueToStrWithCapability(self.host_ctx, self.roc_host, desc.read.capability, desc.read.read, value);
                                owned_custom_text.appendAssumeCapacity(text);
                                attrs.appendAssumeCapacity(.{ .name = desc.name, .value = owned_custom_text.items[owned_custom_text.items.len - 1].asSlice() });
                            }
                            desc.cached_value.replace(self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics, value, cap);
                        },
                        .static_bool => {
                            const desc = self.replacement_stream.static_custom_bool_attrs.items[custom_index.index];
                            if (desc.value) attrs.appendAssumeCapacity(.{ .name = desc.name, .value = "" });
                        },
                        .signal_bool => {
                            const desc = &self.replacement_stream.signal_custom_bool_attrs.items[custom_index.index];
                            if (self.evalPreparedSignalBool(&desc.signal, desc.read, &desc.cached_value)) attrs.appendAssumeCapacity(.{ .name = desc.name, .value = "" });
                        },
                    };
                    splice.addCustomAttrs(&self.engine.render_cache, node.elem_id, attrs.items) catch |err| return renderSpliceError(err);
                    var named: shared_buffer.List(render_cache_mod.NamedEvent) = .empty;
                    defer named.deinit(allocator);
                    named.ensureTotalCapacity(allocator, self.replacement_stream.namedEventIndices(node.elem_id).len) catch return error.OutOfMemory;
                    for (self.replacement_stream.namedEventIndices(node.elem_id)) |event_index| {
                        const desc = self.replacement_stream.events.items[event_index];
                        const binding = desc.named() orelse return error.InvalidDescriptor;
                        const final_index = std.math.add(usize, event_base, event_index) catch return error.ResourceLimit;
                        named.appendAssumeCapacity(.{ .name = binding.name, .binding = .{
                            .event_id = ids.EventId.fromRaw(std.math.add(u64, std.math.cast(u64, final_index) orelse return error.ResourceLimit, 1) catch return error.ResourceLimit),
                            .policy = binding.policy,
                            .delivery = .{ .requested = binding.delivery_request },
                            .key_chord = binding.key_chord,
                            .payload_descriptor = desc.payload_descriptor,
                        } });
                    }
                    splice.addNamedEvents(&self.engine.render_cache, node.elem_id, named.items) catch |err| return renderSpliceError(err);
                }
                for (self.replacement_stream.events.items, 0..) |desc, event_index| if (desc.fixedKind()) |kind| {
                    const final_index = std.math.add(usize, event_base, event_index) catch return error.ResourceLimit;
                    splice.addFixedEvent(&self.engine.render_cache, desc.elem_id, kind, .{
                        .event_id = ids.EventId.fromRaw(std.math.add(u64, std.math.cast(u64, final_index) orelse return error.ResourceLimit, 1) catch return error.ResourceLimit),
                        .delivery = .{ .requested = desc.delivery_request },
                        .payload_descriptor = desc.payload_descriptor,
                    }) catch |err| return renderSpliceError(err);
                };
                for (event_reindex.moves) |move| {
                    const desc = self.engine.active_stream.events.items[move.original];
                    const final_index = move.final;
                    if (desc.fixedKind()) |kind| splice.addFixedEvent(&self.engine.render_cache, desc.elem_id, kind, .{
                        .event_id = ids.EventId.fromRaw(std.math.add(u64, std.math.cast(u64, final_index) orelse return error.ResourceLimit, 1) catch return error.ResourceLimit),
                        .delivery = .{ .requested = desc.delivery_request },
                        .payload_descriptor = desc.payload_descriptor,
                    }) catch |err| return renderSpliceError(err);
                }
                var moved_named_iterator = moved_named_elem_ids.keyIterator();
                while (moved_named_iterator.next()) |elem_id| {
                    var named: shared_buffer.List(render_cache_mod.NamedEvent) = .empty;
                    defer named.deinit(allocator);
                    for (self.engine.active_stream.namedEventIndices(ids.ElemId.fromRaw(elem_id.*))) |original_index| {
                        const desc = self.engine.active_stream.events.items[original_index];
                        const final_index = event_reindex.finalIndex(original_index) orelse continue;
                        const binding = desc.named() orelse continue;
                        named.append(allocator, .{ .name = binding.name, .binding = .{
                            .event_id = ids.EventId.fromRaw(std.math.add(u64, std.math.cast(u64, final_index) orelse return error.ResourceLimit, 1) catch return error.ResourceLimit),
                            .policy = binding.policy,
                            .delivery = .{ .requested = binding.delivery_request },
                            .key_chord = binding.key_chord,
                            .payload_descriptor = desc.payload_descriptor,
                        } }) catch return error.OutOfMemory;
                    }
                    splice.addNamedEvents(&self.engine.render_cache, ids.ElemId.fromRaw(elem_id.*), named.items) catch |err| return renderSpliceError(err);
                }
                splice.clearUnsetReusedFields(&self.engine.render_cache) catch |err| return renderSpliceError(err);
                for (self.replacement_stream.events.items) |*desc| switch (desc.handler) {
                    .reduce => {},
                    .action => |*handler| {
                        const evaluated = self.evalPreparedSignalBinding(&handler.reads);
                        callHostValueToUnitWithCapability(self.host_ctx, self.roc_host, evaluated.cap, hv.hostValueCapabilityDrop(evaluated.cap), evaluated.value);
                    },
                };
                for (self.replacement_stream.on_changes.items) |*desc| {
                    if (desc.cached_value != .absent) continue;
                    const evaluated = self.evalPreparedSignalBinding(&desc.signal);
                    desc.cached_value.replace(self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics, evaluated.value, evaluated.cap);
                }
                return splice;
            }

            fn evalPreparedSignalText(self: *@This(), signal: *HostSignalBinding, read: HostTextRead, cache_slot: *HostSignalCacheSlot) abi.RocStr {
                const evaluated = self.evalPreparedSignalBinding(signal);
                const value = evaluated.value;
                const cap = evaluated.cap;
                assertHostValueCapabilitiesMatch(read.capability, cap, "prepared text read capability did not match its signal value");
                const text = callHostValueToStrWithCapability(self.host_ctx, self.roc_host, read.capability, read.read, value);
                cache_slot.replace(self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics, value, cap);
                return text;
            }

            fn evalPreparedSignalBool(self: *@This(), signal: *HostSignalBinding, read: HostBoolRead, cache_slot: *HostSignalCacheSlot) bool {
                const evaluated = self.evalPreparedSignalBinding(signal);
                const value = evaluated.value;
                const cap = evaluated.cap;
                assertHostValueCapabilitiesMatch(read.capability, cap, "prepared bool read capability did not match its signal value");
                const result = callHostValueToBoolWithCapability(self.host_ctx, self.roc_host, read.capability, read.read, value);
                cache_slot.replace(self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics, value, cap);
                return result;
            }

            fn evalPreparedSignalBinding(self: *@This(), signal: *HostSignalBinding) struct { value: HostValue, cap: HostValueCapability } {
                const previous_bindings = self.engine.active_each_prepared_bindings;
                const previous_generations = self.engine.active_each_prepared_generations;
                self.engine.active_each_prepared_bindings = &self.collection.prepared_row_bindings;
                self.engine.active_each_prepared_generations = &self.collection.prepared_generations;
                defer {
                    self.engine.active_each_prepared_bindings = previous_bindings;
                    self.engine.active_each_prepared_generations = previous_generations;
                }
                return .{
                    .value = self.engine.evalHostSignalBindingStaged(self.host_ctx, self.roc_host, signal, self.collection.prepared_state_cells.items, self.collection.cache_overlay),
                    .cap = self.engine.hostSignalRecordCapabilityWithProvisionalStates(self.host_ctx, signal.record, self.collection.prepared_state_cells.items),
                };
            }

            fn replacementChildCount(self: *const @This(), parent_id: u64) CollectionError!usize {
                var count: usize = 0;
                var child = self.replacement_stream.firstRenderChild(ids.ElemId.fromRaw(parent_id));
                while (child) |child_id| {
                    count = std.math.add(usize, count, 1) catch return error.ResourceLimit;
                    child = self.replacement_stream.nextRenderSibling(child_id);
                }
                return count;
            }

            fn writeReplacementChildren(self: *const @This(), destination: []ids.ElemId, write_index: *usize, parent_id: u64) void {
                var child = self.replacement_stream.firstRenderChild(ids.ElemId.fromRaw(parent_id));
                while (child) |child_id| {
                    destination[write_index.*] = child_id;
                    write_index.* += 1;
                    child = self.replacement_stream.nextRenderSibling(child_id);
                }
            }

            /// Builds the single final child-order allocation that the render
            /// transaction transfers into the committed cache. Surviving old
            /// children retain their order, and replacement children occupy
            /// the first retired child's position or append when none retired.
            fn prepareReplacementChildren(self: *@This(), allocator: std.mem.Allocator, retired: *const std.AutoHashMapUnmanaged(u64, void), parent_id: u64) CollectionError![]ids.ElemId {
                const replacement_count = try self.replacementChildCount(parent_id);
                const parent_index = std.math.cast(usize, parent_id) orelse return error.ResourceLimit;
                const old_children = if (parent_index < self.engine.render_cache.nodes.items.len and self.engine.render_cache.nodes.items[parent_index].isActive()) self.engine.render_cache.nodes.items[parent_index].children.items else &.{};
                var surviving_count: usize = 0;
                for (old_children) |child_id| if (!retired.contains(child_id.raw())) {
                    surviving_count = std.math.add(usize, surviving_count, 1) catch return error.ResourceLimit;
                };
                const final_count = std.math.add(usize, surviving_count, replacement_count) catch return error.ResourceLimit;
                const children = allocator.alloc(ids.ElemId, final_count) catch return error.OutOfMemory;
                errdefer allocator.free(children);
                var write_index: usize = 0;
                var inserted = false;
                for (old_children) |child_id| {
                    if (retired.contains(child_id.raw())) {
                        if (!inserted) {
                            self.writeReplacementChildren(children, &write_index, parent_id);
                            inserted = true;
                        }
                    } else {
                        children[write_index] = child_id;
                        write_index += 1;
                    }
                }
                if (!inserted) self.writeReplacementChildren(children, &write_index, parent_id);
                if (write_index != children.len) @panic("prepared replacement child count changed while materializing");
                return children;
            }

            fn prepareGraphRoutes(self: *@This(), allocator: std.mem.Allocator) CollectionError!void {
                const graph_plan = &self.graph_append.?;
                const graph_count = graph_plan.finalGraphCount();
                var source: shared_buffer.List(active_graph.RouteAppend(u64)) = .empty;
                defer source.deinit(allocator);
                var text: shared_buffer.List(active_graph.RouteAppend(active_graph.TextSink)) = .empty;
                defer text.deinit(allocator);
                var bools: shared_buffer.List(active_graph.RouteAppend(active_graph.BoolSink)) = .empty;
                defer bools.deinit(allocator);
                var changes: shared_buffer.List(active_graph.RouteAppend(active_graph.ChangeSink)) = .empty;
                defer changes.deinit(allocator);
                var structural: shared_buffer.List(active_graph.RouteAppend(active_graph.StructuralSink)) = .empty;
                defer structural.deinit(allocator);
                for (graph_plan.records, graph_plan.record_ids) |record, record_id| switch (record.payload) {
                    .ref => |source_node_id| source.append(allocator, .{ .route_index = source_node_id, .value = record_id }) catch return error.OutOfMemory,
                    else => {},
                };
                const text_node_base = self.engine.active_stream.signal_text_nodes.items.len - self.removal.?.descriptor_indexes.signal_text_node_indexes.items.len;
                for (self.replacement_stream.signal_text_nodes.items, 0..) |desc, offset| try self.appendTextRoute(allocator, &text, graph_plan, desc.signal.record, .{ .kind = .text_node, .index = text_node_base + offset });
                const text_attr_base = self.engine.active_stream.signal_text_attrs.items.len - self.removal.?.descriptor_indexes.signal_text_attr_indexes.items.len;
                for (self.replacement_stream.signal_text_attrs.items, 0..) |desc, offset| try self.appendTextRoute(allocator, &text, graph_plan, desc.signal.record, .{ .kind = .text_attr, .index = text_attr_base + offset });
                const custom_text_base = self.engine.active_stream.signal_custom_text_attrs.items.len - self.removal.?.descriptor_indexes.signal_custom_text_attr_indexes.items.len;
                for (self.replacement_stream.signal_custom_text_attrs.items, 0..) |desc, offset| try self.appendTextRoute(allocator, &text, graph_plan, desc.signal.record, .{ .kind = .custom_text_attr, .index = custom_text_base + offset });
                const optional_custom_text_base = self.engine.active_stream.signal_optional_custom_text_attrs.items.len - self.removal.?.descriptor_indexes.signal_optional_custom_text_attr_indexes.items.len;
                for (self.replacement_stream.signal_optional_custom_text_attrs.items, 0..) |desc, offset| try self.appendTextRoute(allocator, &text, graph_plan, desc.signal.record, .{ .kind = .custom_text_optional_attr, .index = optional_custom_text_base + offset });
                const bool_attr_base = self.engine.active_stream.signal_bool_attrs.items.len - self.removal.?.descriptor_indexes.signal_bool_attr_indexes.items.len;
                for (self.replacement_stream.signal_bool_attrs.items, 0..) |desc, offset| try self.appendBoolRoute(allocator, &bools, graph_plan, desc.signal.record, .{ .kind = .bool_attr, .index = bool_attr_base + offset });
                const custom_bool_base = self.engine.active_stream.signal_custom_bool_attrs.items.len - self.removal.?.descriptor_indexes.signal_custom_bool_attr_indexes.items.len;
                for (self.replacement_stream.signal_custom_bool_attrs.items, 0..) |desc, offset| try self.appendBoolRoute(allocator, &bools, graph_plan, desc.signal.record, .{ .kind = .custom_bool_attr, .index = custom_bool_base + offset });
                const change_base = self.engine.active_stream.on_changes.items.len - self.removal.?.node_indexes.on_change_indexes.items.len;
                for (self.replacement_stream.on_changes.items, 0..) |desc, offset| try self.appendChangeRoute(allocator, &changes, graph_plan, desc.signal.record, .{ .index = change_base + offset });
                const when_base = self.engine.active_stream.whens.items.len - self.removal.?.node_indexes.when_indexes.items.len;
                for (self.replacement_stream.whens.items, 0..) |desc, offset| try self.appendStructuralRoute(allocator, &structural, graph_plan, desc.condition.record, .{ .kind = .when, .index = when_base + offset });
                const each_base = self.engine.active_stream.eaches.items.len - self.removal.?.node_indexes.each_indexes.items.len;
                for (self.replacement_stream.eaches.items, 0..) |desc, offset| try self.appendStructuralRoute(allocator, &structural, graph_plan, desc.items.record, .{ .kind = .each, .index = each_base + offset });
                var source_count = self.engine.active_source_signal_routes.items.len;
                for (source.items) |entry| source_count = @max(source_count, std.math.add(usize, @intCast(entry.route_index), 1) catch return error.ResourceLimit);
                self.graph_source_route_count = source_count;
                self.source_route_appends = active_graph.prepareSourceRouteAppendsAfterRelease(allocator, &self.engine.active_source_signal_routes, &self.graph_release.?.remap, source_count, source.items) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.InvalidAppend => return error.InvalidSignalGraphAppend,
                };
                self.text_route_appends = active_graph.prepareRouteAppends(active_graph.TextSink, allocator, &self.engine.active_text_signal_routes, graph_count, text.items) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.InvalidAppend => return error.InvalidSignalGraphAppend,
                };
                self.bool_route_appends = active_graph.prepareRouteAppends(active_graph.BoolSink, allocator, &self.engine.active_bool_signal_routes, graph_count, bools.items) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.InvalidAppend => return error.InvalidSignalGraphAppend,
                };
                self.change_route_appends = active_graph.prepareRouteAppends(active_graph.ChangeSink, allocator, &self.engine.active_change_signal_routes, graph_count, changes.items) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.InvalidAppend => return error.InvalidSignalGraphAppend,
                };
                self.structural_route_appends = active_graph.prepareRouteAppends(active_graph.StructuralSink, allocator, &self.engine.active_structural_signal_routes, graph_count, structural.items) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.InvalidAppend => return error.InvalidSignalGraphAppend,
                };
                graph_plan.reservePublication(allocator, &self.engine.active_signal_graph) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.InvalidAppend => return error.InvalidSignalGraphAppend,
                };
                graph_plan.reserveParallelRoutes(allocator, &self.engine.active_text_signal_routes, &self.engine.active_bool_signal_routes, &self.engine.active_change_signal_routes, &self.engine.active_structural_signal_routes) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.InvalidAppend => return error.InvalidSignalGraphAppend,
                };
                try self.source_route_appends.?.reserveOuter(allocator, &self.engine.active_source_signal_routes, source_count);
            }

            fn appendTextRoute(self: *@This(), allocator: std.mem.Allocator, routes: *shared_buffer.List(active_graph.RouteAppend(active_graph.TextSink)), graph_plan: *const active_graph.PreparedGraphAppend(HostSignalRecord), record: *HostSignalRecord, sink: active_graph.TextSink) CollectionError!void {
                const id = graph_plan.plannedRecordId(&self.graph_release.?.remap, self.engine.active_signal_graph.items, record) orelse return error.InvalidSignalGraphAppend;
                routes.append(allocator, .{ .route_index = id, .value = sink }) catch return error.OutOfMemory;
            }
            fn appendBoolRoute(self: *@This(), allocator: std.mem.Allocator, routes: *shared_buffer.List(active_graph.RouteAppend(active_graph.BoolSink)), graph_plan: *const active_graph.PreparedGraphAppend(HostSignalRecord), record: *HostSignalRecord, sink: active_graph.BoolSink) CollectionError!void {
                const id = graph_plan.plannedRecordId(&self.graph_release.?.remap, self.engine.active_signal_graph.items, record) orelse return error.InvalidSignalGraphAppend;
                routes.append(allocator, .{ .route_index = id, .value = sink }) catch return error.OutOfMemory;
            }
            fn appendChangeRoute(self: *@This(), allocator: std.mem.Allocator, routes: *shared_buffer.List(active_graph.RouteAppend(active_graph.ChangeSink)), graph_plan: *const active_graph.PreparedGraphAppend(HostSignalRecord), record: *HostSignalRecord, sink: active_graph.ChangeSink) CollectionError!void {
                const id = graph_plan.plannedRecordId(&self.graph_release.?.remap, self.engine.active_signal_graph.items, record) orelse return error.InvalidSignalGraphAppend;
                routes.append(allocator, .{ .route_index = id, .value = sink }) catch return error.OutOfMemory;
            }
            fn appendStructuralRoute(self: *@This(), allocator: std.mem.Allocator, routes: *shared_buffer.List(active_graph.RouteAppend(active_graph.StructuralSink)), graph_plan: *const active_graph.PreparedGraphAppend(HostSignalRecord), record: *HostSignalRecord, sink: active_graph.StructuralSink) CollectionError!void {
                const id = graph_plan.plannedRecordId(&self.graph_release.?.remap, self.engine.active_signal_graph.items, record) orelse return error.InvalidSignalGraphAppend;
                routes.append(allocator, .{ .route_index = id, .value = sink }) catch return error.OutOfMemory;
            }

            fn deinitGraphRoutes(self: *@This(), allocator: std.mem.Allocator) void {
                if (self.source_route_appends) |*routes| routes.deinit(allocator);
                if (self.text_route_appends) |*routes| routes.deinit(allocator);
                if (self.bool_route_appends) |*routes| routes.deinit(allocator);
                if (self.change_route_appends) |*routes| routes.deinit(allocator);
                if (self.structural_route_appends) |*routes| routes.deinit(allocator);
                self.source_route_appends = null;
                self.text_route_appends = null;
                self.bool_route_appends = null;
                self.change_route_appends = null;
                self.structural_route_appends = null;
            }

            fn commitGraphAssumeCapacity(self: *@This()) void {
                const release = &self.graph_release.?;
                const append = &self.graph_append.?;
                release.applyAdjacency(self.engine.active_signal_graph.items);
                release.applyDense(
                    &self.engine.active_signal_graph,
                    &self.engine.active_source_signal_routes,
                    &self.engine.active_text_signal_routes,
                    &self.engine.active_bool_signal_routes,
                    &self.engine.active_change_signal_routes,
                    &self.engine.active_structural_signal_routes,
                );
                append.commitNodes(&self.engine.active_signal_graph);
                append.commitParallelRoutes(
                    &self.engine.active_text_signal_routes,
                    &self.engine.active_bool_signal_routes,
                    &self.engine.active_change_signal_routes,
                    &self.engine.active_structural_signal_routes,
                );
                self.source_route_appends.?.apply(&self.engine.active_source_signal_routes, self.graph_source_route_count);
                const graph_count = append.finalGraphCount();
                self.text_route_appends.?.apply(&self.engine.active_text_signal_routes, graph_count);
                self.bool_route_appends.?.apply(&self.engine.active_bool_signal_routes, graph_count);
                self.change_route_appends.?.apply(&self.engine.active_change_signal_routes, graph_count);
                self.structural_route_appends.?.apply(&self.engine.active_structural_signal_routes, graph_count);
                var lifecycle = ActiveSignalGraphLifecycle{ .engine = self.engine, .ctx = self.host_ctx };
                release.releaseRetired(Ctx.allocator(self.host_ctx), self.engine.active_signal_graph.items, &lifecycle);
                append.registerAppendedEffects(&lifecycle);
                self.engine.commitPreparedSelectors(Ctx.allocator(self.host_ctx), &self.selector_registry.?, append);
            }

            fn commitRenderCacheAssumeCapacity(self: *@This()) void {
                const splice = &(self.render_splice orelse return);
                splice.stageAssumeCapacity(self.render_batch_target.?, Ctx.allocator(self.host_ctx)) catch @panic("prepared render batch violated its preflight contract");
                splice.apply(&self.engine.render_cache);
            }

            fn publishRenderBatchLast(self: *@This()) void {
                if (self.render_splice == null) return;
                self.render_batch_target.?.commit();
                self.publication_phase.markBatchPublished();
                if (comptime @hasDecl(Ctx, "publishRenderPublication")) {
                    Ctx.publishRenderPublication(self.host_ctx, &self.host_render_publication.?);
                    self.publication_phase.markHostPublished();
                }
            }

            fn collectRetiredGraphRoots(self: *@This(), allocator: std.mem.Allocator, roots: *shared_buffer.List(*HostSignalRecord)) CollectionError!void {
                try collectRetiredGraphRootsForRemoval(self.engine, allocator, &self.removal.?, roots);
            }

            fn collectReplacementGraphRoots(self: *@This(), allocator: std.mem.Allocator, roots: *shared_buffer.List(*HostSignalRecord)) CollectionError!void {
                try collectReplacementGraphRootsForStream(allocator, &self.replacement_stream, roots);
            }

            fn prepareSinkEdits(self: *@This(), allocator: std.mem.Allocator) CollectionError!active_graph.PreparedSinkRouteEdits {
                var text: shared_buffer.List(active_graph.TextSinkEdit) = .empty;
                defer text.deinit(allocator);
                var bools: shared_buffer.List(active_graph.BoolSinkEdit) = .empty;
                defer bools.deinit(allocator);
                var structural: shared_buffer.List(active_graph.StructuralSinkEdit) = .empty;
                defer structural.deinit(allocator);
                var changes: shared_buffer.List(active_graph.ChangeSinkEdit) = .empty;
                defer changes.deinit(allocator);
                const indexes = &self.removal.?.descriptor_indexes;
                var text_removals = std.math.add(usize, indexes.signal_text_node_indexes.items.len, indexes.signal_text_attr_indexes.items.len) catch return error.ResourceLimit;
                text_removals = std.math.add(usize, text_removals, indexes.signal_custom_text_attr_indexes.items.len) catch return error.ResourceLimit;
                text_removals = std.math.add(usize, text_removals, indexes.signal_optional_custom_text_attr_indexes.items.len) catch return error.ResourceLimit;
                const bool_removals = std.math.add(usize, indexes.signal_bool_attr_indexes.items.len, indexes.signal_custom_bool_attr_indexes.items.len) catch return error.ResourceLimit;
                const structural_removals = std.math.add(usize, self.removal.?.node_indexes.when_indexes.items.len, self.removal.?.node_indexes.each_indexes.items.len) catch return error.ResourceLimit;
                text.ensureTotalCapacity(allocator, std.math.mul(usize, 2, text_removals) catch return error.ResourceLimit) catch return error.OutOfMemory;
                bools.ensureTotalCapacity(allocator, std.math.mul(usize, 2, bool_removals) catch return error.ResourceLimit) catch return error.OutOfMemory;
                structural.ensureTotalCapacity(allocator, std.math.mul(usize, 2, structural_removals) catch return error.ResourceLimit) catch return error.OutOfMemory;
                changes.ensureTotalCapacity(allocator, std.math.mul(usize, 2, self.removal.?.node_indexes.on_change_indexes.items.len) catch return error.ResourceLimit) catch return error.OutOfMemory;
                try appendTextSinkEdits(allocator, self.engine, &text, self.engine.active_stream.signal_text_nodes.items, indexes.signal_text_node_indexes.items, .text_node);
                try appendTextSinkEdits(allocator, self.engine, &text, self.engine.active_stream.signal_text_attrs.items, indexes.signal_text_attr_indexes.items, .text_attr);
                try appendTextSinkEdits(allocator, self.engine, &text, self.engine.active_stream.signal_custom_text_attrs.items, indexes.signal_custom_text_attr_indexes.items, .custom_text_attr);
                try appendTextSinkEdits(allocator, self.engine, &text, self.engine.active_stream.signal_optional_custom_text_attrs.items, indexes.signal_optional_custom_text_attr_indexes.items, .custom_text_optional_attr);
                try appendBoolSinkEdits(allocator, self.engine, &bools, self.engine.active_stream.signal_bool_attrs.items, indexes.signal_bool_attr_indexes.items, .bool_attr);
                try appendBoolSinkEdits(allocator, self.engine, &bools, self.engine.active_stream.signal_custom_bool_attrs.items, indexes.signal_custom_bool_attr_indexes.items, .custom_bool_attr);
                try appendChangeSinkEdits(allocator, self.engine, &changes, self.engine.active_stream.on_changes.items, self.removal.?.node_indexes.on_change_indexes.items);
                try appendStructuralSinkEdits(allocator, self.engine, &structural, self.engine.active_stream.whens.items, self.removal.?.node_indexes.when_indexes.items, .when);
                try appendStructuralSinkEdits(allocator, self.engine, &structural, self.engine.active_stream.eaches.items, self.removal.?.node_indexes.each_indexes.items, .each);
                return active_graph.prepareSinkRouteEdits(
                    allocator,
                    &self.engine.active_text_signal_routes,
                    &self.engine.active_bool_signal_routes,
                    &self.engine.active_change_signal_routes,
                    &self.engine.active_structural_signal_routes,
                    text.items,
                    bools.items,
                    changes.items,
                    structural.items,
                ) catch return error.OutOfMemory;
            }

            fn descriptorSwapMap(allocator: std.mem.Allocator, len: usize) std.mem.Allocator.Error![]usize {
                const map = try allocator.alloc(usize, len);
                for (map, 0..) |*entry, index| entry.* = index;
                return map;
            }

            fn appendTextSinkEdits(allocator: std.mem.Allocator, engine_ptr: *Self, edits: *shared_buffer.List(active_graph.TextSinkEdit), descriptors: anytype, removal_indexes: []const usize, kind: active_graph.TextSinkKind) CollectionError!void {
                const map = try descriptorSwapMap(allocator, descriptors.len);
                defer allocator.free(map);
                var live_len = descriptors.len;
                for (removal_indexes) |index| {
                    if (index >= live_len) return error.ResourceLimit;
                    edits.appendAssumeCapacity(.{ .record_id = engine_ptr.requireActiveSignalRecordId(descriptors[map[index]].signal.record), .kind = kind, .old_index = index });
                    const last_index = live_len - 1;
                    if (index != last_index) {
                        edits.appendAssumeCapacity(.{ .record_id = engine_ptr.requireActiveSignalRecordId(descriptors[map[last_index]].signal.record), .kind = kind, .old_index = last_index, .new_index = index });
                        map[index] = map[last_index];
                    }
                    live_len = last_index;
                }
            }

            fn appendBoolSinkEdits(allocator: std.mem.Allocator, engine_ptr: *Self, edits: *shared_buffer.List(active_graph.BoolSinkEdit), descriptors: anytype, removal_indexes: []const usize, kind: active_graph.BoolSinkKind) CollectionError!void {
                const map = try descriptorSwapMap(allocator, descriptors.len);
                defer allocator.free(map);
                var live_len = descriptors.len;
                for (removal_indexes) |index| {
                    if (index >= live_len) return error.ResourceLimit;
                    edits.appendAssumeCapacity(.{ .record_id = engine_ptr.requireActiveSignalRecordId(descriptors[map[index]].signal.record), .kind = kind, .old_index = index });
                    const last_index = live_len - 1;
                    if (index != last_index) {
                        edits.appendAssumeCapacity(.{ .record_id = engine_ptr.requireActiveSignalRecordId(descriptors[map[last_index]].signal.record), .kind = kind, .old_index = last_index, .new_index = index });
                        map[index] = map[last_index];
                    }
                    live_len = last_index;
                }
            }

            fn appendChangeSinkEdits(allocator: std.mem.Allocator, engine_ptr: *Self, edits: *shared_buffer.List(active_graph.ChangeSinkEdit), descriptors: anytype, removal_indexes: []const usize) CollectionError!void {
                const map = try descriptorSwapMap(allocator, descriptors.len);
                defer allocator.free(map);
                var live_len = descriptors.len;
                for (removal_indexes) |index| {
                    if (index >= live_len) return error.ResourceLimit;
                    edits.appendAssumeCapacity(.{ .record_id = engine_ptr.requireActiveSignalRecordId(descriptors[map[index]].signal.record), .old_index = index });
                    const last_index = live_len - 1;
                    if (index != last_index) {
                        edits.appendAssumeCapacity(.{ .record_id = engine_ptr.requireActiveSignalRecordId(descriptors[map[last_index]].signal.record), .old_index = last_index, .new_index = index });
                        map[index] = map[last_index];
                    }
                    live_len = last_index;
                }
            }

            fn appendStructuralSinkEdits(allocator: std.mem.Allocator, engine_ptr: *Self, edits: *shared_buffer.List(active_graph.StructuralSinkEdit), descriptors: anytype, removal_indexes: []const usize, comptime kind: active_graph.StructuralKind) CollectionError!void {
                const map = try descriptorSwapMap(allocator, descriptors.len);
                defer allocator.free(map);
                var live_len = descriptors.len;
                for (removal_indexes) |index| {
                    if (index >= live_len) return error.ResourceLimit;
                    const record = switch (kind) {
                        .when => descriptors[map[index]].condition.record,
                        .each => descriptors[map[index]].items.record,
                    };
                    edits.appendAssumeCapacity(.{ .record_id = engine_ptr.requireActiveSignalRecordId(record), .kind = kind, .old_index = index });
                    const last_index = live_len - 1;
                    if (index != last_index) {
                        const moved_record = switch (kind) {
                            .when => descriptors[map[last_index]].condition.record,
                            .each => descriptors[map[last_index]].items.record,
                        };
                        edits.appendAssumeCapacity(.{ .record_id = engine_ptr.requireActiveSignalRecordId(moved_record), .kind = kind, .old_index = last_index, .new_index = index });
                        map[index] = map[last_index];
                    }
                    live_len = last_index;
                }
            }

            fn commitStateCellsAssumeCapacity(self: *@This()) void {
                const retirement = PreparedStateRetirementIndexes{ .indexes_descending = self.state_cell_indexes };
                retirement.apply(self.engine, &self.retired_state_cells);
                self.collection.commit();
            }

            fn commitIdentityRetirement(self: *@This()) void {
                const retirements = PreparedIdentityRetirements{ .node_ids = self.retired_node_identity_ids, .dom_ids = self.retired_dom_identity_ids };
                retirements.apply(self.engine);
            }

            fn commitRowRetirement(self: *@This()) void {
                var row_keys = EachRowScopeKeyLookup{ .engine = self.engine };
                self.row_retirement.?.apply(Ctx.allocator(self.host_ctx), &self.engine.each_row_sites, &self.engine.each_row_site_indexes, &self.engine.each_row_memberships_by_scope_id, &row_keys);
            }

            fn commitEffectsRetirement(self: *@This()) void {
                self.effects_retirement.?.apply(self.engine, self.host_ctx);
            }

            fn commitScopeRetirementLast(self: *@This()) void {
                self.engine.commitPreparedScopeRetirement(Ctx.allocator(self.host_ctx), &self.scope_retirement.?, &self.retired_scope_steps);
            }

            fn commitAssumeCapacity(self: *@This()) void {
                self.commitRenderCacheAssumeCapacity();
                if (self.sink_edits) |*edits| edits.apply(
                    &self.engine.active_text_signal_routes,
                    &self.engine.active_bool_signal_routes,
                    &self.engine.active_change_signal_routes,
                    &self.engine.active_structural_signal_routes,
                );
                if (self.graph_release != null) self.commitGraphAssumeCapacity();
                const indexes = &self.removal.?.descriptor_indexes;
                self.engine.active_stream.commitStaticDescriptorReplacementAssumeCapacity(
                    &self.replacement_stream,
                    &self.retired_stream,
                    indexes.element_indexes.items,
                    indexes.text_node_indexes.items,
                    indexes.static_text_attr_indexes.items,
                    indexes.static_bool_attr_indexes.items,
                    indexes.signal_text_node_indexes.items,
                    indexes.signal_text_attr_indexes.items,
                    indexes.signal_bool_attr_indexes.items,
                    indexes.event_indexes.items,
                    self.removal.?.node_indexes.scope_site_indexes.items,
                    self.removal.?.node_indexes.state_indexes.items,
                    self.removal.?.node_indexes.when_indexes.items,
                    self.removal.?.node_indexes.each_indexes.items,
                );
                self.engine.active_stream.commitCustomDescriptorReplacementAssumeCapacity(
                    &self.replacement_stream,
                    &self.retired_stream,
                    indexes.static_custom_text_attr_indexes.items,
                    indexes.signal_custom_text_attr_indexes.items,
                    indexes.signal_optional_custom_text_attr_indexes.items,
                    indexes.static_custom_bool_attr_indexes.items,
                    indexes.signal_custom_bool_attr_indexes.items,
                );
                self.engine.active_stream.commitLifecycleReplacementAssumeCapacity(
                    &self.replacement_stream,
                    &self.retired_stream,
                    self.removal.?.node_indexes.on_change_indexes.items,
                    self.removal.?.node_indexes.mount_indexes.items,
                    self.removal.?.node_indexes.cleanup_indexes.items,
                );
                self.commitStateCellsAssumeCapacity();
                self.commitIdentityRetirement();
                self.commitRowRetirement();
                self.commitEffectsRetirement();
                self.commitScopeRetirementLast();
                self.publishRenderBatchLast();
            }

            fn deinit(self: *@This()) void {
                const allocator = Ctx.allocator(self.host_ctx);
                if (self.publication_phase.needsAbort() and self.render_batch_target != &self.render_batch) self.render_batch_target.?.abort();
                if (@hasDecl(Ctx, "RenderPublication")) if (self.host_render_publication) |*publication| publication.deinit();
                self.render_batch.deinit(allocator);
                if (self.render_splice) |*splice| splice.deinit();
                if (self.publication) |*publication| publication.deinit(allocator);
                if (self.sink_edits) |*edits| edits.deinit(allocator);
                if (self.graph_append) |*append| append.deinit(allocator);
                if (self.graph_release) |*release| release.deinit(allocator);
                if (self.selector_registry) |*registry| registry.deinit(allocator);
                self.deinitGraphRoutes(allocator);
                if (self.removal) |*removal| removal.deinit(allocator);
                if (self.scope_retirement) |*retirement| retirement.deinit(allocator);
                if (self.row_retirement) |*retirement| retirement.deinit(allocator);
                if (self.effects_retirement) |*effects| effects.deinit(allocator, self.roc_host);
                for (self.retired_scope_steps.items) |*step| self.engine.releasePreparedRetiredScopeStep(step);
                self.retired_scope_steps.deinit(allocator);
                allocator.free(self.state_cell_indexes);
                allocator.free(self.retired_node_identity_ids);
                allocator.free(self.retired_dom_identity_ids);
                for (self.retired_state_cells.items) |*state| state.retire(self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics);
                self.retired_state_cells.deinit(allocator);
                allocator.free(self.target_scopes);
                self.collection.deinit();
                self.retired_stream.deinit(allocator, self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics);
                self.replacement_stream.deinit(allocator, self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics);
                allocator.destroy(self);
            }
        };

        /// Compatibility seam that prepares and immediately commits a root
        /// descriptor generation. Production mount and root replacement must
        /// keep the returned plan provisional until render publication is also
        /// prepared, rather than using this collection-only convenience call.
        pub fn collectStaticRootDescriptorsTransactional(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, stream: *HostNodeDescriptorStream, root: abi.Elem, limits: collection_budget.Limits) CollectionError!void {
            const plan = try PreparedRootCollection.prepare(self, ctx, roc_host, root, limits, &.{});
            stream.* = plan.commit();
        }

        /// Collects active elem root descriptors from the explicitly affected graph or scope set.
        pub fn collectActiveElemRootDescriptors(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, stream: *HostNodeDescriptorStream, root: abi.Elem, dirty_source_node_ids: []const u64) void {
            if (!builtin.is_test) @compileError("collectActiveElemRootDescriptors is a pre-transactional engine path kept only for tests; production goes through prepared transactions");
            const plan = PreparedRootCollection.prepare(self, ctx, roc_host, root, .{}, dirty_source_node_ids) catch @panic("prepared test root collection failed");
            stream.* = plan.commit();
        }

        /// Clears active signal graph while retaining bounded storage where the type promises reuse.
        pub fn clearActiveSignalGraph(self: *Self, ctx: Ctx.Handle) void {
            const allocator = Ctx.allocator(ctx);
            if (self.roc_host == null) {
                if (self.active_signal_graph.items.len != 0) @panic("active signal graph cannot release records without a Roc host");
                self.active_signal_graph.items.len = 0;
                return;
            }
            var lifecycle = ActiveSignalGraphLifecycle{ .engine = self, .ctx = ctx };
            active_graph.clear(HostSignalRecord, allocator, &self.active_signal_graph, &lifecycle);
            if (self.selectors.groups.count() != 0) @panic("active selector index survived graph clear");
            if (self.active_row_sources.count() != 0) @panic("active row-source index survived graph clear");
            self.active_row_sources.deinit(allocator);
            self.active_row_sources = .{};
        }

        /// Clears active intervals while retaining bounded storage where the type promises reuse.
        pub fn clearActiveIntervals(self: *Self, ctx: Ctx.Handle) void {
            effects_runtime.clearActiveIntervals(Ctx, ctx, &self.active_intervals, self.roc_host);
        }

