                &self.active_signal_graph,
                &self.active_source_signal_routes,
                &self.active_text_signal_routes,
                &self.active_bool_signal_routes,
                &self.active_change_signal_routes,
                &self.active_structural_signal_routes,
                record,
                &lifecycle,
            );
        }

