        /// Performs eval host signal record inside the shared engine while preserving transaction and changed-set invariants.
        pub fn evalHostSignalRecord(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, record: *HostSignalRecord) HostValue {
            return self.evalHostSignalRecordWithProvisionalStates(ctx, roc_host, record, &.{});
        }

        fn evalHostSignalRecordWithProvisionalStates(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, record: *HostSignalRecord, provisional_states: []const HostState) HostValue {
            return self.evalHostSignalRecordStaged(ctx, roc_host, record, provisional_states, null);
        }

        fn resolveEachRowBinding(self: *Self, row_handle: row_handles.RowHandleId) ?each_generation.RowBinding {
            if (!self.row_handle_registry.contains(row_handle)) return null;
            if (self.active_each_prepared_bindings) |prepared| if (prepared.get(row_handle)) |binding| return binding;
            if (self.active_each_candidate_bindings) |candidate| if (candidate.candidate.get(row_handle)) |entry| return entry.binding;
            if (self.rows_store) |*store| if (store.findRowHandle(row_handle.raw())) |location| {
                const generation_id = if (self.active_each_candidate_rows_site_id == location.site_id)
                    (if (self.active_each_candidate_generation) |candidate| candidate.id else return null)
                else
                    (self.each_generation_ids_by_rows_site.get(location.site_id) orelse return null);
                const row = store.getRowConst(location.site_id, location.row_id) catch return null;
                return .{ .generation_id = generation_id, .item_slot = row.metadata.item_slot };
            };
            return self.committed_row_bindings.get(row_handle);
        }

        fn eachGenerationForBinding(self: *Self, binding: each_generation.RowBinding) ?*each_generation.Generation {
            if (self.active_each_prepared_generations) |prepared| if (prepared.get(binding.generation_id)) |generation| return generation;
            if (self.active_each_candidate_generation) |candidate| if (candidate.id == binding.generation_id) return candidate;
            return self.each_generations.get(binding.generation_id);
        }

        fn activeRowSourceRecord(self: *Self, row_handle: row_handles.RowHandleId) ?*HostSignalRecord {
            if (!self.row_handle_registry.contains(row_handle)) return null;
            const record = self.active_row_sources.get(row_handle) orelse return null;
            const payload = switch (record.payload) {
                .row_source => |row| row,
                else => @panic("row-source index pointed at a non-row record"),
            };
            if (payload.row_handle != row_handle) @panic("row-source index key disagreed with its record");
            _ = self.requireActiveSignalRecordId(record);
            return record;
        }

        /// Clones only changed surviving row items into ordinary source roots.
        /// Lookup and work are proportional to `row_handles_changed`; rows whose
        /// subtree never reads `Ui.Row` have no active source and need no clone.
        fn prepareChangedRowSourceUpdates(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, generation: *each_generation.Generation, row_handles_changed: []const row_handles.RowHandleId, item_slots: []const u64) CollectionError!signal_records.OwnedSourceUpdates {
            if (row_handles_changed.len != item_slots.len) return error.InvalidDescriptor;
            var expected: usize = 0;
            for (row_handles_changed) |handle| if (self.activeRowSourceRecord(handle) != null) {
                expected = std.math.add(usize, expected, 1) catch return error.ResourceLimit;
            };
            var owned = signal_records.OwnedSourceUpdates.init(Ctx.allocator(ctx), expected) catch return error.OutOfMemory;
            errdefer owned.deinit(ctx, roc_host, &self.pending_roc_metrics);
            for (row_handles_changed, item_slots) |handle, item_slot| {
                const record = self.activeRowSourceRecord(handle) orelse continue;
                const row = switch (record.payload) {
                    .row_source => |payload| payload,
                    else => unreachable,
                };
                assertHostValueCapabilitiesMatch(row.cap, generation.ops.item_capability, "changed row source capability did not match its candidate generation");
                const value = retained_values.callRowsCloneItem(
                    Ctx,
                    ctx,
                    roc_host,
                    generation.ops.rows_capability,
                    generation.ops.item_capability,
                    generation.ops.clone_item,
                    generation.collection.value,
                    item_slot,
                );
                owned.adoptAssumeCapacity(record, value, generation.ops.item_capability, &self.pending_roc_metrics) catch {
                    callHostValueToUnitWithCapability(ctx, roc_host, generation.ops.item_capability, hv.hostValueCapabilityDrop(generation.ops.item_capability), value);
                    return error.InvalidDescriptor;
                };
            }
            return owned;
        }

        fn materializeEachRowItem(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, payload: *HostSignalRowSourceRecord) HostValue {
            const binding = self.resolveEachRowBinding(payload.row_handle) orelse @panic("row source resolved after its row scope was retired");
            const generation = self.eachGenerationForBinding(binding) orelse @panic("row source generation was not retained");
            assertHostValueCapabilitiesMatch(payload.cap, generation.ops.item_capability, "row source capability did not match its collection generation");
            return retained_values.callRowsCloneItem(
                Ctx,
                ctx,
                roc_host,
                generation.ops.rows_capability,
                generation.ops.item_capability,
                generation.ops.clone_item,
                generation.collection.value,
                binding.item_slot,
            );
        }

        /// Evaluates a record inside a staged transaction. `provisional_states`
        /// are the collection's not-yet-published state cells and `overlay` is
        /// the transaction's prepared cache updates: a record whose cache slot
        /// the overlay has staged (a settled task, an interval tick, a storage
        /// read, or a derived record already re-evaluated for this transaction)
        /// reads that staged value, never the committed one, so a branch
        /// mounted by the transaction observes the same values as the scalar
        /// updates published beside it.
        fn evalHostSignalRecordStaged(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, record: *HostSignalRecord, provisional_states: []const HostState, overlay: ?*const signal_records.PreparedCacheUpdates) HostValue {
            if (overlay) |prepared| if (record.cachedSlot()) |slot| {
                const staged = prepared.readSlot(slot);
                if (staged != slot and staged.* == .present) return self.cloneCachedSignalValue(ctx, staged);
            };
            switch (record.payload) {
                .ref => |node_id| {
                    for (provisional_states) |state| if (state.state_id == node_id) return Ctx.cloneHostValue(ctx, state.activePayloadConst().cell.value);
                    return Ctx.stateValueByNodeId(ctx, node_id);
                },
                .const_value => |*payload| {
                    const value = erased_calls.callValueInitThunk(roc_host, payload.init.toAbi());
                    return self.replaceSignalExprCacheAndClone(ctx, &payload.cached_value, roc_host, value, payload.cap);
                },
                .map => |*payload| {
                    const input = self.evalHostSignalRecordStaged(ctx, roc_host, payload.input, provisional_states, overlay);
                    defer self.dropHostSignalRecordValueWithProvisionalStates(ctx, roc_host, payload.input, input, provisional_states);
                    self.recordDerivedCall();
                    const input_cap = self.hostSignalRecordCapabilityWithProvisionalStates(ctx, payload.input, provisional_states);
                    const value = callHostValueToHostValueWithCapability(ctx, roc_host, input_cap, payload.transform.toAbi(), input);
                    return self.replaceSignalExprCacheAndClone(ctx, &payload.cached_value, roc_host, value, payload.cap);
                },
                .map2 => |*payload| {
                    const left = self.evalHostSignalRecordStaged(ctx, roc_host, payload.left, provisional_states, overlay);
                    defer self.dropHostSignalRecordValueWithProvisionalStates(ctx, roc_host, payload.left, left, provisional_states);
                    const right = self.evalHostSignalRecordStaged(ctx, roc_host, payload.right, provisional_states, overlay);
                    defer self.dropHostSignalRecordValueWithProvisionalStates(ctx, roc_host, payload.right, right, provisional_states);
                    self.recordDerivedCall();
                    const left_cap = self.hostSignalRecordCapabilityWithProvisionalStates(ctx, payload.left, provisional_states);
                    const right_cap = self.hostSignalRecordCapabilityWithProvisionalStates(ctx, payload.right, provisional_states);
                    const value = callHostValueHostValueToHostValueWithCapabilities(ctx, roc_host, left_cap, right_cap, payload.transform.toAbi(), left, right);
                    return self.replaceSignalExprCacheAndClone(ctx, &payload.cached_value, roc_host, value, payload.cap);
                },
                .select, .keyed_select => |*payload| {
                    if (payload.false_value == .absent) {
                        const value = erased_calls.callValueInitThunk(roc_host, payload.false_init.toAbi());
                        payload.false_value.replace(ctx, roc_host, &self.pending_roc_metrics, value, payload.cap);
                    }
                    if (payload.true_value == .absent) {
                        const value = erased_calls.callValueInitThunk(roc_host, payload.true_init.toAbi());
                        payload.true_value.replace(ctx, roc_host, &self.pending_roc_metrics, value, payload.cap);
                    }
                    const input = self.evalHostSignalRecordStaged(ctx, roc_host, payload.input, provisional_states, overlay);
                    defer self.dropHostSignalRecordValueWithProvisionalStates(ctx, roc_host, payload.input, input, provisional_states);
                    const selected = callHostValueToStrWithCapability(ctx, roc_host, payload.input_read.capability, payload.input_read.read, input);
                    defer selected.decref(roc_host);
                    const desired = if (std.mem.eql(u8, selected.asSlice(), payload.key)) blk: {
                        break :blk self.cloneCachedSignalValue(ctx, &payload.true_value);
                    } else blk: {
                        break :blk self.cloneCachedSignalValue(ctx, &payload.false_value);
                    };
                    return self.replaceSignalExprCacheAndClone(ctx, &payload.cached_value, roc_host, desired, payload.cap);
                },
                .combine => |*payload| {
                    const allocator = Ctx.allocator(ctx);
                    var values: shared_buffer.List(HostValue) = .empty;
                    errdefer {
                        for (payload.children, values.items) |child, value| {
                            self.dropHostSignalRecordValue(ctx, roc_host, child, value);
                        }
                        values.deinit(allocator);
                    }
                    for (payload.children) |child| {
                        values.append(allocator, self.evalHostSignalRecordStaged(ctx, roc_host, child, provisional_states, overlay)) catch @panic("out of memory");
                    }
                    const list = HostValueList.fromSlice(values.items, roc_host);
                    defer list.decref(roc_host);
                    self.recordDerivedCall();
                    const input_cap = if (payload.children.len == 0) payload.cap else self.hostSignalRecordCapabilityWithProvisionalStates(ctx, payload.children[0], provisional_states);
                    const value = callHostValueListToHostValueWithCapability(ctx, roc_host, input_cap, payload.transform.toAbi(), list);
                    for (payload.children, values.items) |child, child_value| {
                        self.dropHostSignalRecordValueWithProvisionalStates(ctx, roc_host, child, child_value, provisional_states);
                    }
                    values.deinit(allocator);
                    return self.replaceSignalExprCacheAndClone(ctx, &payload.cached_value, roc_host, value, payload.cap);
                },
                .interval_source => |*payload| {
                    return self.evalEffectSourceInitial(ctx, roc_host, &payload.cached_value, payload.initial, payload.cap);
                },
                .location_source => |*payload| {
                    return self.evalLocationSourceInitial(ctx, roc_host, payload);
                },
                .entropy_seed_source => |*payload| {
                    return self.evalEntropySeedSourceInitial(ctx, roc_host, payload);
                },
                .visibility_source => |*payload| {
                    return self.evalVisibilitySourceInitial(ctx, roc_host, payload);
                },
                .online_source => |*payload| {
                    return self.evalOnlineSourceInitial(ctx, roc_host, payload);
                },
                .storage_source => |*payload| {
                    return self.evalStorageSourceInitial(ctx, roc_host, payload);
                },
                .row_source => |*payload| {
                    const slot = if (overlay) |prepared| prepared.readSlot(&payload.cached_value) else &payload.cached_value;
                    if (slot.* == .absent) {
                        const value = self.materializeEachRowItem(ctx, roc_host, payload);
                        return self.replaceSignalExprCacheAndClone(ctx, &payload.cached_value, roc_host, value, payload.cap);
                    }
                    return self.cloneCachedSignalValue(ctx, slot);
                },
            }
        }

        /// Performs eval host signal binding inside the shared engine while preserving transaction and changed-set invariants.
        pub fn evalHostSignalBinding(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, signal: *HostSignalBinding) HostValue {
            return self.evalHostSignalRecord(ctx, roc_host, signal.record);
        }

        fn evalHostSignalBindingWithProvisionalStates(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, signal: *HostSignalBinding, provisional_states: []const HostState) HostValue {
