        /// Performs eval dirty host signal record inside the shared engine while preserving transaction and changed-set invariants.
        pub fn evalDirtyHostSignalRecord(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, record: *HostSignalRecord, dirty_source_node_ids: []const u64, dirty_generation: u64) HostSignalEvalResult {
            if (dirty_generation == 0) @panic("dirty signal evaluation used generation 0");
            debugPhase(ctx, .eval_dirty_signal);
            if (self.cloneMemoizedDirtySignalResult(ctx, record, dirty_generation)) |result| return result;

            switch (record.payload) {
                .ref => |node_id| {
                    debugPhase(ctx, .eval_dirty_ref);
                    return .{
                        .value = Ctx.stateValueByNodeId(ctx, node_id),
                        .changed = u64SliceContains(dirty_source_node_ids, node_id),
                    };
                },
                .const_value => |*payload| {
                    if (payload.cached_value == .absent) {
                        debugPhase(ctx, .eval_dirty_const_initialize);
                        const value = erased_calls.callValueInitThunk(roc_host, payload.init.toAbi());
                        return self.rememberDirtySignalResult(record, dirty_generation, self.updateDirtySignalExprCache(ctx, roc_host, &payload.cached_value, value, payload.cap));
                    }
                    debugPhase(ctx, .eval_dirty_const_cached);
                    return self.rememberDirtySignalResult(record, dirty_generation, .{
                        .value = self.cloneCachedSignalValue(ctx, &payload.cached_value),
                        .changed = false,
                    });
                },
                .map => |*payload| {
                    const cache_was_absent = payload.cached_value == .absent;
                    debugPhase(ctx, .eval_dirty_map_input);
                    const input = self.evalDirtyHostSignalRecord(ctx, roc_host, payload.input, dirty_source_node_ids, dirty_generation);
                    defer self.dropHostSignalRecordValue(ctx, roc_host, payload.input, input.value);
                    if (!input.changed and !cache_was_absent) {
                        debugPhase(ctx, .eval_dirty_map_cached);
                        return self.rememberDirtySignalResult(record, dirty_generation, .{ .value = self.cloneCachedSignalValue(ctx, &payload.cached_value), .changed = false });
                    }

                    self.recordDerivedCall();
                    debugPhase(ctx, .eval_dirty_map_transform);
                    const input_cap = self.hostSignalRecordCapability(ctx, payload.input);
                    const value = callHostValueToHostValueWithCapability(ctx, roc_host, input_cap, payload.transform.toAbi(), input.value);
                    debugPhase(ctx, .eval_dirty_map_cache);
                    return self.rememberDirtySignalResult(record, dirty_generation, self.updateDirtySignalExprCache(ctx, roc_host, &payload.cached_value, value, payload.cap));
                },
                .map2 => |*payload| {
                    const cache_was_absent = payload.cached_value == .absent;
                    debugPhase(ctx, .eval_dirty_map2_left);
                    const left = self.evalDirtyHostSignalRecord(ctx, roc_host, payload.left, dirty_source_node_ids, dirty_generation);
                    defer self.dropHostSignalRecordValue(ctx, roc_host, payload.left, left.value);
                    debugPhase(ctx, .eval_dirty_map2_right);
                    const right = self.evalDirtyHostSignalRecord(ctx, roc_host, payload.right, dirty_source_node_ids, dirty_generation);
                    defer self.dropHostSignalRecordValue(ctx, roc_host, payload.right, right.value);
                    if (!left.changed and !right.changed and !cache_was_absent) {
                        debugPhase(ctx, .eval_dirty_map2_cached);
                        return self.rememberDirtySignalResult(record, dirty_generation, .{ .value = self.cloneCachedSignalValue(ctx, &payload.cached_value), .changed = false });
                    }

                    self.recordDerivedCall();
                    debugPhase(ctx, .eval_dirty_map2_transform);
                    const left_cap = self.hostSignalRecordCapability(ctx, payload.left);
                    const right_cap = self.hostSignalRecordCapability(ctx, payload.right);
                    const value = callHostValueHostValueToHostValueWithCapabilities(ctx, roc_host, left_cap, right_cap, payload.transform.toAbi(), left.value, right.value);
                    debugPhase(ctx, .eval_dirty_map2_cache);
                    return self.rememberDirtySignalResult(record, dirty_generation, self.updateDirtySignalExprCache(ctx, roc_host, &payload.cached_value, value, payload.cap));
                },
                .select, .keyed_select => |*payload| {
                    const cache_was_absent = payload.cached_value == .absent;
                    const input = self.evalDirtyHostSignalRecord(ctx, roc_host, payload.input, dirty_source_node_ids, dirty_generation);
                    defer self.dropHostSignalRecordValue(ctx, roc_host, payload.input, input.value);
                    if (!input.changed and !cache_was_absent) {
                        return self.rememberDirtySignalResult(record, dirty_generation, .{ .value = self.cloneCachedSignalValue(ctx, &payload.cached_value), .changed = false });
                    }
                    if (payload.false_value == .absent or payload.true_value == .absent) @panic("active selector member was not initialized");
                    const selected = callHostValueToStrWithCapability(ctx, roc_host, payload.input_read.capability, payload.input_read.read, input.value);
                    defer selected.decref(roc_host);
                    const desired_slot = if (std.mem.eql(u8, selected.asSlice(), payload.key)) &payload.true_value else &payload.false_value;
                    const desired = self.cloneCachedSignalValue(ctx, desired_slot);
                    return self.rememberDirtySignalResult(record, dirty_generation, self.updateDirtySignalExprCache(ctx, roc_host, &payload.cached_value, desired, payload.cap));
                },
                .combine => |*payload| {
                    const cache_was_absent = payload.cached_value == .absent;
                    const allocator = Ctx.allocator(ctx);
                    var values: shared_buffer.List(HostValue) = .empty;
                    errdefer {
                        for (payload.children[0..values.items.len], values.items) |child, value| {
                            self.dropHostSignalRecordValue(ctx, roc_host, child, value);
                        }
                        values.deinit(allocator);
                    }

                    var any_changed = false;
                    for (payload.children) |child| {
                        debugPhase(ctx, .eval_dirty_combine_child);
                        const child_result = self.evalDirtyHostSignalRecord(ctx, roc_host, child, dirty_source_node_ids, dirty_generation);
                        any_changed = any_changed or child_result.changed;
                        values.append(allocator, child_result.value) catch @panic("out of memory");
                    }

                    if (!any_changed and !cache_was_absent) {
                        debugPhase(ctx, .eval_dirty_combine_cached);
                        for (payload.children, values.items) |child, value| {
                            self.dropHostSignalRecordValue(ctx, roc_host, child, value);
                        }
                        values.deinit(allocator);
                        return self.rememberDirtySignalResult(record, dirty_generation, .{ .value = self.cloneCachedSignalValue(ctx, &payload.cached_value), .changed = false });
                    }

                    const list = HostValueList.fromSlice(values.items, roc_host);
                    defer list.decref(roc_host);
                    self.recordDerivedCall();
                    debugPhase(ctx, .eval_dirty_combine_transform);
                    const input_cap = if (payload.children.len == 0) payload.cap else self.hostSignalRecordCapability(ctx, payload.children[0]);
                    const value = callHostValueListToHostValueWithCapability(ctx, roc_host, input_cap, payload.transform.toAbi(), list);
                    debugPhase(ctx, .eval_dirty_combine_cache);
                    for (payload.children, values.items) |child, child_value| {
                        self.dropHostSignalRecordValue(ctx, roc_host, child, child_value);
                    }
                    values.deinit(allocator);
                    return self.rememberDirtySignalResult(record, dirty_generation, self.updateDirtySignalExprCache(ctx, roc_host, &payload.cached_value, value, payload.cap));
                },
                .row_source => |*payload| {
                    const value = self.materializeEachRowItem(ctx, roc_host, payload);
                    return self.rememberDirtySignalResult(record, dirty_generation, self.updateDirtySignalExprCache(ctx, roc_host, &payload.cached_value, value, payload.cap));
                },
                .interval_source => |*payload| {
                    debugPhase(ctx, .eval_dirty_interval_source);
                    return self.rememberDirtySignalResult(record, dirty_generation, .{
                        .value = self.cloneCachedSignalValue(ctx, &payload.cached_value),
                        .changed = record.last_dirty_generation == dirty_generation and record.last_dirty_changed,
                    });
                },
                .entropy_seed_source => |*payload| {
                    return self.rememberDirtySignalResult(record, dirty_generation, .{
                        .value = self.cloneCachedSignalValue(ctx, &payload.cached_value),
                        .changed = false,
                    });
                },
                .location_source => |*payload| {
                    debugPhase(ctx, .eval_dirty_location_source);
                    return self.rememberDirtySignalResult(record, dirty_generation, .{
                        .value = self.cloneCachedSignalValue(ctx, &payload.cached_value),
                        .changed = record.last_dirty_generation == dirty_generation and record.last_dirty_changed,
                    });
                },
                .visibility_source => |*payload| {
                    debugPhase(ctx, .eval_dirty_visibility_source);
                    return self.rememberDirtySignalResult(record, dirty_generation, .{
                        .value = self.cloneCachedSignalValue(ctx, &payload.cached_value),
                        .changed = record.last_dirty_generation == dirty_generation and record.last_dirty_changed,
                    });
                },
                .online_source => |*payload| {
                    debugPhase(ctx, .eval_dirty_online_source);
                    return self.rememberDirtySignalResult(record, dirty_generation, .{
                        .value = self.cloneCachedSignalValue(ctx, &payload.cached_value),
                        .changed = record.last_dirty_generation == dirty_generation and record.last_dirty_changed,
                    });
                },
                .storage_source => |*payload| {
                    debugPhase(ctx, .eval_dirty_storage_source);
                    return self.rememberDirtySignalResult(record, dirty_generation, .{
                        .value = self.cloneCachedSignalValue(ctx, &payload.cached_value),
                        .changed = record.last_dirty_generation == dirty_generation and record.last_dirty_changed,
                    });
                },
            }
        }

        fn evalPreparedDirtyHostSignalRecord(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, overlay: *signal_records.PreparedCacheUpdates, record: *HostSignalRecord, dirty_source_node_ids: []const u64, dirty_generation: u64) CollectionError!HostSignalEvalResult {
            if (dirty_generation == 0) @panic("prepared dirty signal evaluation used generation 0");
            const evaluation_key = signal_records.EvaluationKey.fromRecord(record);
            if (overlay.rememberedResult(evaluation_key)) |changed| {
                const slot = record.cachedSlot() orelse switch (record.payload) {
                    .ref => |node_id| return .{
                        .value = if (overlay.provisionalValue(evaluation_key)) |cell| Ctx.cloneHostValue(ctx, cell.value) else Ctx.stateValueByNodeId(ctx, node_id),
                        .changed = changed,
                    },
                    else => unreachable,
                };
                return .{ .value = self.cloneCachedSignalValue(ctx, overlay.readSlot(slot)), .changed = changed };
            }

            const result: HostSignalEvalResult = switch (record.payload) {
                .ref => |node_id| .{
                    .value = if (overlay.provisionalValue(evaluation_key)) |cell| Ctx.cloneHostValue(ctx, cell.value) else Ctx.stateValueByNodeId(ctx, node_id),
                    .changed = u64SliceContains(dirty_source_node_ids, node_id),
                },
                .const_value => |*payload| blk: {
                    const slot = overlay.readSlot(&payload.cached_value);
                    if (slot.* != .absent) break :blk .{ .value = self.cloneCachedSignalValue(ctx, slot), .changed = false };
                    const value = erased_calls.callValueInitThunk(roc_host, payload.init.toAbi());
                    break :blk self.updatePreparedDirtySignalExprCache(ctx, roc_host, overlay, &payload.cached_value, value, payload.cap);
                },
                .map => |*payload| blk: {
                    const input = try self.evalPreparedDirtyHostSignalRecord(ctx, roc_host, overlay, payload.input, dirty_source_node_ids, dirty_generation);
                    defer self.dropHostSignalRecordValue(ctx, roc_host, payload.input, input.value);
                    const slot = overlay.readSlot(&payload.cached_value);
                    if (!input.changed and slot.* != .absent) break :blk .{ .value = self.cloneCachedSignalValue(ctx, slot), .changed = false };
                    overlay.derived_calls += 1;
                    const value = callHostValueToHostValueWithCapability(ctx, roc_host, self.hostSignalRecordCapability(ctx, payload.input), payload.transform.toAbi(), input.value);
                    break :blk self.updatePreparedDirtySignalExprCache(ctx, roc_host, overlay, &payload.cached_value, value, payload.cap);
                },
                .map2 => |*payload| blk: {
                    const left = try self.evalPreparedDirtyHostSignalRecord(ctx, roc_host, overlay, payload.left, dirty_source_node_ids, dirty_generation);
                    defer self.dropHostSignalRecordValue(ctx, roc_host, payload.left, left.value);
                    const right = try self.evalPreparedDirtyHostSignalRecord(ctx, roc_host, overlay, payload.right, dirty_source_node_ids, dirty_generation);
                    defer self.dropHostSignalRecordValue(ctx, roc_host, payload.right, right.value);
                    const slot = overlay.readSlot(&payload.cached_value);
                    if (!left.changed and !right.changed and slot.* != .absent) break :blk .{ .value = self.cloneCachedSignalValue(ctx, slot), .changed = false };
                    overlay.derived_calls += 1;
                    const value = callHostValueHostValueToHostValueWithCapabilities(ctx, roc_host, self.hostSignalRecordCapability(ctx, payload.left), self.hostSignalRecordCapability(ctx, payload.right), payload.transform.toAbi(), left.value, right.value);
                    break :blk self.updatePreparedDirtySignalExprCache(ctx, roc_host, overlay, &payload.cached_value, value, payload.cap);
                },
                .select, .keyed_select => |*payload| blk: {
                    const input = try self.evalPreparedDirtyHostSignalRecord(ctx, roc_host, overlay, payload.input, dirty_source_node_ids, dirty_generation);
                    defer self.dropHostSignalRecordValue(ctx, roc_host, payload.input, input.value);
                    const slot = overlay.readSlot(&payload.cached_value);
                    if (!input.changed and slot.* != .absent) break :blk .{ .value = self.cloneCachedSignalValue(ctx, slot), .changed = false };
                    if (payload.false_value == .absent or payload.true_value == .absent) return error.InvalidDescriptor;
                    const selected = callHostValueToStrWithCapability(ctx, roc_host, payload.input_read.capability, payload.input_read.read, input.value);
                    defer selected.decref(roc_host);
                    const desired_slot = if (std.mem.eql(u8, selected.asSlice(), payload.key)) &payload.true_value else &payload.false_value;
                    const desired = self.cloneCachedSignalValue(ctx, desired_slot);
                    break :blk self.updatePreparedDirtySignalExprCache(ctx, roc_host, overlay, &payload.cached_value, desired, payload.cap);
                },
                .combine => |*payload| blk: {
                    const allocator = Ctx.allocator(ctx);
                    var values = shared_buffer.List(HostValue).empty;
                    errdefer {
                        for (payload.children[0..values.items.len], values.items) |child, value| self.dropHostSignalRecordValue(ctx, roc_host, child, value);
                        values.deinit(allocator);
                    }
                    values.ensureTotalCapacity(allocator, payload.children.len) catch return error.OutOfMemory;
                    var any_changed = false;
                    for (payload.children) |child| {
                        const child_result = try self.evalPreparedDirtyHostSignalRecord(ctx, roc_host, overlay, child, dirty_source_node_ids, dirty_generation);
                        any_changed = any_changed or child_result.changed;
                        values.appendAssumeCapacity(child_result.value);
                    }
                    const slot = overlay.readSlot(&payload.cached_value);
                    if (!any_changed and slot.* != .absent) {
                        for (payload.children, values.items) |child, value| self.dropHostSignalRecordValue(ctx, roc_host, child, value);
                        values.deinit(allocator);
                        break :blk .{ .value = self.cloneCachedSignalValue(ctx, slot), .changed = false };
                    }
                    const list = HostValueList.fromSlice(values.items, roc_host);
                    defer list.decref(roc_host);
                    overlay.derived_calls += 1;
                    const input_cap = if (payload.children.len == 0) payload.cap else self.hostSignalRecordCapability(ctx, payload.children[0]);
                    const value = callHostValueListToHostValueWithCapability(ctx, roc_host, input_cap, payload.transform.toAbi(), list);
                    for (payload.children, values.items) |child, child_value| self.dropHostSignalRecordValue(ctx, roc_host, child, child_value);
                    values.deinit(allocator);
                    break :blk self.updatePreparedDirtySignalExprCache(ctx, roc_host, overlay, &payload.cached_value, value, payload.cap);
                },
                .interval_source => |*payload| .{ .value = self.cloneCachedSignalValue(ctx, overlay.readSlot(&payload.cached_value)), .changed = false },
                .entropy_seed_source => |*payload| .{ .value = self.cloneCachedSignalValue(ctx, overlay.readSlot(&payload.cached_value)), .changed = false },
                .location_source => |*payload| .{ .value = self.cloneCachedSignalValue(ctx, overlay.readSlot(&payload.cached_value)), .changed = false },
                .visibility_source => |*payload| .{ .value = self.cloneCachedSignalValue(ctx, overlay.readSlot(&payload.cached_value)), .changed = false },
                .online_source => |*payload| .{ .value = self.cloneCachedSignalValue(ctx, overlay.readSlot(&payload.cached_value)), .changed = false },
                .storage_source => |*payload| .{ .value = self.cloneCachedSignalValue(ctx, overlay.readSlot(&payload.cached_value)), .changed = false },
                .row_source => |*payload| blk: {
                    const value = self.materializeEachRowItem(ctx, roc_host, payload);
                    break :blk self.updatePreparedDirtySignalExprCache(ctx, roc_host, overlay, &payload.cached_value, value, payload.cap);
                },
            };
            return self.rememberPreparedDirtySignalResult(overlay, record, dirty_generation, result);
        }

        /// Performs eval dirty host signal binding inside the shared engine while preserving transaction and changed-set invariants.
        pub fn evalDirtyHostSignalBinding(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, signal: *HostSignalBinding, dirty_source_node_ids: []const u64, dirty_generation: u64) HostSignalEvalResult {
            return self.evalDirtyHostSignalRecord(ctx, roc_host, signal.record, dirty_source_node_ids, dirty_generation);
        }

        /// Returns a borrowed slice backed by engine scratch. Callers must not free
        /// it, and it stays valid only until the next dirty propagation.
        pub fn propagateDirtyActiveSignals(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, allocator: std.mem.Allocator, dirty_source_node_ids: []const u64, dirty_generation: u64) []const u64 {
            if (!builtin.is_test) @compileError("propagateDirtyActiveSignals is a pre-transactional engine path kept only for tests; production goes through prepared transactions");
            self.identity_reuse_barrier = dirty_generation;
            _ = allocator;
            const dirty_record_ids = self.scratchDirtyActiveSignalRecordIdsForSources(ctx, dirty_source_node_ids);
            return self.propagateDirtyActiveSignalRecordIds(ctx, roc_host, dirty_record_ids, dirty_source_node_ids, dirty_generation);
        }

        /// Returns a borrowed slice backed by engine scratch. Callers must not free
        /// it, and it stays valid only until the next dirty propagation.
        pub fn propagateDirtyActiveSignalRecordIds(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, dirty_record_ids: []const u64, dirty_source_node_ids: []const u64, dirty_generation: u64) []const u64 {
            const allocator = Ctx.allocator(ctx);
            var changed_record_ids = &self.scratch.dirty_changed_record_ids;
            changed_record_ids.clearRetainingCapacity();

            for (dirty_record_ids) |record_id| {
                const record = self.active_signal_graph.items[@intCast(record_id)].record;
                debugPhase(ctx, .propagate_record_before_eval);
                const result = self.evalDirtyHostSignalRecord(ctx, roc_host, record, dirty_source_node_ids, dirty_generation);
                if (result.changed) {
                    changed_record_ids.append(allocator, record_id) catch @panic("out of memory");
                }
                debugPhase(ctx, .propagate_record_before_drop);
                self.dropHostSignalRecordValue(ctx, roc_host, record, result.value);
            }

            return changed_record_ids.items;
        }

        /// Evaluates `dirty_record_ids` in the order given - which must already
        /// be rank order - against `overlay`, and returns the ids whose value
        /// moved, in that same order.
        ///
        /// Nothing observable happens here: recomputed values are staged in the
        /// overlay and dirty stamps are memoized in it, so the engine still
        /// holds its previous state until `commitPreparedDirtySignalCaches`
        /// publishes that overlay. Destroying the overlay instead aborts the
        /// transaction and leaves no trace of it. The overlay must therefore
        /// outlive both this call and every later stage that reads through it,
        /// and it must have been reserved for at least this graph's cache slots
        /// because staging is allocation-free by construction.
        ///
        /// The returned slice is owned by the caller and allocated from
        /// `Ctx.allocator(ctx)`; it must be freed whether the transaction
        /// commits or aborts.
        pub fn prepareChangedActiveSignalRecordIds(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, overlay: *signal_records.PreparedCacheUpdates, dirty_record_ids: []const u64, dirty_source_node_ids: []const u64, dirty_generation: u64) CollectionError![]u64 {
            const allocator = Ctx.allocator(ctx);
            var changed = shared_buffer.List(u64).empty;
            errdefer changed.deinit(allocator);
            changed.ensureTotalCapacity(allocator, self.active_signal_graph.items.len) catch return error.OutOfMemory;
            var changed_set = &self.scratch.dirty_changed_record_id_set;
            changed_set.clearRetainingCapacity();
            changed_set.ensureTotalCapacity(allocator, std.math.cast(u32, self.active_signal_graph.items.len) orelse return error.ResourceLimit) catch return error.OutOfMemory;
            var selector_roots = &self.scratch.selector_dirty_roots;
            selector_roots.clearRetainingCapacity();
            selector_roots.ensureTotalCapacity(allocator, self.active_signal_graph.items.len) catch return error.OutOfMemory;
            for (dirty_record_ids) |record_id| {
                if (record_id >= self.active_signal_graph.items.len) return error.ResourceLimit;
                const record = self.active_signal_graph.items[@intCast(record_id)].record;
                const result = try self.evalPreparedDirtyHostSignalRecord(ctx, roc_host, overlay, record, dirty_source_node_ids, dirty_generation);
                if (result.changed) {
                    changed.appendAssumeCapacity(record_id);
                    changed_set.putAssumeCapacity(record_id, {});
                }
                self.dropHostSignalRecordValue(ctx, roc_host, record, result.value);
            }

            const ordinary_changed_len = changed.items.len;
            for (changed.items[0..ordinary_changed_len]) |record_id| {
                const input_record = self.active_signal_graph.items[@intCast(record_id)].record;
                const member = self.selectors.anyMember(input_record) orelse continue;
                const selector = switch (member.payload) {
                    .select, .keyed_select => |*payload| payload,
                    else => return error.InvalidDescriptor,
                };

                const old_value = switch (input_record.payload) {
                    .ref => |node_id| Ctx.stateValueByNodeId(ctx, node_id),
                    else => self.cloneCachedSignalValue(ctx, input_record.cachedSlot() orelse return error.InvalidDescriptor),
                };
                defer self.dropHostSignalRecordValue(ctx, roc_host, input_record, old_value);
                const next_result = try self.evalPreparedDirtyHostSignalRecord(ctx, roc_host, overlay, input_record, dirty_source_node_ids, dirty_generation);
                defer self.dropHostSignalRecordValue(ctx, roc_host, input_record, next_result.value);
                const old_key = callHostValueToStrWithCapability(ctx, roc_host, selector.input_read.capability, selector.input_read.read, old_value);
                defer old_key.decref(roc_host);
                const next_key = callHostValueToStrWithCapability(ctx, roc_host, selector.input_read.capability, selector.input_read.read, next_result.value);
                defer next_key.decref(roc_host);
                if (std.mem.eql(u8, old_key.asSlice(), next_key.asSlice())) continue;

                const member_sets = [_][]const *HostSignalRecord{
                    self.selectors.membersForKey(input_record, old_key.asSlice()),
                    self.selectors.membersForKey(input_record, next_key.asSlice()),
                };
                for (member_sets) |members| for (members) |selector_member| {
                    const member_id = selector_member.active_graph_id orelse return error.InvalidDescriptor;
                    selector_roots.appendAssumeCapacity(member_id);
                };
            }

            overlay.selector_members_dirtied = std.math.add(u64, overlay.selector_members_dirtied, std.math.cast(u64, selector_roots.items.len) orelse return error.ResourceLimit) catch return error.ResourceLimit;
            if (selector_roots.items.len != 0) {
                const selector_dirty_ids = self.scratchDirtyActiveSignalRecordIdsForRoots(ctx, selector_roots.items);
                for (selector_dirty_ids) |record_id| {
                    const record = self.active_signal_graph.items[@intCast(record_id)].record;
                    const result = try self.evalPreparedDirtyHostSignalRecord(ctx, roc_host, overlay, record, dirty_source_node_ids, dirty_generation);
                    if (result.changed) {
                        const entry = changed_set.getOrPutAssumeCapacity(record_id);
                        if (!entry.found_existing) changed.appendAssumeCapacity(record_id);
                    }
                    self.dropHostSignalRecordValue(ctx, roc_host, record, result.value);
                }
            }
            return changed.toOwnedSlice(allocator) catch return error.OutOfMemory;
        }

        fn addPreparedCustomAttrsForElem(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, overlay: *const signal_records.PreparedCacheUpdates, splice: *render_cache_mod.PreparedRenderSplice(Ctx), elem_id: u64) CollectionError!void {
            const allocator = Ctx.allocator(ctx);
            var descriptor_count = std.math.add(usize, self.active_stream.static_custom_text_attrs.items.len, self.active_stream.signal_custom_text_attrs.items.len) catch return error.ResourceLimit;
            descriptor_count = std.math.add(usize, descriptor_count, self.active_stream.signal_optional_custom_text_attrs.items.len) catch return error.ResourceLimit;
            descriptor_count = std.math.add(usize, descriptor_count, self.active_stream.static_custom_bool_attrs.items.len) catch return error.ResourceLimit;
            descriptor_count = std.math.add(usize, descriptor_count, self.active_stream.signal_custom_bool_attrs.items.len) catch return error.ResourceLimit;
            var attrs = shared_buffer.List(render_cache_mod.CustomTextAttr).empty;
            defer attrs.deinit(allocator);
            attrs.ensureTotalCapacity(allocator, descriptor_count) catch return error.OutOfMemory;
            var owned_text = shared_buffer.List(abi.RocStr).empty;
            defer {
                for (owned_text.items) |*text| text.decref(roc_host);
                owned_text.deinit(allocator);
            }
            owned_text.ensureTotalCapacity(allocator, descriptor_count) catch return error.OutOfMemory;
            for (self.active_stream.static_custom_text_attrs.items) |desc| if (desc.elem_id.raw() == elem_id) attrs.appendAssumeCapacity(.{ .name = desc.name, .value = desc.value });
            for (self.active_stream.signal_custom_text_attrs.items) |*desc| if (desc.elem_id.raw() == elem_id) {
                const slot = overlay.readSlot(&desc.cached_value);
                if (slot.* != .present) return error.InvalidDescriptor;
                const value = callHostValueToStrWithCapability(ctx, roc_host, desc.read.capability, desc.read.read, slot.present.value);
                owned_text.appendAssumeCapacity(value);
                attrs.appendAssumeCapacity(.{ .name = desc.name, .value = owned_text.items[owned_text.items.len - 1].asSlice() });
            };
            for (self.active_stream.signal_optional_custom_text_attrs.items) |*desc| if (desc.elem_id.raw() == elem_id) {
                const slot = overlay.readSlot(&desc.cached_value);
                if (slot.* != .present) return error.InvalidDescriptor;
                if (!callHostValueToBoolWithCapability(ctx, roc_host, desc.present.capability, desc.present.read, slot.present.value)) continue;
                const value = callHostValueToStrWithCapability(ctx, roc_host, desc.read.capability, desc.read.read, slot.present.value);
                owned_text.appendAssumeCapacity(value);
                attrs.appendAssumeCapacity(.{ .name = desc.name, .value = owned_text.items[owned_text.items.len - 1].asSlice() });
            };
            for (self.active_stream.static_custom_bool_attrs.items) |desc| if (desc.elem_id.raw() == elem_id and desc.value) attrs.appendAssumeCapacity(.{ .name = desc.name, .value = "" });
            for (self.active_stream.signal_custom_bool_attrs.items) |*desc| if (desc.elem_id.raw() == elem_id) {
                const slot = overlay.readSlot(&desc.cached_value);
                if (slot.* != .present) return error.InvalidDescriptor;
                if (callHostValueToBoolWithCapability(ctx, roc_host, desc.read.capability, desc.read.read, slot.present.value)) attrs.appendAssumeCapacity(.{ .name = desc.name, .value = "" });
            };
            splice.addCustomAttrs(&self.render_cache, ids.ElemId.fromRaw(elem_id), attrs.items) catch |err| return renderSpliceError(err);
        }

        fn prepareNonStructuralRenderSplice(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, overlay: *signal_records.PreparedCacheUpdates, changed_record_ids: []const u64, dirty_source_node_ids: []const u64, dirty_generation: u64) CollectionError!render_cache_mod.PreparedRenderSplice(Ctx) {
            var text_count: usize = 0;
            var bool_count: usize = 0;
            const allocator = Ctx.allocator(ctx);
            var custom_elem_ids = shared_buffer.List(u64).empty;
            defer custom_elem_ids.deinit(allocator);
            var custom_route_upper: usize = 0;
            for (changed_record_ids) |record_id| {
                const index = std.math.cast(usize, record_id) orelse return error.ResourceLimit;
                if (index < self.active_text_signal_routes.items.len) custom_route_upper = std.math.add(usize, custom_route_upper, self.active_text_signal_routes.items[index].len()) catch return error.ResourceLimit;
                if (index < self.active_bool_signal_routes.items.len) custom_route_upper = std.math.add(usize, custom_route_upper, self.active_bool_signal_routes.items[index].len()) catch return error.ResourceLimit;
            }
            custom_elem_ids.ensureTotalCapacity(allocator, custom_route_upper) catch return error.OutOfMemory;
            for (changed_record_ids) |record_id| {
                const index = std.math.cast(usize, record_id) orelse return error.ResourceLimit;
                if (index < self.active_text_signal_routes.items.len) for (self.active_text_signal_routes.items[index].slice()) |route| switch (route.kind) {
                    .text_node, .text_attr => text_count = std.math.add(usize, text_count, 1) catch return error.ResourceLimit,
                    .custom_text_attr => {
                        if (route.index >= self.active_stream.signal_custom_text_attrs.items.len) return error.ResourceLimit;
                        const elem_id = self.active_stream.signal_custom_text_attrs.items[route.index].elem_id;
                        if (!u64SliceContains(custom_elem_ids.items, elem_id.raw())) custom_elem_ids.appendAssumeCapacity(elem_id.raw());
                    },
                    .custom_text_optional_attr => {
                        if (route.index >= self.active_stream.signal_optional_custom_text_attrs.items.len) return error.ResourceLimit;
                        const elem_id = self.active_stream.signal_optional_custom_text_attrs.items[route.index].elem_id;
                        if (!u64SliceContains(custom_elem_ids.items, elem_id.raw())) custom_elem_ids.appendAssumeCapacity(elem_id.raw());
                    },
                };
                if (index < self.active_bool_signal_routes.items.len) for (self.active_bool_signal_routes.items[index].slice()) |route| switch (route.kind) {
                    .bool_attr => bool_count = std.math.add(usize, bool_count, 1) catch return error.ResourceLimit,
                    .custom_bool_attr => {
                        if (route.index >= self.active_stream.signal_custom_bool_attrs.items.len) return error.ResourceLimit;
                        const elem_id = self.active_stream.signal_custom_bool_attrs.items[route.index].elem_id;
                        if (!u64SliceContains(custom_elem_ids.items, elem_id.raw())) custom_elem_ids.appendAssumeCapacity(elem_id.raw());
                    },
                };
            }
            var wire_count = std.math.add(usize, text_count, bool_count) catch return error.ResourceLimit;
            for (custom_elem_ids.items) |elem_id| {
                const cache_index = std.math.cast(usize, elem_id) orelse return error.ResourceLimit;
                const old_count = if (cache_index < self.render_cache.nodes.items.len and self.render_cache.nodes.items[cache_index].isActive()) self.render_cache.nodes.items[cache_index].custom_text_attrs.items.len else 0;
                wire_count = std.math.add(usize, wire_count, old_count) catch return error.ResourceLimit;
                wire_count = std.math.add(usize, wire_count, self.active_stream.customAttrIndices(ids.ElemId.fromRaw(elem_id)).len) catch return error.ResourceLimit;
            }
            var splice = render_cache_mod.PreparedRenderSplice(Ctx).init(Ctx.allocator(ctx), &self.render_cache, .{
                .node_capacity = self.render_cache.nodes.items.len,
                .new_tags = 0,
                .text_fields = text_count,
                .bool_fields = bool_count,
                .custom_attrs = custom_elem_ids.items.len,
                .custom_attr_wire_edits = wire_count - text_count - bool_count,
                .wire_commands = wire_count,
            }) catch |err| switch (err) {
                error.OutOfMemory => return error.OutOfMemory,
                error.ResourceLimit => return error.ResourceLimit,
            };
            errdefer splice.deinit();
            for (changed_record_ids) |record_id| {
                const index: usize = @intCast(record_id);
                if (index < self.active_text_signal_routes.items.len) for (self.active_text_signal_routes.items[index].slice()) |route| {
                    const desc_cache: *HostSignalCacheSlot, const binding: *HostSignalBinding, const read: HostTextRead, const elem_id: u64, const field: ?RenderTextField = switch (route.kind) {
                        .text_node => blk: {
                            const desc = &self.active_stream.signal_text_nodes.items[route.index];
                            break :blk .{ &desc.cached_value, &desc.signal, desc.read, desc.elem_id.raw(), .text };
                        },
                        .text_attr => blk: {
                            const desc = &self.active_stream.signal_text_attrs.items[route.index];
                            break :blk .{ &desc.cached_value, &desc.signal, desc.read, desc.elem_id.raw(), desc.field };
                        },
                        .custom_text_attr => blk: {
                            const desc = &self.active_stream.signal_custom_text_attrs.items[route.index];
                            break :blk .{ &desc.cached_value, &desc.signal, desc.read, desc.elem_id.raw(), null };
                        },
                        .custom_text_optional_attr => blk: {
                            const desc = &self.active_stream.signal_optional_custom_text_attrs.items[route.index];
                            break :blk .{ &desc.cached_value, &desc.signal, desc.read, desc.elem_id.raw(), null };
                        },
                    };
                    const signal_result = try self.evalPreparedDirtyHostSignalRecord(ctx, roc_host, overlay, binding.record, dirty_source_node_ids, dirty_generation);
                    const cap = self.hostSignalBindingCapability(ctx, binding);
                    if (!signal_result.changed) {
                        self.dropHostSignalRecordValue(ctx, roc_host, binding.record, signal_result.value);
                        continue;
                    }
                    const cache_result = self.updatePreparedDirtySignalExprCache(ctx, roc_host, overlay, desc_cache, signal_result.value, cap);
                    if (!cache_result.changed) {
                        self.dropHostSignalRecordValue(ctx, roc_host, binding.record, cache_result.value);
                        continue;
                    }
                    self.dropHostSignalRecordValue(ctx, roc_host, binding.record, cache_result.value);
                    if (field) |text_field| {
                        const slot = overlay.readSlot(desc_cache);
                        if (slot.* != .present) return error.InvalidDescriptor;
                        const text = callHostValueToStrWithCapability(ctx, roc_host, read.capability, read.read, slot.present.value);
                        defer text.decref(roc_host);
                        splice.addTextField(&self.render_cache, ids.ElemId.fromRaw(elem_id), text_field, text.asSlice()) catch |err| return renderSpliceError(err);
                    }
                };
                if (index < self.active_bool_signal_routes.items.len) for (self.active_bool_signal_routes.items[index].slice()) |route| {
                    const desc_cache: *HostSignalCacheSlot, const binding: *HostSignalBinding, const read: HostBoolRead, const elem_id: u64, const field: ?RenderBoolField = switch (route.kind) {
                        .bool_attr => blk: {
                            const desc = &self.active_stream.signal_bool_attrs.items[route.index];
                            break :blk .{ &desc.cached_value, &desc.signal, desc.read, desc.elem_id.raw(), desc.field };
                        },
                        .custom_bool_attr => blk: {
                            const desc = &self.active_stream.signal_custom_bool_attrs.items[route.index];
                            break :blk .{ &desc.cached_value, &desc.signal, desc.read, desc.elem_id.raw(), null };
                        },
                    };
                    const signal_result = try self.evalPreparedDirtyHostSignalRecord(ctx, roc_host, overlay, binding.record, dirty_source_node_ids, dirty_generation);
                    const cap = self.hostSignalBindingCapability(ctx, binding);
                    if (!signal_result.changed) {
                        self.dropHostSignalRecordValue(ctx, roc_host, binding.record, signal_result.value);
                        continue;
                    }
                    const cache_result = self.updatePreparedDirtySignalExprCache(ctx, roc_host, overlay, desc_cache, signal_result.value, cap);
                    if (!cache_result.changed) {
                        self.dropHostSignalRecordValue(ctx, roc_host, binding.record, cache_result.value);
                        continue;
                    }
                    self.dropHostSignalRecordValue(ctx, roc_host, binding.record, cache_result.value);
                    if (field) |bool_field| {
                        const slot = overlay.readSlot(desc_cache);
                        if (slot.* != .present) return error.InvalidDescriptor;
                        const value = callHostValueToBoolWithCapability(ctx, roc_host, read.capability, read.read, slot.present.value);
                        splice.addBoolField(&self.render_cache, ids.ElemId.fromRaw(elem_id), bool_field, value) catch |err| return renderSpliceError(err);
                    }
                };
            }
            for (custom_elem_ids.items) |elem_id| try self.addPreparedCustomAttrsForElem(ctx, roc_host, overlay, &splice, elem_id);
            return splice;
        }

        fn collectPreparedDirtyStructuralSignals(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, allocator: std.mem.Allocator, overlay: *signal_records.PreparedCacheUpdates, changed_record_ids: []const u64, dirty_source_node_ids: []const u64, dirty_generation: u64) CollectionError![]HostDirtyStructuralSignal {
            var route_count: usize = 0;
            for (changed_record_ids) |record_id| {
                const index = std.math.cast(usize, record_id) orelse return error.ResourceLimit;
                if (index < self.active_structural_signal_routes.items.len) route_count = std.math.add(usize, route_count, self.active_structural_signal_routes.items[index].len()) catch return error.ResourceLimit;
            }
            var changes = shared_buffer.List(HostDirtyStructuralSignal).empty;
            errdefer changes.deinit(allocator);
            changes.ensureTotalCapacity(allocator, route_count) catch return error.OutOfMemory;

            for (changed_record_ids) |record_id| {
                const index: usize = @intCast(record_id);
                if (index >= self.active_structural_signal_routes.items.len) continue;
                for (self.active_structural_signal_routes.items[index].slice()) |route| switch (route.kind) {
                    .when => {
                        const desc = &self.active_stream.whens.items[route.index];
                        const site = self.activeScopeSiteByNodeId(desc.node_id.raw(), .when) orelse return error.InvalidDescriptor;
                        const result = try self.evalPreparedDirtyHostSignalRecord(ctx, roc_host, overlay, desc.condition.record, dirty_source_node_ids, dirty_generation);
                        const cap = self.hostSignalBindingCapability(ctx, &desc.condition);
                        assertHostValueCapabilitiesMatch(desc.ops.case_capability, cap, "prepared when case capability did not match its signal value");
                        if (!result.changed) {
                            self.dropHostSignalRecordValue(ctx, roc_host, desc.condition.record, result.value);
                            continue;
                        }
                        const cached = self.updatePreparedDirtySignalExprCache(ctx, roc_host, overlay, &desc.cached_value, result.value, cap);
                        defer self.dropHostSignalRecordValue(ctx, roc_host, desc.condition.record, cached.value);
                        if (!cached.changed) continue;
                        changes.appendAssumeCapacity(.{
                            .kind = .when,
                            .node_id = desc.node_id,
                            .scope_id = site.scope_id,
                            .ordinal = site.ordinal,
                            .record = desc.condition.record,
                            .branch = ((try self.activeWhenBranch(site.scope_id, site.ordinal)) orelse return error.InvalidScope).opposite(),
                            .cache_staged_in_overlay = true,
                        });
                    },
                    .each => {
                        const desc = &self.active_stream.eaches.items[route.index];
                        const site = self.activeScopeSiteByNodeId(desc.node_id.raw(), .each) orelse return error.InvalidDescriptor;
                        const result = try self.evalPreparedDirtyHostSignalRecord(ctx, roc_host, overlay, desc.items.record, dirty_source_node_ids, dirty_generation);
                        const cap = self.hostSignalBindingCapability(ctx, &desc.items);
                        if (!result.changed) {
                            self.dropHostSignalRecordValue(ctx, roc_host, desc.items.record, result.value);
                            continue;
                        }
                        const cached = self.updatePreparedDirtySignalExprCache(ctx, roc_host, overlay, &desc.cached_value, result.value, cap);
                        self.dropHostSignalRecordValue(ctx, roc_host, desc.items.record, cached.value);
                        if (!cached.changed) continue;
                        changes.appendAssumeCapacity(.{
                            .kind = .each,
                            .node_id = desc.node_id,
                            .scope_id = site.scope_id,
                            .ordinal = site.ordinal,
                            .record = desc.items.record,
                            .cache_staged_in_overlay = true,
                        });
                    },
                };
            }
            return changes.toOwnedSlice(allocator) catch return error.OutOfMemory;
        }

        fn prepareOnChangeCommands(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, overlay: *signal_records.PreparedCacheUpdates, changed_record_ids: []const u64, dirty_source_node_ids: []const u64, dirty_generation: u64, pending: *shared_buffer.List(HostPendingOnChangeCommand)) CollectionError!void {
            const allocator = Ctx.allocator(ctx);
            var expected: usize = 0;
            for (changed_record_ids) |record_id| {
                const index = std.math.cast(usize, record_id) orelse return error.ResourceLimit;
                if (index < self.active_change_signal_routes.items.len) expected = std.math.add(usize, expected, self.active_change_signal_routes.items[index].len()) catch return error.ResourceLimit;
            }
            const total_expected = std.math.add(usize, pending.items.len, expected) catch return error.ResourceLimit;
            pending.ensureTotalCapacity(allocator, total_expected) catch return error.OutOfMemory;
            for (changed_record_ids) |record_id| {
                const index: usize = @intCast(record_id);
                if (index >= self.active_change_signal_routes.items.len) continue;
                for (self.active_change_signal_routes.items[index].slice()) |route| {
                    const desc = &self.active_stream.on_changes.items[route.index];
                    const result = try self.evalPreparedDirtyHostSignalRecord(ctx, roc_host, overlay, desc.signal.record, dirty_source_node_ids, dirty_generation);
                    const cap = self.hostSignalBindingCapability(ctx, &desc.signal);
                    if (!result.changed) {
                        self.dropHostSignalRecordValue(ctx, roc_host, desc.signal.record, result.value);
                        continue;
                    }
                    const cached = self.updatePreparedDirtySignalExprCache(ctx, roc_host, overlay, &desc.cached_value, result.value, cap);
                    defer self.dropHostSignalRecordValue(ctx, roc_host, desc.signal.record, cached.value);
                    if (!cached.changed) continue;
                    const cmd = callHostValueToCmdWithCapability(ctx, roc_host, cap, desc.to_cmd.toAbi(), cached.value);
                    cmd.incref(1);
                    cmd.decref(roc_host);
                    pending.appendAssumeCapacity(.{ .scope_id = desc.scope_id.raw(), .cmd = cmd, .on_change_index = route.index });
                }
            }
        }

        /// Collects dirty structural signals from the explicitly affected graph or scope set.
        pub fn collectDirtyStructuralSignals(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, allocator: std.mem.Allocator, dirty_source_node_ids: []const u64, changed_record_ids: []const u64, dirty_generation: u64) []HostDirtyStructuralSignal {
            var dirty_structural_signals: shared_buffer.List(HostDirtyStructuralSignal) = .empty;
            errdefer {
                for (dirty_structural_signals.items) |*change| change.abortPendingWhenCache(ctx, roc_host, &self.pending_roc_metrics);
                dirty_structural_signals.deinit(allocator);
            }

            for (changed_record_ids) |record_id| {
                const route_index: usize = @intCast(record_id);
                if (route_index >= self.active_structural_signal_routes.items.len) continue;

                for (self.active_structural_signal_routes.items[route_index].slice()) |route| {
                    switch (route.kind) {
                        .when => {
                            const desc = &self.active_stream.whens.items[route.index];
                            const site = self.activeScopeSiteByNodeId(desc.node_id.raw(), .when) orelse @panic("active when descriptor had no scope site");
                            const result = self.evalDirtyHostSignalBinding(ctx, roc_host, &desc.condition, dirty_source_node_ids, dirty_generation);
                            const cap = self.hostSignalBindingCapability(ctx, &desc.condition);
                            assertHostValueCapabilitiesMatch(desc.ops.case_capability, cap, "dirty when case capability did not match its signal value");
                            if (!result.changed) {
                                callHostValueToUnitWithCapability(ctx, roc_host, cap, hv.hostValueCapabilityDrop(cap), result.value);
                                continue;
                            }
                            const active_branch = (self.activeWhenBranch(site.scope_id, site.ordinal) catch @panic("active when scope was invalid") orelse @panic("active when had no live branch")).opposite();
                            const changed = switch (desc.cached_value) {
                                .absent => true,
                                .present => |cached| !cached.valueEquals(ctx, roc_host, result.value),
                            };
                            if (!changed) {
                                callHostValueToUnitWithCapability(ctx, roc_host, cap, hv.hostValueCapabilityDrop(cap), result.value);
                                self.recordSignalPrune();
                                continue;
                            }
                            var change = HostDirtyStructuralSignal{
                                .kind = .when,
                                .node_id = desc.node_id,
                                .scope_id = site.scope_id,
                                .ordinal = site.ordinal,
                                .record = desc.condition.record,
                                .branch = active_branch,
                                .pending_when_cache = HostValueCell.initRetained(result.value, cap, &self.pending_roc_metrics),
                            };
                            dirty_structural_signals.append(allocator, change) catch {
                                change.abortPendingWhenCache(ctx, roc_host, &self.pending_roc_metrics);
                                @panic("out of memory");
                            };
                        },
                        .each => {
                            const desc = &self.active_stream.eaches.items[route.index];
                            const site = self.activeScopeSiteByNodeId(desc.node_id.raw(), .each) orelse @panic("active each descriptor had no scope site");
                            const result = self.evalDirtyHostSignalBinding(ctx, roc_host, &desc.items, dirty_source_node_ids, dirty_generation);
                            const cap = self.hostSignalBindingCapability(ctx, &desc.items);
                            if (!result.changed) {
                                callHostValueToUnitWithCapability(ctx, roc_host, cap, hv.hostValueCapabilityDrop(cap), result.value);
                                continue;
                            }
                            if (self.updateDirtySignalCache(ctx, roc_host, &desc.cached_value, result.value, cap)) {
                                dirty_structural_signals.append(allocator, .{
                                    .kind = .each,
                                    .node_id = desc.node_id,
                                    .scope_id = site.scope_id,
                                    .ordinal = site.ordinal,
                                    .record = desc.items.record,
                                }) catch @panic("out of memory");
                            }
                        },
                    }
                }
            }

            return dirty_structural_signals.toOwnedSlice(allocator) catch @panic("out of memory");
        }

        /// Performs state index by node id inside the shared engine while preserving transaction and changed-set invariants.
        pub fn stateIndexByNodeId(self: *Self, node_id: u64) ?usize {
            if (node_id >= self.state_indexes_by_node_id.items.len) return null;
            const state_index = self.state_indexes_by_node_id.items[@intCast(node_id)] orelse return null;
            if (state_index >= self.states.items.len) @panic("state cell index exceeded state table");
            const state = self.states.items[state_index];
            if (!state.isActive() or state.state_id != node_id) @panic("state cell index pointed at the wrong state");
            return state_index;
        }

        /// Returns the exact app-compiled capability that owns the requested state cell.
        pub fn stateCapability(self: *Self, node_id: u64) StateLookupError!HostValueCapability {
            const state_index = self.stateIndexByNodeId(node_id) orelse return StateLookupError.MissingActiveState;
            return self.states.items[state_index].activePayloadConst().cell.cap;
        }

        /// Evaluates one accepted reducer against independently owned reads of
        /// the settled state. The event payload remains borrowed from ingress;
        /// the returned value transfers to the caller's state transaction.
        ///
        /// No state is committed here. After a refused transaction the host may
        /// retry this pure evaluation with the same payload. Both hosts use this
        /// path so snapshot, capability, and read-release semantics stay shared.
        pub fn evaluateEventReducer(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, desc: HostActiveEventDesc, payload: HostValue) HostValue {
            const handler = desc.handler.reduce;
            const state_cap = self.stateCapability(handler.target_node_id.raw()) catch @panic("event target state is not live");
            const read_cap = self.stateCapability(handler.read_node_id.raw()) catch @panic("event read state is not live");
            const current = Ctx.stateValueByNodeId(ctx, handler.target_node_id.raw());
            defer {
                debugPhase(ctx, .event_drop_state);
                callHostValueToUnitWithCapability(ctx, roc_host, state_cap, hv.hostValueCapabilityDrop(state_cap), current);
            }
            const read = Ctx.stateValueByNodeId(ctx, handler.read_node_id.raw());
            defer {
                debugPhase(ctx, .event_drop_read);
                callHostValueToUnitWithCapability(ctx, roc_host, read_cap, hv.hostValueCapabilityDrop(read_cap), read);
            }
            return retained_values.callHostValueHostValueHostValueToHostValueWithCapabilities(
                Ctx,
                ctx,
                roc_host,
                state_cap,
                read_cap,
                handler.payload_reducer.capability,
                handler.payload_reducer.transform,
                current,
                read,
                payload,
            );
        }

        /// Builds one command for one accepted occurrence, borrowing the
        /// settled declared reads. Re-evaluating equal events is intentional;
        /// signal propagation itself never invokes this callback.
        pub fn evaluateEventAction(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, desc: HostActiveEventDesc, payload: HostValue) abi.NodeCmd {
            var handler = desc.handler.action;
            const cap = self.hostSignalBindingCapability(ctx, &handler.reads);
            const snapshot = self.evalHostSignalBinding(ctx, roc_host, &handler.reads);
            defer callHostValueToUnitWithCapability(ctx, roc_host, cap, hv.hostValueCapabilityDrop(cap), snapshot);
            return retained_values.callHostValueHostValueToCmdWithCapabilities(Ctx, ctx, roc_host, cap, handler.payload_cap, handler.to_cmd.toAbi(), snapshot, payload);
        }

        /// Borrows the handler retained by the active event table. Copying a
        /// descriptor across streams must clone this owner, not its stale view.
        pub fn activeEventHandlerByIndex(self: *Self, event_index: usize) ActiveEventLookupError!descriptor_stream.EventHandler {
            if (event_index >= self.active_events.items.len) return ActiveEventLookupError.MissingActiveEvent;
            return self.active_events.items[event_index].handler;
        }

        /// Returns active scope site by node id from the maintained active-runtime indexes.
        pub fn activeScopeSiteByNodeId(self: *Self, node_id: u64, kind: HostNodeScopeSiteKind) ?HostNodeScopeSiteDesc {
            const descriptor_index = self.active_stream.nodeDescriptorIndex(ids.NodeId.fromRaw(node_id)) orelse return null;
            const scope_site_index = descriptor_index.scope_sites.get(kind) orelse return null;
            if (scope_site_index >= self.active_stream.scope_sites.items.len) @panic("active scope site index exceeded descriptor table");
            const site = self.active_stream.scope_sites.items[scope_site_index];
            if (site.node_id.raw() != node_id or site.kind != kind) @panic("active scope site index pointed at the wrong node");
            return site;
        }

        /// Returns active when index by node id from the maintained active-runtime indexes.
        pub fn activeWhenIndexByNodeId(self: *Self, node_id: u64) ?usize {
            const descriptor_index = self.active_stream.nodeDescriptorIndex(ids.NodeId.fromRaw(node_id)) orelse return null;
            const when_index = descriptor_index.when.get() orelse return null;
            if (when_index >= self.active_stream.whens.items.len) @panic("active when index exceeded descriptor table");
            if (self.active_stream.whens.items[when_index].node_id.raw() != node_id) @panic("active when index pointed at the wrong node");
            return when_index;
        }

        /// Returns active each index by node id from the maintained active-runtime indexes.
        pub fn activeEachIndexByNodeId(self: *Self, node_id: u64) ?usize {
            const descriptor_index = self.active_stream.nodeDescriptorIndex(ids.NodeId.fromRaw(node_id)) orelse return null;
            const each_index = descriptor_index.each.get() orelse return null;
            if (each_index >= self.active_stream.eaches.items.len) @panic("active each index exceeded descriptor table");
            if (self.active_stream.eaches.items[each_index].node_id.raw() != node_id) @panic("active each index pointed at the wrong node");
            return each_index;
        }

        /// Records slice contains in the metrics or lifecycle state owned by this operation.
        pub fn recordSliceContains(records: []const *HostSignalRecord, record: *HostSignalRecord) bool {
            return active_graph.recordSliceContains(HostSignalRecord, records, record);
        }

        /// Returns active when branch scope id from the maintained active-runtime indexes.
        pub fn activeWhenBranchScopeId(self: *Self, parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal, branch: HostScopeBranch) scope_tree.Error!?ids.ScopeId {
            return scope_tree.activeWhenBranch(HostEachRowScopeStep, self.scopes.items, parent_scope_id, site_ordinal, branch);
        }

        /// Performs validate scope id inside the shared engine while preserving transaction and changed-set invariants.
        pub fn validateScopeId(self: *Self, scope_id: ids.ScopeId) scope_tree.Error!void {
            return scope_tree.validate(HostEachRowScopeStep, self.scopes.items, scope_id);
        }

        /// Performs intern root scope inside the shared engine while preserving transaction and changed-set invariants.
        pub fn internRootScope(self: *Self, allocator: std.mem.Allocator) scope_tree.Error!scope_tree.InternResult {
            const result = try scope_tree.internRoot(HostEachRowScopeStep, allocator, &self.scopes);
            if (result.created) self.recordScopeCreated();
            return result;
        }

        /// Performs intern component scope inside the shared engine while preserving transaction and changed-set invariants.
        pub fn internComponentScope(self: *Self, allocator: std.mem.Allocator, parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal) scope_tree.Error!scope_tree.InternResult {
            const result = try scope_tree.internComponent(HostEachRowScopeStep, allocator, &self.scopes, parent_scope_id, site_ordinal, ids.Generation.fromRaw(self.identity_reuse_barrier));
            if (result.created) self.recordScopeCreated();
            return result;
        }

        /// Performs intern when branch scope inside the shared engine while preserving transaction and changed-set invariants.
        pub fn internWhenBranchScope(self: *Self, allocator: std.mem.Allocator, parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal, branch: HostScopeBranch) scope_tree.Error!scope_tree.InternResult {
            const result = try scope_tree.internWhenBranch(HostEachRowScopeStep, allocator, &self.scopes, parent_scope_id, site_ordinal, branch, ids.Generation.fromRaw(self.identity_reuse_barrier));
            if (result.created) self.recordScopeCreated();
            return result;
        }

        /// Performs intern node identity inside the shared engine while preserving transaction and changed-set invariants.
        pub fn internNodeIdentity(self: *Self, allocator: std.mem.Allocator, scope_id: ids.ScopeId, ordinal: ids.SiteOrdinal) IdentityInternError!ids.NodeId {
            try self.validateScopeId(scope_id);
            const key = identityKey(scope_id.raw(), ordinal.raw());
            if (self.active_node_identity_ids.get(key)) |node_id| return ids.NodeId.fromRaw(node_id);
            self.active_node_identity_ids.ensureUnusedCapacity(allocator, 1) catch return IdentityInternError.OutOfMemory;
            const node_id = blk: {
                if (!self.has_inactive_node_identities and (self.node_identities.items.len == 0 or identityCanAppend(self.node_identities.items[self.node_identities.items.len - 1], scope_id.raw(), ordinal.raw()))) {
                    break :blk try identity_table.appendFreshNode(allocator, &self.node_identities, scope_id, ordinal);
                }
                break :blk try identity_table.internNode(allocator, &self.node_identities, scope_id, ordinal, ids.Generation.fromRaw(self.identity_reuse_barrier));
            };
            self.active_node_identity_ids.putAssumeCapacity(key, node_id.raw());
            return node_id;
        }

        /// Performs intern dom identity inside the shared engine while preserving transaction and changed-set invariants.
        pub fn internDomIdentity(self: *Self, allocator: std.mem.Allocator, scope_id: ids.ScopeId, ordinal: ids.SiteOrdinal) IdentityInternError!ids.ElemId {
            try self.validateScopeId(scope_id);
            const key = identityKey(scope_id.raw(), ordinal.raw());
            if (self.active_dom_identity_ids.get(key)) |elem_id| return ids.ElemId.fromRaw(elem_id);
            self.active_dom_identity_ids.ensureUnusedCapacity(allocator, 1) catch return IdentityInternError.OutOfMemory;
            const elem_id = blk: {
                if (!self.has_inactive_dom_identities and (self.dom_identities.items.len == 0 or identityCanAppend(self.dom_identities.items[self.dom_identities.items.len - 1], scope_id.raw(), ordinal.raw()))) {
                    break :blk try identity_table.appendFreshDom(allocator, &self.dom_identities, scope_id, ordinal);
                }
                break :blk try identity_table.internDom(allocator, &self.dom_identities, scope_id, ordinal, ids.Generation.fromRaw(self.identity_reuse_barrier), ActiveDomIds{ .stream = &self.active_stream });
            };
            self.active_dom_identity_ids.putAssumeCapacity(key, elem_id.raw());
            return elem_id;
        }

        /// Returns active each row scopes from the maintained active-runtime indexes.
        pub fn activeEachRowScopes(self: *Self, allocator: std.mem.Allocator, parent_scope_id: ids.ScopeId, site_ordinal: ids.SiteOrdinal) scope_tree.Error![]ids.ScopeId {
            try self.validateScopeId(parent_scope_id);
            const site_index = self.activeEachRowSiteIndex(parent_scope_id, site_ordinal) orelse {
                return allocator.alloc(ids.ScopeId, 0) catch return scope_tree.Error.OutOfMemory;
            };
            const row_count = self.each_row_sites.items[site_index].scope_ids.items.len;
            const result = allocator.alloc(ids.ScopeId, row_count) catch return scope_tree.Error.OutOfMemory;
            errdefer allocator.free(result);
            // The dense site table is a membership index; committed row order
            // is owned by the Rows store, so report rows in that order.
            const rows_site_id = self.rows_site_ids.get(.{ .parent_scope_id = parent_scope_id, .site_ordinal = site_ordinal }) orelse return scope_tree.Error.UnknownScope;
            const store = if (self.rows_store) |*store| store else return scope_tree.Error.UnknownScope;
            var rows = store.iterate(rows_site_id) catch return scope_tree.Error.UnknownScope;
            var index: usize = 0;
            while (rows.next()) |entry| : (index += 1) {
                if (index >= result.len) return scope_tree.Error.UnknownScope;
                result[index] = ids.ScopeId.fromRaw(entry.row.metadata.scope_id);
            }
            if (index != result.len) return scope_tree.Error.UnknownScope;
            return result;
        }

        /// Performs each row scope key equals inside the shared engine while preserving transaction and changed-set invariants.
        pub fn eachRowScopeKeyEquals(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, scope_id: u64, key: HostValue, key_cap: HostValueCapability) bool {
            self.recordEachKeyReuseCompare();
            return scope_runtime.eachRowKeyEquals(self.scopes.items, ctx, roc_host, ids.ScopeId.fromRaw(scope_id), key, key_cap);
        }

        /// Performs each row scope key value inside the shared engine while preserving transaction and changed-set invariants.
        pub fn eachRowScopeKeyValue(self: *Self, scope_id: u64) HostValue {
            return scope_runtime.eachRowKeyValue(self.scopes.items, ids.ScopeId.fromRaw(scope_id));
        }

        /// Performs each row scope key hash inside the shared engine while preserving transaction and changed-set invariants.
        pub fn eachRowScopeKeyHash(self: *Self, scope_id: u64) u64 {
            return scope_runtime.eachRowKeyHash(self.scopes.items, ids.ScopeId.fromRaw(scope_id));
        }

        /// Performs each site row ancestor scope id inside the shared engine while preserving transaction and changed-set invariants.
        pub fn eachSiteRowAncestorScopeId(self: *Self, scope_id: u64, site: HostEachSite) scope_tree.Error!?u64 {
            const found = try scope_tree.eachSiteRowAncestor(HostEachRowScopeStep, self.scopes.items, ids.ScopeId.fromRaw(scope_id), site.parent_scope_id, site.site_ordinal);
            return if (found) |scope_id_value| scope_id_value.raw() else null;
        }

        /// Evaluates scope is descendant or self using explicit scope ownership rather than DOM position or content.
        pub fn scopeIsDescendantOrSelf(self: *Self, scope_id: u64, root_scope_id: u64) scope_tree.Error!bool {
            return scope_tree.descendantOrSelf(HostEachRowScopeStep, self.scopes.items, ids.ScopeId.fromRaw(scope_id), ids.ScopeId.fromRaw(root_scope_id));
        }

        fn scopeDepth(self: *Self, scope_id: u64) usize {
            var depth: usize = 0;
            var current: ?u64 = scope_id;
            while (current) |id| {
                if (id >= self.scopes.items.len) return std.math.maxInt(usize);
                const scope = self.scopes.items[@intCast(id)];
                current = if (scope.parent_scope_id) |parent| parent.raw() else null;
                if (current != null) depth += 1;
            }
            return depth;
        }

        /// A scope site's place in the document: the scope it was collected in
        /// and its ordinal there. Collection hands ordinals out in document
        /// order per scope, and every scope a site creates - a branch, a
        /// component, an each row - carries that site's ordinal as its step, so
        /// the scope tree plus the ordinals is a total order over sites.
        pub const SitePosition = struct {
            scope_id: u64,
            ordinal: ids.SiteOrdinal,

            /// The position of a collected scope site.
            pub fn ofSite(site: HostNodeScopeSiteDesc) SitePosition {
                return .{ .scope_id = site.scope_id.raw(), .ordinal = site.ordinal };
            }
        };

        /// How one scope site stands to another in document order. `contains`
        /// means the second site lives inside content the first site created.
        pub const SiteOrder = enum { before, after, same, contains, contained };

        fn parentScopeIdOf(self: *Self, scope_id: u64) CollectionError!u64 {
            if (scope_id >= self.scopes.items.len) return error.InvalidScope;
            const parent = self.scopes.items[@intCast(scope_id)].parent_scope_id orelse return error.InvalidScope;
            return parent.raw();
        }

        /// The ordinal of the site that created `scope_id` in its parent scope.
        fn scopeStepOrdinal(self: *Self, scope_id: u64) CollectionError!ids.SiteOrdinal {
            if (scope_id >= self.scopes.items.len) return error.InvalidScope;
            return switch (self.scopes.items[@intCast(scope_id)].step) {
                .root => error.InvalidScope,
                .component => |step| step.site_ordinal,
                .when_branch => |step| step.site_ordinal,
                .each_row => |row| row.site_ordinal,
            };
        }

        /// Orders two rows of one each site by their committed row order.
        /// The Rows store's order index answers each rank in logarithmic
        /// expected time; the dense site index is a key/membership table
        /// whose slot order is not row order after a sparse delta.
        fn compareEachRowScopes(self: *Self, parent_scope_id: u64, site_ordinal: ids.SiteOrdinal, row_a: u64, row_b: u64) CollectionError!SiteOrder {
            const rows_site_id = self.rows_site_ids.get(.{ .parent_scope_id = ids.ScopeId.fromRaw(parent_scope_id), .site_ordinal = site_ordinal }) orelse return error.InvalidScope;
            const store = if (self.rows_store) |*store| store else return error.InvalidScope;
            const location_a = store.findScope(row_a) orelse return error.InvalidScope;
            const location_b = store.findScope(row_b) orelse return error.InvalidScope;
            if (location_a.site_id != rows_site_id or location_b.site_id != rows_site_id) return error.InvalidScope;
            const render_order = (store.getSiteConst(rows_site_id) catch return error.InvalidScope).render_order;
            const a = render_order.rank(location_a.row_id) catch return error.InvalidScope;
            const b = render_order.rank(location_b.row_id) catch return error.InvalidScope;
            return if (a < b) .before else .after;
        }

        /// Document order over scope sites, in old-stream terms: the position
        /// of every committed scope and site as the active stream has them.
        ///
        /// Two sites of one scope order by ordinal. Otherwise both are followed
        /// up to their common ancestor scope and compared there: a site
        /// compares by its own ordinal, a subtree by the ordinal of the site
        /// that created its top scope. Equal ordinals at the common scope name
        /// one site, so either one position *is* that site and contains the
        /// other, or both are rows of that each site and their committed row
        /// order decides. Nothing here consults render positions, so two
        /// sites that render nothing at one index still have exactly one order.
        pub fn compareSitePositions(self: *Self, a: SitePosition, b: SitePosition) CollectionError!SiteOrder {
            if (a.scope_id == b.scope_id) {
                if (a.ordinal.raw() < b.ordinal.raw()) return .before;
                if (a.ordinal.raw() > b.ordinal.raw()) return .after;
                return .same;
            }
            var scope_a = a.scope_id;
            var scope_b = b.scope_id;
            var child_a: ?u64 = null;
            var child_b: ?u64 = null;
            var depth_a = self.scopeDepth(scope_a);
            var depth_b = self.scopeDepth(scope_b);
            if (depth_a == std.math.maxInt(usize) or depth_b == std.math.maxInt(usize)) return error.InvalidScope;
            while (depth_a > depth_b) : (depth_a -= 1) {
                child_a = scope_a;
                scope_a = try self.parentScopeIdOf(scope_a);
            }
            while (depth_b > depth_a) : (depth_b -= 1) {
                child_b = scope_b;
                scope_b = try self.parentScopeIdOf(scope_b);
            }
            while (scope_a != scope_b) {
                child_a = scope_a;
                scope_a = try self.parentScopeIdOf(scope_a);
                child_b = scope_b;
                scope_b = try self.parentScopeIdOf(scope_b);
            }
            const ordinal_a = if (child_a) |child| try self.scopeStepOrdinal(child) else a.ordinal;
            const ordinal_b = if (child_b) |child| try self.scopeStepOrdinal(child) else b.ordinal;
            if (ordinal_a.raw() < ordinal_b.raw()) return .before;
            if (ordinal_a.raw() > ordinal_b.raw()) return .after;
            if (child_a == null) return .contains;
            if (child_b == null) return .contained;
            return self.compareEachRowScopes(scope_a, ordinal_a, child_a.?, child_b.?);
        }

        fn resolveStateCommandTarget(self: *Self, owner_scope_id: ids.ScopeId, binder_token: HostBinderToken) ids.NodeId {
            return self.findStateCommandTarget(owner_scope_id, binder_token) orelse @panic("UpdateState referenced a state binder outside the command's active scope");
        }

        /// The state a binder names from the command's owning scope outward,
        /// or null when no active scope on that path declares it.
        fn findStateCommandTarget(self: *Self, owner_scope_id: ids.ScopeId, binder_token: HostBinderToken) ?ids.NodeId {
            var scope_id = owner_scope_id;
            while (true) {
                if (scope_id.index() >= self.scopes.items.len or !self.scopes.items[scope_id.index()].lifecycle.isActive()) @panic("state command owner referenced an inactive scope");
                if (self.active_stream.stateNodeForBinder(scope_id, binder_token)) |node_id| return node_id;
                const scope = self.scopes.items[scope_id.index()];
                if (scope.parent_scope_id == null) return null;
                scope_id = scope.parent_scope_id.?;
            }
        }

        /// Evaluates scope is each site row descendant or self using explicit scope ownership rather than DOM position or content.
        pub fn scopeIsEachSiteRowDescendantOrSelf(self: *Self, scope_id: u64, site: HostEachSite) scope_tree.Error!bool {
            return scope_tree.eachSiteRowDescendantOrSelf(HostEachRowScopeStep, self.scopes.items, ids.ScopeId.fromRaw(scope_id), site.parent_scope_id, site.site_ordinal);
        }

        /// Performs each diff preserves survivor render order inside the shared engine while preserving transaction and changed-set invariants.
        pub fn eachDiffPreservesSurvivorRenderOrder(old_render_rows: []const u64, next_scope_ids: []const u64) bool {
            return each_runtime.diffPreservesSurvivorRenderOrder(old_render_rows, next_scope_ids);
        }

        /// Returns active each row render segments in render order from the maintained active-runtime indexes.
        pub fn activeEachRowRenderSegmentsInRenderOrder(self: *Self, allocator: std.mem.Allocator, site: HostEachSite) []HostEachRowRenderSegment {
            var segments: shared_buffer.List(HostEachRowRenderSegment) = .empty;
            errdefer segments.deinit(allocator);
            var segment_indexes_by_scope: std.AutoHashMapUnmanaged(u64, usize) = .{};
            defer segment_indexes_by_scope.deinit(allocator);

            self.recordStreamNodesScannedBy(.stream_nodes_scanned_render_scope, self.active_stream.render_nodes.items.len);
            var render_index: usize = 0;
            while (render_index < self.active_stream.render_nodes.items.len) {
                const node = self.active_stream.render_nodes.items[render_index];
                const scope_id = renderNodeScopeId(&self.active_stream, node);
                const row_scope_id = (self.eachSiteRowAncestorScopeId(scope_id, site) catch @panic("scope descriptor referenced an unknown parent scope")) orelse {
                    render_index += 1;
                    continue;
                };
                const start = render_index;
                render_index += 1;
                while (render_index < self.active_stream.render_nodes.items.len) : (render_index += 1) {
                    const next_node = self.active_stream.render_nodes.items[render_index];
                    const next_scope_id = renderNodeScopeId(&self.active_stream, next_node);
                    const next_row_scope_id = self.eachSiteRowAncestorScopeId(next_scope_id, site) catch @panic("scope descriptor referenced an unknown parent scope");
                    if (next_row_scope_id == null or next_row_scope_id.? != row_scope_id) break;
                }

                const segment_index = segments.items.len;
                segments.append(allocator, .{
                    .scope_id = ids.ScopeId.fromRaw(row_scope_id),
                    .start = start,
                    .len = render_index - start,
                }) catch @panic("out of memory");
                const entry = segment_indexes_by_scope.getOrPut(allocator, row_scope_id) catch @panic("out of memory");
                if (!entry.found_existing) entry.value_ptr.* = segment_index;
            }

            return segments.toOwnedSlice(allocator) catch @panic("out of memory");
        }

        /// Performs each render segment scope ids inside the shared engine while preserving transaction and changed-set invariants.
        pub fn eachRenderSegmentScopeIds(allocator: std.mem.Allocator, segments: []const HostEachRowRenderSegment) []u64 {
            return each_runtime.renderSegmentScopeIds(allocator, segments);
        }

        /// Performs each diff is pure permutation inside the shared engine while preserving transaction and changed-set invariants.
        pub fn eachDiffIsPurePermutation(self: *Self, old_render_rows: []const u64, diff: HostKeyedRowDiffResult, dirty_source_node_ids: []const u64) bool {
            if (diff.rows_created != 0 or diff.rows_removed != 0) return false;
            if (diff.scope_ids.len != old_render_rows.len) return false;
            for (diff.scope_ids, diff.row_items_changed) |scope_id, row_item_changed| {
                if (row_item_changed) return false;
                if (!u64SliceContains(old_render_rows, scope_id)) return false;
                if (self.scopeSubtreeHasDirtyStructuralSource(&self.active_stream, scope_id, dirty_source_node_ids)) return false;
            }
            return true;
        }

        /// Applies dirty each permutation moves after preparation has fixed semantics and reserved fallible growth.
        pub fn applyDirtyEachPermutationMoves(self: *Self, ctx: Ctx.Handle, site: HostNodeScopeSiteDesc, next_scope_ids: []const u64) render.Counts {
            if (site.kind != .each) @panic("dirty each permutation move received a non-each site");

            const allocator = Ctx.allocator(ctx);
            const each_site = HostEachSite{ .parent_scope_id = site.scope_id, .site_ordinal = site.ordinal };
            var segments: shared_buffer.List(HostEachRowRenderSegment) = .empty;
            defer segments.deinit(allocator);
            var segment_indexes_by_scope: std.AutoHashMapUnmanaged(u64, usize) = .{};
            defer segment_indexes_by_scope.deinit(allocator);

            var render_index: usize = 0;
            while (render_index < self.active_stream.render_nodes.items.len) {
                const node = self.active_stream.render_nodes.items[render_index];
                const scope_id = renderNodeScopeId(&self.active_stream, node);
                const row_scope_id = (self.eachSiteRowAncestorScopeId(scope_id, each_site) catch @panic("scope descriptor referenced an unknown parent scope")) orelse {
                    render_index += 1;
                    continue;
                };
                const start = render_index;
                render_index += 1;
                while (render_index < self.active_stream.render_nodes.items.len) : (render_index += 1) {
                    const next_node = self.active_stream.render_nodes.items[render_index];
                    const next_scope_id = renderNodeScopeId(&self.active_stream, next_node);
                    const next_row_scope_id = self.eachSiteRowAncestorScopeId(next_scope_id, each_site) catch @panic("scope descriptor referenced an unknown parent scope");
                    if (next_row_scope_id == null or next_row_scope_id.? != row_scope_id) break;
                }

                const segment_index = segments.items.len;
                segments.append(allocator, .{
                    .scope_id = row_scope_id,
                    .start = start,
                    .len = render_index - start,
                }) catch @panic("out of memory");
                const entry = segment_indexes_by_scope.getOrPut(allocator, row_scope_id) catch @panic("out of memory");
                if (entry.found_existing) @panic("each row render nodes were split across multiple segments");
                entry.value_ptr.* = segment_index;
            }

            if (segments.items.len != next_scope_ids.len) @panic("pure each permutation did not cover every rendered row");
            if (segments.items.len == 0) return .{};

            const region_start = segments.items[0].start;
            var expected_start = region_start;
            var total_len: usize = 0;
            for (segments.items) |segment| {
                if (segment.start != expected_start) @panic("each row render segments were not contiguous");
                expected_start += segment.len;
                total_len += segment.len;
            }

            var moves_by_scope: std.AutoHashMapUnmanaged(u64, HostEachRowRenderMove) = .{};
            defer moves_by_scope.deinit(allocator);
            const reordered_nodes = allocator.alloc(HostRenderNode, total_len) catch @panic("out of memory");
            defer allocator.free(reordered_nodes);

            var write_index: usize = 0;
            for (next_scope_ids) |scope_id| {
                const segment_index = segment_indexes_by_scope.get(scope_id) orelse @panic("pure each permutation referenced a row without render nodes");
                const segment = segments.items[segment_index];
                const next_start = region_start + write_index;
                @memcpy(reordered_nodes[write_index..][0..segment.len], self.active_stream.render_nodes.items[segment.start..][0..segment.len]);
                moves_by_scope.put(allocator, scope_id, .{
                    .old_start = segment.start,
                    .new_start = next_start,
                    .len = segment.len,
                }) catch @panic("out of memory");
                write_index += segment.len;
            }

            if (write_index != total_len) @panic("pure each permutation wrote the wrong render-node count");
            @memcpy(self.active_stream.render_nodes.items[region_start..][0..total_len], reordered_nodes);

            var reordered_region_children: shared_buffer.List(u64) = .empty;
            defer reordered_region_children.deinit(allocator);
            for (self.active_stream.render_nodes.items[region_start..][0..total_len]) |node| {
                if (renderNodeParentElemId(&self.active_stream, node) == site.parent_elem_id) {
                    reordered_region_children.append(allocator, node.elem_id) catch @panic("out of memory");
                }
            }

            var reordered_parent_children: shared_buffer.List(u64) = .empty;
            defer reordered_parent_children.deinit(allocator);
            var inserted_region = false;
            const region_end = region_start + total_len;
            const old_parent_children = streamDirectChildrenInto(allocator, &self.active_stream, site.parent_elem_id, &self.scratch.stream_direct_children);
            for (old_parent_children) |child_id| {
                const child_render_index = self.active_stream.renderNodeIndex(child_id) orelse @panic("parent child had no render index");
                const child_in_region = child_render_index >= region_start and child_render_index < region_end;
                if (child_in_region) {
                    if (!inserted_region) {
                        reordered_parent_children.appendSlice(allocator, reordered_region_children.items) catch @panic("out of memory");
                        inserted_region = true;
                    }
                    continue;
                }
                reordered_parent_children.append(allocator, child_id) catch @panic("out of memory");
            }
            if (!inserted_region and reordered_region_children.items.len != 0) {
                reordered_parent_children.appendSlice(allocator, reordered_region_children.items) catch @panic("out of memory");
            }
            self.active_stream.replaceRenderChildrenIndex(allocator, site.parent_elem_id, reordered_parent_children.items);
            self.active_stream.refreshRenderIndexesInRange(allocator, region_start, total_len, &self.pending_roc_metrics);

            for (self.active_stream.scope_sites.items) |*scope_site| {
                const row_scope_id = (self.eachSiteRowAncestorScopeId(scope_site.scope_id, each_site) catch @panic("scope descriptor referenced an unknown parent scope")) orelse continue;
                const move = moves_by_scope.get(row_scope_id) orelse @panic("scope site referenced a row missing from pure each permutation");
                if (scope_site.render_insert_index < move.old_start) @panic("scope site insertion point preceded its row render segment");
                const offset = scope_site.render_insert_index - move.old_start;
                if (offset > move.len) @panic("scope site insertion point exceeded its row render segment");
                scope_site.render_insert_index = move.new_start + offset;
            }

            var counts: render.Counts = .{};
            const children = streamDirectChildrenInto(allocator, &self.active_stream, site.parent_elem_id, &self.scratch.stream_direct_children);
            self.replaceRenderChildrenForMoves(ctx, site.parent_elem_id, children, &counts);
            if (comptime enable_runtime_metrics) self.render_metrics.addCommandCounts(counts);
            return counts;
        }

        /// Performs render insert index for each row ranges inside the shared engine while preserving transaction and changed-set invariants.
        pub fn renderInsertIndexForEachRowRanges(site: HostNodeScopeSiteDesc, row_ranges: *const std.AutoHashMapUnmanaged(u64, HostEachRowRenderSegment), next_scope_ids: []const u64, row_index: usize) usize {
            return each_runtime.renderInsertIndexForRowRanges(site.render_insert_index, row_ranges, next_scope_ids, row_index);
        }

        /// Performs render append index for each row ranges inside the shared engine while preserving transaction and changed-set invariants.
        pub fn renderAppendIndexForEachRowRanges(site: HostNodeScopeSiteDesc, row_ranges: *const std.AutoHashMapUnmanaged(u64, HostEachRowRenderSegment)) usize {
            var append_index = site.render_insert_index;
            var range_iterator = row_ranges.iterator();
            while (range_iterator.next()) |entry| {
                append_index = @max(append_index, entry.value_ptr.start + entry.value_ptr.len);
            }
            return append_index;
        }

        /// Performs child insertion index for each row ranges inside the shared engine while preserving transaction and changed-set invariants.
        pub fn childInsertionIndexForEachRowRanges(self: *Self, allocator: std.mem.Allocator, site: HostNodeScopeSiteDesc, row_ranges: *const std.AutoHashMapUnmanaged(u64, HostEachRowRenderSegment), render_insert_index: usize) usize {
            const each_site = HostEachSite{ .parent_scope_id = site.scope_id, .site_ordinal = site.ordinal };
            const children = streamDirectChildrenInto(allocator, &self.active_stream, site.parent_elem_id, &self.scratch.stream_direct_children);

            var child_index: usize = 0;
            for (children) |child_id| {
                const child_scope_id = elemScopeId(&self.active_stream, child_id) orelse @panic("each row child had no scope");
                const row_scope_id = (self.eachSiteRowAncestorScopeId(child_scope_id, each_site) catch @panic("scope descriptor referenced an unknown parent scope")) orelse continue;
                const range = row_ranges.get(row_scope_id) orelse @panic("each row child had no render range");
                if (range.start >= render_insert_index) break;
                child_index += 1;
            }
            return child_index;
        }

        /// Performs each site parent has only row children inside the shared engine while preserving transaction and changed-set invariants.
        pub fn eachSiteParentHasOnlyRowChildren(self: *Self, allocator: std.mem.Allocator, site: HostNodeScopeSiteDesc, old_render_segments: []const HostEachRowRenderSegment) bool {
            const each_site = HostEachSite{ .parent_scope_id = site.scope_id, .site_ordinal = site.ordinal };
            const children = streamDirectChildrenInto(allocator, &self.active_stream, site.parent_elem_id, &self.scratch.stream_direct_children);
            if (children.len != old_render_segments.len) return false;

            for (children, old_render_segments) |child_id, segment| {
                const child_scope_id = elemScopeId(&self.active_stream, child_id) orelse return false;
                const row_scope_id = (self.eachSiteRowAncestorScopeId(child_scope_id, each_site) catch @panic("scope descriptor referenced an unknown parent scope")) orelse return false;
                if (row_scope_id != segment.scope_id) return false;
            }
            return true;
        }

        /// Performs adjust each row render ranges inside the shared engine while preserving transaction and changed-set invariants.
        pub fn adjustEachRowRenderRanges(row_ranges: *std.AutoHashMapUnmanaged(u64, HostEachRowRenderSegment), replace_index: usize, removed_count: usize, replacement_count: usize) void {
            each_runtime.adjustRenderRanges(row_ranges, replace_index, removed_count, replacement_count);
        }

        /// Performs update each row render range inside the shared engine while preserving transaction and changed-set invariants.
        pub fn updateEachRowRenderRange(row_ranges: *std.AutoHashMapUnmanaged(u64, HostEachRowRenderSegment), allocator: std.mem.Allocator, scope_id: u64, render_insert_index: usize, removed_count: usize, replacement_count: usize) void {
            each_runtime.updateRenderRange(row_ranges, allocator, scope_id, render_insert_index, removed_count, replacement_count);
        }

        /// Performs eval on change initial inside the shared engine while preserving transaction and changed-set invariants.
        pub fn evalOnChangeInitial(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, desc: *HostNodeOnChangeDesc) void {
            const value = self.evalHostSignalBinding(ctx, roc_host, &desc.signal);
            desc.cached_value.replace(ctx, roc_host, &self.pending_roc_metrics, value, self.hostSignalBindingCapability(ctx, &desc.signal));
        }

        /// Performs eval on change initial command inside the shared engine while preserving transaction and changed-set invariants.
        pub fn evalOnChangeInitialCommand(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, desc: *HostNodeOnChangeDesc) render.Counts {
            const pending = self.evalOnChangeInitialPendingCommand(ctx, roc_host, desc) orelse return .{};
            defer pending.cmd.decref(roc_host);
            return self.runPendingOnChangeCommand(ctx, roc_host, pending);
        }

        fn evalOnChangeInitialPendingCommand(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, desc: *HostNodeOnChangeDesc) ?HostPendingOnChangeCommand {
            if (!desc.run_initial_pending) return null;
            desc.run_initial_pending = false;

            const cap = self.hostSignalBindingCapability(ctx, &desc.signal);
            const value = self.cloneCachedSignalValue(ctx, &desc.cached_value);
            defer callHostValueToUnitWithCapability(ctx, roc_host, cap, hv.hostValueCapabilityDrop(cap), value);

            const cmd = callHostValueToCmdWithCapability(ctx, roc_host, cap, desc.to_cmd.toAbi(), value);
            cmd.incref(1);
            cmd.decref(roc_host);
            return .{ .scope_id = desc.scope_id.raw(), .cmd = cmd, .on_change_index = self.onChangeIndexOf(desc) };
        }

        fn runPendingOnChangeCommands(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, pending_commands: []const HostPendingOnChangeCommand) render.Counts {
            var counts: render.Counts = .{};
            for (pending_commands) |pending| {
                counts.addAll(self.runPendingOnChangeCommand(ctx, roc_host, pending));
            }
            return counts;
        }

        /// Runs active on change initial command indices using the host semantics and measurement boundaries defined by this module.
        pub fn runActiveOnChangeInitialCommandIndices(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, indices: []const usize) render.Counts {
            const allocator = Ctx.allocator(ctx);
            var pending_commands: shared_buffer.List(HostPendingOnChangeCommand) = .empty;
            defer {
                for (pending_commands.items) |pending| pending.cmd.decref(roc_host);
                pending_commands.deinit(allocator);
            }

            self.recordStreamNodesScannedBy(.stream_nodes_scanned_on_change, indices.len);
            for (indices) |on_change_index| {
                if (on_change_index >= self.active_stream.on_changes.items.len) @panic("on_change descriptor index exceeded active descriptor stream");
                if (self.evalOnChangeInitialPendingCommand(ctx, roc_host, &self.active_stream.on_changes.items[on_change_index])) |pending| {
                    pending_commands.append(allocator, pending) catch @panic("out of memory");
                }
            }
            return self.runPendingOnChangeCommands(ctx, roc_host, pending_commands.items);
        }

        /// Runs active on change initial commands using the host semantics and measurement boundaries defined by this module.
        pub fn runActiveOnChangeInitialCommands(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost) render.Counts {
            const allocator = Ctx.allocator(ctx);
            var pending_commands: shared_buffer.List(HostPendingOnChangeCommand) = .empty;
            defer {
                for (pending_commands.items) |pending| pending.cmd.decref(roc_host);
                pending_commands.deinit(allocator);
            }

            self.recordStreamNodesScannedBy(.stream_nodes_scanned_on_change, self.active_stream.on_changes.items.len);
            for (self.active_stream.on_changes.items) |*desc| {
                if (self.evalOnChangeInitialPendingCommand(ctx, roc_host, desc)) |pending| {
                    pending_commands.append(allocator, pending) catch @panic("out of memory");
                }
            }
            return self.runPendingOnChangeCommands(ctx, roc_host, pending_commands.items);
        }

        /// Performs eval mount command inside the shared engine while preserving transaction and changed-set invariants.
        pub fn evalMountCommand(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, desc: *HostNodeMountDesc) render.Counts {
            if (!desc.run_on_mount) return .{};
            desc.run_on_mount = false;

            const cmd = erased_calls.callUnitToCmd(roc_host, desc.to_cmd.toAbi());
            defer cmd.decref(roc_host);
            return self.runCommand(ctx, roc_host, desc.scope_id, cmd);
        }

        /// Runs active mount command indices using the host semantics and measurement boundaries defined by this module.
        pub fn runActiveMountCommandIndices(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, indices: []const usize) render.Counts {
            var counts: render.Counts = .{};
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_mounts, indices.len);
            for (indices) |mount_index| {
                if (mount_index >= self.active_stream.mounts.items.len) @panic("mount descriptor index exceeded active descriptor stream");
                counts.addAll(self.evalMountCommand(ctx, roc_host, &self.active_stream.mounts.items[mount_index]));
            }
            return counts;
        }

        /// Runs active mount commands using the host semantics and measurement boundaries defined by this module.
        pub fn runActiveMountCommands(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost) render.Counts {
            var counts: render.Counts = .{};
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_mounts, self.active_stream.mounts.items.len);
            for (self.active_stream.mounts.items) |*desc| {
                counts.addAll(self.evalMountCommand(ctx, roc_host, desc));
            }
            return counts;
        }

        /// Applies structural event bindings after preparation has fixed semantics and reserved fallible growth.
        pub fn applyStructuralEventBindings(self: *Self, ctx: Ctx.Handle, stream: *const HostNodeDescriptorStream, seen: []const bool, counts: *render.Counts) void {
            if (firstEventDescriptorElemOutsideSeen(stream, seen) != null) {
                @panic("event descriptor referenced element outside structural render stream");
            }
            for (seen, 0..) |is_seen, index| {
                if (index == 0 or !is_seen) continue;

                for (render_event_kinds) |kind| {
                    const elem_id = ids.ElemId.fromIndex(index);
                    const next_binding = fixedEventBindingForElemKind(stream, elem_id, kind);
                    self.applyRenderEventBinding(ctx, elem_id, kind, next_binding, counts);
                }
                self.applyStructuralNamedEventBindingsForElem(ctx, stream, ids.ElemId.fromIndex(index), counts);
            }
        }

        /// Applies structural event bindings for seen after preparation has fixed semantics and reserved fallible growth.
        pub fn applyStructuralEventBindingsForSeen(self: *Self, ctx: Ctx.Handle, stream: *const HostNodeDescriptorStream, seen: []const bool, counts: *render.Counts) void {
            for (seen, 0..) |is_seen, index| {
                if (index == 0 or !is_seen) continue;

                for (render_event_kinds) |kind| {
                    const elem_id = ids.ElemId.fromIndex(index);
                    const next_binding = fixedEventBindingForElemKind(stream, elem_id, kind);
                    self.applyRenderEventBinding(ctx, elem_id, kind, next_binding, counts);
                }
                self.applyStructuralNamedEventBindingsForElem(ctx, stream, ids.ElemId.fromIndex(index), counts);
            }
        }

        /// Performs fixed event binding for elem kind inside the shared engine while preserving transaction and changed-set invariants.
        pub fn fixedEventBindingForElemKind(stream: *const HostNodeDescriptorStream, elem_id: ids.ElemId, kind: RenderEventKind) ?HostRequiredEventBinding {
            const descriptor_index = stream.elemDescriptorIndex(elem_id) orelse return null;
            const event_index = descriptor_index.events.get(kind) orelse return null;
            if (event_index >= stream.events.items.len) @panic("event descriptor index exceeded descriptor table");
            const desc = stream.events.items[event_index];
            const fixed_kind = desc.fixedKind() orelse @panic("fixed event descriptor index pointed at a named event");
            if (desc.elem_id != elem_id or fixed_kind != kind) @panic("fixed event descriptor index pointed at the wrong event");
            return .{ .event_id = ids.EventId.fromIndex(event_index + 1), .delivery = .{ .requested = desc.delivery_request }, .payload_descriptor = desc.payload_descriptor };
        }

        /// Performs named event binding for elem name inside the shared engine while preserving transaction and changed-set invariants.
        pub fn namedEventBindingForElemName(stream: *const HostNodeDescriptorStream, elem_id: ids.ElemId, name: []const u8) ?HostRequiredEventBinding {
            return namedEventBindingForElemFilter(stream, elem_id, name, null);
        }

        fn namedEventBindingForElemFilter(stream: *const HostNodeDescriptorStream, elem_id: ids.ElemId, name: []const u8, chord: ?@import("key_chord.zig").Chord) ?HostRequiredEventBinding {
            for (stream.namedEventIndices(elem_id)) |index| {
                if (index >= stream.events.items.len) @panic("named event index exceeded descriptor table");
                const desc = stream.events.items[index];
                const binding = desc.named() orelse @panic("named event index pointed at a fixed event descriptor");
                if (desc.elem_id == elem_id and std.mem.eql(u8, binding.name, name) and @import("key_chord.zig").optionalEql(binding.key_chord, chord)) {
                    return .{
                        .event_id = ids.EventId.fromIndex(index + 1),
                        .policy = binding.policy,
                        .delivery = .{ .requested = binding.delivery_request },
                        .key_chord = binding.key_chord,
                        .payload_descriptor = desc.payload_descriptor,
                    };
                }
            }
            return null;
        }

        /// Applies structural named event bindings for elem after preparation has fixed semantics and reserved fallible growth.
        pub fn applyStructuralNamedEventBindingsForElem(self: *Self, ctx: Ctx.Handle, stream: *const HostNodeDescriptorStream, elem_id: ids.ElemId, counts: *render.Counts) void {
            var cache_index: usize = 0;
            while (self.render_cache.namedEventAt(elem_id, cache_index)) |event| {
                if (namedEventBindingForElemFilter(stream, elem_id, event.name, event.binding.key_chord) == null) {
                    self.render_cache.applyNamedEventBindingFiltered(ctx, elem_id, event.name, event.binding.key_chord, null, counts);
                    continue;
                }
                cache_index += 1;
            }

            const named_event_indices = stream.namedEventIndices(elem_id);
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_events, named_event_indices.len);
            for (named_event_indices) |index| {
                if (index >= stream.events.items.len) @panic("named event index exceeded descriptor table");
                const desc = stream.events.items[index];
                const binding = desc.named() orelse @panic("named event index pointed at a fixed event descriptor");
                if (desc.elem_id != elem_id) @panic("named event index pointed at the wrong element");
                const event_id = ids.EventId.fromIndex(index + 1);
                self.applyRenderNamedEventBinding(ctx, elem_id, binding.name, .{
                    .event_id = event_id,
                    .policy = binding.policy,
                    .delivery = .{ .requested = binding.delivery_request },
                    .key_chord = binding.key_chord,
                    .payload_descriptor = desc.payload_descriptor,
                }, counts);
            }
        }

        /// Returns active event binding for elem kind from the maintained active-runtime indexes.
        pub fn activeEventBindingForElemKind(self: *Self, elem_id: u64, kind: RenderEventKind) ?HostRequiredEventBinding {
            const descriptor_index = self.active_stream.elemDescriptorIndex(elem_id) orelse return null;
            const event_index = descriptor_index.events.get(kind) orelse return null;
            if (event_index >= self.active_stream.events.items.len) @panic("active event descriptor index exceeded descriptor table");
            const desc = self.active_stream.events.items[event_index];
            const fixed_kind = desc.fixedKind() orelse @panic("active fixed event descriptor index pointed at a named event");
            if (desc.elem_id != elem_id or fixed_kind != kind) @panic("active event descriptor index pointed at the wrong event");
            return .{ .event_id = @intCast(event_index + 1), .delivery = .{ .requested = desc.delivery_request }, .payload_descriptor = desc.payload_descriptor };
        }

        /// Applies structural event bindings for elem after preparation has fixed semantics and reserved fallible growth.
        pub fn applyStructuralEventBindingsForElem(self: *Self, ctx: Ctx.Handle, elem_id: u64, counts: *render.Counts) void {
            for (render_event_kinds) |kind| {
                const next_binding = self.activeEventBindingForElemKind(elem_id, kind);
                self.applyRenderEventBinding(ctx, elem_id, kind, next_binding, counts);
            }
            self.applyStructuralNamedEventBindingsForElem(ctx, &self.active_stream, elem_id, counts);
        }

        /// Applies active stream event bindings after preparation has fixed semantics and reserved fallible growth.
        pub fn applyActiveStreamEventBindings(self: *Self, ctx: Ctx.Handle, counts: *render.Counts) void {
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_events, self.active_stream.render_nodes.items.len);
            for (self.active_stream.render_nodes.items) |node| {
                if (node.kind != .element) continue;
                self.applyStructuralEventBindingsForElem(ctx, node.elem_id, counts);
            }
        }

        /// Applies active stream text attr for elem after preparation has fixed semantics and reserved fallible growth.
        pub fn applyActiveStreamTextAttrForElem(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, elem_id: u64, field: RenderTextField, descriptor_index: HostElemDescriptorIndex, counts: *render.Counts, dirty_source_node_ids: []const u64, dirty_generation: u64) void {
            if (descriptor_index.static_text_attrs.get(field)) |attr_index| {
                if (attr_index >= self.active_stream.static_text_attrs.items.len) @panic("active static text attr index exceeded descriptor table");
                const desc = self.active_stream.static_text_attrs.items[attr_index];
                if (desc.elem_id != elem_id or desc.field != field) @panic("active static text attr index pointed at the wrong field");
                if (self.applyRenderTextField(ctx, desc.elem_id, desc.field, desc.value)) {
                    counts.addTextField(desc.field);
                }
            }

            if (descriptor_index.signal_text_attrs.get(field)) |attr_index| {
                if (attr_index >= self.active_stream.signal_text_attrs.items.len) @panic("active signal text attr index exceeded descriptor table");
                const desc = &self.active_stream.signal_text_attrs.items[attr_index];
                if (desc.elem_id != elem_id or desc.field != field) @panic("active signal text attr index pointed at the wrong field");
                if (self.evalStructuralSignalTextField(ctx, roc_host, desc.elem_id, desc.field, &desc.signal, desc.read, &desc.cached_value, dirty_source_node_ids, dirty_generation)) {
                    counts.addTextField(desc.field);
                }
            }
        }

        /// Clears render text attrs missing from stream while retaining bounded storage where the type promises reuse.
        pub fn clearRenderTextAttrsMissingFromStream(self: *Self, ctx: Ctx.Handle, stream: *const HostNodeDescriptorStream, elem_id: u64, counts: *render.Counts) void {
            var index: usize = 0;
            while (self.render_cache.customTextAttrNameAt(ids.ElemId.fromRaw(elem_id), index)) |name| {
                if (streamHasCustomTextAttr(stream, elem_id, name)) {
                    index += 1;
                    continue;
                }
                if (self.clearRenderTextAttr(ctx, ids.ElemId.fromRaw(elem_id), name)) {
                    counts.addTextAttr();
                }
            }
        }

        /// Applies active stream custom text attrs for elem after preparation has fixed semantics and reserved fallible growth.
        pub fn applyActiveStreamCustomTextAttrsForElem(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, elem_id: u64, counts: *render.Counts, dirty_source_node_ids: []const u64, dirty_generation: u64) void {
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, self.active_stream.static_custom_text_attrs.items.len);
            for (self.active_stream.static_custom_text_attrs.items) |desc| {
                if (desc.elem_id != elem_id) continue;
                if (self.applyRenderTextAttr(ctx, desc.elem_id, desc.name, desc.value)) {
                    counts.addTextAttr();
                }
            }

            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, self.active_stream.signal_custom_text_attrs.items.len);
            for (self.active_stream.signal_custom_text_attrs.items) |*desc| {
                if (desc.elem_id != elem_id) continue;
                if (self.evalStructuralSignalTextAttr(ctx, roc_host, desc.elem_id, desc.name, &desc.signal, desc.read, &desc.cached_value, dirty_source_node_ids, dirty_generation)) {
                    counts.addTextAttr();
                }
            }

            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, self.active_stream.signal_optional_custom_text_attrs.items.len);
            for (self.active_stream.signal_optional_custom_text_attrs.items) |*desc| {
                if (desc.elem_id != elem_id) continue;
                if (self.evalStructuralSignalOptionalTextAttr(ctx, roc_host, desc.elem_id, desc.name, &desc.signal, desc.present, desc.read, &desc.cached_value, dirty_source_node_ids, dirty_generation)) {
                    counts.addTextAttr();
                }
            }

            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, self.active_stream.static_custom_bool_attrs.items.len);
            for (self.active_stream.static_custom_bool_attrs.items) |desc| {
                if (desc.elem_id != elem_id) continue;
                if (self.applyRenderBoolAttr(ctx, desc.elem_id, desc.name, desc.value)) {
                    counts.addTextAttr();
                }
            }

            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, self.active_stream.signal_custom_bool_attrs.items.len);
            for (self.active_stream.signal_custom_bool_attrs.items) |*desc| {
                if (desc.elem_id != elem_id) continue;
                if (self.evalStructuralSignalBoolAttr(ctx, roc_host, desc.elem_id, desc.name, &desc.signal, desc.read, &desc.cached_value, dirty_source_node_ids, dirty_generation)) {
                    counts.addTextAttr();
                }
            }
        }

        fn applyActiveStreamCustomAttrsForElemSet(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, seen: []const bool, counts: *render.Counts, dirty_source_node_ids: []const u64, dirty_generation: u64) void {
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, self.active_stream.static_custom_text_attrs.items.len);
            for (self.active_stream.static_custom_text_attrs.items) |desc| {
                if (desc.elem_id >= seen.len or !seen[@intCast(desc.elem_id)]) continue;
                if (self.applyRenderTextAttr(ctx, desc.elem_id, desc.name, desc.value)) counts.addTextAttr();
            }
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, self.active_stream.signal_custom_text_attrs.items.len);
            for (self.active_stream.signal_custom_text_attrs.items) |*desc| {
                if (desc.elem_id >= seen.len or !seen[@intCast(desc.elem_id)]) continue;
                if (self.evalStructuralSignalTextAttr(ctx, roc_host, desc.elem_id, desc.name, &desc.signal, desc.read, &desc.cached_value, dirty_source_node_ids, dirty_generation)) counts.addTextAttr();
            }
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, self.active_stream.signal_optional_custom_text_attrs.items.len);
            for (self.active_stream.signal_optional_custom_text_attrs.items) |*desc| {
                if (desc.elem_id >= seen.len or !seen[@intCast(desc.elem_id)]) continue;
                if (self.evalStructuralSignalOptionalTextAttr(ctx, roc_host, desc.elem_id, desc.name, &desc.signal, desc.present, desc.read, &desc.cached_value, dirty_source_node_ids, dirty_generation)) counts.addTextAttr();
            }
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, self.active_stream.static_custom_bool_attrs.items.len);
            for (self.active_stream.static_custom_bool_attrs.items) |desc| {
                if (desc.elem_id >= seen.len or !seen[@intCast(desc.elem_id)]) continue;
                if (self.applyRenderBoolAttr(ctx, desc.elem_id, desc.name, desc.value)) counts.addTextAttr();
            }
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, self.active_stream.signal_custom_bool_attrs.items.len);
            for (self.active_stream.signal_custom_bool_attrs.items) |*desc| {
                if (desc.elem_id >= seen.len or !seen[@intCast(desc.elem_id)]) continue;
                if (self.evalStructuralSignalBoolAttr(ctx, roc_host, desc.elem_id, desc.name, &desc.signal, desc.read, &desc.cached_value, dirty_source_node_ids, dirty_generation)) counts.addTextAttr();
            }
        }

        /// Applies active stream bool attr for elem after preparation has fixed semantics and reserved fallible growth.
        pub fn applyActiveStreamBoolAttrForElem(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, elem_id: u64, field: RenderBoolField, descriptor_index: HostElemDescriptorIndex, counts: *render.Counts, dirty_source_node_ids: []const u64, dirty_generation: u64) void {
            if (descriptor_index.static_bool_attrs.get(field)) |attr_index| {
                if (attr_index >= self.active_stream.static_bool_attrs.items.len) @panic("active static bool attr index exceeded descriptor table");
                const desc = self.active_stream.static_bool_attrs.items[attr_index];
                if (desc.elem_id != elem_id or desc.field != field) @panic("active static bool attr index pointed at the wrong field");
                if (self.applyRenderBoolField(ctx, desc.elem_id, desc.field, desc.value)) {
                    counts.addBoolField(desc.field);
                }
            }

            if (descriptor_index.signal_bool_attrs.get(field)) |attr_index| {
                if (attr_index >= self.active_stream.signal_bool_attrs.items.len) @panic("active signal bool attr index exceeded descriptor table");
                const desc = &self.active_stream.signal_bool_attrs.items[attr_index];
                if (desc.elem_id != elem_id or desc.field != field) @panic("active signal bool attr index pointed at the wrong field");
                if (self.evalStructuralSignalBoolField(ctx, roc_host, desc.elem_id, desc.field, &desc.signal, desc.read, &desc.cached_value, dirty_source_node_ids, dirty_generation)) {
                    counts.addBoolField(desc.field);
                }
            }
        }

        fn applyActiveStreamFieldsForElemOptions(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, elem_id: u64, counts: *render.Counts, dirty_source_node_ids: []const u64, dirty_generation: u64, apply_custom_attrs: bool) void {
            const descriptor_index = self.active_stream.elemDescriptorIndex(elem_id) orelse @panic("active render node had no descriptor index");
            const text_fields = std.enums.values(RenderTextField);
            const bool_fields = std.enums.values(RenderBoolField);

            for (text_fields) |field| {
                if (!streamHasTextField(&self.active_stream, elem_id, field) and self.clearRenderTextField(ctx, elem_id, field)) {
                    counts.addTextField(field);
                }
            }
            for (bool_fields) |field| {
                if (!streamHasBoolField(&self.active_stream, elem_id, field) and self.clearRenderBoolField(ctx, elem_id, field)) {
                    counts.addBoolField(field);
                }
            }
            self.clearRenderTextAttrsMissingFromStream(ctx, &self.active_stream, elem_id, counts);

            if (descriptor_index.text_node.get()) |text_index| {
                if (text_index >= self.active_stream.text_nodes.items.len) @panic("active text node index exceeded descriptor table");
                const desc = self.active_stream.text_nodes.items[text_index];
                if (desc.elem_id != elem_id) @panic("active text node index pointed at the wrong elem id");
                if (self.applyRenderTextField(ctx, desc.elem_id, .text, desc.value)) {
                    counts.addTextField(.text);
                }
            }

            if (descriptor_index.signal_text_node.get()) |signal_text_index| {
                if (signal_text_index >= self.active_stream.signal_text_nodes.items.len) @panic("active signal text node index exceeded descriptor table");
                const desc = &self.active_stream.signal_text_nodes.items[signal_text_index];
                if (desc.elem_id != elem_id) @panic("active signal text node index pointed at the wrong elem id");
                if (self.evalStructuralSignalTextField(ctx, roc_host, desc.elem_id, .text, &desc.signal, desc.read, &desc.cached_value, dirty_source_node_ids, dirty_generation)) {
                    counts.addTextField(.text);
                }
            }

            for (text_fields) |field| {
                self.applyActiveStreamTextAttrForElem(ctx, roc_host, elem_id, field, descriptor_index, counts, dirty_source_node_ids, dirty_generation);
            }
            if (apply_custom_attrs) self.applyActiveStreamCustomTextAttrsForElem(ctx, roc_host, elem_id, counts, dirty_source_node_ids, dirty_generation);
            for (bool_fields) |field| {
                self.applyActiveStreamBoolAttrForElem(ctx, roc_host, elem_id, field, descriptor_index, counts, dirty_source_node_ids, dirty_generation);
            }
        }

        /// Applies active stream fields for elem after preparation has fixed semantics and reserved fallible growth.
        pub fn applyActiveStreamFieldsForElem(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, elem_id: u64, counts: *render.Counts, dirty_source_node_ids: []const u64, dirty_generation: u64) void {
            self.applyActiveStreamFieldsForElemOptions(ctx, roc_host, elem_id, counts, dirty_source_node_ids, dirty_generation, true);
        }

        /// Applies structural node descriptor target after preparation has fixed semantics and reserved fallible growth.
        pub fn applyStructuralNodeDescriptorTarget(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, stream: *HostNodeDescriptorStream, targets: HostStructuralPatchTargets) render.Counts {
            if (!self.hasRenderRoot()) @panic("structural DOM patch requested before initial DOM root creation");

            const allocator = Ctx.allocator(ctx);
            const max_elem_id = @max(maxRenderElemId(&self.active_stream), maxRenderElemId(stream));
            const required_child_table_len: usize = @intCast(max_elem_id + 1);
            const child_table_len = required_child_table_len;
            self.ensureRenderNodeCapacity(ctx, required_child_table_len);

            var seen = allocator.alloc(bool, child_table_len) catch @panic("out of memory");
            defer allocator.free(seen);
            @memset(seen, false);

            var touched_parents: shared_buffer.List(u64) = .empty;
            defer touched_parents.deinit(allocator);

            var counts: render.Counts = .{};

            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, stream.render_nodes.items.len);
            for (stream.render_nodes.items) |node| {
                if (!self.renderNodeInReplacementTarget(stream, node, targets.replacement)) continue;
                if (node.elem_id.index() >= child_table_len) @panic("render node exceeded structural DOM patch table");

                const parent_elem_id = renderNodeParentElemId(stream, node);
                if (parent_elem_id >= child_table_len) @panic("render node referenced parent outside structural DOM patch table");

                const tag = descriptor_stream.renderNodeShape(HostNodeDescriptorStream, stream, node);
                if (self.activeRenderNodeShapeDiffers(node.elem_id.raw(), tag)) {
                    self.removeRenderNode(ctx, node.elem_id.raw(), &counts);
                }
                self.ensureRenderNode(ctx, node.elem_id.raw(), tag, &counts);
                seen[node.elem_id.index()] = true;
                appendUniqueU64(allocator, &touched_parents, parent_elem_id);
            }

            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, self.active_stream.render_nodes.items.len);
            for (self.active_stream.render_nodes.items) |node| {
                if (!self.renderNodeInReplacementTarget(&self.active_stream, node, targets.removed)) continue;
                if (node.elem_id < seen.len and seen[@intCast(node.elem_id)]) continue;
                if (!self.hasActiveRenderNode(node.elem_id)) continue;
                self.removeRenderNode(ctx, node.elem_id, &counts);
            }

            for (touched_parents.items) |parent_elem_id| {
                const children = streamDirectChildrenInto(allocator, stream, parent_elem_id, &self.scratch.stream_direct_children);
                self.replaceRenderChildren(ctx, parent_elem_id, children, &counts);
            }

            const text_fields = std.enums.values(RenderTextField);
            const bool_fields = std.enums.values(RenderBoolField);
            for (seen, 0..) |is_seen, index| {
                if (index == 0 or !is_seen) continue;
                const elem_id: u64 = @intCast(index);

                for (text_fields) |field| {
                    if (!streamHasTextField(stream, elem_id, field) and self.clearRenderTextField(ctx, elem_id, field)) {
                        counts.addTextField(field);
                    }
                }
                for (bool_fields) |field| {
                    if (!streamHasBoolField(stream, elem_id, field) and self.clearRenderBoolField(ctx, elem_id, field)) {
                        counts.addBoolField(field);
                    }
                }
                self.clearRenderTextAttrsMissingFromStream(ctx, stream, elem_id, &counts);
            }

            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, stream.text_nodes.items.len);
            for (stream.text_nodes.items) |desc| {
                if (desc.elem_id < seen.len and seen[@intCast(desc.elem_id)] and self.applyRenderTextField(ctx, desc.elem_id, .text, desc.value)) {
                    counts.addTextField(.text);
                }
            }
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, stream.signal_text_nodes.items.len);
            for (stream.signal_text_nodes.items) |*desc| {
                if (desc.elem_id < seen.len and seen[@intCast(desc.elem_id)] and self.evalSignalTextField(ctx, roc_host, desc.elem_id, .text, &desc.signal, desc.read, &desc.cached_value)) {
                    counts.addTextField(.text);
                }
            }
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, stream.static_text_attrs.items.len);
            for (stream.static_text_attrs.items) |desc| {
                if (desc.elem_id < seen.len and seen[@intCast(desc.elem_id)] and self.applyRenderTextField(ctx, desc.elem_id, desc.field, desc.value)) {
                    counts.addTextField(desc.field);
                }
            }
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, stream.signal_text_attrs.items.len);
            for (stream.signal_text_attrs.items) |*desc| {
                if (desc.elem_id < seen.len and seen[@intCast(desc.elem_id)] and self.evalSignalTextField(ctx, roc_host, desc.elem_id, desc.field, &desc.signal, desc.read, &desc.cached_value)) {
                    counts.addTextField(desc.field);
                }
            }
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, stream.static_custom_text_attrs.items.len);
            for (stream.static_custom_text_attrs.items) |desc| {
                if (desc.elem_id < seen.len and seen[@intCast(desc.elem_id)] and self.applyRenderTextAttr(ctx, desc.elem_id, desc.name, desc.value)) {
                    counts.addTextAttr();
                }
            }
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, stream.signal_custom_text_attrs.items.len);
            for (stream.signal_custom_text_attrs.items) |*desc| {
                if (desc.elem_id < seen.len and seen[@intCast(desc.elem_id)] and self.evalSignalTextAttr(ctx, roc_host, desc.elem_id, desc.name, &desc.signal, desc.read, &desc.cached_value)) {
                    counts.addTextAttr();
                }
            }
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, stream.signal_optional_custom_text_attrs.items.len);
            for (stream.signal_optional_custom_text_attrs.items) |*desc| {
                if (desc.elem_id < seen.len and seen[@intCast(desc.elem_id)] and self.evalSignalOptionalTextAttr(ctx, roc_host, desc.elem_id, desc.name, &desc.signal, desc.present, desc.read, &desc.cached_value)) {
                    counts.addTextAttr();
                }
            }
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, stream.static_custom_bool_attrs.items.len);
            for (stream.static_custom_bool_attrs.items) |desc| {
                if (desc.elem_id < seen.len and seen[@intCast(desc.elem_id)] and self.applyRenderBoolAttr(ctx, desc.elem_id, desc.name, desc.value)) {
                    counts.addTextAttr();
                }
            }
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, stream.signal_custom_bool_attrs.items.len);
            for (stream.signal_custom_bool_attrs.items) |*desc| {
                if (desc.elem_id < seen.len and seen[@intCast(desc.elem_id)] and self.evalSignalBoolAttr(ctx, roc_host, desc.elem_id, desc.name, &desc.signal, desc.read, &desc.cached_value)) {
                    counts.addTextAttr();
                }
            }
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, stream.static_bool_attrs.items.len);
            for (stream.static_bool_attrs.items) |desc| {
                if (desc.elem_id < seen.len and seen[@intCast(desc.elem_id)] and self.applyRenderBoolField(ctx, desc.elem_id, desc.field, desc.value)) {
                    counts.addBoolField(desc.field);
                }
            }
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, stream.signal_bool_attrs.items.len);
            for (stream.signal_bool_attrs.items) |*desc| {
                if (desc.elem_id < seen.len and seen[@intCast(desc.elem_id)] and self.evalSignalBoolField(ctx, roc_host, desc.elem_id, desc.field, &desc.signal, desc.read, &desc.cached_value)) {
                    counts.addBoolField(desc.field);
                }
            }
            self.recordStreamNodesScannedBy(.stream_nodes_scanned_apply, stream.on_changes.items.len);
            for (stream.on_changes.items) |*desc| {
                if (self.scopeIsInReplacementTarget(desc.scope_id, targets.replacement)) {
                    self.evalOnChangeInitial(ctx, roc_host, desc);
                }
            }

            self.applyStructuralEventBindingsForSeen(ctx, stream, seen, &counts);
            self.debugAssertRenderCacheMatchesStream(ctx, stream);
            self.debugAssertRenderCacheMatchesSink(ctx);

            self.rebuildActiveSignalGraphFromStream(ctx, stream);
            if (comptime enable_runtime_metrics) self.render_metrics.addCommandCounts(counts);
            return counts;
        }

        /// Applies node descriptor stream after preparation has fixed semantics and reserved fallible growth.
        pub fn applyNodeDescriptorStream(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, stream: *HostNodeDescriptorStream) render.Counts {
            var counts: render.Counts = .{};
            counts.addHostReset();
            self.resetRenderTree(ctx);
            self.ensureRenderNodeCapacity(ctx, @intCast(maxRenderElemId(stream) + 1));

            for (stream.render_nodes.items) |node| {
                switch (node.kind) {
                    .element => {
                        const desc = findElementDesc(stream, node.elem_id.raw()) orelse @panic("render node referenced missing element descriptor");
                        self.appendRenderNodeShape(ctx, desc.elem_id, desc.parent_elem_id, .{ .element = .{ .tag = desc.tag, .namespace = desc.namespace } });
                        counts.addCreateElement();
                        counts.addAppendChild();
                    },
                    .text => {
                        const desc = findTextNodeDesc(stream, node.elem_id.raw()) orelse @panic("render node referenced missing text descriptor");
                        self.appendRenderNodeShape(ctx, desc.elem_id, desc.parent_elem_id, .text);
                        counts.addCreateElement();
                        counts.addAppendChild();
                        if (self.applyRenderTextField(ctx, desc.elem_id, .text, desc.value)) {
                            counts.addTextField(.text);
                        }
                    },
                    .signal_text => {
                        const desc = findSignalTextNodeDescMutable(stream, node.elem_id.raw()) orelse @panic("render node referenced missing signal text descriptor");
                        self.appendRenderNodeShape(ctx, desc.elem_id, desc.parent_elem_id, .text);
                        counts.addCreateElement();
                        counts.addAppendChild();
                        if (self.evalSignalTextField(ctx, roc_host, desc.elem_id.raw(), .text, &desc.signal, desc.read, &desc.cached_value)) {
                            counts.addTextField(.text);
                        }
                    },
                }
            }

            for (stream.static_text_attrs.items) |desc| {
                if (self.applyRenderTextField(ctx, desc.elem_id, desc.field, desc.value)) {
                    counts.addTextField(desc.field);
                }
            }
            for (stream.signal_text_attrs.items) |*desc| {
                if (self.evalSignalTextField(ctx, roc_host, desc.elem_id.raw(), desc.field, &desc.signal, desc.read, &desc.cached_value)) {
                    counts.addTextField(desc.field);
                }
            }
            for (stream.static_custom_text_attrs.items) |desc| {
                if (self.applyRenderTextAttr(ctx, desc.elem_id, desc.name, desc.value)) {
                    counts.addTextAttr();
                }
            }
            for (stream.signal_custom_text_attrs.items) |*desc| {
                if (self.evalSignalTextAttr(ctx, roc_host, desc.elem_id.raw(), desc.name, &desc.signal, desc.read, &desc.cached_value)) {
                    counts.addTextAttr();
                }
            }
            for (stream.signal_optional_custom_text_attrs.items) |*desc| {
                if (self.evalSignalOptionalTextAttr(ctx, roc_host, desc.elem_id.raw(), desc.name, &desc.signal, desc.present, desc.read, &desc.cached_value)) {
                    counts.addTextAttr();
                }
            }
            for (stream.static_custom_bool_attrs.items) |desc| {
                if (self.applyRenderBoolAttr(ctx, desc.elem_id, desc.name, desc.value)) {
                    counts.addTextAttr();
                }
            }
            for (stream.signal_custom_bool_attrs.items) |*desc| {
                if (self.evalSignalBoolAttr(ctx, roc_host, desc.elem_id.raw(), desc.name, &desc.signal, desc.read, &desc.cached_value)) {
                    counts.addTextAttr();
                }
            }
            for (stream.static_bool_attrs.items) |desc| {
                if (self.applyRenderBoolField(ctx, desc.elem_id, desc.field, desc.value)) {
                    counts.addBoolField(desc.field);
                }
            }
            for (stream.signal_bool_attrs.items) |*desc| {
                if (self.evalSignalBoolField(ctx, roc_host, desc.elem_id.raw(), desc.field, &desc.signal, desc.read, &desc.cached_value)) {
                    counts.addBoolField(desc.field);
                }
            }
            for (stream.on_changes.items) |*desc| {
                self.evalOnChangeInitial(ctx, roc_host, desc);
            }
            for (stream.events.items, 0..) |desc, index| {
                const event_id = ids.EventId.fromIndex(index + 1);
                switch (desc.binding) {
                    .fixed => |kind| self.applyRenderEventBinding(ctx, desc.elem_id, kind, .{ .event_id = event_id, .delivery = .{ .requested = desc.delivery_request }, .payload_descriptor = desc.payload_descriptor }, &counts),
                    .named => |binding| self.applyRenderNamedEventBinding(ctx, desc.elem_id, binding.name, .{
                        .event_id = event_id,
                        .policy = binding.policy,
                        .delivery = .{ .requested = binding.delivery_request },
                        .key_chord = binding.key_chord,
                        .payload_descriptor = desc.payload_descriptor,
                    }, &counts),
                }
            }

            self.debugAssertRenderCacheMatchesStream(ctx, stream);
            self.debugAssertRenderCacheMatchesSink(ctx);
            self.rebuildActiveSignalGraphFromStream(ctx, stream);
            if (comptime enable_runtime_metrics) self.render_metrics.addCommandCounts(counts);
            return counts;
        }

        /// Applies spliced structural node descriptor target after preparation has fixed semantics and reserved fallible growth.
        pub fn applySplicedStructuralNodeDescriptorTarget(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, splice: HostStructuralSplice, targets: HostStructuralPatchTargets, dirty_source_node_ids: []const u64, dirty_generation: u64) render.Counts {
            _ = targets;
            if (!self.hasRenderRoot()) @panic("structural DOM patch requested before initial DOM root creation");

            const allocator = Ctx.allocator(ctx);
            var max_elem_id: u64 = 0;
            for (splice.removed_elem_ids) |elem_id| {
                max_elem_id = @max(max_elem_id, elem_id);
            }
            for (splice.replacement_elem_ids) |elem_id| {
                max_elem_id = @max(max_elem_id, elem_id);
            }
            const required_child_table_len: usize = @intCast(max_elem_id + 1);
            const child_table_len = required_child_table_len;
            self.ensureRenderNodeCapacity(ctx, required_child_table_len);

            var seen = allocator.alloc(bool, child_table_len) catch @panic("out of memory");
            defer allocator.free(seen);
            @memset(seen, false);
            var replacement_members = allocator.alloc(bool, child_table_len) catch @panic("out of memory");
            defer allocator.free(replacement_members);
            @memset(replacement_members, false);
            for (splice.replacement_elem_ids) |elem_id| replacement_members[@intCast(elem_id)] = true;
            var removed_members = allocator.alloc(bool, child_table_len) catch @panic("out of memory");
            defer allocator.free(removed_members);
            @memset(removed_members, false);
            for (splice.removed_elem_ids) |elem_id| removed_members[@intCast(elem_id)] = true;

            var touched_parents: shared_buffer.List(u64) = .empty;
            defer touched_parents.deinit(allocator);
            var touched_parent_set: std.AutoHashMapUnmanaged(u64, void) = .empty;
            defer touched_parent_set.deinit(allocator);
            for (splice.touched_parent_ids) |parent_id| {
                const entry = touched_parent_set.getOrPut(allocator, parent_id) catch @panic("out of memory");
                if (!entry.found_existing) touched_parents.append(allocator, parent_id) catch @panic("out of memory");
            }

            var counts: render.Counts = .{};

            self.recordStreamNodesScannedBy(.stream_nodes_scanned_splice, splice.replacement_elem_ids.len);
            for (splice.replacement_elem_ids) |elem_id| {
                if (elem_id >= child_table_len) @panic("render node exceeded structural DOM patch table");

                const parent_elem_id = streamElemParentElemId(&self.active_stream, elem_id);
                const parent_available = parent_elem_id == 0 or
                    (parent_elem_id < replacement_members.len and replacement_members[@intCast(parent_elem_id)]) or
                    (self.hasActiveRenderNode(parent_elem_id) and
                        !(parent_elem_id < removed_members.len and removed_members[@intCast(parent_elem_id)]));
                if (!parent_available) {
                    @panic("render node referenced unavailable parent in structural DOM splice");
                }

                const tag = descriptor_stream.streamElemShape(HostNodeDescriptorStream, &self.active_stream, ids.ElemId.fromRaw(elem_id));
                if (self.activeRenderNodeShapeDiffers(elem_id, tag)) {
                    self.removeRenderNode(ctx, elem_id, &counts);
                }
                self.ensureRenderNode(ctx, elem_id, tag, &counts);
                seen[@intCast(elem_id)] = true;
                const entry = touched_parent_set.getOrPut(allocator, parent_elem_id) catch @panic("out of memory");
                if (!entry.found_existing) touched_parents.append(allocator, parent_elem_id) catch @panic("out of memory");
            }

            for (splice.removed_elem_ids) |elem_id| {
                if (elem_id < seen.len and seen[@intCast(elem_id)]) continue;
                if (!self.hasActiveRenderNode(elem_id)) continue;
                self.removeRenderNode(ctx, elem_id, &counts);
            }

            for (touched_parents.items) |parent_elem_id| {
                const children = streamDirectChildrenInto(allocator, &self.active_stream, parent_elem_id, &self.scratch.stream_direct_children);
                self.replaceRenderChildren(ctx, parent_elem_id, children, &counts);
            }

            for (splice.replacement_elem_ids) |elem_id| {
                self.applyActiveStreamFieldsForElemOptions(ctx, roc_host, elem_id, &counts, dirty_source_node_ids, dirty_generation, false);
            }
            self.applyActiveStreamCustomAttrsForElemSet(ctx, roc_host, seen, &counts, dirty_source_node_ids, dirty_generation);
            var event_binding_elem_ids: shared_buffer.List(u64) = .empty;
            defer event_binding_elem_ids.deinit(allocator);
            var event_binding_elem_set: std.AutoHashMapUnmanaged(u64, void) = .empty;
            defer event_binding_elem_set.deinit(allocator);
            for (splice.replacement_elem_ids) |elem_id| {
                const entry = event_binding_elem_set.getOrPut(allocator, elem_id) catch @panic("out of memory");
                if (!entry.found_existing) event_binding_elem_ids.append(allocator, elem_id) catch @panic("out of memory");
            }
            for (touched_parents.items) |parent_elem_id| {
                const children = streamDirectChildrenInto(allocator, &self.active_stream, parent_elem_id, &self.scratch.stream_direct_children);
                for (children) |child_id| {
                    const entry = event_binding_elem_set.getOrPut(allocator, child_id) catch @panic("out of memory");
                    if (!entry.found_existing) event_binding_elem_ids.append(allocator, child_id) catch @panic("out of memory");
                }
            }
            for (splice.moved_event_elem_ids) |elem_id| {
                const entry = event_binding_elem_set.getOrPut(allocator, elem_id) catch @panic("out of memory");
                if (!entry.found_existing) event_binding_elem_ids.append(allocator, elem_id) catch @panic("out of memory");
            }
            for (event_binding_elem_ids.items) |elem_id| {
                if (!self.hasActiveRenderNode(elem_id)) continue;
                self.applyStructuralEventBindingsForElem(ctx, elem_id, &counts);
            }

            self.recordStreamNodesScannedBy(.stream_nodes_scanned_splice, splice.replacement_on_change_indices.len);
            for (splice.replacement_on_change_indices) |on_change_index| {
                if (on_change_index >= self.active_stream.on_changes.items.len) @panic("structural splice on_change index exceeded active descriptor stream");
                const desc = &self.active_stream.on_changes.items[on_change_index];
                self.evalOnChangeInitial(ctx, roc_host, desc);
            }

            self.debugAssertRenderCacheMatchesStream(ctx, &self.active_stream);
            self.debugAssertRenderCacheMatchesSink(ctx);
            counts.addAll(self.runActiveOnChangeInitialCommandIndices(ctx, roc_host, splice.replacement_on_change_indices));
            counts.addAll(self.runActiveMountCommandIndices(ctx, roc_host, splice.replacement_mount_indices));
            if (comptime enable_runtime_metrics) self.render_metrics.addCommandCounts(counts);
            return counts;
        }

        /// Applies structural node descriptor stream after preparation has fixed semantics and reserved fallible growth.
        pub fn applyStructuralNodeDescriptorStream(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, stream: *HostNodeDescriptorStream) render.Counts {
            if (!builtin.is_test) @compileError("applyStructuralNodeDescriptorStream is a pre-transactional engine path kept only for tests; production goes through prepared transactions");
            if (!self.hasRenderRoot()) @panic("structural DOM patch requested before initial DOM root creation");

            const allocator = Ctx.allocator(ctx);
            const max_elem_id = @max(maxRenderElemId(&self.active_stream), maxRenderElemId(stream));
            const required_child_table_len: usize = @intCast(max_elem_id + 1);
            const child_table_len = required_child_table_len;
            self.ensureRenderNodeCapacity(ctx, required_child_table_len);

            var seen = allocator.alloc(bool, child_table_len) catch @panic("out of memory");
            defer allocator.free(seen);
            @memset(seen, false);

            var next_children = allocator.alloc(shared_buffer.List(ids.ElemId), child_table_len) catch @panic("out of memory");
            defer {
                for (next_children) |*children| {
                    children.deinit(allocator);
                }
                allocator.free(next_children);
            }
            for (next_children) |*children| {
                children.* = .empty;
            }

            var counts: render.Counts = .{};

            for (stream.render_nodes.items) |node| {
                if (node.elem_id.index() >= child_table_len) @panic("render node exceeded structural DOM patch table");

                const parent_elem_id = renderNodeParentElemId(stream, node);
                if (parent_elem_id >= child_table_len) @panic("render node referenced parent outside structural DOM patch table");

                const tag = descriptor_stream.renderNodeShape(HostNodeDescriptorStream, stream, node);
                if (self.activeRenderNodeShapeDiffers(node.elem_id, tag)) {
                    self.removeRenderNode(ctx, node.elem_id, &counts);
                }
                self.ensureRenderNode(ctx, node.elem_id, tag, &counts);
                seen[node.elem_id.index()] = true;

                next_children[@intCast(parent_elem_id)].append(allocator, node.elem_id) catch @panic("out of memory");
            }

            for (self.active_stream.render_nodes.items) |node| {
                const still_rendered = node.elem_id.index() < seen.len and seen[node.elem_id.index()];
                if (!still_rendered and self.hasActiveRenderNode(node.elem_id)) self.removeRenderNode(ctx, node.elem_id, &counts);
            }

            for (next_children, 0..) |*children, index| {
                const accepts_children = index == 0 or (index < seen.len and seen[index]);
                if (!accepts_children) continue;
                self.replaceRenderChildren(ctx, ids.ElemId.fromRaw(@intCast(index)), children.items, &counts);
            }

            const text_fields = std.enums.values(RenderTextField);
            const bool_fields = std.enums.values(RenderBoolField);
            for (seen, 0..) |is_seen, index| {
                if (index == 0 or !is_seen) continue;
                const elem_id: u64 = @intCast(index);

                for (text_fields) |field| {
                    if (!streamHasTextField(stream, elem_id, field) and self.clearRenderTextField(ctx, ids.ElemId.fromRaw(elem_id), field)) {
                        counts.addTextField(field);
                    }
                }
                for (bool_fields) |field| {
                    if (!streamHasBoolField(stream, elem_id, field) and self.clearRenderBoolField(ctx, ids.ElemId.fromRaw(elem_id), field)) {
                        counts.addBoolField(field);
                    }
                }
                self.clearRenderTextAttrsMissingFromStream(ctx, stream, elem_id, &counts);
            }

            for (stream.text_nodes.items) |desc| {
                if (self.applyRenderTextField(ctx, desc.elem_id, .text, desc.value)) {
                    counts.addTextField(.text);
                }
            }
            for (stream.signal_text_nodes.items) |*desc| {
                if (self.evalSignalTextField(ctx, roc_host, desc.elem_id.raw(), .text, &desc.signal, desc.read, &desc.cached_value)) {
                    counts.addTextField(.text);
                }
            }
            for (stream.static_text_attrs.items) |desc| {
                if (self.applyRenderTextField(ctx, desc.elem_id, desc.field, desc.value)) {
                    counts.addTextField(desc.field);
                }
            }
            for (stream.signal_text_attrs.items) |*desc| {
                if (self.evalSignalTextField(ctx, roc_host, desc.elem_id.raw(), desc.field, &desc.signal, desc.read, &desc.cached_value)) {
                    counts.addTextField(desc.field);
                }
            }
            for (stream.static_custom_text_attrs.items) |desc| {
                if (self.applyRenderTextAttr(ctx, desc.elem_id, desc.name, desc.value)) {
                    counts.addTextAttr();
                }
            }
            for (stream.signal_custom_text_attrs.items) |*desc| {
                if (self.evalSignalTextAttr(ctx, roc_host, desc.elem_id.raw(), desc.name, &desc.signal, desc.read, &desc.cached_value)) {
                    counts.addTextAttr();
                }
            }
            for (stream.signal_optional_custom_text_attrs.items) |*desc| {
                if (self.evalSignalOptionalTextAttr(ctx, roc_host, desc.elem_id.raw(), desc.name, &desc.signal, desc.present, desc.read, &desc.cached_value)) {
                    counts.addTextAttr();
                }
            }
            for (stream.static_custom_bool_attrs.items) |desc| {
                if (self.applyRenderBoolAttr(ctx, desc.elem_id, desc.name, desc.value)) {
                    counts.addTextAttr();
                }
            }
            for (stream.signal_custom_bool_attrs.items) |*desc| {
                if (self.evalSignalBoolAttr(ctx, roc_host, desc.elem_id.raw(), desc.name, &desc.signal, desc.read, &desc.cached_value)) {
                    counts.addTextAttr();
                }
            }
            for (stream.static_bool_attrs.items) |desc| {
                if (self.applyRenderBoolField(ctx, desc.elem_id, desc.field, desc.value)) {
                    counts.addBoolField(desc.field);
                }
            }
            for (stream.signal_bool_attrs.items) |*desc| {
                if (self.evalSignalBoolField(ctx, roc_host, desc.elem_id.raw(), desc.field, &desc.signal, desc.read, &desc.cached_value)) {
                    counts.addBoolField(desc.field);
                }
            }
            for (stream.on_changes.items) |*desc| {
                self.evalOnChangeInitial(ctx, roc_host, desc);
            }

            self.applyStructuralEventBindings(ctx, stream, seen, &counts);
            self.debugAssertRenderCacheMatchesStream(ctx, stream);
            self.debugAssertRenderCacheMatchesSink(ctx);

            self.rebuildActiveSignalGraphFromStream(ctx, stream);
            if (comptime enable_runtime_metrics) self.render_metrics.addCommandCounts(counts);
            return counts;
        }

        /// Applies dirty structural signals locally after preparation has fixed semantics and reserved fallible growth.
        pub fn applyDirtyStructuralSignalsLocally(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, dirty_source_node_ids: []const u64, dirty_generation: u64, changes: []HostDirtyStructuralSignal) render.Counts {
            if (!builtin.is_test) @compileError("applyDirtyStructuralSignalsLocally is a pre-transactional engine path kept only for tests; production goes through prepared transactions");
            _ = dirty_generation;
            var all_when = changes.len != 0;
            for (changes) |change| all_when = all_when and change.kind == .when;
            if (all_when) {
                if (self.tryApplyPreparedDirtyWhenSet(ctx, roc_host, dirty_source_node_ids, changes) catch {
                    @panic("failed to prepare atomic dirty-when transaction");
                }) |counts| return counts;
                @panic("dirty-when set could not enter the atomic transaction");
            }
            if (changes.len == 1 and changes[0].kind == .each) {
                if (self.tryApplyPreparedDirtyEach(ctx, roc_host, dirty_source_node_ids, &changes[0]) catch {
                    @panic("failed to prepare atomic dirty-each transaction");
                }) |counts| return counts;
                @panic("dirty-each change could not enter the atomic transaction");
            }
            if (changes.len == 0) return .{};
            @panic("mixed or multiple dirty-each structural changes require one atomic transaction");
        }

        fn tryApplyPreparedDirtyEach(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, dirty_source_node_ids: []const u64, change: *const HostDirtyStructuralSignal) CollectionError!?render.Counts {
            if (change.kind != .each or !self.render_cache.hasRoot()) return null;
            const site = self.activeScopeSiteByNodeId(change.node_id.raw(), .each) orelse return null;
            if (site.scope_id != change.scope_id or site.ordinal != change.ordinal) return null;
            const each_index = self.activeEachIndexByNodeId(change.node_id.raw()) orelse return null;
            const each_desc = self.active_stream.eaches.items[each_index];
            if (each_desc.items.record != change.record) return null;

            const allocator = Ctx.allocator(ctx);
            const rows = try PreparedActiveEachRows.prepare(self, ctx, roc_host, site, each_desc, allocator);
            defer rows.deinit();
            const replacement = try PreparedEachRowReplacementCollection.prepare(self, ctx, roc_host, site, each_desc, rows, .{}, dirty_source_node_ids, null, &.{});
            defer replacement.deinit();
            var layout = try PreparedEachRowRenderLayout.prepare(self, allocator, site, &rows.rows, replacement.replacement_rows, &replacement.replacement.collection);
            defer layout.deinit();
            const downstream = try PreparedStructuralDownstream.prepareExternalEach(self, ctx, roc_host, &rows.rows, &rows.inputs, replacement, &layout, null);
            defer downstream.deinit();

            const RowCommit = struct {
                plan: *PreparedActiveEachRows,
                diff: ?HostKeyedRowDiffResult = null,

                fn apply(transaction: *@This()) void {
                    transaction.diff = transaction.plan.commit();
                }
            };
            var row_commit = RowCommit{ .plan = rows };
            var counts = downstream.render_splice.?.counts();
            downstream.commitAssumeCapacityWith(&row_commit, RowCommit.apply);
            var diff = row_commit.diff orelse @panic("prepared each row commit was skipped");
            defer diff.deinit(allocator);
            counts.addAll(self.runActiveOnChangeInitialCommandIndices(ctx, roc_host, downstream.publication.?.replacement_on_change_indices));
            counts.addAll(self.runActiveMountCommandIndices(ctx, roc_host, downstream.publication.?.replacement_mount_indices));
            if (comptime enable_runtime_metrics) self.render_metrics.addCommandCounts(counts);
            return counts;
        }

        const PreparedDirtyWhenSet = struct {
            selected_indexes: []usize,
            subsumed_indexes: []usize,

            fn prepare(engine: *Self, allocator: std.mem.Allocator, changes: []const HostDirtyStructuralSignal) CollectionError!@This() {
                for (changes) |change| if (change.kind != .when) return error.ResourceLimit;
                return prepareWhenSubset(engine, allocator, changes);
            }

            fn prepareWhenSubset(engine: *Self, allocator: std.mem.Allocator, changes: []const HostDirtyStructuralSignal) CollectionError!@This() {
                const ordered = allocator.alloc(usize, changes.len) catch return error.OutOfMemory;
                errdefer allocator.free(ordered);
                var ordered_len: usize = 0;
                for (changes, 0..) |change, index| if (change.kind == .when) {
                    ordered[ordered_len] = index;
                    ordered_len += 1;
                };

                const Order = struct {
                    engine: *Self,
                    changes: []const HostDirtyStructuralSignal,

                    fn lessThan(order: @This(), lhs_index: usize, rhs_index: usize) bool {
                        const lhs = order.changes[lhs_index];
                        const rhs = order.changes[rhs_index];
                        const lhs_depth = order.engine.scopeDepth(lhs.scope_id.raw());
                        const rhs_depth = order.engine.scopeDepth(rhs.scope_id.raw());
                        if (lhs_depth != rhs_depth) return lhs_depth < rhs_depth;
                        if (lhs.scope_id != rhs.scope_id) return lhs.scope_id.raw() < rhs.scope_id.raw();
                        if (lhs.ordinal != rhs.ordinal) return lhs.ordinal.raw() < rhs.ordinal.raw();
                        return lhs.node_id.raw() < rhs.node_id.raw();
                    }
                };
                std.mem.sort(usize, ordered[0..ordered_len], Order{ .engine = engine, .changes = changes }, Order.lessThan);

                var selected = shared_buffer.List(usize).empty;
                errdefer selected.deinit(allocator);
                var subsumed = shared_buffer.List(usize).empty;
                errdefer subsumed.deinit(allocator);
                selected.ensureTotalCapacity(allocator, changes.len) catch return error.OutOfMemory;
                subsumed.ensureTotalCapacity(allocator, changes.len) catch return error.OutOfMemory;

                var replacement_roots = std.AutoHashMapUnmanaged(u64, void).empty;
                defer replacement_roots.deinit(allocator);
                const change_count: u32 = std.math.cast(u32, ordered_len) orelse return error.ResourceLimit;
                replacement_roots.ensureTotalCapacity(allocator, change_count) catch return error.OutOfMemory;
                var replaces_root = false;

                for (ordered[0..ordered_len]) |index| {
                    const change = changes[index];

                    var covered = replaces_root;
                    var ancestor: ?u64 = change.scope_id.raw();
                    while (!covered and ancestor != null) {
                        const scope_id = ancestor.?;
                        if (replacement_roots.contains(scope_id)) {
                            covered = true;
                            break;
                        }
                        if (scope_id >= engine.scopes.items.len) return error.ResourceLimit;
                        ancestor = if (engine.scopes.items[@intCast(scope_id)].parent_scope_id) |parent| parent.raw() else null;
                    }
                    if (covered) {
                        subsumed.appendAssumeCapacity(index);
                        continue;
                    }

                    selected.appendAssumeCapacity(index);
                    const branch = change.branch orelse return error.InvalidDescriptor;
                    const replacement_root = engine.activeWhenBranchScopeId(change.scope_id, change.ordinal, branch.opposite()) catch |err| return scopeError(err);
                    if (replacement_root) |scope_id| {
                        replacement_roots.putAssumeCapacity(scope_id.raw(), {});
                    } else {
                        replaces_root = true;
                    }
                }

                const selected_indexes = selected.toOwnedSlice(allocator) catch return error.OutOfMemory;
                errdefer allocator.free(selected_indexes);
                const subsumed_indexes = subsumed.toOwnedSlice(allocator) catch return error.OutOfMemory;
                allocator.free(ordered);
                return .{
                    .selected_indexes = selected_indexes,
                    .subsumed_indexes = subsumed_indexes,
                };
            }

            fn deinit(self: *@This(), allocator: std.mem.Allocator) void {
                allocator.free(self.selected_indexes);
                allocator.free(self.subsumed_indexes);
                self.* = undefined;
            }
        };

        /// Applies dirty when structural signals after preparation has fixed semantics and reserved fallible growth.
        pub fn applyDirtyWhenStructuralSignals(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, dirty_source_node_ids: []const u64, dirty_generation: u64, changes: []HostDirtyStructuralSignal) render.Counts {
            if (!builtin.is_test) @compileError("applyDirtyWhenStructuralSignals is a pre-transactional engine path kept only for tests; production goes through prepared transactions");
            for (changes) |change| {
                if (change.kind != .when) @panic("non-when structural change reached when-only test helper");
            }
            return self.applyDirtyStructuralSignalsLocally(ctx, roc_host, dirty_source_node_ids, dirty_generation, changes);
        }

        fn tryApplyPreparedDirtyWhenSet(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, dirty_source_node_ids: []const u64, changes: []HostDirtyStructuralSignal) CollectionError!?render.Counts {
            if (changes.len == 0 or !self.render_cache.hasRoot()) return null;
            const allocator = Ctx.allocator(ctx);
            var normalized = try PreparedDirtyWhenSet.prepare(self, allocator, changes);
            defer normalized.deinit(allocator);
            if (normalized.selected_indexes.len == 0) return null;

            const selections = allocator.alloc(AggregateBranchSelection, normalized.selected_indexes.len) catch return error.OutOfMemory;
            defer allocator.free(selections);
            var built_selection_count: usize = 0;
            defer for (selections[0..built_selection_count]) |selection| selection.elem.decref(roc_host);
            for (normalized.selected_indexes, 0..) |change_index, selection_index| {
                const change = changes[change_index];
                const site = self.activeScopeSiteByNodeId(change.node_id.raw(), .when) orelse return null;
                if (site.scope_id != change.scope_id or site.ordinal != change.ordinal) return null;
                const when_index = self.activeWhenIndexByNodeId(change.node_id.raw()) orelse return null;
                const when_desc = &self.active_stream.whens.items[when_index];
                if (when_desc.condition.record != change.record) return null;
                const branch = change.branch orelse return error.InvalidDescriptor;
                const retired_scope_id = (self.activeWhenBranchScopeId(site.scope_id, site.ordinal, branch.opposite()) catch |err| return scopeError(err)) orelse return null;
                // Reusing a previously active branch requires a different ownership
                // transfer plan that is not staged yet. Declining here makes the
                // caller fail loudly; there is no fallback path.
                if ((self.activeWhenBranchScopeId(site.scope_id, site.ordinal, branch) catch |err| return scopeError(err)) != null) return null;
                const value_cell = change.pending_when_cache orelse return error.InvalidDescriptor;
                const branch_elem = self.buildWhenElem(ctx, roc_host, when_desc.ops, value_cell.value, value_cell.cap);
                selections[selection_index] = .{
                    .node_id = change.node_id,
                    .parent_scope_id = site.scope_id,
                    .site_ordinal = site.ordinal,
                    .parent_elem_id = site.parent_elem_id,
                    .retired_scope_id = retired_scope_id,
                    .render_insert_index = site.render_insert_index,
                    .binder_bindings = site.binder_bindings,
                    .branch = branch,
                    .elem = branch_elem,
                };
                built_selection_count += 1;
            }

            const plan = try AggregateBranchCollection.prepare(self, ctx, roc_host, selections, .{}, dirty_source_node_ids);
            defer plan.deinit();
            var counts = plan.render_splice.?.counts();
            plan.commitAssumeCapacity();
            for (normalized.selected_indexes) |change_index| {
                const change = &changes[change_index];
                const when_index = self.activeWhenIndexByNodeId(change.node_id.raw()) orelse @panic("published dirty when descriptor disappeared");
                change.commitPendingWhenCache(&self.active_stream.whens.items[when_index].cached_value, ctx, roc_host, &self.pending_roc_metrics);
            }
            for (normalized.subsumed_indexes) |change_index| changes[change_index].abortPendingWhenCache(ctx, roc_host, &self.pending_roc_metrics);
            // These callbacks can allocate and trigger user effects, so they run
            // only after the atomic engine/cache/host publication above.
            counts.addAll(self.runActiveOnChangeInitialCommandIndices(ctx, roc_host, plan.publication.?.replacement_on_change_indices));
            counts.addAll(self.runActiveMountCommandIndices(ctx, roc_host, plan.publication.?.replacement_mount_indices));
            return counts;
        }

        /// Returns active interval record by period from the maintained active-runtime indexes.
        pub fn activeIntervalRecordByPeriod(self: *Self, period_ms: u64) ?*HostSignalRecord {
            return effects_runtime.activeIntervalRecordByPeriod(self.active_signal_graph.items, period_ms);
        }

        /// Performs rebuild active events from stream inside the shared engine while preserving transaction and changed-set invariants.
        pub fn rebuildActiveEventsFromStream(self: *Self, ctx: Ctx.Handle, stream: *HostNodeDescriptorStream) void {
            if (!builtin.is_test) @compileError("rebuildActiveEventsFromStream is a pre-transactional engine path kept only for tests; production goes through prepared transactions");
            const allocator = Ctx.allocator(ctx);
            self.clearActiveEvents(ctx) catch @panic("active event table cannot release retained payloads without a Roc host");

            for (stream.events.items) |*desc| {
                if (!desc.owns_handler) @panic("event descriptor payload reducer ownership was already transferred");
                self.active_events.append(allocator, .{
                    .payload_descriptor = desc.payload_descriptor,
                    .handler = desc.handler,
                }) catch @panic("out of memory");
                desc.owns_handler = false;
            }
        }

        /// Performs update effect source cache slot inside the shared engine while preserving transaction and changed-set invariants.
        pub fn updateEffectSourceCacheSlot(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, cache_slot: *HostSignalCacheSlot, value: HostValue, cap: HostValueCapability) bool {
            switch (cache_slot.*) {
                .absent => {
                    debugPhase(ctx, .effect_cache_initialize);
                    cache_slot.replace(ctx, roc_host, &self.pending_roc_metrics, value, cap);
                    return true;
                },
                .present => |*cached| {
                    debugPhase(ctx, .effect_cache_compare);
                    if (cached.valueEquals(ctx, roc_host, value)) {
                        debugPhase(ctx, .effect_cache_drop_equal);
                        cached.dropIncoming(ctx, roc_host, value);
                        self.recordSignalPrune();
                        return false;
                    }
                    debugPhase(ctx, .effect_cache_replace);
                    cached.replaceValue(ctx, roc_host, value);
                    return true;
                },
            }
        }

        /// Performs update effect source cache inside the shared engine while preserving transaction and changed-set invariants.
        pub fn updateEffectSourceCache(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, record: *HostSignalRecord, value: HostValue) bool {
            const source = record.effectSource() orelse @panic("effect source update targeted a non-source signal record");
            return self.updateEffectSourceCacheSlot(ctx, roc_host, source.cachedSlot(), value, source.capability());
        }

        /// Applies dirty signal batch after preparation has fixed semantics and reserved fallible growth.
        pub fn applyDirtySignalBatch(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, dirty_source_node_ids: []const u64, changed_record_ids: []const u64, dirty_generation: u64) render.Counts {
            if (!builtin.is_test) @compileError("applyDirtySignalBatch is a pre-transactional engine path kept only for tests; production goes through prepared transactions");
            const allocator = Ctx.allocator(ctx);
            const stable_changed_record_ids = allocator.dupe(u64, changed_record_ids) catch @panic("out of memory");
            defer allocator.free(stable_changed_record_ids);

            var pending_on_change_commands: shared_buffer.List(HostPendingOnChangeCommand) = .empty;
            defer {
                for (pending_on_change_commands.items) |pending| {
                    pending.cmd.decref(roc_host);
                }
                pending_on_change_commands.deinit(allocator);
            }

            var deferred_storage_effects: shared_buffer.List(HostDeferredStorageEffect) = .empty;
            defer {
                for (deferred_storage_effects.items) |effect| allocator.free(effect.key);
                deferred_storage_effects.deinit(allocator);
            }
            var deferred_location_effect = false;

            debugPhase(ctx, .collect_dirty_sinks);
            var counts = self.collectDirtyRenderSinksAndCommands(
                ctx,
                roc_host,
                dirty_source_node_ids,
                stable_changed_record_ids,
                dirty_generation,
                &pending_on_change_commands,
            );

            debugPhase(ctx, .collect_dirty_structure);
            const dirty_structural_signals = self.collectDirtyStructuralSignals(ctx, roc_host, allocator, dirty_source_node_ids, stable_changed_record_ids, dirty_generation);
            defer {
                for (dirty_structural_signals) |*change| change.abortPendingWhenCache(ctx, roc_host, &self.pending_roc_metrics);
                allocator.free(dirty_structural_signals);
            }
            if (dirty_structural_signals.len != 0) {
                debugPhase(ctx, .apply_dirty_structure);
                counts.addAll(self.applyDirtyStructuralSignalsLocally(ctx, roc_host, dirty_source_node_ids, dirty_generation, dirty_structural_signals));
            }
            debugPhase(ctx, .apply_dirty_commands);
            counts.addAll(self.runPendingOnChangeCommandsDeferringSourceEffects(
                ctx,
                roc_host,
                pending_on_change_commands.items,
                &deferred_location_effect,
                &deferred_storage_effects,
            ));
            debugPhase(ctx, .flush_deferred_effects);
            counts.addAll(self.flushDeferredSourceEffects(ctx, roc_host, deferred_location_effect, deferred_storage_effects.items));
            debugPhase(ctx, .dirty_batch_complete);
            return counts;
        }

        /// Dispatches effect source value through validated routing and dependency-ordered propagation.
        pub fn dispatchEffectSourceValue(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, record: *HostSignalRecord, value: HostValue) render.Counts {
            return self.tryDispatchEffectSourceValue(ctx, roc_host, record, value) catch @panic("failed to prepare atomic effect-source transaction");
        }

        /// Runs the same effect-source transaction as production while exposing
        /// recoverable host-preparation failure to deterministic fault tests.
        pub fn tryDispatchEffectSourceValue(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, record: *HostSignalRecord, value: HostValue) CollectionError!render.Counts {
            const transaction = try PreparedSourceTransaction.prepare(self, ctx, roc_host, record, value) orelse {
                return .{};
            };
            defer transaction.deinit();
            var metrics = self.pending_roc_metrics;
            metrics.bump(.dirty_source_roots, transaction.root_count);
            self.pending_roc_metrics = metrics;
            return transaction.commit();
        }

        /// Prepares and publishes an owned state value atomically after the
        /// reducer callback has returned across the fatal Roc boundary.
        pub fn tryDispatchStateValue(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, node_id: u64, value: HostValue, cap: HostValueCapability) CollectionError!render.Counts {
            const transaction = try PreparedSourceTransaction.prepareState(self, ctx, roc_host, node_id, value, cap) orelse return .{};
            defer transaction.deinit();
            var metrics = self.pending_roc_metrics;
            metrics.bump(.dirty_source_roots, transaction.root_count);
            self.pending_roc_metrics = metrics;
            return transaction.commit();
        }

        /// Consumes a complete set of independently owned state proposals.
        /// Duplicate or inactive destinations are rejected before propagation;
        /// all changed values then share one graph, structure, and observer
        /// transaction. Refusal drops every proposal without changing state.
        pub fn tryDispatchStateWrites(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, writes: []const StateWrite) CollectionError!render.Counts {
            const transaction = try PreparedSourceTransaction.prepareStates(self, ctx, roc_host, writes) orelse return .{};
            defer transaction.deinit();
            self.pending_roc_metrics.bump(.dirty_source_roots, transaction.root_count);
            return transaction.commit();
        }

        /// Publishes an owned state value or terminates on unrecoverable host
        /// preparation failure at the infallible production boundary.
        pub fn dispatchStateValue(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, node_id: u64, value: HostValue, cap: HostValueCapability) render.Counts {
            return self.tryDispatchStateValue(ctx, roc_host, node_id, value, cap) catch |err| switch (err) {
                error.OutOfMemory => @panic("host out of memory while preparing atomic state transaction"),
                error.ResourceLimit => @panic("configured resource limit rejected atomic state transaction"),
                error.InvalidScope => @panic("atomic state transaction named a scope or identity that is unknown, inactive, or already claimed"),
                error.InvalidDescriptor => @panic("atomic state transaction staged a descriptor the committed stream does not hold"),
                error.OverlappingRemoval => @panic("atomic state transaction staged overlapping removals"),
                error.InvalidRenderTopology => @panic("staged render topology conflicted with the committed render tree"),
                error.InvalidSignalGraphAppend => @panic("staged signal graph append did not match the committed graph"),
                error.InvalidSignalGraphRelease => @panic("staged signal graph release did not match the committed graph"),
            };
        }

        const PreparedSourceTransaction = struct {
            const HostRenderPublication = if (@hasDecl(Ctx, "RenderPublication")) Ctx.RenderPublication else void;
            const PreparedStateUpdate = struct {
                state_index: usize,
                state_id: u64,
                ownership: union(enum) {
                    provisional: HostValueCell,
                    committed: HostValueCell,
                },

                fn provisionalCell(self: *@This()) *HostValueCell {
                    return switch (self.ownership) {
                        .provisional => |*cell| cell,
                        .committed => @panic("committed state update has no provisional cell"),
                    };
                }

                fn commit(self: *@This(), engine: *Self) void {
                    const next = switch (self.ownership) {
                        .provisional => |cell| cell,
                        .committed => @panic("prepared state update committed twice"),
                    };
                    const live = &engine.states.items[self.state_index];
                    if (live.state_id != self.state_id) @panic("prepared state update target changed before commit");
                    const payload = live.activePayload();
                    const displaced = payload.cell;
                    payload.cell = next;
                    payload.version += 1;
                    self.ownership = .{ .committed = displaced };
                }

                fn deinit(self: *@This(), ctx: Ctx.Handle, roc_host: *abi.RocHost, metrics: anytype) void {
                    switch (self.ownership) {
                        .provisional => |*cell| cell.deinit(ctx, roc_host, metrics),
                        .committed => |*cell| cell.deinit(ctx, roc_host, metrics),
                    }
                }
            };
            const PreparedStateWrites = struct {
                allocator: std.mem.Allocator,
                entries: shared_buffer.List(PreparedStateUpdate) = .empty,
                node_ids: shared_buffer.List(u64) = .empty,
                external: shared_buffer.List(PreparedExternalState) = .empty,
                by_state_id: std.AutoHashMapUnmanaged(u64, usize) = .empty,

                fn prepare(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, incoming: []const StateWrite) CollectionError!@This() {
                    var consumed: usize = 0;
                    defer for (incoming[consumed..]) |write| callHostValueToUnitWithCapability(ctx, roc_host, write.cap, hv.hostValueCapabilityDrop(write.cap), write.value);
                    const allocator = Ctx.allocator(ctx);
                    var writes = @This(){ .allocator = allocator };
                    errdefer writes.deinit(ctx, roc_host, &engine.pending_roc_metrics);
                    try writes.entries.ensureTotalCapacityPrecise(allocator, incoming.len);
                    try writes.node_ids.ensureTotalCapacityPrecise(allocator, incoming.len);
                    try writes.external.ensureTotalCapacityPrecise(allocator, incoming.len);
                    try writes.by_state_id.ensureTotalCapacity(allocator, std.math.cast(u32, incoming.len) orelse return error.ResourceLimit);
                    // Validate the whole destination set before comparing or
                    // adopting values. Equal proposals do not excuse duplicate
                    // destinations, and no ordering implies last-writer wins.
                    for (incoming) |write| {
                        const entry = writes.by_state_id.getOrPutAssumeCapacity(write.state_id);
                        if (entry.found_existing) return error.InvalidDescriptor;
                        entry.value_ptr.* = std.math.maxInt(usize);
                        const state_index = engine.stateIndexByNodeId(write.state_id) orelse return error.InvalidDescriptor;
                        const cell = engine.states.items[state_index].activePayload().cell;
                        assertHostValueCapabilitiesMatch(cell.cap, write.cap, "prepared state write used the wrong value capability");
                    }
                    for (incoming) |write| {
                        const state_index = engine.stateIndexByNodeId(write.state_id).?;
                        const cell = &engine.states.items[state_index].activePayload().cell;
                        if (cell.valueEqualsIncoming(ctx, roc_host, write.value, write.cap)) {
                            callHostValueToUnitWithCapability(ctx, roc_host, write.cap, hv.hostValueCapabilityDrop(write.cap), write.value);
                            consumed += 1;
                            engine.recordSignalPrune();
                            continue;
                        }
                        writes.by_state_id.getPtr(write.state_id).?.* = writes.entries.items.len;
                        writes.entries.appendAssumeCapacity(.{
                            .state_index = state_index,
                            .state_id = write.state_id,
                            .ownership = .{ .provisional = HostValueCell.initRetained(write.value, write.cap, &engine.pending_roc_metrics) },
                        });
                        consumed += 1;
                        writes.node_ids.appendAssumeCapacity(write.state_id);
                        writes.external.appendAssumeCapacity(write);
                    }
                    return writes;
                }

                fn provisionalCell(self: *@This(), state_id: u64) ?*HostValueCell {
                    const index = self.by_state_id.get(state_id) orelse return null;
                    if (index == std.math.maxInt(usize)) return null;
                    return self.entries.items[index].provisionalCell();
                }

                fn commit(self: *@This(), engine: *Self) void {
                    for (self.entries.items) |*entry| entry.commit(engine);
                }

                fn deinit(self: *@This(), ctx: Ctx.Handle, roc_host: *abi.RocHost, metrics: anytype) void {
                    for (self.entries.items) |*entry| entry.deinit(ctx, roc_host, metrics);
                    self.entries.deinit(self.allocator);
                    self.node_ids.deinit(self.allocator);
                    self.external.deinit(self.allocator);
                    self.by_state_id.deinit(self.allocator);
                    self.* = undefined;
                }
            };
            engine: *Self,
            host_ctx: Ctx.Handle,
            roc_host: *abi.RocHost,
            generation: u64,
            root_count: u64,
            caches: signal_records.PreparedCacheUpdates,
            state_update: ?PreparedStateWrites = null,
            changed_record_ids: []u64,
            render_splice: ?render_cache_mod.PreparedRenderSplice(Ctx) = null,
            structural_changes: []HostDirtyStructuralSignal = &.{},
            structural_downstream: ?*PreparedStructuralDownstream = null,
            composite_structural: ?*PreparedCompositeStructural = null,
            composite_rows: ?*PreparedCompositeRows = null,
            each_rows: ?*PreparedActiveEachRows = null,
            each_replacement: ?*PreparedEachRowReplacementCollection = null,
            each_layout: ?PreparedEachRowRenderLayout = null,
            sparse_each_parent_elem_id: ?ids.ElemId = null,
            position_edits: ?structural_positions.Prepared = null,
            sparse_each_render_roots_moved: usize = 0,
            pending_on_change_commands: shared_buffer.List(HostPendingOnChangeCommand) = .empty,
            fallback_batch: render.TransactionalBatch = .{},
            batch_target: *render.TransactionalBatch,
            publication_phase: PublicationPhase = .unprepared,
            host_publication: ?HostRenderPublication = null,

            fn prepare(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, record: *HostSignalRecord, incoming: HostValue) CollectionError!?*@This() {
                const allocator = Ctx.allocator(ctx);
                const source = record.effectSource() orelse return error.InvalidDescriptor;
                const cap = source.capability();
                var incoming_owned = true;
                errdefer if (incoming_owned) callHostValueToUnitWithCapability(ctx, roc_host, cap, hv.hostValueCapabilityDrop(cap), incoming);
                var owned = signal_records.OwnedSourceUpdates.init(allocator, 1) catch return error.OutOfMemory;
                defer owned.deinit(ctx, roc_host, &engine.pending_roc_metrics);
                owned.adoptAssumeCapacity(record, incoming, cap, &engine.pending_roc_metrics) catch unreachable;
                incoming_owned = false;
                return prepareMany(engine, ctx, roc_host, &owned);
            }

            fn prepareWhenDownstream(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, changes: []const HostDirtyStructuralSignal, state_update: ?*const PreparedStateWrites, cache_overlay: *signal_records.PreparedCacheUpdates) CollectionError!*PreparedStructuralDownstream {
                const allocator = Ctx.allocator(ctx);
                var normalized = try PreparedDirtyWhenSet.prepareWhenSubset(engine, allocator, changes);
                defer normalized.deinit(allocator);
                if (normalized.selected_indexes.len == 0) return error.ResourceLimit;
                const selections = allocator.alloc(AggregateBranchSelection, normalized.selected_indexes.len) catch return error.OutOfMemory;
                defer allocator.free(selections);
                var built_selection_count: usize = 0;
                defer for (selections[0..built_selection_count]) |selection| selection.elem.decref(roc_host);
                for (normalized.selected_indexes, 0..) |change_index, selection_index| {
                    const change = changes[change_index];
                    const site = engine.activeScopeSiteByNodeId(change.node_id.raw(), .when) orelse return error.InvalidDescriptor;
                    if (site.scope_id != change.scope_id or site.ordinal != change.ordinal) return error.InvalidDescriptor;
                    const when_index = engine.activeWhenIndexByNodeId(change.node_id.raw()) orelse return error.InvalidDescriptor;
                    const when_desc = &engine.active_stream.whens.items[when_index];
                    if (when_desc.condition.record != change.record) return error.InvalidDescriptor;
                    const branch = change.branch orelse return error.InvalidDescriptor;
                    const retired_scope_id = (engine.activeWhenBranchScopeId(site.scope_id, site.ordinal, branch.opposite()) catch |err| return scopeError(err)) orelse return error.InvalidScope;
                    if ((engine.activeWhenBranchScopeId(site.scope_id, site.ordinal, branch) catch |err| return scopeError(err)) != null) return error.InvalidScope;
                    const value_cell = switch (cache_overlay.readSlot(@constCast(&when_desc.cached_value)).*) {
                        .absent => return error.InvalidDescriptor,
                        .present => |cell| cell,
                    };
                    const branch_elem = engine.buildWhenElem(ctx, roc_host, when_desc.ops, value_cell.value, value_cell.cap);
                    selections[selection_index] = .{
                        .node_id = change.node_id,
                        .parent_scope_id = site.scope_id,
                        .site_ordinal = site.ordinal,
                        .parent_elem_id = site.parent_elem_id,
                        .retired_scope_id = retired_scope_id,
                        .render_insert_index = site.render_insert_index,
                        .binder_bindings = site.binder_bindings,
                        .branch = branch,
                        .elem = branch_elem,
                    };
                    built_selection_count += 1;
                }
                return AggregateBranchCollection.prepareWithState(engine, ctx, roc_host, selections, .{}, &.{}, externalStateOf(state_update), cache_overlay);
            }

            /// Borrows the complete proposed write set for structural
            /// collection; empty for transactions that publish no state.
            fn externalStateOf(state_update: ?*const PreparedStateWrites) []const PreparedExternalState {
                const update = state_update orelse return &.{};
                return update.external.items;
            }

            fn prepareMany(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, owned: *signal_records.OwnedSourceUpdates) CollectionError!?*@This() {
                return prepareRoots(engine, ctx, roc_host, owned, null);
            }

            /// Appends the ordinary graph wave produced by changed surviving
            /// rows to this transaction's existing cache overlay. Reconciliation
            /// is the only place that knows which keyed rows survived and
            /// changed; everything after that point follows normal rank order,
            /// equality pruning, render routing, and on-change routing.
            fn appendChangedRowPropagation(self: *@This(), rows: *PreparedActiveEachRows) CollectionError![]HostDirtyStructuralSignal {
                const allocator = Ctx.allocator(self.host_ctx);
                var handles = shared_buffer.List(row_handles.RowHandleId).empty;
                defer handles.deinit(allocator);
                var slots = shared_buffer.List(u64).empty;
                defer slots.deinit(allocator);
                if (rows.inputs.delta != null and !rows.inputs.snapshot.complete) {
                    const candidates = rows.candidateRows();
                    try handles.ensureTotalCapacity(allocator, candidates.changedUpperBound());
                    try slots.ensureTotalCapacity(allocator, candidates.changedUpperBound());
                    var changed = candidates.iterateChanged();
                    while (try changed.next()) |candidate| {
                        // Rows without `Row.signal` have no graph root to schedule.
                        if (self.engine.activeRowSourceRecord(candidate.row_handle) == null) continue;
                        handles.appendAssumeCapacity(candidate.row_handle);
                        slots.appendAssumeCapacity(candidate.item_slot);
                    }
                } else {
                    try handles.ensureTotalCapacity(allocator, rows.rows.next_scope_ids.len);
                    try slots.ensureTotalCapacity(allocator, rows.rows.next_scope_ids.len);
                    for (rows.rows.next_scope_ids, rows.rows.scope_created, rows.rows.row_items_changed, 0..) |scope_id, created, changed, index| {
                        if (created or !changed) continue;
                        const handle = scope_runtime.eachRowHandle(self.engine.scopes.items, scope_id);
                        // Rows without `Row.signal` have no graph root to schedule.
                        if (self.engine.activeRowSourceRecord(handle) == null) continue;
                        handles.appendAssumeCapacity(handle);
                        slots.appendAssumeCapacity(rows.inputs.slot(index) orelse return error.InvalidDescriptor);
                    }
                }
                if (handles.items.len == 0) return allocator.alloc(HostDirtyStructuralSignal, 0) catch return error.OutOfMemory;

                var owned = try self.engine.prepareChangedRowSourceUpdates(self.host_ctx, self.roc_host, rows.inputs.generation, handles.items, slots.items);
                defer owned.deinit(self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics);
                var root_ids = shared_buffer.List(u64).empty;
                defer root_ids.deinit(allocator);
                try root_ids.ensureTotalCapacityPrecise(allocator, owned.entries.items.len);
                for (owned.entries.items) |entry| root_ids.appendAssumeCapacity(self.engine.requireActiveSignalRecordId(entry.record));
                try self.engine.scratch.dirty_active_records.reserveForGraph(HostSignalRecord, allocator, self.engine.active_signal_graph.items);
                const dirty_ids = self.engine.scratchDirtyActiveSignalRecordIdsForRoots(self.host_ctx, root_ids.items);
                // The first wave may have read an unchanged row source while
                // evaluating a derived record that also depends on the state
                // root which changed the collection. Reconciliation is the
                // first point where the row source can be promoted. Forget the
                // complete downstream wave before staging it so every consumer
                // observes the candidate generation rather than an interim
                // memoized value.
                for (dirty_ids) |record_id| {
                    const record = self.engine.active_signal_graph.items[@intCast(record_id)].record;
                    self.caches.forgetEvaluation(record, self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics);
                    const route_index: usize = @intCast(record_id);
                    if (route_index < self.engine.active_text_signal_routes.items.len) for (self.engine.active_text_signal_routes.items[route_index].slice()) |route| switch (route.kind) {
                        .text_node => self.caches.forgetCacheSlot(&self.engine.active_stream.signal_text_nodes.items[route.index].cached_value, self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics),
                        .text_attr => self.caches.forgetCacheSlot(&self.engine.active_stream.signal_text_attrs.items[route.index].cached_value, self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics),
                        .custom_text_attr => self.caches.forgetCacheSlot(&self.engine.active_stream.signal_custom_text_attrs.items[route.index].cached_value, self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics),
                        .custom_text_optional_attr => self.caches.forgetCacheSlot(&self.engine.active_stream.signal_optional_custom_text_attrs.items[route.index].cached_value, self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics),
                    };
                    if (route_index < self.engine.active_bool_signal_routes.items.len) for (self.engine.active_bool_signal_routes.items[route_index].slice()) |route| switch (route.kind) {
                        .bool_attr => self.caches.forgetCacheSlot(&self.engine.active_stream.signal_bool_attrs.items[route.index].cached_value, self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics),
                        .custom_bool_attr => self.caches.forgetCacheSlot(&self.engine.active_stream.signal_custom_bool_attrs.items[route.index].cached_value, self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics),
                    };
                    if (route_index < self.engine.active_structural_signal_routes.items.len) for (self.engine.active_structural_signal_routes.items[route_index].slice()) |route| switch (route.kind) {
                        .when => self.caches.forgetCacheSlot(&self.engine.active_stream.whens.items[route.index].cached_value, self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics),
                        .each => self.caches.forgetCacheSlot(&self.engine.active_stream.eaches.items[route.index].cached_value, self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics),
                    };
                    if (route_index < self.engine.active_change_signal_routes.items.len) for (self.engine.active_change_signal_routes.items[route_index].slice()) |route| self.caches.forgetCacheSlot(&self.engine.active_stream.on_changes.items[route.index].cached_value, self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics);
                }
                for (owned.entries.items) |entry| self.caches.forgetEvaluation(entry.record, self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics);
                root_ids.clearRetainingCapacity();
                for (owned.entries.items, 0..) |*entry, index| {
                    const cell = &entry.cell.?;
                    const source = entry.record.effectSource() orelse return error.InvalidDescriptor;
                    const live_slot = source.cachedSlot();
                    if (live_slot.* == .present and live_slot.present.valueEqualsIncoming(self.host_ctx, self.roc_host, cell.value, cell.cap)) {
                        self.engine.recordSignalPrune();
                        continue;
                    }
                    const transferred = owned.take(index).cell.?;
                    self.caches.stageOwnedAssumeCapacity(live_slot, transferred);
                    self.caches.rememberResultAssumeCapacity(signal_records.EvaluationKey.fromRecord(entry.record), self.generation, true);
                    root_ids.appendAssumeCapacity(self.engine.requireActiveSignalRecordId(entry.record));
                }
                if (root_ids.items.len == 0) return allocator.alloc(HostDirtyStructuralSignal, 0) catch return error.OutOfMemory;
                // Row sources are internal roots discovered while reconciling
                // one already-counted app/host source transaction. Keep
                // `dirty_source_roots` describing only those externally
                // initiated roots, as documented by RuntimeMetrics.
                const changed_dirty_ids = self.engine.scratchDirtyActiveSignalRecordIdsForRoots(self.host_ctx, root_ids.items);
                const wave_changed = try self.engine.prepareChangedActiveSignalRecordIds(self.host_ctx, self.roc_host, &self.caches, changed_dirty_ids, &.{}, self.generation);
                defer allocator.free(wave_changed);
                if (wave_changed.len == 0) return allocator.alloc(HostDirtyStructuralSignal, 0) catch return error.OutOfMemory;

                var wave_splice = try self.engine.prepareNonStructuralRenderSplice(self.host_ctx, self.roc_host, &self.caches, wave_changed, &.{}, self.generation);
                defer wave_splice.deinit();
                const splice = &(self.render_splice orelse return error.ResourceLimit);
                splice.adoptScalarUpdates(&wave_splice) catch |err| return renderSpliceError(err);

                const wave_structural = try self.engine.collectPreparedDirtyStructuralSignals(self.host_ctx, self.roc_host, allocator, &self.caches, wave_changed, &.{}, self.generation);
                try self.engine.prepareOnChangeCommands(self.host_ctx, self.roc_host, &self.caches, wave_changed, &.{}, self.generation, &self.pending_on_change_commands);
                return wave_structural;
            }

            /// Adopts the render-order portion of a matching Rows delta when
            /// every row scope and descriptor survives. Stable row spans make
            /// each move local; item-only updates produce an empty journal.
            /// Deltas that create or retire scopes deliberately return false
            /// so their descriptor ownership still uses the snapshot-capable
            /// structural path until its sparse splice is prepared separately.
            fn tryAdoptSparseSurvivingRows(self: *@This(), site: HostNodeScopeSiteDesc, rows: *PreparedActiveEachRows) CollectionError!bool {
                if (!rows.direct_delta) return false;
                const transition = if (rows.inputs.rows_transition) |*value| value else return error.InvalidDescriptor;
                if (transition.createdRows().len != 0 or transition.removedRows().len != 0) return false;
                for (transition.orderEdits()) |edit| switch (edit) {
                    .move => {},
                    .insert, .remove, .clear => return false,
                };

                var roots_moved: usize = 0;
                var journal = render_cache_mod.PreparedSparseChildren.init(
                    Ctx,
                    Ctx.allocator(self.host_ctx),
                    &self.engine.render_cache,
                    site.parent_elem_id,
                    0,
                    0,
                ) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.ResourceLimit => return error.ResourceLimit,
                    error.MissingParent => return error.InvalidRenderTopology,
                };
                var journal_owned = true;
                defer if (journal_owned) journal.deinit();

                var positions = (if (self.engine.positions) |*value| value else return error.InvalidRenderTopology).prepare();
                var positions_owned = true;
                defer if (positions_owned) positions.deinit();
                const end_marker = structural_positions.PositionId.marker(site.node_id, .each_end);
                for (transition.orderEdits()) |edit| switch (edit) {
                    .move => |move| {
                        const span = positions.rootsInRange(site.parent_elem_id, structural_positions.PositionId.rowStart(ids.ScopeId.fromRaw(move.first_scope_id)), structural_positions.PositionId.rowEnd(ids.ScopeId.fromRaw(move.last_scope_id))) catch |err| return positionError(err);
                        journal.reserveAdditional(span.count + 4, span.count) catch |err| return positionError(err);
                        const lexical_before = if (move.before_scope_id == 0) end_marker else structural_positions.PositionId.rowStart(ids.ScopeId.fromRaw(move.before_scope_id));
                        const before = positions.anchor(site.parent_elem_id, lexical_before) catch |err| return positionError(err);
                        positions.moveRange(site.parent_elem_id, structural_positions.PositionId.rowStart(ids.ScopeId.fromRaw(move.first_scope_id)), structural_positions.PositionId.rowEnd(ids.ScopeId.fromRaw(move.last_scope_id)), lexical_before) catch |err| return positionError(err);
                        if (span.count == 0) continue;
                        roots_moved = std.math.add(usize, roots_moved, span.count) catch return error.ResourceLimit;
                        journal.moveRangeBefore(
                            Ctx,
                            &self.engine.render_cache,
                            span.first.?,
                            span.last.?,
                            span.count,
                            before,
                        ) catch |err| switch (err) {
                            error.ResourceLimit => return error.ResourceLimit,
                            error.InvalidAnchor, error.InvalidRange, error.MissingNode => return error.InvalidRenderTopology,
                        };
                    },
                    else => unreachable,
                };
                positions.preflight() catch |err| return positionError(err);
                const splice = &(self.render_splice orelse return error.ResourceLimit);
                splice.adoptSparseChildren(&journal) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.ConflictingParent, error.MissingNode => return error.InvalidRenderTopology,
                };
                journal_owned = false;
                self.position_edits = positions;
                positions_owned = false;
                self.sparse_each_parent_elem_id = site.parent_elem_id;
                self.sparse_each_render_roots_moved = roots_moved;
                return true;
            }

            /// Preflights the ordinary scalar/sparse render plan after all
            /// graph waves have joined it. Nothing is published on failure.
            fn prepareDirectRenderPublication(self: *@This(), allocator: std.mem.Allocator) CollectionError!void {
                self.batch_target = if (comptime @hasDecl(Ctx, "renderCommandBatch")) Ctx.renderCommandBatch(self.host_ctx) else &self.fallback_batch;
                errdefer self.fallback_batch.deinit(allocator);
                self.render_splice.?.finishSparseParents() catch |err| return switch (err) {
                    error.InvalidRange => error.InvalidRenderTopology,
                    else => |other| renderSpliceError(other),
                };
                self.render_splice.?.preflight(self.batch_target, allocator) catch |err| switch (err) {
                    error.OutOfMemory => return error.OutOfMemory,
                    error.ResourceLimit => return error.ResourceLimit,
                };
                self.publication_phase.markPreflighted();
                errdefer self.batch_target.abort();
                if (comptime @hasDecl(Ctx, "prepareRenderPublication")) {
                    self.host_publication = Ctx.prepareRenderPublication(self.host_ctx, &self.render_splice.?) catch |err| switch (err) {
                        error.OutOfMemory => return error.OutOfMemory,
                        error.ResourceLimit => return error.ResourceLimit,
                        error.InvalidRenderTopology => return error.InvalidRenderTopology,
                    };
                }
            }

            /// Mirrors a prepared sparse child move into the descriptor
            /// stream's durable sibling links. The Rows transition has already
            /// validated range identity and the operation allocates nothing.
            fn applySparseEachDescriptorOrder(self: *@This(), _: *const PreparedActiveEachRows) void {
                self.render_splice.?.applySparseChildrenToIndexedStream(HostNodeDescriptorStream, Ctx.allocator(self.host_ctx), &self.engine.active_stream);
                self.position_edits.?.commit();
            }

            fn prepareState(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, node_id: u64, incoming: HostValue, cap: HostValueCapability) CollectionError!?*@This() {
                return prepareStates(engine, ctx, roc_host, &.{.{ .state_id = node_id, .value = incoming, .cap = cap }});
            }

            fn prepareStates(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, incoming: []const StateWrite) CollectionError!?*@This() {
                var state_update = try PreparedStateWrites.prepare(engine, ctx, roc_host, incoming);
                if (state_update.entries.items.len == 0) {
                    state_update.deinit(ctx, roc_host, &engine.pending_roc_metrics);
                    return null;
                }
                errdefer state_update.deinit(ctx, roc_host, &engine.pending_roc_metrics);
                var owned = signal_records.OwnedSourceUpdates.init(Ctx.allocator(ctx), 0) catch return error.OutOfMemory;
                defer owned.deinit(ctx, roc_host, &engine.pending_roc_metrics);
                const plan = try prepareRoots(engine, ctx, roc_host, &owned, &state_update);
                if (plan != null) state_update = undefined;
                return plan;
            }

            fn prepareRoots(engine: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, owned: *signal_records.OwnedSourceUpdates, state_update: ?*PreparedStateWrites) CollectionError!?*@This() {
                const allocator = Ctx.allocator(ctx);
                if (owned.entries.items.len == 0 and state_update == null) return null;
                const generation = std.math.add(u64, engine.dirty_signal_generation, 1) catch return error.ResourceLimit;
                var expected = engine.active_signal_graph.items.len;
                for (engine.active_text_signal_routes.items) |routes| expected = std.math.add(usize, expected, routes.len()) catch return error.ResourceLimit;
                for (engine.active_bool_signal_routes.items) |routes| expected = std.math.add(usize, expected, routes.len()) catch return error.ResourceLimit;
                for (engine.active_structural_signal_routes.items) |routes| expected = std.math.add(usize, expected, routes.len()) catch return error.ResourceLimit;
                for (engine.active_change_signal_routes.items) |routes| expected = std.math.add(usize, expected, routes.len()) catch return error.ResourceLimit;
                const plan = allocator.create(@This()) catch return error.OutOfMemory;
                errdefer allocator.destroy(plan);
                var caches = signal_records.PreparedCacheUpdates.init(allocator, expected) catch return error.OutOfMemory;
                var caches_owned = true;
                errdefer if (caches_owned) caches.deinit(ctx, roc_host, &engine.pending_roc_metrics);
                var root_record_ids: shared_buffer.List(u64) = .empty;
                defer root_record_ids.deinit(allocator);
                try root_record_ids.ensureTotalCapacityPrecise(allocator, owned.entries.items.len);
                for (owned.entries.items, 0..) |*entry, index| {
                    const cell = &entry.cell.?;
                    const source = entry.record.effectSource() orelse return error.InvalidDescriptor;
                    assertHostValueCapabilitiesMatch(cell.cap, source.capability(), "browser source update used the wrong value capability");
                    const live_slot = source.cachedSlot();
                    if (live_slot.* == .present and live_slot.present.valueEqualsIncoming(ctx, roc_host, cell.value, cell.cap)) {
                        engine.recordSignalPrune();
                        continue;
                    }
                    const transferred = owned.take(index).cell.?;
                    caches.stageOwnedAssumeCapacity(live_slot, transferred);
                    caches.rememberResultAssumeCapacity(signal_records.EvaluationKey.fromRecord(entry.record), generation, true);
                    root_record_ids.appendAssumeCapacity(engine.requireActiveSignalRecordId(entry.record));
                }
                if (root_record_ids.items.len == 0 and state_update == null) {
                    caches.deinit(ctx, roc_host, &engine.pending_roc_metrics);
                    allocator.destroy(plan);
                    return null;
                }
                try engine.scratch.dirty_active_records.reserveForGraph(HostSignalRecord, allocator, engine.active_signal_graph.items);
                const state_node_ids: []const u64 = if (state_update) |update| update.node_ids.items else &.{};
                const dirty_ids = if (state_update != null)
                    engine.scratchDirtyActiveSignalRecordIdsForSources(ctx, state_node_ids)
                else
                    engine.scratchDirtyActiveSignalRecordIdsForRoots(ctx, root_record_ids.items);
                if (state_update) |update| {
                    for (dirty_ids) |record_id| {
                        const record = engine.active_signal_graph.items[@intCast(record_id)].record;
                        switch (record.payload) {
                            .ref => |ref_node_id| if (update.provisionalCell(ref_node_id)) |cell| {
                                const evaluation_key = signal_records.EvaluationKey.fromRecord(record);
                                caches.bindProvisionalValueAssumeCapacity(evaluation_key, cell);
                                caches.rememberResultAssumeCapacity(evaluation_key, generation, true);
                            },
                            else => {},
                        }
                    }
                }
                const changed = try engine.prepareChangedActiveSignalRecordIds(ctx, roc_host, &caches, dirty_ids, state_node_ids, generation);
                errdefer allocator.free(changed);
                var splice = try engine.prepareNonStructuralRenderSplice(ctx, roc_host, &caches, changed, state_node_ids, generation);
                var splice_owned = true;
                errdefer if (splice_owned) splice.deinit();
                var structural_changes = try engine.collectPreparedDirtyStructuralSignals(ctx, roc_host, allocator, &caches, changed, state_node_ids, generation);
                errdefer allocator.free(structural_changes);
                plan.* = .{
                    .engine = engine,
                    .host_ctx = ctx,
                    .roc_host = roc_host,
                    .generation = generation,
                    .root_count = if (state_update) |update| @intCast(update.entries.items.len) else @intCast(root_record_ids.items.len),
                    .caches = caches,
                    .state_update = null,
                    .changed_record_ids = changed,
                    .render_splice = splice,
                    .structural_changes = structural_changes,
                    .batch_target = undefined,
                };
                caches_owned = false;
                splice_owned = false;
                errdefer plan.caches.deinit(ctx, roc_host, &engine.pending_roc_metrics);
                errdefer if (plan.render_splice) |*owned_splice| owned_splice.deinit();
                try engine.prepareOnChangeCommands(ctx, roc_host, &plan.caches, changed, state_node_ids, generation, &plan.pending_on_change_commands);
                errdefer {
                    for (plan.pending_on_change_commands.items) |pending| pending.cmd.decref(roc_host);
                    plan.pending_on_change_commands.deinit(allocator);
                }
                // Each reconciliation is the first point at which changed
                // surviving row handles are known. Run a preparation-only
                // reconciliation pass for every dirty each (including nested
                // eaches discovered by earlier row waves), append those row
                // roots to this same transaction, and only then choose the
                // final structural planner from the complete change set.
                // A lone each whose changed rows reveal no further structural
                // roots can reuse this prepared reconciliation as its final
                // plan. Discarding it and preparing the same site again would
                // repeat every key hash, key comparison, and item comparison
                // despite the candidate generation being unchanged.
                var reusable_single_each_rows: ?*PreparedActiveEachRows = null;
                defer if (reusable_single_each_rows) |rows| rows.deinit();
                var structural_index: usize = 0;
                while (structural_index < structural_changes.len) : (structural_index += 1) {
                    const change = structural_changes[structural_index];
                    if (change.kind != .each) continue;
                    const site = engine.activeScopeSiteByNodeId(change.node_id.raw(), .each) orelse return error.InvalidDescriptor;
                    const each_index = engine.activeEachIndexByNodeId(change.node_id.raw()) orelse return error.InvalidDescriptor;
                    const each_desc = &engine.active_stream.eaches.items[each_index];
                    const row_structural = blk: {
                        const provisional_rows = try PreparedActiveEachRows.prepareWithOverlay(engine, ctx, roc_host, site, each_desc, allocator, &plan.caches);
                        errdefer provisional_rows.deinit();
                        const discovered = try plan.appendChangedRowPropagation(provisional_rows);
                        if (discovered.len == 0 and structural_changes.len == 1 and structural_index == 0) {
                            reusable_single_each_rows = provisional_rows;
                        } else {
                            provisional_rows.deinit();
                        }
                        break :blk discovered;
                    };
                    defer allocator.free(row_structural);
                    if (row_structural.len == 0) {
                        continue;
                    }
                    const merged = allocator.alloc(HostDirtyStructuralSignal, structural_changes.len + row_structural.len) catch return error.OutOfMemory;
                    @memcpy(merged[0..structural_changes.len], structural_changes);
                    @memcpy(merged[structural_changes.len..], row_structural);
                    allocator.free(structural_changes);
                    structural_changes = merged;
                    plan.structural_changes = merged;
                }
                if (structural_changes.len != 0) {
                    var each_count: usize = 0;
                    var when_count: usize = 0;
                    for (structural_changes) |change| switch (change.kind) {
                        .when => when_count += 1,
                        .each => each_count += 1,
                    };
                    const external_state = externalStateOf(state_update);
                    if (each_count != 0 and when_count != 0) {
                        var all_eaches_subsumed = false;
                        plan.composite_structural = PreparedCompositeStructural.prepareWithSubsumedFlag(engine, ctx, roc_host, structural_changes, &plan.caches, .{}, state_node_ids, external_state, &all_eaches_subsumed) catch |err| switch (err) {
                            error.OutOfMemory => return error.OutOfMemory,
                            error.ResourceLimit => if (all_eaches_subsumed) null else return error.ResourceLimit,
                            else => |other| return other,
                        };
                        if (all_eaches_subsumed) {
                            plan.structural_downstream = try prepareWhenDownstream(engine, ctx, roc_host, structural_changes, state_update, &plan.caches);
                            errdefer plan.structural_downstream.?.deinit();
                            try plan.structural_downstream.?.adoptScalarRenderSplice(&plan.render_splice.?);
                            plan.render_splice.?.deinit();
                            plan.render_splice = null;
                            if (state_update) |update| {
                                plan.caches.clearProvisionalValues();
                                plan.state_update = update.*;
                            }
                            return plan;
                        }
                        errdefer plan.composite_structural.?.deinit();
                        const downstream = plan.composite_structural.?.downstream;
                        try downstream.adoptScalarRenderSplice(&plan.render_splice.?);
                        plan.render_splice.?.deinit();
                        plan.render_splice = null;
                        if (state_update) |update| {
                            plan.caches.clearProvisionalValues();
                            plan.state_update = update.*;
                        }
                        return plan;
                    }
                    if (each_count > 1) {
                        plan.composite_rows = try PreparedCompositeRows.prepare(engine, ctx, roc_host, structural_changes, &plan.caches, external_state);
                        errdefer plan.composite_rows.?.deinit();
                        const downstream = plan.composite_rows.?.downstream.?;
                        try downstream.adoptScalarRenderSplice(&plan.render_splice.?);
                        plan.render_splice.?.deinit();
                        plan.render_splice = null;
                        if (state_update) |update| {
                            plan.caches.clearProvisionalValues();
                            plan.state_update = update.*;
                        }
                        return plan;
                    }
                    if (each_count == 1) {
                        const change = structural_changes[0];
                        const site = engine.activeScopeSiteByNodeId(change.node_id.raw(), .each) orelse return error.InvalidDescriptor;
                        const each_index = engine.activeEachIndexByNodeId(change.node_id.raw()) orelse return error.InvalidDescriptor;
                        const each_desc = &engine.active_stream.eaches.items[each_index];
                        if (each_desc.items.record != change.record) return error.InvalidDescriptor;
                        plan.each_rows = if (reusable_single_each_rows) |rows| blk: {
                            reusable_single_each_rows = null;
                            break :blk rows;
                        } else try PreparedActiveEachRows.prepareWithOverlay(engine, ctx, roc_host, site, each_desc, allocator, &plan.caches);
                        errdefer plan.each_rows.?.deinit();
                        if (try plan.tryAdoptSparseSurvivingRows(site, plan.each_rows.?)) {
                            try plan.prepareDirectRenderPublication(allocator);
                            if (state_update) |update| {
                                plan.caches.clearProvisionalValues();
                                plan.state_update = update.*;
                            }
                            return plan;
                        }
                        plan.each_replacement = try PreparedEachRowReplacementCollection.prepare(engine, ctx, roc_host, site, each_desc.*, plan.each_rows.?, .{}, &.{}, &plan.caches, external_state);
                        errdefer plan.each_replacement.?.deinit();
                        if (engine.positions != null) {
                            plan.structural_downstream = try PreparedStructuralDownstream.prepareSparseExternalEach(engine, ctx, roc_host, site, plan.each_rows.?, plan.each_replacement.?, &plan.caches);
                        } else {
                            plan.each_layout = try PreparedEachRowRenderLayout.prepare(engine, allocator, site, &plan.each_rows.?.rows, plan.each_replacement.?.replacement_rows, &plan.each_replacement.?.replacement.collection);
                            errdefer plan.each_layout.?.deinit();
                            plan.structural_downstream = try PreparedStructuralDownstream.prepareExternalEach(engine, ctx, roc_host, &plan.each_rows.?.rows, &plan.each_rows.?.inputs, plan.each_replacement.?, &plan.each_layout.?, &plan.caches);
                        }
                    } else {
                        plan.structural_downstream = try prepareWhenDownstream(engine, ctx, roc_host, structural_changes, state_update, &plan.caches);
                    }
                    // The each-row errdefers above end with their block; the
                    // adoption below can still fail, and the plan is only
                    // handed to `deinit` once it is returned.
                    errdefer if (plan.each_rows) |rows| rows.deinit();
                    errdefer if (plan.each_replacement) |replacement| replacement.deinit();
                    errdefer if (plan.each_layout) |*layout| layout.deinit();
                    errdefer plan.structural_downstream.?.deinit();
                    try plan.structural_downstream.?.adoptScalarRenderSplice(&plan.render_splice.?);
                    plan.render_splice.?.deinit();
                    plan.render_splice = null;
                    if (state_update) |update| {
                        plan.caches.clearProvisionalValues();
                        plan.state_update = update.*;
                    }
                    return plan;
                }
                try plan.prepareDirectRenderPublication(allocator);
                if (state_update) |update| {
                    plan.caches.clearProvisionalValues();
                    plan.state_update = update.*;
                }
                return plan;
            }

            fn commit(self: *@This()) render.Counts {
                return self.commitWithPublication({}, struct {
                    fn publish(_: void) void {}
                }.publish);
            }

            // The joined publication is already fully prepared. Run it after
            // structural retirement
            // and before observers or mount commands can start another turn.
            fn commitWithPublication(self: *@This(), publication: anytype, comptime publish: fn (@TypeOf(publication)) void) render.Counts {
                const allocator = Ctx.allocator(self.host_ctx);
                if (self.composite_structural) |composite| {
                    const downstream = composite.downstream;
                    var total = if (downstream.render_splice) |*splice| splice.counts() else render.Counts{};
                    composite.commitRowsTransitionRemovalsEarly();
                    downstream.commitAssumeCapacityWithEarlyAndLate(self, commitSourceCaches, composite, PreparedCompositeStructural.commitLate);
                    publish(publication);
                    total.addAll(self.engine.runActiveOnChangeInitialCommandIndices(self.host_ctx, self.roc_host, downstream.publication.?.replacement_on_change_indices));
                    total.addAll(self.engine.runActiveMountCommandIndices(self.host_ctx, self.roc_host, downstream.publication.?.replacement_mount_indices));
                    total.addAll(self.runPostCommitCommands());
                    if (comptime enable_runtime_metrics) self.engine.render_metrics.addCommandCounts(total);
                    return total;
                }
                if (self.composite_rows) |composite| {
                    const downstream = composite.downstream.?;
                    const counts = downstream.render_splice.?.counts();
                    composite.commitRowsTransitionRemovalsEarly();
                    downstream.commitAssumeCapacityWithEarlyAndLate(self, commitSourceCaches, composite, struct {
                        fn apply(rows: *PreparedCompositeRows) void {
                            rows.commit();
                        }
                    }.apply);
                    var total = counts;
                    publish(publication);
                    total.addAll(self.engine.runActiveOnChangeInitialCommandIndices(self.host_ctx, self.roc_host, downstream.publication.?.replacement_on_change_indices));
                    total.addAll(self.engine.runActiveMountCommandIndices(self.host_ctx, self.roc_host, downstream.publication.?.replacement_mount_indices));
                    total.addAll(self.runPostCommitCommands());
                    if (comptime enable_runtime_metrics) self.engine.render_metrics.addCommandCounts(total);
                    return total;
                }
                if (self.structural_downstream) |downstream| {
                    const counts = downstream.render_splice.?.counts();
                    if (self.each_rows) |rows| {
                        const Late = struct {
                            rows: *PreparedActiveEachRows,
                            diff: ?HostKeyedRowDiffResult = null,
                            fn apply(state: *@This()) void {
                                state.diff = state.rows.commit();
                            }
                        };
                        rows.commitRowsTransitionRemovalsEarly();
                        var late = Late{ .rows = rows };
                        downstream.commitAssumeCapacityWithEarlyAndLate(self, commitSourceCaches, &late, Late.apply);
                        var diff = late.diff orelse @panic("prepared source each row commit was skipped");
                        diff.deinit(allocator);
                    } else {
                        downstream.commitAssumeCapacityWithEarlyAndLate(self, commitSourceCaches, {}, struct {
                            fn apply(_: void) void {}
                        }.apply);
                    }
                    var total = counts;
                    publish(publication);
                    total.addAll(self.engine.runActiveOnChangeInitialCommandIndices(self.host_ctx, self.roc_host, downstream.publication.?.replacement_on_change_indices));
                    total.addAll(self.engine.runActiveMountCommandIndices(self.host_ctx, self.roc_host, downstream.publication.?.replacement_mount_indices));
                    total.addAll(self.runPostCommitCommands());
                    if (comptime enable_runtime_metrics) self.engine.render_metrics.addCommandCounts(total);
                    return total;
                }
                if (self.each_rows) |rows| {
                    self.render_splice.?.stageAssumeCapacity(self.batch_target, allocator) catch @panic("prepared sparse Rows batch violated preflight");
                    commitSourceCaches(self);
                    self.render_splice.?.apply(&self.engine.render_cache);
                    self.applySparseEachDescriptorOrder(rows);
                    var diff = rows.commit();
                    diff.deinit(allocator);
                    self.engine.pending_roc_metrics.bump(.rows_render_roots_moved, @intCast(self.sparse_each_render_roots_moved));
                    self.batch_target.commit();
                    self.publication_phase.markBatchPublished();
                    if (comptime @hasDecl(Ctx, "publishRenderPublication")) {
                        Ctx.publishRenderPublication(self.host_ctx, &self.host_publication.?);
                        self.publication_phase.markHostPublished();
                    }
                    var counts = self.render_splice.?.counts();
                    publish(publication);
                    counts.addAll(self.runPostCommitCommands());
                    if (comptime enable_runtime_metrics) self.engine.render_metrics.addCommandCounts(counts);
                    return counts;
                }
                self.render_splice.?.stageAssumeCapacity(self.batch_target, allocator) catch @panic("prepared source batch violated preflight");
                commitSourceCaches(self);
                self.render_splice.?.apply(&self.engine.render_cache);
                self.batch_target.commit();
                self.publication_phase.markBatchPublished();
                if (comptime @hasDecl(Ctx, "publishRenderPublication")) {
                    Ctx.publishRenderPublication(self.host_ctx, &self.host_publication.?);
                    self.publication_phase.markHostPublished();
                }
                var counts = self.render_splice.?.counts();
                publish(publication);
                counts.addAll(self.runPostCommitCommands());
                if (comptime enable_runtime_metrics) self.engine.render_metrics.addCommandCounts(counts);
                return counts;
            }

            fn commitSourceCaches(self: *@This()) void {
                if (self.state_update) |*update| update.commit(self.engine);
                self.engine.commitPreparedDirtySignalCaches(&self.caches);
                self.engine.dirty_signal_generation = self.generation;
                self.engine.identity_reuse_barrier = self.generation;
                self.engine.recordDispatch();
            }

            fn runPostCommitCommands(self: *@This()) render.Counts {
                const allocator = Ctx.allocator(self.host_ctx);
                var deferred_location = false;
                var deferred_storage: shared_buffer.List(HostDeferredStorageEffect) = .empty;
                defer {
                    for (deferred_storage.items) |effect| allocator.free(effect.key);
                    deferred_storage.deinit(allocator);
                }
                var counts = self.engine.runPendingOnChangeCommandsDeferringSourceEffects(self.host_ctx, self.roc_host, self.pending_on_change_commands.items, &deferred_location, &deferred_storage);
                counts.addAll(self.engine.flushDeferredSourceEffects(self.host_ctx, self.roc_host, deferred_location, deferred_storage.items));
                return counts;
            }

            fn deinit(self: *@This()) void {
                const allocator = Ctx.allocator(self.host_ctx);
                if (self.position_edits) |*positions| positions.deinit();
                if (self.publication_phase.needsAbort()) self.batch_target.abort();
                if (comptime @hasDecl(Ctx, "RenderPublication")) if (self.host_publication) |*publication| publication.deinit();
                self.caches.deinit(self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics);
                if (self.state_update) |*update| update.deinit(self.host_ctx, self.roc_host, &self.engine.pending_roc_metrics);
                if (self.structural_downstream) |downstream| downstream.deinit();
                if (self.composite_structural) |composite| composite.deinit();
                if (self.composite_rows) |rows| rows.deinit();
                if (self.each_layout) |*layout| layout.deinit();
                if (self.each_replacement) |replacement| replacement.deinit();
                if (self.each_rows) |rows| rows.deinit();
                if (self.render_splice) |*splice| splice.deinit();
                for (self.pending_on_change_commands.items) |pending| pending.cmd.decref(self.roc_host);
                self.pending_on_change_commands.deinit(allocator);
                allocator.free(self.structural_changes);
                allocator.free(self.changed_record_ids);
                self.fallback_batch.deinit(allocator);
                allocator.destroy(self);
            }
        };

        fn locationSnapshotFromCommandPayload(payload: anytype) boundary.LocationSnapshot {
            return .{
                .path = payload.path.asSlice(),
                .query = payload.query.asSlice(),
                .hash = payload.hash.asSlice(),
            };
        }

        fn storageAreaFromCommand(area_id: u64) boundary.StorageArea {
            return boundary.StorageArea.fromId(area_id) orelse @panic("storage command referenced an unknown storage area");
        }

        const BrowserSourceRefresh = union(enum) {
            location,
            visibility,
            online,
            storage: struct { area: boundary.StorageArea, key: []const u8 },
        };

        fn browserSourceMatches(record: *HostSignalRecord, refresh: BrowserSourceRefresh) bool {
            return switch (refresh) {
                .location => record.locationSource() != null,
                .visibility => record.visibilitySource() != null,
                .online => record.onlineSource() != null,
                .storage => |target| if (record.storageSource()) |payload| payload.area == target.area and std.mem.eql(u8, payload.key, target.key) else false,
            };
        }

        fn tryDispatchCurrentBrowserSources(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, refresh: BrowserSourceRefresh) CollectionError!render.Counts {
            const allocator = Ctx.allocator(ctx);
            var expected: usize = 0;
            for (self.active_signal_graph.items) |node| {
                if (browserSourceMatches(node.record, refresh)) expected = std.math.add(usize, expected, 1) catch return error.ResourceLimit;
            }
            var owned = signal_records.OwnedSourceUpdates.init(allocator, expected) catch return error.OutOfMemory;
            defer owned.deinit(ctx, roc_host, &self.pending_roc_metrics);
            for (self.active_signal_graph.items) |node| {
                if (!browserSourceMatches(node.record, refresh)) continue;
                const incoming: struct { value: HostValue, cap: HostValueCapability } = switch (refresh) {
                    .location => blk: {
                        const payload = node.record.locationSource().?;
                        const raw = Ctx.initialLocationPayload(ctx, roc_host, payload.payload_cap);
                        break :blk .{ .value = callHostValueToHostValueWithCapability(ctx, roc_host, payload.payload_cap, payload.from_payload.toAbi(), raw), .cap = payload.cap };
                    },
                    .visibility => blk: {
                        const payload = node.record.visibilitySource().?;
                        const raw = Ctx.initialVisibilityPayload(ctx, roc_host, payload.payload_cap);
                        break :blk .{ .value = callHostValueToHostValueWithCapability(ctx, roc_host, payload.payload_cap, payload.from_payload.toAbi(), raw), .cap = payload.cap };
                    },
                    .online => blk: {
                        const payload = node.record.onlineSource().?;
                        const raw = Ctx.initialOnlinePayload(ctx, roc_host, payload.payload_cap);
                        break :blk .{ .value = callHostValueToHostValueWithCapability(ctx, roc_host, payload.payload_cap, payload.from_payload.toAbi(), raw), .cap = payload.cap };
                    },
                    .storage => blk: {
                        const payload = node.record.storageSource().?;
                        const raw = Ctx.initialStoragePayload(ctx, roc_host, payload.area, payload.key, payload.payload_cap);
                        break :blk .{ .value = callHostValueToHostValueWithCapability(ctx, roc_host, payload.payload_cap, payload.from_payload.toAbi(), raw), .cap = payload.cap };
                    },
                };
                owned.adoptAssumeCapacity(node.record, incoming.value, incoming.cap, &self.pending_roc_metrics) catch {
                    callHostValueToUnitWithCapability(ctx, roc_host, incoming.cap, hv.hostValueCapabilityDrop(incoming.cap), incoming.value);
                    return error.ResourceLimit;
                };
            }
            const transaction = try PreparedSourceTransaction.prepareMany(self, ctx, roc_host, &owned) orelse return .{};
            defer transaction.deinit();
            var metrics = self.pending_roc_metrics;
            metrics.bump(.dirty_source_roots, transaction.root_count);
            self.pending_roc_metrics = metrics;
            return transaction.commit();
        }

        /// Prepares and publishes all location roots atomically, returning host
        /// allocation or resource failure without changing committed state.
        pub fn tryDispatchCurrentLocationSources(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost) CollectionError!render.Counts {
            return self.tryDispatchCurrentBrowserSources(ctx, roc_host, .location);
        }

        /// Dispatches current location sources through validated routing and dependency-ordered propagation.
        pub fn dispatchCurrentLocationSources(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost) render.Counts {
            return self.tryDispatchCurrentLocationSources(ctx, roc_host) catch |err| std.debug.panic("failed to prepare atomic location-source transaction: {s}", .{@errorName(err)});
        }

        /// Prepares and publishes all visibility roots atomically, returning
        /// host preparation failure without partial cache or render mutation.
        pub fn tryDispatchCurrentVisibilitySources(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost) CollectionError!render.Counts {
            return self.tryDispatchCurrentBrowserSources(ctx, roc_host, .visibility);
        }

        /// Dispatches current visibility sources through validated routing and dependency-ordered propagation.
        pub fn dispatchCurrentVisibilitySources(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost) render.Counts {
            return self.tryDispatchCurrentVisibilitySources(ctx, roc_host) catch @panic("failed to prepare atomic visibility-source transaction");
        }

        /// Prepares and publishes all online roots atomically, returning host
        /// preparation failure while leaving the transaction retryable.
        pub fn tryDispatchCurrentOnlineSources(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost) CollectionError!render.Counts {
            return self.tryDispatchCurrentBrowserSources(ctx, roc_host, .online);
        }

        /// Dispatches current online sources through validated routing and dependency-ordered propagation.
        pub fn dispatchCurrentOnlineSources(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost) render.Counts {
            return self.tryDispatchCurrentOnlineSources(ctx, roc_host) catch @panic("failed to prepare atomic online-source transaction");
        }

        /// Prepares and publishes the matching storage roots atomically,
        /// returning host preparation failure without partial publication.
        pub fn tryDispatchCurrentStorageSources(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, area: boundary.StorageArea, key: []const u8) CollectionError!render.Counts {
            return self.tryDispatchCurrentBrowserSources(ctx, roc_host, .{ .storage = .{ .area = area, .key = key } });
        }

        /// Dispatches current storage sources through validated routing and dependency-ordered propagation.
        pub fn dispatchCurrentStorageSources(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, area: boundary.StorageArea, key: []const u8) render.Counts {
            return self.tryDispatchCurrentStorageSources(ctx, roc_host, area, key) catch @panic("failed to prepare atomic storage-source transaction");
        }

        /// Publishes a location change and refreshes active location sources in the same engine turn.
        pub fn navigateLocationCommand(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, kind: NavigationKind, location: boundary.LocationSnapshot) render.Counts {
            Ctx.sink(ctx).navigate(kind, location);
            return self.dispatchCurrentLocationSources(ctx, roc_host);
        }

        /// Sets storage text command at the narrow host or engine boundary that owns the mutation.
        pub fn setStorageTextCommand(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, payload: anytype) render.Counts {
            const area = storageAreaFromCommand(payload.area);
            const key = payload.key.asSlice();
            Ctx.sink(ctx).setStorageText(area, key, payload.value.asSlice());
            return self.dispatchCurrentStorageSources(ctx, roc_host, area, key);
        }

        /// Sets document title command at the narrow host or engine boundary that owns the mutation.
        pub fn setDocumentTitleCommand(_: *Self, ctx: Ctx.Handle, payload: anytype) render.Counts {
            Ctx.sink(ctx).setDocumentTitle(payload.title.asSlice());
            return .{};
        }

        /// Removes storage command and releases the ownership attached to that live entry.
        pub fn removeStorageCommand(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, payload: anytype) render.Counts {
            const area = storageAreaFromCommand(payload.area);
            const key = payload.key.asSlice();
            Ctx.sink(ctx).removeStorage(area, key);
            return self.dispatchCurrentStorageSources(ctx, roc_host, area, key);
        }

        /// Performs update state command inside the shared engine while preserving transaction and changed-set invariants.
        pub fn updateStateCommand(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, owner_scope_id: ids.ScopeId, cmd: erased_calls.UpdateStateCmd) render.Counts {
            return self.tryUpdateStateCommand(ctx, roc_host, owner_scope_id, cmd) catch @panic("failed to prepare state command transaction");
        }

        /// Executes a reusable single-state recipe through the same write-set
        /// transaction as coordinated updates. The command remains borrowed;
        /// each attempt materializes a fresh independently owned proposal.
        pub fn tryUpdateStateCommand(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, owner_scope_id: ids.ScopeId, cmd: erased_calls.UpdateStateCmd) CollectionError!render.Counts {
            return self.tryUpdateStateCommands(ctx, roc_host, owner_scope_id, &.{cmd});
        }

        /// Resolves every destination in the command owner's live scope before
        /// invoking any value recipe. Duplicate destinations are rejected even
        /// if their proposals would compare equal. Materialized proposals are
        /// consumed by one atomic transaction; the reusable commands stay owned
        /// by the caller and are safe to retry after preparation refusal.
        pub fn tryUpdateStateCommands(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, owner_scope_id: ids.ScopeId, commands: []const erased_calls.UpdateStateCmd) CollectionError!render.Counts {
            const allocator = Ctx.allocator(ctx);
            const writes = try allocator.alloc(StateWrite, commands.len);
            defer allocator.free(writes);
            var destinations: std.AutoHashMapUnmanaged(u64, void) = .empty;
            defer destinations.deinit(allocator);
            try destinations.ensureTotalCapacity(allocator, std.math.cast(u32, commands.len) orelse return error.ResourceLimit);
            for (commands, writes) |cmd, *write| {
                const binder_token = retained_values.hostSignalTokenFromCallable(cmd.binder);
                const target_node_id = self.resolveStateCommandTarget(owner_scope_id, binder_token);
                const state_cap = Ctx.stateCapability(ctx, target_node_id.raw());
                assertHostValueCapabilitiesMatch(cmd.update.capability, state_cap, "state command value capability did not match its target state");
                const destination = destinations.getOrPutAssumeCapacity(target_node_id.raw());
                if (destination.found_existing) return error.InvalidDescriptor;
                write.* = .{ .state_id = target_node_id.raw(), .cap = state_cap, .value = undefined };
            }
            for (commands, writes) |cmd, *write| write.value = erased_calls.callValueInitThunk(roc_host, cmd.update.initial);
            return self.tryDispatchStateWrites(ctx, roc_host, writes);
        }

        /// Reads the explicit destination once from settled state and evaluates
        /// a reusable pure updater through its owning capability. The input is
        /// independently owned and released here; the proposed replacement is
        /// consumed by the normal state transaction, including on refusal.
        pub fn tryUpdateTransformCommand(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, owner_scope_id: ids.ScopeId, cmd: abi.NodeStateTransform) CollectionError!render.Counts {
            const binder_token = retained_values.hostSignalTokenFromCallable(cmd.binder);
            const target = self.resolveStateCommandTarget(owner_scope_id, binder_token);
            const cap = Ctx.stateCapability(ctx, target.raw());
            assertHostValueCapabilitiesMatch(cmd.capability, cap, "state updater capability did not match its target state");
            const current = Ctx.stateValueByNodeId(ctx, target.raw());
            defer callHostValueToUnitWithCapability(ctx, roc_host, cap, hv.hostValueCapabilityDrop(cap), current);
            const next = callHostValueToHostValueWithCapability(ctx, roc_host, cap, cmd.transform, current);
            return self.tryDispatchStateValue(ctx, roc_host, target.raw(), next, cap);
        }

        /// Applies an atomic batch of state changes. Every destination is
        /// resolved before any recipe or reducer runs; a reducer reads its
        /// state's settled value at this commit, so it can never apply a value
        /// captured before an effect. Duplicate destinations are rejected. A
        /// change from an effect's result whose state was retired while the
        /// effect ran is skipped; any other change to a missing state is a bug.
        pub fn tryUpdateChangeCommands(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, owner_scope_id: ids.ScopeId, changes: []const abi.NodeStateChange) CollectionError!render.Counts {
            const allocator = Ctx.allocator(ctx);
            const writes = try allocator.alloc(StateWrite, changes.len);
            defer allocator.free(writes);
            const selected = try allocator.alloc(usize, changes.len);
            defer allocator.free(selected);
            var destinations: std.AutoHashMapUnmanaged(u64, void) = .empty;
            defer destinations.deinit(allocator);
            try destinations.ensureTotalCapacity(allocator, std.math.cast(u32, changes.len) orelse return error.ResourceLimit);
            var write_count: usize = 0;
            for (changes, 0..) |change, change_index| {
                const binder = switch (change.tag) {
                    .Set => change.payload_set().binder,
                    .Transform => change.payload_transform().binder,
                };
                const binder_token = retained_values.hostSignalTokenFromCallable(binder);
                const target_node_id = if (self.applying_effect_result)
                    self.findStateCommandTarget(owner_scope_id, binder_token) orelse continue
                else
                    self.resolveStateCommandTarget(owner_scope_id, binder_token);
                const state_cap = Ctx.stateCapability(ctx, target_node_id.raw());
                switch (change.tag) {
                    .Set => assertHostValueCapabilitiesMatch(change.payload_set().update.capability, state_cap, "state change value capability did not match its target state"),
                    .Transform => assertHostValueCapabilitiesMatch(change.payload_transform().capability, state_cap, "state change reducer capability did not match its target state"),
                }
                const destination = destinations.getOrPutAssumeCapacity(target_node_id.raw());
                if (destination.found_existing) return error.InvalidDescriptor;
                writes[write_count] = .{ .state_id = target_node_id.raw(), .cap = state_cap, .value = undefined };
                selected[write_count] = change_index;
                write_count += 1;
            }
            for (writes[0..write_count], selected[0..write_count]) |*write, change_index| write.value = switch (changes[change_index].tag) {
                .Set => erased_calls.callValueInitThunk(roc_host, changes[change_index].payload_set().update.initial),
                .Transform => blk: {
                    const transform = changes[change_index].payload_transform();
                    const current = Ctx.stateValueByNodeId(ctx, write.state_id);
                    defer callHostValueToUnitWithCapability(ctx, roc_host, write.cap, hv.hostValueCapabilityDrop(write.cap), current);
                    break :blk callHostValueToHostValueWithCapability(ctx, roc_host, write.cap, transform.transform, current);
                },
            };
            return self.tryDispatchStateWrites(ctx, roc_host, writes[0..write_count]);
        }

        /// Applies a `Then` command: its changes commit now, and its effect is
        /// queued for the host to run after the turn settles. Roc prepares the
        /// effect's thunk here, from a snapshot of the declared reads of the
        /// handler, sink, or effect whose command this is, taken after the
        /// changes committed. The changes may retire the scope that ran the
        /// command, such as a dialog whose button closes it: the effect then
        /// belongs to the nearest surviving ancestor, and if a retired scope
        /// held one of the reads, the snapshot is the one taken just before
        /// the commit, which is what the handler saw.
        pub fn tryThenCommand(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, owner_scope_id: ids.ScopeId, cmd: erased_calls.ThenCmd) CollectionError!render.Counts {
            if (comptime @hasDecl(Ctx, "runsEffects")) {
                const origin = self.effect_origin orelse @panic("a Then command needs declared reads; bind it through an action, a change sink, or Action.on_mount");
                const allocator = Ctx.allocator(ctx);
                try self.pending_effects.ensureUnusedCapacity(allocator, 1);
                var reads = origin.cloneRetained(allocator, &self.pending_roc_metrics);
                errdefer self.releaseEffectReads(ctx, &reads);
                const cap = retained_values.retainHostValueCapability(self.hostSignalBindingCapability(ctx, &reads), &self.pending_roc_metrics);
                defer retained_values.releaseHostValueCapability(cap, roc_host, &self.pending_roc_metrics);
                const before = self.evalHostSignalBinding(ctx, roc_host, &reads);
                var before_dropped = false;
                errdefer if (!before_dropped) callHostValueToUnitWithCapability(ctx, roc_host, cap, hv.hostValueCapabilityDrop(cap), before);
                const counts = try self.tryUpdateChangeCommands(ctx, roc_host, owner_scope_id, cmd.changes.items());
                const snapshot = if (self.readsStatesActive(&reads)) blk: {
                    callHostValueToUnitWithCapability(ctx, roc_host, cap, hv.hostValueCapabilityDrop(cap), before);
                    before_dropped = true;
                    break :blk self.evalHostSignalBinding(ctx, roc_host, &reads);
                } else before;
                before_dropped = true;
                defer callHostValueToUnitWithCapability(ctx, roc_host, cap, hv.hostValueCapabilityDrop(cap), snapshot);
                const thunk = retained_values.prepareEffectWithCapability(Ctx, ctx, roc_host, cmd.effect, snapshot, cap, &self.pending_roc_metrics);
                self.pending_effects.appendAssumeCapacity(.{
                    .id = self.next_effect_id,
                    .owner_scope_id = self.nearestActiveScope(owner_scope_id),
                    .thunk = thunk,
                    .reads = reads,
                });
                self.next_effect_id += 1;
                return counts;
            } else {
                @panic("Then commands are unsupported by this host");
            }
        }

        fn readsStatesActive(self: *Self, reads: *const HostSignalBinding) bool {
            for (reads.source_node_ids) |node_id| if (self.stateIndexByNodeId(node_id) == null) return false;
            return true;
        }

        /// The innermost scope at or above `scope_id` that is still active.
        /// The root scope never retires, so the walk always ends.
        pub fn nearestActiveScope(self: *Self, scope_id: ids.ScopeId) ids.ScopeId {
            var current = scope_id;
            while (true) {
                if (current.index() >= self.scopes.items.len) @panic("command owner referenced an unknown scope");
                const scope = self.scopes.items[current.index()];
                if (scope.lifecycle.isActive()) return current;
                current = scope.parent_scope_id orelse @panic("command owner's root scope is inactive");
            }
        }

        /// Hands the host the oldest queued effect, transferring ownership of
        /// its thunk and reads reference.
        pub fn takeNextPendingEffect(self: *Self) ?PendingEffect {
            if (self.pending_effects.items.len == 0) return null;
            return self.pending_effects.orderedRemove(0);
        }

        /// Releases an effect the host took but did not hand to Roc.
        pub fn releasePendingEffect(self: *Self, ctx: Ctx.Handle, effect: *PendingEffect) void {
            const roc_host = self.roc_host orelse @panic("pending effect cannot release its thunk without a Roc host");
            abi.decrefErasedCallable(effect.thunk, roc_host);
            self.releaseEffectReads(ctx, &effect.reads);
            effect.* = undefined;
        }

        /// Records an effect whose thunk the host has handed to its worker,
        /// taking over the reads reference until the effect finishes.
        pub fn trackRunningEffect(self: *Self, ctx: Ctx.Handle, effect: *PendingEffect) void {
            self.running_effects.ensureUnusedCapacity(Ctx.allocator(ctx), 1) catch @panic("out of memory");
            self.running_effects.appendAssumeCapacity(.{
                .id = effect.id,
                .owner_scope_id = effect.owner_scope_id,
                .reads = effect.reads,
            });
            effect.* = undefined;
        }

        /// Removes a finished effect's record so the host can apply its command.
        pub fn finishRunningEffect(self: *Self, effect_id: u64) RunningEffect {
            for (self.running_effects.items, 0..) |running, index| {
                if (running.id == effect_id) return self.running_effects.orderedRemove(index);
            }
            @panic("finished effect was not running");
        }

        /// Releases the reads of a finished effect the host has applied.
        pub fn releaseFinishedEffect(self: *Self, ctx: Ctx.Handle, running: *RunningEffect) void {
            self.releaseEffectReads(ctx, &running.reads);
            running.* = undefined;
        }

        fn releaseEffectReads(self: *Self, ctx: Ctx.Handle, reads: *HostSignalBinding) void {
            const roc_host = self.roc_host orelse @panic("effect cannot release its reads without a Roc host");
            reads.deinit(Ctx.allocator(ctx), ctx, roc_host, &self.pending_roc_metrics);
        }

        /// Releases queued effect closures and tracked reads at host teardown.
        /// The host must finish or abandon its running calls before releasing
        /// these retained references; this is not scope-driven cancellation.
        pub fn clearEffects(self: *Self, ctx: Ctx.Handle) void {
            for (self.pending_effects.items) |*effect| self.releasePendingEffect(ctx, effect);
            self.pending_effects.items.len = 0;
            self.pending_effects.deinit(Ctx.allocator(ctx));
            self.pending_effects = .empty;
            for (self.running_effects.items) |*running| self.releaseEffectReads(ctx, &running.reads);
            self.running_effects.items.len = 0;
            self.running_effects.deinit(Ctx.allocator(ctx));
            self.running_effects = .empty;
        }

        fn onChangeIndexOf(self: *Self, desc: *const HostNodeOnChangeDesc) usize {
            const base = @intFromPtr(self.active_stream.on_changes.items.ptr);
            const address = @intFromPtr(desc);
            if (address < base) @panic("change sink descriptor is not in the active stream");
            const index = (address - base) / @sizeOf(HostNodeOnChangeDesc);
            if (index >= self.active_stream.on_changes.items.len) @panic("change sink descriptor is not in the active stream");
            return index;
        }

        /// Runs one pending change-sink command with that sink's reads as the
        /// effect origin, so a `Then` it contains snapshots the changed signal.
        fn runPendingOnChangeCommand(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, pending: HostPendingOnChangeCommand) render.Counts {
            const previous = self.effect_origin;
            defer self.effect_origin = previous;
            self.effect_origin = if (pending.on_change_index) |index| &self.active_stream.on_changes.items[index].signal else null;
            return self.runCommand(ctx, roc_host, ids.ScopeId.fromRaw(pending.scope_id), pending.cmd);
        }

        /// Runs a command at a fatal boundary, including follow-on commands
        /// after an earlier engine step committed. Unlike tryRunCommand, this
        /// call cannot unwind a failed preparation to its caller. Native fault
        /// instrumentation classifies this boundary separately from retryable
        /// ingress; it does not change command execution or failure policy.
        pub fn runCommand(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, owner_scope_id: ids.ScopeId, cmd: erased_calls.Cmd) render.Counts {
            if (comptime @hasDecl(Ctx, "enterFatalCommandBoundary")) Ctx.enterFatalCommandBoundary(ctx);
            defer if (comptime @hasDecl(Ctx, "leaveFatalCommandBoundary")) Ctx.leaveFatalCommandBoundary(ctx);
            return self.tryRunCommand(ctx, roc_host, owner_scope_id, cmd) catch @panic("failed to prepare command transaction");
        }

        /// Runs a command while exposing recoverable state and task-start
        /// preparation refusal to ingress. Other command kinds retain their
        /// host-boundary failure policy. Commands remain caller-owned and
        /// reusable; state-value recipes materialize fresh proposals per attempt.
        pub fn tryRunCommand(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, owner_scope_id: ids.ScopeId, cmd: erased_calls.Cmd) CollectionError!render.Counts {
            return switch (cmd.tag) {
                .Noop => .{},
                .PushState => blk: {
                    const payload = cmd.payload_push_state();
                    break :blk self.navigateLocationCommand(ctx, roc_host, .push, locationSnapshotFromCommandPayload(&payload));
                },
                .RemoveStorage => self.removeStorageCommand(ctx, roc_host, cmd.payload_remove_storage()),
                .ReplaceState => blk: {
                    const payload = cmd.payload_replace_state();
                    break :blk self.navigateLocationCommand(ctx, roc_host, .replace, locationSnapshotFromCommandPayload(&payload));
                },
                .SetStorageText => self.setStorageTextCommand(ctx, roc_host, cmd.payload_set_storage_text()),
                .SetDocumentTitle => self.setDocumentTitleCommand(ctx, cmd.payload_set_document_title()),
                .UpdateState => self.tryUpdateStateCommand(ctx, roc_host, owner_scope_id, cmd.payload_update_state()),
                .UpdateStates => self.tryUpdateStateCommands(ctx, roc_host, owner_scope_id, cmd.payload_update_states().items()),
                .UpdateTransform => self.tryUpdateTransformCommand(ctx, roc_host, owner_scope_id, cmd.payload_update_transform()),
                .UpdateChanges => self.tryUpdateChangeCommands(ctx, roc_host, owner_scope_id, cmd.payload_update_changes().items()),
                .Then => self.tryThenCommand(ctx, roc_host, owner_scope_id, cmd.payload_then()),
            };
        }

        fn tickIntervalRecord(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, record: *HostSignalRecord) render.Counts {
            const interval_payload = record.requireIntervalSource();
            const current = self.evalHostSignalRecord(ctx, roc_host, record);
            defer self.dropHostSignalRecordValue(ctx, roc_host, record, current);
            const next = callHostValueToHostValueWithCapability(ctx, roc_host, interval_payload.cap, interval_payload.tick.toAbi(), current);
            return self.dispatchEffectSourceValue(ctx, roc_host, record, next);
        }

        /// Advances interval source through the shared propagation queue.
        pub fn tickIntervalSource(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, period_ms: u64) render.Counts {
            const record = self.activeIntervalRecordByPeriod(period_ms) orelse @panic("tick_interval matched no active interval source");
            return self.tickIntervalRecord(ctx, roc_host, record);
        }

        /// Advances interval source by runtime token through the shared propagation queue.
        pub fn tickIntervalSourceByRuntimeToken(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, token: u64) render.Counts {
            const source_token = self.activeIntervalSourceTokenByRuntimeToken(token) orelse @panic("timer tick referenced an inactive interval token");
            const record = self.activeIntervalRecordByToken(source_token) orelse @panic("timer tick matched no active interval source");
            return self.tickIntervalRecord(ctx, roc_host, record);
        }

        /// Performs eval dirty on change command inside the shared engine while preserving transaction and changed-set invariants.
        pub fn evalDirtyOnChangeCommand(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, desc: *HostNodeOnChangeDesc, dirty_source_node_ids: []const u64, dirty_generation: u64) ?HostPendingOnChangeCommand {
            const result = self.evalDirtyHostSignalBinding(ctx, roc_host, &desc.signal, dirty_source_node_ids, dirty_generation);
            const cap = self.hostSignalBindingCapability(ctx, &desc.signal);
            if (!result.changed) {
                callHostValueToUnitWithCapability(ctx, roc_host, cap, hv.hostValueCapabilityDrop(cap), result.value);
                return null;
            }
            if (!self.updateDirtySignalCache(ctx, roc_host, &desc.cached_value, result.value, cap)) return null;

            const value = self.cloneCachedSignalValue(ctx, &desc.cached_value);
            defer callHostValueToUnitWithCapability(ctx, roc_host, cap, hv.hostValueCapabilityDrop(cap), value);
            const cmd = callHostValueToCmdWithCapability(ctx, roc_host, cap, desc.to_cmd.toAbi(), value);
            cmd.incref(1);
            cmd.decref(roc_host);
            return .{ .scope_id = desc.scope_id.raw(), .cmd = cmd, .on_change_index = self.onChangeIndexOf(desc) };
        }

        /// Performs eval dirty on change inside the shared engine while preserving transaction and changed-set invariants.
        pub fn evalDirtyOnChange(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, desc: *HostNodeOnChangeDesc, dirty_source_node_ids: []const u64, dirty_generation: u64) render.Counts {
            const pending = self.evalDirtyOnChangeCommand(ctx, roc_host, desc, dirty_source_node_ids, dirty_generation) orelse return .{};
            const cmd = pending.cmd;
            defer cmd.decref(roc_host);
            return self.runCommand(ctx, roc_host, ids.ScopeId.fromRaw(pending.scope_id), cmd);
        }

        fn collectDirtyRenderSinksAndCommands(
            self: *Self,
            ctx: Ctx.Handle,
            roc_host: *abi.RocHost,
            dirty_source_node_ids: []const u64,
            changed_record_ids: []const u64,
            dirty_generation: u64,
            pending_on_change_commands: *shared_buffer.List(HostPendingOnChangeCommand),
        ) render.Counts {
            var counts: render.Counts = .{};
            const allocator = Ctx.allocator(ctx);

            for (changed_record_ids) |record_id| {
                const route_index: usize = @intCast(record_id);
                if (route_index < self.active_text_signal_routes.items.len) {
                    for (self.active_text_signal_routes.items[route_index].slice()) |route| {
                        switch (route.kind) {
                            .text_node => {
                                const desc = &self.active_stream.signal_text_nodes.items[route.index];
                                if (self.evalDirtySignalTextField(ctx, roc_host, desc.elem_id.raw(), .text, &desc.signal, desc.read, &desc.cached_value, dirty_source_node_ids, dirty_generation)) {
                                    counts.addTextField(.text);
                                }
                            },
                            .text_attr => {
                                const desc = &self.active_stream.signal_text_attrs.items[route.index];
                                if (self.evalDirtySignalTextField(ctx, roc_host, desc.elem_id.raw(), desc.field, &desc.signal, desc.read, &desc.cached_value, dirty_source_node_ids, dirty_generation)) {
                                    counts.addTextField(desc.field);
                                }
                            },
                            .custom_text_attr => {
                                const desc = &self.active_stream.signal_custom_text_attrs.items[route.index];
                                if (self.evalDirtySignalTextAttr(ctx, roc_host, desc.elem_id.raw(), desc.name, &desc.signal, desc.read, &desc.cached_value, dirty_source_node_ids, dirty_generation)) {
                                    counts.addTextAttr();
                                }
                            },
                            .custom_text_optional_attr => {
                                const desc = &self.active_stream.signal_optional_custom_text_attrs.items[route.index];
                                if (self.evalDirtySignalOptionalTextAttr(ctx, roc_host, desc.elem_id.raw(), desc.name, &desc.signal, desc.present, desc.read, &desc.cached_value, dirty_source_node_ids, dirty_generation)) {
                                    counts.addTextAttr();
                                }
                            },
                        }
                    }
                }

                if (route_index < self.active_bool_signal_routes.items.len) {
                    for (self.active_bool_signal_routes.items[route_index].slice()) |route| {
                        switch (route.kind) {
                            .bool_attr => {
                                const desc = &self.active_stream.signal_bool_attrs.items[route.index];
                                if (self.evalDirtySignalBoolField(ctx, roc_host, desc.elem_id.raw(), desc.field, &desc.signal, desc.read, &desc.cached_value, dirty_source_node_ids, dirty_generation)) {
                                    counts.addBoolField(desc.field);
                                }
                            },
                            .custom_bool_attr => {
                                const desc = &self.active_stream.signal_custom_bool_attrs.items[route.index];
                                if (self.evalDirtySignalBoolAttr(ctx, roc_host, desc.elem_id.raw(), desc.name, &desc.signal, desc.read, &desc.cached_value, dirty_source_node_ids, dirty_generation)) {
                                    counts.addTextAttr();
                                }
                            },
                        }
                    }
                }

                if (route_index < self.active_change_signal_routes.items.len) {
                    for (self.active_change_signal_routes.items[route_index].slice()) |route| {
                        const desc = &self.active_stream.on_changes.items[route.index];
                        if (self.evalDirtyOnChangeCommand(ctx, roc_host, desc, dirty_source_node_ids, dirty_generation)) |pending| {
                            pending_on_change_commands.append(allocator, pending) catch @panic("out of memory");
                        }
                    }
                }
            }

            if (comptime enable_runtime_metrics) self.render_metrics.addCommandCounts(counts);
            return counts;
        }

        fn runPendingOnChangeCommandsDeferringSourceEffects(
            self: *Self,
            ctx: Ctx.Handle,
            roc_host: *abi.RocHost,
            pending_on_change_commands: []const HostPendingOnChangeCommand,
            deferred_location_effect: *bool,
            deferred_storage_effects: *shared_buffer.List(HostDeferredStorageEffect),
        ) render.Counts {
            var counts: render.Counts = .{};
            const allocator = Ctx.allocator(ctx);

            for (pending_on_change_commands) |pending| {
                if (pending.scope_id >= self.scopes.items.len or !self.scopes.items[@intCast(pending.scope_id)].lifecycle.isActive()) {
                    continue;
                }
                switch (pending.cmd.tag) {
                    .PushState => {
                        const payload = pending.cmd.payload_push_state();
                        const location = locationSnapshotFromCommandPayload(&payload);
                        Ctx.sink(ctx).navigate(.push, location);
                        deferred_location_effect.* = true;
                    },
                    .ReplaceState => {
                        const payload = pending.cmd.payload_replace_state();
                        const location = locationSnapshotFromCommandPayload(&payload);
                        Ctx.sink(ctx).navigate(.replace, location);
                        deferred_location_effect.* = true;
                    },
                    .SetStorageText => {
                        const payload = pending.cmd.payload_set_storage_text();
                        const area = storageAreaFromCommand(payload.area);
                        const key = payload.key.asSlice();
                        Ctx.sink(ctx).setStorageText(area, key, payload.value.asSlice());
                        deferred_storage_effects.append(allocator, .{ .area = area, .key = allocator.dupe(u8, key) catch @panic("out of memory") }) catch @panic("out of memory");
                    },
                    .RemoveStorage => {
                        const payload = pending.cmd.payload_remove_storage();
                        const area = storageAreaFromCommand(payload.area);
                        const key = payload.key.asSlice();
                        Ctx.sink(ctx).removeStorage(area, key);
                        deferred_storage_effects.append(allocator, .{ .area = area, .key = allocator.dupe(u8, key) catch @panic("out of memory") }) catch @panic("out of memory");
                    },
                    else => counts.addAll(self.runPendingOnChangeCommand(ctx, roc_host, pending)),
                }
            }

            if (comptime enable_runtime_metrics) self.render_metrics.addCommandCounts(counts);
            return counts;
        }

        fn flushDeferredSourceEffects(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, deferred_location_effect: bool, deferred_storage_effects: []const HostDeferredStorageEffect) render.Counts {
            var counts: render.Counts = .{};
            if (deferred_location_effect) counts.addAll(self.dispatchCurrentLocationSources(ctx, roc_host));
            for (deferred_storage_effects) |effect| {
                counts.addAll(self.dispatchCurrentStorageSources(ctx, roc_host, effect.area, effect.key));
            }
            return counts;
        }

        /// Applies dirty render sinks after preparation has fixed semantics and reserved fallible growth.
        pub fn applyDirtyRenderSinks(self: *Self, ctx: Ctx.Handle, roc_host: *abi.RocHost, dirty_source_node_ids: []const u64, changed_record_ids: []const u64, dirty_generation: u64) render.Counts {
            const allocator = Ctx.allocator(ctx);
            var pending_on_change_commands: shared_buffer.List(HostPendingOnChangeCommand) = .empty;
            defer {
                for (pending_on_change_commands.items) |pending| {
                    pending.cmd.decref(roc_host);
                }
                pending_on_change_commands.deinit(allocator);
            }
            var deferred_storage_effects: shared_buffer.List(HostDeferredStorageEffect) = .empty;
            defer {
                for (deferred_storage_effects.items) |effect| allocator.free(effect.key);
                deferred_storage_effects.deinit(allocator);
            }
            var deferred_location_effect = false;
            var counts = self.collectDirtyRenderSinksAndCommands(
                ctx,
                roc_host,
                dirty_source_node_ids,
                changed_record_ids,
                dirty_generation,
                &pending_on_change_commands,
            );
            counts.addAll(self.runPendingOnChangeCommandsDeferringSourceEffects(
                ctx,
                roc_host,
                pending_on_change_commands.items,
                &deferred_location_effect,
                &deferred_storage_effects,
            ));
            counts.addAll(self.flushDeferredSourceEffects(ctx, roc_host, deferred_location_effect, deferred_storage_effects.items));
            return counts;
        }
    };
}

const VerifyCtxHost = struct {
    allocator: std.mem.Allocator,
    render_batch: render.TransactionalBatch = .{},
    state_capability: HostValueCapability = std.mem.zeroes(HostValueCapability),

    /// Produces an independently owned copy through the value's app-compiled capability.
    pub fn cloneHostValue(_: *@This(), value: HostValue) HostValue {
        return value;
    }

    /// Opens a checked capability frame for an app-compiled erased call.
    pub fn pushHostValueCapabilities(_: *@This(), _: []const HostValueCapability) void {}

    /// Closes the current capability frame after an app-compiled erased call.
    pub fn popHostValueCapabilities(_: *@This()) void {}
};

test "structural event validation rejects descriptors outside seen render stream" {
    const allocator = std.testing.allocator;
    var stream: HostNodeDescriptorStream = .{};
    defer stream.events.deinit(allocator);

    const binder: HostBinderToken = @ptrFromInt(0x1000);
    try stream.events.append(allocator, .{
        .elem_id = ids.ElemId.fromRaw(5),
        .binding = .{ .fixed = .click },
        .payload_descriptor = BoundaryPayloadDescriptor.init(.unit, .none),
        .handler = .{ .reduce = .{
            .binder_token = binder,
            .target_node_id = ids.NodeId.fromRaw(1),
            .read_binder_token = binder,
            .read_node_id = ids.NodeId.fromRaw(1),
            .payload_reducer = undefined,
        } },
        .owns_handler = false,
    });

    const missing = [_]bool{ true, true, false, false, false, false };
    try std.testing.expectEqual(@as(?u64, 5), firstEventDescriptorElemOutsideSeen(&stream, &missing));

    const seen = [_]bool{ false, false, false, false, false, true };
    try std.testing.expectEqual(@as(?u64, null), firstEventDescriptorElemOutsideSeen(&stream, &seen));
}

const VerifySink = struct {
    ctx: *VerifyCtxHost,
    /// Stages a complete render-surface reset in the host command sink.
    pub fn reset(_: VerifySink) void {}
    /// Emits the already-decided command that attaches a newly created render node.
    pub fn appendNode(_: VerifySink, _: ids.ElemId, _: ids.ElemId, _: render.NodeShape) void {}
    /// Ensures the host render surface contains the engine-selected node and tag.
    pub fn ensureNode(_: VerifySink, _: ids.ElemId, _: render.NodeShape) void {}
    /// Emits removal of a node whose owning scope has already been disposed by the engine.
    pub fn removeNode(_: VerifySink, _: ids.ElemId) void {}
    /// Publishes the engine-selected child order for one parent.
    pub fn replaceChildren(_: VerifySink, _: ids.ElemId, _: []const ids.ElemId) void {}
    /// Publishes a moves-only child reorder without rebuilding surviving row structure.
    pub fn replaceChildrenForMoves(_: VerifySink, _: ids.ElemId, _: []const ids.ElemId) void {}
    /// Applies an engine-decided text field value to one render node.
    pub fn applyTextField(_: VerifySink, _: ids.ElemId, _: RenderTextField, _: []const u8) void {}
    /// Applies an engine-decided custom text attribute to one render node.
    pub fn applyTextAttr(_: VerifySink, _: ids.ElemId, _: []const u8, _: []const u8) void {}
    /// Applies an engine-decided boolean field value to one render node.
    pub fn applyBoolField(_: VerifySink, _: ids.ElemId, _: RenderBoolField, _: bool) void {}
    /// Clears an engine-decided text field from one render node.
    pub fn clearTextField(_: VerifySink, _: ids.ElemId, _: RenderTextField) void {}
    /// Clears an engine-decided custom text attribute from one render node.
    pub fn clearTextAttr(_: VerifySink, _: ids.ElemId, _: []const u8) void {}
    /// Clears an engine-decided boolean field from one render node.
    pub fn clearBoolField(_: VerifySink, _: ids.ElemId, _: RenderBoolField) void {}
    /// Publishes a validated canonical event binding selected by the engine.
    pub fn bindEvent(_: VerifySink, _: ids.ElemId, _: render_cache_mod.EventBindingKey, _: HostRequiredEventBinding) void {}
    /// Removes a host event registration whose engine-owned binding is no longer active.
    pub fn clearEvent(_: VerifySink, _: ids.ElemId, _: render_cache_mod.EventBindingKey) void {}
    /// Starts the bounded host registration for an engine-owned interval source.
    pub fn startInterval(_: VerifySink, _: ids.IntervalToken, _: u64) void {}
    /// Cancels the host registration for an interval whose owning scope is no longer active.
    pub fn cancelInterval(_: VerifySink, _: ids.IntervalToken) void {}
    /// Applies an engine-issued storage write without deriving storage semantics.
    pub fn setStorageText(_: VerifySink, _: boundary.StorageArea, _: []const u8, _: []const u8) void {}
    /// Applies an engine-issued storage removal without deriving storage semantics.
    pub fn removeStorage(_: VerifySink, _: boundary.StorageArea, _: []const u8) void {}
    /// Applies an engine-issued browser-history command without deriving routing semantics.
    pub fn navigate(_: VerifySink, _: NavigationKind, _: boundary.LocationSnapshot) void {}
    /// Applies the document title already selected by graph propagation.
    pub fn setDocumentTitle(_: VerifySink, _: []const u8) void {}
    /// Checks that the host render surface matches the engine's committed node metadata.
    pub fn debugAssertNode(_: VerifySink, _: ids.ElemId, _: bool, _: ?[]const u8, _: ?ids.ElemId, _: []const ids.ElemId, _: ?ids.EventId, _: ?ids.EventId, _: ?ids.EventId, _: ?ids.EventId, _: ?ids.EventId, _: ?ids.EventId, _: ?ids.EventId) void {}
};

const VerifyCtx = struct {
    pub const Handle = *VerifyCtxHost;
    pub const RegistryOps = hv.RegistryOps();
    pub const Metrics = RuntimeMetrics;
    pub const Sink = VerifySink;

    /// Creates the host's zeroed metric accumulator for a new engine operation.
    pub fn zeroMetrics() Metrics {
        return zeroRuntimeMetrics();
    }

    /// Returns the allocator owned by this host context for shared-engine work.
    pub fn allocator(ctx: Handle) std.mem.Allocator {
        return ctx.allocator;
    }

    /// Returns the reusable unpublished/published render command bank.
    pub fn renderCommandBatch(ctx: Handle) *render.TransactionalBatch {
        return &ctx.render_batch;
    }

    /// Produces an independently owned copy through the value's app-compiled capability.
    pub fn cloneHostValue(_: Handle, value: HostValue) HostValue {
        return value;
    }

    /// Opens a checked capability frame for an app-compiled erased call.
    pub fn pushHostValueCapabilities(_: Handle, _: []const HostValueCapability) void {}

    /// Closes the current capability frame after an app-compiled erased call.
    pub fn popHostValueCapabilities(_: Handle) void {}

    /// Resolves a state cell by dense node id without scanning the signal graph.
    pub fn stateValueByNodeId(_: Handle, _: u64) HostValue {
        return .invalid;
    }

    /// Replaces a state source value in the verification host.
    pub fn updateStateValue(_: Handle, _: *abi.RocHost, _: u64, _: HostValue) bool {
        return true;
    }

    /// Returns the exact app-compiled capability that owns the requested state cell.
    pub fn stateCapability(ctx: Handle, _: u64) HostValueCapability {
        return ctx.state_capability;
    }

    /// Supplies a deterministic seed while verifying source materialization.
    pub fn initialEntropySeedPayload(_: Handle, _: *abi.RocHost, _: HostValueCapability) HostValue {
        return .invalid;
    }

    /// Materializes the mount-time browser location through the source's owning capability.
    pub fn initialLocationPayload(_: Handle, _: *abi.RocHost, _: HostValueCapability) HostValue {
        return .invalid;
    }

    /// Materializes one declared storage key through the source's owning capability.
    pub fn initialStoragePayload(_: Handle, _: *abi.RocHost, _: boundary.StorageArea, _: []const u8, _: HostValueCapability) HostValue {
        return .invalid;
    }

    /// Materializes the mount-time visibility state through the source's owning capability.
    pub fn initialVisibilityPayload(_: Handle, _: *abi.RocHost, _: HostValueCapability) HostValue {
        return .invalid;
    }

    /// Materializes the mount-time online state through the source's owning capability.
    pub fn initialOnlinePayload(_: Handle, _: *abi.RocHost, _: HostValueCapability) HostValue {
        return .invalid;
    }

    /// Returns the thin render-command sink used by the shared engine.
    pub fn sink(ctx: Handle) Sink {
        return .{ .ctx = ctx };
    }
};

fn borrowedVerifyElemList(items: []const abi.Elem) abi.RocList(abi.Elem) {
    if (items.len == 0) return abi.RocList(abi.Elem).empty();
    return .{
        .elements_ptr = @constCast(items.ptr),
        .length = items.len,
        .capacity_or_alloc_ptr = items.len << 1,
    };
}

fn borrowedVerifyAttrList(items: []const abi.NodeAttr) abi.RocList(abi.NodeAttr) {
    if (items.len == 0) return abi.RocList(abi.NodeAttr).empty();
    return .{ .elements_ptr = @constCast(items.ptr), .length = items.len, .capacity_or_alloc_ptr = items.len << 1 };
}

fn borrowedVerifySignalExprList(items: []const abi.NodeSignalExpr) abi.RocList(abi.NodeSignalExpr) {
    if (items.len == 0) return abi.RocList(abi.NodeSignalExpr).empty();
    return .{ .elements_ptr = @constCast(items.ptr), .length = items.len, .capacity_or_alloc_ptr = items.len << 1 };
}

fn verifyStaticRoot(attrs: []const abi.NodeAttr, children: []const abi.Elem) abi.Elem {
    return .{
        .payload = .{ .element = .{
            .namespace = .html,
            .attrs = borrowedVerifyAttrList(attrs),
            .children = borrowedVerifyElemList(children),
            .tag = abi.RocStr.fromSlice("div", undefined),
        } },
        .tag = .Element,
    };
}

/// Builds a test element whose nested lists obey Roc ownership rules. Use this
/// for values retained by descriptors; the borrowed helper is immediate-only.
fn ownedVerifyStaticRoot(roc_host: *abi.RocHost, attrs: []const abi.NodeAttr, children: []const abi.Elem) abi.Elem {
    for (attrs) |attr| attr.incref(1);
    for (children) |child| child.incref(1);
    return .{
        .payload = .{ .element = .{
            .namespace = .html,
            .attrs = abi.RocList(abi.NodeAttr).fromSlice(attrs, roc_host),
            .children = abi.RocList(abi.Elem).fromSlice(children, roc_host),
            .tag = abi.RocStr.fromSlice("div", roc_host),
        } },
        .tag = .Element,
    };
}

fn decrefOwnedVerifySignalExprBox(expr: *abi.NodeSignalExpr, roc_host: *abi.RocHost) void {
    const Drop = struct {
        fn drop(data: ?*anyopaque, host: *abi.RocHost) callconv(.c) void {
            const payload: *abi.NodeSignalExpr = @ptrCast(@alignCast(data.?));
            payload.decref(host);
        }
    };
    abi.decrefBoxWith(@ptrCast(expr), @alignOf(abi.NodeSignalExpr), true, Drop.drop, roc_host);
}

fn boxOwnedVerifyElem(roc_host: *abi.RocHost, elem: abi.Elem) *abi.Elem {
    const raw = abi.allocateBox(@sizeOf(abi.Elem), @alignOf(abi.Elem), true, roc_host);
    const boxed: *abi.Elem = @ptrCast(@alignCast(raw));
    boxed.* = elem;
    return boxed;
}

fn decrefOwnedVerifyElemBox(elem: *abi.Elem, roc_host: *abi.RocHost) void {
    const Drop = struct {
        fn drop(data: ?*anyopaque, host: *abi.RocHost) callconv(.c) void {
            const payload: *abi.Elem = @ptrCast(@alignCast(data.?));
            payload.decref(host);
        }
    };
    abi.decrefBoxWith(@ptrCast(elem), @alignOf(abi.Elem), true, Drop.drop, roc_host);
}

fn boxOwnedVerifySignalExpr(roc_host: *abi.RocHost, expr: abi.NodeSignalExpr) *abi.NodeSignalExpr {
    expr.incref(1);
    const raw = abi.allocateBox(@sizeOf(abi.NodeSignalExpr), @alignOf(abi.NodeSignalExpr), true, roc_host);
    const boxed: *abi.NodeSignalExpr = @ptrCast(@alignCast(raw));
    boxed.* = expr;
    return boxed;
}

fn ownedVerifyStateRoot(roc_host: *abi.RocHost, binder: abi.RocErasedCallable, capability_callable: abi.RocErasedCallable, child: abi.Elem) abi.Elem {
    abi.increfErasedCallable(binder, 2);
    abi.increfErasedCallable(capability_callable, 3);
    return .{ .payload = .{ .state = .{
        .binder = binder,
        .cap = .{ .clone = capability_callable, .drop = capability_callable, .eq = capability_callable },
        .child = boxOwnedVerifyElem(roc_host, child),
        .initial = binder,
    } }, .tag = .State };
}

const OwnedAggregateGraphRoot = struct {
    allocator: std.mem.Allocator,
    roc_host: *abi.RocHost,
    value_callable: abi.RocErasedCallable,
    first_false_callable: abi.RocErasedCallable,
    first_true_callable: abi.RocErasedCallable,
    second_false_callable: abi.RocErasedCallable,
    second_true_callable: abi.RocErasedCallable,
    first_false_transform: abi.RocErasedCallable,
    first_true_transform: abi.RocErasedCallable,
    second_false_transform: abi.RocErasedCallable,
    second_true_transform: abi.RocErasedCallable,
    bool_callable: abi.RocErasedCallable,
    text_callable: abi.RocErasedCallable,
    first_condition: *abi.NodeSignalExpr,
    first_false: *abi.Elem,
    first_true: *abi.Elem,
    second_false: *abi.Elem,
    second_true: *abi.Elem,
    root: abi.Elem,

    fn signalBranch(self: *@This(), label: []const u8, binder: abi.RocErasedCallable, transform: abi.RocErasedCallable) *abi.Elem {
        const state_capability = HostValueCapability{ .clone = binder, .drop = binder, .eq = binder };
        const result_capability = HostValueCapability{ .clone = transform, .drop = transform, .eq = transform };
        const read = HostTextRead{ .capability = result_capability, .read = self.text_callable };
        const input = boxOwnedVerifySignalExpr(self.roc_host, .{ .payload = .{ .ref = binder }, .tag = .Ref });
        const signal = boxOwnedVerifySignalExpr(self.roc_host, .{ .payload = .{ .map = .{ ._0 = transform, ._1 = input, ._2 = transform, ._3 = result_capability } }, .tag = .Map });
        decrefOwnedVerifySignalExprBox(input, self.roc_host);
        var static_text = verifyStaticText();
        static_text.payload.text = abi.RocStr.fromSlice(label, self.roc_host);
        const signal_text = abi.Elem{ .payload = .{ .text_signal = .{ .read = read, .signal = signal } }, .tag = .TextSignal };
        const element = ownedVerifyStaticRoot(self.roc_host, &.{}, &.{ static_text, signal_text });
        static_text.decref(self.roc_host);
        signal_text.decref(self.roc_host);
        abi.increfErasedCallable(binder, 5);
        return boxOwnedVerifyElem(self.roc_host, .{ .payload = .{ .state = .{
            .binder = binder,
            .cap = state_capability,
            .child = boxOwnedVerifyElem(self.roc_host, element),
            .initial = binder,
        } }, .tag = .State });
    }

    fn initWithShape(allocator: std.mem.Allocator, roc_host: *abi.RocHost, nested: bool) !*@This() {
        const self = try allocator.create(@This());
        errdefer allocator.destroy(self);
        self.* = undefined;
        self.allocator = allocator;
        self.roc_host = roc_host;
        self.value_callable = abi.rocErasedCallableAllocate(roc_host, verifyStateCallable, null, 0) orelse return error.OutOfMemory;
        errdefer abi.decrefErasedCallable(self.value_callable, roc_host);
        self.first_false_callable = abi.rocErasedCallableAllocate(roc_host, verifyStateCallable, null, 0) orelse return error.OutOfMemory;
        errdefer abi.decrefErasedCallable(self.first_false_callable, roc_host);
        self.first_true_callable = abi.rocErasedCallableAllocate(roc_host, verifyStateCallable, null, 0) orelse return error.OutOfMemory;
        errdefer abi.decrefErasedCallable(self.first_true_callable, roc_host);
        self.second_false_callable = abi.rocErasedCallableAllocate(roc_host, verifyStateCallable, null, 0) orelse return error.OutOfMemory;
        errdefer abi.decrefErasedCallable(self.second_false_callable, roc_host);
        self.second_true_callable = abi.rocErasedCallableAllocate(roc_host, verifyStateCallable, null, 0) orelse return error.OutOfMemory;
        errdefer abi.decrefErasedCallable(self.second_true_callable, roc_host);
        self.first_false_transform = abi.rocErasedCallableAllocate(roc_host, verifyStateCallable, null, 0) orelse return error.OutOfMemory;
        errdefer abi.decrefErasedCallable(self.first_false_transform, roc_host);
        self.first_true_transform = abi.rocErasedCallableAllocate(roc_host, verifyStateCallable, null, 0) orelse return error.OutOfMemory;
        errdefer abi.decrefErasedCallable(self.first_true_transform, roc_host);
        self.second_false_transform = abi.rocErasedCallableAllocate(roc_host, verifyStateCallable, null, 0) orelse return error.OutOfMemory;
        errdefer abi.decrefErasedCallable(self.second_false_transform, roc_host);
        self.second_true_transform = abi.rocErasedCallableAllocate(roc_host, verifyStateCallable, null, 0) orelse return error.OutOfMemory;
        errdefer abi.decrefErasedCallable(self.second_true_transform, roc_host);
        self.bool_callable = abi.rocErasedCallableAllocate(roc_host, verifyBoolCallable, null, 0) orelse return error.OutOfMemory;
        errdefer abi.decrefErasedCallable(self.bool_callable, roc_host);
        self.text_callable = abi.rocErasedCallableAllocate(roc_host, verifyTextCallable, null, 0) orelse return error.OutOfMemory;
        errdefer abi.decrefErasedCallable(self.text_callable, roc_host);
        self.first_false = self.signalBranch("first-new", self.first_false_callable, self.first_false_transform);
        self.first_true = self.signalBranch("first-old", self.first_true_callable, self.first_true_transform);
        self.second_false = self.signalBranch("second-new", self.second_false_callable, self.second_false_transform);
        self.second_true = self.signalBranch("second-old", self.second_true_callable, self.second_true_transform);
        const condition_capability = HostValueCapability{ .clone = self.value_callable, .drop = self.value_callable, .eq = self.value_callable };
        const condition = abi.NodeSignalExpr{ .payload = .{ .const_value = .{ ._0 = self.value_callable, ._1 = self.value_callable, ._2 = condition_capability } }, .tag = .ConstValue };
        self.first_condition = boxOwnedVerifySignalExpr(roc_host, condition);
        var nested_box: ?*abi.Elem = null;
        defer if (nested_box) |boxed| decrefOwnedVerifyElemBox(boxed, roc_host);
        const first_true = if (nested) blk: {
            abi.increfBox(@ptrCast(self.first_condition), 1);
            const inner_when = abi.Elem{ .payload = .{ .when = .{ .condition = self.first_condition, .ops = borrowedVerifyWhenOps(roc_host, condition_capability, self.first_true.*, self.second_false.*) } }, .tag = .When };
            nested_box = boxOwnedVerifyElem(roc_host, inner_when);
            break :blk nested_box.?;
        } else self.first_true;
        abi.increfBox(@ptrCast(self.first_condition), 2);
        const first_when = abi.Elem{ .payload = .{ .when = .{ .condition = self.first_condition, .ops = borrowedVerifyWhenOps(roc_host, condition_capability, first_true.*, self.first_false.*) } }, .tag = .When };
        const second_when = abi.Elem{ .payload = .{ .when = .{ .condition = self.first_condition, .ops = borrowedVerifyWhenOps(roc_host, condition_capability, self.second_true.*, self.second_false.*) } }, .tag = .When };
        var separator = verifyStaticText();
        separator.payload.text = abi.RocStr.fromSlice("separator", roc_host);
        self.root = if (nested)
            ownedVerifyStaticRoot(roc_host, &.{}, &.{first_when})
        else
            ownedVerifyStaticRoot(roc_host, &.{}, &.{ first_when, separator, second_when });
        first_when.decref(roc_host);
        second_when.decref(roc_host);
        decrefOwnedVerifySignalExprBox(self.first_condition, roc_host);
        decrefOwnedVerifyElemBox(self.first_false, roc_host);
        decrefOwnedVerifyElemBox(self.first_true, roc_host);
        decrefOwnedVerifyElemBox(self.second_false, roc_host);
        decrefOwnedVerifyElemBox(self.second_true, roc_host);
        return self;
    }

    fn init(allocator: std.mem.Allocator, roc_host: *abi.RocHost) !*@This() {
        return initWithShape(allocator, roc_host, false);
    }

    fn initNested(allocator: std.mem.Allocator, roc_host: *abi.RocHost) !*@This() {
        return initWithShape(allocator, roc_host, true);
    }

    fn deinit(self: *@This()) void {
        self.root.decref(self.roc_host);
        abi.decrefErasedCallable(self.text_callable, self.roc_host);
        abi.decrefErasedCallable(self.bool_callable, self.roc_host);
        abi.decrefErasedCallable(self.second_true_transform, self.roc_host);
        abi.decrefErasedCallable(self.second_false_transform, self.roc_host);
        abi.decrefErasedCallable(self.first_true_transform, self.roc_host);
        abi.decrefErasedCallable(self.first_false_transform, self.roc_host);
        abi.decrefErasedCallable(self.second_true_callable, self.roc_host);
        abi.decrefErasedCallable(self.second_false_callable, self.roc_host);
        abi.decrefErasedCallable(self.first_true_callable, self.roc_host);
        abi.decrefErasedCallable(self.first_false_callable, self.roc_host);
        abi.decrefErasedCallable(self.value_callable, self.roc_host);
        self.allocator.destroy(self);
    }
};

fn verifyStaticText() abi.Elem {
    return .{ .payload = .{ .text = abi.RocStr.fromSlice("hello", undefined) }, .tag = .Text };
}

test "owned retained element fixture keeps nested Roc lists alive" {
    var env = abi.RocEnv{ .allocator = std.testing.allocator, .roc_io = abi.RocIo.default() };
    var roc_host = abi.makeRocHost(&env);
    const attr = abi.NodeAttr{ .payload = .{ .static_bool = .{
        .field = .{ .id = @intFromEnum(RenderBoolField.disabled) },
        .name = abi.RocStr.empty(),
        .value = true,
    } }, .tag = .StaticBool };
    const child = verifyStaticText();
    const elem = ownedVerifyStaticRoot(&roc_host, &.{attr}, &.{child});
    elem.incref(1);
    elem.decref(&roc_host);
    try std.testing.expectEqual(@as(usize, 1), elem.payload_element().attrs.items().len);
    try std.testing.expectEqual(@as(usize, 1), elem.payload_element().children.items().len);
    try std.testing.expect(elem.payload_element().attrs.items()[0].payload_static_bool().value);
    elem.decref(&roc_host);
}

test "combined replacement owner assigns distinct identities across two each sites and sweeps OOM" {
    const FaultAllocator = @import("fault_allocator.zig").FaultAllocator;
    const Runner = struct {
        fn run(roc_host: *abi.RocHost, failure_number: ?usize) !usize {
            var fault = FaultAllocator.init(std.testing.allocator);
            var ctx = VerifyCtxHost{ .allocator = fault.allocator() };
            var engine = Engine(VerifyCtx).init();
            defer deinitVerifyStateEngine(&engine, &ctx, roc_host);
            _ = try engine.internRootScope(ctx.allocator);
            const first_elem = abi.Elem{ .payload = .{ .text = abi.RocStr.fromSlice("first combined replacement row with retained text", roc_host) }, .tag = .Text };
            defer first_elem.decref(roc_host);
            const second_elem = abi.Elem{ .payload = .{ .text = abi.RocStr.fromSlice("second combined replacement row with retained text", roc_host) }, .tag = .Text };
            defer second_elem.decref(roc_host);
            const when_elem = abi.Elem{ .payload = .{ .text = abi.RocStr.fromSlice("combined replacement when branch with retained text", roc_host) }, .tag = .Text };
            defer when_elem.decref(roc_host);
            const counts = try Engine(VerifyCtx).PreparedReplacementOwner.countRoots(&.{ first_elem, second_elem, when_elem });
            const each = HostNodeEachDesc{ .node_id = ids.NodeId.fromRaw(0), .items = undefined, .ops = std.mem.zeroes(HostEachOps) };
            const first_site = HostNodeScopeSiteDesc{ .node_id = ids.NodeId.fromRaw(10), .scope_id = ids.ScopeId.fromRaw(0), .ordinal = ids.SiteOrdinal.fromRaw(10), .parent_elem_id = ids.ElemId.fromRaw(0), .render_insert_index = 0, .kind = .each, .binder_bindings = &.{} };
            const second_site = HostNodeScopeSiteDesc{ .node_id = ids.NodeId.fromRaw(20), .scope_id = ids.ScopeId.fromRaw(0), .ordinal = ids.SiteOrdinal.fromRaw(20), .parent_elem_id = ids.ElemId.fromRaw(0), .render_insert_index = 0, .kind = .each, .binder_bindings = &.{} };

            fault.configure(failure_number);
            const owner = Engine(VerifyCtx).PreparedReplacementOwner.create(&engine, &ctx, roc_host, .{}, counts, 3) catch |err| {
                try std.testing.expectEqual(error.OutOfMemory, err);
                return fault.attempts;
            };
            defer owner.deinit();
            owner.attachExternalScopeIds(&.{ 1, 2 }) catch |err| {
                try std.testing.expectEqual(error.OutOfMemory, err);
                return fault.attempts;
            };
            _ = owner.collectEachRow(first_site, each, first_elem, ids.ScopeId.fromRaw(1), true, &.{}) catch |err| {
                try std.testing.expectEqual(error.OutOfMemory, err);
                return fault.attempts;
            };
            _ = owner.collectEachRow(second_site, each, second_elem, ids.ScopeId.fromRaw(2), true, &.{}) catch |err| {
                try std.testing.expectEqual(error.OutOfMemory, err);
                return fault.attempts;
            };
            const branch_scope_id = owner.collectWhenSelection(.{
                .node_id = ids.NodeId.fromRaw(30),
                .parent_scope_id = ids.root_scope,
                .site_ordinal = ids.SiteOrdinal.fromRaw(30),
                .parent_elem_id = ids.root_elem,
                .retired_scope_id = ids.root_scope,
                .render_insert_index = 0,
                .binder_bindings = &.{},
                .branch = .true_branch,
                .elem = when_elem,
            }, &.{}) catch |err| {
                try std.testing.expectEqual(error.OutOfMemory, err);
                return fault.attempts;
            };
            owner.materialize();
            try std.testing.expect(failure_number == null);
            try std.testing.expectEqual(@as(u64, 3), branch_scope_id);
            try std.testing.expectEqual(@as(usize, 3), owner.stream.text_nodes.items.len);
            try std.testing.expectEqual(@as(u64, 1), owner.stream.text_nodes.items[0].scope_id.raw());
            try std.testing.expectEqual(@as(u64, 2), owner.stream.text_nodes.items[1].scope_id.raw());
            try std.testing.expectEqual(@as(u64, 3), owner.stream.text_nodes.items[2].scope_id.raw());
            try std.testing.expect(owner.stream.text_nodes.items[0].elem_id != owner.stream.text_nodes.items[1].elem_id);
            try std.testing.expect(owner.stream.text_nodes.items[1].elem_id != owner.stream.text_nodes.items[2].elem_id);
            try std.testing.expectEqual(@as(usize, 1), engine.scopes.items.len);
            try std.testing.expectEqual(@as(usize, 0), engine.dom_identities.items.len);
            return fault.attempts;
        }
    };

    var env = abi.RocEnv{ .allocator = std.testing.allocator, .roc_io = abi.RocIo.default() };
    var roc_host = abi.makeRocHost(&env);
    const attempts = try Runner.run(&roc_host, null);
    try std.testing.expect(attempts != 0);
    for (1..attempts + 1) |failure_number| _ = try Runner.run(&roc_host, failure_number);
}

test "final render placements preserve two disjoint intervals under one parent" {
    const FaultAllocator = @import("fault_allocator.zig").FaultAllocator;
    var env = abi.RocEnv{ .allocator = std.testing.allocator, .roc_io = abi.RocIo.default() };
    var roc_host = abi.makeRocHost(&env);

    const Runner = struct {
        fn run(host: *abi.RocHost, fail_at: ?usize) !usize {
            var fault = FaultAllocator.init(std.testing.allocator);
            var ctx = VerifyCtxHost{ .allocator = fault.allocator() };
            var engine = Engine(VerifyCtx).init();
            defer {
                engine.active_stream.deinit(ctx.allocator, &ctx, host, &engine.pending_roc_metrics);
                deinitVerifyStateEngine(&engine, &ctx, host);
            }
            for (0..5) |_| _ = try engine.internRootScope(ctx.allocator);
            engine.active_stream.appendTextNode(ctx.allocator, ids.ElemId.fromRaw(1), ids.root_elem, ids.root_scope, "a");
            engine.active_stream.appendTextNode(ctx.allocator, ids.ElemId.fromRaw(2), ids.root_elem, ids.ScopeId.fromRaw(1), "old-left");
            engine.active_stream.appendTextNode(ctx.allocator, ids.ElemId.fromRaw(3), ids.root_elem, ids.root_scope, "middle");
            engine.active_stream.appendTextNode(ctx.allocator, ids.ElemId.fromRaw(4), ids.root_elem, ids.ScopeId.fromRaw(2), "old-right");
            engine.active_stream.appendTextNode(ctx.allocator, ids.ElemId.fromRaw(5), ids.root_elem, ids.root_scope, "z");
            const replacement = try Engine(VerifyCtx).PreparedReplacementOwner.create(&engine, &ctx, host, .{}, .{}, 0);
            defer replacement.deinit();
            replacement.stream.appendTextNode(ctx.allocator, ids.ElemId.fromRaw(6), ids.root_elem, ids.ScopeId.fromRaw(3), "new-left");
            replacement.stream.appendTextNode(ctx.allocator, ids.ElemId.fromRaw(7), ids.root_elem, ids.ScopeId.fromRaw(4), "new-right");
            const before = try ctx.allocator.dupe(HostRenderNode, engine.active_stream.render_nodes.items);
            defer ctx.allocator.free(before);
            const targets = [_]bool{ false, true, true, false, false };
            const Placement = Engine(VerifyCtx).PreparedFinalRenderTopology.Placement;
            const placements = [_]Placement{
                Engine(VerifyCtx).PreparedFinalRenderTopology.Placement.replacement(.{ .value = 0 }, .{ .value = 1 }, 1),
                Engine(VerifyCtx).PreparedFinalRenderTopology.Placement.replacement(.{ .value = 1 }, .{ .value = 3 }, 1),
            };
            fault.configure(fail_at);
            var topology = Engine(VerifyCtx).PreparedFinalRenderTopology.preparePlaced(&engine, ctx.allocator, replacement, &targets, 2, &placements) catch |err| {
                try std.testing.expectEqual(error.OutOfMemory, err);
                try std.testing.expectEqualDeep(before, engine.active_stream.render_nodes.items);
                return fault.attempts;
            };
            const attempts = fault.attempts;
            fault.configure(null);
            defer topology.deinit();
            const expected = [_]u64{ 1, 6, 3, 7, 5 };
            for (topology.render_nodes.items, expected) |node, elem_id| try std.testing.expectEqual(elem_id, node.elem_id.raw());
            try std.testing.expectEqualDeep(before, engine.active_stream.render_nodes.items);
            return attempts;
        }
    };

    const attempts = try Runner.run(&roc_host, null);
    for (1..attempts + 1) |fail_at| _ = try Runner.run(&roc_host, fail_at);
}

test "owned aggregate graph root ingests two signal branches around a survivor" {
    var roc_env = abi.RocEnv{ .allocator = std.testing.allocator, .roc_io = abi.RocIo.default() };
    var roc_host = abi.makeRocHost(&roc_env);
    const fixture = try OwnedAggregateGraphRoot.init(std.testing.allocator, &roc_host);
    defer fixture.deinit();
    try std.testing.expectEqual(fixture.first_condition.payload_const_value()._0, fixture.first_condition.payload_const_value()._1);
    _ = abi_view.SignalExpr.fromAbi(fixture.first_condition.*);
    var ctx = VerifyCtxHost{ .allocator = std.testing.allocator };
    var engine = Engine(VerifyCtx).init();
    var stream: HostNodeDescriptorStream = .{};
    defer {
        stream.deinit(ctx.allocator, &ctx, &roc_host, &engine.pending_roc_metrics);
        deinitVerifyStateEngine(&engine, &ctx, &roc_host);
    }

    const expected = try Engine(VerifyCtx).countStaticRootNodes(fixture.root);
    try std.testing.expectEqual(@as(usize, 2), expected.signal_records);
    try engine.collectStaticRootDescriptorsTransactional(&ctx, &roc_host, &stream, fixture.root, .{});
    try std.testing.expectEqual(@as(usize, 2), stream.whens.items.len);
    try std.testing.expectEqual(@as(usize, 2), stream.signal_text_nodes.items.len);
    try std.testing.expectEqual(@as(usize, 5), stream.text_nodes.items.len + stream.signal_text_nodes.items.len);
    try std.testing.expect(stream.whens.items[0].node_id.raw() < stream.whens.items[1].node_id.raw());
    const separator = for (stream.text_nodes.items) |desc| {
        if (std.mem.eql(u8, desc.value, "separator")) break desc;
    } else return error.TestUnexpectedResult;
    const separator_index = stream.renderNodeIndex(separator.elem_id).?;
    var signals_before: usize = 0;
    var signals_after: usize = 0;
    for (stream.signal_text_nodes.items) |desc| {
        const index = stream.renderNodeIndex(desc.elem_id).?;
        if (index < separator_index) signals_before += 1 else signals_after += 1;
    }
    try std.testing.expectEqual(@as(usize, 1), signals_before);
    try std.testing.expectEqual(@as(usize, 1), signals_after);
}

fn verifyErasedCallable(_: *abi.RocHost, _: ?[*]u8, _: ?[*]const u8, _: ?[*]u8, _: ?[*]u8, _: *?*const anyopaque) callconv(.c) void {}

var verifyStateInitCalls: usize = 0;

fn verifyStateCallable(_: *abi.RocHost, result: ?[*]u8, _: ?[*]const u8, _: ?[*]u8, _: ?[*]u8, _: *?*const anyopaque) callconv(.c) void {
    if (result) |bytes| {
        const value: *HostValue = @ptrCast(@alignCast(bytes));
        value.* = HostValue.fromRaw(42);
        verifyStateInitCalls += 1;
    }
}

fn verifyBoolCallable(_: *abi.RocHost, result: ?[*]u8, _: ?[*]const u8, _: ?[*]u8, _: ?[*]u8, _: *?*const anyopaque) callconv(.c) void {
    if (result) |bytes| bytes[0] = 1;
}

const VerifyWhenCapture = extern struct { when_false: abi.Elem, when_true: abi.Elem };

fn verifyWhenElemCallable(_: *abi.RocHost, result: ?[*]u8, args: ?[*]const u8, capture_ptr: ?[*]u8, _: ?[*]u8, _: *?*const anyopaque) callconv(.c) void {
    const input: *align(1) const erased_calls.ErasedHostValueUnaryArgs = @ptrCast(args.?);
    const capture: *VerifyWhenCapture = @ptrCast(@alignCast(capture_ptr.?));
    const selected = if (input.arg0 == 42) capture.when_true else capture.when_false;
    selected.incref(1);
    const out: *align(1) abi.Elem = @ptrCast(result.?);
    out.* = selected;
}

fn verifyWhenElemOnDrop(capture_ptr: ?[*]u8, roc_host: *abi.RocHost) callconv(.c) void {
    const capture: *VerifyWhenCapture = @ptrCast(@alignCast(capture_ptr.?));
    capture.when_false.decref(roc_host);
    capture.when_true.decref(roc_host);
}

fn ownedVerifyWhenOps(roc_host: *abi.RocHost, capability: HostValueCapability, when_true: abi.Elem, when_false: abi.Elem) HostWhenOps {
    const build = abi.rocErasedCallableAllocate(roc_host, verifyWhenElemCallable, verifyWhenElemOnDrop, @sizeOf(VerifyWhenCapture)) orelse @panic("out of memory");
    const capture: *VerifyWhenCapture = @ptrCast(@alignCast(abi.rocErasedCallableCapturePtr(build)));
    capture.* = .{ .when_false = when_false, .when_true = when_true };
    var metrics = zeroRuntimeMetrics();
    return .{ .build = build, .case_capability = retainHostValueCapability(capability, &metrics) };
}

fn borrowedVerifyWhenOps(roc_host: *abi.RocHost, capability: HostValueCapability, when_true: abi.Elem, when_false: abi.Elem) HostWhenOps {
    when_true.incref(1);
    when_false.incref(1);
    return ownedVerifyWhenOps(roc_host, capability, when_true, when_false);
}

fn verifyHostValueEqCallable(_: *abi.RocHost, result: ?[*]u8, args: ?[*]const u8, _: ?[*]u8, _: ?[*]u8, _: *?*const anyopaque) callconv(.c) void {
    const input: *const erased_calls.ErasedHostValueBinaryArgs = @ptrCast(@alignCast(args.?));
    result.?[0] = @intFromBool(input.arg0 == input.arg1);
}

var verifyTextReadCalls: usize = 0;

fn verifyTextCallable(roc_host: *abi.RocHost, result: ?[*]u8, _: ?[*]const u8, _: ?[*]u8, _: ?[*]u8, _: *?*const anyopaque) callconv(.c) void {
    verifyTextReadCalls += 1;
    if (result) |bytes| {
        const text: *abi.RocStr = @ptrCast(@alignCast(bytes));
        text.* = abi.RocStr.fromSlice("signal", roc_host);
    }
}

fn deinitVerifyStaticEngine(engine: *Engine(VerifyCtx), ctx: *VerifyCtxHost) void {
    engine.clearEachRowSites(ctx.allocator);
    engine.committed_row_bindings.deinit(ctx.allocator);
    engine.row_handle_registry.deinit(ctx.allocator);
    engine.scopes.deinit(std.testing.allocator);
    engine.dom_identities.deinit(std.testing.allocator);
    engine.active_dom_identity_ids.deinit(std.testing.allocator);
    engine.deinitScratch(ctx);
}

fn deinitVerifyStateEngine(engine: *Engine(VerifyCtx), ctx: *VerifyCtxHost, roc_host: *abi.RocHost) void {
    effects_runtime.deinitCleanupEvents(ctx.allocator, &engine.cleanup_events);
    for (engine.states.items) |*state| if (state.isActive()) state.retire(ctx, roc_host, &engine.pending_roc_metrics);
    engine.states.deinit(ctx.allocator);
    engine.state_indexes_by_node_id.deinit(ctx.allocator);
    engine.node_identities.deinit(ctx.allocator);
    engine.active_node_identity_ids.deinit(ctx.allocator);
    for (engine.scopes.items) |*scope| if (scope.lifecycle.isActive()) deinitHostScopeStep(&scope.step);
    deinitVerifyStaticEngine(engine, ctx);
}

test "state command targets resolve the nearest live ancestor among unrelated scoped aliases" {
    const allocator = std.testing.allocator;
    for ([_]usize{ 100, 1000 }) |unrelated_count| {
        var env = abi.RocEnv{ .allocator = allocator, .roc_io = abi.RocIo.default() };
        var roc_host = abi.makeRocHost(&env);
        const callable = abi.rocErasedCallableAllocate(&roc_host, verifyErasedCallable, null, 0).?;
        defer abi.decrefErasedCallable(callable, &roc_host);
        const cap = HostValueCapability{ .clone = callable, .drop = callable, .eq = callable };
        var ctx = VerifyCtxHost{ .allocator = allocator };
        var engine = Engine(VerifyCtx).init();
        defer engine.scopes.deinit(allocator);
        defer engine.active_stream.deinit(allocator, &ctx, &roc_host, &engine.pending_roc_metrics);
        const root = (try scope_tree.internRoot(HostEachRowScopeStep, allocator, &engine.scopes)).scope_id;
        const child = try scope_tree.internComponent(HostEachRowScopeStep, allocator, &engine.scopes, root, ids.SiteOrdinal.fromRaw(0), ids.Generation.fromRaw(0));
        const sibling = try scope_tree.internComponent(HostEachRowScopeStep, allocator, &engine.scopes, root, ids.SiteOrdinal.fromRaw(1), ids.Generation.fromRaw(0));
        const nested = try scope_tree.internComponent(HostEachRowScopeStep, allocator, &engine.scopes, child.scope_id, ids.SiteOrdinal.fromRaw(0), ids.Generation.fromRaw(0));
        const owners = [_]ids.ScopeId{ root, child.scope_id, sibling.scope_id };
        try engine.active_stream.reservePreparedStateSites(allocator, unrelated_count + owners.len, @intCast(unrelated_count + owners.len));
        for (owners, 0..) |scope, i| {
            try engine.active_stream.reserveScopeDescriptorOwnership(allocator, scope, 0, if (scope == sibling.scope_id) unrelated_count + 1 else 1);
            const node = ids.NodeId.fromIndex(i);
            const site = try engine.active_stream.prepareScopeSite(allocator, node, scope, ids.SiteOrdinal.fromRaw(0), ids.ElemId.fromRaw(0), .state, &.{});
            const state = engine.active_stream.prepareState(node, .fromAbi(callable), cap, &engine.pending_roc_metrics);
            engine.active_stream.appendPreparedStateSite(site, state);
        }
        for (0..unrelated_count) |i| {
            const node = ids.NodeId.fromIndex(i + owners.len);
            const site = try engine.active_stream.prepareScopeSite(allocator, node, sibling.scope_id, ids.SiteOrdinal.fromIndex(i + 1), ids.ElemId.fromRaw(0), .state, &.{});
            const state = engine.active_stream.prepareState(node, .fromAbi(callable), cap, &engine.pending_roc_metrics);
            engine.active_stream.appendPreparedStateSite(site, state);
        }
        const token = retained_values.hostSignalTokenFromCallable(callable);
        try std.testing.expectEqual(ids.NodeId.fromRaw(0), engine.resolveStateCommandTarget(root, token));
        try std.testing.expectEqual(ids.NodeId.fromRaw(1), engine.resolveStateCommandTarget(child.scope_id, token));
        try std.testing.expectEqual(ids.NodeId.fromRaw(1), engine.resolveStateCommandTarget(nested.scope_id, token));
        try std.testing.expectEqual(ids.NodeId.fromRaw(2), engine.resolveStateCommandTarget(sibling.scope_id, token));
    }
}

test "provisional each-row scopes abort and publish without partial scope mutation" {
    const FaultAllocator = @import("fault_allocator.zig").FaultAllocator;
    var env = abi.RocEnv{ .allocator = std.testing.allocator, .roc_io = abi.RocIo.default() };
    var roc_host = abi.makeRocHost(&env);
    const callable = abi.rocErasedCallableAllocate(&roc_host, verifyErasedCallable, null, 0).?;
    defer abi.decrefErasedCallable(callable, &roc_host);
    const capability = HostValueCapability{ .clone = callable, .drop = callable, .eq = callable };

    const Runner = struct {
        fn run(host: *abi.RocHost, cap: HostValueCapability, fail_at: ?usize) !usize {
            var fault = FaultAllocator.init(std.testing.allocator);
            var ctx = VerifyCtxHost{ .allocator = fault.allocator() };
            var engine = Engine(VerifyCtx).init();
            defer deinitVerifyStateEngine(&engine, &ctx, host);
            _ = try engine.internRootScope(ctx.allocator);
            fault.configure(fail_at);
            var overlay = scope_runtime.PreparedEachRowScopes.init(ctx.allocator, engine.scopes.items, ids.Generation.fromRaw(engine.identity_reuse_barrier));
            defer overlay.deinit();

            _ = cap;
            const first = overlay.prepareRow(&engine.scopes, ids.ScopeId.fromRaw(0), ids.SiteOrdinal.fromRaw(9), 101, row_handles.RowHandleId.fromRaw(0x0000_0001_0000_0001));
            if (first) |first_id| {
                const second = overlay.prepareRow(&engine.scopes, ids.ScopeId.fromRaw(0), ids.SiteOrdinal.fromRaw(9), 202, row_handles.RowHandleId.fromRaw(0x0000_0001_0000_0002));
                if (second) |second_id| {
                    try std.testing.expectEqual(@as(u64, 1), first_id.raw());
                    try std.testing.expectEqual(@as(u64, 2), second_id.raw());
                    try std.testing.expectEqual(@as(usize, 1), engine.scopes.items.len);
                    const attempts = fault.attempts;
                    fault.configure(1);
                    overlay.commit(&engine.scopes);
                    try std.testing.expectEqual(@as(usize, 0), fault.attempts);
                    try std.testing.expectEqual(@as(usize, 3), engine.scopes.items.len);
                    try std.testing.expectEqual(@as(u64, 101), scope_runtime.eachRowConst(engine.scopes.items, first_id).key_hash);
                    try std.testing.expectEqual(@as(u64, 202), scope_runtime.eachRowConst(engine.scopes.items, second_id).key_hash);
                    return attempts;
                } else |err| {
                    try std.testing.expectEqual(error.OutOfMemory, err);
                }
            } else |err| {
                try std.testing.expectEqual(error.OutOfMemory, err);
            }
            try std.testing.expectEqual(@as(usize, 1), engine.scopes.items.len);
            overlay.abort();
            try std.testing.expectEqual(@as(usize, 1), engine.scopes.items.len);

            fault.configure(null);
            const retry_first = try overlay.prepareRow(&engine.scopes, ids.ScopeId.fromRaw(0), ids.SiteOrdinal.fromRaw(9), 101, row_handles.RowHandleId.fromRaw(0x0000_0001_0000_0001));
            const retry_second = try overlay.prepareRow(&engine.scopes, ids.ScopeId.fromRaw(0), ids.SiteOrdinal.fromRaw(9), 202, row_handles.RowHandleId.fromRaw(0x0000_0001_0000_0002));
            try std.testing.expectEqual(@as(u64, 1), retry_first.raw());
            try std.testing.expectEqual(@as(u64, 2), retry_second.raw());
            overlay.commit(&engine.scopes);
            try std.testing.expectEqual(@as(usize, 3), engine.scopes.items.len);
            return fault.attempts;
        }
    };

    const attempts = try Runner.run(&roc_host, capability, null);
    var failures: usize = 0;
    for (1..attempts + 1) |fail_at| {
        _ = try Runner.run(&roc_host, capability, fail_at);
        failures += 1;
    }
    try std.testing.expectEqual(attempts, failures);
}

