    var counter_ctx = VerifyCtxHost{ .allocator = counter.allocator() };
    var counter_engine = Engine(VerifyCtx).init();
    verifyStateInitCalls = 0;
    const counted = try Engine(VerifyCtx).PreparedRootCollection.prepare(&counter_engine, &counter_ctx, &roc_host, root, .{}, &.{});
    const attempts = counter.attempts;
    try std.testing.expectEqual(@as(usize, 1), verifyStateInitCalls);
    try std.testing.expectEqual(@as(usize, 0), counter_engine.scopes.items.len);
    try std.testing.expectEqual(@as(usize, 0), counter_engine.node_identities.items.len);
    try std.testing.expectEqual(@as(usize, 0), counter_engine.states.items.len);
    try std.testing.expectEqual(@as(usize, 1), counted.descriptorStream().elements.items.len);
    try std.testing.expectEqual(@as(usize, 1), counted.descriptorStream().events.items.len);
    counted.deinit();
    deinitVerifyStateEngine(&counter_engine, &counter_ctx, &roc_host);
    try std.testing.expect(attempts != 0);

    for (1..attempts + 1) |failure_number| {
        var fault = FaultAllocator.init(std.testing.allocator);
        fault.configure(failure_number);
        var ctx = VerifyCtxHost{ .allocator = fault.allocator() };
        var engine = Engine(VerifyCtx).init();
        defer deinitVerifyStateEngine(&engine, &ctx, &roc_host);
        verifyStateInitCalls = 0;

        try std.testing.expectError(error.OutOfMemory, Engine(VerifyCtx).PreparedRootCollection.prepare(&engine, &ctx, &roc_host, root, .{}, &.{}));
        try std.testing.expectEqual(@as(usize, 0), engine.scopes.items.len);
        try std.testing.expectEqual(@as(usize, 0), engine.node_identities.items.len);
        try std.testing.expectEqual(@as(usize, 0), engine.dom_identities.items.len);
        try std.testing.expectEqual(@as(usize, 0), engine.states.items.len);
        try std.testing.expectEqual(@as(usize, 0), engine.active_stream.elements.items.len);
        try std.testing.expectEqual(engine.pending_roc_metrics.closure_retains, engine.pending_roc_metrics.closure_releases);
        const calls_before_retry = verifyStateInitCalls;

        fault.configure(null);
        const retry = try Engine(VerifyCtx).PreparedRootCollection.prepare(&engine, &ctx, &roc_host, root, .{}, &.{});
        try std.testing.expectEqual(calls_before_retry + 1, verifyStateInitCalls);
        try std.testing.expectEqual(@as(usize, 0), engine.scopes.items.len);
        try std.testing.expectEqual(@as(usize, 0), engine.node_identities.items.len);
        try std.testing.expectEqual(@as(usize, 0), engine.states.items.len);
        try std.testing.expectEqualStrings("div", retry.descriptorStream().elements.items[0].tag);
        try std.testing.expectEqualStrings("keydown", retry.descriptorStream().events.items[0].named().?.name);

        var committed_stream = retry.commit();
        defer committed_stream.deinit(ctx.allocator, &ctx, &roc_host, &engine.pending_roc_metrics);
        try std.testing.expectEqual(@as(usize, 2), engine.scopes.items.len);
        try std.testing.expectEqual(@as(usize, 2), engine.node_identities.items.len);
        try std.testing.expectEqual(@as(usize, 1), engine.states.items.len);
        try std.testing.expectEqual(HostValue.fromRaw(42), engine.states.items[0].activePayloadConst().cell.value);
        try std.testing.expectEqual(@as(usize, 1), committed_stream.events.items.len);
    }
}

test "prepared initial root downstream sweeps failures and commits allocation free" {
    const FaultAllocator = @import("fault_allocator.zig").FaultAllocator;
    var roc_env = abi.RocEnv{ .allocator = std.testing.allocator, .roc_io = abi.RocIo.default() };
    var roc_host = abi.makeRocHost(&roc_env);
    const callable = abi.rocErasedCallableAllocate(&roc_host, verifyStateCallable, null, 0).?;
    defer abi.decrefErasedCallable(callable, &roc_host);
    const text_callable = abi.rocErasedCallableAllocate(&roc_host, verifyTextCallable, null, 0).?;
    defer abi.decrefErasedCallable(text_callable, &roc_host);
    const capability = HostValueCapability{ .clone = callable, .drop = callable, .eq = callable };
    var signal_expr = abi.NodeSignalExpr{ .payload = .{ .const_value = .{
        ._0 = callable,
        ._1 = callable,
        ._2 = capability,
    } }, .tag = .ConstValue };
    const extraction_bytes = EventExtractionPlanKind.none.bytes();
    const event = abi.NodeAttr{ .payload = .{ .on = .{
        .kind = .{ .id = 0 },
        .msg = .{
            .event_extraction_plan = .{ .bytes = .{ .elements_ptr = @constCast(extraction_bytes.ptr), .length = extraction_bytes.len, .capacity_or_alloc_ptr = extraction_bytes.len << 1 } },
            .handler = .{ .payload = .{ .reduce = .{
                .binder = callable,
                .read_binder = callable,
                .payload_reducer = std.mem.zeroes(HostEventReducer),
            } }, .tag = .Reduce },
        },
        .name = abi.RocStr.fromSlice("keydown", undefined),
        .delivery = .{ .native = false },
        .policy = std.mem.zeroes(abi.NodeEventBindingPolicy),
        .key_chord = std.mem.zeroes(@FieldType(abi.NodeEventBinding, "key_chord")),
    } }, .tag = .On };
    const signal_attr = abi.NodeAttr{ .payload = .{ .signal_text = .{
        .field = .{ .id = @intFromEnum(RenderTextField.value) },
        .name = abi.RocStr.empty(),
        .read = .{ .capability = capability, .read = text_callable },
        .signal = &signal_expr,
    } }, .tag = .SignalText };
    var child = verifyStaticRoot(&.{ event, signal_attr }, &.{verifyStaticText()});
    var state = abi.Elem{ .payload = .{ .state = .{
        .binder = callable,
        .cap = capability,
        .child = &child,
        .initial = callable,
    } }, .tag = .State };
    const root = abi.Elem{ .payload = .{ .component = .{ .child = &state } }, .tag = .Component };

    const Runner = struct {
        fn prepare(engine: *Engine(VerifyCtx), ctx: *VerifyCtxHost, host: *abi.RocHost, elem: abi.Elem) !*Engine(VerifyCtx).PreparedRootDownstream {
            const collection = try Engine(VerifyCtx).PreparedRootCollection.prepare(engine, ctx, host, elem, .{}, &.{});
            errdefer collection.deinit();
            return Engine(VerifyCtx).PreparedRootDownstream.prepare(collection);
        }

        fn deinitEngine(engine: *Engine(VerifyCtx), ctx: *VerifyCtxHost, host: *abi.RocHost) void {
            if (engine.active_signal_graph.items.len != 0) {
                engine.clearActiveSignalRoutes(ctx);
                engine.clearActiveSignalGraph(ctx);
            }
            engine.active_stream.deinit(ctx.allocator, ctx, host, &engine.pending_roc_metrics);
            engine.active_events.deinit(ctx.allocator);
            engine.active_signal_graph.deinit(ctx.allocator);
            engine.active_source_signal_routes.deinit(ctx.allocator);
            engine.active_text_signal_routes.deinit(ctx.allocator);
            engine.active_bool_signal_routes.deinit(ctx.allocator);
            engine.active_change_signal_routes.deinit(ctx.allocator);
            engine.active_structural_signal_routes.deinit(ctx.allocator);
            ctx.render_batch.deinit(ctx.allocator);
            engine.deinitRenderCache(ctx);
            deinitVerifyStateEngine(engine, ctx, host);
        }

        fn run(host: *abi.RocHost, elem: abi.Elem, fail_at: ?usize) !usize {
            var fault = FaultAllocator.init(std.testing.allocator);
            fault.configure(fail_at);
            var ctx = VerifyCtxHost{ .allocator = fault.allocator() };
            var engine = Engine(VerifyCtx).init();
            engine.roc_host = host;
            defer deinitEngine(&engine, &ctx, host);

            const prepared = prepare(&engine, &ctx, host, elem) catch |err| {
                try std.testing.expect(fail_at != null);
                try std.testing.expectEqual(error.OutOfMemory, err);
                try std.testing.expectEqual(@as(usize, 0), engine.scopes.items.len);
                try std.testing.expectEqual(@as(usize, 0), engine.node_identities.items.len);
                try std.testing.expectEqual(@as(usize, 0), engine.dom_identities.items.len);
                try std.testing.expectEqual(@as(usize, 0), engine.states.items.len);
                try std.testing.expectEqual(@as(usize, 0), engine.active_stream.render_nodes.items.len);
                try std.testing.expectEqual(@as(usize, 0), engine.active_events.items.len);
                try std.testing.expectEqual(@as(usize, 0), engine.active_signal_graph.items.len);
                try std.testing.expect(!engine.render_cache.hasRoot());
                try std.testing.expectEqual(@as(usize, 0), ctx.render_batch.staged.commands.len());
                try std.testing.expectEqual(@as(usize, 0), ctx.render_batch.published.commands.len());
                try std.testing.expectEqual(engine.pending_roc_metrics.closure_retains, engine.pending_roc_metrics.closure_releases);
                const attempts = fault.attempts;

                fault.configure(null);
                const retry = try prepare(&engine, &ctx, host, elem);
                try std.testing.expectEqual(@as(usize, 0), engine.active_stream.render_nodes.items.len);
                try std.testing.expect(!engine.render_cache.hasRoot());
                fault.configure(1);
                retry.commit();
                try std.testing.expectEqual(@as(usize, 0), fault.attempts);
                try std.testing.expect(engine.render_cache.hasRoot());
                try std.testing.expectEqual(@as(usize, 2), engine.active_stream.render_nodes.items.len);
                try std.testing.expectEqual(@as(usize, 1), engine.active_events.items.len);
                try std.testing.expect(engine.active_signal_graph.items.len != 0);
                try std.testing.expectEqual(@as(usize, 3), engine.render_cache.nodes.items.len);
                ctx.render_batch.publish();
                try std.testing.expectEqual(@as(usize, 0), ctx.render_batch.staged.commands.len());
                try std.testing.expect(ctx.render_batch.published.commands.len() != 0);
                try std.testing.expectEqual(@intFromEnum(render.Op.reset_dom), ctx.render_batch.published.commands.records.items[0].op);
                retry.deinit();
                return attempts;
            };
            try std.testing.expect(fail_at == null);
            const attempts = fault.attempts;
            try std.testing.expectEqual(@as(usize, 0), engine.active_stream.render_nodes.items.len);
            try std.testing.expect(!engine.render_cache.hasRoot());
            fault.configure(1);
            prepared.commit();
            try std.testing.expectEqual(@as(usize, 0), fault.attempts);
            try std.testing.expect(engine.render_cache.hasRoot());
            try std.testing.expectEqual(@as(usize, 2), engine.active_stream.render_nodes.items.len);
            try std.testing.expectEqual(@as(usize, 1), engine.active_events.items.len);
            try std.testing.expect(engine.active_signal_graph.items.len != 0);
            try std.testing.expectEqual(@as(usize, 3), engine.render_cache.nodes.items.len);
            ctx.render_batch.publish();
            try std.testing.expectEqual(@intFromEnum(render.Op.reset_dom), ctx.render_batch.published.commands.records.items[0].op);
            prepared.deinit();
            return attempts;
        }
    };

    const attempts = try Runner.run(&roc_host, root, null);
    try std.testing.expect(attempts != 0);
    for (1..attempts + 1) |fail_at| _ = try Runner.run(&roc_host, root, fail_at);
}

test "staged collection refuses unknown and duplicate scopes as InvalidScope" {
    var ctx = VerifyCtxHost{ .allocator = std.testing.allocator };
    var engine = Engine(VerifyCtx).init();
    defer {
        engine.node_identities.deinit(ctx.allocator);
        engine.active_node_identity_ids.deinit(ctx.allocator);
        engine.state_indexes_by_node_id.deinit(ctx.allocator);
        deinitVerifyStaticEngine(&engine, &ctx);
    }
    _ = try engine.internRootScope(std.testing.allocator);
    var stream: HostNodeDescriptorStream = .{};
    defer stream.deinit(std.testing.allocator, &ctx, undefined, &engine.pending_roc_metrics);

    var collection = try Engine(VerifyCtx).StagedCollectionCtx.init(&engine, &ctx, &stream, .{}, .{ .when_sites = 1 }, 2);
    defer collection.deinit();
    // A scope id the committed tree has never interned is unknown, not a budget.
    try std.testing.expectError(error.InvalidScope, collection.validateScope(ids.ScopeId.fromRaw(7)));
    try collection.attachExternalScopeIds(&.{1});
    try collection.validateScope(ids.ScopeId.fromRaw(1));
    // Claiming the same external scope twice in one transaction is a duplicate.
    try std.testing.expectError(error.InvalidScope, collection.attachExternalScopeIds(&.{1}));
    try std.testing.expectEqual(@as(usize, 1), engine.scopes.items.len);
}

test "structural targets refuse nested retirement roots as OverlappingRemoval" {
    var engine = Engine(VerifyCtx).init();
    defer engine.scopes.deinit(std.testing.allocator);
    const root = try engine.internRootScope(std.testing.allocator);
    const child = try engine.internWhenBranchScope(std.testing.allocator, root.scope_id, ids.SiteOrdinal.fromRaw(10), .false_branch);
    const grandchild = try engine.internWhenBranchScope(std.testing.allocator, child.scope_id, ids.SiteOrdinal.fromRaw(11), .false_branch);

    var disjoint = try Engine(VerifyCtx).PreparedStructuralTargets.prepare(&engine, std.testing.allocator, &.{root.scope_id.raw()}, &.{child.scope_id.raw()}, null);
    disjoint.deinit(std.testing.allocator);
    // Retiring a subtree and one of its own descendants claims the descendant twice.
    try std.testing.expectError(error.OverlappingRemoval, Engine(VerifyCtx).PreparedStructuralTargets.prepare(&engine, std.testing.allocator, &.{root.scope_id.raw()}, &.{ child.scope_id.raw(), grandchild.scope_id.raw() }, null));
    try std.testing.expectEqual(@as(usize, 3), engine.scopes.items.len);
    try std.testing.expect(engine.scopes.items[grandchild.scope_id.index()].lifecycle.isActive());
}

test "structural targets mark ten thousand flat row roots with exact linear subtree work" {
    var engine = Engine(VerifyCtx).init();
    defer engine.scopes.deinit(std.testing.allocator);
    const root = try engine.internRootScope(std.testing.allocator);
    var roots: shared_buffer.List(u64) = .empty;
    defer roots.deinit(std.testing.allocator);
    try roots.ensureTotalCapacity(std.testing.allocator, 10_000);
    for (0..10_000) |index| {
        const row = try scope_runtime.appendFreshEachRow(
            std.testing.allocator,
            &engine.scopes,
            root.scope_id,
            ids.SiteOrdinal.fromRaw(@intCast(index + 1)),
            index,
            row_handles.RowHandleId.fromRaw(@intCast(0x0000_0001_0000_0001 + index)),
        );
        roots.appendAssumeCapacity(row.scope_id.raw());
    }

    var targets = try Engine(VerifyCtx).PreparedStructuralTargets.prepare(&engine, std.testing.allocator, roots.items, roots.items, null);
    defer targets.deinit(std.testing.allocator);
    try std.testing.expect(!targets.descriptor_target_scopes[root.scope_id.index()]);
    for (roots.items) |scope_id| try std.testing.expect(targets.descriptor_target_scopes[@intCast(scope_id)]);
    try std.testing.expectEqual(@as(usize, 10_000), targets.work.subtree_scope_visits);
    try std.testing.expectEqual(@as(usize, 0), targets.work.subtree_child_links_followed);
    try std.testing.expectEqual(@as(usize, 10_000), targets.scope_retirement.?.work.validation_roots_checked);
    try std.testing.expectEqual(@as(usize, 10_000), targets.scope_retirement.?.work.validation_parent_links_followed);
}

fn countDirectRootNestedScan(retirement_scope_ids: []const ids.ScopeId, synced_row_roots: []const ids.ScopeId, nested: *shared_buffer.List(ids.ScopeId)) usize {
    // Reference for the retired quadratic classification: one equality per
    // (retiring scope, root) pair until the first hit.
    var comparisons: usize = 0;
    for (retirement_scope_ids) |scope_id| {
        const is_direct = for (synced_row_roots) |root| {
            comparisons += 1;
            if (root == scope_id) break true;
        } else false;
        if (!is_direct) nested.appendAssumeCapacity(scope_id);
    }
    return comparisons;
}

test "sparse scope retirement classifies flat direct row roots with one probe per scope" {
    const Membership = Engine(VerifyCtx).PreparedStructuralDownstream.DirectRowRootMembership;
    const measure = struct {
        fn run(row_count: usize) !void {
            var engine = Engine(VerifyCtx).init();
            defer engine.scopes.deinit(std.testing.allocator);
            const root = try engine.internRootScope(std.testing.allocator);
            var roots: shared_buffer.List(ids.ScopeId) = .empty;
            defer roots.deinit(std.testing.allocator);
            try roots.ensureTotalCapacity(std.testing.allocator, row_count);
            for (0..row_count) |index| {
                const row = try scope_runtime.appendFreshEachRow(
                    std.testing.allocator,
                    &engine.scopes,
                    root.scope_id,
                    ids.SiteOrdinal.fromRaw(@intCast(index + 1)),
                    index,
                    row_handles.RowHandleId.fromRaw(@intCast(0x0000_0001_0000_0001 + index)),
                );
                roots.appendAssumeCapacity(row.scope_id);
            }
            var retirement = try scope_runtime.prepareSubtreesRetirement(HostEachRowScopeStep, std.testing.allocator, engine.scopes.items, roots.items);
            defer retirement.deinit(std.testing.allocator);
            try std.testing.expectEqual(row_count, retirement.scope_ids.len);

            var nested: shared_buffer.List(ids.ScopeId) = .empty;
            defer nested.deinit(std.testing.allocator);
            try nested.ensureTotalCapacity(std.testing.allocator, retirement.scope_ids.len);
            var membership = try Membership.init(std.testing.allocator, roots.items);
            defer membership.deinit(std.testing.allocator);
            const work = try membership.classify(retirement.scope_ids, &nested);
            // Direct rows belong to the rows-site plan; none may be retired a
            // second time through the scope-owned row retirement.
            try std.testing.expectEqual(@as(usize, 0), nested.items.len);
            try std.testing.expectEqual(row_count, work.roots_indexed);
            try std.testing.expectEqual(row_count, work.scopes_classified);
            try std.testing.expectEqual(row_count, work.direct_matches);
            // Linear: exactly one membership probe per retiring scope. A
            // restored nested scan over the roots reports the triangular
            // count below instead and fails here.
            try std.testing.expectEqual(row_count, work.membership_probes);

            var reference_nested: shared_buffer.List(ids.ScopeId) = .empty;
            defer reference_nested.deinit(std.testing.allocator);
            try reference_nested.ensureTotalCapacity(std.testing.allocator, retirement.scope_ids.len);
            const triangular = row_count * (row_count + 1) / 2;
            try std.testing.expectEqual(triangular, countDirectRootNestedScan(retirement.scope_ids, roots.items, &reference_nested));
            try std.testing.expectEqualSlices(ids.ScopeId, reference_nested.items, nested.items);
        }
    }.run;
    // clear1k: 500_500 baseline comparisons; clear10k: 50_005_000.
    try measure(1_000);
    try measure(10_000);
}

test "sparse scope retirement keeps nested rows and independent scopes while direct roots stay linear" {
    const FaultAllocator = @import("fault_allocator.zig").FaultAllocator;
    const Membership = Engine(VerifyCtx).PreparedStructuralDownstream.DirectRowRootMembership;
    const row_count = 1_000;
    var engine = Engine(VerifyCtx).init();
    defer engine.scopes.deinit(std.testing.allocator);
    const root = try engine.internRootScope(std.testing.allocator);
    var direct_rows: shared_buffer.List(ids.ScopeId) = .empty;
    defer direct_rows.deinit(std.testing.allocator);
    var expected_nested: shared_buffer.List(ids.ScopeId) = .empty;
    defer expected_nested.deinit(std.testing.allocator);
    // Each direct row owns a component that owns a nested row, and one
    // surviving sibling row is never part of the retirement.
    for (0..row_count) |index| {
        const row = try scope_runtime.appendFreshEachRow(std.testing.allocator, &engine.scopes, root.scope_id, ids.SiteOrdinal.fromRaw(1), index, row_handles.RowHandleId.fromRaw(@intCast(0x0000_0001_0000_0001 + index)));
        const component = try engine.internComponentScope(std.testing.allocator, row.scope_id, ids.SiteOrdinal.fromRaw(3));
        const nested_row = try scope_runtime.appendFreshEachRow(std.testing.allocator, &engine.scopes, component.scope_id, ids.SiteOrdinal.fromRaw(4), index, row_handles.RowHandleId.fromRaw(@intCast(0x0000_0002_0000_0001 + index)));
        try direct_rows.append(std.testing.allocator, row.scope_id);
        try expected_nested.append(std.testing.allocator, nested_row.scope_id);
        try expected_nested.append(std.testing.allocator, component.scope_id);
    }
    const survivor = try scope_runtime.appendFreshEachRow(std.testing.allocator, &engine.scopes, root.scope_id, ids.SiteOrdinal.fromRaw(1), row_count, row_handles.RowHandleId.fromRaw(0x0000_0003_0000_0001));
    // An independently retiring `when` branch is not a synchronized row root,
    // so it and its child are nested scopes for the scope-owned retirement.
    const branch = try engine.internWhenBranchScope(std.testing.allocator, root.scope_id, ids.SiteOrdinal.fromRaw(2), .true_branch);
    const branch_row = try scope_runtime.appendFreshEachRow(std.testing.allocator, &engine.scopes, branch.scope_id, ids.SiteOrdinal.fromRaw(5), 7, row_handles.RowHandleId.fromRaw(0x0000_0004_0000_0001));
    try expected_nested.append(std.testing.allocator, branch_row.scope_id);
    try expected_nested.append(std.testing.allocator, branch.scope_id);

    var retired_roots: shared_buffer.List(ids.ScopeId) = .empty;
    defer retired_roots.deinit(std.testing.allocator);
    try retired_roots.appendSlice(std.testing.allocator, direct_rows.items);
    try retired_roots.append(std.testing.allocator, branch.scope_id);
    var retirement = try scope_runtime.prepareSubtreesRetirement(HostEachRowScopeStep, std.testing.allocator, engine.scopes.items, retired_roots.items);
    defer retirement.deinit(std.testing.allocator);
    const retiring_count = 3 * row_count + 2;
    try std.testing.expectEqual(@as(usize, retiring_count), retirement.scope_ids.len);
    for (retirement.scope_ids) |scope_id| try std.testing.expect(scope_id != survivor.scope_id);

    var fault = FaultAllocator.init(std.testing.allocator);
    var nested: shared_buffer.List(ids.ScopeId) = .empty;
    defer nested.deinit(fault.allocator());
    try nested.ensureTotalCapacity(fault.allocator(), retirement.scope_ids.len);
    fault.configure(null);
    var membership = try Membership.init(fault.allocator(), direct_rows.items);
    const init_attempts = fault.attempts;
    try std.testing.expect(init_attempts != 0);
    // Classification is allocation free once the index exists.
    fault.configure(1);
    const work = try membership.classify(retirement.scope_ids, &nested);
    try std.testing.expectEqual(@as(usize, 0), fault.attempts);
    fault.configure(null);
    membership.deinit(fault.allocator());
    try std.testing.expectEqual(@as(usize, retiring_count), work.scopes_classified);
    try std.testing.expectEqual(@as(usize, retiring_count), work.membership_probes);
    try std.testing.expectEqual(@as(usize, row_count), work.direct_matches);
    try std.testing.expectEqualSlices(ids.ScopeId, expected_nested.items, nested.items);
    for (nested.items) |scope_id| for (direct_rows.items) |direct| try std.testing.expect(scope_id != direct);

    var reference_nested: shared_buffer.List(ids.ScopeId) = .empty;
    defer reference_nested.deinit(std.testing.allocator);
    try reference_nested.ensureTotalCapacity(std.testing.allocator, retirement.scope_ids.len);
    const reference_comparisons = countDirectRootNestedScan(retirement.scope_ids, direct_rows.items, &reference_nested);
    try std.testing.expectEqualSlices(ids.ScopeId, reference_nested.items, nested.items);
    // Nested descendants each scan every root without a hit.
    try std.testing.expect(reference_comparisons >= (2 * row_count + 2) * row_count);

    // Every index allocation refusal is recoverable and leaves no index behind.
    for (1..init_attempts + 1) |fail_at| {
        fault.configure(fail_at);
        try std.testing.expectError(error.OutOfMemory, Membership.init(fault.allocator(), direct_rows.items));
        fault.configure(null);
        var retry = try Membership.init(fault.allocator(), direct_rows.items);
        retry.deinit(fault.allocator());
    }

    // Contract errors: a duplicated direct root, and a direct root that is
    // not among the retiring scopes.
    try std.testing.expectError(error.InvalidDescriptor, Membership.init(std.testing.allocator, &.{ direct_rows.items[0], direct_rows.items[0] }));
    var foreign = try Membership.init(std.testing.allocator, &.{survivor.scope_id});
    defer foreign.deinit(std.testing.allocator);
    nested.clearRetainingCapacity();
    try std.testing.expectError(error.InvalidDescriptor, foreign.classify(retirement.scope_ids, &nested));
}

test "structural targets ignore already retired scope slots" {
    var engine = Engine(VerifyCtx).init();
    defer engine.scopes.deinit(std.testing.allocator);
    const root = try engine.internRootScope(std.testing.allocator);
    const retired = try engine.internWhenBranchScope(std.testing.allocator, root.scope_id, ids.SiteOrdinal.fromRaw(10), .false_branch);
    engine.scopes.items[retired.scope_id.index()].lifecycle = .{ .retired = ids.Generation.fromRaw(0) };

    var targets = try Engine(VerifyCtx).PreparedStructuralTargets.prepare(&engine, std.testing.allocator, &.{root.scope_id.raw()}, &.{}, null);
    defer targets.deinit(std.testing.allocator);
    try std.testing.expect(targets.descriptor_target_scopes[root.scope_id.index()]);
    try std.testing.expect(!targets.descriptor_target_scopes[retired.scope_id.index()]);
}

test "initial root downstream refuses a stale graph binding as InvalidSignalGraphRelease" {
    var roc_env = abi.RocEnv{ .allocator = std.testing.allocator, .roc_io = abi.RocIo.default() };
    var roc_host = abi.makeRocHost(&roc_env);
    const callable = abi.rocErasedCallableAllocate(&roc_host, verifyStateCallable, null, 0).?;
    defer abi.decrefErasedCallable(callable, &roc_host);
    const text_callable = abi.rocErasedCallableAllocate(&roc_host, verifyTextCallable, null, 0).?;
    defer abi.decrefErasedCallable(text_callable, &roc_host);
    const capability = HostValueCapability{ .clone = callable, .drop = callable, .eq = callable };
    var signal_expr = abi.NodeSignalExpr{ .payload = .{ .const_value = .{
        ._0 = callable,
        ._1 = callable,
        ._2 = capability,
    } }, .tag = .ConstValue };
    const signal_attr = abi.NodeAttr{ .payload = .{ .signal_text = .{
        .field = .{ .id = @intFromEnum(RenderTextField.value) },
        .name = abi.RocStr.empty(),
        .read = .{ .capability = capability, .read = text_callable },
        .signal = &signal_expr,
    } }, .tag = .SignalText };
    var child = verifyStaticRoot(&.{signal_attr}, &.{verifyStaticText()});
    var state = abi.Elem{ .payload = .{ .state = .{
        .binder = callable,
        .cap = capability,
        .child = &child,
        .initial = callable,
    } }, .tag = .State };
    const root = abi.Elem{ .payload = .{ .component = .{ .child = &state } }, .tag = .Component };

    var ctx = VerifyCtxHost{ .allocator = std.testing.allocator };
    var engine = Engine(VerifyCtx).init();
    engine.roc_host = &roc_host;
    defer {
        engine.active_stream.deinit(ctx.allocator, &ctx, &roc_host, &engine.pending_roc_metrics);
        engine.active_events.deinit(ctx.allocator);
        engine.active_signal_graph.deinit(ctx.allocator);
        engine.active_source_signal_routes.deinit(ctx.allocator);
        engine.active_text_signal_routes.deinit(ctx.allocator);
        engine.active_bool_signal_routes.deinit(ctx.allocator);
        engine.active_change_signal_routes.deinit(ctx.allocator);
        engine.active_structural_signal_routes.deinit(ctx.allocator);
        ctx.render_batch.deinit(ctx.allocator);
        engine.deinitRenderCache(&ctx);
        deinitVerifyStateEngine(&engine, &ctx, &roc_host);
    }

    const collection = try Engine(VerifyCtx).PreparedRootCollection.prepare(&engine, &ctx, &roc_host, root, .{}, &.{});
    defer collection.deinit();
    // The staged binding claims membership of a committed graph node the
    // (empty) active graph does not hold, so the release closure that must
    // retain it cannot be matched against the committed graph. Before this
    // variant existed the same rejection was reported as `OutOfMemory`.
    const record = collection.owner.stream.signal_text_attrs.items[0].signal.record;
    record.active_graph_id = 3;
    defer record.active_graph_id = null;
    try std.testing.expectError(error.InvalidSignalGraphRelease, Engine(VerifyCtx).PreparedRootDownstream.prepare(collection));
    try std.testing.expectEqual(@as(usize, 0), engine.active_signal_graph.items.len);
    try std.testing.expect(!engine.render_cache.hasRoot());
}

test "transactional initial when root sweeps failures and evaluates once" {
    const FaultAllocator = @import("fault_allocator.zig").FaultAllocator;
    var roc_env = abi.RocEnv{ .allocator = std.testing.allocator, .roc_io = abi.RocIo.default() };
    var roc_host = abi.makeRocHost(&roc_env);
    const value_callable = abi.rocErasedCallableAllocate(&roc_host, verifyStateCallable, null, 0).?;
    defer abi.decrefErasedCallable(value_callable, &roc_host);
    const bool_callable = abi.rocErasedCallableAllocate(&roc_host, verifyBoolCallable, null, 0).?;
    defer abi.decrefErasedCallable(bool_callable, &roc_host);
    const capability = HostValueCapability{ .clone = value_callable, .drop = value_callable, .eq = value_callable };
    var condition = abi.NodeSignalExpr{ .payload = .{ .const_value = .{
        ._0 = value_callable,
        ._1 = value_callable,
        ._2 = capability,
    } }, .tag = .ConstValue };
    var when_false = verifyStaticText();
    when_false.payload.text = abi.RocStr.fromSlice("no", undefined);
    var when_true = verifyStaticText();
    when_true.payload.text = abi.RocStr.fromSlice("yes", undefined);
    const when_ops = borrowedVerifyWhenOps(&roc_host, capability, when_true, when_false);
    defer {
        var metrics = zeroRuntimeMetrics();
        retained_values.releaseHostWhenOps(when_ops, &roc_host, &metrics);
    }
    const root = abi.Elem{ .payload = .{ .when = .{
        .condition = &condition,
        .ops = when_ops,
    } }, .tag = .When };

    var counter = FaultAllocator.init(std.testing.allocator);
    var counter_ctx = VerifyCtxHost{ .allocator = counter.allocator() };
    var counter_engine = Engine(VerifyCtx).init();
    var counter_stream: HostNodeDescriptorStream = .{};
    verifyStateInitCalls = 0;
    try counter_engine.collectStaticRootDescriptorsTransactional(&counter_ctx, &roc_host, &counter_stream, root, .{});
    const attempts = counter.attempts;
    try std.testing.expectEqual(@as(usize, 1), verifyStateInitCalls);
    counter_stream.deinit(counter_ctx.allocator, &counter_ctx, &roc_host, &counter_engine.pending_roc_metrics);
    deinitVerifyStateEngine(&counter_engine, &counter_ctx, &roc_host);

    for (1..attempts + 1) |failure_number| {
        var fault = FaultAllocator.init(std.testing.allocator);
        fault.configure(failure_number);
        var ctx = VerifyCtxHost{ .allocator = fault.allocator() };
        var engine = Engine(VerifyCtx).init();
        var stream: HostNodeDescriptorStream = .{};
        defer {
            stream.deinit(ctx.allocator, &ctx, &roc_host, &engine.pending_roc_metrics);
            deinitVerifyStateEngine(&engine, &ctx, &roc_host);
        }
        verifyStateInitCalls = 0;
        try std.testing.expectError(error.OutOfMemory, engine.collectStaticRootDescriptorsTransactional(&ctx, &roc_host, &stream, root, .{}));
        try std.testing.expectEqual(@as(usize, 0), engine.scopes.items.len);
        try std.testing.expectEqual(@as(usize, 0), engine.node_identities.items.len);
        try std.testing.expectEqual(@as(usize, 0), stream.whens.items.len);
        try std.testing.expectEqual(@as(usize, 0), stream.text_nodes.items.len);
        const calls_before_retry = verifyStateInitCalls;

        fault.configure(null);
        try engine.collectStaticRootDescriptorsTransactional(&ctx, &roc_host, &stream, root, .{});
        try std.testing.expectEqual(calls_before_retry + 1, verifyStateInitCalls);
        try std.testing.expectEqual(@as(usize, 2), engine.scopes.items.len);
        try std.testing.expectEqual(@as(usize, 1), engine.node_identities.items.len);
        try std.testing.expectEqual(@as(usize, 1), stream.whens.items.len);
        try std.testing.expectEqualStrings("yes", stream.text_nodes.items[0].value);
    }
}

test "staged root rows share scope ids with provisional structural children and sweep OOM" {
    const FaultAllocator = @import("fault_allocator.zig").FaultAllocator;
    var roc_env = abi.RocEnv{ .allocator = std.testing.allocator, .roc_io = abi.RocIo.default() };
    var roc_host = abi.makeRocHost(&roc_env);
    const callable = abi.rocErasedCallableAllocate(&roc_host, verifyStateCallable, null, 0).?;
    defer abi.decrefErasedCallable(callable, &roc_host);
    const capability = HostValueCapability{ .clone = callable, .drop = callable, .eq = callable };
    const root = verifyStaticRoot(&.{}, &.{verifyStaticText()});

    const Runner = struct {
        fn run(host: *abi.RocHost, elem: abi.Elem, cap: HostValueCapability, fail_at: ?usize) !usize {
            var fault = FaultAllocator.init(std.testing.allocator);
            fault.configure(fail_at);
            var ctx = VerifyCtxHost{ .allocator = fault.allocator() };
            var engine = Engine(VerifyCtx).init();
            engine.roc_host = host;
            defer deinitVerifyStateEngine(&engine, &ctx, host);

            const prepared = Engine(VerifyCtx).PreparedRootCollection.prepare(&engine, &ctx, host, elem, .{}, &.{}) catch |err| {
                try std.testing.expect(fail_at != null);
                try std.testing.expectEqual(error.OutOfMemory, err);
                return fault.attempts;
            };
            errdefer prepared.deinit();
            const collection = &prepared.owner.collection;
            // Row scopes are reserved through the capacity plan by the site
            // that evaluated them; this seam test stands in for that site.
            collection.reserveCounts(.{ .external_scopes = 2, .each_rows = 2 }) catch |err| {
                try std.testing.expect(fail_at != null);
                try std.testing.expectEqual(error.OutOfMemory, err);
                prepared.deinit();
                return fault.attempts;
            };
            _ = cap;
            const first_row = collection.reserveEachRowScopeGeneration(ids.ScopeId.fromRaw(0), ids.SiteOrdinal.fromRaw(7), 11, row_handles.RowHandleId.fromRaw(0x0000_0001_0000_0001)) catch |err| {
                try std.testing.expect(fail_at != null);
                try std.testing.expectEqual(error.OutOfMemory, err);
                prepared.deinit();
                try std.testing.expectEqual(@as(usize, 0), engine.scopes.items.len);
                return fault.attempts;
            };
            const second_row = collection.reserveEachRowScopeGeneration(ids.ScopeId.fromRaw(0), ids.SiteOrdinal.fromRaw(7), 22, row_handles.RowHandleId.fromRaw(0x0000_0001_0000_0002)) catch |err| {
                try std.testing.expect(fail_at != null);
                try std.testing.expectEqual(error.OutOfMemory, err);
                prepared.deinit();
                try std.testing.expectEqual(@as(usize, 0), engine.scopes.items.len);
                return fault.attempts;
            };
            collection.reserveCounts(.{ .roots = .{ .when_sites = 1 } }) catch |err| {
                try std.testing.expect(fail_at != null);
                try std.testing.expectEqual(error.OutOfMemory, err);
                prepared.deinit();
                return fault.attempts;
            };
            const nested = collection.reserveWhenBranchScope(first_row, ids.SiteOrdinal.fromRaw(3), .true_branch) catch |err| {
                try std.testing.expect(fail_at != null);
                try std.testing.expectEqual(error.OutOfMemory, err);
                prepared.deinit();
                return fault.attempts;
            };
            try std.testing.expectEqual(ids.ScopeId.fromRaw(1), first_row);
            try std.testing.expectEqual(ids.ScopeId.fromRaw(2), second_row);
            try std.testing.expectEqual(@as(u64, 3), nested.scope_id.raw());

            const attempts = fault.attempts;
            if (fail_at != null) {
                prepared.deinit();
                try std.testing.expectEqual(@as(usize, 0), engine.scopes.items.len);
                return attempts;
            }
            fault.configure(1);
            var stream = prepared.commit();
            try std.testing.expectEqual(@as(usize, 0), fault.attempts);
            try std.testing.expectEqual(@as(usize, 4), engine.scopes.items.len);
            try std.testing.expectEqual(@as(?ids.ScopeId, ids.ScopeId.fromRaw(0)), engine.scopes.items[1].parent_scope_id);
            try std.testing.expectEqual(@as(?ids.ScopeId, ids.ScopeId.fromRaw(0)), engine.scopes.items[2].parent_scope_id);
            try std.testing.expectEqual(@as(?ids.ScopeId, ids.ScopeId.fromRaw(1)), engine.scopes.items[3].parent_scope_id);
            try std.testing.expectEqual(row_handles.RowHandleId.fromRaw(0x0000_0001_0000_0001), scope_runtime.eachRowConst(engine.scopes.items, ids.ScopeId.fromRaw(1)).row_handle);
            try std.testing.expectEqual(row_handles.RowHandleId.fromRaw(0x0000_0001_0000_0002), scope_runtime.eachRowConst(engine.scopes.items, ids.ScopeId.fromRaw(2)).row_handle);
            stream.deinit(ctx.allocator, &ctx, host, &engine.pending_roc_metrics);
            return attempts;
        }
    };

    const attempts = try Runner.run(&roc_host, root, capability, null);
    try std.testing.expect(attempts != 0);
    for (1..attempts + 1) |fail_at| _ = try Runner.run(&roc_host, root, capability, fail_at);
}

test "branch replacement preparation leaves the active branch unpublished" {
    var roc_env = abi.RocEnv{ .allocator = std.testing.allocator, .roc_io = abi.RocIo.default() };
    var roc_host = abi.makeRocHost(&roc_env);
    const value_callable = abi.rocErasedCallableAllocate(&roc_host, verifyStateCallable, null, 0).?;
    defer abi.decrefErasedCallable(value_callable, &roc_host);
    const bool_callable = abi.rocErasedCallableAllocate(&roc_host, verifyBoolCallable, null, 0).?;
    defer abi.decrefErasedCallable(bool_callable, &roc_host);
    const state_callable = abi.rocErasedCallableAllocate(&roc_host, verifyStateCallable, null, 0).?;
    defer abi.decrefErasedCallable(state_callable, &roc_host);
